window.__BOOK__['p04'].push([{"id":"b70-1","bab":"الجزء 7","sec":"أخبار الوليد بن يزيد ونسبه","page":"ج7 ص5","text":"هو الوليد بن يزيد بن عبد الملك بن مروان بن الحكم بن أبي العاصي ابن أمية بن عبد شمس بن عبد مناف ويكنى أبا العباس وأمه أم الحجاج بنت محمد بن يوسف بن الحكم بن أبي عقيل الثقفي وهي بنت أخي الحجاج وفيه يقول أبو نخيلة\n(بين أبي العاصي وبين الحجاج ... يا لكما نورا سراج وهاج)\n(عليه بعد عمه عقد التاج ... )\nأم يزيد بن عبد الملك عاتكة بنت يزيد بن معاوية بن أبي سفيان بن حرب بن أمية وأمها أم كلثوم بنت عبد الله بن عامر وأم عبد الله بن عامر أم حكيم البيضاء بنت عبد المطلب بن هاشم ولذلك قال الوليد بن يزيد\n(نبي الهدى خالي ومن يك خاله ... نبي الهدى يقهر به من يفاخر)\nوكان الوليد بن يزيد من فتيان بني أمية وظرفائهم وشعرائهم وأجوادهم ونسبائهم وكان فاسقا خليعا متهما في دينه مرميا بالزندقة وشاع ذلك من أمره وظهر حتى أنكره الناس فقتل وله أشعار كثيرة تدل على خبثه وكفره ومن الناس من ينفي ذلك عنه وينكره ويقول إنه نحله وألصق إليه والأغلب الأشهر غير ذلك","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":0,"spl":"أخبار الوليد بن يزيد ونسبه","loc":1250,"partial":1},
{"id":"b70-2","bab":"الجزء 7","sec":"ضعف الوليد أمام مكر هشام","page":"ج7 ص6","text":"أخبرني الحسن بن علي وأحمد بن الحارث الخراز عن المدائني عن إسحاق بن أيوب القرشي وجويرية بن أسماء وعامر بن الأسود والمنهال بن عبد الملك وأبي عمرو بن المبارك وسحيم بن حفص وغيرهم أن يزيد بن عبد الملك لما وجه الجيوش إلى يزيد بن المهلب وعقد لمسلمة بن عبد الملك على الجيش وبعث العباس بن الوليد بن عبد الملك وعقد له على أهل دمشق قال له العباس يا أمير المؤمنين إن\nأهل العراق أهل غدر وإرجاف وقد وجهتنا محاربين والأحداث تحدث ولا آمن أن يرجف أهل العراق ويقولوا مات أمير المؤمنين ولم يعهد فيفت ذلك في أعضاد أهل الشام فلو عهدت عهدا لعبد العزيز بن الوليد قال غدا وبلغ ذلك مسلمة بن عبد الملك فأتى يزيد فقال يا أمير المؤمنين أيما أحب إليك ولد عبد الملك أو ولد الوليد فقال بل ولد عبد الملك قال أفأخوك أحق بالخلافة أم ابن أخيك قال إذا لم تكن في ولدي فأخي أحق بها من ابن أخي قال فابنك لم يبلغ فبايع لهشام ثم لابنك بعد هشام قال والوليد يومئذ ابن إحدى عشرة سنة قال غدا أبايع له فلما أصبح فعل ذلك وبايع لهشام وأخذ العهد عليه ألا يخلع الوليد بعده ولا يغير عهده ولا يحتال عليه فلما أدرك الوليد ندم أبوه فكان ينظر إليه ويقول الله بيني وبين من جعل هشاما بيني وبينك وتوفي يزيد سنة خمس ومائة وابنه الوليد ابن خمس عشرة سنة قالوا فلم يزل الوليد مكرما عند هشام رفيع المنزلة مدة ثم طمع في خلعه وعقد العهد بعده لابنه مسلمة بن هشام فجعل يذكر الوليد بن يزيد وتهتكه وإدمانه على الشراب ويذكر ذلك في مجلسه ويقوم ويقعد به وولاه الحج ليظهر ذلك منه بالحرمين فيسقط فحج وظهر منه فعل كثير مذموم وتشاغل بالمغنين وبالشراب وأمر مولى له فحج بالناس فلما حج طالبه هشام بأن يخلع نفسه فأبى ذلك فحرمه العطاء وحرم سائر مواليه وأسبابه وجفاه جفاء شديدا فخرج متبديا وخرج معه عبد الصمد بن عبد الأعلى مؤدبه وكان يرمى بالزندقة ودعا هشام الناس إلى خلعه والبيعة لمسلمة بن هشام وأمه أم حكيم بنت يحيى بن الحكم بن أبي العاصي وكان مسلمة يكنى أبا شاكر كني بذلك لمولى كان لمروان يكنى أبا\nشاكر كان ذا رأي وفضل وكانوا يعظمونه ويتبركون به فأجابه إلى خلع الوليد والبيعة لمسلمة بن هشام محمد وإبراهيم ابنا هشام بن إسماعيل المخزومي والوليد وعبد العزيز وخالد بن القعقاع بن خويلد العبسي وغيرهم من خاصة هشام وكتب إلى الوليد ما تدع شيئا من المنكر إلا أتيته وارتكبته غير متحاش ولا مستتر فليت شعري ما دينك أعلى الإسلام أنت أم لا فكتب إليه الوليد بن يزيد ويقال بل قال ذلك عبد الصمد بن عبد الأعلى ونحله إياه\n(يا أيها السائل عن ديننا ... نحن على دين أبي شاكر)\n(نشربها صرفا وممزوجة ... بالسخن أحيانا وبالفاتر)\nناه عمر الوادي رملا بالبنصر فغضب هشام على ابنه مسلمة وقال يعيرني بك الوليد وأنا أرشحك للخلافة فالزم الأدب وأحضر الصلوات وولاه الموسم سنة سبع عشرة ومائة فأظهر النسك وقسم بمكة والمدينة أموالا فقال رجل من موالي أهل المدينة\n(يا أيها السائل عن ديننا ... نحن على دين أبي شاكر)\n(الواهب البزل بأرسانها ... ليس بزنديق ولا كافر)\nقال المدائني وبلغ خالدا القسري ما عزم عليه هشام فقال أنا بريء من خليفة يكنى أبا شاكر فبلغت هشاما عنه هذه فكان ذلك سبب إيقاعه به","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":1,"spl":"ضعف الوليد أمام مكر هشام","song":1,"loc":1251},
{"id":"b70-3","bab":"الجزء 7","sec":"الوليد العابث","page":"ج7 ص9","text":"أخبرني محمد بن الحسن الكندي المؤدب قال حدثني أبي عن العباس ابن هشام قال دخل الوليد بن يزيد يوما مجلس هشام بن عبد الملك وقد كان في ذكره قبل أن يدخل فحمقه من حضر من بني أمية فلما جلس قال له العباس بن الوليد وعمر بن الوليد كيف حبك يا وليد للروميات فإن أباك كان بهن مشغوفا قال إني لأحبهن وكيف لا أحبهن ولن تزال الواحدة منهن قد جاءت بالهجين مثلك وكانت أم العباس رومية قال اسكت فليس الفحل يأتي عسبه بمثلي فقال له الوليد اسكت يابن البظراء قال\nأتفخر علي بما قطع من بظر أمك وأقبل هشام على الوليد فقال له ما شرابك قال شرابك يا أمير المؤمنين وقام مغضبا فخرج فقال هشام أهذا الذي تزعمون أنه أحمق ما هو أحمق ولكني لا أظنه على الملة أخبرني محمد بن العباس اليزيدي قال أخبرنا أحمد بن الحارث الخراز عن المدائني قال دخل الوليد بن يزيد مجلس هشام بن عبد الملك وفيه سعيد بن هشام بن عبد الملك وأبو الزبير مولى مروان وليس هشام حاضرا فجلس الوليد مجلس هشام ثم أقبل على سعيد بن هشام فقال له من أنت وهو به عارف قال سعيد ابن أمير المؤمنين قال مرحبا بك ثم نظر إلى أبي الزبير فقال من أنت قال أبو الزبيرمولاك أيها الأمير قال أنسطاس أنت مرحبا بك ثم قال لإبراهيم بن هشام من أنت قال إبراهيم بن هشام قال من إبراهيم بن هشام وهو يعرفه قال إبراهيم بن هشام بن إسماعيل قال من إسماعيل وهو يعرفه قال إسماعيل بن هشام بن الوليد بن المغيرة قال من الوليد بن المغيرة قال الذي لم يكن جدك يرى أنه في شيء حتى زوجه أبي وهو بعض ولد ابنته قال يابن اللخناء أتقول هذا\nوائتخذا وأقبل هشام فقيل لهما قد جاء أمير المؤمنين فجلسا وكفا ودخل هشام فما كاد الوليد يتنحى له عن صدر مجلسه إلا أنه زحل له قليلا فجلس هشام وقال له كيف أنت يا وليد قال صالح قال ما فعلت برابطك قال معملة أو مستعملة قال فما فعل ندماؤك قال صالحون ولعنهم الله إن كانوا شرا ممن حضرك وقام فقال له هشام يابن اللخناء جؤوا عنقه فلم يفعلوا ودفعوه رويدا فقال الوليد\n(أنا ابن أبي العاصي وعثمان والدي ... ومروان جدي ذو الفعال وعامر)\n(أنا ابن عظيم القريتين وعزها ... ثقيف وفهر والعصاة الأكابر)\n(نبي الهدى خالي ومن يك خاله ... نبي الهدى يقهر به من يفاخر)","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":2,"spl":"الوليد العابث","loc":1252},
{"id":"b70-4","bab":"الجزء 7","sec":"الوليد يرثي مسلمة بن عبد الملك","page":"ج7 ص11","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني قال كان هشام بن عبد الملك يكثر تنقص الوليد بن يزيد فكان مسلمة يعاتب هشاما ويكفه فمات مسلمة فغم الوليد ورثاه فقال\n\n(أتانا بريدان من واسط ... يخبان بالكتب المعجمه)\n(أقول وما البعد إلا الردى ... أمسلم لا تبعدن مسلمه)\n(فقد كنت نورا لنا في البلاد ... تضيء فقد أصبحت مظلمه)\n(كتمنا نعيك نخشى اليقين ... فجلى اليقين عن الجمجمه)\n(وكم من يتيم تلافيته ... بأرض العدو وكم أيمه)\n(وكنت إذا الحرب درت دما ... نصبت لها راية معلمه)\nنى في هذه الأبيات التي أولها\n(أقول وما البعد إلا الردى ... )\nونس خفيف ثقيل بالوسطى عن عمرو وذكر الهشامي أن فيه ثقيلا أول ينسب إلى أبي كامل وعمر الوادي وذكر حبش أن ليونس فيه رملا بالبنصر\nأخبرني الطوسي والحرمي بن أبي العلاء قالا حدثنا الزبير بن بكار قال حدثني موسى بن زهير بن مضرس بن منظور بن زبان بن سيار عن أبيه قال رأيت هشام بن عبد الملك وأنا في عسكره يوم توفي مسلمة بن عبد الملك وهشام في شرطته إذ طلع الوليد بن يزيد على الناس وهو نشوان يجر مطرف خز عليه فوقف على هشام فقال يا أمير المؤمنين إن عقبى من بقي لحوق من مضى وقد أقفر بعد مسلمة الصيد لمن يرى واختل الثغر فوهى وعلى أثر من سلف يمضي من خلف فتزودوا فإن خير الزاد التقوى فأعرض عنه هشام ولم يرد جوابا ووجم الناس فما همس أحد بشيء قال فمضى الوليد وهو يقول\n(أهينمة حديث القوم أم هم ... سكوت بعد ما متع النهار)\n(عريز كان بينهم نبيا ... فقول القوم وحي لا يحار)\n(كأنا بعد مسلمة المرجى ... شروب طوحت بهم عقار)\n(أو آلاف هجان في قيود ... تلفت كلما حنت ظؤار)\n(فليتك لم تمت وفداك قوم ... تريح غبيهم عنا الديار)\n(سقيم الصدر أو شكس نكيد ... وآخر لا يزور ولا يزار)\nعني بالسقيم الصدر يزيد بن الوليد ويعني بالشكس هشاما والذي لا يزور ولا يزار مروان بن محمد قال الزبير وحدثني محمد بن الضحاك عن أبيه قال أراد هشام أن يخلع الوليد ويجعل العهد لولده فقال الوليد\n(كفرت يدا من منعم لو شكرتها ... جزاك بها الرحمن ذو الفضل والمن)\n(رأيتك تبني جاهدا في قطيعتي ... ولو كنت ذا حزم لهدمت ما تبني)\n(أراك على الباقين تجني ضغينة ... فياويحهم إن مت من شر ما تجني)\n(كأني بهم يوما وأكثر قولهم ... أيا ليت أنا حين يا ليت لا تغني)\nخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز عن المدائني قال عتب هشام على الوليد وخاصته فخرج الوليد ومعه قوم من خاصته ومواليه فنزل بالأبرق بين أرض بلقين وفزارة على ماء يقال له الأغدف وخلف بالرصافة كاتبه عياض بن مسلم مولى عبد الملك ليكاتبه بما يحدث وأخرج معه عبد الصمد بن عبد الأعلى فشربوا يوما فقال له الوليد يا أبا وهب قل أبياتا تغني فيها فقال أبياتا وأمر عمر الوادي فغنى فيها وهي\n(ألم تر للنجم إذ سبعا ... يبادر في برجه المرجعا)\n(تحير عن قصد مجراته ... إلى الغور والتمس المطلعا)\n(فقلت وأعجبني شأنه ... وقد لاح إذ لاح لي مطمعا)\n(لعل الوليد دنا ملكه ... فأمسى إليه قد استجمعا)\n(وكنا نؤمل في ملكه ... كتأميل ذي الجدب أن يمرعا)\n(عقدنا محكمات الأمور ... طوعا وكان لها موضعا)\nروي هذا الشعر وبلغ هشاما فقطع عن الوليد ما كان يجري عليه وعلى أصحابه وحرمهم وكتب إلى الوليد قد بلغني أنك اتخذت عبد الصمد خدنا ومحدثا ونديما وقد حقق ذلك ما بلغني عنك ولن أبرئك من سوء فأخرج عبد الصمد مذموما قال فأخرجه الوليد وقال\n(لقد قذفوا أبا وهب بأمر ... كبير بل يزيد على الكبير)\n(وأشهد أنهم كذبوا عليه ... شهادة عالم بهم خبير)\nكتب الوليد إلى هشام بأنه قد أخرج عبد الصمد واعتذر إليه من منادمته وسأله أن يأذن لابن سهيل في الخروج إليه وكان من خاصة الوليد فضرب هشام ابن سهيل ونفاه وسيره وكان ابن سهيل من أهل النباهة وقد ولي الولايات ولي دمشق مرارا وولي غيرها وأخذ عياض بن مسلم كاتب الوليد فضربه ضربا مبرحا وألبسه المسوح وقيده وحبسه فغم ذلك الوليد فقال من يثق بالناس ومن يصنع المعروف هذا الأحول المشؤوم قدمه أبي على ولده وأهل بيته وولاه وهو يصنع بي ما ترون ولا يعلم أن لي في أحد","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":3,"spl":"الوليد يرثي مسلمة بن عبد الملك","song":2,"loc":1253,"partial":1},
{"id":"b70-5","bab":"الجزء 7","sec":"الوليد يرثي مسلمة بن عبد الملك","page":"ج7 ص11","text":"هوى إلا أضر به كتب إلي بأن أخرج عبد الصمد فأخرجته وكتبت إليه في أن يأذن لابن سهيل في الخروج إلي فضربه وطرده وقد علم رأيي فيه وعرف مكان عياض مني وانقطاعه إلي فضربه وحبسه يضارني بذلك اللهم أجرني منه ثم قال الوليد\n(أنا النذير لمسدي نعمة أبدا ... إلى المقاريف لما يخبر الدخلا)\n(إن أنت أكرمتهم ألفيتهم بطروا ... وإن أهنتهم ألفيتهم ذللا)\n(أتشمخون ومنا رأس نعمتكم ... ستعلمون إذا أبصرتم الدولا)\n(أنظر فإن أنت لم تقدر على مثل ... لهم سوى الكلب فاضربه لهم مثلا)\n(بينا يسمنه للصيد صاحبه ... حتى إذا ما استوى من بعد ما هزلا)\n(عدا عليه فلم تضرره عدوته ... ولو أطاق له أكلا لقد أكلا)\nناه مالك خفيف ثقيل من رواية الهشامي","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":4,"spl":"الوليد يرثي مسلمة بن عبد الملك — الشاعر الحاقد","song":1,"loc":1254},
{"id":"b70-6","bab":"الجزء 7","sec":"الوليد يفتخر على هشام","page":"ج7 ص16","text":"قال وقال الوليد أيضا يفتخر على هشام\n(أنا الوليد أبو العباس قد علمت ... عليا معد مدى كري وإقدامي)\n(إني لفي الذروة العليا إذا انتسبوا ... مقابل بين أخوالي وأعمامي)\n(بنى لي المجد بان لم يكن وكلا ... على منار مضيئات وأعلام)\n(حللت من جوهر الأعياص قد علموا ... في باذخ مشمخر العز قمقام)\n(صعب المرام يسامي النجم مطلعه ... يسمو إلى فرع طود شامخ سامي)\nناه عمر الوادي خفيف ثقيل بالخنصر في مجرى الوسطى عن إسحاق وأخبرني أحمد بن عبيد الله بن عمار قال حدثنا أحمد بن زهير بن حرب قال حدثني مصعب الزبيري قال بعث الوليد بن يزيد إلى هشام بن عبد الملك راويته فأنشده قوله\n(أنا الوليد أبو العباس قد علمت ... عليا معد مدى كري وإقدامي)\nقال هشام والله ما علمت له معد كرا ولا إقداما إلا أنه شرب مرة مع عمه بكار بن عبد الملك فعربد عليه وعلى جواريه فإن كان يعني ذلك بكره وإقدامه فعسى","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":4,"spl":"الوليد يرثي مسلمة بن عبد الملك — الشاعر الحاقد","song":1,"loc":1255},
{"id":"b70-7","bab":"الجزء 7","sec":"الشاعر الحاقد","page":"ج7 ص17","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني عبد الله بن عمرو بن أبي سعد قال حدثت أن أبا الزناد قال\nدخلت على هشام بن عبد الملك وعنده الزهري وهما يعيبان الوليد فأعرضت ولم أدخل في شيء من ذكره فلم ألبث أن استؤذن للوليد فأذن له فدخل وهو مغضب فجلس قليلا ثم نهض فلما مات هشام وولي الوليد كتب إلى المدينة فحملت فدخلت عليه فقال أتذكر قول الأحول والزهري قلت نعم وما عرضت في شيء من أمرك قال صدقت أتدري من أبلغني ذلك قلت لا قال الخادم الواقف على رأسه وايم الله لو بقي الفاسق الزهري لقتله ثم قال ذهب هشام بعمري فقلت بل يبقيك الله يا أمير المؤمنين وقام وصلى العصر ثم جلس يتحدث إلى المغرب ثم صلى المغرب ودعا بالعشاء فتعشيت معه ثم جلس يتحدث حتى صلى العتمة ثم تحدثنا قليل ثم قال اسقينني فأتينه بإناء مغطى وجاء جوار فقمن بيني وبينه فشرب وانصرفن ومكث قليلا ثم قال اسقينني ففعلن مثل ذلك وما زال والله ذلك دأبه حتى طلع الفجر فأحصيت له سبعين قدحا وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب عن أبي الزناد قال أجمع الزهري على أن يدخل إلى بلاد الروم إن ولي الوليد بن يزيد فمات الزهري قبل ذلك قال المدائني وبلغ الوليد أن العباس بن الوليد وغيره من بني مروان يعيبونه بالشراب فلعنهم وقال إنهم ليعيبون علي ما لو كانت لهم فيه لذة ما تركوه وقال هذا الشعر وأمر عمر الوادي أن يغني فيه وهو من جيد شعره ومختاره وفيه غناء قديم ذكره يونس لعمر الوادي غير مجنس\n(ولقد قضيت وإن تجلل لمتي ... شيب على رغم العدا لذاتي)\n(من كاعبات كالدمى ومناصف ... ومراكب للصيد والنشوات)\n(في فتية تأبى الهوان وجوههم ... شم الأنوف جحاجح سادات)\n(إن يطلبوا بتراتهم يعطوا بها ... أو يطلبوا لا يدركوا بترات)","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":4,"spl":"الوليد يرثي مسلمة بن عبد الملك — الشاعر الحاقد","song":1,"loc":1256},
{"id":"b70-8","bab":"الجزء 7","sec":"الوليد يكتب وهشام يرد","page":"ج7 ص19","text":"حدثني المنهال بن عبد الملك قال كتب الوليد إلى هشام قد بلغني ما أحدث أمير المؤمنين من قطع ما قطع عني ومحو من محا من أصحابي وأنه حرمني وأهلي ولم أكن أخاف أن يبتلي الله أمير المؤمنين بذلك في ولا ينالني مثله منه ولم يبلغ استصحابي لابن سهيل ومسألتي في أمره أن يجري علي ما جرى وإن كان ابن سهيل على ما ذكره أمير المؤمنين فبحسب العير أن يقرب من الذئب وعلى ذلك فقد عقد الله لي من العهد وكتب لي من العمر وسبب لي من الرزق ما لا يقدر أحد دونه تبارك وتعالى على قطعه عني دون مدته ولا صرفه عن مواقعه المحتومة له فقدر الله يجري على ما قدره فيما أحب الناس وكرهوا لا تعجيل لآجله ولا تأخير لعاجله والناس بعد ذلك يحتسبون الأوزار ويقترفون الآثام على أنفسهم من الله بما يستوجبون العقوبة عليه وأمير المؤمنين أحق بالنظر في ذلك والحفظ له والله يوفق أمير المؤمنين لطاعته ويحسن القضاء له في الأمور بقدرته وكتب اليه الوليد في آخر كتابه\n(أليس عظيما أن أرى كل وارد ... حياضك يوما صادرا بالنوافل)\n(فأرجع محمود الرجاء مصردا ... بتحلئة عن ورد تلك المناهل)\n(فأصبحت مما كنت آمل منكم ... وليس بلاق ما رجا كل آمل)\n(كمقتبض يوما على عرض هبوة ... يشد عليها كفه بالأنامل)\nكتب إليه هشام قد فهم أمير المؤمنين ما كتبت به من قطع ما وغير ذلك وأمير المؤمنين يستغفر الله من إجرائه ما كان يجري عليك ولا يتخوف على نفسه اقتراف المآثم في الذي أحدث من قطع ما قطع ومحو من محا من صحابتك لأمرين أما أحدهما فإن أمير المؤمنين يعلم مواضعك التي كنت تصرف إليها ما يجريه عليك وأما الآخر فإثبات صحابتك وأرزاقهم دارة عليهم لا ينالهم ما نال المسلمين عند قطع البعوث عليهم وهم معك تجول بهم في سفهك وأمير المؤمنين يرجو أن يكفر الله عنه ما سلف من إعطائه إياك باستئنافه قطعه عنك وأما ابن سهيل فلعمري لئن كان نزل منك بحيث يسوءك ما جرى عليه لما جعله الله لذلك أهلا وهل زاد ابن سهيل لله أبوك على أن كان زفانا مغنيا قد بلغ في السفه غايته وليس مع ذلك ابن سهيل بشر ممن كنت تستصحبه في الأمور التي ينزه أمير المؤمنين نفسه\nعنها مما كنت لعمري أهلا للتوبيخ فيه وأما ما ذكرت مما سببه الله لك فإن الله قد ابتدأ أمير المؤمنين بذلك واصطفاه له والله بالغ أمره ولقد أصبح أمير المؤمنين وهو على يقين من رأيه إلا أنه لا يملك لنفسه مما أعطاه الله من كرامته ضرا ولا نفعا وإن الله ولي ذلك منه وإنه لا بد له من مفارقته وإن الله أرأف بعباده وأرحم من أن يولي أمرهم غير من يرتضيه لهم منهم وإن أمير المؤمنين مع حسن ظنه بربه لعلي أحسن الرجاء لأن يوليه بسبب ذلك لمن هو أهله في الرضا به لهم فإن بلاء الله عند أمير المؤمنين أعظم من أن يبلغه ذكره أو يوازيه شكره إلا بعون منه ولئن كان قد قدر الله لأمير المؤمنين وفاة تعجيل فإن في الذي هو مفض وصائر إليه من كرامة الله لخلفا من الدنيا ولعمري إن كتابك لأمير المؤمنين بما كتبت به لغير مستنكر من سفهك وحمقك فأبق على نفسك وقصر من غلوائها وأربع على ظلعك فإن لله بسطوات وغيرا يصيب بها من يشاء من عباده وأمير المؤمنين يسأل الله العصمة والتوفيق لأحب الأمور إليه وأرضاها له وكتب في أسفل الكتاب\n(إذا أنت سامحت الهوى قادك الهوى ... إلى بعض ما فيه عليك مقال)\nوالسلام","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":5,"spl":"الوليد يكتب وهشام يرد","loc":1257},
{"id":"b70-9","bab":"الجزء 7","sec":"بويع له بالخلافة وهو سكران","page":"ج7 ص21","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز وأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة عن المدائني عن جويرية بن أسماء عن المنهال بن عبد الملك عن إسحاق بن أيوب كلهم عن أبي الزبير المنذر بن عمرو قال وكان كاتبا للوليد بن يزيد قال أرسل إلي الوليد صبيحة اليوم الذي أتته فيه الخلافة فأتيته فقال لي يا أبا الزبير ما أتت علي ليلة أطول من هذه الليلة عرضتني أمور وحدثت\nنفسي فيها بأمور وهذا الرجل قد أولع بي فاركب بنا نتنفس فركب وسرت معه فسار ميلين ووقف على تل فجعل يشكو هشاما إذ نظر إلى رهج قد أقبل قال عمر بن شبة في حديثه وسمع قعقعة البريد فتعوذ بالله من شر هشام وقال إن هذا البريد قد أقبل بموت وحي أو بملك عاجل فقلت لا يسوءك الله أيها الأمير بل يسرك ويبقيك إذ بدا رجلان على البريد يقبلان أحدهما مولى لآل أبي سفيان بن حرب فلما قربا رأيا الوليد فنزلا يعدوان حتى دنوا فسلما عليه بالخلافة فوجم وجعلا يكروان عليه التسليم بالخلافة فقال ويحكم ما الخبر أمات هشام قالا نعم قال فمرحبا بكما ما معكما قالا كتاب مولاك سالم بن عبد الرحمن فقرأ الكتاب وانصرفنا وسأل عن عياض بن مسلم كاتبه الذي كان هشام ضربه وحبسه فقالا يا أمير المؤمنين لم يزل محبوسا حتى نزل بهشام أمر الله فلما صار إلى حال لا ترجى الحياة لمثله معها أرسل عياض إلى الخزان احتفظوا بما في أيديكم فلا يصلن أحد إلى شيء وأفاق هشام إفاقة فطلب شيئا فمنعه فقال أرانا كنا خزانا للوليد وقضى من ساعته فخرج عياض من السجن ساعة قضى هشام فختم الأبواب والخزائن وأمر بهشام فأنزل عن فراشه ومنعهم أن يكفنوه من الخزائن فكفنه غالب مولى هشام ولم يجدوا قمقما حتى استعاروه وأمر الوليد بأخذ ابني هشام بن إسماعيل المخزومي فأخذا بعد أن عاذ إبراهيم بن هشام بقبر يزيد بن عبد الملك فقال الوليد ما أراه إلا قد نجا فقال له يحيى بن عروة بن الزبير وأخوه\nعبد الله إن الله لم يجعل قبر أبيك معاذا للظالمين فخذه برد ما في يده من مال الله فقال صدقت وأخذهما فبعث بهما إلى يوسف بن عمر وكتب إليه أن يبسط عليهما العذاب حتى يتلفا ففعل ذلك بهما وماتا جميعا في العذاب بعد أن أقيم إبراهيم بن هشام للناس حتى اقتضوا منه المظالم وقال عمر بن شبة في خبره إنه لما نعي له هشام قال والله لأتلقين هذه النعمة بسكرة قبل الظهر ثم أنشأ يقول\n(طاب يومي ولذ شرب السلافه ... إذ أتاني نعي من بالرصافه)\n(وأتانا البريد ينعى هشاما ... وأتانا بخاتم للخلافة)\n(فاصطبحنا من خمر عانة صرفا ... ولهونا بقينة عزافه)\nم حلف ألا يبرح موضعه حتى يغنى في هذا الشعر ويشرب عليه فغني له فيه وشرب وسكر ثم دخل فبويع له بالخلافة قال وسمع صياحا فسأل عنه فقيل له هذا من دار هشام يبكيه بناته فقال\n(إني سمعت بليل ... ورا المصلى برنه)\n(إذا بنات هشام ... يندبن والدهنه)\n(يندبن قرما جليلا ... قد كان يعضدهنه)\n(أنا المخنث حقا ... إن لم أنيكنهنه)\nوقال المدائني في خبر أحمد بن الحارث وشرب الوليد يوما فلما طابت نفسه تذكر هشاما فقال لعمر الوادي غنني\n(إني سمعت بليل ... ورا المصلى برنه)\nغناه فيه فشرب عليه ثلاثة أرطال ثم قال والله لئن سمعه منك أحد أبدا لاقتلنك قال فما سمع منه بعدها ولا عرف","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":6,"spl":"بويع له بالخلافة وهو سكران","loc":1258},
{"id":"b70-10","bab":"الجزء 7","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج7 ص24","text":"\n(طاب يومي ولذ شرب السلافه ... إذ أتانا نعي من في الرصافه)\nناه عمر الوادي خفيف رمل بالبنصر أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني أبو غسان قال قال حكم الوادي كنا عند الوليد بن يزيد وهو يشرب إذ جاءنا خصي فشق جيبه وعزاه عن عمه هشام وهنأه بالخلافة وفي يده قضيب وخاتم وطومار فأمسكنا ساعة ونظرنا إليه بعين الخلافة فقال غنوني غنياني قد طاب شرب السلافه البيتين فلم نزل نغنيه بهما الليل كله أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا\nإسحاق بن إبراهيم قال حدثني مروان بن أبي حفصة قال دخلت على الرشيد أمير المؤمنين فسألني عن الوليد بن يزيد فذهبت أتزحزح فقال إن أمير المؤمنين لا ينكر ما تقول فقل قلت كان من أصبح الناس وأظرف الناس وأشعر الناس فقال أتروي من شعره شيئا قلت نعم دخلت عليه مع عمومتي وفي يده قضيب ولي جمة فينانة فجعل يدخل القضيب في جمتي وجعل يقول يا غلام ولدتك سكر وهي أم ولد كانت لمروان بن الحكم فزوجها أبا حفصة قال فسمعته يومئذ ينشد\n(ليت هشاما عاش حتى يرى ... مكياله الأوفر قد أترعا)\n(كلنا له الصاع التي كالها ... فما ظلمناه بها أصوعا)\n(لم نأت ما نأتيه عن بدعة ... أحله القرآن لي أجمعا)\nال فأمر الرشيد بكتابتها فكتبت","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":7,"spl":"نسبة ما في هذا الخبر من الغناء — الشاعر المجيد","song":1,"loc":1259},
{"id":"b70-11","bab":"الجزء 7","sec":"الشاعر المجيد","page":"ج7 ص25","text":"وللوليد أشعار جياد فوق هذا الشعر الذي اختاره مروان فمنها وهو ما\nبرز فيه وجوده وتبعه الناس جميعا فيه وأخذوه منه قوله في صفة الخمر أنشدنيه الحسن بن علي قال أنشدني الحسين بن فهم قال أنشدني عمر بن شبة قال أنشدني أبو غسان محمد بن يحيى وغيره للوليد قال وكان أبو غسان يكاد يرقص إذا انشدها\n(اصدع نجي الهموم بالطرب ... وانعم على الدهر بابنة العنب)\n(واستقبل العيش في غضارته ... لا تقف منه آثار معتقب)\n(من قهوة زانها تقادمها ... فهي عجوز تعلو على الحقب)\n(أشهى إلى الشرب يوم جلوتها ... من الفتاة الكريمة النسب)\n(فقد تجلت ورق جوهرها ... حتى تبدت في منظر عجب)\n(فهي بغير المزاج من شرر ... وهي لدى المزج سائل الذهب)\n(كأنها في زجاجها قبس ... تذكو ضياء في عين مرتقب)\n(في فتية من بني أمية أهل ... المجد والمأثرات والحسب)\n(ما في الورى مثلهم ولا فيهم ... مثلي ولا منتم لمثل أبي)\nال المدائني في خبره وقال الوليد حين أتاه نعي هشام\n(طال ليلي فبت أسقى المداما ... إذ أتاني البريد ينعى هشاما)\n(وأتاني بحلة وقضيب ... وأتاني بخاتم ثم قاما)\n(فجعلت الولي من بعد فقدي ... يفضل الناس ناشئا وغلاما)\n(ذلك ابني وذاك قرم قريش ... خير قرم وخيرهم أعماما)\nخبرني الحسين بن يحيى عن حماد عن أبيه عن المدائني عن جرير قال قال لي عمر الوادي كنت يوما أغني الوليد إذ ذكر هشاما فقال لي غنني بهذه الأبيات قلت وما هي يا أمير المؤمنين فأنشأ يقول\n\n(هلك الأحول المشوم ... فقد أرسل المطر)\n(ثمت استخلف الوليد ... فقد أورق الشجر)","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":7,"spl":"نسبة ما في هذا الخبر من الغناء — الشاعر المجيد","song":1,"loc":1260},
{"id":"b70-12","bab":"الجزء 7","sec":"الشعراء يقتبسون معاني الوليد","page":"ج7 ص27","text":"وللوليد في ذكر الخمر وصفتها أشعار كثيرة قد أخذها الشعراء فأدخلوها في أشعارهم سلخوا معانيها وأبو نواس خاصة فإنه سلخ معانيه كلها وجعلها في شعره فكررها في عدة مواضع منه ولولا كراهة التطويل لذكرتها ها هنا على أنها تنبىء عن نفسها وله أبيات أنشدنيها الحسن بن علي قال أنشدني الحسين بن فهم قال أنشدني عمر بن شبة قال أنشدني أبو غسان وغيره للوليد وكان أبو غسان يكاد أن يرقص إذا أنشدها\n(اصدع نجي الهموم بالطرب ... وانعم على الدهر بابنة العنب)\nلأبيات التي مضت متقدما وهذا من بديع الكلام ونادره وقد جود فيه منذ ابتدأ إلى أن ختم وقد نقلها أبو نواس والحسين بن الضحاك في أشعارهما ومن جيد معانيه قوله\n(رأيتك تبني جاهدا في قطيعتي ... ولو كنت ذا حزم لهدمت ما تبني)\nوقد مضت في أخباره مع هشام وأنشدني الحسن بن علي عن الحسين بن فهم قال أنشدني عمرو بن أبي عمرو للوليد بن يزيد وكان يستجيده فقال\n(إذا لم يكن خير مع الشر لم تجد ... نصيحا ولا ذا حاجة حين تفزع)\n(وكانوا إذا هموا بإحدى هناتهم ... حسرت لهم رأسي فلا أتقنع)\nمن نادر شعره قوله لهشام\n(فإن تك قد مللت القرب مني ... فسوف ترى مجانبتي وبعدي)\n(وسوف تلوم نفسك إن بقينا ... وتبلو الناس والأحوال بعدي)\n(فتندم في الذي فرطت فيه ... إذا قايست في ذمي وحمدي)\nخبرني الحسين بن يحيى قال حدثنا ابن مهرويه وعبد الله بن عمرو بن أبي سعد قالا حدثنا عبد الله بن أحمد بن الحارث القرشي قال حدثنا محمد ابن عائذ قال حدثني الهيثم بن عمران قال سمعته يقول لما بويع الوليد سمعته على المنبر يقول بدمشق\n(ضمنت لكم إن لم ترعني منيتي ... بأن سماء الضر عنكم ستقلع)\nخبرني أحمد بن عبد العزيز قال حدثني عمر بن شبة قال حدثني عيسى ابن عبد الله بن محمد بن عمر بن على بن أبي طالب رضي الله عنه قال لما ولي الوليد بن يزيد كتب إلى أهل المدينة والشعر له\n(محرمكم ديوانكم وعطاؤكم ... به يكتب الكتاب والكتب تطبع)\n(ضمنت لكم إن لم تصابوا بمهجتي ... بأن سماء الضر عنكم ستقلع)\nأول هذه الأبيات\n(ألا أيها الركب المخبون أبلغوا ... سلامي سكان البلاد فأسمعوا)\n(وقولوا أتاكم أشبه الناس سنة ... بوالده فاستبشروا وتوقعوا)\n(سيوشك إلحاق بكم وزيادة ... وأعطية تأتي تباعا فتشفع)\nكان سبب مكاتبته أهل الحرمين بذلك أن هشاما لما خرج عليه زيد بن علي رضي الله عنه منع أهل مكة وأهل المدينة أعطياتهم سنة فقال حمزة ابن بيض يرد على الوليد لما فعل خلاف ما قال\n(وصلت سماء الضر بالضر بعد ما ... زعمت سماء الضر عنا ستقلع)\n(فليت هشاما كان حيا يسوسنا ... وكنا كما كنا نرجي ونطمع)\nخبرني أحمد قال حدثني عمر بن شبة قال روى جرير بن حازم عن الفضل بن سويد قال بعث الوليد بن يزيد إلى جماعة من أ هله لما ولي الخلافة فقال أتدرون لم دعوتكم قالوا لا قال ليقل قائلكم فقال رجل منهم أردت يا أمير المؤمنين أن ترينا ما جدد الله لك من نعمته وإحسانه فقال نعم ولكني\n(أشهد الله والملائكة الأبرار ... والعابدين أهل الصلاح)\n(أنني أشتهي السماع وشرب الكأس ... والعض للخدود الملاح)\n(والنديم الكريم والخادم الفاره ... يسعى علي بالأقداح)\nقوموا إذا شئتم","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":8,"spl":"الشعراء يقتبسون معاني الوليد","loc":1261},
{"id":"b70-13","bab":"الجزء 7","sec":"الوليد يبتاع الجواري ويجيز المادحين","page":"ج7 ص30","text":"أخبرني إسماعيل بن يونس وأحمد بن عبد العزيز قالا حدثنا عمر بن شبة قال حدثني إسحاق قال عرضت على الوليد بن يزيد جارية صفراء كوفية مولدة يقال لها سعاد فقال لها أي شيء تحسنين فقالت أنا مغنية فقال لها غنيني فغنت\n(لولا الذي حملت من حبكم ... لكان في إظهاره مخرج)\n(أو مذهب في الأرض ذو فسحة ... أجل ومن حجت له مذحج)\n(لكن سباني منكم شادن ... مربب ذو غنة أدعج)\n(أغر ممكور هضيم الحشى ... قد ضاق عنه الحجل والدملج)\nلشعر للحارث بن خالد والغناء لابن سريج خفيف رمل بالبنصر وفيه لدحمان هزج بالوسطى وذكر الهشامي أن الهزج ليحيى المكي فطرب طربا شديدا وقال يا غلام اسقني فسقاه عشرين قدحا وهو يستعيدها ثم قال لها لمن هذا الشعر قالت للحارث بن خالد قال وممن أخذتيه\nقالت من حنين قال وأين لقيته قالت ربيت بالعراق وكان أهلي يجيئون به فيطارحني فدعا صاحبه فقال اذهب فابتعها بما بلغت ولا تراجعني في ثمنها ففعل ولم تزل عنده حظية أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني عبيد الله بن عمار قال حدثني عبيد الله بن أحمد بن الحارث القرشي قال حدثنا العباس بن الوليد قال حدثنا ضمرة قال خرج عبد الوهاب بن إبراهيم الإمام يوما إلى بعض الديارات فنزل فيه وهو وال على الرملة فسأل صاحب الدير هل نزل بك أحد من بني أمية قال نعم نزل بي الوليد بن يزيد ومحمد بن سليمان بن عبد الملك قال فأي شيء صنعا قال شربا في ذلك الموضع ولقد رأيتهما شربا في آنيتهما ثم قال أحدهما لصاحبه هلم نشرب هذا الجرن وأومأ إلى جرن عظيم من رخام قال أفعل فلم يزالا يتعاطيانه بينهما ويشربان به حتى ثملا فقال عبد الوهاب لمولى له أسود هاته قال ضمرة وقد رأيته وكان يوصف بالشدة فذهب يحركه فلم يقدر فقال الراهب والله لقد رأيتهما يتعاطيانه وكل واحد منهما يملؤه لصاحبه فيرفعه ويشربه غير مكترث أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا أبو غسان محمد بن يحيى قال وفد سعد بن مرة بن جبير مولى آل كثير بن الصلت وكان شاعرا على الوليد بن يزيد فعرض له في يوم من أيام الربيع وقد خرج إلى متنزه له\nفصاح به يا أمير المؤمنين وافدك وزائرك ومؤملك فتبادر الحرس إليه ليصدوه عنه فقال دعوه ادن إلي فدنا إليه فقال من أنت قال أنا رجل من أهل الحجاز شاعر قال تريد ماذا قال تسمع مني أربعة أبيات قال هات\n(شمن المخايل نحو أرضك بالحيا ... ولقين ركبانا بعرفك قفلا)\nقال ثم مه قال\n(فعمدن نحوك لم ينخن لحاجة ... إلا وقوع الطير حتى ترحلا)\nقال إن هذا السير حثيث ثم ماذا قال\n(يعمدن نحو موطىء حجراته ... كرما ولم تعدل بذلك معدلا)\nقال فقد وصلت إليه فمه قال\n(لاحت لها نيران حيي قسطل ... فاخترن نارك في المنازل منزلا)\nقال فهل غير هذا قال لا قال أنجحت وفادتك ووجبت ضيافتك أعطوه أربعة آلاف دينار فقبضها ورحل الغناء لابن عائشة ثاني ثقيل بالبنصر عن عمرو والهشامي","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":9,"spl":"الوليد يبتاع الجواري ويجيز المادحين","song":2,"loc":1262},
{"id":"b70-14","bab":"الجزء 7","sec":"أخبار عن الوليد وزوجته","page":"ج7 ص33","text":"رجعت الرواية إلى حديث المدائني قال لما قدم العباس بن الوليد لإحصاء ما في خزائن هشام وولده سوى مسلمة بن هشام فإنه كان كثيرا ما يكف أباه عن الوليد ويكلمه فيه ألا يعرض له ولا يدخل منزله وكانت عند مسلمة أم سلمة بنت يعقوب المخزومية وكان مسلمة يشرب فلما قدم العباس لإحصاء ما كتب إليه الوليد كتبت إليه أم سلمة ما يفيق من الشراب ولا يهتم بشيء مما فيه إخوته ولا بموت أبيه فلما راح مسلمة بن هشام إلى العباس قال له يا مسلمة كان أبوك يرشحك للخلافة ونحن نرجوك لما بلغني عنك وأنبه وعاتبه على الشراب فأنكر مسلمة ذلك وقال من أخبرك بهذا قال كتبت إلي به أم سلمة فطلقها في ذلك المجلس فخرجت إلى فلسطين وبها كانت تنزل وتزوجها أبو العباس السفاح هناك وسلمى التي عناها الوليد هناك هي سلمى بنت سعيد بن خالد بن عمرو ابن عثمان بن عفان وأمها أم عمرو بنت مروان بن الحكم وأمها بنت عمر ابن أبي ربيعة المخزومي فأخبرني محمد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن محمد بن سلام وعن المدائني عن جويرية بن أسماء أن يزيد بن عبد الملك كان خرج إلى قرين متبديا به وكان هناك قصر لسعيد بن خالد بن عمرو بن عثمان وكانت بنته أم عبد الملك واسمها سعدة تحت الوليد بن يزيد فمرض سعيد في ذلك الوقت وجاءه الوليد عائدا فدخل فلمح سلمى بنت سعيد أخت زوجته وسترها حواضنها وأختها\nفقامت ففرعتهن طولا فوقعت بقلب الوليد فلما مات أبوه طلق أم عبد الملك زوجته وخطب سلمى إلى أبيها وكانت لها أخت يقال لها أم عثمان تحت هشام بن عبد الملك فبعثت إلى أبيها وقيل بعث إليه هشام أتريد أن تستفحل الوليد لبناتك يطلق هذه وينكح هذه فلم يزوجه سعيد ورده أقبح رد وهويها الوليد ورام السلو عنها فلم يسل وكان يقول العجب لسعيد خطبت إليه فردني ولو قد مات هشام ووليت لزوجني وهي طالق ثلاثا إن تزوجتها حينئذ وإن كنت أهواها فيقال إنه لما طلق سعدة ندم على ذلك وغمه وكان لها من قلبه محل ولم تحصل له سلمى فاهتم لذلك وجزع وراسل سعدة وقد كانت زوجت غيره فلم ينتفع بذلك فأخبرني أحمد بن عبد العزيز الجوهري والحسن بن علي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو مسلم عبد الرحمن بن الجهم قال حدثنا المدائني قال بعث الوليد بن يزيد إلى أشعب بعد ما طلق امرأته فقال يا أشعب لك عندي عشرة آلاف درهم على أن تبلغ رسالتي سعدة فقال أحضر العشرة الآلاف الدرهم حتى أنظر إليها فأحضرها الوليد فوضعها أشعب على عنقه وقال هات رسالتك قال قل لها يقول لك أمير المؤمنين\n(أسعدة هل إليك لنا سبيل ... وهل حتى القيامة من تلاقي)\n(بلى ولعل دهرا أن يؤاتي ... بموت من حليلك أو طلاق)\n(فأصبح شامتا وتقر عيني ... ويجمع شملنا بعد افتراق)\nفأتى أشعب الباب فأخبرت بمكانه فأمرت بفرش لها ففرشت وجلست وأذنت له فلما دخل أنشدها ما أمره فقالت لخدمها خذوا الفاسق فقال يا سيدتي إنها بعشرة آلاف درهم قالت والله لأقتلنك أو تبلغه كما بلغتني قال وما تهبين لي قالت بساطي الذي تحتي قال قومي عنه فقامت فطواه وجعله إلى جانبه ثم قال هات رسالتك جعلت فداك قالت قل له\n(أتبكي على لبنى وأنت تركتها ... فقد ذهبت لبنى فما أنت صانع)\nأقبل أشعب فدخل على الوليد فقال هيه فأنشده البيت فقال أوه قتلتني يابن الزانية ما أنا صانع فاختر أنت الآن ما أنت صانع يابن الزانية إما أن أدليك على رأسك منكسا في بئر أو أرمي بك منكسا من فوق القصر أو أضرب رأسك بعمودي هذا ضربة هذا الذي أنا صانع فاختر أنت الآن ما أنت صانع فقال ما كنت لتفعل شيئا من ذلك قال ولم يابن الزانية قال لم تكن لتعذب عينين نظرتا إلى سعدة قال أوه أفلت والله بهذا يابن الزانية اخرج عني وقال الحسن في روايته إنها قالت له أنشده\n(أتبكي على لبنى وأنت تركتها ... وأنت عليها بالملا كنت أقدر)\nوفي هذه الأبيات غناء هذه نسبته\n(أرى بيت لبنى أصبح اليوم يهجر ... وهجران لبنى يا لك الخير منكر)\n(فإن تكن الدنيا بلبنى تغيرت ... فللدهر والدنيا بطون وأظهر)\n(أتبكي على لبنى وأنت تركتها ... وأنت عليها بالحرا كنت أقدر)","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":10,"spl":"أخبار عن الوليد وزوجته","song":1,"loc":1263},
{"id":"b70-15","bab":"الجزء 7","sec":"أخبار عن الوليد وزوجته","page":"ج7 ص33","text":"روضه من الطويل والشعر لقيس بن ذريح والغناء في الثاني والثالث للغريض ثقيل أول بالبنصر عن عمرو والهشامي وفيهما لعريب رمل بالبنصر وفيه لشارية خفيف رمل بالوسطى عن الهشامي وفي الأول خفيف ثقيل مجهول قال ابن سلام والمدائني في خبرهما وخرج الوليد بن يزيد يريد فرتنى لعله يراها فلقيه زيات معه حمار عليه زيت فقال له هل لك أن تأخذ فرسي هذا وتعطيني حمارك هذا بما عليه وتأخذ ثيابي وتعطيني ثيابك ففعل الزيات ذلك وجاء الوليد وعليه الثياب وبين يديه الحمار يسوقه متنكرا حتى دخل قصر سعيد فنادى من يشتري الزيت فاطلع بعض الجواري فرأينه فدخلن إلى سلمى وقلن إن بالباب زياتا أشبه الناس بالوليد فاخرجي\nفانظري إليه فخرجت فرأته ورآها فرجعت القهقرى وقالت هو والله الفاسق الوليد وقد رآني فقلن له لا حاجة بنا إلى زيتك فانصرف وقال\n(إنني أبصرت شيخا ... حسن الوجه مليح)\n(ولباسي ثوب شيخ ... من عباء ومسوح)\n(وأبيع الزيت بيعا ... خاسرا غير ربيح)\nوقال أيضا\n(ما مسك يعل بزنجبيل ... ولا عسل بألبان اللقاح)\n(بأشهى من مجاجة ريق سلمى ... ولا ما في الزقاق من القراح)\n(ولا والله لا أنسى حياتي ... وثاق الباب دوني واطراحي)\nال فلما ولي الخلافة أشخص إلى المغنين فحضروه وفيهم معبد وابن عائشة وذووهما فقال لابن عائشة يا محمد إن غنيتني صوتين في نفسي فلك عندي مائة ألف درهم فغناه قوله\n(إنني أبصرت شيخا ... )\nوغناه\n(فما مسك يعل بزنجبيل ... )\nالأبيات فقال الوليد ما عدوت ما في نفسي وأمر له بمائة ألف درهم وألطاف وخلع وأمر لسائر المغنين بدون ذلك","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":11,"spl":"أخبار عن الوليد وزوجته — نسبة ما في هذا الخبر من الغناء","loc":1264,"partial":1},
{"id":"b70-16","bab":"الجزء 7","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج7 ص37","text":"\n(فما مسك يعل بزنجبيل ... ولا عسل بألبان اللقاح)\n(بأطيب من مجاجة ريق سلمى ... ولا ما في الزقاق من القراح)\nناه ابن عائشة ولحنه ثقيل أول بالوسطى عن الهشامي وحماد بن إسحاق","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":11,"spl":"أخبار عن الوليد وزوجته — نسبة ما في هذا الخبر من الغناء","song":1,"loc":1265},
{"id":"b70-17","bab":"الجزء 7","sec":"الوليد يرثي زوجته سلمى","page":"ج7 ص38","text":"قال المدائني وابن سلام فلما طال بالوليد ما به كتب إلى أبيها سعيد\n(أبا عثمان هل لك في صنيع ... تصيب الرشد في صلتي هديتا)\n(فأشكر منك ما تسدي وتحيي ... أبا عثمان ميتة وميتا)\nالوا فلم يجبه إلى ذلك حتى ولي الخلافة فلما وليها زوجه إياها فلم يلبث إلا مدة يسيرة حتى ماتت وقال فيها ليلة زفت إليه\n(خف من دار جيرتي ... يابن داود أنسها)\nوهي طويلة وفيها مما يغنى به\n(أو لا تخرج العروس ... فقد طال حبسها)\n(قد دنا الصبح أو بدا ... وهي لم يقض لبسها)\n(برزت كالهلال في ... ليلة غاب نحسها)\n(بين خمس كواعب ... أكرم الخمس جنسها)\nغناء ابن سريج فيما ذكره حبش رمل بالبنصر أوله\n(خف من دار جيرتي ... )\nوغناء معبد فيه خفيف ثقيل أوله\n(ومتى تخرج العروس ... )\nي رواية الهشامي وابن المكي وغناء عمر الوادي في الأربعة الأبيات الأخر خفيف رمل بالبنصر عن عمرو وذكر في النسخة الثانية ووافقه الهشامي أن فيه هزجا بالوسطى ينسب إلى حكم وإلى أبي كامل وإلى عمر وقد أخبرنا إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا الأصمعي قال رأيت حكما الوادي قد تعرض للمهدي وهو يريد الحج فوقف له في الطريق وكانت له شهرة فأخرج دفا له فنقر فيه وقال أنا أطال الله بقاءك القائل\n(ومتى تخرج العروس ... فقد طال حبسها)\n(قد دنا الصبح أو بدا ... وهي لم يقض لبسها)\nال فتسرع اليه الحرس فصيح بهم وإذا هو حكم الوادي فأدخل اليه المضرب فوصله وانصرف نسبة أولا تخرج العروس قال الشعر للوليد بن يزيد والغناء لعمر الوادي وفيه لحنان هزج خفيف بالخنصر في مجرى البنصر وخفيف رمل بالخنصر في مجرى البنصر جميعا عن إسحاق وذكر حكم الوادي أن الهزج له وذكر إسحاق أن لحن حكم خفيف رمل بالخنصر في مجرى الوسطى وقال في كتاب يحيى إن هذا اللحن لعمر الوادي وذكر الهشامي أن فيه خفيف ثقيل لمعبد ورملا لابن سريج وذكر عمرو بن بانة أن فيه للدلال خفيف ثقيل أول بالبنصر وقال المدائني مكثت عنده سلمى أربعين يوما ثم ماتت فقال\n(ألما تعلما سلمى أقامت ... مضمنة من الصحراء لحدا)\n(لعمرك يا وليد لقد أجنوا ... بها حسبا ومكرمة ومجدا)\n(ووجها كان يقصر عن مداه ... شعاع الشمس أهل أن يفدى)\n(فلم أر ميتا أبكى لعين ... وأكثر جازعا وأجل فقدا)\n(وأجدر أن تكون لديه ملكا ... يريك جلادة ويسر وجدا)\nكر أشعار الوليد التي قالها في سلمى وغنى المغنون فيها منها\n(عرفت المنزل الخالي ... عفا من بعد أحوال)\n(عفاه كل حنان ... عسوف الوبل هطال)\n(لسلمى قرة العين ... وبنت العم والخال)\n(بذلت اليوم في سلمى ... خطارا أتلفت مالي)\n(كأن الريق من فيها ... سحيق بين جريال)\nناه عمر الوادي هزجا بالوسطى عن عمرو وذكر ابن خرداذبه أن هذا اللحن للوليد بن يزيد وفيه رمل ذكر الهشامي أنه لابن سريج ومنها وهو الصوت الذي غناه أبو كامل فأعطاه الوليد قلنسيته\n(منازل قد تحل بها سليمى ... دوراس قد أضر بها السنون)\n(أميت السر حفظا يا سليمى ... إذا ما السر باح به الحزون)\nناه أبو كامل من الثقيل الأول وفيه لابن سريج ويقال للغريض خفيف ثقيل أول بالوسطى عن الهشامي وقيل إنه لحكم أو لعمر الوادي ومنها\n(أراني قد تصابيت ... وقد كنت تناهيت)\n(ولو يتركني الحب ... لقد صمت وصليت)\n(إذا شئت تصبرت ... ولا أصبر إن شيت)\n(ولا والله لا يصبر ... في الديمومة الحوت)\n(سليمى ليس لي صبر ... وإن رخصت لي جيت)\n(فقبلتك ألفين ... وفديت وحييت)\n(ألا أحبب بزور زار ... من سلمى ببيروت)\n(غزال أدعج العين ... نقي الجيد والليت)\nناه ابن جامع في البيتين الأولين هزجا بالوسطى وغناه أبو كامل في الأبيات كلها على ما ذكرت بذل ولم تجنسه وغنى حكم الوادي في الثالث والرابع والسابع والثامن خفيف رمل بالوسطى عن عمرو والهشامي ومنها\n(عتبت سلمى علينا سفاها ... أن سببت اليوم فيها أباها)\n(كان حق العتب يا قوم مني ... ليس منها كان قلبي فداها)\n(فلئن كنت أردت بقلبي ... لأبي سلمى خلاف هواها)\n(فثكلت اليوم سلمى فسلمى ... ملأت أرضي معا وسماها)\n(غير أني لا أظن عدوا ... قد أتاها كاشحا بأذاها)\n(فلها العتبى لدينا وقلت ... أبدا حتى أنال رضاها)","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":12,"spl":"الوليد يرثي زوجته سلمى","song":4,"loc":1266,"partialRef":{"sid":"b67-3","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b70-18","bab":"الجزء 7","sec":"الوليد يرثي زوجته سلمى","page":"ج7 ص38","text":"ناه أبو كامل خفيف رمل مطلق في مجرى البنصر عن إسحاق وفيه ليحيى المكي ثقيل أول من رواية علي بن يحيى وفيه رمل يقال إنه لابن جامع ويقال بل لحن ابن جامع خفيف رمل أيضا أخبرني أحمد بن عبيد الله بن عمار قال حدثني محمد بن القاسم بن مهرويه قال حدثني عبد الله بن عمرو قال لقي سعيد بن خالد الوليد بن يزيد وهو ثمل فقال له يا أبا عثمان أتردني على سلمى وكأني بك لو قد وليت الخلافة خطبتني فلم أجبك وإن تزوجتها حينئذ فهي طالق ثلاثا فقال له سعيد إن المرء يجعل كريمته عند مثلك لحقيق بأكثر مما قلت فأمضه الوليد وشتمه وتسامعا وافترقا وبلغ الوليد أن سلمى جزعت لما جرى وبكت وسبت الوليد ونالت منه فقال\n(عتبت سلمى علينا سفاها ... أن هجوت اليوم فيها أباها)\nوذكر الأبيات وقال أيضا في ذلك\n(على الدور التي بليت سفاها ... قفا يا صاحبي فسائلاها)\n(دعتك صبابة ودعاك شوق ... وأخضل دمع عينك مأقياها)\n(وقالت عند هجوتنا أباها ... أردت الصرم فانتده انتداها)\n(أردت بعادنا بهجاء شيخي ... وعندك خلة تبغي هواها)\n(فإن رضيت فذاك وإن تمادت ... فهبها خطة بلغت مداها)\nغناه مالك بن أبي السمح خفيف رمل بالسبابة في مجرى الوسطى عن إسحاق وللهذلي فيه ثاني ثقيل بالوسطى عن يونس والهشامي وذكر حبش أن الثقيل الثاني لإسحاق يعني بقوله\n(أردت بعادنا بهجاء شيخي ... )\nأنه كان هجا سعيد بن خالد فقال\n(ومن يك مفتاحا لخير يريده ... فإنك قفل يا سعيد بن خالد)\nال المدائني لما غضبت سلمى من هجائه أباها قال يعتذر إليه بقوله\n(ألا أبلغ أبا عثمان ... عذرة معتب أسفا)\n(فلست كمن يودك باللسان ... ويكثر الحلفا)\n(عتبت علي في أشياء ... كانت بيننا سرفا)\n(فلا تشمت بي الأعداء ... والجيران ملتهفا)\n(تود لو انني لحم ... رأته الطير فاختطفا)\n(ولا ترفع به رأسا ... عفا الرحمن ما سلفا)\nومنها وهو من سخيف شعره\n\n(خبروني أن سلمى ... خرجت يوم المصلى)\n(فإذا طير مليح ... فوق غصن يتفلى)\n(قلت من يعرف سلمى ... قال ها ثم تعلى)\n(قلت يا طير اذن مني ... قال ها ثم تدلى)\n(قلت هل أبصرت سلمى ... قال لا ثم تولى)\n(فنكا في القلب كلما ... باطنا ثم تعلى)\nيه ثقيل أول بالبنصر مطلق ذكر الهشامي أنه لأبي كامل ولعمر الوادي وذكر حبش أنه لدحمان ومنها\n(اسقني يابن سالم قد أنارا ... كوكب الصبح وانجلى واستنارا)\n(اسقني من سلاف ريق سليمى ... واسق هذا النديم كأسا عقارا)\nغناه ابن قندح ثاني ثقيل بالوسطى من رواية حبش أخبرنا محمد بن العباس اليزيدي قال حدثني عمي عبيد الله قال\nحدثني أبي أن المأمون قال لمن حضره من جلسائه أنشدوني بيتا لملك يدل البيت وإن لم يعرف قائله أنه شعر ملك فأنشده بعضهم قول امرىء القيس\n(أمن أجل أعرابية حل أهلها ... جنوب الملا عيناك تبتدران)\nال وما في هذا مما يدل على ملكه قد يجوز أن يقول هذا سوقة من أهل الحضر فكأنه يؤنب نفسه على التعلق بأعرابية ثم قال الشعر الذي يدل على أن قائله ملك قول الوليد\n(اسقني من سلاف ريق سليمى ... واسق هذا النديم كأسا عقارا)\nأما ترى إلى إشارته في قوله هذا النديم وأنها إشارة ملك ومثل قوله\n(لي المحض من ودهم ... ويغمرهم نائلي)\nوهذا قول من يقدر بالملك على طويات الرجال يبذل المعروف لهم ويمكنه استخلاصها لنفسه وفي هذا البيت مع أبيات قبله غناء وهو قوله\n(سقيت أبا كامل ... من الأصفر البابلي)\n(وسقيتها معبدا ... وكل فتى بازل)\n(لي المحض من ودهم ... ويغمرهم نائلي)\n(فما لامني فيهم ... سوى حاسد جاهل)\nغناه أبو كامل ثقيلا أول بإطلاق الوتر في مجرى البنصر ومنها وهو من ملح شعره\n(أراني الله يا سلمى حياتي ... وفي يوم الحساب كما أراك)\n(ألا تجزين من تيمت عصرا ... ومن لو تطلبين لقد قضاك)\n(ومن لو مت مات ولا تموتي ... ولو أنسي له أجل بكاك)\n(ومن حقا لو اعطي ما تمنى ... من الدنيا العريضة ما عداك)\n(ومن لو قلت مت فأطاق موتا ... إذا ذاق الممات وما عصاك)\n(أثيبي عاشقا كلفا معنى ... إذا خدرت له رجل دعاك)\nانت العرب تقول إن الإنسان إذا خدرت قدمه دعا باسم أحب الناس اليه فسكنت في الخبر أن رجل عبد الله بن عمر خدرت فقيل له ادع باسم أحب الناس اليك فقال يا رسول الله ذكر يونس أن في هذه الأبيات لحنا لسنان الكاتب وذكرت دنانير أنه لحكم ولم تجنسه ومنها","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":13,"spl":"الوليد يرثي زوجته سلمى","song":6,"loc":1267,"partial":1},
{"id":"b70-19","bab":"الجزء 7","sec":"الوليد يرثي زوجته سلمى","page":"ج7 ص38","text":"(ويح سلمى لو تراني ... لعناها ما عناني)\n(متلفا في اللهو مالي ... عاشقا حور القيان)\n(إنما أحزن قلبي ... قول سلمى إذ أتاني)\n(ولقد كنت زمانا ... خالي الذرع لشاني)\n(شاق قلبي وعناني ... حب سلمى وبراني)\n(ولكم لام نصيح ... في سليمى ونهاني)\nنته فريدة خفيف ثقيل بالوسطى عن عمرو وفيه ثقيل أول ينسب إلى معبد وهو فيما يذكر إسحاق يشبه غناءه وليس تعرف صحته له وذكر كثير الكبير أنه له وذكر الهشامي أنه لابن المكي وفيه لحكم هزج صحيح ومنها\n(بلغا عني سليمى ... وسلاها لي عما)\n(فعلت في شأن صب ... دنف أشعر هما)\n(ولقد قلت لسلمى ... إذ قتلت البين علما)\n(أنت همي يا سليمى ... قد قضاه الرب حتما)\n(نزلت في القلب قسرا ... منزلا قد كان يحمى)\nناه حكم خفيف ثقيل ولعمر الوادي فيه خفيف رمل بالخنصر في مجرى الوسطى عن إسحاق ومنها\n(يا سليمى يا سليمى ... كنت للقلب عذابا)\n(يا سليمى ابنة عمي ... برد الليل وطابا)\n(أيما واش وشى بي ... فاملئي فاه ترابا)\n(ريقها في الصبح مسك ... باشر العذب الرضابا)\nناه عمر الوادي هزجا بالبنصر عن الهشامي وذكر ابن المكي أنه لمعان وفي كتاب إبراهيم أنه لعطرد ومنها\n(أسلمى تلك حييت ... قفي نخبرك إن شيت)\n(وقيليي ساعة نشك ... إليك الحب أو بيتي)\n(فما صهباء لم تكس ... قذى من خمر بيروت)\n(ثوت في الدن أعواما ... ختيما عند حانوت)\nغناه عمر الوادي ثاني ثقيل بالوسطى عن عمرو ومنها\n(يا من لقلب في الهوى متشعب ... بل من لقلب بالحبيب عميد)\n(سلمى هواه ليس يعرف غيرها ... دون الطريف ودون كل تليد)\n(إن القرابة والسعادة ألفا ... بين الوليد وبين بنت سعيد)\n(يا قلب كم كلف الفؤاد بغادة ... ممكورة ريا العظام خريد)\nناه عمر الوادي رملا بالبنصر عن عمرو ومنها\n(قد تمنى معشر إذ أطربوا ... من عقار وسوام وذهب)\n(ثم قالوا لي تمن واستمع ... كيف ننحو في الأماني والطلب)\n(فتمنيت سليمى إنها ... بنت عمي من لهاميم العرب)\nيه للهذلي خفيف ثقيل أول بالوسطى عن عمرو وذكر الهشامي أن هذا الخفيف الثقيل لخالد صامة وذكر ابن المكي أن فيه لمالك ثاني ثقيل بالوسطى ومنها\n(هل إلى أم سعيد ... من رسول أو سبيل)\n(ناصح يخبر أني ... حافظ ود خليل)\n(يبذل الود لغيري ... وأكافي بالجميل)\n(لست أرضى لخليلي ... من وصالي بالقليل)\nناه عمر الوادي هزجا خفيفا بالسبابة في مجرى الوسطى ومنها\n(طاف من سلمى خيال ... بعد ما نمت فهاجا)\n(قلت عج نحوي أسائلك ... عن الحب فعاجا)\n(يا خليلي يا نديمي ... قم فأنفث لي سراجا)\n(بفلاة ليس ترعى ... أنبتت شيحا وحاجا)\nغناه عمر الوادي ثاني ثقيل بالوسطى عن عمرو ولابن سريج فيه خفيف رمل بالوسطى عن حبش ... ولأبي سلمى المدني ثقيل أول عن ابن خرداذبه ومنها\n(أم سلام أثيبي عاشقا ... يعلم الله يقينا ربه)\n(أنكم من عيشه في نفسه ... يا سليمى فاعلميه حسبه)\n(فارحميه إنه يهذي بكم ... هائم صب قد اودى قلبه)\n(أنت لو كنت له راحمة ... لم يكدر يا سليمى شربه)\nناه حكم رملا بالسبابة في مجرى البنصر عن إسحاق وذكر عمرو بن بانة أن فيه لابن سريج رملا بالوسطى\nومنها\n(رب بيت كأنه متن سهم ... سوف نأتيه من قرى بيروت)\n(من بلاد ليست لنا ببلاد ... كلما جئت نحوها حييت)\n(أم سلام لا برحت بخير ... ثم لا زلت جنتي ما حييت)\n(طربا نحوكم وتوقا وشوقا ... لادكاريكم وطيب المبيت)\n(حيثما كنت من بلاد وسرتم ... فوقاك الإله ما قد خشيت)\nي البيت الأول والثاني لابن عائشة ثقيل أول بالسبابة في مجرى البنصر عن الهشامي وذكر غيره أنه لإبراهيم وفي الثالث وما بعده والثاني لابن عائشة أيضا رمل بالوسطى ولابن سريج خفيف رمل بالبنصر وقيل إن الرمل لعمر الوادي وهو أن يكون له أشبه ومنها\n(طرقتني وصحابي هجوع ... ظبية أدماء مثل الهلال)\n(مثل قرن الشمس لما تبدت ... واستقلت في رؤوس الجبال)\n(تقطع الأهوال نحوي وكانت ... عندنا سلمى ألوف الحجال)\n(كم أجازت نحونا من بلاد ... وحشة قتالة للرجال)\nابن محرز فيه ثقيل أول مطلق في مجرى الوسطى عن إسحاق في الثاني والثالث ولابن سريج في الأول وما بعده خفيف ثقيل بالوسطى عن\nعمرو وفيه لحن لابن عائشة ذكر الهشامي أنه رمل بالوسطى وفيه خفيف رمل ينسب إلى ابن سريج وعمر الوادي ومنها","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":14,"spl":"الوليد يرثي زوجته سلمى","song":11,"loc":1268},
{"id":"b70-20","bab":"الجزء 7","sec":"الوليد يرثي زوجته سلمى","page":"ج7 ص38","text":"(أنا الوليد الإمام مفتخرا ... أنعم بالي وأتبع الغزلا)\n(أهوى سليمى وهي تصرمني ... وليس حقا جفاء من وصلا)\n(أسحب بردي إلى منازلها ... ولا أبالي مقال من عذلا)\nنى فيه أبو كامل رملا بالبنصر وغنى عمر الوادي فيه خفيف رمل بالوسطى ويقال إن هذا اللحن للوليد أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال الوليد على لسان سلمى\n(إقر مني على الوليد السلاما ... عدد النجم قل ذا للوليد)\n(حسدا ما حسدت أختي عليه ... ربنا بيننا وبين سعيد)\nناه الهذلي خفيف ثقيل أول بالوسطى عن ابن المكي حدثني محمد بن يحيى الصولي قال حدثنا خالد بن النضر القرشي\nبالبصرة قال حدثنا أبو حاتم السجستاني قال حدثنا العتبي قال كانت للوليد بني يزيد جارية يقال لها صدوف فغاضبها ثم لم يطعه قلبه فجعل يتسبب لصلحها فدخل عليه رجل قرشي من أهل المدينة فكلمه في حاجة وقد عرف خبره فبرم به فأنشده\n(أعتبت أن عتبت عليك صدوف ... وعتاب مثلك مثلها تشريف)\n(لا تقعدن تلوم نفسك دائما ... فيها وأنت بحبها مشغوف)\n(إن القطيعة لا يقوم لمثلها ... إلا القوي ومن يحب ضعيف)\n(الحب أملك بالفتى من نفسه ... والذل فيه مسلك مألوف)\nقال فضحك وجعل ذلك سببا لصلحها وأمر بقضاء حوائج القرشي كلها","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":15,"spl":"الوليد يرثي زوجته سلمى — الوليد يستقدم حماد الراوية","song":1,"loc":1269},
{"id":"b70-21","bab":"الجزء 7","sec":"الوليد يستقدم حماد الراوية","page":"ج7 ص54","text":"أخبرني الحسن بن علي عن أحمد بن الحارث عن المدائني قال قال حماد الراوية استدعاني الوليد بن يزيد وأمر لي بألفين لنفقتي وألفين لعيالي فقدمت عليه فلما دخلت داره قال لي الخدم أمير المؤمنين من خلف الستارة الحمراء فسلمت بالخلافة فقال لي يا حماد قلت لبيك يا أمير المؤمنين قال ثم ثاروا فلم أدر ما يعنى فقال ويحك يا حماد ثم ثاروا فقلت في نفسي راوية أهل العراق لا يدري عما يسأل ثم انتبهت فقلت\n(ثم ثاروا إلى الصبوح فقامت ... قينة في يمينها إبريق)\n(قدمته على عقار كعين الديك ... صفى سلافها الراووق)\n(ثم فض الختام عن حاجب الدن ... وقامت لدى اليهودي سوق)\n(فسباها منه أشم عزيز ... أريحي غذاه عيش رقيق)\nلشعر لعدي بن زيد والغناء لحنين خفيف ثقيل أول بالبنصر ... وفيه لمالك خفيف رمل ولعبد الله بن العباس الربيعي رمل كل ذلك عن الهشامي قال فإذا جارية قد أخرجت كفا لطيفة من تحت الستر في يدها قدح والله ما أدري أيهما أحسن الكف أم القدح فقال رديه فما أنصفناه تغدينا ولم نغده فأتيت بالغداء وحضر أبو كامل مولاه فغناه\n(أدر الكأس يمينا ... لا تدرها ليسار)\n(اسق هذا ثم هذا ... صاحب العود النضار)\n(من كميت عتقوها ... منذ دهر في جرار)\n(ختموها بالأفاويه ... وكافور وقار)\n(فلقد أيقنت أني ... غير مبعوث لنار)\n(سأروض الناس حتى ... يركبوا أير الحمار)\n(وذروا من يطلب الجنة ... يسعى لتبار)\nيه هزجان بالوسطى والبنصر لعمر الوادي وأبي كامل فطرب وبرز إلينا وعليه غلالة موردة وشرب حتى سكر فأقمت عنده مدة ثم أذن بالإنصراف وكتب لي إلى عامله بالعراق بعشرة آلاف درهم","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":15,"spl":"الوليد يرثي زوجته سلمى — الوليد يستقدم حماد الراوية","song":1,"loc":1270},
{"id":"b70-22","bab":"الجزء 7","sec":"الوليد إذا تهتك","page":"ج7 ص56","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز عن المدائني قال لما ولي الوليد بن يزيد لهج بالغناء والشراب والصيد وحمل المغنين من المدينة وغيرها إليه وأرسل إلى أشعب فجاء به فألبسه سراويل من جلد قرد له ذنب وقال له ارقص وغنني شعرا يعجبني فإن فعلت فلك ألف درهم فغناه فأعجبه فأعطاه ألف درهم ودخل إليه يوما فلما رآه الوليد كشف عن أيره وهو منعظ قال أشعب فرأيته كأنه مزمار آبنوس مدهون فقال لي أرأيت مثله قط قلت لا يا سيدي قال فاسجد له فسجدت ثلاثا فقال ما هذا قلت واحدة\nلأيرك وثنتين لخصيتيك قال فضحك وأمر لي بجائزة قال وتكلم بعض جلسائه والمغنية تغني فكره ذلك وأضجره فقال لبعض جلسائه قم فنكه فقام فناكه والناس حضور وهو يضحك وذكرت جارية أنه واقعها يوما وهو سكران فلما تنحى عنها آذنه المؤذن بالصلاة فحلف ألا يصلي بالناس غيرها فخرجت متلثمة فصلت بالناس قال ونزل على غدير ماء فاستحسنه فلما سكر حلف ألا يبرح حتى يشرب ذلك الغدير كله ونام فأمر العلاء بن البندار بالقرب والروايا فأحضرت فجعل ينزحه ويصبه على الأرض والكثب التي حولهم حتى لم يبق فيه شيء فلما أصبح الوليد رآه قد نشف فطرب وقال أنا أبو العباس ارتحلوا فارتحل الناس نسخت من كتاب الحسين بن فهم قال النضر بن حديد حدثني ابن أبي جناح قال أخبرني عمر بن جبلة أن الوليد بن يزيد بات عند امرأة وعدته المبيت فقال حين انصرف\n(قامت الي بتقبيل تعانقني ... ريا العظام كأن المسك في فيها)\n(أدخل فديتك لا يشعر بنا أحد ... نفسي لنفسك من داء تفديها)\n(تبنا كذلك لا نوم على سرر ... من شدة الوجد تدنيني وأدنيها)\n(حتى إذا ما بدا الخيطان قلت لها ... حان الفراق فكاد الحزن يشجيها)\n(ثم انصرفت ولم يشعر بنا أحد ... والله عني بحسن الفعل يجزيها)\nوحدثني النضر بن حديد قال حدثنا هشام بن الكلبي عن خالد بن سعيد قال مر الوليد بن يزيد وهو متصيد بنسوة من بني كلب من بني المنجاب فوقف عليهن واستسقاهن وحدثهن وأمر لهن بصلة ثم مضى وهو يقول\n(ولقد مررت بنسوة أعشينني ... حور المدامع من بنس المنجاب)\n(فيهن خرعبة مليح دلها ... غرثى الوشاح دقيقة الأنياب)\n(زين الحواضر ما ثوت في حضرها ... وتزين باديها من الأعراب)\nقال النضر وحدثني ابن الكلبي عن أبيه أن الوليد خرج يتصيد ذات يوم فصادت كلابه غزالا فأتي به فقال خلوه فما رأيت أشبه منه جيدا وعينين بسلمى ثم أنشأ يقول\n(ولقد صدنا غزالا سانحا ... قد أردنا ذبحه لما سنح)\n(فإذا شبهك ما ننكره ... حين أزجى طرفه ثم لمح)\n(فتركناه ولولا حبكم ... فاعلمي ذاك لقد كان انذبح)\n(أنت يا ظبي طليق آمن ... فاغدفي الغزلان مسرورا ورح)\nسخت من كتاب الحسين بن فهم قال أخبرني عمرو عن أبيه عن عمرو ابن واقد الدمشقي قال\nبعث الوليد بن يزيد إلى شراعة بن الزندبوذ فلما قدم عليه قال يا شراعة إني لم أستحضرك لأسألك عن العلم ولا لأستفتيك في الفقه ولا لتحدثني ولا لتقرئني القرآن قال لو سألتني عن هذا لوجدتني فيه حمارا قال فكيف علمك بالفتوة قال ابن بجدتها وعلى الخبير بها سقطت فسل عما شئت قال فكيف علمك بالأشربة قال ليسألني أمير المؤمنين عما أحب قال ما قولك في الماء قال هو الحياة ويشركني فيه الحمار قال فاللبن قال ما رأيته قط إلا ذكرت أمي فاستحيت قال فالخمر قال تلك السارة البارة وشراب أهل الجنة قال لله درك فأي شيء أحسن ما يشرب عليه قال عجبت لمن قدر أن يشرب على وجه السماء في كن من الحر والقر كيف يختار عليها شيئا","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":16,"spl":"الوليد إذا تهتك","loc":1271},
{"id":"b70-23","bab":"الجزء 7","sec":"قصة الوليد والمصحف","page":"ج7 ص59","text":"قال وأخبرنا عمرو عن أبيه عن يحيى بن سليم قال دعا الوليد بن يزيد ذات ليلة يمصحف فلما فتحه وافق ورقة فيها ( واستفتحوا وخاب كل جبار عنيد . من ورائه جهنم ويسقى من ماء صديد\nفقال أسجعا سجعا علقوه ثم أخذ القوس والنبل فرماه حتى مزقه ثم قال\n(أتوعد كل جبار عنيد ... فها أنا ذاك جبار عنيد)\n(إذا لاقيت ربك يوم حشر ... فقل لله مزقني الوليد)\nقال فما لبث بعد ذلك إلا يسيرا حتى قتل أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إسحاق ابن إبراهيم قال حدثني معاوية بن بكر عن يعقوب بن عياش المروزي من أهل ذي المروة أن أباه حمل عدة جوار إلى الوليد بن يزيد فدخل اليه وعنده أخوه عبد الجبار وكان حسن الوجه والشعرة وفيها فأمر الوليد جارية منهن أن تغني\n(لو كنت من هاشم أو من بني أسد ... أو عبد شمس أو أصحاب اللوا الصيد)\nوأمرها أخوه أن تغني\n(أتعجب أن طربت لصوت حاد ... حدا بزلا يسرن ببطن واد)\nفغنت ما أمرها به الغمر فغضب الوليد واحمر وجهه وظن أنها فعلت ذلك ميلا إلى أخيه وعرفت الشر في وجهه فاندفعت فغنت\n\n(أيها العاتب الذي خاف هجري ... وبعادي وما عمدت لذاكا)\n(أترى أنني بغيرك صب ... جعل الله من تظن فداكا)\n(أنت كنت الملول في غير شيء ... بئس ما قلت ليس ذاك كذاكا)\n(ولو ان الذي عتبت عليه ... خير الناس واحدا ما عداكا)\n(فارض عني جعلت نعليك إني ... والعظيم الجليل أهوى رضاكا)\nلشعر لعمر والغناء لمعبد من روايتي يونس وإسحاق ولحنه من خفيف الثقيل بإطلاق الوتر في مجرى البنصر وذكر حماد في أخبار ابن عائشة أن له فيه لحنا قال فسري عن الوليد وقال لها ما منعك أن تغني ما دعوتك إليه قالت لم أكن أحسنه وكنت أحسن الصوت الذي سألنيه أخذته من ابن عائشة فلما تبينت غضبك غنيت هذا الصوت وكنت أخذته من معبد تعني الذي اعتذرت به إليه","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":17,"spl":"قصة الوليد والمصحف — ولع الوليد بغناء الجواري","song":1,"loc":1272},
{"id":"b70-24","bab":"الجزء 7","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج7 ص61","text":"\n(لو كنت من هاشم أو من بني أسد ... أو عبد شمس أو أصحاب اللوا الصيد)\n(أو من بني نوفل أو آل مطلب ... أو من بني جمح الخضر الجلاعيد)\n(أو من بني زهرة الأبطال قد عرفوا ... لله درك لم تهمم بتهديد)\nالشعر لحسان بن ثابت يقوله لمسافع بن عياض أحد بني تيم بن مرة وخبره يذكر بعد هذا والغناء لابن سريج خفيف رمل بالخنصر وقيل إنه لمالك ومنها\n(أتعجب أن طربت لصوت حاد ... حدا بزلا يسرن ببطن واد)\n(فلا تعجب فإن الحب أمسى ... لبثنة في السواد من الفؤاد)\nالشعر لجميل والغناء لابن عائشة رمل بالبنصر","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":17,"spl":"قصة الوليد والمصحف — ولع الوليد بغناء الجواري","song":2,"loc":1273},
{"id":"b70-25","bab":"الجزء 7","sec":"ولع الوليد بغناء الجواري","page":"ج7 ص62","text":"أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثني إسحاق بن إبراهيم قال عرضت على الوليد بن يزيد جارية مغنية فقال لها غني فغنت\n\n(لولا الذي حملت من حبكم ... لكان من إظهاره مخرج)\n(أو مذهب في الأرض ذو فسحة ... أجل ومن حجت له مذحج)\n(لكن سباني منهم شادن ... مربب بينهم أدعج)\n(أغر ممكور هضيم الحشى ... قد ضاق عنه الحجل والدملج)\nفقال لها الوليد لمن هذا الشعر قالت للوليد بن يزيد المخزومي قال فممن أخذت الغناء قالت من حنين فقال أعيديه فأعادته فأجادت فطرب الوليد ونعر وقال أحسنت وأبي وجمعت كل ما يحتاج إليه في غنائك وأمر بابتياعها وحظيت عنده غنى في هذا الصوت ابن سريج ولحنه رمل بالبنصر وغنى فيه إسحاق فيما ذكر الهشامي خفيف ثقيل ومما يغنى به من هذه القصيدة\n(قد صرح القوم وما لجلجوا ... لجوا علينا ليت لم يلججوا)\n(باتوا وفيهم كالمها طفلة ... قد زانها الخلخال والدملج)\nغناه صباح الخياط خفيف ثقيل بالبنصر وغنى فيه ابن أبي الكنات خفيف ثقيل بالوسطى","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":17,"spl":"قصة الوليد والمصحف — ولع الوليد بغناء الجواري","song":2,"loc":1274},
{"id":"b70-26","bab":"الجزء 7","sec":"حسان يهجو مسافع بن عياض","page":"ج7 ص63","text":"فأما خبر الشعر الذي قاله حسان بن ثابت لمسافع بن عياض أحد بني تيم بن مرة فأخبرني به الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عثمان بن عبد الرحمن\nأن عبيد الله بن معمر وعبد الله بن عامر بن كريز اشتريا من عمر ابن الخطاب رضي الله عنه رقيقا ممن سبي ففضل عليهما ثمانون ألف درهم فأمر بهما عمر أن يلزما فمر بهما طلحة بن عبيد الله وهو يريد الصلاة في مسجد رسول الله ما لابن معمر يلازم فأخبر خبره فأمر له بالأربعين ألفا التي عليه تقضى عنه فقال ابن معمر لابن عامر إنها إن قضيت عني بقيت ملازما وإن قضيت عنك لم يتركني طلحة حتى يقضي عني فدفع إليه الأربعين ألف درهم فقضاها ابن عامر عن نفسه وخليت سبيله فمر طلحة منصرفا من الصلاة فوجد ابن معمر يلازم فقال ما لابن معمر ألم آمر بالقضاء عنه فأخبر بما صنع فقال أما ابن معمر فعلم أن له ابن عم لا يسلمه إحملوا عنه أربعين ألف درهم فاقضوها عنه ففعلوا وخلي سبيله فقال حسان بن ثابت لمسافع بن عياض بن صخر بن عامر بن كعب ابن سعد بن تيم بن مرة\n(يا آل تيم ألا تنهون جاهلكم ... قبل القذاف بصم كالجلاميد)\n(فنهنهوه فإني غير تارككم ... إن عاد ما اهتز ماء في ثرى عود)\n(لو كنت من هاشم أو من بني أسد ... أو عبد شمس أو اصحاب اللوا الصيد)\n(أو من بني نوفل أو آل مطلب ... أو من بني جمح الخضر الجلاعيد)\n(أو من بني زهرة الأبطال قد عرفوا ... لله درك لم تهمم بتهديد)\n(أو في الذؤابة من تيم إذا انتسبوا ... أو من بني الحارث البيض الأماجيد)\n(لكن سأصرفها عنكم وأعدلها ... لطلحة بن عبيد الله ذي الجود)\nرجع الخبر إلى سياقة أخبار الوليد أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن عمرو قال قال الهيثم حدثني ابن عياش قال دخل أبو الأقرع على الوليد بن يزيد فقال له أنشدني قولك في الخمر فأنشده قوله\n(كميت إذا شجت وفي الكأس وردة ... لها في عظام الشاربين دبيب)\n(تريك القذى من دونها وهي دونه ... لوجه أخيها في الإناء قطوب)\nفقال الوليد شربتها يا أبا الأقرع ورب الكعبة يا أمير المؤمنين\nلئن كان نعتي له رابك لقد رابني معرفتك بها أخبرني الحسن قال حدثني ابن مهرويه قال حدثني عبد الله بن عمرو قال قال المدائني نظر الوليد بن يزيد إلى أم حبيب بنت عبد الرحمن بن مصعب بن عبد الرحمن بن عوف وقد مروا بين يديها بالشمع ليلا فلما رآها أعجبته وراعه جمالها وحسنها فسأل عنها فقيل له إن لها زوجا فأنشأ يقول\n(إنما هاج لقلبي ... شجوه بعد المشيب)\n(نظرة قد وقرت في القلب ... من أم حبيب)\n(فإذا ما ذقت فاها ... ذقت عذبا ذا غروب)\n(خالط الراح بمسك ... خالص غير مشوب)\nغناه ابن محرز خفيف رمل بالوسطى عن الهشامي وذكر عمرو بن بانة أنه للأبجر وهو الصحيح","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":18,"spl":"حسان يهجو مسافع بن عياض — أأيقاظ أمية أم نيام","song":1,"loc":1275},
{"id":"b70-27","bab":"الجزء 7","sec":"أأيقاظ أمية أم نيام","page":"ج7 ص66","text":"أخبرني عمي قال حدثني الكراني عن النضر بن عمرو عن العتبي قال\nلما ظهرت المسودة بخراسان كتب نصر بن سيار إلى الوليد يستمده فتشاغل عنه فكتب إليه كتابا وكتب في أسفله يقول\n(أرى خلل الرماد وميض جمر ... وأحر بأن يكون له ضرام)\n(فإن النار بالعودين تذكى ... وإن الحرب مبدؤها الكلام)\n(فقلت من التعجب ليت شعري ... أأيقاظ أمية أم نيام)\nكتب إليه الوليد قد أقطعتك خراسان فاعمل لنفسك أو دع فإني مشغول عنك بابن سريج ومعبد والغريض أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن أبي سعد عن ابن الصباح عن ابن الكلبي عن حماد الراوية قال دخلت يوما على الوليد وكان آخر يوم لقيته فيه فاستنشدني فأنشدته كل ضرب من شعر أهل الجاهلية والإسلام فما هش لشيء منه حتى أخذت في السخف فأنشدته لعمار ذي كناز مجنبذا\n(أشتهي منك منك منك ... مكانا مجنبذا)\n(فأجا فيه فيه فيه ... بأير كمثل ذا)\n(ليت أيري وحرك يوما ... جميعا تجابذا)\n(فأخذ ذا بشعر ذا ... وأخذ ذا بقعر ذا)\nفضحك حتى استلقى وطرب ودعا بالشراب فشرب وجعل يستعيدني الأبيات فأعيدها حتى سكر وأمر لي بجائزة فعلمت أن أمره قد أدبر ثم أدخلت على أبي مسلم فاستنشدني فأنشدته قول الأفوه\n(لنا معاشر لم يبنوا لقومهم ... )\nفلما بلغت إلى قوله\n(تهدى الأمور بأهل الرشد ما صلحت ... وإن تولت فبالأشرار تنقاد)\nقال أنا ذلك الذي تنقاد به الناس فأيقنت حينئذ أن أمره مقبل","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":18,"spl":"حسان يهجو مسافع بن عياض — أأيقاظ أمية أم نيام","loc":1276,"partial":1},
{"id":"b70-28","bab":"الجزء 7","sec":"الوليد السكران يخطب الجمعة شعرا","page":"ج7 ص68","text":"أخبرني محمد بن خلف وكيع قال وجدت في كتاب عن عبيد الله ابن سعيد الزهري عن عمر عن أبيه قال خرج الوليد بن يزيد وكان مع أصحابه على شراب فقيل له إن اليوم الجمعة فقال والله لأخطبنهم اليوم بشعر فصعد المنبر فخطب فقال\n(الحمد لله ولي الحمد ... أحمد في يسرنا والجهد)\n(وهو الذي في الكرب أستعين ... وهو الذي ليس له قرين)\n(أشهد في الدنيا وما سواها ... أن لا إله غيره إلها)\n(ما إن له في خلقه شريك ... قد خضعت لملكه الملوك)\n(أشهد أن الدين دين أحمد ... فليس من خالفه بمهتدي)\n(وأنه رسول رب العرش ... القادر الفرد الشديد البطش)\n(أرسله في خلقه نذيرا ... وبالكتاب واعظا بشيرا)\n(ليظهر الله بذاك الدنيا ... وقد جعلنا قبل مشركينا)\n(من يطع الله فقد أصابا ... أو يعصه أو الرسول خابا)\n(ثم القران والهدى السبيل ... قد بقيا لما مضى الرسول)\n(كأنه لما بقي لديكم ... حي صحيح لا يزال فيكم)\n(إنكم من بعد إن تزلوا ... عن قصده أو نهجه تضلوا)\n(لا تتركن نصحي فإني ناصح ... إن الطريق فاعلمن واضح)\n(من يتق الله يجد غب التقى ... يوم الحساب صائرا إلى الهدى)\n(إن التقى أفضل شيء في العمل ... أرى جماع البر فيه قد دخل)\n(خافوا الجحيم إخوتي لعلكم ... يوم اللقاء تعرفوا ما سركم)\n(قد قيل في الأمثال لو علمتم ... فانتفعوا بذاك إن عقلتم)\n(ما يزرع الزارع يوما يحصده ... وما يقدم من صلاح يحمده)\n(فاستغفروا ربكم وتوبوا ... فالموت منكم فاعلموا قريب)\nثم نزل","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":19,"spl":"الوليد السكران يخطب الجمعة شعرا","loc":1277},
{"id":"b70-29","bab":"الجزء 7","sec":"نوادر الوليد","page":"ج7 ص69","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي عن أبيه عن الوليد البندار قال حججت مع الوليد بن يزيد فقلت له لما أراد أن يخطب الناس أيها الأمير إن اليوم يوم يشهده الناس من جميع الآفاق وأريد أن تشرفني بشيء\nقال وما هو قلت إذا علوت المنبر دعوت بي فيتحدث الناس بذلك وبأنك أسررت إلي شيئا فقال أفعل فلما جلس على المنبر قال الوليد البندار فقمت إليه فقال ادن مني فدنوت فأخذ بأذني ثم قال البندار ولد زنا والوليد ولد زنا وكل من ترى حولنا ولد زنا أفهمت قلت نعم قال انزل الآن فنزلت أخبرني محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري عن الهيثم بن عدي عن أشعب قال دخلت على الوليد بن يزيد الخاسر وقد تناول نبيذا فقال لي تمن فقلت يتمنى أمير المؤمنين ثم أتمنى قال فإنما أردت أن تغلبني فإني لأتمنى ضعف ما تتمنى به كائنا ما كان قلت فإني أتمنى كفلين من العذاب فضحك ثم قال إذا نوفرهما عليك ثم قال لي ما أشياء تبلغني عنك قلت يكذبون علي قال متى عهدك بالأصم قلت لا عهد لي به فأخرج أيره كأنه ناي مدهون فسجدت له ثلاث سجدات فقال ويلك إنما يسجد الناس سجدة واحدة فقلت واحدة للأصم واثنتين لخصيتيك أخبرنا محمد بن العباس اليزيدي قال حدثنا محمد بن علي بن حمزة قال حدثني عبد الصمد بن موسى الهاشمي قال إنما أغلى الجوهر بنو أمية ولقد كان الوليد بن يزيد يلبس منه العقود ويغيرها في اليوم مرارا كما تغير الثياب شغفا فكان يجمعه من كل وجه ويغالي به قال وكان يوما في داره على فرس له وجارية تضرب بطبل قدامه\nفأخذه منها ووضعه على رقبته ونفر الفرس من صوت الطبل فخرج به على أصحابه في هذه الهيئة وكان خليعا أخبرني الحسن بن علي قال حدثنا الخراز عن المدائني عن جويرية بن أسماء قال قدم الوليد بن يزيد المدينة فقلت لاسماعيل بن يسار أحذنا مما أعطاك الله فقال هلم أقاسمك إن قبلت بعث إلي براوية من خمر أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قال حدثني رجل قال كان الوليد بن يزيد إذا أصبح يوم الاثنين تغدى وشرب رطلين ثم جلس للناس قال فحدثني عمر الوادي قال دخلت عليه وعنده أصحابه وقد تغدى وهو يشرب فقال لي اشرب فشربت وطرب وغنى صوتا واحدا وأخذ دفافة فدفف بها فأخذ كل واحد منا دفافة فدفف بها وقام وقمنا حتى بلغنا إلى الحاجب فلما رآنا الحاجب صاح بالناس الحرم الحرم اخرجوا ودخل الحاجب فقال جعلني الله فداءك اليوم يحضر فيه الناس فقال له اجلس واشرب فقال إنما أنا حاجب فلا تحملني على الشراب فما شربته قط قال اجلس فاشرب فامتنع فما فارقناه حتى صببنا في حلقه بالقمع وقام وهو سكران أخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن شريك قال\nحدثنى عمي علي بن عمرو قرقارة قال حدثني أنيف بن هشام بن الكلبي ومات قبل أبيه قال حدثني أبي قال خرج الوليد بن يزيد من مقصورة له إلى مقصورة فإذا هو ببنت له معها حاضنتها فوثب عليها فافترعها فقالت له الحاضنة إنها المجوسية قال اسكتي ثم قال\n(من راقب الناس مات غما ... وفاز باللذة الجسور)\nوأحسب أنا أن هذا الخبر باطل لأن هذا الشعر لسلم الخاسر ولم يدرك زمن الوليد أخبرنا أحمد بن عبيد الله بن عمار قال حدثني عمر بن شبة قال حدثني إسحاق الموصلي قال أخبرني مسلمة بن سلم الكاتب قال قال الوليد بن يزيد وددت أن كل كأس تشرب من خمر بدينار وأن كل حر في جبهة أسد فلا يشرب إلا سخي ولا ينكح إلا شجاع أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قال سمعت رجلا يحدث أبي بالكوفة قال أرسلت إلى الوليد جفنة مملوءة قوارير فرعونية لم ير مثلها قط فلما أمسينا صببنا فيها الشراب في ليلة أربع عشرة حتى إذا استوى القمر على","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":20,"spl":"نوادر الوليد","loc":1278},
{"id":"b70-30","bab":"الجزء 7","sec":"نوادر الوليد","page":"ج7 ص69","text":"رؤوسنا وصار في الجفنة قال الوليد في أي منزلة القمر الليلة فقال بعضهم في الحمل وقال بعضهم في منزلة كذا وكذا من منازل القمر فقال بعض جلسائه القمر في الجفنة قال قاتلك الله أصبت ما في نفسي لتشربن الهفتجنة فقال مصعب فسأل أبي عن الهفتجنة فقال شرب كانت الفرس تشربه سبعة أسابيع فشرب تسعة وأربعين يوما أخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثني عبد الرحمن بن عبد الله الزهري عن عبد الله بن عمران بن أبي فروة قال أخبرني خالد صامة المغني وكان من أحسن الناس غناء على عود قال بعث إلي الوليد بن يزيد فقدمت عليه فوجدت عنده معبدا ومالكا والهذلي وعمر الوادي وأبا كامل فغنى القوم ونحن في مجلس يا له من مجلس وغلام للوليد يقال له سبرة يسقي القوم الطلاء إذ جاءت نوبة الغناء إلي فأخذت عودي فغنيت بأبيات قالها عروة بن أذينة يرثي أخاه بكرا\n(سرى همي وهم المرء يسري ... وغار النجم إلا قيد فتر)\n(أراقب في المجرة كل نجم ... تعرض في المجرة كيف يجري)\n(بحزن ما أزال له مديما ... كأن القلب أسعر حر جمر)\n(على بكر أخي ولى حميدا ... وأي العيش يحسن بعد بكر)\nناه ابن سريج ثاني ثقيل بالوسطى وغنى فيه ابن عباد الكاتب ولحنه رمل بالوسطى عن الهشامي قال خالد فقال لي الوليد أعد يا صام فأعدت فقال من يقوله ويحك قلت ابن أذينة قال هذا والله العيش الذي نحن فيه على رغم أنفه لقد تحجر واسعا قال عبد الرحمن بن عبد الله قال عبد الله بن أبي فروة وأنشدها ابن أذينة ابن أبي عتيق فضحك ابن أبي عتيق وقال كل العيش يحسن حتى الخبز والزيت فحلف ابن أذينة لا يكلمه أبدا فمات ابن أبي عتيق وابن أذينة مهاجر له أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال بلغني أن سكينة بنت الحسين رضى الله عنها أنشدت وأخبرني الحرمي قال حدثنا الزبير عن مصعب قال أنشدت سكينة وأخبرني الحسين بن يحيى عن عباد عن أبيه عن أبي يحيى العبادي إن سكينة أنشدت أبيات عروة بن أذينة في أخيه بكر فلما انتهت إلى قولة\n(على بكر أخي ولى حميدا ... وأي العيش يحسن بعد بكر)\nقالت سكينة ومن أخوه بكر أليس الدحداح الأسيد القصير الذي\nكان يمر بنا صباحا ومساء قالوا نعم قالت كل العيش والله يصلح ويحسن بعد بكر حتى الخبز والزيت أخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي عن إسحاق قال قدم سليمان بن عبد الملك المدينة فجمع المغنين وسبق بينهم ببدرة وقال أيكم كان أحسن غناء فهي له فاجتمعوا فبلغ الخبر ابن سريج فجاء وقد أغلق الباب فقال للحاجب استأذن لي قال لا يمكن وقد أغلق الباب ولو كنت جئت قبل أن يغلق الباب لاستأذنت لك قال فدعني أغن من شق الباب قال نعم فسكت حتى فرغ جميع المغنين من غنائهم ثم اندفع فغنى\n(سرى همي وهم المرء يسري ... )\nفنظر المغنون بعضهم إلى بعض وعرفوه فلما فرغ قال سليمان سليما أحسن والله هذا أحسن منكم غناء اخرج يا غلام إليه بالبدرة فأخرجها إليه أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني عن ابن جعدبة أن رجلا أهدى إلى هشام بن عبد الملك خيلا فكان فيها فرس مربوع قريب الركاب فعرف الوليد منه ما لم يعرف هشام فنهر الرجل وشتمه وقال أتجيء بمثل هذا إلى أمير المؤمنين ردوه عليه فردوه فلما\nخرج وجه إليه بثلاثين ألف درهم وأخذه منه فهو فرسه الذي يسميه السندي فأخبري بعض أصحابي أن الوليد خرج يوما يتصيد وحده فانتدب إليه مولى لهشام يريد الفتك به فلما بصر به الوليد حاوله فقهره بفرسه الذي كان تحته فقتله وقال في ذلك\n(ألم تر أني بين ما أنا آمن ... يخب بي السندي قفرا فيافيا)\n(تطلعت من غور فأبصرت فارسا ... فأوجست منه خيفة أن يرانيا)\n(ولما بدا لي أنما هو فارس ... وقفت له حتى أتى فرمانيا)\n(رماني ثلاثا ثم إني طعنته ... فرويت منه صعدتي وسنانيا)\nناه أبو كامل لحنا من الماخوري بالبنصر ولإبراهيم فيه ثقيل أول وقيل إن له فيه ماخوريا آخر وفيه لعمر الوادي ثاني ثقيل ولمالك رمل من رواية الهشامي قال وقال الوليد أيضا في فرسه السندي\n(قد أغتدي بذي سبيب هيكل ... مشرب مثل الغراب أرجل)\n(أعددته لحلبات الأحول ... وكل نقع ثائر لجحفل)\n(وكل خطب ذي شؤون معضل ... )","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":21,"spl":"نوادر الوليد","song":1,"loc":1279,"partialRef":{"sid":"b3-45","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b70-31","bab":"الجزء 7","sec":"نوادر الوليد","page":"ج7 ص69","text":"فقال هشام لكنا أعددنا له ما يسوءه نخلعه ونقصيه فيكون مهانا مدحورا مطرحا نسخت من كتاب أحمد بن أبي طاهر حدثني أبو الحسن العقيلي أن الوليد لما ولي الخلافة خطب سلمى التي كان ينسب بها فزوجها لما مضى صدر من خلافته فقامت عنده سبعة أيام فماتت فقال يرثيها\n(يا سلم كنت كجنة قد أطعمت ... أفنانها دان جناها موضع)\n(أربابها شفقا عليها نومهم ... تحليل موضعها ولما يهجعوا)\n(حتى إذا فسح الربيع ظنونهم ... نثر الخريف ثمارها فتصدعوا)","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":22,"spl":"نوادر الوليد — الوليد يأمر بقتل نديمه ثم يرثيه","loc":1280},
{"id":"b70-32","bab":"الجزء 7","sec":"الوليد يأمر بقتل نديمه ثم يرثيه","page":"ج7 ص77","text":"أخبرني علي بن سليمان الأخفش قال حدثنا أحمد بن يحيى ثعلب عن أبي العالية وأخبرني الحسن بن علي عن أحمد بن سعيد عن الزبير بن بكار عن عمه أن الوليد بن يزيد لما انهمك على شربه ولذاته ورفض الآخرة وراء ظهره وأقبل على القصف والعسف مع المغنين مثل مالك ومعبد وابن عائشة وذويهم كان نديمه القاسم بن الطويل العبادي وكان أديبا ظريفا شاعرا فكان لا يصبر عنه فغناه معبد ذات يوم شعر عدي\n(بكر العاذلون في وضح الصبح ... يقولون لي ألا تستفيق)\n(لست أدري وقد جفاني خليلي ... أعدو يلومني أم صديق)\n(ثم قالوا ألا اصبحونا فقامت ... قينة في يمينها إبريق)\n(قدمته على عقار كعين الديك ... صفى سلافها الراووق)\nفيه لمعبد ثقيل ويقال إنه لحنين وفيه لمالك خفيف رمل وفيه لعبد الله بن العباس رمل كل ذلك عن الهشامي قال فاستحسنه الوليد وأجب به وطرب عليه وجعل يشرب إلى أن غلب عليه السكر فنام في موضعه فانصرف ابن الطويل فلما أفاق الوليد سأل عنه فعرف حين انصرافه فغضب وقال وهو سكران لغلام كان واقفا على رأسه يقال له سبرة ائتني برأسه فمضى الغلام حتى ضرب عنقه وأتاه برأسه فجعله في طست بين يديه فلما رآه أنكره وسأل عن الخبر فعرفه فاسترجع وندم على ما فرط منه وجعل يقلب الرأس بيده ثم قال يرثيه\n(عيني للحدث الجليل ... جودا بأربعة همول)\n(جودا بدمع إنه ... يشفي الفؤاد من الغليل)\n(لله قبر ضمنت ... فيه عظام ابن الطويل)\n(ماذا تضمن إذ ثوى ... فيه من اللب الأصيل)\n(قد كنت آوي من هواك ... إلى ذرى كهف ظليل)\n(أصبحت بعدك واحدا ... فردا بمدرجة السيول)\nغناه الغريض ثاني ثقيل بالوسطى عن عمرو وغنى فيه سليم لحنا من الثقيل الأول بالبنصر عن الهشامي وذكر غيره أن لحن الغريض لدحمان\nوذكر حبش أنه لأبي كامل وذكر غيره أن لحن الغريض لدحمان قال ثم دخل إلى جواريه فقال والله ما أبالي متى جاءني الموت بعد الخليل ابن الطويل فيقال إنه لم يعش بعده إلا مديدة حتى قتل والله أعلم أخبرني الحسين بن يحيى عن حماد عن أبيه قال روى الهيثم بن عدي عن ابن عياش عن حماد الراوية قال دعاني الوليد يوما من الأيام في السحر والقمر طالع وعنده جماعة من ندمائه وقد اصطبح فقال أنشدني في النسيب فأنشدته أشعارا كثيرة فلم يهش لشيء منها حتى أنشدته قول عمار ذي كناز\n(اصبح القوم قهوة ... في الأباريق تحتذى)\n(من كميت مدامة ... حبذا تلك حبذا)\nفطرب ثم رفع رأسه إلى خادم وكان قائما كأنه الشمس فأومأ إليه فكشف سترا خلف ظهره فطلع منه أربعون وصيفا ووصيفة كأنهم اللؤلؤ المنثور في أيديهم الأباريق والمناديل فقال أسقوهم فما بقي أحد إلا أسقي وأنا في خلال ذلك أنشده الشعر فما زال يشرب ويسقي إلى طلوع الفجرثم لم نخرج عن حضرته حتى حملنا الفراشون في البسط فألقونا في دار الضيافة فما أفقنا حتى طلعت الشمس قال حماد ثم أحضرني فخلع علي خلعا من فاخر ثيابه وأمر لي بعشرة آلاف درهم وحملني على فرس","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":22,"spl":"نوادر الوليد — الوليد يأمر بقتل نديمه ثم يرثيه","song":2,"loc":1281},
{"id":"b70-33","bab":"الجزء 7","sec":"تأتيه الأخبار فيرد شعرا","page":"ج7 ص80","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني عن أبي بكر الهذلي قال كان بين الحكم بن الزبير أخي أبي بكر بن كلاب وبين بكر بن نوفل أحد بني جعفر بن كلاب شيء في وكالة للوليد بن يزيد يخاصم الجعفري في الرحبة من أرض دمشق وكان الجعفري قد استولى عليها فقطع شفره الأعلى فاستعدى عليه هشاما فلم يعده فقال الوليد في ذلك\n(أيا حكم المتبول لو كنت تعتزي ... إلى أسرة ليسوا بسود زعانف)\n(لأيقنت قد أدركت وترك عنوة ... بلا حكم قاض بل بضرب السوالف)\nغناه الهذلي ثقيلا أول عن الهشامي ويونس قال فلما استخلف الوليد بعث إلى بكر بن نوفل الجعفري فقال ألا تعطي حكم بن الزبير حقه قال لا فأمر به فشترت عينه ثم قال\n(يا رب أمر ذي شؤون جحفل ... قاسيت فيه جلبات الأحول)\nأخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني قال خرج الوليد إلى متصيد له فأقام به ومات له ابن يقال له مؤمن بن الوليد فلم يقدر أحد أن ينعاه إليه حتى ثمل فنعاه إليه سنان الكاتب وكان\nمغنيا فقال الوليد وفي هذا الشعر غناء من الأصوات التي اختيرت للواثق والرشيد قبله","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":23,"spl":"تأتيه الأخبار فيرد شعرا","song":2,"loc":1282},
{"id":"b70-34","bab":"الجزء 7","sec":"من المائة المختارة من رواية علي بن يحيى","page":"ج7 ص81","text":"(أتاني سنان بالوداع لمؤمن ... فقلت له إني إلى الله راجع)\n(ألا أيها الحاثي عليه ترابه ... هبلت وشلت من يديك الأصابع)\n(يقولون لا تجزع وأظهر جلادة ... فكيف بما تحنى عليه الأضالع)\nروضه من الطويل غناه سنان الكاتب ولحنه المختار من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه لأبي كامل خفيف ثقيل أول بالوسطى عن عمرو وقيل إن فيه لحنا لعبد الله ابن يونس صاحب أيلة أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني عقيل ابن عمرو قال قال يزيد بن أبي مساحق السلمي مؤدب الوليد شعرا وبعث به إلى النوار جارية الوليد فغنته به وهو\n(مضى الخلفاء بالأمر الحميد ... وأصبحت المذمة للوليد)\n(تشاغل عن رعيته بلهو ... وخالف فعل ذي الرأي الرشيد)\nفكتب اليه الوليد\n(ليت حظي اليوم من كل ... معاش لي وزاد)\n(قهوة أبذل فيها ... طارفي ثم تلادي)\n(فيظل القلب منها ... هائما في كل واد)\n(إن في ذاك صلاحي ... وفلاحي ورشادي)\nخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إبراهيم ابن الوليد الحمصي قال حدثنا هارون بن الحسن العنبري قال قال الوليد بن يزيد يا بني أمية إياكم والغناء فإنه ينقص الحياء ويزيد في الشهوة ويهدم المروءة ويثور على الخمر ويفعل ما يفعل السكر فإن كنتم لا بد فاعلين فجنبوه النساء فإن الغناء رقية الزنا وإني لأقول ذلك فيه على أنه أحب إلي من كل لذة وأشهى إلي من الماء البارد إلى ذي الغلة ولكن الحق أحق أن يقال أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني قال حدثني بعض موالي الوليد قال دخلت إليه وقد عقد لابنيه بعده وقدم عثمان فقلت له يا أمير المؤمنين أقول قول الموثوق بنصيحته أو يسعني السكوت قال بل قل قول الموثوق به فقلت إن الناس قد أنكروا ما فعلت وقالوا يبايع لمن لم يحتلم وقد سمعت ما أكره فيك فقال عضوا ببظور أمهاتكم أفأدخل بيني وبين ابني غيري فيلقى منه كما لقيت من الأحول بعد أبي ثم أنشأ يقول\n\n(سرى طيف ذا الظبي بالعاقدان ... ليلا فهيج قلبا عميدا)\n(وأرق عيني على غرة ... فباتت بحزن تقاسي السهودا)\n(نؤمل عثمان بعد الوليد ... للعهد فينا ونرجو سعيدا)\n(كما كان إذ كان في دهره ... يزيد يرجي لتلك الوليدا)\n(على أنها شسعت شسعة ... فنحن نرجي لها أن تعودا)\n(فإن هي عادت فعاص القريب ... منها لتؤيس منها البعيدا)\nغناه أبو كامل ثاني ثقيل بالبنصر من أصوات قليلة الأشباه وذكر عمرو ابن بانة أن فيه لعمر الوادي لحنا من الماخوري بالوسطى وذكر الهشامي أن فيه خفيف رمل لحكم وذكرت دنانير عن حكم أنه لعمر الوادي وذكر حبش أن الثقيل الثاني لمالك وأن فيه لفضل النجار رملا بالبنصر أخبرني الحسن ابن علي قال حدثنا أحمد بن سعيد عن الزبير بن بكار قال هو\n(سرى طيف ظبي بأعلى الغوير ... )\nولكن هذا تصحيف سليمان السوادي أو قال خليد أخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني إسحاق قال كان الوليد قد بايع لابنيه الحكم وعثمان وهو أول من بايع لابن سرية\nأمة ولم يكونوا يفعلون ذلك وأخذهما يزيد بن الوليد الناقص فحبسهما ثم قتلهما وفيهما يقول ابن أبي عقب\n(إذا قتل الخلف المديم لسكره ... بقفر من البخراء أسس في الرمل)\n(وسيق بلا جرم إلى الحتف والردى ... بنياه حتى يذبحا مذبح السخل)\n(فويل بني مروان ماذا أصابهم ... بأيدي بني العباس بالأسر والقتل)\nخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي قال حدثني أبي عن العلاء البندار قال كان الوليد زنديقا وكان رجل من كلب يقول بمقالته مقالة الثنوية فدخلت على الوليد يوما وذلك الكلبي عنده وإذا بينهما سفط قد رفع رأسه عنه فإذا ما يبدو لي منه حرير أخضر فقال ادن يا علاء فدنوت فرفع الحريرة فإذا في السفط صورة إنسان وإذا الزئبق والنوشادر قد جعلا في جفنه فجفنه يطرف كأنه يتحرك فقال يا علاء هذا ماني لم يبتعث الله نبيا قبله ولا يبتعث نبيا بعده فقلت يا أمير المؤمنين اتق الله ولا يغرنك هذا الذي ترى عن دينك فقال له الكلبي يا أمير المؤمنين ألم أقل لك إن العلاء لا يحتمل هذا الحديث قال العلاء ومكثت أياما ثم جلست مع الوليد على بناء كان بناه في عسكره يشرف به والكلبي عنده إذ نزل من عنده","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":24,"spl":"من المائة المختارة من رواية علي بن يحيى","song":1,"loc":1283,"partial":1},
{"id":"b70-36","bab":"الجزء 7","sec":"من المائة المختارة من رواية علي بن يحيى — مقتل الوليد","page":"ج7 ص81 – ج7 ص85","text":"وقد كان الوليد حمله على برذون هملاج أشقر من أفره ما سخر فخرج على برذونه ذلك فمضى به في الصحراء حتى غاب عن العسكر فما شعر إلا وأعراب قد جاؤوا به يحملونه منفسخة عنقه ميتا وبرذونه يقاد حتى أسلموه فبلغني ذلك فخرجت متعمدا حتى أتيت أولئك الأعراب وقد كانت لهم أبيات بالقرب منه في أرض البخراء لا حجر فيها ولا مدر فقلت لهم كيف كانت قصة هذا الرجل قالوا أقبل علينا على برذون فوالله لكأنه دهن يسيل على صفاة من فراهته فعجبنا لذلك إذ انقض رجل من السماء عليه ثياب بيض فأخذ بضبعيه فاحتمله ثم نكسه وضرب برأسه الأرض فدق عنقه ثم غاب عن عيوننا فاحتملناه فجئنا به\nوأخبرني الحسن بن علي قال حدثنا الخراز عن المدائني قال لما أكثر الوليد بن يزيد التهتك وانهمك في اللذات وشرب الخمر وبسط المكروه على ولد هشام والوليد وأفرط في أمره وغيه مل الناس أيامه وكرهوه وكان قد عقد لابنيه بعده ولم يكونا بلغا فمشى الناس بعضهم إلى بعض في خلعه وكان أقواهم في ذلك يزيد الناقص بن الوليد بن عبد الملك بن مروان فمشى إلى أخيه العباس وكان امرأ صدق ولم يكن في بني أمية مثله كان يتشبه بعمر بن عبد العزيز فشكا إليه ما يجري على الناس من\nالوليد فقال له يا أخي إن الناس قد ملوا بني مروان وإن مشى بعضكم في أمر بعض أكلتم ولله أجل لا بد أن يبلغه فانتظره فخرج من عنده ومشى إلى غيره فبايعه جماعة من اليمانية الوجوه فعاد إلى أخيه ومعه مولى له وأعاد عليه القول وعرض له بأنه قد دعي إلى الخلافة فقال له والله لولا أني لا آمنه عليك من تحامله لوجهت بك إليه مشدودا فنشدتك الله ألا تسعى في شيء من هذا فانصرف من عنده وجعل يدعو الناس إلى نفسه وبلغ الوليد ذلك فقال يذكر قومه ومشي بعضهم إلى بعض في خلعه\n(سل هم النفس عنها ... بعلنداة علاة)\n(تتقي الأرض وتهوي ... بخفاف مدمجات)\n(ذاك أم ما بال قومي ... كسروا سن قناتي)\n(واستخفوا بي وصاروا ... كقرود خاسئات)\nلشعر للوليد بن يزيد بن عبد الملك والغناء لأبي كامل غزيل الدمشقي ماخوري بالبنصر وفي هذه القصيدة يقول الوليد بن يزيد\n(أصبح اليوم وليد ... هائما بالفتيات)\n(عنده راح وإبريق ... وكأس بالفلاة)\n(ابعثوا خيلا لخيل ... ورماة لرماة)\nأخبرني بالسبب في مقتله الحسن بن علي قال أخبرنا أحمد بن\nالحارث قال حدثني المدائني عن جويرية بن أسماء وأخبرني به ابن أبي الأزهر عن حماد عن أبيه عن المدائني عن جويرية بن أسماء قال قال ابن بشر بن الوليد بن عبد الملك لما أظهر الوليد بن يزيد أمره وأدمن على اللهو والصيد واحتجب عن الناس ووالى بين الشرب وانهمك في اللذات سئمه الناس ووعظه من أشفق عليه من أهله فلما لم يقلع دبوا في خلعه فدخل أبي بشر بن الوليد على عمي العباس بن الوليد وأنا معه فجعل يكلم عمي في أن يخلع الوليد بن يزيد ومعه عمي يزيد بن الوليد فكان العباس ينهاه وأبي يرد عليه فكنت أفرح وأقول في نفسي أرى أبي يجترىء أن يكلم عمي ويرد عليه فقال العباس يا بني مروان أظن أن الله قد أذن في هلاككم ثم قال العباس\n(إني أعيذكم بالله من فتن ... مثل الجبال تسامى ثم تندفع)\n(إن البرية قد ملت سياستكم ... فاستمسكوا بعمود الدين وارتدعوا)\n(لا تلحمن ذئاب الناس أنفسكم ... إن الذئاب إذا ما ألحمت رتعوا)\n(لا تبقرن بأيديكم بطونكم ... فثم لا فدية تغني ولا جزع)\nال المدائني عن رجاله فلما استجمع ليزيد أمره وهو متبد أقبل إلى دمشق وبين مكانه الذي كان متبديا فيه وبين دمشق أربع ليال فأقبل إلى دمشق متنكرا في سبعة أنفس على حمر وقد بايع له أكثر أهل دمشق وبايع له أكثر أهل المزة فقال مولى لعباد بن زياد إني لبجرود وبين جرود","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":25,"spl":"من المائة المختارة من رواية علي بن يحيى — مقتل الوليد","song":1,"loc":1284},
{"id":"b70-37","bab":"الجزء 7","sec":"مقتل الوليد","page":"ج7 ص85","text":"ودمشق مرحلة إذ طلع علينا سبعة معتمون على حمر فنزلوا وفيهم رجل طويل جسيم فرمى بنفسه فنام وألقوا عليه ثوبا وقالوا لي هل عندك شيء نشتريه من طعام فقلت أما بيع فلا وعندي من قراكم ما يشبعكم فقالوا فعجله فذبحت له دجاجا وفراخا وأتيتهم بما حضر من عسل وسمن وشوانيز وقلت أيقظوا صاحبكم للغداء فقالوا هو محموم لا يأكل فسفروا للغداء فعرفت بعضهم وسفر النائم فإذا هو يزيد بن الوليد فعرفته فلم يكلمني ومضوا ليدخلوا دمشق ليلا في نفر من أصحابه مشاة إلى معاوية ابن مصاد وهو بالمزة وبينها وبين دمشق ميل فأصابهم مطر شديد فأتوا منزل معاوية فضربوا بابه وقالوا يزيد بن الوليد فقال له معاوية الفراش ادخل أصلحك الله قال في رجلي طين وأكره أن أفسد عليك بساطك فقال ما تريدني عليه أفسد فمشى على البساط وجلس على الفراش ثم كلم معاوية فبايعه وخرج إلى دمشق فنزل دار ثابت بن سليمان الحسني مستخفيا وعلى دمشق عبد الملك بن محمد بن الحجاج بن يوسف فخاف عبد الملك الوباء فخرج فنزل قطنا واستخلف ابنه على دمشق وعلى شرطته أبو العاج كثير بن عبد الله السلمي وتم ليزيد أمره فأجمع على الظهور وقيل لعامل دمشق إن يزيد خارج فلم يصدق وأرسل يزيد إلى أصحابه بين المغرب والعشاء في ليلة الجمعة من جمادى الآخرة سنة سبع وعشرين ومائة فكمنوا في ميضأة عند باب الفراديس حتى إذا أذنوا\nالعتمة دخلوا المسجد مع الناس فصلوا وللمسجد حرس قد وكلوا بإخراج الناس من المسجد بالليل فإذا خرج الناس خرج الحرس وأغلق صاحب المسجد الأبواب ودخل الدار من باب المقصورة فيدفع المفاتيح إلى من يحفظها ويخرج فلما صلى الناس العتمة صاح الحرس بالناس فخرجوا وتباطأ أصحاب يزيد الناقص فجعلوا يخرجونهم من باب ويدخلون من باب حتى لم يبق في المسجد إلى الحرس وأصحاب يزيد فأخذوا الحرس ومضى يزيد بن عنبسة السكسكي إلى يزيد فأخبره وأخذ بيده وقال قم يا أمير المؤمنين وأبشر بعون الله ونصره فأقبل وأقبلنا ونحن اثنا عشر رجلا فلما كنا عند سوق القمح لقيهم فيها مائتا رجل من أصحابهم فمضوا حتى دخلوا المسجد وأتوا باب المقصورة وقالوا نحن رسل الوليد ففتح لهم خادم الباب ودخلوا فأخذوا الخادم وإذا أبو العاج سكران فأخذوه وأخذوا خزان البيت وصاحب البريد وأرسل إلى كل من كان يحذره فأخذه وأرسل من ليلته إلى محمد بن عبيدة مولى سعيد بن العاص وهو على بعلبك وإلى عبد الملك بن محمد بن الحجاج فأخذهما وبعث أصحابه إلى الخشبية فأتوه وقال للبوابين لا تفتحوا الأبواب غدوة إلا لمن أخبركم بشعار كذا وكذا قال فتركوا الأبواب في السلاسل وكان في المسجد سلاح كثير قدم به سليمان بن هشام من الجزيرة فلم يكن الخزان قبضوه فأصابوا سلاحا\nكثيرا فأخذوه وأصبحوا وجاء أهل المزة مع حريث بن أبي الجهم فما انتصف النهار حتى بايع الناس يزيد وهو يتمثل قول النابغة\n(إذا استنزلوا عنهن للطعن أرقلوا ... إلى الموت إرقال الجمال المصاعب)\nفجعل أصحابه يتعجبون ويقولون انظروا إلى هذا كان قبيل الصبح يسبح وهو الآن ينشد الشعر قال وأمر يزيد عبد العزيز بن الحجاج بن عبد الملك بن مروان فوقف بباب الجابية فنادى من كان له عطاء فليأت إلى عطائه ومن لم يكن له عطاء فله ألف درهم معونة فبايع له الناس وأمر بالعطاء قال وندب يزيد بن الوليد الناس إلى قتال الوليد بن يزيد مع عبد العزيز وقال من انتدب معه فله ألفان فانتدب ألفا رجل فأعطاهم وقال موعدكم ذنبة فوافى ذنبه ألف ومائتا رجل فقال ميعادكم مصنعة بالبرية وهي لبني عبد العزيز بن الوليد فوافاه ثمانمائة رجل فسار فوافاهم ثقل الوليد فأخذوه ومع عبد العزيز فرسان منهم منصور بن جمهور ويعقوب بن عبد الرحمن السلمي والأصبغ بن ذؤالة وشبيب بن أبي مالك الغساني وحميد بن نصر اللخمي فأقبلوا فنزلوا قريبا من الوليد فقال الوليد أخرجوا لي سريرا فأخرجوه فصعد عليه وأتاه خبر العباس بن الوليد إني أجيئك وأتي الوليد بفرسين الذائد والسندي وقال أعلي يتواثب الرجال وأنا أثب على الأسد","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":26,"spl":"مقتل الوليد","loc":1285},
{"id":"b70-38","bab":"الجزء 7","sec":"مقتل الوليد","page":"ج7 ص85","text":"وأتخصر الأفاعي وهم ينتظرون العباس أن يأتيهم ولم يكن بينهم كبير قتال فقتل عثمان الخشبي وكان من أولاد الخشبية الذين كانوا مع المختار وبلغ عبد العزيز بن الحجاج أن العباس بن الوليد يأتي الوليد فأرسل منصور بن جمهور في جريدة خيل وقال إنكم تلقون العباس بن الوليد ومعه بنوه في الشعب فخذوه وخرج منصور في تلك الخيل وتقدموا إلى الشعب وإذا العباس ومعه ثلاثون تقدموا أصحابه فقال له اعدل إلى عبد العزيز فشتمهم فقال له منصور والله لئن تقدمت لأنفذن حصينك بالرمح فقال إنا لله فأقبلوا به يسوقونه إلى عبد العزيز فقال له عبد العزيز بايع ليزيد فبايع ووقف ونصبوا راية وقالوا هذا العباس قد بايع ونادى منادي عبد العزيز من لحق بالعباس بن الوليد فهو آمن فقال العباس إنا لله خدعة من خدع الشيطان هلك والله بنو مروان فتفرق الناس عن الوليد وأتوا العباس وظاهر الوليد في درعين وقاتلهم وقال الوليد من جاء برأس فله خمسمائة درهم فجاء جماعة بعدة رؤوس فقال اكتبوا أسماءهم فقال له رجل من مواليه ليس هذا يا أمير المؤمنين يوما يعامل فيه\nبالنسيئة وناداهم رجال اقتلوا اللوطي قتلة قوم لوط فرموه بالحجارة فلما سمع ذلك دخل القصر وأغلق الباب وقال صوت دعوا لي سليمى والطلاء وقينة ... وكأسا ألا حسبي بذلك مالا إذا ما صفا عيش برملة عالج ... وعانقت سلمى لا أريد بدالا خذوا ملككم لا ثبت الله ملككم ... ثباتا يساوي ما حييت عقالا وخلوا عناني قبل عير وما جرى ... ولا تحسدوني أن أموت هزالا\nغناه عمر الوادي رملا بالوسطى عن حبش ثم قال لعمر الوادي يا جامع لذتي غنني بهذا الشعر وقد أحاط الجند بالقصر فقال لهم الوليد من وراء الباب أما فيكم رجل شريف له حسب وحياء أكلمه فقال له يزيد ابن عنبسة السكسكي كلمني فقال له الوليد يا أخا السكاسك ما تنقمون مني ألم أزد في أعطياتكم وأعطية فقرائكم وأخدمت زمناكم ودفعت عنكم المؤن فقال ما ننقم عليك في أنفسنا شيئا ولكن ننقم عليك انتهاك ما حرم الله وشرب الخمور ونكاح أمهات أولاد أبيك واستخفافك بأمر الله قال حسبك يا أخا السكاسك فلعمري لقد أغرقت فأكثرت وإن فيما\nأحل الله لسعة عما ذكرت ورجع إلى الدار فجلس وأخذ المصحف وقال يوم كيوم عثمان ونشر المصحف يقرأ فعلوا الحائط فكان أول من علا الحائط يزيد بن عنبسة فنزل وسيف الوليد إلى جنبه فقال له يزيد نح سيفك فقال الوليد لو أردت السيف لكانت لي ولك حالة غير هذه فأخذ بيده وهو يريد أن يدخله بيتا ويؤامر فيه فنزل من الحائط عشرة فيهم منصور ابن جمهور وعبد الرحمن وقيس مولى يزيد بن عبد الملك والسري بن زياد بن أبي كبشة فضربه عبد الرحمن السلمي على رأسه ضربة وضربه السري بن زياد على وجهه وجروه بين خمسة ليخرجوه فصاحت امرأه كانت معه في الدار فكفوا عنه فلم يخرجوه واحتز رأسه أبو علاقة القضاعي وخاط الضربة التي في وجهه بالعقب وقدم بالرأس على يزيد قدم به روح بن مقبل وقال أبشر يا أمير المؤمنين بقتل الفاسق فاستتم الأمر له وأحسن صلته ثم كان من خلع يزيد بعد ذلك ما ليس هذا موضع ذكره قال ولما قتل الوليد بن يزيد جعل أبو محجن مولى خالد القسري يدخل سيفه في است الوليد وهو مقتول فقال الأصبغ بن ذؤالة الكلبي في قتل الوليد وأخذهم ابنيه\n(من مبلغ قيسا وخندف كلها ... وساداتهم من عبد شمس وهاشم)\n(قتلنا أمير المؤمنين بخالد ... وبعنا وليي عهده بالدراهم)\nوقال أبو محجن مولى خالد\n(لو شاهدوا حد سيفي حين أدخله ... في است الوليد لماتوا عنده كمدا)\nخبرني الحسين بن يحيى عن حماد عن أبيه عن هشام بن الكلبي عن جرير قال قال لي عمر الوادي كنت أغني الوليد أقول\n(كذبتك نفسك أم رأيت بواسط ... غلس الظلام من الرباب خيالا)\nقال فما أتممت الصوت حتى رأيت رأسه قد فارق بدنه ورأيته يتشحط في دمه يقال إن اللحن في هذا الشعر لعمر الوادي ويقال لابن جامع قالوا وكان عثمان والحكم ابنا الوليد قد بايعهما بالعهد بعده فتغيبا فأخذهما يزيد بعد ذلك فحبسهما في الخضراء ودخل عليهما يزيد الأفقم ابن هشام فجعل يشتم أباهما الوليد وكان قد ضربه وحلقه فبكى الحكم فقال عثمان أخوه اسكت يا أخي وأقبل على يزيد فقال أتشتم أبي قال نعم قال لكني لا أشتم عمي هشاما ووالله لو كنت من بني مروان ما شتمت أحدا منهم فانظر إلى وجهك فإن كنت رأيت حكميا يشبهك أوله","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":27,"spl":"مقتل الوليد","song":1,"loc":1286},
{"id":"b70-39","bab":"الجزء 7","sec":"مقتل الوليد","page":"ج7 ص85","text":"مثل وجهك فأنت منهم لا والله ما في الأرض حكمي يشبهك أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني عن مسلمة بن محارب قال لما قتل الوليد قال أيوب السختياني ليت القوم تركوا لنا خليفتنا لم يقتلوه قال وإنما قال ذلك تخوفا من الفتنة","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":28,"spl":"مقتل الوليد — الرشيد يلعن قاتلي الوليد — من المائة المختارة","loc":1287},
{"id":"b70-41","bab":"الجزء 7","sec":"الرشيد يلعن قاتلي الوليد — من المائة المختارة","page":"ج7 ص95 – ج7 ص96","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني أن ابنا للغمر بن يزيد بن عبد الملك دخل على الرشيد فقال ممن أنت قال من قريش قال من أيها فأمسك قال قل وأنت آمن ولو أنك مرواني قال أنا ابن الغمر بن يزيد قال رحم الله عمك ولعن يزيد الناقص وقتلة عمك جميعا فإنهم قتلوا خليفة مجمعا عليه ارفع إلي حوائجك فقضاها\nأخبرني محمد بن يحيى الصولي قال حدثنا الغلابي قال حدثنا العلاء ابن سويد المنقري قال ذكر ليلة المهدي أمير المؤمنين الوليد بن يزيد فقال كان ظريفا أديبا فقال له شبيب بن شيبة يا أمير المؤمنين إن رأيت ألا تجري ذكره على سمعك ولسانك فافعل فإنه كان زنديقا فقال اسكت فما كان الله ليضع خلافته عند من يكفر به وهكذا رواه الصولي وقد أخبرنا به أحمد بن عبد العزيز إجازة قال حدثنا عمر بن شبة قال أخبرنا عقيل بن عمرو قال أخبرني شبيب بن شيبة عن أبيه قال كنا جلوسا عند المهدي فذكروا الوليد بن يزيد فقال المهدي أحسبه كان زنديقا فقام ابن علاثة الفقيه فقال يا أمير المؤمنين الله عز و جل أعظم من أن يولي خلافة النبوة وأمر الأمة من لا يؤمن بالله لقد أخبرني من كان يشهده في ملاعبه وشربه عنه بمروءة في طهارته وصلاته وحدثني أنه كان إذا حضرت الصلاة يطرح ثيابا كانت عليه من مطيبة ومصبغة ثم يتوضأ فيحسن الوضوء ويؤتى بثياب بيض نظاف من ثياب الخلافة فيصلي فيها أحسن صلاة بأحسن قراءة وأحسن سكوت وسكون وركوع وسجود فإذا فرغ عاد إلى تلك الثياب التي كانت عليه قبل ذلك ثم يعود إلى شربه ولهوه أفهذه أفعال من لا يؤمن بالله فقال له المهدي صدقت بارك الله عليك يابن علاثة وفي جملة المائة الصوت المختارة عدة أصوات من شعر الوليد نذكرها ها هنا مع أخباره والله أعلم\n(أم سلام ما ذكرتك إلا ... شرقت بالدموع مني المآقي)\n(أم سلام ذكركم حيث كنتم ... أنت دائي وفي لسانك راقي)\n(ما لقلبي يجول بين التراقي ... مستخفا يتوق كل متاق)\n(حذرا أن تبين دار سليمى ... أو يصيح الداعي لها بفراق)\nناه عمر الوادي ولحنه المختار خفيف رمل مطلق في مجرى البنصر وذكر عمرو بن بانة أن لسلامة القس فيه خفيف رمل بالوسطى ولعله بمعنى هذا ومن الناس من يروي هذه الأبيات لعبد الرحمن بن أبي عمار الجشمي في سلامة القس وليس ذلك له هو للوليد صحيح وهو كثيرا ما يذكر سلمى هذه في شعره بأم سلام وبسلمى لأنه لم يكن يتصنع في شعره ولا يبالي بما يقوله منه ومن ذلك قوله فيها\n(أم سلام لو لقيت من الوجد ... عشير الذي لقيت كفاك)\n(فأثيبي بالوصل صبا عميدا ... وشفيقا شجاه ما قد شجاك)\nغناه مالك خفيف رمل بالبنصر عن الهشامي","topic":"أخبار الوليد بن يزيد ونسبه","topicNo":70,"sp":28,"spl":"مقتل الوليد — الرشيد يلعن قاتلي الوليد — من المائة المختارة","song":2,"loc":1288},
{"id":"b71-1","bab":"الجزء 7","sec":"ذكر أخبار عمر الوادي ونسبه","page":"ج7 ص98","text":"هو عمر بن داود بن زاذان وجده زاذان مولى عمرو بن عثمان بن عفان وكان عمر مهندسا وأخذ الغناء عنه حكم وذووه من أهل وادي القرى وكان قدم إلى الحرم فأخذ من غناء أهله فحذق وصنع فأجاد وأتقن وكان طيب الصوت شجيه مطربا وكان أول من غنى من أهل وادي القرى واتصل بالوليد بن يزيد في أيام إمارته فتقدم عنده جدا وكان يسميه جامع لذاتي ومحيي طربي وقتل الوليد وهو يغنيه وكان آخر عهده به من الناس وفي عمر يقول الوليد بن يزيد وفيه غناء\n(إنني فكرت في عمر ... حين قال القول فاختلجا)\n(إنه للمستنير به ... قمر قد طمس السرجا)\n(ويغني الشعر ينظمه ... سيد القوم الذي فلجا)\n(أكمل الوادي صنعته ... في لباب الشعر فاندمجا)\nالشعر للوليد بن يزيد والغناء لعمر الوادي هزج خفيف بالبنصر في مجراها\nأخبرني الحسين بن يحيى ومحمد بن مزيد قالا حدثنا حماد بن إسحاق عن أبيه قال كان عمر الوادي يجتمع مع معبد ومالك وغيرهما من المغنين عند الوليد ابن يزيد فلا يمنعه حضورهم من تقديمه والإصغاء إليه والإختصاص له وبلغني أنه كان لا يضرب وإنما كان مرتجلا وكان الوليد يسميه جامع لذاتي قال وبلغني أن حكما الوادي وغيره من مغني وادي القرى أخذوا عنه الغناء وانتحلوا أكثر أغانيه قال إسحاق وحدثني عبد السلام الربيع إن الوليد بن يزيد كان يوما جالسا وعنده عمر الوادي وأبو رقية وكان ضعيف العقل وكان يمسك المصحف على أم الوليد فقال الوليد لعمر الوادي وقد غناه صوتا أحسنت والله أنت جامع لذاتي وأبو رقية مضطجع وهم يحسبونه نائما فرفع رأسه إلى الوليد فقال له وأنا جامع لذات أمك فغضب الوليد وهم به فقال له عمر الوادي جعلني الله فداك ما يعقل أبو رقية وهو صاح فكيف يعقل وهو سكران فأمسك عنه","topic":"ذكر أخبار عمر الوادي ونسبه","topicNo":71,"sp":0,"spl":"ذكر أخبار عمر الوادي ونسبه — عمر يأخذ الغناء عن راع ويمدحه","song":1,"loc":1289},
{"id":"b71-2","bab":"الجزء 7","sec":"عمر يأخذ الغناء عن راع ويمدحه","page":"ج7 ص99","text":"قال إسحاق وحدثت عن عمر الوادي قال بينا أنا أسير ليلة بين العرج والسقيا سمعت إنسانا يغني غناء لم أسمع قط أحسن منه وهو\n(وكنت إذا ما جئت سعدى بأرضها ... أرى الأرض تطوى لي ويدنو بعيدها)\n(من الخفرات البيض ود جليسها ... إذا ما انقضت أحدوثة لو تعيدها)\nفكدت أسقط عن راحلتي طربا فقلت والله لألتمسن الوصول إلى هذا الصوت ولو بذهاب عضو من أعضائي حتى هبطت من الشرف فإذا أنا برجل يرعى غنما وإذا هو صاحب الصوت فأعلمته الذي أقصدني إليه وسألته إعادته علي فقال والله لو كان عندي قرى ما فعلت ولكني أجعله قراك فربما ترنمت به وأنا جائع فأشبع وكسلان فأنشط ومستوحش فآنس فأعاده علي مرارا حتى أخذته فوالله ما كان لي كلام غيره حتى دخلت المدينة ولقد وجدته كما قال حدثني بهذا الخبر الحرمي بن أبي العلاء قال حدثني الزبير ابن بكار قال حدثني المؤمل بن طالوت الوادي قال حدثني مكين العذري قال سمعت عمر الوادي يقول بينا أنا أسير بين الروحاء والعرج ثم ذكر مثله وقال فيه فربما ترنمت به وأنا غرثان فيشبعني ومستوحش فيؤنسني وكسلان فينشطني قال فما كان زادي حتى ولجت المدينة غيره وجربت ما وصفه الراعي فيه فوجدته كما قال","topic":"ذكر أخبار عمر الوادي ونسبه","topicNo":71,"sp":0,"spl":"ذكر أخبار عمر الوادي ونسبه — عمر يأخذ الغناء عن راع ويمدحه","song":1,"loc":1290},
{"id":"b71-3","bab":"الجزء 7","sec":"نسبة هذا الصوت","page":"ج7 ص100","text":"\n(لقد هجرت سعدى وطال صدودها ... وعاود عيني دمعها وسهودها)\n(وكنت إذا ما زرت سعدى بأرضها ... أرى الأرض تطوى لي ويدنو بعيدها)\n(منعمة لم تلق بؤس معيشة ... هي الخلد في الدنيا لمن يستفيدها)\n(هي الخلد ما دامت لأهلك جارة ... وهل دام في الدنيا لنفس خلودها)\nلشعر لكثير والغناء لابن محرز ثقيل أول مطلق بالبنصر عن يحيى المكي وذكر الهشامي أن فيه ليزيد حوراء ثاني ثقيل وفيه خفيف رمل ينسب إلى عمر الوادي وهو بعض هذا اللحن الذي حكاه عن الراعي ولا أعلم لمن هو وهذه الأبيات من قصيدة لكثير سائرها في الغزل وهي من جيد غزله ومختاره وتمام الأبيات بعد ما مضى منها\n(فتلك التي أصفيتها بمودتي ... وليدا ولما يستبن لي نهودها)\n(وقد قتلت نفسا بغير جريرة ... وليس لها عقل ولا من يقيدها)\n(فكيف يود القلب من لا يوده ... بلى قد تريد النفس من لا يريدها)\n(ألا ليت شعري بعدنا هل تغيرت ... عن العهد أم أمست كعهدي عهودها)\n(إذا ذكرتها النفس جنت بذكرها ... وريعت وحنت واستخف جليدها)\n(فلو كان ما بي بالجبال لهدها ... وإن كان في الدنيا شديدا هدودها)\n(ولست وإن أوعدت فيها بمنته ... وإن أوقدت نار فشب وقودها)\n(أبيت نجيا للهموم مسهدا ... إذا أوقدت نحوي بليل وقودها)\n(فأصبحت ذا نفسن نفس مريضة ... من اليأس ما ينفك هم يعودها)\n(ونفس إذا ما كنت وحدي تقطعت ... كما انسل من ذات النظام فريدها)\n(فلم تبد لي يأسا ففي اليأس راحة ... ولم تبد لي جودا فينفع جودها)","topic":"ذكر أخبار عمر الوادي ونسبه","topicNo":71,"sp":1,"spl":"نسبة هذا الصوت — عمر والوليد وخاتم الياقوت","song":1,"loc":1291},
{"id":"b71-4","bab":"الجزء 7","sec":"عمر والوليد وخاتم الياقوت","page":"ج7 ص102","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن أيوب ابن عباية قال قال عمر الوادي خرج إلي الوليد بن يزيد يوما وفي يده خاتم ياقوت أحمر قد كان البيت يلتمع من شعاعه فقال لي يا جامع لذتي أتحب أن أهبه لك قلت نعم والله يا مولاي فقال غن في هذه الأبيات التي أنشدك فيها واجهد نفسك فإن أصبت إرادتي وهبته لك فقلت أجتهد وأرجو التوفيق\n(ألا يسليك عن سلمى ... قتير الشيب والحلم)\n(وأن الشك ملتبس ... فلا وصل ولا صرم)\n(فلا والله رب الناس ... مالك عندنا ظلم)\n(وكيف بظلم جارية ... ومنها اللين والرحم)\nخلوت في بعض المجالس فما زلت أديره حتى استقام ثم خرجت إليه وعلى رأسه وصيفة بيدها كأس وهو يروم أن يشربها فلا يقدر خمارا فقال ما صنعت فقلت فرغت مما أمرتني به وغنيته فصاح أحسنت والله ووثب قائما على رجليه وأخذ الكأس واستدناني فرضع يده اليسرى علي متكئا والكأس في يده اليمنى ثم قال لي أعد بأبي أنت وأمي فأعدته عليه\nفشرب ودعا بثانية وثالثة ورابعة وهو على حاله يشرب قائما حتى كاد أن يسقط تعبا ثم جلس ونزع الخاتم والحلة التي كانت عليه فقال والله العظيم لا تبرح هكذا حتى أسكر فما زلت أعيده عليه ويشرب حتى مال على جنبه سكرا فنام أخبرني محمد بن مزيد قال حدثنا حماد عن أبيه عن غرير بن طلحة الأرقمي عن أبي الحكم عبد المطلب بن عبد الله بن يزيد بن عبد الملك قال والله إني لبالعقيق في قصر القاسم بن عبد الله بن عمرو بن عثمان بن عفان وعندي أشعب وعمر الوادي وأبو رقية إذ دعوت بدينار فوضعته بين يدي وسبقتهموه في رجز فكان أول من خسق عمر الوادي فقال\n(أنا ابن داود أنا ابن زاذان ... أنا ابن مولى عمرو بن عثمان)\nثم خسق أبو رقية فقال\n(أنا ابن عامر القاري ... أنا ابن أول أعجمي)\nتقدم في مسجد رسول الله خسق أشعب فقال\n(أنا ابن أم الخلنداج ... أنا ابن المحرشة بين أزواج)\nالنبي أبو الحكم فقلت له أي أخزاك الله هل سمعت أحدا قط فخر بهذا فقال وهل فخر أحد بمثل فخري لولا أن أمي كانت عندهن ثقة ما قبلن منها حتى يغضب بعضهن على بعض","topic":"ذكر أخبار عمر الوادي ونسبه","topicNo":71,"sp":1,"spl":"نسبة هذا الصوت — عمر والوليد وخاتم الياقوت","song":1,"loc":1292},
{"id":"b71-5","bab":"الجزء 7","sec":"أخبار أبي كامل","page":"ج7 ص104","text":"اسمه الغزيل وهو مولى الوليد بن يزيد وقيل بل كان مولى أبيه وقيل بل كان أبوه مولى عبد الملك وكان مغنيا محسنا وطيبا مضحكا ولم أسمع له بخبر بعد أيام بني أمية ولعله مات في أيامهم أو قتل معهم أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز عن المدائني أن أبا كامل غنى الوليد بن يزيد ذات يوم فقال\n(نام من كان خليا من ألم ... وبدائي بت ليلي لم أنم)\n(أرقب الصبح كأني مسند ... في أكف القوم تغشاني الظلم)\n(إن سلمى ولنا من حبها ... ديدن في القلب ما اخضر السلم)\n(قد سبتني بشتيت نبته ... وثنايا لم يعبهن قضم)\nقال فطرب الوليد وخلع عليه قلنسية وشي مذهبة كانت على رأسه فكان أبو كامل يصونها ولا يلبسها إلا من عيد إلى عيد ويمسحها بكمه ويرفعها\nويبكي ويقول إنما أرفعها لأني أجد منها ريح سيدي يعني الوليد الغناء في هذا الصوت هزج بالوسطى نسبه عمرو بن بانة إلى عمر الوادي ونسبه غيره إلى أبي كامل وزعم آخرون أنه لحكم هكذا نسبه ابن المكي إلى حكم وزعم أنه بالبنصر أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني الأصمعي عن صفوان بن الوليد المعيطي قال غنى أبو كامل ذات يوم الوليد بن يزيد في لحن لابن عائشة وهو\n(جنباني أذاة كل لئيم ... إنه ما علمت شر نديم)\nفخلع عليه ثيابه كلها حتى قلنسيته ثم ذكر باقي الخبر مثل الذي تقدمه وزاد فيه أنه أوصى أن تجعل في أكفانه وللوليد في أبي كامل أشعار كثيرة فمنها مما يغنى به\n(سقيت أبا كامل ... من الأصفر البابلي)\n(وسقيتها معبدا ... وكل فتى فاضل)\nوقال أيضا فيه\n(وزق وافر الجنبين ... مثل الجمل البازل)\n(به رحت إلى صحبي ... وندماني أبي كامل)\n(شربناه وقد بتنا ... بأعلى الدير بالساحل)\n(ولم نقبل من الواشي ... قبول الجاهل الخاطل)\nالغناء لأبي كامل خفيف رمل بالوسطى وذكر الهشامي أنه ليحيى المكي وأنه نحله أبو كامل وذكر أن لعمر الوادي أو لحكم فيه رملا بالوسطى وهو القائم وأخبرني أبو الحسن محمد بن إبراهيم قريش رحمه الله أن لينشو فيه خفيف رمل ومنها في قول الوليد\n(سقيت أبا كامل ... من الأصفر البابلي)\n(وسقيتها معبدا ... وكل فتى فاضل)\n(لي المحض من ودهم ... ويغمرهم نائلي)\n(وما لامني فيهم ... سوى حاسد جاهل)\nفيه هزج ينسب إلى أبي كامل وإلى حكم وفيه لينشو ثقيل أول أخبرني بذلك قريش ووجه الرزة جميعا وأخبرني قريش عن أحمد بن أبي العلاء قال كان للمعتضد علي صوتان من شعر الوليد أحدهما\n(سقيت أبا كامل ... من الأصفر البابلي)\nوالآخر\n(إن في الكأس لمسكا ... أو بكفي من سقاني)\nوكان يعجب بهما ويقول لجلسائه أما ترون شمائل الملوك في شعره ما أبينها\n(لي المحض من ودهم ... ويغمرهم نائلي)\nوحين يقول\n(كللاني توجاني ... وبشعري غنياني)\nوقد نسب إلى الوليد بن يزيد في هذه المائة الصوت المختارة شعر صوتين لأن ذكر سليمى في أحدهما ولأن الصنعة في الآخر لأبي كامل فذكرت من ذلك ها هنا صوتين أحدهما","topic":"ذكر أخبار عمر الوادي ونسبه","topicNo":71,"sp":2,"spl":"أخبار أبي كامل — من المائة المختارة","song":4,"loc":1293},
{"id":"b71-6","bab":"الجزء 7","sec":"من المائة المختارة","page":"ج7 ص107","text":"(سليمى تلك من العير ... قفي نخبرك أو سيري)\n(إذا ما أنت لم ترثي ... لصب القلب مغمور)\n(فلما أن دنا الصبح ... بأصوات العصافير)\n(خرجنا نتبع الشمس ... عيونا كالقوارير)\n(وفينا شادن أحور ... من حور اليعافير)\nالشعر ليزيد بن ضبة والغناء في اللحن المختار لإسماعيل بن\nالهربذ ولحنه رمل مطلق في مجرى الوسطى هكذا ذكر إسحاق في كتاب شجا لابن الهربذ وذكر في موضع آخر أن فيه لحنا لابن زرزور الطائفي رملا آخر بالسبابة في مجرى البنصر وذكر إبراهيم أن فيه لحنا لأبي كامل ولم يجنسه وذكر حبش أن فيه لعطرد هزجا بالوسطى","topic":"ذكر أخبار عمر الوادي ونسبه","topicNo":71,"sp":2,"spl":"أخبار أبي كامل — من المائة المختارة","loc":1294},
{"id":"b72-1","bab":"الجزء 7","sec":"أخبار يزيد بن ضبة ونسبه","page":"ج7 ص109","text":"أخبرني علي بن صالح بن الهيثم قال حدثني أحمد بن الهيثم عن الحسن بن إبراهيم بن سعدان عن عبد العظيم بن عبد الله بن يزيد بن ضبة الثقفي قال كان جدي يزيد بن ضبة مولى لثقيف واسم أبيه مقسم وضبة أمه غلبت على نسبه لأن أباه مات وخلفه صغيرا فكانت أمه تحضن أولاد المغيرة بن شعبة ثم أولاد ابنه عروة بن المغيرة فكان جدي ينسب إليها لشهرتها قال وولاؤه لبني مالك بن حطيط ثم لبني عامر بن يسار قال عبد العظيم وكان جدي يزيد بن ضبة منقطعا إلى الوليد بن يزيد في حياة أبيه متصلا به لا يفارقه فلما أفضت الخلافة إلى هشام أتاه جدي مهنئا بالخلافة فلما استقر به المجلس ووصلت إليه الوفود وقامت الخطباء تثني عليه والشعراء تمدحه مثل جدي بين السماطين فاستأذنه في الإنشاد فلم\nحذف\nيأذن له وقال عليك بالوليد فامدحه وأنشده وأمر بإخراجه وبلغ الوليد خبره فبعث إليه بخمسمائة دينار وقال له لو أمنت عليك هشاما لما فارقتني ولكن اخرج إلى الطائف وعليك بمالي هناك فقد سوغتك جميع غلته ومهما احتجت إلي من شيء بعد ذلك فالتمسه مني فخرج إلى الطائف وقال يذكر ما فعله هشام به\n(أرى سلمى تصد وما صددنا ... وغير صدودها كنا أردنا)\n(لقد بخلت بنائلها علينا ... ولو جادت بنائلها حمدنا)\n(وقد ضنت بما وعدت وأمست ... تغير عهدها عما عهدنا)\n(ولو علمت بما لاقيت سلمى ... فتخبرني وتعلم ما وجدنا)\n(تلم على تنائي الدار منا ... فيسهرنا الخيال إذا رقدنا)\n(ألم تر أننا لما ولينا ... أمورا خرقت فوهت سددنا)\n(رأينا الفتق حين وهى عليهم ... وكم من مثله صدع رفأنا)\n(إذا هاب الكريهة من يليها ... وأعظمها الهيوب لها عمدنا)\n(وجبار تركناه كلبلا ... وقائد فتنة طاغ أزلنا)\n(فلا تنسوا مواطننا فإنا ... إذا ما عاد أهل الجرم عدنا)\n(وما هيضت مكاسر من جبرنا ... ولا جبرت مصيبة من هددنا)\n(ألا من مبلغ عني هشاما ... فما منا البلاء ولا بعدنا)\n(وما كنا إلى الخلفاء نفضي ... ولا كنا نؤخر إن شهدنا)\n(ألم يك بالبلاء لنا جزاء ... فنجزى بالمحاسن أم حسدنا)\n(وقد كان الملوك يرون حقا ... لوافدنا فنكرم إن وفدنا)\n(ولينا الناس أزمانا طوالا ... وسسناهم ودسناهم وقدنا)\n(ألم تر من ولدنا كيف أشبى ... وأشبينا وما بهم قعدنا)\n(نكون لمن ولدناه سماء ... إذا شيمت مخايلنا رعدنا)\n(وكان أبوك قد أسدى إلينا ... جسيمة أمره وبه سعدنا)\n(كذلك أول الخلفاء كانوا ... بنا جدوا كما بهم جددنا)\n(هم آباؤنا وهم بنونا ... لنا جبلوا كما لهم جبلنا)\n(ونكوي بالعداوة من بغانا ... ونسعد بالمودة من وددنا)\n(نرى حقا لسائلنا علينا ... فنحبوه ونجزل إن وعدنا)\n(ونضمن جارنا ونراه منا ... فنرفده فنجزل إن رفدنا)\n(وما نعتد دون المجد مالا ... إذا يغلى بمكرمة أفدنا)\n(وأتلد مجدنا أنا كرام ... بحد المشرفية عنه ذدنا)","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":0,"spl":"أخبار يزيد بن ضبة ونسبه","loc":1295},
{"id":"b72-2","bab":"الجزء 7","sec":"لكل بيت ألف درهم","page":"ج7 ص111","text":"قال فلم يزل مقيما بالطائف إلى أن ولي الوليد بن يزيد الخلافة فوفد إليه فلما دخل عليه والناس بين يديه جلوس ووقوف على مراتبهم هنأه بالخلافة فأدناه الوليد وضمه إليه وقبل يزيد بن ضبة رجليه والأرض بين يديه فقال الوليد لأصحابه هذا طريد الأحول لصحبته إياي وانقطاعه إلي فاستأذنه يزيد في الإنشاد وقال له يا أمير المؤمنين هذا اليوم الذي نهاني عمك هشام عن الإنشاد فيه قد بلغته بعد يأس والحمد لله على ذلك فأذن له فأنشده\n(سليمى تلك في العير ... قفي أسألك أو سيري)\n(إذا ما بنت لم تأوي ... لصب القلب مغمور)\n(وقد بانت ولم تعهد ... مهاة في مها حور)\n(وفي الآل حمول الحي ... تزهى كالقراقير)\n(يواريها وتبدو منه ... آل كالسمادير)\n(وتطفو حين تطفو فيه ... كالنخل المواقير)\n(لقد لاقيت من سلمى ... تباريح التناكير)\n(دعت عيني لها قلبي ... وأسباب المقادير)\n(وما إن من به شيب ... إذا يصبو بمعذور)\n(لسلمى رسم أطلال ... عفتها الريح بالمور)\n(خريق تنخل الترب ... بأذيال الأعاصير)\n(فأوحش إذ نأت سلمى ... بتلك الدور من دور)\n(سأرمي قانصات البيد ... إن عشت بعسبور)\n(من العيس شجوجاة ... طواها النسع بالكور)\n(إذا ما حقب منها ... قرناه بتصدير)\n(زجرنا العيس فارقدت ... بإعصاف وتشمير)\n(تقاسيها على أين ... بإدلاج وتهجير)\n(إذا ما اعصوصب الآل ... ومال الظل بالقور)\n(وراحت تتقي الشمس ... مطايا القوم كالعور)\n(إلى أن يفضح الصبح ... بأصوات العصافير)\n(لتعتام الوليد القرم ... أهل الجود والخير)\n(كريم يهب البزل ... مع الخور الجراجير)\n(تراعي حين تزجيها ... هويا كالمزامير)\n(كما جاوبت النيب ... رباع الخلج الخور)\n(ويعطى الذهب الأحمر ... وزنا بالقناطير)\n(بلوناه فأحمدناه ... في عسر وميسور)\n(كريم العود والعنصر ... غمر غير منزور)\n(له السبق إلى الغايات ... في ضم المضامير)\n(إمام يوضح الحق ... له نور على نور)\n(مقال من أخي ود ... بحفظ الصدق مأثور)\n(بإحكام وإخلاص ... وتفهيم وتحبير)\nال فأمر الوليد بأن تعد أبيات القصيدة ويعطى لكل بيت ألف درهم فعدت فكانت خمسين بيتا فأعطي خمسين ألفا فكان أول خليفة عد أبيات الشعر وأعطى على عددها لكل بيت ألف درهم ثم لم يفعل ذلك إلا هارون الرشيد فإنه بلغه خبر جدي مع الوليد فأعطى مروان بن أبي حفصة ومنصورا النمري لما مدحاه وهجوا آل أبي طالب لكل بيت ألف درهم","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":1,"spl":"لكل بيت ألف درهم","loc":1296},
{"id":"b72-3","bab":"الجزء 7","sec":"يزيد يمدح فرس الوليد","page":"ج7 ص114","text":"قال عبد العظيم وحدثني أبي وجماعة من أصحاب الوليد أن الوليد خرج إلى الصيد ومعه جدي يزيد بن ضبة فاصطاد على فرسه السندي صيدا حسنا ولحق عليه حمارا فصرعه فقال لجدي صف فرسي هذا وصيدنا اليوم فقال في ذلك\n(وأحوى سلس المرسن ... مثل الصدع الشعب)\n(سما فوق منيفات ... طوال كالقنا سلب)\n(طويل الساق عنجوج ... أشق أصمع الكعب)\n(على لأم أصم مضمر ... الأشعر كالقعب)\n(ترى بين حواميه ... نسورا كنوى القسب)\n(معالى شنج الأنساء ... سام جرشع الجنب)\n(طوى بين الشراسيف ... إلى المنقب فالقنب)\n(يغوص الملحم القائم ... ذو حد وذو شغب)\n(عتيد الشد والتقريب ... والإحضار والعقب)\n(صليب الأذن والكاهل ... والموقف والعجب)\n(عريض الخد والجبهة ... والبركة والهلب)\n(إذا ما حثه حاث ... يباري الريح في غرب)\n(وإن وجهه أسرع ... كالخذروف في الثقب)\n(وقفاهن كالأجدل ... لما انضم للضرب)\n(ووالى الطعن يختار ... جواشن بدن قب)\n(ترى كل مدل قائما ... يلهث كالكلب)\n(كأن الماء في الأعطاف ... منه قطع العطب)\n(كأن الدم في النحر ... قذال عل بالخضب)\n(يزين الدار موقوفا ... ويشفي قرم الركب)\nال فقال له الوليد أحسنت يا يزيد الوصف وأجدته فاجعل لقصيدتك تشبيبا وأعطه الغزيل وعمر الوادي حتى يغنيا فيه فقال\n(إلى هند صبا قلبي ... وهند مثلها يصبي)\n(وهند غادة غيداء ... من جرثومة غلب)\n(وما إن وجد الناس ... من الأدواء كالحب)\n(لقد لج بها الإعراض ... والهجر بلا ذنب)\n(ولما أقض من هند ... ومن جاراتها نحبي)\n(أرى وجدي بهند دائما ... يزداد عن غب)\n(وقد أطولت إعراضا ... وما بغضهم طبي)\n(ولكن رقبة الأعين ... قد تحجز ذا اللب)\n(ورغم الكاشح الراغم ... فيها أيسر الخطب)\nقال ودفع هذه الأبيات إلى المغنين فغنوه فيها أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي عن الأصمعي وحدثني به محمد بن الحسن بن دريد قال حدثنا أبو حاتم قال حدثنا الأصمعي قال كان يزيد بن ضبة مولى ثقيف ولكنه كان فصيحا وقد أدركته بالطائف وقد كان يطلب القوافي المعتاصة والحوشي من الشعر قال أبو حاتم في خبره خاصة وحدثني غسان بن عبد الله بن عبد الوهاب الثقفي عن جماعة من مشايخ الطائفيين وعلمائهم قالوا قال يزيد بن ضبة ألف قصيدة فاقتسمتها شعراء العرب وانتحلتها فدخلت في أشعارها","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":2,"spl":"يزيد يمدح فرس الوليد","song":1,"loc":1297},
{"id":"b72-4","bab":"الجزء 7","sec":"أخبار إسماعيل بن الهربذ","page":"ج7 ص118","text":"إسماعيل بن الهربذ مكي مولى لآل الزبير بن العوام وقيل بل هو مولى بني كنانة أدرك آخر أيام بني أمية وغنى للوليد بن يزيد وعمر إلى آخر أيام الرشيد أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه عن عبد الله بن أبي سعد عن محمد بن عبد الله بن مالك الخزاعي عن أبيه إن إسماعيل بن الهربذ قدم على الرشيد من مكة فدخل إليه وعنده ابن جامع وإبراهيم وابنه إسحاق وفليح وغيرهم والرشيد يومئذ خاثر به خمار شديد فغنى ابن جامع ثم فليح ثم إبراهيم ثم إسحاق فما حركه أحد منهم ولا أطربه فاندفع ابن الهربذ يغني فعجبوا من إقدامه في تلك الحال على الرشيد فغنى\n(يا راكب العيس التي ... وفدت من البلد الحرام)\n(قل للإمام ابن الإمام ... أخي الإمام أبي الإمام)\n(زين البرية إذ بدا ... فيهم كمصباح الظلام)\n(جعل الإله الهربذي ... فداك من بين الأنام)\nالغناء لابن الهربذ رمل بالوسطى عن عمرو قال فكاد الرشيد يرقص واستخفه الطرب حتى ضرب بيديه ورجليه ثم أمر له بعشرة آلاف درهم فقال له يا أمير المؤمنين إن لهذا الصوت حديثا فإن أذن مولاي حدثته به فقال حدث ... قال كنت مملوكا لرجل من ولد الزبير فدفع إلي درهمين أبتاع له بهما لحما فرحت فلقيت جارية على رأسها جرة مملوءة من ماء العقيق وهي تغني هذا اللحن في شعر غير هذا الشعر على وزنه ورويه فسألتها أن تعلمنيه فقالت لا وحق القبر إلا بدرهمين فدفعت إليها الدرهمين وعلمتنيه فرجعت إلى مولاي بغير لحم فضربني ضربا مبرحا شغلت معه بنفسي فأنسيت الصوت ثم دفع إلي درهمين آخرين بعد أيام أبتاع له بهما لحما فلقيتني الجارية فسألتها أن تعيد الصوت علي فقالت لا والله إلا بدرهمين فدفعتهما إليها وأعادته علي مرارا حتى أخذته فلما رجعت إلى مولاي أيضا ولا لحم معي قال ما القصة في هذين الدرهمين فصدقته القصة وأعدت عليه الصوت فقبل بين عيني وأعتقني فرحلت اليك بهذا الصوت وقد جعلت ذلك اللحن في هذا الشعر فقال دع الأول وتناسه وأقم على الغناء بهذا اللحن في هذا الشعر فأما مولاك فسأدفع إليه بدل كل درهم ألف دينار ثم أمر له بذلك فحمل إليه ومما نسب إلى الوليد بن يزيد من الشعر وليس له","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":3,"spl":"أخبار إسماعيل بن الهربذ — من المائة المختارة","song":2,"loc":1298},
{"id":"b72-5","bab":"الجزء 7","sec":"من المائة المختارة","page":"ج7 ص119","text":"(امدح الكأس ومن أعملها ... واهج قوما قتلونا بالعطش)\n(إنما الكأس ربيع باكر ... فإذا ما غاب عنا لم نعش)\nالشعر لنابغة بني شيبان والغناء لأبي كامل ولحنه المختار من خفيف الثقيل الثاني بالوسطى وهو الذي تسميه الناس اليوم الماخوري وفيه لأبي كامل أيضا خفيف رمل بالبنصر عن عمرو وذكر الهشامي أن فيه لمالك لحنا من الثقيل الأول بالوسطى ولعمر الوادي ثاني ثقيل بالبنصر","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":3,"spl":"أخبار إسماعيل بن الهربذ — من المائة المختارة","loc":1299},
{"id":"b72-7","bab":"الجزء 7","sec":"نسب نابغة بني شيبان — نابغة بني شيبان يمدح عبد الملك","page":"ج7 ص120 – ج7 ص121","text":"النابغة اسمه عبد الله بن المخارق بن سليم بن حصرة بن قيس بن سنان ابن حماد بن حارثة بن عمرو بن أبي ربيعة بن ذهل بن شيبان بن ثعلبة بن عكابة بن صعب بن علي بن بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار شاعر بدوي من شعراء الدولة الأموية وكان يفد إلى الشام إلى خلفاء بني أمية فيمدحهم ويجزلون عطاءه وكان فيما أرى نصرانيا لأني وجدته في شعره يحلف بالإنجيل والرهبان والأيمان التي يحلف بها النصارى ومدح عبد الملك بن مروان ومن بعده من ولده وله في الوليد مدائح كثيرة\nأخبرني عمي قال حدثني محمد بن سعد الكراني قال حدثني العمري عن العتبي قال لما هم عبد الملك بخلع عبد العزيز أخيه وتولية الوليد ابنه العهد كان نابغة بني شيبان منقطعا إلى عبد الملك مداحا له فدخل إليه في يوم حفل\nوالناس حواليه وولده قدامه فمثل بين يديه وأنشده قوله\n(أشتقت وانهل دمع عينك أن ... أضحى قفارا من أهله طلح)\nحتى انتهى إلى قوله\n(أزحت عنا آل الزبير ولو ... كانوا هم المالكين ما صلحوا)\n(إن تلق بلوى فأنت مصطبر ... وإن تلاق النعمى فلا فرح)\n(ترمي بعيني أقنى على شرف ... لم يؤذه عائر ولا لحح)\n(آل أبي العاص آل مأثرة ... غر عتاق بالخير قد نفحوا)\n(خير قريش وهم أفاضلها ... في الجد جد وإن هم مزحوا)\n(أرحبها أذرعا وأصبرها ... أنتم إذا القوم في الوغى كلحوا)\n(أما قريش فأنت وارثها ... تكف من صعبهم إذا طمحوا)\n(حفظت ما ضيعوا وزندهم ... أوريت إذا أصلدوا وقد قدحوا)\n(آليت جهدا وصادق قسمي ... برب عبد تجنه الكرح)\n(يظل يتلو الإنجيل يدرسه ... من خشية الله قلبه طفح)\n(لابنك أولى بملك والده ... ونجم من قد عصاك مطرح)\n(داود عدل فاحكم بسيرته ... ثم ابن حرب فإنهم نصحوا)\n(وهم خيار فاعمل بسنتهم ... واحي بخير واكدح كما كدحوا)\nقال فتبسم عبد الملك ولم يتكلم في ذلك بإنذار ولا دفع فعلم الناس أن رأيه خلع عبد العزيز وبلغ ذلك من قول النابغة عبد العزيز فقال لقد أدخل ابن النصرانية نفسه مدخلا ضيقا فأوردها موردا خطرا وبالله علي لئن ظفرت بن لأخضبن قدمه بدمه","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":4,"spl":"نسب نابغة بني شيبان — نابغة بني شيبان يمدح عبد الملك — مدح يزيد","loc":1300},
{"id":"b72-8","bab":"الجزء 7","sec":"مدح يزيد","page":"ج7 ص123","text":"وقال أبو عمرو الشيباني لما قتل يزيد بن المهلب دخل النابغة الشيباني على يزيد بن عبد الملك بن مروان فأنشده قوله في تهنئته بالفتح\n(ألا طال التنظر والثواء ... وجاء الصيف وانكشف الغطاء)\n(وليس يقيم ذو شجن مقيم ... ولا يمضي إذا ابتغي المضاء)\n(طوال الدهر إلا في كتاب ... ومقدار يوافقه القضاء)\n(فما يعطى الحريص غنى لحرص ... وقد ينمي لذي الجود الثراء)\n(وكل شديدة نزلت بحي ... سيتبعها إذا انتهت الرخاء)\nويقول فيها\n(أؤم فتى من الأعياص ملكا ... أغر كأن غرته ضياء)\n(لأسمعه غريب الشعر مدحا ... وأثني حيث يتصل الثناء)\n(يزيد الخير فهو يزيد خيرا ... وينمي كلما ابتغي النماء)\n(فضضت كتائب الأزدي فضا ... بكبشك حين لفهما اللقاء)\n(سمكت الملك مقتبلا جديدا ... كما سمكت على الأرض السماء)\n(نرجي أن تدوم لنا إماما ... وفي ملك الوليد لنا رجاء)\n(هشام والوليد وكل نفس ... تريد لك الفناء لك الفداء)\nوهي قصيدة طويلة فأمر له بمائة ناقة من نعم كلب وأن توقر له برا وزبيبا وكساه وأجزل صلته قال ووفد إلى هشام لما ولي الخلافة فلما رآه قال له يا ماص ما أبقت المواسي من بظر أمه ألست القائل\n(هشام والوليد وكل نفس ... تريد لك الفناء لك الفداء)\nأخرجوه عني والله لا يرزؤني شيئا أبدا وحرمه ولم يزل طول أيامه طريدا حتى ولي الوليد بن يزيد فوفد إليه ومدحه مدائح كثيرة فأجزل صلته حدثني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني عبيد الله بن محمد الكوفي عن العمري الخصاف عن الهيثم بن عدي عن حماد الراوية أنه أنشده لنابغة بني شيبان\n(أيها الساقي سقتك مزنة ... من ربيع ذي أهاضيب وطش)\n(امدح الكأس ومن أعملها ... واهج قوما قتلونا بالعطش)\n(إنما الكأس ربيع باكر ... فإذا ما غاب عنا لم نعش)\n(وكأن الشرب قوم موتوا ... من يقم منهم لأمر يرتعش)\n(خرس الألسن مما نالهم ... بين مصروع وصاح منتعش)\n(من حميا قرقف حصية ... قهوة حولية لم تمتحش)\n(ينفع المزكوم منها ريحها ... ثم تنفي داءه إن لم تنش)\n(كل من يشربها يألفها ... ينفق الأموال فيها كل هش)","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":4,"spl":"نسب نابغة بني شيبان — نابغة بني شيبان يمدح عبد الملك — مدح يزيد","loc":1301},
{"id":"b72-9","bab":"الجزء 7","sec":"مدح بني شيبان","page":"ج7 ص125","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن الجمحي قال ابن أبي الأزهر وهو محمد بن سلام غني أبو كامل مولى الوليد بن يزيد يوما بحضرة الوليد بن يزيد\n(امدح الكأس ومن أعملها ... واهج قوما قتلونا بالعطش)\nفسأل عن قائل هذا الشعر فقيل نابغة بني شيبان فأمر بإحضاره فأحضر فاستنشده القصيدة فأنشده إياها وظن أن فيه مدحا له فإذا هو يفتخر بقومه ويمدحهم فقال له الوليد لو سعد جدك لكانت مديحا فينا لا في بني شيبان ولسنا نخليك على ذلك من حظ ووصله وانصرف وأول هذه القصيدة قوله\n(خل قلبي من سليمى نبلها ... إذ رمتني بسهام لم تطش)\n(طفلة الأعطاف رؤد دمية ... وشواها بختري لم يحش)\n(وكأن الدر في أخراصها ... بيض كحلاء أقرته بعش)\n(ولها عينا مهاة في مها ... ترتعي نبت خزامى ونتش)\n(حرة الوجه رخيم صوتها ... رطب تجنيه كف المنتقش)\n(وهي في الليل إذا ما عونقت ... منية البعل وهم المفترش)\nوفيها يقول مفتخرا\n(وبنو شيبان حولي عصب ... منهم غلب وليست بالقمش)\n(وردوا المجد وكانوا أهله ... فرووا والجود عاف لم ينش)\n(وترى الجرد لدى أبياتهم ... أرنات بين صلصال وجش)\n(ليس في الألوان منها هجنة ... وضح البلق ولا عيب البرش)\n(فبها يحوون أموال العدا ... ويصيدون عليها كل وحش)\n(دميت أكفالها من طعنهم ... بالردينيات والخيل النجش)\n(ننهل الخطي من أعدائنا ... ثم نفري الهام إن لم نفترش)\n(فإذا العيس من المحل غدت ... وهي في أعينها مثل العمش)\n(حسر الأوبار مما لقيت ... من سحاب حاد عنها لم يرش)\n(خسف الأعين ترعى جوفة ... همدت أوبارها لم تنتفش)\n(تنعش العافي ومن لاذ بنا ... بسجال الخير من أيد نعش)\n(ذاك قولي وثنائي وهم ... أهل ودي خالصا في غير غش)\n(فسلوا شيبان إن فارقتهم ... يوم يمشون إلى قبري بنعش)\n(هل غشينا محرما في قومنا ... أو جزينا جازيا فحشا بفحش)\nومما يغنى فيه من شعر نابغة بني شيبان\n(ذرفت عيني دموعا ... من رسوم بحفير)\n(موحشات طامسات ... مثل آيات الزبور)\n(وزقاق مترعات ... من سلافات العصير)\n(مجلخدات ملاء ... بطنوهن بقير)\n(فإذا صارت اليهم ... صيرت خير مصير)\n(من شباب وكهول ... حكموا كأس المدير)\n(كم ترى فيهم نديما ... من رئيس وأمير)\nكر يونس أن فيه لمالك لحنا ولابن عائشة آخر ولم يذكر طريقتهما وفيه خفيف رمل معروف لا أدري لحن أيهما هو","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":5,"spl":"مدح بني شيبان — من المائة المختارة","song":2,"loc":1302},
{"id":"b72-10","bab":"الجزء 7","sec":"من المائة المختارة","page":"ج7 ص127","text":"(يا عمر حم فراقكم عمرا ... وعزمت منا النأي والهجرا)\n(إحدى بني أود كلفت بها ... حملت بلا ترة لنا وترا)\n(وترى لها دلا إذا نطقت ... تركت بنات فؤاده صعرا)\n(كتساقط الرطب الجني من الأفنان ... لا بثرا ولا نزرا)\nلشعر لأبي دهبل الجمحي والغناء لفزار المكي ولحنه المختار ثقيل أول مطلق في مجرى الوسطى عن الهشامي","topic":"أخبار يزيد بن ضبة ونسبه","topicNo":72,"sp":5,"spl":"مدح بني شيبان — من المائة المختارة","loc":1303},
{"id":"b73-1","bab":"الجزء 7","sec":"أخبار أبي دهبل ونسبه","page":"ج7 ص128","text":"نسبه فيما ذكر الزبير بن بكار وغيره وهب بن زمعة بن أسيد بن أحيحة بن خلف بن وهب بن حذافة بن جمح بن عمرو بن هصيص بن كعب ابن لؤي بن غالب ولخلف بن وهب يقول عبد الله بن الزبعري أو غيره\n(خلف بن وهب كل آخر ليلة ... أبدا يكثر أهله بعيال)\n(سقيا لوهب كهلها ووليدها ... ما دام في أبياتها الذيال)\n(نعم الشباب شبابهم وكهولهم ... صيابة ليسوا من الجهال)\nوأم أبي دهبل امرأة من هذيل وإياها يعني بقوله\n(أنا ابن الفروع الكرام التي ... هذيل لأبياتها سائله)\n(هم ولدوني وأشبهتهم ... كما تشبه الليلة القابله)\nواسمها فيما ذكر ابن الأعرابي هذيلة بنت سلمة","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":0,"spl":"أخبار أبي دهبل ونسبه","loc":1304},
{"id":"b73-2","bab":"الجزء 7","sec":"بعض من صفاته","page":"ج7 ص129","text":"قال المدائني كان أبو دهبل رجلا جميلا شاعرا وكانت له جمة\nيرسلها فتضرب منكبيه وكان عفيفا وقال الشعر في آخر خلافة علي بن أبي طالب رضي الله عنه ومدح معاوية وعبد الله بن الزبير وقد كان ابن الزبير ولاه بعض أعمال اليمن حدثنا محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري عن الكلبي عن أبي مسكين وأخبرني به محمد بن خلف بن المرزبان قال حدثني أحمد بن الهيثم بن فراس قال حدثني العباس بن هشام عن أبيه عن أبي مسكين إن قوما مروا براهب فقالوا له يا راهب من أشعر الناس قال مكانكم حتى أنظر في كتاب عندي فنظر في رق له عتيق ثم قال وهب من وهبين من جمح أو جمحين أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا علي ابن صالح عن عبد الله بن عروة قال قال أبو دهبل يفخر بقومه\n(قومي بنو جمح قوم إذا انحدرت ... شهباء تبصر في حافاتها الزغفا)\n(أهل الخلافة والموفون إن وعدوا ... والشاهدو الروع لا عزلا ولا كشفا)\nقال الزبير وأنشدني عمي قال أنشدني مصعب لأبي دهبل يفخر بقومه بقوله\n(أنا أبو دهبل وهب لوهب ... من جمح في العز منها والحسب)\n(والأسرة الخضراء والعيص الأشب ... ومن هذيل والدي عالي النسب)\n(أورثني المجد أب من بعد أب ... رمحي رديني وسيفي المستلب)\n(وبيضتي قونسها من الذهب ... درعي دلاص سردها سرد عجب)\n(والقوس فجاء لها نبل ذرب ... محشورة أحكم منهن القطب)\n(ليوم هيجاء أعدت للرهب ... )\nشيج الأحبة أخبرني محمد بن خلف قال حدثنا محمد بن زهير قال حدثنا المدائني أن أبا دهبل كان يهوى امرأة من قومه يقال لها عمرة وكانت امرأة جزلة يجتمع إليها الرجال للمحادثة وإنشاد الشعر والأخبار وكان أبو دهبل لا يفارق مجلسها مع كل من يجتمع إليها وكانت هي أيضا محبة له وكان أبو دهبل رجلا سيدا من أشراف بني جمح وكان يحمل الحمالات ويعطي الفقراء ويقري الضيف وزعمت بنو جمح أنه تزوج عمرة هذه بعد ذلك وزعم غيرهم أنه لم يصل إليها وكانت عمرة توصيه بحفط ما بينهما وكتمانه فضمن لها ذلك واتصل ما بينهما فوقفت عليه زوجته فدست إلى عمرة امرأة داهية من عجائز أهلها فجاءتها فحادثتها طويلا ثم قالت لها في عرض حديثها إني لأعجب لك كيف لا تتزوجين أبا دهبل مع ما بينكما قالت وأي شيء يكون بيني وبين أبي دهبل قال فتضاحكت وقالت أتسترين عني شيئا قد تحدثت به أشراف قريش في مجالسها وسوقة أهل\nالحجاز في أسواقها والسقاة في مواردها فما يتدافع اثنان أنه يهواك وتهوينه فوثبت عن مجلسها فاحتجبت ومنعت كل من كان يجالسها من المصير إليها وجاء أبو دهبل على عادته فحجبته وأرسلت إليه بما كره ففي ذلك يقول\n(تطاول هذا الليل ما يتبلج ... وأعيت غواشي عبرتي ما تفرج)\n(وبت كئيبا ما أنام كأنما ... خلال ضلوعي جمرة تتوهج)\n(فطورا أمني النفس من عمرة المنى ... وطورا إذا ما لج بي الحزن أنشج)\n(لقد قطع الواشون ما كان بيننا ... ونحن إلى أن يوصل الحبل أحوج)\nلغناء في البيت الأول وبعده بيت في آخر القصيدة\n(أخطط في ظهر الحصير كأنني ... أسير يخاف القتل ولهان ملفج)\nلمعبد ثقيل أول بالوسطى وذكر حماد عن أبيه في أخبار مالك أنه لحائد بن جرهد وأن مالكا أخذه عنه فنسبه الناس إليه فكان إذا غناه وسئل عنه يقول هذا والله لحائد بن جرهد لا لي وفيه لأبي عيسى بن الرشيد ثاني ثقيل بالوسطى عن حبش وفي لقد قطع الواشون وقبله فطورا أمني النفس لمالك ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه لمعبد خفيف ثقيل بالوسطى عن حبش\n(رأوا غرة فاستقبلوها بألبهم ... فراحوا على مالا نحب وأدلجوا)\n(وكانوا أناسا كنت آمن غيبهم ... فلم ينههم حلمي ولم يتحرجوا)\n(فليت كوانينا من أهلي وأهلها ... بأجمعهم في قعر دجلة لججوا)\n(هم منعونا ما نحب وأوقدوا ... علينا وشبوا نار صرم تأجج)\n(ولو تركونا لا هدى الله سعيهم ... ولم يلحموا قولا من الشر ينسج)\n(لأوشك صرف الدهر يفرق بيننا ... ولا يستقيم الدهر والدهر أعوج)\n(عسى كربة أمسيت فيها مقيمة ... يكون لنا منها نجاة ومخرج)\n(فيكبت أعداء ويجذل آلف ... له كبد من لوعة الحب تلعج)\n(وقلت لعباد وجاء كتابها ... لهذا وربي كانت العين تخلج)\n(وإني لمحزون عشية زرتها ... وكنت إذا ما جئتها لا أعرج)\n(أخطط في ظهر الحصير كأنني ... أسير يخاف القتل ولهان ملفج)\nالملفج الفقير المحتاج","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":1,"spl":"بعض من صفاته","song":1,"loc":1305,"partial":1},
{"id":"b73-3","bab":"الجزء 7","sec":"بعض من صفاته","page":"ج7 ص129","text":"(وأشفق قلبي من فراق خليلة ... لها نسب في فرع فهر متوج)\n(وكف كهداب الدمقس لطيفة ... بها دوس حناء حديث مضرج)\n(يجول وشاحاها ويغتص حجلها ... ويشبع منها وقف عاج ودملج)\n(فلما التقينا لجلجت في حديثها ... ومن آية الصرم الحديث الملجلج)","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":2,"spl":"بعض من صفاته — شعره في عمرة","loc":1306},
{"id":"b73-4","bab":"الجزء 7","sec":"شعره في عمرة","page":"ج7 ص133","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أنشدني عمي ومحمد بن الضحاك عن أبيه محمد بن خشرم ومن شئت من قريش لأبي دهبل في عمرة\n(يا عمر حم فراقكم عمرا ... وعزمت منا النأي والهجرا)\n(يا عمر شيخك وهو ذو كرم ... يحمي الذمار ويكرم الصهرا)\n(إن كان هذا السحر منك فلا ... ترعي علي وجددي السحرا)\n(إحدى بني أود كلفت بها ... حملت بلا وتر لنا وترا)\n(وترى لها دلا إذا نطقت ... تركت بنات فؤاده صعرا)\n(كتساقط الرطب الجني من الأفنان ... لا بثرا ولا نزرا)\n(أقسمت ما أحببت حبكم ... لا ثيبا خلقت ولا بكرا)\n(ومقالة فيكم عركت بها ... جنبي أريد بها لك العذرا)\n(ومريد سركم عدلت به ... فيما يحاول معدلا وعرا)\n(قالت يقيم بنا لنجزيه ... يوما فخيم عندها شهرا)\n(ما إن أقيم لحاجة عرضت ... إلا لأبلي فيكم العذرا)\nقالوا وفيها يقول\n(يلومونني في غير ذنب جنيته ... وغيري في الذنب الذي كان ألوم)\n(أمنا أناسا كنت تأتمنينهم ... فزادوا علينا في الحديث وأوهموا)\n(وقالوا لنا ما لم يقل ثم كثروا ... علينا وباحوا بالذي كنت أكتم)\nنى في هذه الأبيات أبو كامل مولى الوليد رملا بالبنصر\n(وقد منحت عيني القذى لفراقهم ... وعاد لها تهتانها فهي تسجم)\n(وصافيت نسوانا فلم أر فيهم ... هواي ولا الود الذي كنت أعلم)\n(أليس عظيما أن نكون ببلدة ... كلانا بها ثاو ولا نتكلم)\nخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال حدثني أبو غسان قال سمع أبو السائب المخزومي رجلا ينشد قول أبي دهبل\n(أليس عجيبا أن نكون ببلدة ... كلانا بها ثاو ولا نتكلم)\nفقال له أبو السائب قف يا حبيبي فوقف فصاح بجارية يا سلامة اخرجي فخرجت فقال له أعد بأبي أنت البيت فأعاده فقال بلى والله إنه لعجيب عظيم وإلا فسلامة حرة لوجه الله اذهب فديتك مصاحبا ثم دخل ودخلت الجارية تقول له ما لقيت منك لا تزال تقطعني عن شغلي فيما لا ينفعك ولا ينفعني وحدثني أحمد بن عبيد الله بن عمار قال كنا نختلف إلى أبي العباس المبرد ونحن أحداث نكتب عن الرواة ما يروونه من الآداب والأخبار وكان يصحبنا فتى من أحسن الناس وجها وأنظفهم ثوبا وأجملهم زيا ولا نعرف باطن أمره فانصرفنا يوما من مجلس أبي العباس المبرد وجلسنا في مجلس نتقابل بما كتبناه ونصحح المجلس الذي شهدناه فإذا بجارية قد اطلعت فطرحت في حجر الفتى رقعة ما رأيت أحسن من شكلها مختومة بعنبر فقرأها منفردا بها ثم أجاب عنها ورمى بها إلى الجارية فلم نلبث أن خرج خادم من الدار في يده كرش فدخل الينا فصفع الفتى به حتى رحمناه وخلصناه من يده\n(وقمنا أسوأ الناس حالا فلما تباعدنا سألناه عن الرقعة فإذا فيها مكتوب ... )\n(كفى حزنا أنا جميعا ببلدة ... كلانا بها ثاو ولا نتكلم)\nفقلنا له هذا ابتداء ظريف فبأي شيء أجبت أنت قال هذا صوت سمعته يغنى فيه فلما قرأته في الرقعة أجبت عنه بصوت مثله فسألناه ما هو فقال كتبت في الجواب\n(أراعك بالخابور نوق وأجمال ... )\nفقلنا له ما وفاك القوم حقك قط وقد كان ينبغي أن يدخلونا معك في القصة لدخولك في جملتنا ولكنا نحن نوفيك حقك ثم تناولناه فصفعناه حتى لم يدر أي طريق يأخذ وكان آخر عهده بالاجتماع معنا رجع الخبر إلى سياقة أخبار أبي دهبل","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":2,"spl":"بعض من صفاته — شعره في عمرة","song":1,"loc":1307,"partial":1},
{"id":"b73-5","bab":"الجزء 7","sec":"أبو دهبل وعاتكة بنت معاوية","page":"ج7 ص136","text":"أخبرني عمي حدثني الكراني قال حدثني العمري عن الهيثم بن عدي قال حدثنا صالح بن حسان قال وأخبرني بهذا الخبر محمد بن خلف بن المرزبان قال حدثني محمد بن عمر قال حدثني محمد بن السري قال\nحدثنا هشام بن الكلبي عن أبيه يزيد أحدهما على الآخر في خبره واللفظ لصالح بن حسان وخبره أتم قال حجت عاتكة بنت معاوية بن أبي سفيان فنزلت من مكة بذي طوى فبينا هي ذات يوم جالسة وقد اشتد الحر وانقطع الطريق وذلك في وقت الهاجرة إذ أمرت جواريها فرفعن الستر وهي جالسة في مجلسها عليها شفوف لها تنظر إلى الطريق إذ مر بها أبو دهبل الجمحي وكان من أجمل الناس وأحسنهم منظرا فوقف طويلا ينظر إليها وإلى جمالها وهي غافلة عنه فلما فطنت له سترت وجهها وأمرت بطرح الستر وشتمته فقال أبو دهبل\n(إني دعاني الحين فاقتادني ... حتى رأيت الظبي بالباب)\n(يا حسنه إذ سبني مدبرا ... مستترا عني بجلباب)\n(سبحان من وقفها حسرة ... صبت على القلب بأوصاب)\n(يذود عنها إن تطلبتها ... أب لها ليس بوهاب)\n(أحلها قصرا منيع الذرى ... يحمى بأبواب وحجاب)\nقال وأنشد أبو دهبل هذه الأبيات بعض إخوانه فشاعت بمكة وشهرت وغنى فيها المغنون حتى سمعتها عاتكة إنشادا وغناء فضحكت وأعجبتها وبعثت إليه بكسوة وجرت الرسل بينهما فلما صدرت عن مكة خرج معها إلى الشأم ونزل قريبا منها فكانت تعاهده بالبر واللطف حتى وردت دمشق وورد معها فانقطعت عن لقائه وبعد من أن يراها ومرض بدمشق مرضا طويلا فقال في ذلك\n(طال ليلي وبت كالمحزون ... ومللت الثواء في جيرون)\n(وأطلت المقام بالشأم حتى ... ظن أهلي مرجمات الظنون)\n(فبكت خشية التفرق جمل ... كبكاء القرين إثر القرين)\n(وهي زهراء مثل لؤلؤة الغواص ... ميزت من جوهر مكنون)\n(وإذا ما نسبتها لم تجدها ... في سناء من المكارم دون)\n(ثم خاصرتها إلى القبة الخضراء ... تمشي في مرمر مسنون)\n(قبة من مراجل ضربوها ... عند برد الشتاء في قيطون)\n(عن يساري إذا دخلت من الباب ... وإن كنت خارجا عن يميني)\n(ولقد قلت إذ تطاول سقمي ... وتقلبت ليلتي في فنون)\n(ليت شعري أمن هوى طار نومي ... أم براني الباري قصير الجفون)\nال وشاع هذا الشعر حتى بلغ معاوية فأمسك عنه حتى إذا كان في يوم الجمعة دخل عليه الناس وفيهم أبو دهبل فقال معاوية لحاجبه إذا أراد أبو دهبل الخروج فامنعه واردده إلي وجعل الناس يسلمون وينصرفون فقام أبو دهبل لينصرف فناداه معاوية يا أبا دهبل إلي فلما دنا إليه أجلسه حتى خلا به ثم قال له ما كنت ظننت أن في قريش أشعر منك حيث تقول\n(ولقد قلت إذ تطاول سقمي ... وتقلبت ليلتي في فنون)\n(ليت شعري أمن هوى طار نومي ... أم براني الباري قصير الجفون)\nغير أنك قلت\n(وهي زهراء مثل لؤلؤة الغواص ... ميزت من جوهر مكنون)\n(وإذا ما نسبتها لم تجدها ... في سناء من المكارم دون)\nووالله إن فتاة أبوها معاوية وجدها أبو سفيان وجدتها هند بنت عتبة لكما ذكرت وأي شيء زدت في قدرها ولقد أسأت في قولك\n(ثم خاصرتها إلى القبة الخضراء ... تمشي في مرمر مسنون)\nفقال والله يا أمير المؤمنين ما قلت هذا وإنما قيل على لساني فقال له أما من جهتي فلا خوف عليك لأني أعلم صيانة ابنتي نفسها وأعرف أن فتيان الشعر لم يتركوا أن يقولوا النسيب في كل من جاز أن يقولوه فيه وكل من لم يجز وإنما أكره لك جوار يزيد وأخاف عليك وثباته فإن له سورة الشباب وأنفة الملوك وإنما أراد معاوية أن يهرب أبو دهبل فتنقضي المقالة عن ابنته فحذر أبو دهبل فخرج إلى مكة هاربا على وجهه فكان يكاتب عاتكة فبينا معاوية ذات يوم في مجلسه إذ جاءه خصي له فقال يا أمير المؤمنين والله لقد سقط إلى عاتكة اليوم كتاب فلما قرأته بكت ثم أخذته\nفوضعته تحت مصلاها وما زالت خاثرة النفس منذ اليوم فقال له اذهب فالطف لهذا الكتاب حتى تأتيني به فانطلق الخصي فلم يزل يلطف حتى أصاب منها غرة فأخذ الكتاب وأقبل به إلى معاوية فإذا فيه\n(أعاتك هلا إذ بخلت فلا تري ... لذي صبوة زلفى لديك ولا حقا)\n(رددت فؤادا قد تولى به الهوى ... وسكنت عينا لا تمل ولا ترقا)\n(ولكن خلعت القلب بالوعد والمنى ... ولم أر يوما منك جودا ولا صدقا)\n(أتنسين أيامي بربعك مدنفا ... صريعا بأرض الشأم ذا سقم ملقى)\n(وليس صديق يرتضى لوصية ... وأدعو لدائي بالشراب فما أسقى)","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":3,"spl":"أبو دهبل وعاتكة بنت معاوية","loc":1308},
{"id":"b73-6","bab":"الجزء 7","sec":"أبو دهبل وعاتكة بنت معاوية","page":"ج7 ص136","text":"(وأكبر همي أن أرى لك مرسلا ... فطول نهاري جالس أرقب الطرقا)\n(فواكبدي إذ ليس لي منك مجلس ... فأشكو الذي بي من هواك وما ألقى)\n(رأيتك تزدادين للصب غلظة ... ويزداد قلبي كل يوم لكم عشقا)\nال فلما قرأ معاوية هذا الشعر بعث إلى يزيد بن معاوية فأتاه فدخل عليه فوجد معاوية مطرقا فقال يا أمير المؤمنين ما هذا الأمر الذي شجاك قال أمر أمرضني وأقلقني منذ اليوم وما أدري ما أعمل في شأنه قال وما هو يا أمير المؤمنين قال هذا الفاسق أبو دهبل كتب بهده الأبيات إلى أختك عاتكة فلم تزل باكية منذ اليوم وقد أفسدها فما ترى فيه فقال والله إن الرأي لهين قال وما هو قال عبد من عبيدك يكمن له في أزقة مكة فيريحنا منه قال معاوية أف لك والله إن امرأ يريد بك ما يريد ويسمو بك إلى ما يسمو لغير ذي رأي وأنت قد ضاق ذرعك بكلمة وقصر فيها باعك حتى أردت أن تقتل رجلا من قريش أو ما تعلم أنك إذا فعلت ذلك صدقت\nقوله وجعلتنا أحدوثة أبدا قال يا أمير المؤمنين إنه قال قصيدة أخرى تناشدها أهل مكة وسارت حتى بلغتني وأوجعتني وحملتني على ما أشرت به فيه قال وما هي قال قال\n(ألا لا تقل مهلا فقد ذهب المهل ... وما كل من يلحى محبا له عقل)\n(لقد كان في حولين حالا ولم أزر ... هواي وإن خوفت عن حبها شغل)\n(حمى الملك الجبار عني لقاءها ... فمن دونها تخشى المتالف والقتل)\n(فلا خير في حب يخاف وباله ... ولا في حبيب لا يكون له وصل)\n(فواكبدي إني شهرت بحبها ... ولم يك فيما بيننا ساعة بذل)\n(ويا عجبا إني أكاتم حبها ... وقد شاع حتى قطعت دونها السبل)\nال فقال معاوية قد والله رفهت عني فما كنت آمن أنه قد وصل إليها فأما الآن وهو يشكو أنه لم يكن بينهما وصل ولا بذل فالخطب فيه يسير قم عني فقام يزيد فانصرف وحج معاوية في تلك السنة فلما انقضت أيام الحج كتب أسماء وجوه قريش وأشرافهم وشعرائهم وكتب فيهم اسم أبي دهبل ثم دعا بهم ففرق في جميعهم صلات سنية وأجازهم جوائز كثيرة فلما قبض أبو دهبل جائزته وقام لينصرف دعا به معاوية فرجع إليه فقال له يا أبا دهبل مالي رأيت أبا خالد يزيد ابن أمير المؤمنين عليك ساخطا في قوارص تأتيه عنك وشعر لا تزال قد نطقت به وأنفذته إلى خصمائنا وموالينا لا تعرض لأبي خالد فجعل يعتذر إليه ويحلف له أنه مكذوب عليه فقال له معاوية لا بأس عليك وما يضرك ذلك عندنا هل\nتأهلت قال لا قال فأي بنات عمك أحب إليك قال فلانة قال قد زوجتكها وأصدقتها ألفي دينار وأمرت لك بألف دينار فلما قبضها قال إن رأى أمير المؤمنين أن يعفو لي عما مضى فإن نطقت ببيت في معنى ما سبق مني فقد أبحت به دمي وفلانة التي زوجتنيها طالق البتة فسر بذلك معاوية وضمن له رضا يزيد عنه ووعده بإدرار ما وصله به في كل سنة وانصرف إلى دمشق ولم يحجج معاوية في تلك السنة إلى من أجل أبي دهبل","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":4,"spl":"أبو دهبل وعاتكة بنت معاوية","loc":1309},
{"id":"b73-7","bab":"الجزء 7","sec":"الرجل الضعيف والمرأة الآثمة","page":"ج7 ص142","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قال حدثني إبراهيم بن عبد الله قال خرج أبو دهبل يريد الغزو وكان رجلا صالحا وكان جميلا فلما كان بجيرون جاءته امرأة فأعطته كتابا فقالت اقرأ لي هذا الكتاب فقرأه لها ثم ذهبت فدخلت قصرا ثم خرجت إليه فقالت لو بلغت القصر فقرأت الكتاب على امرأة كان لك فيه أجر إن شاء الله فإنه من غائب لها يعنيها أمره فبلغ معها القصر فلما دخلا إذا فيه جوار كثيرة فأغلقن القصر عليه وإذا فيه امرأة وضيئة فدعته إلى نفسها فأبى فأمرت به فحبس في بيت في القصر وأطعم وسقي قليلا قليلا حتى ضعف وكاد يموت ثم دعته إلى نفسها فقال لا يكون ذلك أبدا ولكني أتزوجك قالت نعم فتزوجها فأمرت به فأحسن إليه حتى رجعت إليه نفسه فأقام معها زمانا طويلا لا تدعه يخرج حتى يئس منه أهله وولده وتزوج بنوه وبناته واقتسموا ماله وأقامت زوجته تبكي عليه حتى عمشت ولم تقاسمهم ماله ثم إنه قال لامرأته إنك قد أثمت في وفي ولدي وأهلي فأذني لي أطالعهم وأعود إليك فأخذت عليه أيمانا ألا يقيم إلا سنة حتى يعود إليها فخرج من عندها يجر الدنيا حتى قدم على أهله فرأى حال زوجته وما صار إليه ولده وجاء إليه ولده فقال لهم لا والله ما\nبيني وبينكم عمل أنتم قد ورثتموني وأنا حي فهو حظكم والله لا يشرك زوجتي فيما قدمت به أحد ثم قال لها شأنك به فهو لك كله وقال في الشامية\n(صاح حيا الإله حيا ودورا ... عند أصل القناة من جيرون)\n(عن يساري إذا دخلت من الباب ... وإن كنت خارجا عن يميني)\n(فبذاك اغتربت في الشأم حتى ... )\n(ظن أهلي مرجمات الظنون ... )\n(وهي زهراء مثل لؤلؤة الغواص ... ميزت من جوهر مكنون)\n(وإذا ما نسبتها لم تجدها ... في سناء من المكارم دون)\n(تجعل المسك واليلنجوج والند صلاء لها على الكانون ... )\n(ثم ماشيتها إلى القبة الخضراء ... تمشي في مرمر مسنون)\n(وقباب قد أسرجت وبيوت ... نظمت بالريحان والزرجون)\n(قبة من مراجل ضربوها ... عند حد الشتاء في قيطون)\n(ثم فارقتها على خير ما كان ... قرين مفارق لقرين)\n(فبكت خشية التفرق للبين ... بكاء الحزين إثر الحزين)\n(واسألي عن تذكري واطمئني ... لأناسي إذا هم عذلوني)\nفلما حل الأجل أراد الخروج إليها فجاءه موتها فأقام","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":5,"spl":"الرجل الضعيف والمرأة الآثمة","loc":1310,"partialRef":{"sid":"b73-5","gi":1,"vi":1,"side":1},"partial":1},
{"id":"b73-8","bab":"الجزء 7","sec":"أبو دهبل وابن الأزرق","page":"ج7 ص143","text":"أخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني عمي مصعب قال وفد أبو دهبل الجمحي على ابن الأزرق عبد الله بن عبد الرحمن بن\nالوليد بن عبد شمس بن المغيرة بن عبد الله بن عمر بن مخزوم وكان يقال له ابن الأزرق والهبرزي وكان عاملا لعبد الله بن الزبير على اليمن فأنكره ورأى منه جفوة فمضى إلى عمارة بن عمرو بن حزم وهو عامل لعبد الله بن الزبير على حضرموت فقال يمدحه ويعرض بابن الأزرق\n(يا رب حي بخير ما ... حييت إنسانا عماره)\n(أعطى فأسنانا ولم ... يك من عطيته الصغاره)\n(ومن العطية ما ترى ... جذماء ليس لها نزاره)\n(حجرا تقلبه وهل ... تعطي على المدح الحجارة)\n(كالبغل يحمد قائما ... وتذم مشيته المصارة)\nثم رجع من عند عمارة بن عمرو بن حزم فقدم فقال له حنين مولى ابن الأزرق في السر أرى أنك عجلت على ابن عمك وهو أجود الناس وأكرمهم فعد إليه فإنه غير تاركك واعلم أنا نخاف أن يكون قد عزل فلازمه ولا يفقدك فإني أخاف أن ينساك ففعل وأعطاه وأرضاه فقال في ذلك\n(يا حن إني لما حدثتني أصلا ... مرنح من صميم الوجد معمود)\n(نخاف عزل امرىء كنا نعيش به ... معروفه إن طلبنا الجود موجود)\n(اعلم بأني لمن عاديت مضطغن ... ضبا وأني عليك اليوم محسود)\n(وأن شكرك عندي لا انقضاء له ... ما دام بالهضب من لبنان جلمود)\n(أنت الممدح والمغلي به ثمنا ... إذ لا تمدح صم الجندل السود)\n(إن تغد من منقلي نجران مرتحلا ... يرحل من اليمن المعروف والجود)\n(ما زلت في دفعات الخير تفعلها ... لما اعترى الناس لأواء ومجهود)\n(حتى الذي بين عسفان إلى عدن ... لحب لمن يطلب المعروف أخدود)\nقال وأنشدنيها محمد بن الضحاك بن عثمان قال سمعتها من أبي أخبرني الحرمي بن أبي العلاء قال أخبرني الزبير بن بكار وحدثني حمزة بن عتبة قال قال أبو دهبل الجمحي لما قلت أبياتي التي قلت فيها\n(اعلم بأني لمن عاديت مضطغن ... ضبا وأني عليك اليوم محسود)\nقلت فيها نصف بيت ( وأن شكرك عندي لا انقضاء له ...\nثم أرتج علي فأقمت حولين لا أقع على تمامه حتى سمعت رجلا من الحاج في الموسم يذكر لبنان فقلت ما لبنان فقال جبل بالشأم فأتممت نصف البيت\n(ما دام بالهضب من لبنان جلمود ... )\nقال الزبير وحدثني محمد بن حبش المخزومي قال دخل نصيب على إبراهيم بن هشام وهو وال على المدينة فأنشده\nقصيدة مدحه فيها فقال إبراهيم بن هشام ما هذا بشيء أين هذا من قول أبي دهبل لصاحبنا ابن الأزرق حيث قال\n(إن تغد من منقلي نجران مرتحلا ... يبن من اليمن المعروف والجود)\nفغضب نصيب فحمي فنزع عمامته وطرحها وبرك عليها ثم قال إن تأتونا برجال مثل ابن الأزرق نأتكم بمديح أجود من مديح أبي دهبل قال الزبير وحدثني عبد الرحمن بن عبد الله بن عبد العزيز الزهري قال حدثني إسماعيل بن يعقوب بن مجمع التيمي قال كان إبراهيم بن هشام جبارا وكان يقيم بلا إذن إذ كان على المدينة الأشهر فإذا أذن للناس أذن معهم لشاعر فينشد قصيدة مديح لهشام بن عبد الملك وقصيدة مديح لإبراهيم بن هشام فأذن لهم يوما وكان الشاعر الذي أذن له معهم نصيبا وعليه جبة وشي فاستأذنه في الإنشاد فأذن له فأنشده قصيدة لهشام به عبد الملك ثم قطعها وأنشد قصيدة مديح لإبراهيم بن هشام وقصيدة هشام أشعر فأراد الناس ممالحة نصيب فقالوا ما أحسن هذا يا أبا محجن أعد هذا البيت فقال إبراهيم أكثرتم إنه لشاعر وأشعر منه الذي يقول في ابن الأزرق\n(إن تمس من منقلي نجران مرتحلا ... يبن من اليمن المعروف والجود)\n(ما زلت في دفعات الخير تفعلها ... لما اعترى الناس لأواء ومجهود)\nوحمي نصيب فقال إنا والله ما نصنع المديح إلا على قدر الرجال كما يكون الرجل يمدح فعم الناس الضحك وحلم عنه وقال الحاجب ارتفعوا فلما صاروا في السقيفة ضحكوا وقالوا أرأيتم مثل شجاعة هذا\nالأسود على هذا الجبار وحلم من غير حلم قال الزبير وحدثني عمي مصعب قال خرج أبو دهبل يريد ابن الأزرق فلقيه معزولا فشق ذلك عليه واسترجع فقال له ابن الأزرق هون عليك لم يفتك شيء فأعطاه مائتي دينار فقال في ذلك أبو دهبل\n(أعطى أميرا ومنزوعا وما نزعت ... عنه المكارم تغشاه وما نزعا)","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":6,"spl":"أبو دهبل وابن الأزرق","loc":1311,"partial":1},
{"id":"b73-9","bab":"الجزء 7","sec":"أبو دهبل وابن الأزرق","page":"ج7 ص143","text":"وحدثني محمد بن الضحاك مثل ذلك وأنشدني البيت وأخبرني محمد بن خلف بن المرزبان قال حدثني أبو توبة صالح بن محمد بن دراج قال حدثنا أبو عمرو الشيباني قال ولى عبد الله بن الزبير ابنا لسعد بن أبي وقاص يقال له إبراهيم مكان الثبت بن عبد الرحمن بن الوليد الذي يقال له ابن الأزرق فخرج حتى نزل بزبيد فقال لابن الأزرق هلم حسابك فقال مالك عندي حساب ولا بيني وبينك عمل وخرج متوجها إلى مكة فاستأذنه أبو دهبل في صحبة الوقاصي فأذن له فرجع معه حتى إذا دخلوا صنعاء لقيهم بحير بن ريسان في نفر كثير من الفرس وغيرهم ومضى ابن الأزرق ومعه ما احتمله من أموال\nاليمن فسار يوما ثم نزل فضرب رواقه ودعا الناس فأعطاهم ذلك المال حتى لم يبق منه درهم فقال أبو دهبل\n(أعطى أميرا ومنزوعا وما نزعت ... عنه المكارم تغشاه وما نزعا)\nوأقام أبو دهبل مع الوقاصي فلم يصنع به خيرا فقال أبو دهبل\n(ماذا رزئنا غداة الخل من رمع ... عند التفرق من خيم ومن كرم)\n(ظل لنا واقفا يعطي فأكثر ما ... سمى وقال لنا في قوله نعم)\nنعم حرف موقوف فإذا حرك أجريت حركته إلى الخفض لأنه أولى بالساكن\n(ثم انتحى غير مذموم وأعيننا ... لما تولى بدمع واكف سجم)\n(تحمله الناقة الأدماء معتجرا ... بالبرد كالبدر جلى ليلة الظلم)\n(وكيف أنساك لا أيديك واحدة ... عندي ولا بالذي أوليت من قدم)\n(حتى لقينا بحيرا عند مقدمنا ... في موكب كضياع الجزع مرتكم)\n(لما رأيت مقامي عند بابهم ... وددت أني بذاك الباب لم أقم)\nوبحير بن ريسان الذي يقول فيه أبو دهبل\n(بحير بن ريسان الذي سكن الجند ... يقول له الناس الجواد ومن ولد)\n(له نفحات حين يذكر فضله ... كسيل ربيع في ضحاضحة السند)\nي هذين البيتين هزج بالبنصر ذكر عمرو بن بانة أنه ليمان وذكر الهشامي أنه لابن جامع أخبرني محمد بن خلف بن المرزبان قال حدثنا أبو توبة عن أبي عمرو الشيباني قال كان ابن الزبير بعث عبد الله بن عبد الرحمن على بعض أعمال اليمن فمد يده إلى أموالها وأعطى أعطية سنية وبث في قريش منها أشياء جزيلة فأثنت عليه قريش ووفدوا إليه فأسنى لهم العطايا وبلغ ذلك عبد الله بن الزبير فحسده وعزله بإبراهيم بن سعد بن أبي وقاص فلما قدم عليه أراد أن يحاسبه فقال له مالك عندي حساب ولا بيني وبينك عمل وقدم مكة فخافت قريش ابن الزبير عليه أن يفتشه أو يكشفه فلبست السلاح وخرجت إليه لتمنعه فلما لقيهم نزلت إليه قريش فسلمت عليه وبسطت له أرديتها وتلقته إماؤهم وولائدهم بمجامر الألوة والعود المندلي يبخرون بين يديه حتى انتهى إلى المسجد وطاف بالبيت ثم جاء إلى ابن الزبير فسلم عليه وهم معه مطيفون به فعلم ابن الزبير أنه لا سبيل له إليه فما عرض ولا صرح له بشيء ومضى إلي منزله فقال أبو دهبل\n(فمن يك شان العزل أو هد ركنه ... لأعدائه يوما فما شانك العزل)\n(وما أصبحت من نعمة مستفادة ... ولا رحم إلا عليها لك الفضل)\nوقال أبو دهبل أيضا فيه أخبرني بذلك ابن المرزبان عن أبي توبة عن أبي عمرو الشيباني وأخبرني به الحرمي عن الزبير عن عمه\n(عقم النساءفلم يلدن شبيهه ... إن النساء بمثله عقم)\n(متهلل بنعم بلا متباعد ... سيان منه الوفر والعدم)\n(نزر الكلام من الحياء تخاله ... ضمنا وليس بجسمه سقم)","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":7,"spl":"أبو دهبل وابن الأزرق","song":1,"loc":1312},
{"id":"b73-10","bab":"الجزء 7","sec":"أبو دهبل وسليمان بن عبد الملك","page":"ج7 ص150","text":"أخبرني محمد بن خلف قال حدثنا أبو توبة عن أبي عمرو قال قال أبو دهبل يمدح ابن الأزرق\n(بأبي وأمي غير قول الباطل ... الكامل ابن الكامل ابن الكامل)\n(والحازم الأمر الكريم برأيه ... والواصل الأرحام وابن الواصل)\n(جمع الرياسة والسماح كليهما ... جمع الجفير قداح نبل النابل)\nخبرني محمد بن خلف قال حدثني محمد بن عمر قال حدثني سليمان ابن عباد قال حدثني أبو جعفر الشويفعي رجل من أهل مكة قال قدم سليمان بن عبد الملك مكة في حر شديد فكان ينقل سريره بفناء الكعبة وأعطى الناس العطاء فلما بلغ بني جمح نودي بأبي دهبل فقال سليمان أين أبو دهبل الشاعر علي به فأتي به فقال سليمان أنت أبو دهبل الشاعر قال نعم قال فأنت القائل\n(فتنة يشعلها ورادها ... حطب النار فدعها تشتعل)\n(فإذا ما كان أمن فأتهم ... وإذا ما كان خوف فاعتزل)\nقال نعم قال وأنت القائل\n(يدعون مروان كيما يستجيب لهم ... وعند مروان خار القوم أو رقدوا)\n(قد كان في قوم موسى قبلهم جسد ... عجل إذا خار فيهم خورة سجدوا)\nقال نعم قال أنت القائل هذا ثم تطلب ما عندنا لا والله ولا كرامة فقال يا أمير المؤمنين إن قوما فتنوا فكافحوكم بأسيافهم وأجلبوا عليكم بخيلهم ورجلهم ثم أدالكم الله منهم فعفوتم عنهم وإنما فتنت فقلت بلساني فلم لا يعفى عني فقال سليمان قد عفونا عنك وأقطعه قطيعة بحاذان باليمن فقيل لسليمان كيف أقطعته هذه القطيعة قال أردت أن أميته وأميت ذكره بها أخبرني محمد بن خلف قال حدثنا أحمد بن زهير قال حدثنا المدائني عن جماعة من الرواة أن أبا دهبل كان يهوى امرأة من قومه يقال لها عمرة وكانت امرأة جزلة يجتمع الرجال عندها لإنشاد الشعر والمحادثة وكان أبو دهبل لا يفارق مجلسها مع كل من يجتمع إليها وكانت هي أيضا محبة له وكان أبو دهبل من أشراف بني جمح وكان يحمل الحمالة وكان مسودا وزعمت بنو جمح أنه تزوجها بعد وزعم غيرهم من الرواة أنه لم يصل إليها ولم يجر بينهما حلال ولا حرام قال وكانت عمرة تتقدم إلى أبي دهبل في حفظ ما بينهما وكتمانه فضمن ذلك لها فجاء نسوة كن يتحدثن إليها فذكرن لها شيئا من أبي دهبل وقلن قد علق امرأة قالت وما ذاك قلن ذكر أنه عاشق لك وأنك عاشقة له فرفعت مجلسها ومجالسة الرجال ظاهرة وضربت حجابا بينهم وبينها وكتبت إلى أبي دهبل تعذله وتخبره بما بلغها من سوء صنيعه فعند ذلك يقول\n(تطاول هذا الليل ما يتبلج ... وأعيت غواشي عبرتي ما تفرج)\n(وبت كئيبا ما أنام كأنما ... خلال ضلوعي جمرة تتوهج)\n(فطورا أمني النفس من عمرة المنى ... وطورا إذا ما لج بي الحزن أنشج)\n(لقد قطع الواشون ما كان بيننا ... ونحن إلى أن يوصل الحبل أحوج)\n(رأوا غرة فاستقبلوها بألبهم ... فراحوا على ما لا نحب وأدلجوا)\n(وكانوا أناسا كنت آمن غيهم ... فلم ينههم حلم ولم يتحرجوا)\n(هم منعونا ما نحب وأوقدوا ... علينا وشبوا نار صرم تأجج)\n(ولو تركونا لا هدى الله سعيهم ... ولم يلحموا قولا من الشر ينسج)\n(لأوشك صرف الدهر يفرق بيننا ... وهل يستقيم الدهر والدهر أعوج)\n(عسى كربة أمسيت فيها مقيمة ... يكون لنا منها نجاة ومخرج)\n(فيكبت أعداء ويجذل آلف ... له كبد من لوعة الحب تنضج)\n(وقلت لعباد وجاء كتابها ... لهذا وربي كانت العين تخلج)\n(وخططت في ظهر الحصير كأنني ... أسير يخاف القتل ولهان ملفج)\n(فلما التقينا لجلجت في حديثها ... ومن آية الصرم الحديث الملجلج)\n(وإني لمحجوب عشية زرتها ... وكنت إذا ما جئتها لا أعرج)\n(وأعيا علي القول والقول واسع ... وفي القول مستن كثير ومخرج)\nأخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني خالد بن بكر الصواف قال أتيت ابن أبي العراقيب فسألته أن يدخلني على جارية مغنية لم ير أحد مثلها قط فقال لي إن في البيت والله شيخين كريمين علي لا أدري ما يوافقهما من دخول أحد عليهما فلو أقمت حتى أطلع رأيهما في ذلك فدخل ثم خرج إلي فقال ادخل فدخلت فإذا أبو السائب المخزومي وأبو\nجندب الهذلي وخرجت علينا الجارية قاطبة عابسة فلما وضع العود في حجرها اندفعت تغني وتقول\n(عسى كربة أمسيت فيها مقيمة ... يكون لنا منها نجاة ومخرج)\n(وإني لمحجوب غداة أزورها ... وكنت إذا ما زرتها لا أعرج)","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":8,"spl":"أبو دهبل وسليمان بن عبد الملك","loc":1313},
{"id":"b73-12","bab":"الجزء 7","sec":"أبو دهبل وسليمان بن عبد الملك — نسبة ما في هذه القصيدة من الغناء","page":"ج7 ص150 – ج7 ص152","text":"قال ثم بكت فوثبا عليه جميعا فقالا له لعلك أربتها بشيء عليك وعلينا إن لم تقم إليها حتى تقبل رأسها وتترضاها ففعل\n\n(تطاول هذا الليل ما يتبلج ... وأعيت غواشي عبرتي ما تفرج)\n(أخطط في ظهر الحصير كأنني ... أسير يخاف القتل ولهان ملفج)\nلغناء لمعبد ثقيل أول بالوسطى عن عمرو وفيه لحن لمالك ذكره حماد عن أبيه في أخبار مالك ولم يجنسه وحكي أن مالكا كان إذا سئل عنه يذكر أنه أخذه من حائد بن جرهد فقومه وأصلحه وفيه لأبي عيسى بن الرشيد ثاني ثقيل بالوسطى عن حبش والهشامي\n(لقد قطع الواشون ما كان بيننا ... ونحن إلى أن يوصل الحبل أحوج)\n(فطورا أمني النفس من عمرة المنى ... وطورا إذا ما لج بي الهم أنشج)\nلغناء لمالك ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وذكر حبش أن فيه لمعبد خفيف ثقيل بالوسطى","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":9,"spl":"أبو دهبل وسليمان بن عبد الملك — نسبة ما في هذه القصيدة من الغناء","song":2,"loc":1314},
{"id":"b73-13","bab":"الجزء 7","sec":"رثاء الحسين بن علي","page":"ج7 ص153","text":"أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قال قال أبو دهبل في قتل الحسين بن علي صلوات الله عليه وزكواته\n(تبيت سكارى من أمية نوما ... وبالطف قتلى ما ينام حميمها)\n(وما أفسد الإسلام إلا عصابة ... تأمر نوكاها ودام نعيمها)\n(فصارت قناة الدين في كف ظالم ... إذا اعوج منها جانب لا يقيمها)\nال الزبير وحدثني يحيى بن مقداد بن عمران بن يعقوب الزمعي قال حدثني عمي موسى ين يعقوب قال أنشدني أبو دهبل قصيدته التي يقول فيها\n(سقى الله جازانا فمن حل وليه ... فكل فسيل من سهام وسردد)\nرثاء الحسين بن علي أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قال قال أبو دهبل في قتل الحسين بن علي صلوات الله عليه وزكواته\n(تبيت سكارى من أمية نوما ... وبالطف قتلى ما ينام حميمها)\n(وما أفسد الإسلام إلا عصابة ... تأمر نوكاها ودام نعيمها)\n(فصارت قناة الدين في كف ظالم ... إذا اعوج منها جانب لا يقيمها)\nال الزبير وحدثني يحيى بن مقداد بن عمران بن يعقوب الزمعي قال حدثني عمي موسى ين يعقوب قال أنشدني أبو دهبل قصيدته التي يقول فيها\n(سقى الله جازانا فمن حل وليه ... فكل فسيل من سهام وسردد)\n(ومحصوله الدار التي خيمت بها ... سقاها فأروى كل ربع وفدفد)\n(فأنت التي كلفتني البرك شاتيا ... وأوردتنيه فانظري أي مورد)\n\n(فواندمي أن لم أعج إذ تقول لي ... تقدم فشيعنا إلى ضحوة الغد)\n(تكن سكنا أو تقدر العين أنها ... ستبكي مرارا فاسل من بعد واحمد)\n(فأصبحت مما كان بيني وبينها ... سوى ذكرها كالقابض الماء باليد)\nلغناء لابن سريج خفيف رمل بالوسطى عن عمرو وفيه لبذل الكبير رمل عن الهشامي\n(لعلك أن تلقى محبا فتشتفي ... برؤية ريم بضة المتجرد)\n(بلاد العدا لم تأتها غير أنها ... بها هم نفسي من تهام ومنجد)\n(وما جعلت ما بين مكة ناقتي ... إلى البرك إلا نومة المتهجد)\n(وكانت قبيل الصبح تنبذ رحلها ... بدومة من لغط القطا المتبدد)\nقال فقلت يا عمي فما يمنعك أن تكتري دابة بدرهمين فتشيعها وتصبح معك فضحك وقال نفع الله بك يابن أخي أما علمت أن الندم توبة وعمك كان أشغل مما تحسب قال الزبير وحدثني عمي مصعب بن عبد الله قال أنشد رجل أبا السائب المخزومي قصيدة أبي دهبل\n(سقى الله جازانا فمن حل وليه ... فكل فسيل من سهام وسردد)\nفلما بلغ قوله\n(فواندمي أن لم أعج إذ تقول لي ... تقدم فشيعنا إلى ضحوة الغد)\nقال أبو السائب ما صنع شيئا ألا اكترى حمارا بدرهمين فشيعهم ولم يقل فواندمي أو اعتذر وإني أظن أنه قد كان له عذر قال وما هو قال أظنه كان مثلي لا يجد شيئا فقال الزبير وحدثني ابن مقداد قال حدثني عمي موسى بن يعقوب قال أنشدني أبو دهبل قوله\n(ألا علق القلب المتيم كلثما ... لجاجا ولم يلزم من الحب ملزما)\n(خرجت بها من بطن مكة بعدما ... أصات المنادي بالصلاة فأعتما)\n(فما نام من راع ولا ارتد سامر ... من الحي حتى جاوزت بي يلملما)\n(ومرت ببطن الليث تهوي كأنما ... تبادر بالإدلاج نهبا مقسما)\nنى في هذه الأبيات ابن سريج خفيف رمل بالبنصر عن الهشامي قال وفيه هزج يمان بالوسطى وذكر عمرو بن بانة أن خفيف الثقيل هو اليماني وفيه لفيل مولى العبلات رمل صحيح عن حماد عن أبيه عن الهشامي وقال الهشامي فيه لحكم ثقيل أول وذكر أبو أيوب المديني في أغاني ابن جامع أن فيه لحنا ولم يجنسه\n(وجازت على البزواء والليل كاسر ... جناحين بالبزواء وردا وأدهما)\n(فما ذر قرن الشمس حتى تبينت ... بعليب نخلا مشرفا أو مخيما)\n(ومرت على أشطان رونق بالضحى ... فما خزرت للماء عينا ولا فما)\n(وما شربت حتى ثنيت زمامها ... وخفت عليها أن تخر وتكلما)\n(فقلت لها قد بنت غير ذميمة ... وأصبح وادي البرك غيثا مديما)\nقال فقلت له ما كنت إلا على الريح فقال يابن أخي إن عمك كان إذا هم فعل وهي الحاجة أما سمعت قول أخي بني مرة\n(إذا أقبلت قلت مشحونة ... أطاعت لها الريح قلعا جفولا)\n(وإن أدبرت قلت مذعورة ... من الربد تتبع هيقا ذمولا)\n(وإن أعرضت خال فيها البصير ... مالا تكلفه أن يميلا)\n(يدا سرح مائل ضبعها ... تسوم وتقدم رجلا زحولا)\n(فمرت على خشب غدوة ... ومرت فويق أريك أصيلا)\n(تخبط بالليل حزانه ... كخبط القوي العزيز الذليلا)","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":10,"spl":"رثاء الحسين بن علي","song":2,"loc":1315},
{"id":"b73-14","bab":"الجزء 7","sec":"أحاديث عن شعره","page":"ج7 ص158","text":"وأخبرني الحرمي قال حدثنا الزبير قال حدثني جعفر بن الحسن اللهبي قال أنشدت ريان السواق قول أبي دهبل\n(أليس عجيبا أن نكون ببلدة ... كلانا بها ثاو ولا نتكلم)\n(ولا تصرميني أن تريني أحبكم ... أبوء بذنب إنني أنا أظلم)\nفقال أحسن أحسن الله إليه ما بعد هذا شيء وفي هذه القصيدة يقول\n\n(أمنا أناسا كنت قد تأمنينهم ... فزادوا علينا في الحديث وأوهموا)\n(وقالوا لنا ما لم يقل ثم كثروا ... علينا وباحوا بالذي كنت أكتم)\n(لقد كحلت عيني القذى لفراقكم ... وعاودها تهتانها فهي تسجم)\n(وأنكرت طيب العيش مني وكدرت ... علي حياتي والهوى متقسم)\nلغناء لابن سريج رمل بالسبابة في مجرى الوسطى عن إسحاق وفيه لابن زرزور الطائفي خفيف ثقيل بالوسطى عن عمرو وفيه خفيفا رمل أحدهما بالوسطى لمتيم والآخر بالبنصر لعريب أخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثني عمي قال حدثني القاسم بن المعتمر الزهري قال قلت لأبي السائب المخزومي يا أبا السائب أما أحسن أبو دهبل حيث يقول\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\n(هبوني امرأ منكم أضل بعيره ... له ذمة إن الذمام كبير)\n(وللصاحب المتروك أفضل ذمة ... على صاحب من أن يضل بعير)\nقال فقال لي وبأبي أنت كنت والله لا أحبك وتثقل علي فأنا الآن أحبك وتخف علي\nوفي هذه الأبيات غناء لابن سريج خفيف رمل بالوسطى عن عمرو وفيه لعلويه رمل بالوسطى من جامع أغانيه وفيه للمازني خفيف ثقيل آخر من رواية الهشامي وذكاء وغيرهما وأول هذا الصوت بيت لم يذكر في الخبر وهو\n(عفا الله عن ليلى الغداة فإنها ... إذا وليت حكما علي تجور)\nخبرني الحرمي قال حدثني الزبير قال حدثني عمي مصعب ومحمد بن الضحاك عن أبيه أن أبا ريحانة عم أبي دهبل كان شديد الخلاف على عبد الله بن الزبير فتوعده عبد الله بن صفوان فلحق بعبد الملك بن مروان فاستمده الحجاج فأمده عبد الملك بطارق مولى عثمان في أربعة آلاف فأشرف أبو ريحانة على أبي قبيس فصاح أبو ريحانة أليس قد أخزاكم الله يا أهل مكة فقال له ابن أبي عتيق بلى والله قد أخزانا الله فقال له ابن الزبير مهلا يابن أخي فقال قلنا لك ائذن لنا فيهم وهم قليل فأبيت حتى صاروا إلى ما ترى من الكثرة قال وقال أبو دهبل في وعيد عبد الله بن صفوان عمه أبا ريحانة واسمه علي بن أسيد بن أحيحة\n(ولا توعد لتقتله عليا ... فإن وعيده كلأ وبيل)\n(ونحن ببطن مكة إذ تداعى ... لرهطك من بني عمرو رعيل)\n(أولو الجمع المقدم حين ثابوا ... إليك ومن يودعهم قليل)\n(فلما أن تفانينا وأودى ... بثروتنا الترحل والرحيل)\n(جعلت لحومنا غرضا كأنا ... لتهلكنا عروبة أو سلول)","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":11,"spl":"أحاديث عن شعره — من المائة المختارة من رواية علي بن يحيى","song":2,"loc":1316},
{"id":"b73-15","bab":"الجزء 7","sec":"وصية أبي دهبل","page":"ج7 ص161","text":"أخبرني محمد بن خلف قال حدثنا أبو توبة عن أبي عمرو الشيباني قال مات ابن الأزرق وأبو دهبل حي فدفن بعليب فلما احتضر أبو دهبل أيضا أوصى أن يدفن عنده وفيه يقول أبو دهبل يرثيه عن أبي عمرو الشيباني\n(لقد غال هذا اللحد من بطن عليب ... فتى كان من أهل الندى والتكرم)\n(فتى كان فيما ناب يوما هو الفتى ... ونعم الفتى للطارق المتيمم)\n(أألحق أني لا أزال على منى ... إذا صدر الحجاج عن كل موسم)\n(سقى الله أرضا أنت ساكن قبرها ... سجال الغوادي من سحيل ومبرم)\nخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثني عمي قال حدثني إبراهيم بن أبي عبد الله قال وقع لأبي دهبل ميراث بمصر فخرج يريده ثم رجع من الطريق فقال\n(اسلمي أم دهبل بعد هجر ... وتقض من الزمان وعمر)\n(واذكري كري المطي إليكم ... بعد ما قد توجهت نحو مصر)\n(لا تخالي أني نسيتك لما ... حال بيش ومن به خلف ظهري)\n(إن تكوني أنت المقدم قبلي ... وأطع يثو عند قبرك قبري)\nقال إبراهيم فوقفت على قبره إلى جانب قبرها بعليب","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":11,"spl":"أحاديث عن شعره — من المائة المختارة من رواية علي بن يحيى","song":1,"loc":1317},
{"id":"b73-16","bab":"الجزء 7","sec":"من المائة المختارة من رواية علي بن يحيى","page":"ج7 ص162","text":"(ألا أيها الشادن الأكحل ... إلى كم تقول ولا تفعل)\n(إلى كم تجود بما لا نريد ... منك وتمنع ما نسأل)\nالشعر للحسين بن الضحاك والغناء لأبي زكار الأعمى ولحنه المختار هزج بالبنصر","topic":"أخبار أبي دهبل ونسبه","topicNo":73,"sp":11,"spl":"أحاديث عن شعره — من المائة المختارة من رواية علي بن يحيى","loc":1318},
{"id":"b74-1","bab":"الجزء 7","sec":"أخبار حسين بن الضحاك ونسبه","page":"ج7 ص163","text":"الحسين بن الضحاك باهلي صليبة فيم ذكر محمد بن داود بن الجراح والصحيح أنه مولى لباهلة وهو بصري المولد والمنشأ من شعراء الدولة العباسية وأحد ندماء الخلفاء من بني هاشم ويقال إنه أول من جالس منهم محمد الأمين شاعر أديب ظريف مطبوع حسن التصرف في الشعر حلو المذهب لشعره قبول ورونق صاف وكان أبو نواس يأخذ معانيه في الخمر فيغير عليها وإذا شاع له شعر نادر في هذا المعنى نسبه الناس إلى أبي نواس وله معان في صفتها أبدع فيها وسبق إليها فاستعارها أبو نواس وأخبارهما في هذا المعنى وغيره تذكر في أماكنها وكان يلقب الخليع والأشقر وهاجى مسلم بن الوليد فانتصف منه وله غزل كثير جيد وهو\nمن المطبوعين الذين تخلو أشعارهم ومذاهبهم جملة من التكلف وعمر عمرا طويلا حتى قارب المائة السنة ومات في خلافة المستعين أو المنتصر وحدثني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال كان حسين بن الضحاك بن ياسر مولى لباهلة وأصله من خراسان فكان ربما اعترف بهذا الولاء وربما جحده وكان يلقب بالأشقر وهو ومحمد ابن حازم الباهلي ابنا خالة وحدثني الصولي عن إبراهيم بن المعلى الباهلي أنه سأله عن نسب حسين بن الضحاك فقال هو حسين بن الضحاك بن ياسر من موالي سليمان ابن ربيعة الباهلي قال الصولي وسألت الطيب بن محمد الباهلي عنه فقال لي هو الحسين بن الضحاك بن فلان بن فلان بن ياسر قديم الولاء وداره في بني مجاشع وفيها ولد الحسين أرانيها صاحبنا سعيد بن مسلم أخبرني علي بن العباس بن أبي طلحة الكاتب ومحمد بن يحيى الصولي قالا حدثنا المغيرة بن محمد المهلبي قال حدثنا حسين بن الضحاك قال أنشدت أبا نواس لما حججت قصيدتي التي قلتها في الخمر وهي\n(بدلت من نفحات الورد بالآء ... ومن صبوحك در الإبل والشاء)\nفلما انتهيت منها إلى قولي\n(حتى إذا أسندت في البيت واحتضرت ... عند الصبوح ببسامين أكفاء)\n(فضت خواتمها في نعت واصفها ... عن مثل رقراقة في جفن مرهاء)\nقال فصعق صعقة أفزعني وقال أحسنت والله يا أشقر فقلت ويلك يا حسن إنك أفزعتني والله فقال بلى والله أفزعتني ورعتني هذا معنى من المعاني التي كان فكري لا بد أن ينتهي إليها أو أغوص عليها وأقولها فسبقتني إليه واختلسته مني وستعلم لمن يروى ألي أم لك فكان والله كما قال سمعت من لا يعلم يرويها له أخبرني بهذا الخبر الحسن بن علي الخفاف قال حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن عبد الله مولى بني هاشم أبو جعفر قال سمعت الحسين بن الضحاك يقول لما قلت قصيدتي\n(بدلت من نفحات الورد بالآء ... )\nأنشدتها أبا نواس فقال ستعلم لمن يرويها الناس ألي أم لك فكان الأمر كما قال رأيتها في دفاتر الناس في أول أشعاره أخبرني جعفر بن قدامة عن أحمد بن أبي طاهر عن أحمد بن صالح عن الحسين بن الضحاك فذكر نحوا منه","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":0,"spl":"أخبار حسين بن الضحاك ونسبه","loc":1319,"partial":1},
{"id":"b74-2","bab":"الجزء 7","sec":"إذا سار المأمون إلى بغداد انحدر ابن الضحاك إلى البصرة","page":"ج7 ص165","text":"أخبرني الصولي قال حدثني عبد الله بن محمد الفارسي عن ثمامة بن\nأشرس قال الصولي وحدثنيه عون بن محمد عن عبد الله بن العباس بن الفضل بن الربيع قال لما قدم المأمون من خراسان وصار إلى بغداد أمر بأن يسمى له قوم من أهل الأدب ليجالسوه ويسامروه فذكر له جماعة فيهم الحسين بن الضحاك وكان من جلساء محمد المخلوع فقرأ أسماءهم حتى بلغ إلى اسم حسين فقال أليس هو ا لذي يقول في محمد\n(هلا بقيت لسد فاقتنا ... أبدا وكان لغيرك التلف)\n(فلقد خلفت خلائفا سلفوا ... ولسوف يعوز بعدك الخلف)\nلا حاجة لي فيه والله لا يراني أبدا إلا في الطريق ولم يعاقب الحسين على ما كان من هجائه له وتعريضه به قال وانحدر حسين إلى البصرة فأقام بها طول أيام المأمون أخبرني عمي والكوكبي بهذا قالا حدثنا عبد الله بن أبي سعد قال حدثنا عبد الله بن الحارث المروزي عن إبراهيم بن عبد الله ابن أخي السندي بن شاهك فذكر مثله سواء قال ابن أبي طاهر فحدثني محمد بن عبد الله صاحب المراكب قال أخبرني أبي عن صالح بن الرشيد قال\nدخلت يوما على المأمون ومعي بيتان للحسين بن الضحاك فقلت يا أمير المؤمنين أحب أن تسمع مني بيتين فقال أنشدهما فأنشدته\n(حمدنا الله شكرا إذ حبانا ... بنصرك يا أمير المؤمنينا)\n(فأنت خليفة الرحمن حقا ... جمعت سماحة وجمعت دينا)\nفقال لمن هذان البيتان يا صالح فقلت لعبدك يا أمير المؤمنين حسين بن الضحاك قال قد أحسن فقلت وله يا أمير المؤمنين أجود من هذا فقال وما هو فأنشدته قوله\n(أيبخل فرد الحسن فرد صفاته ... علي وقد أفردته بهوى فرد)\n(رأى الله عبد الله خير عباده ... فملكه والله أعلم بالعبد)\nقال فأطرق ساعة ثم قال ما تطيب نفسي له بخير بعدما قال في أخي محمد وقال قال أبو الفرج وهذه الأبيات تروى لابن البواب وستذكر في أبوابه إن شاء الله تعالى وعلى أن الذي رواها غلط في روايته غلطا بينا لأنها مشهورة من شعر حسين بن الضحاك وقد روي أيضا في أخباره أنه دفعها إلى ابن البواب فأوصلها إلى ابن المأمون وكان له صديقا ولعل الغلط وقع من هذه الجهة الغناء في الأبيات المذكورة المنسوبة إلى حسين بن الضحاك وإلى ابن البواب الدالية لإبراهيم بن المهدي خفيف ثقيل بالبنصر وفيها لعبيد الله ابن موسى الطائفي رمل بالبنصر\nأخبرني محمد بن يحيى الصولي قال حدثنا أحمد بن يزيد المهلبي عن أبيه عن عمرو بن بانة أنهم كانوا عند صالح بن الرشيد فقال لست تطرح على جواري وغلماني ما أستجيده فقال له ويلك ما أبغضك ابعث إلى منزلي فجىء بالدفاتر واختر منها ما شئت حتى ألقيه عليهم فبعث إلى منزلي فجيء إليه بدفاتر الغناء فأخذ منها دفترا ليتخير مما فيه فمر به شعر الحسين ابن الضحاك يرثي الأمين ويهجو المأمون وهو\n(أطل حزنا وابك الإمام محمدا ... بحزن وإن خفت الحسام المهندا)\n(فلا تمت الأشياء بعد محمد ... ولا زال شمل الملك منها مبددا)\n(ولا فرح المأمون بالملك بعده ... ولا زال في الدنيا طريدا مشردا)\nفقال لي صالح أنت تعلم أن المأمون يجيء إلي في كل ساعة فإذا قرأ هذا ما تراه يكون فاعلا ثم دعا بسكين فجعل يحكه وصعد المأمون من الدرجة ورمى صالح الدفتر فقال المأمون يا غلام الدفتر فأتي به فنظر فيه ووقف على الحك فقال إن قلت لكم ما كنتم فيه تصدقوني قلنا نعم قال ينبغي أن يكون أخي قال لك ابعث فجىء بدفاترك ليتخير ما تطرح فوقف على هذا الشعر فكره أن أراه فأمر بحكه قلنا كذا كان فقال غنه يا عمرو فقلت يا أمير المؤمنين الشعر لحسين بن الضحاك والغناء لسعيد بن جابر فقال وما يكون غنه فغنيته فقال اردده فرددته ثلاث مرات فأمر لي بثلاثين ألف درهم وقال حتى تعلم أنه لم يضررك عندي قال وسعيد بن جابر الذي يقول فيه حسين بن الضحاك وكان نديمه وصديقه\n(يا سعيد وأين مني سعيد ... )\nراثيه في الأمين ولحسين بن الضحاك في محمد الأمين مراث كثيرة جياد وكان كثير التحقق به والموالاة له لكثرة أفضاله عليه وميله إليه وتقديمه إياه وبلغ من جزعه عليه\nأنه خولط فكان ينكر قتله لما بلغه ويدفعه ويقول إنه مستتر وإنه قد وقف على تفرق دعاته في الأمصار يدعون إلى مراجعة أمره والوفاء ببيعته ضنا به وشفقة عليه ومن جيد مراثيه إياه قوله\n(سألونا أن كيف نحن فقلنا ... من هوى نجمه فكيف يكون)\n(نحن قوم أصابنا حدث الدهر ... فظلنا لريبه نستكين)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":1,"spl":"إذا سار المأمون إلى بغداد انحدر ابن الضحاك إلى البصرة","song":2,"loc":1320,"partial":1},
{"id":"b74-3","bab":"الجزء 7","sec":"إذا سار المأمون إلى بغداد انحدر ابن الضحاك إلى البصرة","page":"ج7 ص165","text":"(نتمنى من الأمين إيابا ... لهف نفسي وأين مني الأمين)\nي هذه الأبيات لسعيد بن جابر ثاني ثقيل بالوسطى وفيها لعريب خفيف ثقيل ومن جيد قوله في مراثيه إياه\n(أعزي يا محمد عنك نفسي ... معاذ الله والأيدي الجسام)\n(فهلا مات قوم لم يموتوا ... ودوفع عنك لي يوم الحمام)\n(كأن الموت صادف منك غنما ... أو استشفى بقربك من سقام)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا علي بن محمد النوفلي قال قال لي محمد بن عباد قال لي المأمون وقد قدمت من البصرة كيف ظريف شعرائكم وواحد مصركم قلت ما أعرفه قال ذاك الحسين بن الضحاك أشعر شعرائكم وأظرف ظرفائكم أليس هو الذي يقول\n(رأى الله عبد الله خير عباده ... فملكه والله أعلم بالعبد)\nقال ثم قال لي المأمون ما قال في أحد من شعراء زماننا بيتا أبلغ من\nبيته هذا فاكتب إليه فاستقدمه وكان حسين عليلا وكان يخاف بوادر المأمون لما فرط منه فقلت للمأمون إنه عليل يا أمير المؤمنين علته تمنعه من الحركة والسفر قال فخذ كتابا إلى عامل خراجكم بالبصرة حتى يعطيه ثلاثين ألف درهم فأخذت الكتاب بذلك وأنفذته إليه فقبض المال حدثنا علي بن العباس بن أبي طلحة الكاتب قال سمعت أبا العباس محمد بن يزيد الأزدي يقول حسين بن الضحاك أشعر المحدثين حيث يقول\n(أي ديباجة حسن ... هيجت لوعة حزني)\n(إذ رماني القمر الزاهر ... عن فترة جفن)\n(بأبي شمس نهار ... برزت في يوم دجن)\n(قربتني بالمنى حتى ... إذا ما أخلفتني)\n(تركتني بين ميعاد ... وخلف وتجني)\n(ما أراني لي من الصبوة ... إلا حسن ظني)\n(إنما دامت على الغدر ... لما تعرف مني)\n(أستعيذ الله من إعراض ... من أعرض عني)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":2,"spl":"إذا سار المأمون إلى بغداد انحدر ابن الضحاك إلى البصرة — حسين بن الضحاك والمعتصم","loc":1321},
{"id":"b74-4","bab":"الجزء 7","sec":"حسين بن الضحاك والمعتصم","page":"ج7 ص170","text":"أخبرني علي بن العباس قال حدثني سوادة بن الفيض المخزومي قال حدثني أبو الفيض بن سوادة عن جدي قال لما ولي المعتصم الخلافة سألني عن حسين بن الضحاك فأخبرته\nبإقامته بالبصرة لانحراف المأمون عنه فأمر بمكاتبته بالقدوم عليه فقدم فلما دخل وسلم استأذن في الإنشاد فأذن له فأنشده قوله\n(هلا سألت تلذذ المشتاق ... ومننت قبل فراقه بتلاق)\n(إن الرقيب ليستريب تنفسا ... صعدا اليك وظاهر الإقلاق)\n(ولئن أربت لقد نظرت بمقلة ... عبرى عليك سخينة الآماق)\n(نفسي الفداء لخائف مترقب ... جعل الوداع إشارة بعناق)\n(إذ لا جواب لمفحم متحير ... إلا الدموع تصان بالإطراق)\nحين انتهى إلى قوله\n(خير الوفود مبشر بخلافة ... خصت ببهجتها أبا إسحاق)\n(وافته في الشهر الحرام سليمة ... من كل مشكلة وكل شقاق)\n(أعطته صفقتها الضمائر طاعة ... قبل الأكف بأوكد الميثاق)\n(سكن الأنام إلى إمام سلامة ... عف الضمير مهذب الأخلاق)\n(فحمى رعيته ودافع دونها ... وأجار مملقها من الإملاق)\nحتى أتمها فقال له المعتصم أدن مني فدنا منه فملأ فمه جوهرا من جوهر كان بين يديه ثم أمره بأن يخرجه من فيه فأخرجه وأمر بأن ينظم ويدفع إليه ويخرج إلى الناس وهو في يده ليعلموا موقعه من رأيه ويعرفوا فعله فكان أحسن ما مدح به يومئذ ومما قدمه أهل العلم على سائر ما قالته الشعراء قول حسين بن الضحاك حيث قال\n(قل للألى صرفوا الوجوه عن الهدى ... متعسفين تعسف المراق)\n(إني أحذركم بوادر ضيغم ... درب بحطم موائل الأعناق)\n(متأهب لا يستفز جنانه ... زجل الرعود ولا مع الإبراق)\n(لم يبق من متعرمين توثبوا ... بالشأم غير جماجم أفلاق)\n(من بين منجدل تمج عروقه ... علق الأخادع أو أسير وثاق)\n(وثنى الخيول إلى معاقل قيصر ... تختال بين أحزة ورقاق)\n(يحملن كل مشمر متغشم ... ليث هزبر أهرت الأشداق)\n(حتى إذا أم الحصون منازلا ... والموت بين ترائب وتراق)\n(هرت بطارقها هرير قساور ... بدهت بأكره منظر ومذاق)\n(ثم استكانت للحصار ملوكها ... ذلا وناط حلوقها بخناق)\n(هربت وأسلمت الصليب عشية ... لم يبق غير حشاشة الأرماق)\nال فأمر له المعتصم لكل بيت بألف درهم وقال له أنت تعلم يا حسين أن هذا أكثر ما مدحني به مادح في دولتنا فقبل الأرض بين يديه وشكره وحمل المال معه","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":2,"spl":"إذا سار المأمون إلى بغداد انحدر ابن الضحاك إلى البصرة — حسين بن الضحاك والمعتصم","loc":1322},
{"id":"b74-5","bab":"الجزء 7","sec":"شاعر الخمرة","page":"ج7 ص173","text":"حدثني علي قال حدثني عثمان بن عمر الآجري قال سمعت الرياشي ينشد هذين البيتين ويستحسنهما ويستظرفهما جدا وهما\n(إذا ما الماء أمكنني ... وصفو سلافة العنب)\n(صببت الفضة البيضاء ... فوق قراضة الذهب)\nفقلت له من يقولهما يا أبا الفضل قال أرق الناس طبعا وأكثرهم ملحا وأكملهم ظرفا حسين بن الضحاك أخبرني يحيى بن علي إجازة قال حدثني أبي عن حسين بن الضحاك قال أنشدت أبا نواس قصيدتي\n(وشاطري اللسان مختلق التكريه ... شاب المجون بالنسك)\nحتى بلغت إلى قولي\n(كأنما نصب كأسه قمر ... يكرع في بعض أنجم الفلك)\nقال فأنشدني أبو نواس بعد أيام لنفسه\n(إذا عب فيها شارب القوم خلته ... يقبل في داج من الليل كوكبا)\nقال فقلت له يا أبا علي هذه مصالتة فقال لي أتظن أنه يروى لك في الخمر معنى جيد وأنا حي أخبرني به جعفر بن قدامة عن علي\nابن محمد بن نصر عن أحمد بن حمدون عن حسين بن الضحاك فذكر مثله أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال أنشدت إبراهيم بن المدبر قول حسين بن الضحاك\n(كأنما نصب كأسه قمر ... حاسده بعض أنجم الفلك)\n(حتى إذا رنحته سورتها ... وأبدلته السكون بالحرك)\n(كشفت عن وزة مسنمة ... في لين صينية من الفلك)\nفقال لي إبراهيم بن المدبر إن الحسين كان يزعم أن أبا نواس سرق منه هذا المعنى حين يقول يقبل في داج من الليل كوكبا فإن كان سرقه منه فهو أحق به لأنه قد برز عليه وإن كان حسين سرقه منه فقد قصر عنه","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":3,"spl":"شاعر الخمرة","loc":1323},
{"id":"b74-6","bab":"الجزء 7","sec":"حسين بن الضحاك والواثق","page":"ج7 ص174","text":"أخبرني محمد بن يحيى الخراساني قال حدثني محمد بن مخارق قال لما بويع الواثق بالخلافة ودخل عليه الحسين بن الضحاك فأنشده قصيدته التي أولها\n(ألم يرع الإسلام موت نصيره ... بلى حق أن يرتاع من مات ناصره)\n(سيسليك عما فات دولة مفضل ... أوائله محمودة وأواخره)\n(ثنى الله عطفيه وألف شخصه ... على البر مذ شدت عليه مآزره)\n(يصب ببذل المال حتى كأنما ... يرى بذله للمال نهبا يبادره)\n(وما قدم الرحمن إلا مقدما ... موارده محمودة ومصادره)\nفقال الواثق إن كان الحسين لينطق عن حسن طوية ويمدح بخلوص نية ثم أمر بأن يعطى لكل بيت قاله من هذه القصيدة ألف درهم فأعجبته الأبيات حتى أمر فصنعت فيها عدة ألحان منها لعريب في طريقة الثقيل الأول وأخبرني محمد بن يحيى قال حدثني عون بن محمد قال حدثني محمد ابن عمرو الرومي قال لما ولي الواثق الخلافة أنشده حسين بن الضحاك قصيدة منها\n(سيسليك عما فات دولة مفضل ... أوائله محمودة وأواخره)\n(وما قدم الرحمن إلا مقدما ... موارده محمودة ومصادره)\nقال فأنشدت إسحاق الموصلي هذا الشعر فقال لي نقل حسين كلام أبي العتاهية في الرشيد حتى جاء بألفاظه بعينها حيث يقول\n(جرى لك من هارون بالسعد طائره ... إمام اعتزام لا تخاف بوادره)\n(إمام له رأي حميد ورحمة ... موارده محمودة ومصادره)\nقال فعجبت من رواية إسحاق شعر المحدثين وإنما كان يروي للأوائل ويتعصب على المحدثين وعلى أبي العتاهية خاصة في هذين الشعرين أغاني نسبتها\n\n(جرى لك من هارون بالسعد طائره ... إمام اعتزام لا تخاف بوادره)\n(إمام له رأي حميد ورحمة ... موارده محمودة ومصادره)\n(هو الملك المجبول نفسا على التقى ... مسلمة من كل سوء عساكره)\n(لتغمد سيوف الحرب فالله وحده ... ولي أمير المؤمنين وناصره)\nلشعر لأبي العتاهية على ما ذكره الصولي وقد وجدت هذه القصيدة بعينها في بعض النسخ لسلم الخاسر والغناء لإبراهيم وله فيه لحنان خفيف ثقيل بالبنصر عن عمرو وثاني ثقيل بالبنصر عن الهشامي\n(سيسليك عما فات دولة مفضل ... أوائله محمودة وأواخره)\n(ثنى الله عطفيه وألف شخصه ... على البر مذ شدت عليه مآزره)\nلشعر لحسين بن الضحاك والغناء لعريب ثقيل أول مطلق وفيه لقلم الصالحية خفيف رمل وهو أغرب اللحنين ولحن عريب المشهور أخبرني محمد بن يحيى قال حدثني محمد بن يحيى قال حدثني علي بن الصباح قال حدثني علي بن صالح كاتب الحسن بن رجاء قال حدثني إبراهيم بن الحسن بن سهل قال\nكنا مع الواثق بالقاطول وهو يتصيد فصاد صيدا حسنا وهو في الزو من الإوز والدراج وطير الماء وغير ذلك ثم رجع فتغدى ودعا بالجلساء والمغنين وطرب وقال من ينشدنا فقام الحسين بن الضحاك فأنشده\n(سقى الله بالقاطول مسرح طرفكا ... وخص بسقياه مناكب قصركا)\nحتى انتهى إلى قوله\n(تخين للدراج في جنباته ... وللغر آجال قدرن بكفكا)\n(حتوفا إذا وجهتهن قواضبا ... عجالا إذا أغريتهن بزجركا)\n(أبحت حماما مصعدا ومصوبا ... وما رمت في حاليك مجلس لهوكا)\n(تصرف فيه بين ناي ومسمع ... ومشمولة من كف ظبي لسقيكا)\n(قضيت لبانات وأنت مخيم ... مريح وإن شطت مسافة عزمكا)\n(وما نال طيب العيش إلا مودع ... وما طاب عيش نال مجهود كدكا)\nفقال الواثق ما يعدل الراحة ولذة الدعة شيء فلما انتهى إلى قوله\n(خلقت أمين الله للخلق عصمة ... وأمنا فكل في ذراك وظلكا)\n(وثقت بمن سماك بالغيب واثقا ... وثبت بالتأييد أركان ملككا)\n(فأعطاك معطيك الخلافة شكرها ... وأسعد بالتقوى سريرة قلبكا)\n(وزادك من أعمارنا غير منة ... عليك بها أضعاف أضعاف عمركا)\n(ولا زالت الأقدار في كل حالة ... عداة لمن عاداك سلما لسلمكا)\n(إذا كنت من جدواك في كل نعمة ... فلا كنت إن لم أفن عمري بشكركا)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":4,"spl":"حسين بن الضحاك والواثق","song":3,"loc":1324},
{"id":"b74-7","bab":"الجزء 7","sec":"حسين بن الضحاك والواثق","page":"ج7 ص174","text":"فطرب الواثق فضرب الأرض بمخصرة كانت في يده وقال لله درك يا حسين ما أقرب قلبك من لسانك فقال يا أمير المؤمنين جودك ينطق المفحم بالشعر والجاحد بالشكر فقال له لن تنصرف إلا مسرورا ثم أمر له بخمسين ألف درهم حدثنا علي بن العباس بن أبي طلحة قال حدثنا أبو العباس الرياشي قال حدثنا الحسين بن الضحاك قال دخلت على الواثق ذات يوم وفي السماء لطخ غيم فقال لي ما الرأي عندك في هذا اليوم فقلت يا أمير المؤمنين ما حكم به وأشار إليه قبلي أحمد بن يوسف فإنه أشار بصواب لا يرد وجعله في شعر لا يعارض فقال وما قال فقلت قال\n(أرى غيما تؤلفه جنوب ... وأحسبه سيأتينا بهطل)\n(فعين الرأي أن تدعو برطل ... فتشربه وتدعو لي برطل)\nفقال أصبتما ودعا بالطعام وبالشراب والمغنين والجلساء واصطبحنا أخبرني علي بن العباس قال حدثني الحسين بن علوان قال حدثني العباس بن عبيد الله الكاتب قال كان حسين بن الضحاك ليلة عند الواثق وقد شربوا إلى أن مضى ثلث من الليل فأمر بأن يبيت مكانه فلما أصبح خرج إلى الندماء وهم مقيمون\nفقال لحسين هل وصفت ليلتنا الماضية وطيبها فقال لم يمض شيء وأنا أقول الساعة وفكر هنيهة ثم قال\n(حثت صبوحي فكاهة اللاهي ... وطاب يومي بقرب أشباهي)\n(فاستثر اللهو من مكامنه ... من قبل يوم منغص ناهي)\n(بابنة كرم من كف منتطق ... مؤزر بالمجون تياه)\n(يسقيك من طرفه ومن يده ... سقى لطيف مجرب داهي)\n(كأسا فكأسا كأن شاربها ... حيران بين الذكور والساهي)\nقال فأمر الواثق برد مجلسه كهيئته واصطبح يومه ذلك معهم وقال نحقق قولك يا حسين ونقضي بك كل أرب وحاجة أخبرني محمد بن يحيى الصولي قال حدثني محمد بن مغيرة المهلبي قال حدثنا حسين بن الضحاك قال كانت لي نوبة في دار الواثق أحضرها جلس أو لم يجلس فبينا أنا نائم ذات ليلة في حجرتي إذ جاء خادم من خدم الحرم فقال قم فإن أمير المؤمنين يدعوك فقلت له وما الخبر قال كان نائما وإلى جنبه حظية له فقام وهو يظنها نائمة فألم بجارية له أخرى ولم تكن ليلة نوبتها وعاد إلى فراشه فغضبت حظيته وتركته حتى نام ثم قامت ودخلت حجرتها فانتبه وهو يرى أنها عنده فلم يجدها فقال اختلست عزيزتي ويحكم أين هي فأخبر أنها قامت غضبى ومضت إلى حجرتها فدعا بك فقلت في طريقي\n(غضبت أن زرت أخرى خلسة ... فلها العتبى لدينا والرضا)\n(يا فدتك النفس كانت هفوة ... فاغفريها واصفحي عما مضى)\n(واتركي العذل على من قاله ... وانسبي جوري إلى حكم القضا)\n(فلقد نبهتني من رقدتي ... وعلى قلبي كنيران الغضا)\nقال فلما جئته خبرني القصة وقال لي قل في هذا شيئا ففكرت هنيهة كأني أقول شعرا ثم أنشدته الأبيات فقال أحسنت وحياتي أعدها يا حسين فأعدتها عليه حتى حفظها وأمر لي بخمسمائة دينار وقام فمضى إلى الجارية وخرجت أنا إلى حجرتي أخبرني علي بن العباس بن أبي طلحة قال حدثني الغلابي قال حدثني مهدي بن سابق قال قال لي حسين بن الضحاك كان الواثق يتحظى جارية فماتت فجزع عليها وترك الشرب أياما ثم سلاها وعاد إلى حاله فدعاني ليلة فقال لي يا حسين رأيت فلانة في النوم فليت نومي كان طال قليلا لأتمتع بلقائها فقل في هذا شيئا فقلت\n(ليت عين الدهر عنا غفلت ... ورقيب الليل عنا رقدا)\n(وأقام النوم في مدته ... كالذي كان وكنا أبدا)\n(بأبي زور تلفت له ... فتنفست إليه الصعدا)\n(بينما أضحك مسرورا به ... إذ تقطعت عليه كمدا)\nقال فقال لي الواثق أحسنت ولكنك وصفت رقيب فشكوته ولا ذنب لليل وإنما رأيت الرؤيا نهارا ثم عاد إلى منامه فرقد","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":5,"spl":"حسين بن الضحاك والواثق","loc":1325},
{"id":"b74-8","bab":"الجزء 7","sec":"أخباره مع أبو نواس","page":"ج7 ص180","text":"أخبرني جحظة قال حدثني علي بن يحيى المنجم قال حدثني حسين بن الضحاك وأخبرني به جعفر بن قدامة عن علي بن يحيى عن حسين بن الضحاك قال لقيني أبو نواس ذات يوم عند باب أم جعفر من الجانب الغربي فأنشدته\n(أخوي حي على الصبوح صباحا ... هبا ولا تعدا الصباح رواحا)\n(هذا الشميط كأنه متحير ... في الأفق سد طريقه فألاحا)\n(ما تأمران بسكرة قروية ... قرنت إلى درك النجاح نجاحا)\nهكذا قال جحظة والذي أحفظه\n(ما تأمران بقهوة قروية ... )\nقال فلما كان بعد أيام لقيني في ذلك الموضع فأنشدني يقول\n(ذكر الصبوح بسحرة فارتاحا ... وأمله ديك الصباح صياحا)\nفقلت له حسن يابن الزانية أفعلتها فقال دع هذا عنك فوالله لا قلت في الخمر شيئا أبدا وأنا حي إلا نسب لي أخبرني محمد بن يحيى الصولي قال حدثني محمد بن سعيد قال حدثني أبو أمامة الباهلي عن الحسين بن الضحاك قال محمد بن يحيى وحدثني المغيرة بن محمد المهلبي إن الحسين بن الضحاك شرب يوما عند إبراهيم بن المهدي فجرت بينهما ملاحاة في أمر الدين والمذهب فدعا له إبراهيم بنطع وسيف وقد\nأخذ منه الشراب فانصرف وهو غضبان فكتب إليه إبراهيم يعتذر إليه ويسأله أن يجيئه فكتب إليه\n(نديمي غير منسوب ... إلى شيء من الحيف)\n(سقاني مثل ما يشرب ... فعل الضيف بالضيف)\n(فلما دارت الكأس ... دعا بالنطع والسيف)\n(كذا من يشرب الخمر ... مع التنين في الصيف)\nقال ولم يعد إلى منادمته مدة ثم إن إبراهيم تحمل عليه ووصله فعاد إلى منادمته حدثني عمي قال حدثني ميمون بن هارون قال حدثني حسين بن الضحاك قال كنت أنا وأبو نواس تربين نشأنا في مكان واحد وتأدبنا بالبصرة وكنا نحضر مجالس الأدباء متصاحبين ثم خرج قبلي عن البصرة وأقام مدة واتصل بي ما آل إليه أمره وبلغني إيثار السلطان وخاصته له فخرجت عن البصرة إلى بغداد ولقيت الناس ومدحتهم وأخذت جوائزهم وعددت في الشعراء وهذا كله في أيام الرشيد إلا أني لم أصل إليه واتصلت بابنه صالح فكنت في خدمته فغني يوما بهذا الصوت\n(أأن زم أجمال وفارق جيرة ... وصاح غراب البين أنت حزين)\nفقال لي صالح قل أنت في هذا المعنى شيئا فقلت\n(أأن دب حساد ومل حبيب ... وأورق عود الهجر أنت حبيب)\n(ليبلغ بنا هجر الحبيب مرامه ... هل الحب إلا عبرة ونحيب)\n(كأنك لم تسمع بفرقة ألفة ... وغيبة وصل لا تراه يؤوب)\nفأمر بأن يغنى فيه واتصلت بمحمد بن زبيدة في أيام أبيه وخدمته ثم اتصلت خدمتي له في أيام خلافته أخبرني جعفر بن قدامة قال حدثني أبو العيناء عن الحسين بن الضحاك قال كنت يوما عند صالح بن الرشيد فجرى بيننا كلام على النبيذ وقد أخذ مني الشراب مأخذا قويا فرددت عليه ردا أنكره وتأوله على غير ما أردت فهاجرني فكتبت إليه\n(يابن الإمام تركتني هملا ... أبكي الحياة وأندب الأملا)\n(ما بال عينك حين تلحظني ... ما إن تقل جفونها ثقلا)\n(لو كان لي ذنب لبحت به ... كي لا يقال هجرتني مللا)\n(إن كنت أعرف زلة سلفت ... فرأيت ميتة واحدي عجلا)\nيه خفيف ثقيل ينسب إلى عبد الله بن العلاء وإلى عبد الله بن العباس الربيعي قال فكتب إلي قد تلافى لسانك بشعرك ما جناه في وقت سكرك وقد رضيت عنك رضا صحيحا فصر إلي على أتم نشاطك وأكمل بساطك فعدت إلى خدمته فما سكرت عنده بعدها قال وكانت في حسين عربدة","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":6,"spl":"أخباره مع أبو نواس","song":1,"loc":1326,"partial":1},
{"id":"b74-9","bab":"الجزء 7","sec":"تقلب المأمون عليه","page":"ج7 ص184","text":"وأخبرني ببعضه محمد بن مزيد بن أبي الأزهر ومحمد بن خلف بن المرزبان وألفاظهما تزيد وتنقص وأخبرني ببعضه محمد بن خلف وكيع عن آخره وقصة وصوله إلى المأمون ولم يذكر ما قبل ذلك قال وحدثنا حماد بن إسحاق عن أبيه ولم يقل وكيع عن أبيه واللفظ في الخبر لابن أبي الأزهر وحديثه أتم قال كنت بين يدي المأمون واقفا فأدخل إليه ابن البواب رقعة فيها أبيات وقال إن رأى أمير المؤمينين أن يأذن لي في إنشادها فظنها له فقال هات فأنشده\n(أجرني فإني قد ظمئت إلى الوعد ... متى تنجز الوعد المؤكد بالعهد)\n(أعيذك من خلف الملوك وقد بدا ... تقطع أنفاسي عليك من الوجد)\n(أيبخل فرد الحسن عني بنائل ... قليل وقد أفردته بهوى فرد)\nإلى أن بلغ إلى قوله\n(رأى الله عبد الله خير عباده ... فملكه والله أعلم بالعبد)\n(ألا إنما المأمون للناس عصمة ... مميزة بين الضلالة والرشد)\nفقال المأمون أحسنت يا عبد الله فقال يا أمير المؤمنين أحسن قائلها قال ومن هو فقال عبدك حسين بن الضحاك فغضب ثم قال لاحيا الله من ذكرت ولا بياه ولا قربه ولا أنعم به عينا أليس القائل\n(أعيني جودا وابكيا لي محمدا ... ولا تذخرا دمعا عليه وأسعدا)\n(فلا تمت الأشياء بعد محمد ... ولا زال شمل الملك فيه مبددا)\n(ولا فرح المأمون بالملك بعده ... ولا زال في الدنيا طريدا مشردا)\nهذا بذاك ولا شيء له عندنا فقال له ابن البواب فأين فضل إحسان\nأمير المؤمنين وسعة حلمه وعادته في العفو فأمر بإحضاره فلما حضر سلم فرد عليه السلام ردا جافيا ثم أقبل عليه فقال أخبرني عنك هل عرفت يوم قتل أخي محمد هاشمية قتلت أو هتكت قال لا قال فما معنى قولك\n(وسرب ظباء من ذؤابة هاشم ... هتفن بدعوى خير حي وميت)\n(أرد يدا مني إذا ما ذكرته ... على كبد حرى وقلب مفتت)\n(فلا بات ليل الشامتين بغبطة ... ولا بلغت آمالهم ما تمنت)\nفقال يا أمير المؤمنين لوعة غلبتني وروعة فاجأتني ونعمة فقدتها بعد أن غمرتني وإحسان شكرته فأنطقني وسيد فقدته فأقلقني فإن عاقبت فبحقك وإن عفوت فبفضلك فدمعت عينا المأمون وقال قد عفوت عنك وأمرت بإدرار أرزاقك وإعطائك ما فات منها وجعلت عقوبة ذنبك امتناعي من استخدامك أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبي قال لما أعيت حسين بن الضحاك الحيلة في رضا المأمون عنه رمى بأمره إلى عمرو بن مسعدة وكتب إليه\n(أنت طودي من بين هذي الهضاب ... وشهابي من دون كل شهاب)\n(أنت يا عمرو قوتي وحياتي ... ولساني وأنت ظفري ونابي)\n(أتراني أنسى أياديك البيض ... إذ اسود نائل الأصحاب)\n(أين عطف الكرام في مأقط الحاجة ... يحمون حوزة الآداب)\n(أين أخلاقك الرضية حالت ... في أم أين رقة الكتاب)\n(أنا في ذمة السحاب وأظما ... إن هذا لوصمة في السحاب)\n(قم إلى سيد البرية عني ... قومة تستجر حسن خطاب)\n(فلعل الإله يطفىء عني ... بك نارا علي ذات التهاب)\nقال فلم يزل عمرو يلطف للمأمون حتى أوصله إليه وأدر أرزاقه حدثني الصولي قال حدثني عون بن محمد قال حدثني الحسين بن الضحاك قال غضب المعتصم علي في شيء جرى على النبيذ فقال والله لأؤدبنه وحجبني أياما فكتبت إليه\n(غضب الإمام أشد من أدبه ... وقد استجرت وعذت من غضبه)\n(أصبحت معتصما بمعتصم ... أثنى الإله عليه في كتبه)\n(لا والذي لم يبق لي سببا ... أرجو النجاة به سوى سببه)\n(مالي شفيع غير حرمته ... ولكل من أشفى على عطبه)\nقال فلما قرىء عليه التفت إلى الواثق ثم قال بمثل هذا الكلام يستعطف الكرام ما هو إلا أن سمعت أبيات حسين هذه حتى أزالت ما في نفسي عليه فقال له الواثق هو حقيق بأن يوهب له ذنبه ويتجاوز عنه فرضي عني وأمر بإحضاري قال الصولي فحدثني الحسين بن يحيى أن هذه الأبيات إنما كتب بها إلى المعتصم لأنه بلغه عنه أنه مدح العباس بن المأمون وتمنى له\nالخلافة فطلبه فاستتر وكتب بها إلى المعتصم على يدي الواثق فأوصلها وشفع له فرضي عنه وأمنه فظهر إليه وهجا العباس بن المأمون فقال\n(خل اللعين وما اكتسب ... لا زال منقطع السبب)\n(يا عرة الثقلين لا ... دينا رعيت ولا حسب)\n(حسد الإمام مكانه ... جهلا حذاك على العطب)\n(وأبوك قدمه لها ... لما تخير وانتخب)\n(ما تستطيع سوى التنفس ... والتجرع للكرب)\n(ما زلت عند أبيك منتقص ... المروءة والأدب)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":7,"spl":"تقلب المأمون عليه","loc":1327},
{"id":"b74-10","bab":"الجزء 7","sec":"مع صالح بن الرشيد ومحبوبه محمد","page":"ج7 ص187","text":"أخبرني الحسن بن علي قال حدثنا عمر بن محمد بن عبد الملك الزيات وابن مهرويه قالا كنا عند صالح بن الرشيد ليلة ومعنا حسين بن الضحاك وذلك في خلافة المأمون وكان صالح يهوى خادما له فغاضبه في تلك الليلة فتنحى عنه وكان جالسا في صحن حوله نرجس في قمر طالع حسن فقال للحسين قل في مجلسنا هذا وما نحن فيه أبياتا يغني فيها عمرو بن بانة فقال الحسين\n(وصف البدر حسن وجهك حتى ... خلت أني وما أراك أراكا)\n(وإذا ما تنفس النرجس الغض ... توهمته نسيم شذاكا)\n(خدع للمنى تعللني فيك ... بإشراق ذا ونفحة ذاكا)\n(لأدومن يا حبيبي على العهد ... لهذا وذاك إذ حكياكا)\nقال عمرو فقال لي صالح تغن فيها فتغنيت فيها من ساعتي لحن عمرو في هذه الأبيات ثقيل بالبنصر من روايته وقد حدثني بهذا الخبر علي بن العباس بن أبي طلحة قال حدثني عبيد الله بن زكريا الضرير قال حدثنا الجماز عن أبي نواس قال كنت أتعشق ابنا للعلاء يقال له محمد وكان حسين يتعشق خادما لأبي عيسى بن الرشيد يقال له يسر فزارني يوما فسألته عنه فقال قد كاد قلبي أن يسلو عنه وعن حبه قال وجاءني ابن العلاء صاحبي فدخل علي وفي يده نرجس فجلسنا نشرب وطلع القمر فقلت له يا حسين أيما أحسن القمر أم محمد فأطرق ساعة ثم قال اسمع جواب الذي سألت عنه\n(وصف البدر حسن وجهك حتى ... خلت أني وما أراك أراكا)\n(وإذا ما تنفس النرجس الغض ... توهمته نسيم شذاكا)\n(وأخال الذي لثمت أنيسي ... وجليسي ما باشرته يداكا)\n(فإذا ما لثمت لثمك فيه ... فكأني بذاك قبلت فاكا)\n(خدع للمنى تعللني فيك ... بإشراق ذا ونفحة ذاكا)\n(لأقيمن ما حييت على الشكر ... لهذا وذاك إذ حكياكا)\nقال فقلت له أحسنت والله ما شئت ولكنك يا كشخان هو ذا تقدر أن تقطع الطريق في عملي فقال يا كشخان أو شعري الذي سمعته في حاضر أم بذكر غائب والله للنعل التي يطأ عليها يسر أحسن عندي من صاحبك ومن القمر ومن كل ما أنتم فيه\nأخبرني علي بن العباس قال حدثني أحمد بن سعيد بن عنبسة القرشي الأموي قال حدثني علي بن الجهم قال دخلت يوما على المتوكل وهو جالس في صحن خلده وفي يده غصن آس وهو يتمثل بهذا الشعر\n(بالشط لي سكن أفديه من سكن ... أهدى من الآس لي غصنين في غصن)\n(فقلت إذ نظما إلفين والتبسا ... سقيا ورعيا لفأل فيكما حسن)\n(فالآس لا شك آس من تشوقنا ... شاف وآس لنا يبقى على الزمن)\n(أبشرتماني بأسباب ستجمعنا ... إن شاء ربي ومهما يقضه يكن)\nقال فلما فرغ من إنشادها قال لي وكدت أنشق حسدا لمن هذا الشعر يا علي فقلت للحسين بن الضحاك يا سيدي فقال لي هو عندي أشعر أهل زماننا وأملحهم مذهبا وأظرفهم نمطا فقلت وقد زاد غيظي في الغزل يا مولاي قال وفي غيره وإن رغم أنفك ومت حسدا وكنت قد مدحته بقصيدة وأردت إنشادها يومئذ فلم أفعل وعلمت أني لا أنتفع مع ما جرى بيننا بشيء لا به ولا بالقصيدة فأخرتها إلى وقت آخر","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":8,"spl":"مع صالح بن الرشيد ومحبوبه محمد","song":1,"loc":1328},
{"id":"b74-11","bab":"الجزء 7","sec":"خبره مع خادم المتوكل","page":"ج7 ص189","text":"أخبرني محمد بن يحيى قال حدثني أحمد بن يزيد المهلبي قال حدثني أبي قال\nأحب المتوكل على الله أن ينادمه حسين بن الضحاك وأن يرى ما بقي من شهوته لما كان عليه فأحضره وقد كبر وضعف فسقاه حتى سكر وقال لخادمه شفيع اسقه فسقاه وحياه بوردة وكانت على شفيع ثياب موردة فمد الحسين يده إلى ذراع شفيع فقال له المتوكل يا حسين أتجمش أخص خدمي عندي بحضرتي فكيف لو خلوت ما أحوجك إلى أدب وقد كان المتوكل غمز شفيعا على العبث به فقال الحسين يا سيدي أريد دواة وقرطاسا فأمر له بذلك فكتب بخطه\n(وكالوردة الحمراء حيا بأحمر ... من الورد يمشي في قراطق كالورد)\n(له عبثات عند كل تحية ... بعينيه تستدعي الحليم إلى الوجد)\n(تمنيت أن أسقى بكفيه شربة ... تذكرني ما قد نسيت من العهد)\n(سقى الله دهرا لم أبت فيه ليلة ... خليا ولكن من حبيب على وعد)\nثم دفع الرقعة إلى شفيع وقال له ادفعها إلى مولاك فلما قرأها استملحها وقال أحسنت والله يا حسين لو كان شفيع ممن تجوز هبته لوهبته لك ولكن بحياتي إلا كنت ساقيه باقي يومه هذا واخدمه كما تخدمني وأمر له بمال كثير حمل معه لما انصرف قال أحمد بن يزيد فحدثني أبي قال صرت إلى الحسين بعد انصرافه من عند المتوكل بأيام فقلت له ويلك أتدري ما صنعت قال نعم أدري وما كنت لأدع عادتي بشيء وقد قلت بعدك\n\n(لا رأى عطفة الأحبة ... من لا يصرح)\n(أصغر الساقيين أشكل ... عندي وأملح)\n(لو تراه كالظبي يسنح ... حينا ويبرح)\n(خلت غصنا على كثيب ... بنور يرشح)\nنى عمرو بن بانة في هذه الأبيات ثاني ثقيل بالبنصر وقد أخبرني بهذا الخبر محمد بن العباس اليزيدي وقال حدثني محمد ابن أبي عون قال حضرت المتوكل وعنده محمد بن عبد الله بن طاهر وقد أحضر حسين ابن الضحاك للمنادمة فأمر خادما كان واقفا على رأسه فسقاه وحياه بتفاحة عنبر وقال لحسين قل في هذا شيئا فقال\n(وكالدرة البيضاء حيا بعنبر ... وكالورد يسعى في قراطق كالورد)\n(له عبثات عند كل تحية ... بعينيه تستدعي الحليم إلى الوجد)\n(تمنيت أن أسقى بكفيه شربة ... تذكرني ما قد نسيت من العهد)\n(سقى الله عيشا لم أبت فيه ليلة ... من الدهر إلا من حبيب على وعد)\nفقال المتوكل يحمل إلى حسين لكل بيت مائة دينار فالتفت إليه محمد بن عبد الله بن طاهر كالمتعجب وقال لم ذاك يا أمير المؤمنين فوالله لقد أجاب فأسرع وذكر فأوجع وأطرب فأمتع ولولا أن يد أمير المؤمنين لا تطاولها يد لأجزلت له العطاء ولو أحاط بالطارف والتالد فخجل المتوكل وقال يعطى حسين بكل بيت ألف دينار وقد أخبرني بهذا الخبر ابن قاسم الكوكبي قال حدثنا بشر بن محمد قال وحدثني علي بن الجهم أنه حضر المتوكل وقد أمر شفيعا أن يسقي حسين بن الضحاك وذكر باقي الخبر نحو ما مضى من رواية غيره\nأخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد المبرد وحدثني عمي قال حدثنا عبد الله بن أبي سعد قال أخبرني محمد بن مروان عن محمد بن عمرو الرومي قال اجتمع حسين بن الضحاك وعمرو بن بانة يوما عند ابن شغوف الهاشمي فاحتبسهما عنده وكان لابن شغوف خادم حسن يقال له مقحم وكان عمرو ابن بانة يتعشقه ويسر ذلك من ابن شغوف فلما أكلوا وضع النبيذ قال عمرو ابن بانة للحسين قل في مقحم أبياتا أغن فيها الساعة فقال الحسين\n(وابأبي مقحم لعزته ... قلت له إذ خلوت مكتتما)\n(تحب بالله من يخصك بالود ... فما قال لا ولا نعما)\nوغنى فيه عمرو قال فبينا هم كذلك إذ جاء الحاجب فقال إسحاق لموصلي بالباب فقال له عمرو أعفنا من دخوله ولا تنغص علينا ببغضه وصلفه وثقله ففعل وخرج الحاجب فاعتل على إسحاق حتى انصرف وأقاموا يومهم وباتوا ليلتهم عند ابن شغوف فلما أصبحوا مضى الحسين بن الضحاك إلى إسحاق فحدثه الحديث بنصه فقال إسحاق\n(يابن شغوف أما علمت بما ... قد صار في الناس كلهم علما)\n(دعوت عمرا فبات ليلته ... في كل ما يشتهي كما زعما)\n(حتى إذا ما الظلام ألبسه ... سرى دبيبا فضاجع الخدما)\n(ثمت لم يرض أن يضاجعهم ... سرا ولكن أبدى الذي كتما)\n(ثم تغنى لفرط صبوته ... صوتا شفى من غليله السقما)\n(وابأبي مقحم لعزته ... قلت له إذ خلوت مكتتما)\n(تحب بالله من يخصك بالود ... فما قال لا ولا نعما)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":9,"spl":"خبره مع خادم المتوكل","song":2,"loc":1329},
{"id":"b74-13","bab":"الجزء 7","sec":"خبره مع خادم المتوكل — أشعرهم غزلا","page":"ج7 ص189 – ج7 ص193","text":"ال وشاعت الأبيات في الناس وغنى فها إسحاق أيضا فيما أظن فبلغت ابن شغوف فحلف ألا يدخل عمرا داره أبدا ولا يكلمه وقال فضحني وشهرني وعرضني للسان إسحاق فمات مهاجرا له وقال ابن أبي سعد في خبره إن إسحاق غنى فيها للمعتصم فسأله عن خبرها فحدثه بالحديث فضحك وطرب وصفق ولم يزل يستعيد الصوت والحديث وابن شغوف يكاد أن يموت إلى أن سكر ونام لحن عمرو بن بانة في البيتين اللذين قالهما حسين في مقحم من الثقيل الثاني بالوسطى\nأخبرني علي بن العباس بن أبي طلحة قال حدثني محمد بن موسى بن حماد قال سمعت مهدي بن سابق يقول التقى أبو نواس وحسين بن الضحاك فقال أبو نواس أنت أشعر أهل زمانك في الغزل قال وفي أي ذلك قال ألا تعلم يا حسين قال لا قال في قولك\n(وابأبي مقحم لعزته ... قلت له إذ خلوت مكتتما)\n(تحب بالله من يخصك بالود ... فما قال لا ولا نعما)\n(ثم تولى بمقلتي خجل ... أراد رجع الجواب فاحتشما)\n(فكنت كالمبتغي بحيلته ... برءا من السقم فابتدا سقما)\nفقال الحسين ويحك يا أبا نواس فأنت لا تفارق مذهبك في الخمر البتة قال لا والله وبذلك فضلتك وفضلت الناس جميعا\nأخبرني علي بن العباس قال أنشدنا أبو العباس ثعلب قال أنشدني حماد ابن المبارك صاحب حسين بن الضحاك قال أنشدني حسين لنفسه\n(لا وحبيك لا أصافح ... بالدمع مدمعا)\n(من بكى شجوه استراح ... وإن كان موجعا)\n(كبدي من هواك أسقم ... من أن تقطعا)\n(لم تدع سورة الضنى ... في للسقم موضعا)\nقال ثم قال لنا ثعلب ما بقي من يحسن أن يقول مثل هذا أخبرني علي قال حدثني محمد بن الفضل الأهوازي قال سمعت علي ابن العباس الرومي يقول حسين بن الضحاك أغزل الناس وأظرفهم فقلت حين يقول ماذا فقال حين يقول\n(يا مستعير سوالف الحشف ... اسمع لحلفة صادق الحلف)\n(إن لم أصح ليلي ويا حربي ... من وجنتيك وفترة الطرف)\n(فجحدت ربي فضل نعمته ... وعبدته أبدا على حرف)\nخبرني علي بن العباس الرومي قال حدثني قتيبة عن عمرو السكوني بالكوفة قال حدثني أبي قال حدثني حسين بن الضحاك قال كانت تألفني مغنية وتجيئني دائما وكنت أميل إليها وأستملحها وكان\nيقال لها فتن فكان يجيء معها خادم لمولاتها يحفظها يسمى نجحا وكان بغيضا شرس الخلق فإذا جاء معها توقيته فمرض فجاءتني ومعها غيره فبلغت منها مرادي وتفرجت يومي وليلتي فقلت\n(لا تلمني على فتن ... إنها كاسمها فتن)\n(فإذا لم أهم بها ... فبمن لا بمن إذن)\n(أين لا أين مثلها ... في جميع الورى سكن)\n(طيب نشر إذا لثمت ... وغنج ومحتضن)\n(وال عشرا من الصبوح ... على وجهها الحسن)\n(وعلى لفظها المنون ... للام بالغنن)\n(لست أنسى من الغريرة ... إذ بحت بالشجن)\n(قولها إذ سلبتها ... عن كثيب وعن عكن)\n(ليس يرضيك يا فتى ... من هوى دون أن تهن)\n(فامتزجنا معا ممازجة ... الروح للبدن)\n(وكفينا من أن نراقب ... نجحا إذا فطن)\n(وأمناه أن ينم ... وما كان مؤتمن)\n(كل ما كان من حبيبك ... مستظرف حسن)\nدثني جحظة قال حدثني أبو عبد الله الهشامي أن مخارقا وحسين بن الضحاك تلاحيا في أبي العتاهية وأبي نواس\nأيهما أشعر فاتفقا على اختيار شعر من شعريهما يتخايران فيه فاختار الحسين بن الضحاك شيئا من شعر أبي نواس جيدا قويا لمعرفته بذلك واختار مخارق شيئا من شعر أبي العتاهية ضعيفا سخيفا غزلا كان يغني فيه لا لشيء عرفه منه إلا لأنه استملحه وغنى فيه فخاير به لقلة علمه ولما كان بينه وبين أبي العتاهية من المودة وتخاطرا على مال وتحاكما إلى من يرتضيه الواثق بالله ويختاره لهما فاختار الواثق لذلك أبا محلم وبعث فأحضره وتحاكما إليه بالشعرين فحكم لحسين بن الضحاك فتلكأ مخارق وقال لم أحسن الاختيار للشعر ولحسين أعلم مني بذلك ولأبي العتاهية خير مما اخترت وقد اختار حسين أجود ما قدر عليه لأبي نواس لأنه أعلم مني بالشعر ولكنا نتخاير بالشاعرين ففيهما وقع الجدال فتحاكما فحكم لأبي نواس وقال هو أشعر وأذهب في فنون الشعر وأكثر إحسانا في جميع تصرفه فأمر الواثق بدفع الخطر إلى حسين وانكسر مخارق فما انتفع به بقية يومه","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":10,"spl":"خبره مع خادم المتوكل — أشعرهم غزلا","loc":1330},
{"id":"b74-14","bab":"الجزء 7","sec":"مدح الحسن بن سهل","page":"ج7 ص196","text":"أخبرني ابن أبي طلحة قال حدثني سوادة بن الفيض قال حدثني أبي قال لما اطرح المأمون حسين بن الضحاك لهواه كان في أخيه محمد وجفاه لاذ الحسين بن الضحاك بالحسن بن سهل وطمع أن يصلحه له فقال يمدحه\n(أرى الآمال غير معرجات ... على أحد سوى الحسن بن سهل)\n(يباري يومه غده سماحا ... كلا اليومين بان بكل فضل)\n(أرى حسنا تقدم مستبدا ... ببعد من رياسته وقبل)\n(فإن حضرتك مشكلة بشك ... شفاك بحكمة وخطاب فصل)\n(سليل مرازب برعوا حلوما ... وراع صغيرهم بسداد كهل)\n(ملوك إن جريت بهم أبروا ... وعزوا أن توازنهم بعدل)\n(ليهنك أن ما أرجأت رشد ... وما أمضيت من قول وفعل)\n(وأنك مؤثر للحق فينا ... أراك الله من قطع ووصل)\n(وأنك للجميع حيا ربيع ... يصوب على قرارة كل محل)\nقال فاستحسنها الحسن بن سهل ودعا بالحسين فقربه وآنسه ووصله وخلع عليه ووعده إصلاح المأمون له فلم يمكنه ذلك لسوء رأي المأمون فيه ولما عاجل الحسن من العلة قال علي بن العباس بن أبي طلحة وحدثني أبو العباس أحمد بن الفضل المروزي قال سمعت الحسن بن سهل يقول لحسين بن الضحاك ما عنيت بقولك\n(يا خلي الذرع من شجني ... إنما أشكو لترحمني)\nقال قد بينته قال بأي شيء قال قلت\n(منعك الميسور يؤيسني ... وقليل اليأس يقتلني)\nفقال له أبو محمد إنك لتضيع بالخلاعة ما أعطيته من البراعة","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":11,"spl":"مدح الحسن بن سهل","loc":1331},
{"id":"b74-15","bab":"الجزء 7","sec":"شاعر الغلمان","page":"ج7 ص197","text":"أخبرني علي بن العباس قال حدثني أحمد بن القاسم المري قال حدثنا أبو هفان قال\nسألت حسين بن الضحاك عن خبره المشهور مع الحسن بن سهل في اليوم الذي شرب معه فيه وبات عنده وكيف كان ابتداؤه فقلت له إني أشتهي أن أسمعه منك فقال لي دخلت على الحسن بن سهل في فصل الخريف وقد جاء وسمي من المطر فرش رشا حسنا واليوم في أحسن منظر وأطيبه وهو جالس على سرير آبنوس وعليه قبة فوقها طارمة ديباج أصفر وهو يشرف على بستان في داره وبين يديه وصائف يترددن في خدمته وعلى رأسه غلام كالدينار فسلمت عليه فرد علي السلام ونظر إلي كالمستنطق فأنشأت أقول\n(ألست ترى ديمة تهطل ... وهذا صباحك مستقبل)\nفقال بلى فقلت\n(وتلك المدام وقد شاقنا ... برؤيته الشادن الأكحل)\nفقال صدقت فمه فقلت\n(فعاد به وبنا سكرة ... تهون مكروه ما نسأل)\nفسكت فقلت\n(فإني رأيت له نظرة ... تخبرني أنه يفعل)\nثم قال مه فقلت\n(وقد أشكل العيش في يومنا ... فيا حبذا عيشنا المشكل)\nفقال العيش مشكل فما ترى فقلت مبادرة القصف وتقريب الإلف قال على أن تقيم معنا وتبيت عندنا فقلت له لك الوفاء وعليك مثله لي من الشرط قال وما هو قلت يكون هذا الواقف على رأسك\nيسقيني فضحك ثم قال ذلك لك على ما فيه ودعا بالطعام فأكلنا وبالشراب فشربنا أقداحا ولم أر الغلام فسألت عنه فقال لي الساعة يجيء فلم نلبث أن وافاني فسألته أين كان فقال كنت في الحمام وهو الذي حبسني عنك فقلت لوقتي\n(وابأبي أبيض في صفرة ... كأنه تبر على فضه)\n(جرده الحمام عن درة ... تلوح فيها عكن بضه)\n(غصن تبدى يتثنى على ... مأكمة مثقلة النهضه)\n(كأنما الرش على خده ... طل على تفاحة غضه)\n(صفاته فاتنة كلها ... فبعضه يذكرني بعضه)\n(يا ليتني زودني قبلة ... أو لا فمن وجنته عضه)\nفقال لي الحسن قد عمل فيك النبيذ فقلت لا وحياتك فقال هذا شر من ذلك فقلت\n(إسقياني وصرفا ... بنت حولين قرقفا)\n(واسقيا المرهف الغرير ... سقى الله مرهفا)\n(لا تقولا نراه أكلف ... نضوا مخففا)\n(نعم ريحانة النديم ... وإن كان مخطفا)\n(إن يكن أكلفا فإني ... أرى البدر أكلفا)\n(بأبي ما جن السريرة ... يبدي تعففا)\n(حف أصداغه وعقر ... بها ثم صففا)\n(وحشا مدرج القصاص ... بمسك ورصفا)\n(فإذا رمت منه ذاك ... تأبى وعنفا)\n(ليس إلا بأن يرنحه ... السكر مسعفا)\n(باكرا لا تسوفاني ... عدمت المسوفا)\n(أعجلاه وبالفضاضة ... في السقي فاعنفا)\n(واحملا شغبه وإن ... هو زنى وأففا)\n(فإذا هم للمنام ... فقوما وخففا)\nفتغاضب الغلام وقام فذهب ثم عاد فقال لي أقبل على شرابك ودع الهذيان وناولني قدحا وقام أبو محمد ليبول فشربت وأعطاني نقلا فقلت اجعل بدله قبلة فضحك وقال أفعل هذا وقته فبدا له وقال لا أفعل فعاودته فانتهرني فقال له خادم للحسن يقال له فرج بحياتي يا بني أسعفه بما طلب فضحك ثم دنا مني كأنه يناولني نقلا وتغافل فاختلست منه قبلة فقال لي هي حرام عليك فقلت\n(وبديع الدل قصري الغنج ... مره العين كحيل بالدعج)\n(سمته شيئا وأصغيت له ... بعد ما صرف كأسا ومزج)\n(واستخفته على نشوته ... نبرات من خفيف وهزج)\n(فتأبى وتثنى خجلا ... وذرا الدمع فنونا ونشج)\n(لج في لولا وفي سوف ترى ... وكذا كفكف عني وخلج)\n(ذهب الليل وما نولني ... دون أن أسفر صبح وانبلج)\n(هون الأمر عليه فرج ... بتأتيه فسقيا لفرج)\n(خمر النكهة لا من قهوة ... أرج الأصداغ بالمسك أرج)\n(وبنفسي نفس من قال وقد ... كان ما كان حرام وحرج)\nقال ثم أسفر الصبح فانصرفت وعدت من غد إلى الحسن فقال لي كيف كنت في ليلتك وكيف كنت عند نومك فقلت له أأصف ذلك نثرا أم نظما فقال بل نظما فهو أحسن عندي فقلت\n(تألفت طيف غزال الحرم ... فواصلني بعد ما قد صرم)\n(وما زلت أقنع من نيله ... بما تجتنيه بنان الحلم)\n(بنفسي خيال على رقبة ... ألم به الشوق فيما زعم)\n(أتاني يجاذب أردافه ... من البهر تحت كسوف الظلم)\n(تمج سوالفه مسكة ... وعنبرة ريقه والنسم)\n(تضمخ من بعد تجميره ... فطاب من القرن حتى القدم)\n(يقول ونازعته ثوبه ... على أن يقول لشيء نعم)\n(فغض الجفون على خجلة ... وأعرض إعراضة المحتشم)\n(فشبكت كفي على كفه ... وأصغيت ألثم درا بفم)\n(فنهنهني دفع لا مؤيس ... بجد ولا مطمع معتزم)\n(إذا ما هممت فأدنيته ... تثنى وقال لي الويل لم)\n(فما زلت أبسطه مازحا ... وأفرط في اللهو حتى ابتسم)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":12,"spl":"شاعر الغلمان","loc":1332},
{"id":"b74-16","bab":"الجزء 7","sec":"شاعر الغلمان","page":"ج7 ص197","text":"(وحكمني الريم في نفسه ... بشيء ولكنه مكتتم)\n(فواها لذلك من طارق ... على أن ما كان أبقى سقم)\nقال فقال لي الحسن يا حسين يا فاسق أظن ما ادعيته على الطيف في النوم كان في اليقظة مع الشخص نفسه وأصلح الأشياء لنا بعد ما جرى أن نرحض العار عن أنفسنا بهبة الغلام لك فخذه لا بورك لك فيه فأخذته وانصرفت حدثني علي بن العباس قال حدثني أبو العيناء قال أنشدني الحسين بن الضحاك لنفسه في غلام للحسن بن سهل كان اجتمع معه في دار الحسن ثم لقيه بعد ذلك فسلم عليه فلم يكلمه الغلام فقال\n(فديتك ما لوجهك صد عني ... وأبديت التندم بالسلام)\n(أحين خلبتني وقرنت قلبي ... بطرفك والصبابة في نظام)\n(تنكر ما عهدت لغب يوم ... فيا قرب الرضاع من الفطام)\n(لأسرع ما نهيت إلى همومي ... سروري بالزيارة واللمام)\nخبرني حبيب بن نصر المهلبي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثني حسين بن الضحاك الخليع قال كنت في المسجد الجامع بالبصرة فدخل علينا أبو نواس وعليه جبة خز جديدة فقلت له من أين هذه يا أبا نواس فلم يخبرني فتوهمت أنه أخذها من موسى بن عمران لأنه دخل من باب بني تميم فقمت فوجدت موسى قد لبس جبة خز أخرى فقلت له\n(كيف أصبحت يا أبا عمران ... )\nفقال بخير صبحك الله به فقلت\n(يا كريم الإخاء والإخوان ... )\nفقال أسمعك الله خيرا فقلت\n(إن لي حاجة فرأيك فيها ... إننا في قضائها سيان)\nفقال هاتها على اسم الله وبركته فقلت\n(جبة من جبابك الخز حتى ... لا يراني الشتاء حيث يراني)\nقال خذها على بركة الله ومد كمه فنزعتها وجئت وأبو نواس جالس فقال من أين لك هذه فقلت من حيث جاءتك تلك","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":13,"spl":"شاعر الغلمان","loc":1333,"partial":1},
{"id":"b74-17","bab":"الجزء 7","sec":"حسين بن الضحاك والمعتصم","page":"ج7 ص203","text":"أخبرني الحسن بن علي الخفاف قال حدثني محمد بن موسى بن حماد قال أخبرني عبد الله بن الحارث عن إبراهيم بن عبد السلام عن الحسين بن الضحاك قال دخلت أنا ومحمد بن عمرو الرومي دار المعتصم فخرج علينا كالحا قال فتوهمنا أنه أراد النكاح فعجز عنه قال وجاء إيتاخ فقال مخارق وعلويه وفلان وفلان من أشباههما بالباب فقال اعزب عني عليك وعليهم لعنة الله قال فتبسمت إلى محمد بن عمرو وفهم المعتصم تبسمي فقال لي مم تبسمت فقلت من شيء حضرني فقال هاته فأنشدته\n\n(انف عن قلبك الحزن ... باقتراب من السكن)\n(وتمتع بكر طرفك ... في وجهه الحسن)\n(إن فيه شفاء صدرك من لاعج الحزن ... )\nقال فدعا بألفي دينار ألف لي وألف لمحمد فقلت الشعر لي فما معنى الألف لمحمد بن عمرو قال لأنه جاءنا معك ثم أذن لمخارق وعلويه فدخلا فأمرهما بأن يغنيا فيه ففعلا فما زال يعيد هذا الشعر ولقد قام ليبول فسمعته يردده الغناء في هذا الشعر اشترك فيه مخارق وعلويه وهو من الثقيل الأول بالبنصر أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن محمد بن مروان قال كان الحسين بن الضحاك عند أبي كامل المهندس وأنا معهم حاضر فرأى خادما فاستحسنه وأعجبه فقال له بعض أصحابه أتحبه قال نعم والله قال فأعلمه قال هو أعلم بحبي له مني به ثم قال\n(عالم بحبيه ... مطرق من التيه)\n(يوسف الجمال وفرعون ... في تعديه)\n(لا وحق ما أنا من ... عطفه أرجيه)\n(ما الحياة نافعة ... لي على تأبيه)\n(النعيم يشغله ... والجمال يطغيه)\n(فهو غير مكترث ... للذي ألاقيه)\n(تائه تزهده ... في رغبتي فيه)\nقال محمد بن محمد وغنى في هذا الشعر عمرو بن بانة وعريب وسليم وجماعة من المغنين\nحدثني عمي قال حدثني ميمون بن هارون قال كان للحسين بن الضحاك صديق وكان يتعشق جارية مغنية فزاحمه فيها غلام كان في مرودته حسن الوجه فلما خرجت لحيته جعل ينتف ما يخرج منها ومالت القينة إليه لشبابه فشكا ذلك إلى الحسين بن الضحاك وسأله أن يقول فيها شعرا فقال\n(خل الذي عنك لا تسطيع تدفعه ... يا من يصارع من لا شك يصرعه)\n(جاءت طرائق شعر أنت ناتفها ... فكيف تصنع لو قد جاء أجمعه)\n(الله أكبر لا أنفك من عجب ... أأنت تحصد ما ذو العرش يزرعه)\n(تبا لسعيك بل تبا لأمك إذ ... ترعى حمى خالق الأحماء يمنعه)\nوقال فيه أيضا\n(ثكلتك أمك يابن يوسف ... حتام ويحك أنت تنتف)\n(لو قد أتى الصيف الذي ... فيه رؤوس الناس تكشف)\n(فكشفت عن خديك لي ... لكشفت عن مثل المفوف)\n(أو مثل زرع ناله اليرقان ... أو نكباء حرجف)\n(فغدا عليه الزارعون ... ليحصدوه وقد تقصف)\n(فظللت تأسف كالألى ... أسفوا ولم يغن التأسف)\nدثني علي بن العباس قال حدثني عمير بن أحمد بن نصر الكوفي قال حدثني زيد بن محمد شيخنا قال قلت لحسين بن الضحاك وقد قدم إلينا الكوفة يا أبا علي شهرت نفسك وفضحتها في خادم فألا أشتريته فقال فديتك إن الحب لجاج\nكله وكنت أحببت هذا الخادم ووافقني على أن يستبيع لأشتريه فعارضني فيه صالح بن الرشيد فاختلسه مني ولم أقدر على الانتصاف منه وآثره الخادم واختاره وكلانا يحبه إلا أن صالحا يناك ولا أناك والخادم في الوسط بلا شغل فضحكت من قوله ثم سألته أن ينشدني شيئا من شعره فأنشدني\n(إن من لا أرى وليس يراني ... نصب عيني ممثل بالأماني)\n(بأبي من ضميره وضميري ... أبدا بالمغيب ينتجيان)\n(نحن شخصان إن نظرت وروحان ... إذا ما اختبرت يمتزجان)\n(فإذا ما هممت بالأمر أو هم ... بشيء بدأته وبداني)\n(كان وفقا ما كان منه ومني ... فكأني حكيته وحكاني)\n(خطرات الجفون منا سواء ... وسواء تحرك الأبدان)\nفسألته أن يحدثني بأسر يوم مر له معه فقال نعم اجتمعنا يوما فغنى مغن لنا بشعر قلته فيه فاستحسنه كل من حضر ثم تغنى بغيره فقال لي عارضه فقلت بقبلة فقال هي لك فقبلته قبلة وقلت\n(فديت من قال لي على خفره ... وغض من جفنه على حوره)\n(سمع بي شعرك المليح فما ... ينفك شاد به على وتره)\n(حسبك بعض الذي أذعت ولا ... حسب لصب لم يقض من وطره)\n(وقلت يا مستعير سالفة الخشف ... وحسن الفتور من نظره)\n(لا تنكرن الحنين من طرب ... عاود فيك الصبا على كبره)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":14,"spl":"حسين بن الضحاك والمعتصم","song":1,"loc":1334,"partial":1},
{"id":"b74-18","bab":"الجزء 7","sec":"حسين بن الضحاك والمعتصم","page":"ج7 ص203","text":"دثني الصولي وعلي بن العباس قالا حدثنا المغيرة بن محمد المهلبي قال كان حسين بن الضحاك يتعشق خادما لأبي عيسى أو لصالح بن الرشيد أخيه فاجتمعا يوما عند أخي مولى الخادم فجعل حسين يشكو إليه ما به فلا يسمع به ويكذبه ثم سكن نفاره وضحك إليه وتحدثا ساعة فأنشدنا حسين قوله فيه\n(سائل بطيفك عن ليلي وعن سهري ... وعن تتابع أنفاسي وعن فكري)\n(لم يخل قلبي من ذكراك إذ نظرت ... عيني إليك على صحوي ولا سكري)\n(سقيا ليوم سروري إذ تنازعني ... صفو المدامة بين الأنس والخفر)\n(وفضل كأسك يأتيني فأشربه ... جهرا وتشرب كأسي غير مستتر)\n(وكيف أشمله لثمي وألزمه ... نحري وترفعه كفي إلى بصري)\n(فليت مدة يومي إذ مضى سلفا ... كانت ومدة أيامي على قدر)\n(حتى إذا ما انطوت عنا بشاشته ... صرنا جميعا كذا جارين في الحفر)\nدثني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن محمد بن مروان قال حدثني حسين بن الضحاك قال كان صالح بن الرشيد يتعشق غلاما يسمى يسرا خادم أخيه أبي عيسى فكان يراوده عن نفسه فيعده ولا يفي له فأرسله أبو عيسى ذات يوم إلى صالح أخيه في السحر يقول له يا أخي إني قد اشتهيت أن أصطبح اليوم فبحياتي لما ساعدتني وصرت إلي لنصطبح اليوم جميعا فسار يسر إلى صالح أخيه في السحر وهو منتش قد شرب في السحر فأبلغه الرسالة فقال نعم وكرامة اجلس أولا فجلس فقال يا غلام أحضرني عشرة آلاف درهم فأحضرها فقال له يا يسر دعني من مواعيدك ومطلك هذه عشرة آلاف درهم فخذها واقض حاجتي وإلا فليس ها هنا إلا الغضب فقال له يا سيدي إني أقضي الحاجة ولا آخذ المال ثم فعل ما أراد وطاوعه فقضى حاجته وأمر صالح بحمل العشرة الآلاف الدرهم معه قال الحسين ثم خرج إلي صالح من خلوته فقال يا حسين قد رأيت ما كنا فيه فإن حضرك شيء فقل فقلت\n(أيا من طرفه سحر ... ومن ريقته خمر)\n(تجاسرت فكاشفتك ... لما غلب الصبر)\n(وما أحسن في مثلك ... أن ينهتك الستر)\n(وإن لامني الناس ... ففي وجهك لي عذر)\n(فدعني من مواعيدك ... إذ حينك الدهر)\n(فلا والله لا تبرح ... أو ينقضي الأمر)\n(فإما الغضب والذم ... وإما البذل والشكر)\n(ولو شئت تيسرت ... كما سميت يا يسر)\n(وكن كاسمك لا تمنعك ... النخوة والكبر)\n(فلا فزت بحظي منك ... إن ذاع له ذكر)\nال الحسين فضحك ثم قال قد لعمري تيسر يسر كما ذكرت فقلت نعم ومن لا يتيسر بعد أخذه الدية لو أردتني أيضا بهذا لتيسرت فضحك ثم قال نعطيك يا حسين الدية لحضورك ومساعدتك ولا نريدك لما أردنا له يسرا فبئست المطية أنت وأمر لي بها ثم أمر عريب بعد ذلك فغنت في بعض هذا الشعر حدثني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن محمد بن مروان قال حدثني حسين بن الضحاك قال كنت عند عبد الله بن العباس بن الفضل بن الربيع وهو مصطبح وخادم له يسقيه فقال لي يا أبا علي قد استحسنت سقي هذا الغلام فإن حضرك شيء في قصتنا هذه فقل فقلت\n(أحيت صبوحي فكاهة اللاهي ... وطاب يومي لقرب أشباهي)\n(فاستثر اللهو من مكامنه ... من قبل يوم منغص ناهي)\n(بابنة كرم من كف منتطق ... مؤتزر بالمجون تياه)\n(يسقيك من طرفه ومن يده ... سقي لطيف مجرب داهي)\n(كأسا فكأسا كان شاربها ... حيران بين الذكور والساهي)\nقال فاستحسنه عبد الله وغنى فيه لحنا مليحا وشربنا عليه بقية يومنا","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":15,"spl":"حسين بن الضحاك والمعتصم","song":1,"loc":1335},
{"id":"b74-19","bab":"الجزء 7","sec":"والغلمان عندهم نخوة","page":"ج7 ص209","text":"أخبرني علي بن العباس قال حدثني سوادة بن الفيض المخزومي قال حدثني أبي قال خرج حسين بن الضحاك إلى القفص متنزها ومعه جماعة من إخوانه ظرفاء وبلغ يسرا الخادم خروجه فشد في وسطه خنجرا وخرج إليه فجاءه وهو على غفلة فسر به حسين وتلقاه وأقام معه إلى آخر النهار يشربان فلما سكرا جمشه حسين فأخرج خنجره عليه وعربد فأمسك حسين وعاد إلى شرابه وقال في ذلك\n(جمشت يسرا على تسكره ... وقد دهاني بحسن منظره)\n(فهم بالفتك بي فناشده ... في كريم من خير معشره)\n(يا من رأى مثل شادن خنث ... يصول في خدره بزوره)\n(يسحب ذيل القميص صعتره ... وواردات من هدب مئزره)\n(ولا يعاطي نديمه قدحا ... إلا بإبهامه وخنصره)\n(أخاف من كبره بوادره ... أدالني الله من تكبره)\n(قد قلت للشرب إذ بدا فضلا ... في ريطتيه وفي ممصره)\n(ويلي على شادن توعدني ... بسل سكينه وخنجره)\n(أما كفاه ما حز في كبدي ... بسحر أجفانه ومحجره)\n(إذا نسيم الرياح قابلنا ... بالطيب من مسكه وعنبره)\n(هز قواما كأنه غصن ... وارتج ما انحط من مخصره)\nخبرني علي بن العباس قال حدثني سوادة بن الفيض قال حدثني أبي قال حضرت حسين بن الضحاك يوما وقد جاءه يسر فجلس عنده وأخذنا نتحدث مليا ثم غازله حسين فقال له يسر إياك والتعرض لي واربح نفسك فقال حسين\n(أيها النفاث في العقد ... أنا مطوي على الكمد)\n(إنما زخرفت لي خدعا ... قدحت في الروح والجسد)\n(هات يا خداع واحدة ... من كثير قلته وقدي)\n(ليت شعري بعد حلفك لي ... بوفاء العهد بعد غد)\n(ما الذي بالله صيره ... بعد قرب في مدى الأبد)\n(مالأنس كان مبتذلا ... منك لي بالأمس لم يعد)\n(إيه قل لي غير محتشم ... هل دهاني فيك من أحد)\n(حبذا والكأس دائرة ... لهونا والصيد بالطرد)\n(وحديث في القلوب له ... أخذ يصدعن في الكبد)\n(يوم تعطيني وتأخذها ... دون ندماني يدا بيد)\n(فإذا ألويت هيجني ... تلع من ظبية البلد)\n(وإذا أصغيت ذكرني ... نشر كافور على برد)\n(ذاك يوم كان حاسدنا ... فيه معذورا على الحسد)\nدثني الصولي قال حدثنا يزيد بن محمد المهلبي قال حدثنا عمرو بن بانة قال خرجنا مع المعتصم إلى الشام لما غزا فنزلنا في طريقنا بدير مران وهو دير على تلعة مشرفة عالية تحتها مروج ومياه حسنة فنزل فيه المعتصم فأكل ونشط للشرب ودعا بنا فلما شربنا أقداحا قال لحسين بن الضحاك أين هذا المكان من ظهر بغداد فقال لا أين يا أمير المؤمنين والله لبعض الغياض والآجام هناك أحسن من هنا قال صدقت والله وعلى ذلك فقل أبياتا يغن فيها عمرو فقال أما أن أقول شيئا في وصف هذه الناحية بخير فلا أحسب لساني ينطق به ولكني أقول متشوفا إلى بغداد فضحك وقال قل ما شئت\n(يا دير مديان لا عريت من سكن ... هيجت لي سقما يا دير مديانا)\n(هل عند قسك من علم فيخبرنا ... أم كيف يسعف وجه الصبر من بانا)\n(حث المدام فإن الكأس مترعة ... مما يهيج دواعي الشوق أحيانا)\n(سقيا ورعيا لكرخايا وساكنها ... وللجنينة بالروحاء من كانا)\nاستحسنها المعتصم وأمرني ومخارقا فغنينا فيها وشرب على ذلك حتى سكر وأمر للجماعة بجوائز لحن عمرو بن بانة في هذه الأبيات رمل ولحن مخارق هزج ويقال إنه لغيره أخبرني الصولي قال حدثنا يزيد بن محمد قال كان حسين بن الضحاك يميل إلى خادم لأبي عيسى بن الرشيد فعبث به يوما على سكر فأخذ قنينة فضرب بها رأسه فشجه شجة منكرة وشاع خبره وتوجع له إخوانه وعولج منها مدة فجفا الخادم واطرحه وأبغضه ولم يعرض له بعدها فرآه بعد ذلك في مجلس مولاه فعبث به الخادم وغازله فلما أكثر ذلك قال له الحسين\n(تعز بيأس عن هواي فإنني ... إذا انصرفت نفسي فهيهات عن ردي)\n(إذا خنتم بالغيب ودي فما لكم ... تدلون إدلال المقيم على العهد)\n(ولي منك بد فاجتنبني مذمما ... وإن خلت أني ليس لي منك من بد)\nلغناء في هذه الأبيات لعمرو بن بانة وله فيه لحنان رمل وخفيف رمل","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":16,"spl":"والغلمان عندهم نخوة","song":3,"loc":1336},
{"id":"b74-20","bab":"الجزء 7","sec":"تهنئة الواثق بالخلافة","page":"ج7 ص212","text":"حدثني أحمد بن العباس العسكري قال حدثني عبد الله بن المؤمل العسكري قال\nلما ولي الواثق الخلافة جلس للناس ودخل إليه المهنئون والشعراء فمدحوه وهنؤوه ثم استأذن حسين بن الضحاك بعدهم في الإنشاد وكان من الجلساء فترفع عن الإنشاد مع الشعراء فأذن له فأنشده قوله\n(أكاتم وجدي فما ينكتم ... بمن لو شكوت إليه رحم)\n(وإني على حسن ظني به ... لأحذر إن بحت أن يحتشم)\n(ولي عند لحظته روعة ... تحقق ما ظنه المتهم)\n(وقد علم الناس أني له ... محب وأحسبه قد علم)\nوفي هذا رمل لعبد الله بن العباس بن الربيع\n(وإني لمغض على لوعة ... من الشوق في كبدي تضطرم)\n(عشية ودعت عن مقلة ... سفوح وزفرة قلب سدم)\n(فما كان عند النوى مسعد ... سوى العين تمزج دمعا بدم)\n(سيذكر من بان أوطانه ... ويبكي المقيمين من لم يقم)\nوقال فيها يصف السفينة\n(إلى خازن الله في خلقه ... سراج النهار وبدر الظلم)\n(رحلنا غرابيب زفافة ... بدجلة في موجها الملتطم)\n(إذا ما قصدنا لقاطولها ... ودهم قراقيرها تصطدم)\n(سكنا إلى خير مسكونة ... تيممها راغب من أمم)\n(مباركة شاد بنيانها ... بخير المواطن خير الأمم)\n(كأن بها نشر كافورة ... لبرد نداها وطيب النسم)\n(كظهر الأديم إذا ما السحاب ... صاب على متنها وانسجم)\n(مبرأة من وحول الشتاء ... إذا ما طمى وحله وارتكم)\n(فما إن يزال بها راجل ... يمر الهوينى ولا يلتطم)\n(ويمشي على رسله آمنا ... سليم الشراك نقي القدم)\n(وللنون والضب في بطنها ... مراتع مسكونة والنعم)\n(غدوت على الوحش مغترة ... رواتع في نورها المنتظم)\n(ورحت عليها وأسرابها ... تحوم بأكنافها تبتسم)\nثم قال يمدح الواثق\n(يضيق الفضاء به إن غدا ... بطودي أعاريبه والعجم)\n(ترى النصر يقدم راياته ... إذا ما خفقن أمام العلم)\n(وفي الله دوخ أعداءه ... وجرد فيهم سيوف النقم)\n(وفي الله يكظم من غيظه ... وفي الله يصفح عمن جرم)\n(رأى شيم الجود محمودة ... وما شيم الجود إلا قسم)\n(فراح على نعم واغتدى ... كأن ليس يحسن إلا نعم)\nقال فأمر له الواثق بثلاثين ألف درهم واتصلت أيامه بعد ذلك ولم يزل من ندمائه حدثني أحمد بن العباس قال حدثنا محمد بن زكريا الغلابي قال حدثني مهدي بن سابق قال قال الواثق لحسين بن الضحاك قل الساعة أبياتا ملاحا حتى أهب لك شيئا مليحا فقال في أي معنى يا أمير المؤمنين فقال امدد طرفك وقل\nفيما شئت مما ترى بين يديك وصفه فالتفت فإذا ببساط زهره قد تفتحت أنواره وأشرق في نور الصبح فأرتج علي ساعة حتى خجلت وضقت ذرعا فقال لي الواثق مالك ويحك ألست ترى نور صباح ونور أقاح فانفتح القول فقلت\n(ألست ترى الصبح قد أسفرا ... ومبتكر الغيث قد أمطرا)\n(وأسفرت الأرض عن حلة ... تضاحك بالأحمر الأصفرا)\n(ووافاك نيسان في ورده ... وحثك في الشرب كي تسكرا)\n(وتعمل كأسين في فتية ... تطارد بالأصغر الأكبرا)\n(يحث كؤوسهم مخطف ... تجاذب أردافه المئزرا)\n(ترجل بالبان حتى إذا ... أدار غدائره وفرا)\n(وفضض في الجلنار البهار ... والآبنوسة والعبهرا)\n(فلما تمازج ما شذرت ... مقاريض أطرافه شذرا)\n(فكل ينافس في بره ... ليفعل في ذاته المنكرا)\nال فضحك الواثق وقال سنستعمل كل ما قلت يا حسين إلا الفسق الذي ذكرته فلا ولا كرامة ثم أمر بإحضار الطعام فأكل وأكلوا معه ثم قال قوموا بنا إلى حانة الشط فقاموا اليها فشرب وطرب وما ترك يومئذ أحدا من الجلساء والمغنين والحشم إلا أمر له بصلة وكانت من الأيام التي سارت أخبارها وذكرت في الآفاق قال حسين فلما كان من الغد غدوت إليه فقال أنشدني يا حسين شيئا إن كنت قلته في يومنا الماضي فقد كان حسنا فأنشدته\n\n(يا حانة الشط قد أكرمت مثوانا ... عودي بيوم سرور كالذي كانا)\n(لا تفقدينا دعابات الإمام ولا ... طيب البطالة إسرارا وإعلانا)\n(ولا تخالعنا في غير فاحشة ... إذا يطربنا الطنبور أحيانا)\n(وهاج زمر زنام بين ذاك لنا ... شجوا فأهدى لنا روحا وريحانا)\n(وسلسل الرطل عمرو ثم عم به السقيا ... فألحق أولانا بأخرانا)\n(سقيا لشكلك من شكل خصصت به ... دون الدساكر من لذات دنيانا)\n(حفت رياضك جنات مجاورة ... في كل مخترق نهرا وبستانا)\n(لا زلت آهلة الأوطان عامرة ... بأكرم الناس أعراقا وأغصانا)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":17,"spl":"تهنئة الواثق بالخلافة","song":1,"loc":1337},
{"id":"b74-21","bab":"الجزء 7","sec":"تهنئة الواثق بالخلافة","page":"ج7 ص212","text":"ال فأمر له الواثق بصلة سنية مجددة واستحسن الصوت وأمر فغني في عدة أبيات منها غنت فريدة في البيتين الأولين من هذه الأبيات ولحنها هزج مطلق حدثني جعفر بن قدامة قال حدثني علي بن يحيى قال اجتمعت أنا وحسين بن الضحاك وأبو شهاب الشاعر وهو الذي يقول\n(لقد كنت ريحانة في الندي ... وتفاحة في يد الكاعب)\nوعمرو بن بانة يغنيها فتذاكرنا الدواب واتصل الحديث إلى أن\nتلاحى حسين وأبو شهاب في دابتيهما وتراهنا على المسابقة بهما فتسابقا فسبقه أبو شهاب فقال حسين في ذلك\n(كلوا واشربوا هنئتم وتمتعوا ... وعيشوا وذموا الكودنين جميعا)\n(فأقسم ما كان الذي نال منهما ... مدى السبق إذ جد الجراء سريعا)\nهي قصيدة معروفة في شعره فقال أبو شهاب يجيبه\n(أيا شاعر الخصيان حاولت خطة ... سبقت إليها وانكفأت سريعا)\n(تحاول سبقي بالقريض سفاهة ... لقد رمت جهلا من حماي منيعا)\nهي أيضا قصيدة فكان ذلك سبب التباعد بينهما وكنا إذا أردنا العبث بحسين نقول له أيا شاعر الخصيان فيجن ويشتمنا حدثني جعفر قال حدثني علي بن يحيى قال حدثني حسين بن الضحاك قال كان يألفني إنسان من جند الشأم عجيب الخلقة والزي والشكل غليظ جلف جاف فكنت احتمل ذلك كله له ويكون حظي التعجب به وكان يأتيني بكتب من عشيقة له ما رأيت كتبا أحلى منها ولا أظرف ولا أبلغ ولا أشكل من معانيها ويسألني أن أجيب عنها فأجهد نفسي في الجوابات وأصرف عنايتي إليها على علمي بأن الشامي بجهله لا يميز بين الخطأ والصواب ولا يفرق بين الابتداء والجواب فلما طال ذلك علي حسدته وتنبهت إلى إفساد حاله عندها فسألته عن اسمها فقال بصبص فكتبت إليها عنه في جواب كتاب منها جاءني به\n(أرقصني حبك يا بصبص ... والحب يا سيدتي يرقص)\n(أرمصت أجفاني بطول البكا ... فما لأجفانك لا ترمص)\n(وابأبي وجهك ذاك الذي ... كأنه من حسنه عصعص)\nجاءني بعد ذلك فقال لي يا أبا علي جعلني الله فداءك ما كان ذنبي إليك وما أردت بما صنعت بي فقلت له وما ذاك عافاك الله فقال ما هو والله إلا أن وصل ذلك الكتاب إليها حتى بعثت إلي إني مشتاقة إليك والكتاب لا ينوب عن الرؤية فتعال إلى الروشن الذي بالقرب من بابنا فقف بحياله حتى أراك فتزينت بأحسن ما قدرت عليه وصرت إلى الموضع فبينا أنا واقف أنتظر مكلما أو مشيرا إلي إذا شيء قد صب علي فملأني من قرني إلى قدمي وأفسد ثيابي وسرجي وصيرني وجميع ما علي ودابتي في نهاية السواد والنتن والقذر وإذا به ماء قد خلط ببول وسواد سرجين فانصرفت بخزي وكان ما مر بي من الصبيان وسائر من مررت به من الضحك والطنز والصياح بي أغلظ مما مر بي ولحقني من أهلي ومن في منزلي شر من ذلك وأوجع وأعظم من ذلك أن رسلها انقطعت عني جملة قال فجعلت أعتذر إليه وأقول له إن الآفة أنها لم تفهم معنى الشعر لجودته وفصاحته وأنا أحمد الله على ما ناله وأسر الشماتة به","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":18,"spl":"تهنئة الواثق بالخلافة","loc":1338},
{"id":"b74-22","bab":"الجزء 7","sec":"ابن الضحاك يدعى فيلبي ويعتذر","page":"ج7 ص218","text":"أخبرني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون عن حسين ابن الضحاك قال\nكتب إلي الحسن بن رجاء في يوم شك وقد أمر الواثق بالإفطار فقال\n(هززتك للصبوح وقد نهاني ... أمير المؤمنين عن الصيام)\n(وعندي من قيان المصر عشر ... تطيب بهن عاتقة المدام)\n(ومن أمثالهن إذا انتشينا ... ترانا نجتني ثمر الغرام)\n(فكن أنت الجواب فليس شيء ... أحب إلي من حذف الكلام)\nقال فوردت علي رقعته وقد سبقه إلي محمد بن الحارث بن بسخنر ووجه إلي بغلام نظيف الوجه كان يتخطاه ومعه ثلاثة غلمة أقران حسان الوجوه ومعهم رقعة قد كتبها إلي كما تكتب المناشير وختمها في أسفلها وكتب فيها يقول\n(سر على اسم الله يا أشكل ... من غصن لجين)\n(في ثلاث من بني الروم ... إلى دار حسين)\n(فاشخص الكهل إلى مولاك ... يا قرة عيني)\n(أره العنف إذا استعصى ... وطالبه بدين)\n(ودع اللفظ وخاطبه ... بغمز الحاجبين)\n(واحذر الرجعة من وجهك ... في خفي حنين)\nقال فمضيت معهم وكتبت إلى الحسن بن رجاء جواب رقعته\n(دعوت إلى مماحكة الصيام ... وإعمال الملاهي والمدام)\n(ولو سبق الرسول لكان سعيي ... إليك ينوب عن طول الكلام)\n(وما شوقي إليك بدون شوقي ... إلى ثمر التصابي والغرام)\n(ولكن حل في نفر عسوف ... بمنشور محل المستهام)\n(حسين فاستباح له حريما ... بطرف باعث سبب الحمام)\n(وأظهر نخوة وسطا وأبدى ... فظاظته بترك للسلام)\n(وأزعجني بألفاظ غلاظ ... وقد أعطيته طرفي زمامي)\n(ولو خالفته لم يخش قتلي ... وقنعني سريعا بالجسام)\nخبرني الحسين بن القاسم الكوكبي قال حدثني جعفر بن هارون بن زياد قال حدثني أبي قال كان الواثق يلاعب حسين بن الضحاك بالنرد وخاقان غلام الواثق واقف على رأسه وكان الواثق يتحظاه فجعل يلعب وينظر إليه ثم قال للحسين ابن الضحاك إن قلت الساعة شعرا يشبه ما في نفسي وهبت لك ما تفرح به فقال الحسين\n(أحبك حبا شابه بنصيحة ... أب لك مأمون عليك شفيق)\n(وأقسم ما بيني وبينك قربة ... ولكن قلبي بالحسان علوق)\nفضحك الواثق وقال أصبت ما في نفسي وأحسنت وصنع الواثق فيه لحنا وأمر لحسين بألفي دينار لحن الواثق في هذين البيتين من الثقيل الأول بالوسطى أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن خلاد قال أنشدني حسين بن الضحاك لنفسه\n(بدلت من نفحات الورد بالآء ... ومن صبوحك در الإبل والشاء)\nحتى أتى على آخرها وقال لي ما قال أحد من المحدثين مثلها فقلت أنت تحوم حول أبي نواس في قوله\n(دع عنك لومي فإن اللوم إغراء ... وداوني بالتي كانت هي الداء)\nهي أشعر من قصيدتك فغضب وقال ألي تقول هذا علي وعلي إن لم أكن نكت أبا نواس فقلت له دع ذا عنك فإنه كلام في الشعر لا قدح في نسب لو نكت أبا نواس وأمه وأباه لم تكن أشعر منه وأحب أن تقول لي هل لك في قصيدتك ببيت نادر غير قولك\n(فضت خواتمها في نعت واصفها ... عن مثل رقراقة في عين مرهاء)\nوهذه قصيدة أبي نواس يقول فيها\n(دارت على فتية ذل الزمان لهم ... فما أصابهم إلا بما شاؤوا)\n(صفراء لا تنزل الأحزان ساحتها ... لو مسها حجر مسته سراء)\n(فأرسلت من فم الإبريق صافية ... كأنما أخذها بالعقل إغفاء)\nوالله ما قدرت على هذا ولا تقدر عليه فقام وهو مغضب كالمقر بقولي","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":19,"spl":"ابن الضحاك يدعى فيلبي ويعتذر","song":1,"loc":1339},
{"id":"b74-23","bab":"الجزء 7","sec":"يتحاكم مع أبي نواس","page":"ج7 ص221","text":"حدثني الحسن قال حدثنا ابن مهرويه قال حدثني إبراهيم بن المدبر قال حدثني أحمد بن المعتصم قال\nحج أبو نواس وحسين بن الضحاك فجمعهما الموسم فتناشدا قصيدتيهما قول أبي نواس\n(دع عنك لومي فإن اللوم إغراء ... وداوني بالتي كانت هي الداء)\nوقصيدة حسين\n(بدلت من نفحات الورد بالآء ... )\nفتنازعها أيهما أشعر في قصيدته فقال أبو نواس هذا ابن مناذر حاضر الموسم وهو بيني وبينك فأنشده قصيدته حتى فرغ منها فقال ابن مناذر ما أحسب أن أحدا يجيء بمثل هذه وهم بتفضيله فقال له الحسين لا تعجل حتى تسمع فقال هات فأنشده قوله\n(بدلت من نفحات الورد بالآء ... ومن صبوحك در الإبل والشاء)\nحتى انتهى إلى قوله\n(فضت خواتمها في نعت واصفها ... عن مثل رقراقة في عين مرهاء)\nفقال له ابن مناذر حسبك قد استغنيت عن أن تزيد شيئا والله لو لم تقل في دهرك كله غير هذا البيت لفضلتك به على سائر من وصف الخمر قم فأنت أشعر وقصيدتك أفضل فحكم له وقام أبو نواس منكسرا أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد قال حدثني كثير بن إسماعيل التحتكار قال\n(لما قدم المعتصم بغداد سأل عن ندماء صالح بن الرشيد وهم أبو ... )\nالواسع وقنينة وحسين بن الضحاك وحاتم الريش وأنا فأدخلنا عليه فلشؤمي وشقائي كتبت بين عيني سيدي هب لي شيئا فلما رآني قال ما هذا على جبينك فقال حمدون بن إسماعيل يا سيدي تطايب بأن كتب على جبينه سيدي هب لي شيئا فلم يستطب لي ذلك ولا استملحه ودعا بأصحابي من غد ولم يدع بي ففزعت إلى حسين بن الضحاك فقال لي إني لم أحلل من أنسه بعد بالمحل الموجب أن أشفع إليه فيك ولكني أقول لك بيتين من شعر وادفعهما إلى حمدون بن إسماعيل يوصلهما فإن ذلك أبلغ فقلت أفعل فقال حسين\n(قل لدينا أصبحت تلعب بي ... سلط الله عليك الآخره)\n(إن أكن أبرد من قنينة ... ومن الريش فأمي فاجره)\nقال فأخذتهما وعرفت حمدون أنهما لي وسألته إيصالهما ففعل فضحك المعتصم وأمر لي بألفي دينار واستحضرني وألحقني بأصحابي أخبرني عمي قال حدثني هارون بن محمد بن عبد الملك قال قال لي أحمد بن حمدون كان محمد بن الحارث بن بسخنر لا يرى الصبوح ولا يؤثر على الغبوق شيئا ويحتج بأن من خدم الخلفاء كان اصطباحه استخفافا بالخدمة لأنه لا يأمن أن يدعى على غفلة والغبوق يؤمنه من ذلك وكان المعتصم يحب الصبوح فكان يلقب ابن بسخنر الغبوقي فإذا حضر مجلس\nالمعتصم مع المغنين منعه الصبوح وجمع له مثل ما يشرب نظراؤه فإذا كان الغبوق سقاه إياه جملة غيظا عليه فيضج من ذلك ويسأل أن يترك حتى يشرب مع الندماء إذا حضروا فيمنعه ذلك فقال فيه حسين بن الضحاك وفي حاتم الريش الضراط وكان من المضحكين\n(حب أبي جعفر للغبوق ... كقبحك يا حاتم مقبلا)\n(فلا ذاك يعذر في فعله ... وحقك في الناس أن تقتلا)\n(وأشبه شيء بما اختاره ... ضراطك دون الخلا في الملا)\nدثني محمد بن خلف وكيع قال حدثنا محمد بن علي بن حمزة قال مزح أبو أحمد بن الرشيد مع حسين بن الضحاك مزاحا أغضبه فجاوبه حسين جوابا غضب منه أبو أحمد أيضا فمضى إليه حسين من غد فاعتذر إليه وتنصل وحلف فأظهر له قبولا لعذره ورأى ثقلا في طرفه وانقباضا عما كان يعهده منه فقال في ذلك\n(لا تعجبن لملة صرفت ... وجه الأمير فإنه بشر)\n(وإذا نبا بك في سريرته ... عقد الضمير نبا بك البصر)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":20,"spl":"يتحاكم مع أبي نواس","loc":1340,"partialRef":{"sid":"b74-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b74-24","bab":"الجزء 7","sec":"يحكي للنشار صحبته للأمين","page":"ج7 ص224","text":"حدثني الصولي قال حدثني أبو محمد بن النشار قال كان أبي صديقا للحسين بن الضحاك وكان يعاشره فحملني معه يوما إليه وجعل أبي يحادثه إلى أن قال له يا أبا علي قد تأخرت أرزاقك وانقطعت موادك ونفقتك كثيرة فكيف يمشي أمرك فقال له بلى والله يا أخي ما قوام أمري إلا ببقايا هبات الأمين محمد بن زبيدة وذخائره وهبات جارية له لم يسمها أغنتني للأبد لشيء ظريف جرى على غير تعمد وذلك\nأن الأمين دعاني يوما فقال لي يا حسين إن جليس الرجل عشيره وثقته وموضع سره وأمنه وإن جاريتي فلانة أحسن الناس وجها وغناء وهي مني بمحل نفسي وقد كدرت علي صفوها ونغصت علي النعمة فيها بعجبها بنفسها وتجنيها علي وإدلالها بما تعلم من حبي إياها وإني محضرها ومحضر صاحبة لها ليست منها في شيء لتغني معها فإذا غنت وأومأت لك إليها على أن أمرها أبين من أن يخفى عليك فلا تستحسن الغناء ولا تشرب عليه وإذا غنت الأخرى فاشرب واطرب واستحسن واشقق ثيابك وعلي مكان كل ثوب مائة ثوب فقلت السمع والطاعة فجلس في حجرة الخلوة وأحضرني وسقاني وخلع علي وغنت المحسنة وقد أخذ الشراب مني فما تمالكت أن استحسنت وطربت وشربت فأومأ إلي وقطب في وجهي ثم غنت الأخرى فجعلت أتكلف ما أقوله وأفعله ثم غنت المحسنة ثانية فأتت بما لم أسمع مثله قط حسنا فما ملكت نفسي أن صحت وشربت وطربت وهو ينظر إلي ويعض شفتيه غيظا وقد زال عقلي فما أفكر فيه حتى فعلت ذلك مرارا وكلما ازداد شربي ذهب عقلي وزدت مما يكره فغضب فأمضني وأمر بجر رجلي من بين يديه وصرفي فجررت وصرفت فأمر بأن أحجب وجاءني الناس يتوجعون لي ويسألوني عن قصتي فأقول لهم حمل علي النبيذ فأسأت أدبي فقومني أمير المؤمنين بصرفي وعاقبني بمنعي من الوصول إليه ومضى لما أنا فيه شهر ثم جاءتني البشارة أنه قد رضي عني وأمر بإحضاري فحضرت وأنا خائف فلما وصلت أعطاني الأمين يده فقبلتها وضحك إلي وقام وقال اتبعني ودخل إلى تلك الحجرة بعينها ولم يحضر غيري وغنت المحسنة التي نالني من أجلها ما نالني فسكت فقال لي قل ما شئت ولا تخف فشربت واستحسنت ثم قال لي يا حسين لقد خار الله لك بخلافي وجرى القدر بما تحب فيه إن هذه الجارية عادت إلى الحال التي أريد منها ورضيت كل أفعالها فأذكرتني بك وسألتني الرضا عنك والاختصاص لك وقد فعلت ووصلتك بعشرة آلاف دينار ووصلتك هي\nبدون ذلك والله لو كنت فعلت ما قلت لك حتى تعود إلى مثل هذه الحال ثم تحقد ذلك عليك فتسألني ألا تصل إلي لأجبتها فدعوت له وشكرته وحمدت الله على توفيقه وزدت في الاستحسان والسرور إلى أن سكرت وانصرفت وقد حمل معي المال فما كان يمضي أسبوع إلا وصلاتها وألطافها تصل إلي من الجوهر والثياب والمال بغير علم الأمين وما جالسته مجلسا بعد ذلك إلا سألته أن يصلني فكل شيء أنفقته بعده إلى هذه الغاية فمن فضل مالها وما ذخرت من صلاتها قال ابن النشار فقال له أبي ما سمعت بأحسن من هذا الحديث ولا أعجب مما وفقه الله لك فيه حدثني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبي قال دخل حسين بن الضحاك على محمد الأمين بعقب وقعة أوقعها أهل بغداد بأصحاب طاهر فهزموهم وفضحوهم فهنأه بالظفر ثم استأذنه في الإنشاد فأذن له فأنشده\n(أمين الله ثق بالليه ... تعط العز والنصره)\n(كل الأمر إلى الله ... كلاك الله ذو القدره)\n(لنا النصر بإذن ألله والكرة لا الفره ... )\n(وللمراق أعداءك ... يوم السوء والدبره)\n(وكأس تورد الموت ... كريه طعمها مره)\n(سقونا وسقيناهم ... فكانت بهم الحره)\n(كذاك الحرب أحيانا ... علينا ولنا مره)\nفأمر له بعشرة آلاف درهم ولم يزل يتبسم وهو ينشده","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":21,"spl":"يحكي للنشار صحبته للأمين","loc":1341,"partial":1},
{"id":"b74-25","bab":"الجزء 7","sec":"الأمين يركب ظهره","page":"ج7 ص227","text":"حدثني الصولي قال حدثني الحسين بن يحيى أبو الحمار قال قال لي الحسين بن الضحاك شربنا يوما مع الأمين في بستان فسقانا على الريق وجد بنا في الشرب وتحرز من أن نذوق شيئا فاشتد الأمر علي وقمت لأبول فأعطيت خادما من الخدم ألف درهم على أن يجعل لي تحت شجرة أومأت إليها رقاقة فيها لحم فأخذ الألف وفعل ذلك ووثب محمد فقال من يكون منكم حماري فكل واحد منهم قال له أنا لأنه كان يركب الواحد منا عبثا ثم يصله ثم قال يا حسين أنت أضلع القوم فركبني وجعل يطوف وأنا أعدل به عن الشجرة وهو يمر بي إليها حتى صار تحتها فرأى الرقاقة فتطأطأ فأخذها فأكلها على ظهري وقال هذه جعلت لبعضكم ثم رجع إلى مجلسه وما وصلني بشيء فقلت لأصحابي أنا أشقى الناس ركب ظهري وذهب ألف درهم مني وفاتني ما يمسك رمقي ولم يصلني كعادتي ما أنا إلا كما قال الشاعر\n(ومطعم الصيد يوم الصيد مطعمه ... أنى توجه والمحروم محروم)\nدثني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد النحوي المبرد قال كان حسين بن الضحاك الأشقر وهو الخليع يهوى جارية لأم\nجعفر وكانت من أجمل الجواري وكان لها صدغان معقربان وكانت تخرج إليه إذا جاء فتقول له ما قلت فينا أنشدنا منه شيئا فيخرج إليها الصحيفة فتقول له اقرأ معي فيقرأ معها حتى تحفظه ثم تدخل وتأخذ الصحيفة فشكا ذلك إلى عاصم الغساني الذي كان يمدحه سلم الخاسر وكان مكينا عند أم جعفر وسأله أن يستوهبها له فاستوهبها فأبت عليه أم جعفر فوجه إلى الخليع بألف دينار وقال خذ هذا الألف فقد جهدت الجهد كله فيها فلم تمكني حيلة فقال الحسين في ذلك\n(رمتك غداة السبت شمس من الخلد ... بسهم الهوى عمدا وموتك في العمد)\n(مؤزرة السربال مهضومة الحشا ... غلامية التقطيع شاطرة القد)\n(محنأة الأطراف رؤد شبابها ... معقربة الصدغين كاذبة الوعد)\n(أقول ونفسي بين شوق وزفرة ... وقد شخصت عيني ودمعي على الخد)\n(أجيزي على من قد تركت فؤاده ... بلحظته بين التأسف والجهد)\n(فقالت عذاب بالهوى مع قربكم ... وموت إذا أقرحت قلبك بالبعد)\n(لقد فطنت للجور فطنة عاصم ... لصنع الأيادي الغر في طلب الحمد)\n(سأشكوك في الأشعار غير مقصر ... إلى عاصم ذي المكرمات وذي المجد)\n(لعل فتى غسان يجمع بيننا ... فيأمن قلبي منكم روعة الصد)\nدثني محمد بن خلف وكيع قال حدثني هارون بن مخارق قال أقطع المعتصم الناس الدور بسر من رأى وأعطاهم النفقات لبنائها ولم يقطع الحسين بن الضحاك شيئا فدخل عليه فأنشده قوله\n(يا أمين الله لا خطة لي ... ولقد أفردت صحبي بخطط)\n(أنا في دهياء من مظلمة ... تحمل الشيخ على كل غلط)\n(صعبة المسلك يرتاع لها ... كل من أصعد فيها وهبط)\n(بوني منك كما بوأتهم ... عرصة تبسط طرفي ما انبسط)\n(أبتني فيها لنفسي موطنا ... ولعقبي فرطا بعد فرط)\n(لم يزل منك قريبا مسكني ... فأعد لي عادة القرب فقط)\n(كل من قربته مغتبط ... ولمن أبعدت خزي وسخط)\nقال فأقطعه دارا وأعطاه ألف دينار لنفقته عليها","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":22,"spl":"الأمين يركب ظهره","loc":1342},
{"id":"b74-26","bab":"الجزء 7","sec":"مع أبي العتاهية","page":"ج7 ص229","text":"أخبرني محمد بن العباس اليزيدي قال أخبرني عمي الفضل عن الحسين بن الضحاك قال كنت أمشي مع أبي العتاهية فمررت بمقبرة وفيها باكية تبكي بصوت شج على ابن لها فقال أبو العتاهية\n(أما تنفك باكية بعين ... غزير دمعها كمد حشاها)\nأجز يا حسين فقلت\n(تنادي حفرة أعيت جوابا ... فقد ولهت وصم بها صداها)\nدثني الصولي قال حدثني الحسين بن يحيى قال حدثني الحسين بن الضحاك قال\nكنت عازما على أن أرثي الأمين بلساني كله وأشفي لوعتي فلقيني أبو العتاهية فقال لي يا حسين أنا إليك مائل ولك محب وقد علمت مكانك من الأمين وإنه لحقيق بأن ترثيه إلا أنك قد أطلقت لسانك من التلهف عليه والتوجع له بما صار هجاء لغيره وثلبا له وتحريضا عليه وهذا المأمون منصب إلى العراق قد أقبل عليك فأبق على نفسك يا ويحك أتجسر على أن تقول\n(تركوا حريم أبيهم نفلا ... والمحصنات صوارخ هتف)\n(هيهات بعدك أن يدوم لهم ... عز وأن يبقى لهم شرف)\nأكفف غرب لسانك واطو ما انتشر عنك وتلاف ما فرط منك فعلمت أنه قد نصحني فجزيته الخير وقطعت القول فنجوت برأيه وما كدت أن أنجو حدثني جعفر بن قدامة قال حدثني أبو العيناء قال وقف علينا حسين بن الضحاك ومعنا فتى جالس من أولاد الموالي جميل الوجه فحادثنا طويلا وجعل يقبل على الفتى بحديثه والفتى معرض عنه حتى طال ذلك ثم أقبل عليه الحسين فقال\n(تتيه علينا أن رزقت ملاحة ... فمهلا علينا بعض تيهك يا بدر)\n(لقد طالما كنا ملاحا وربما ... صددنا وتهنا ثم غيرنا الدهر)\nوقام فانصرف أخبرني الحسن بن القاسم الكوفي قال حدثني ابن عجلان قال غنى بعض المغنين في مجلس محمد المخلوع بشعر حسين بن الضحاك وهو\n\n(ألست ترى ديمة تهطل ... وهذا صباحك مستقبل)\n(وهذي العقار وقد راعنا ... بطلعته الشادن الأكحل)\n(فعاد به وبنا سكرة ... تهون مكروه ما نسأل)\n(فإني رأيت له نظرة ... تخبرنا أنه يفعل)\nال فأمر بإحضار حسين فأحضر وقد كان محمد شرب أرطالا فلما مثل بين يديه أمر فسقي ثلاثة أرطال فلم يستوفها الحسين حتى غلبه السكر وقذف فأمر بحمله إلى منزله فحمل فلما أفاق كتب إليه\n(إذا كنت في عصبة ... من المعشر الأخيب)\n(ولم يك لي مسعد ... نديم سوى جعدب)\n(فأشرب من رملة ... وأسهر من قطرب)\n(ولما حباني الزمان ... من حيث لم أحسب)\n(ونادمت بدر السماء ... في فلك الكوكب)\n(أبت لي غضوضيتي ... ولؤم من المنصب)\n(فأسكرني مسرعا ... قوي من المشرب)\n(كذا النذل ينبو به ... منادمة المنجب)\nقال فرده إلى منادمته وأحسن جائزته وصلته أخبرني الكوكبي قال حدثني علي بن محمد بن نصر عن خالد بن حمدون أن الحسين بن الضحاك أنشده وقد عاتبه خادم من خدام أبي أحمد بن الرشيد كان حسين يتعشقه ولامه في أن قال فيه شعرا وغنى فيه عمرو ابن بانة فقال حسين فيه\n(فديت من قال لي على خفره ... وغض جفنا له على حوره)\n(سمع بي شعرك المليح فما ... ينفك شاد به على وتره)\n(فقلت يا مستعير سالفة الخشف ... وحسن الفتور من نظره)\n(لا تنكرن الحنين من طرب ... عاود فيك الصبا على كبره)\nوغنى فيه عمرو بن بانة هزجا مطلقا","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":23,"spl":"مع أبي العتاهية","song":2,"loc":1343},
{"id":"b74-27","bab":"الجزء 7","sec":"شعره على قبر أبي نواس","page":"ج7 ص232","text":"أخبرني الكوكبي قال حدثني أبو سهل بن نوبخت عن عمرو بن بانة قال لما مات أبو نواس كتب حسين بن الضحاك على قبره\n(كابرنيك الزمان يا حسن ... فخاب سهمي وأفلح الزمن)\n(ليتك إذ لم تكن بقيت لنا ... لم تبق روح يحوطها بدن)\nخبرني الحسن بن علي الخفاف قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبي قال كان في جوار الحسين بن الضحاك طبيب يدواي الجراحات يقال له نصير وكان مخنثا فإذا كانت وليمة دخل مع المخنثين وإذا لم تكن عالج الجراحات فقال فيه الحسين بن الضحاك\n(نصير ليس المرد من شأنه ... نصير طب بالنكاريش)\n(يقول للنكريش في خلوة ... مقال ذي لطف وتجميش)\n(هل لك أن نلعب في فرشنا ... تقلب الطير المراعيش)\nيعني المبادلة فكان نصير بعد ذلك يصيح به الصبيان يا نصير نلعب تقلب الطير المراعيش فيشتمهم ويرميهم بالحجارة حدثني جعفر قال حدثني علي بن يحيى عن حسين بن الضحاك قال أنشدت ابن مناذر قصيدتي التي أقول فيها\n(لفقدك ريحانة العسكر ... )\nوكانت من أول ما قلته من الشعر فأخذ رداءه ورمى به إلى السقف وتلقاه برجله وجعل يردد هذا البيت فقلنا لحسين أتراه فعل ذلك استحسانا لما قلت فقال لا فقلنا فإنما فعله طنزا بك فشتمه وشتمنا وكنا بعد ذلك نسأله إعادة هذا البيت فيرمي بالحجارة ويجدد شتم ابن مناذر بأقبح ما يقدر عليه أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن أبي كامل قال مررت بباب حسين بن الضحاك وإذا أبو يزيد السلولي وأبو حزرة الغنوي وهما ينتظران المحاربي وقد استؤذن لهم على ابن الضحاك فقلت\nلهما لم لا تدخلان فقال أبو يزيد ننتظر اللؤم أن يجتمع فليس في الدنيا أعجب مما اجتمع منا الغنوي والسلولي ينتظران المحاربي ليدخلوا على باهلي أخبرني محمد بن مزيد بن أبي الأزهر البوشنجي قال حدثنا عمر بن شبة قال حدثني حسين بن الضحاك قال كان الواثق يميل إلى الفتح بن خاقان ويأنس به وهو يومئذ غلام وكان الفتح ذكيا جيد الطبع والفطنة فقال له المعتصم يوما وقد دخل على أبيه خاقان عرطوج يا فتح أيما أحسن داري أو دار أبيك فقال له وهو غير متوقف وهو صبي له سبع سنين أو نحوها دار أبي إذا كنت فيها فعجب منه وتبناه وكان الواثق له بهذه المنزلة وزاد المتوكل عليهما فاعتل الفتح في أيام الواثق علة صعبة ثم أفاق وعوفي فعزم الواثق على الصبوح فقال لي يا حسين اكتب بأبيات عني إلى الفتح تدعوه إلى الصبوح فكتبت إليه\n(لما اصطبحت وعين اللهو ترمقني ... قد لاح لي باكرا في ثوب بذلته)\n(ناديت فتحا وبشرت المدام به ... لما تخلص من مكروه علته)\n(ذب الفتى عن حريم الراح مكرمة ... إذا رآه امرؤ ضدا لنحلته)\n(فاعجل إلينا وعجل بالسرور لنا ... وخالس الدهر في أوقات غفلته)\nفلما قرأها الفتح صار إليه فاصطبح معه\nأخبرني عمي قال حدثني يعقوب بن نعيم وعبد الله بن أبي سعد قالا حدثنا محمد بن محمد الأنباري قال حدثني حسين بن الضحاك قال كنت عند عبد الله بن العباس بن الفضل بن الربيع وهو مصطبح وخادم له يسقيه فقال لي يا أبا علي قد استحسنت سقي هذا الخادم فإن حضرك شيء في قصتنا هذه فقل فقلت\n(أحيت صبوحي فكاهة اللاهي ... وطاب يومي بقرب أشباهي)\n(فاستثر اللهو من مكامنه ... من قبل يوم منغص ناهي)\n(بابنة كرم من كف منتطق ... مؤتزر بالمجون تياه)\n(يسقيك من طرفه ومن يده ... سقي لطيف مجرب داهي)\n(كأسا فكأسا كأن شاربها ... حيران بين الذكور والساهي)\nقال فاستحسنه عبد الله وغنى فيه لحنا مليحا وشربنا عليه بقية يومنا","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":24,"spl":"شعره على قبر أبي نواس","loc":1344,"partial":1},
{"id":"b74-28","bab":"الجزء 7","sec":"أخباره مع يسر","page":"ج7 ص235","text":"أخبرني علي بن العباس قال حدثني سوادة بن الفيض عن أبيه قال اتفق حسين بن الضحاك ويسر مرة عند بعض إخوانهما وشربا وذلك في العشر الأواخر من شعبان فقال حسين ليسر يا سيدي قد هجم الصوم علينا فتفضل بمجلس نجتمع فيه قبل هجومه فوعده بذلك فقال له قد سكرت وأخشى أن يبدو لك فحلف له يسر أنه يفي فلما كان من الغد كتب إليه حسين وسأله الوفاء فجحد الوعد وأنكره فكتب إليه يقول\n(تجاسرت على الغدر ... كعاداتك في الهجر)\n(فأخلفت وما استخلفت ... من إخوانك الزهر)\n(لئن خست لما ذلك ... من فعلك بالنكر)\n(وما أقنعني فعلك ... يا مختلق العذر)\n(بنفسي أنت إن سؤت ... فلا بد من الصبر)\n(وإن جرعني الغيظ ... وإن خشن بالصدر)\n(ولولا فرقي منك ... لسميتك في الشعر)\n(وعنفتك لا آلو ... وإن جزت مدى العذر)\n(أما تخرج من إخلاف ... ميعادك في العشر)\n(غدا يفطمنا الصوم ... عن الراح إلى الفطر)\nال فسألت الحسين بن الضحاك عما أثر له هذا الشعر وما كان الجواب فقال كان أحسن جواب وأجمل فعل كان اجتماعنا قبل الصوم في بستان لمولاه وتممنا سرورنا وقضينا أوطارنا إلى الليل وقلت في ذلك\n(سقى الله بطن الدير من مستوى السفح ... إلى ملتقى النهرين فالأثل فالطلح)\n(ملاعب قدن القلب قسرا إلى الهوى ... ويسرن ما أملت من درك النجح)\n(أتنسى فلا أنسى عتابك بينها ... حبيبك حتى انقاد عفوا إلى الصلح)\n(سمحت لمن أهوى بصفو مودتي ... ولكن من أهواه صيغ على الشح)\nقال علي بن العباس وأنشدني سوادة بن الفيض عن أبيه لحسين بن الضحاك يصف أياما مضت له بالبصرة ويومه بالقفص ومجيء يسر إليه\nيسر سأله أن يقول في ذلك شعرا\n(تيسري للمام من أمم ... ولا تراعي حمامة الحرم)\n(قد غاب لا آب من يراقبنا ... ونام لا قام سامر الخدم)\n(فاستصحبي مسعدا يفاوضنا ... إذا خلونا في كل مكتتم)\n(تبذلي بدلة تقر بها العين ... ولا تحصري وتحتشمي)\n(ليت نجوم السماء راكدة ... على دجى ليلنا فلم ترم)\n(ما لسروري بالشك ممتزجا ... حتى كأني أراه في حلم)\n(فرحت حتى أستخفني فرحي ... وشبت عين اليقين بالتهم)\n(أمسح عيني مستثبتا نظري ... أخالني نائما ولم أنم)\n(سقيا لليل أفنيت مدته ... ببارد الريق طيب النسم)\n(أبيض مرتجة روادفه ... ما عيب من قرنه إلى القدم)\n(إذ قصبات العريش تجمعنا ... حتى تجلت أواخر الظلم)\n(وليلة بتها محسدة ... محفوفة بالظنون والتهم)\n(أبث عبراته على غصص ... يرد أنفاسه إلى الكظم)\n(سقيا لقيطونها ومخدعها ... كم من لمام به ومن لمم)\n(لا أكفر السيلحين أزمنة ... مطيعة بالنعيم والنعم)\n(وليلة القفص إن سألت بها ... كانت شفاء لعلة السقم)\n(بات أنيسي صريع خمرته ... وتلك إحدى مصارع الكرم)\n(وبت عن موعد سبقت به ... ألثم درا مفلجا بفم)\n(وابأبي من بدا بروعة لا ... وعاد من بعدها إلى نعم)\n(أباحني نفسه ووسدني ... يمنى يديه وبات ملتزمي)\n(حتى إذا اهتاجت النواقس في ... سحرة أحوى أحم كالحمم)\n(وقلت هبا يا صاحبي ونبهت ... أبانا فهب كالزلم)\n(فاستنها كالشهاب ضاحكة ... عن بارق في الإناء مبتسم)\n(صفراء زيتية موشحة ... بأرجوان ملمع ضرم)\n(أخذت ريحانة أراح لها ... دب سروري بها دبيب دمي)\n(فراجع العذر إن بدا لك في العذر ... وإن عدت لائما فلم)\nخبرني علي بن العباس قال حدثني سوادة بن الفيض المخزومي قال حدثني المعتمر بن الوليد المخزومي قال قال لي الحسين بن الضحاك وهو على شراب له ويحكم أحدثكم عن يسر بأعجوبة قلنا هات قال بلغ مولاه أنه جرى له مع أخيه سبب فحجبه كما تحجب النساء وأمر بالحجر عليه وأمره ألا يخرج عن داره إلا ومعه حافظ له موكل به فقلت في ذلك\n(ظن من لا كان ظنا ... بحبيبي فحماه)\n(أرصد الباب رقيبين ... له فاكتنفاه)\n(فإذا ما اشتاق قربي ... ولقائي منعاه)\n(جعل الله رقيبيه ... من السوء فداه)\n(والذي أقرح في الشادن ... قلبي ولواه)\n(كل مشتاق إليه ... فمن السوء فداه)\n(سيما من حالت الأحراس ... من دون مناه)\nخبرني علي بن العباس قال حدثنا أحمد بن العباس الكاتب قال حدثني عبدالله بن زكريا الضرير قال : قال أبو نواس قال لي حسين بن الضحاك يوما يا أبا علي أما ترى غضب يسر علي فقلت له وما كان سبب ذلك قال حال أردتها منه فمنعنيها فغضبت فأسألك أن تصلح بيني وبينه فقلت وما تحب أن أبلغه عنك قال تقول له","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":25,"spl":"أخباره مع يسر","loc":1345},
{"id":"b74-29","bab":"الجزء 7","sec":"أخباره مع يسر","page":"ج7 ص235","text":"(بحرمه السكر وما كانا ... عزمت ان تقتل إنسانا)\n(أخاف أن تهجرني صاحيا ... بعد سروري بك سكرانا)\n(إن بقلبي روعة كلما ... أضمر لي قلبك هجرانا)\n(يا ليت ظني أبدا كاذب ... فإنه يصدق أحيانا)\nال فقلت له ويحك أتجتنبه وتريد أن تترضاه وترسل إليه بمثل هذه الرسالة فقال لي أنا أعرف به وهو كثير التبذل فأبلغه ما سألتك فأبلغته فرضي عنه وأصلحت بينهما حدثني جعفر بن قدامة قال حدثني علي بن يحيى قال جاءني يوما حسين بن الضحاك فقلت له أي شيء كان خبرك أمس فقال لي اسمعه شعرا ولا أزيدك على ذلك وهو أحسن فقلت هات يا سيدي فقال\n(زائرة زادت على غفلة ... يا حبذا الزورة والزائره)\n(فلم أزل أخدعها ليلتي ... خديعة الساحر للساحره)\n(حتى إذا ما أذعنت بالرضا ... وأنعمت دارت بها الدائره)\n(بت إلى الصبح بها ساهرا ... وباتت الجوزاء بي ساهره)\n(أفعل ما شئت بها ليلتي ... وملء عيني نعمة ظاهره)\n(فلم ننم إلا على تسعة ... من غلمة بي وبها ثائره)\n(سقيا لها لا لأخي شعرة ... شعرته كالشعرة الوافره)\n(وبين رجليه له حربة ... مشهورة في حقوه شاهره)\n(وفي غد يتبعها لحية ... تلحقه بالكرة الخاسره)\nقال فقلت له زنيت يعلم الله إن كنت صادقا فقال قل أنت ما شئت حدثني الحسن بن علي قال حدثنا أبو العيناء قال دخل حسين بن الضحاك على الواثق في خلافة المعتصم في يوم طيب فحثه على الصبوح فلم ينشط له فقال اسمع ما قلت قال هات فأنشده\n(استثر اللهو من مكامنه ... من قبل يوم منغص ناهي)\n(بابنة كرم من كف منتطق ... مؤتزر بالمجون تياه)\n(يسقيك من لحظه ومن يده ... سقي لطيف مجرب داهي)\n(كأسا فكأسا كأن شاربها ... حيران بين الذكور والساهي)\nقال فنشط الواثق وقال إن فرصة العيش لحقيقة أن تنتهز واصطبح ووصل الحسين حدثني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو الشبل عاصم بن وهب البرجمي قال حج الحسين بن الضحاك فمر في منصرفه عل موضع يعرف\nبالقريتين فإذا جارية تطلع في ثيابها وتنظر في حرها ثم تضربه بيدها وتقول ما أضيعني وأضيعك فأنشأ يقول\n(مررت بالقريتين منصرفا ... من حيث يقضي ذوو النهى النسكا)\n(إذا فتاة كأنها قمر ... للتم لما توسط الفلكا)\n(واضعة كفها على حرها ... تقول يا ضيعتي وضيعتكا)\nقال فلما سمعت قوله ضحكت وغطت وجهها وقالت وافضيحتاه أوقد سمعت ما قلت حدثني محمد الصولي قال حدثني ميمون بن هارون قال كان الحسين بن الضحاك صديقا لأبي وكنت ألقاه معه كثيرا وكانت نفسه قد تتبعت شفيعا بعد انصرافه من مجلس المتوكل فأنشدنا لنفسه فيه\n(وأبيض في حمر الثياب كأنه ... )\n(إذا ما بدا نسرينة في شقائق ... )\n(سقاني بكفيه رحيقا وسامني ... فسوقا بعينيه ولست بفاسق)\n(وأقسم لولا خشية الله وحده ... ومن لا أسمي كنت أول عاشق)\n(وإني لمعذور على وجناته ... وإن وسمتني شيبة في المفارق)\n(ولا عشق لي أو يحدث الدهر شرة ... تعود بعادات الشباب المفارق)\n(ولو كنت شكلا للصبا لاتبعته ... ولكن سني بالصبا غير لائق)\nدثني الصولي قال حدثنا ميمون بن هارون قال\nكان للحسين بن الضحاك ابن يسمى محمدا له أرزاق فمات فقطعت أرزاقه فقال يخاطب المتوكل ويسأله أن يجعل أرزاق ابنه المتوفى لزوجته وأولاده\n(إني أتيتك شافعا ... بولي عهد المسلمينا)\n(وشبيهك المعتز أوجه ... شافع في العالمينا)\n(يابن الخلائف الأولين ... ويا أبا المتأخرينا)\n(إن ابن عبدك مات والأيام ... تخترم القرينا)\n(ومضى وخلف صبية ... بعراصه متلددينا)\n(ومهيرة عبرى خلاف ... أقارب مستعبرينا)\n(أصبحن في ريب الحوادث ... يحسنون بك الظنونا)\n(قطع الولاة جراية ... كانوا بها مستمسكينا)\n(فامنن برد جميع ما ... قطعوه غير مراقبينا)\n(أعطاك أفضل ما تؤمل ... أفضل المتفضلينا)\nقال فأمر المتوكل له بما سأل فقال يشكره\n(يا خير مستخلف من آل عباس ... اسلم وليس على الأيام من باس)\n(أحييت من أملي نضوا تعاوره ... تعاقب اليأس حتى مات بالياس)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":26,"spl":"أخباره مع يسر","loc":1346,"partial":1},
{"id":"b74-30","bab":"الجزء 7","sec":"مغنية تهرب من هجائه","page":"ج7 ص242","text":"أخبرني جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك قال كنا في مجلس ومعنا حسين بن الضحاك ونحن على نبيذ فعبث بالمغنية وجمشها فصاحت عليه واستخفت به فأنشأ يقول\n(لها في وجهها عكن ... وثلثا وجهها ذقن)\n(وأسنان كريش البط ... بين أصولها عفن)\nقال فضحكا وبكت المغنية حتى قلت قد عميت وما انتفعنا بها بقية يومنا وشاع هذان البيتان فكسدت من أجلهما وكانت إذا حضرت في موضع أنشدوا البيتين فتجن ثم هربت من سر من رأى فما عرفنا لها بعد ذلك خبرا قال جعفر وحدثنا أبو العيناء أنه حضر هذا المجلس وحكى مثل ما حكاه محمد حدثني عمي قال حدثني يزيد بن محمد المهلبي قال سألت حسين بن الضحاك ونحن في مجلس المتوكل عن سنه فقال لست أحفظ السنة التي ولدت فيها بعينها ولكني أذكر وأنا بالبصرة موت شعبة بن الحجاج سنة ستين ومائة حدثني الصولي قال حدثني علي بن محمد بن نصر قال حدثني خالي يعني أحمد بن حمدون قال أمر المتوكل أن ينادمه حسين بن الضحاك ويلازمه فلم يطق ذلك لكبر سنه فقال للمتوكل بعض من حضر عنده هو يطيق الذهاب إلى القرى والمواخير والسكر فيها ويعجز عن خدمتك فبلغه ذلك فدفع إلي أبياتا قالها وسألني إيصالها فأوصلتها إلى المتوكل وهي\n(أما في ثمانين وفيتها ... عذير وإن أنا لم أعتذر)\n(فكيف وقد جزتها صاعدا ... مع الصاعدين بتسع أخر)\n(وقد رفع الله أقلامه ... عن ابن ثمانين دون البشر)\n(سوى من أصر على فتنة ... وألحد في دينه أو كفر)\n(وإني لمن أسراء الإله ... في الأرض نصب صروف القدر)\n(فإن يقض لي عملا صالحا ... أثاب وإن يقض شرا غفر)\n(فلا تلح في كبر هدني ... فلا ذنب لي أن بلغت الكبر)\n(هو الشيب حل بعقب الشباب ... فأعقبني خورا من أشر)\n(وقد بسط الله لي عذره ... فمن ذا يلوم إذا عذر)\n(وإني لفي كنف مغدق ... وعز بنصر أبي المنتصر)\n(يباري الرياح بفضل السماح ... حتى تبلد أو تنحسر)\n(له أكد الوحي ميراثه ... ومن ذا يخالف وحي السور)\n(وما للحسود وأشياعه ... ومن كذب الحق إلا الحجر)\nال ابن حمدون فلما أوصلتها شيعتها بكلامي أعذره وقلت لو أطاق خدمة أمير المؤمنين لكان أسعد بها فقال المتوكل صدقت خذ له عشرين ألف درهم واحملها إليه فأخذتها فحملتها إليه","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":27,"spl":"مغنية تهرب من هجائه — الخلفاء يضربونه","loc":1347},
{"id":"b74-31","bab":"الجزء 7","sec":"الخلفاء يضربونه","page":"ج7 ص244","text":"حدثني عمي قال حدثني علي بن محمد بن نصر قال حدثني خالي عن حسين بن الضحاك قال ضربني الرشيد في خلافته لصحبتي ولده ثم ضربني الأمين لممايلة ابنه عبد الله ثم ضربني المأمون لميلي إلى محمد ثم ضربني المعتصم لمودة كانت بيني وبين العباس بن المأمون ثم ضربني الواثق لشيء بلغه من ذهابي إلى المتوكل وكل ذلك يجري مجرى الولع بي والتحذير لي ثم أحضرني المتوكل وأمر شفيعا بالولع بي فتغاضب المتوكل علي فقلت له يا أمير المؤمنين إن كنت تريد أن تضربني كما ضربني آباؤك فاعلم أن آخر\nضرب ضربته بسببك فضحك وقال بل أحسن إليك يا حسين وأصونك وأكرمك حدثني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل قال حدثني محمد بن محمد بن مروان الأبزاري قال دخلت على حسين بن الضحاك فقلت له كيف أنت جعلني الله فداءك فبكى ثم أنشأ يقول\n(أصبحت من أسراء الله محتسبا ... في الأرض نحو قضاء الله والقدر)\n(إن الثمانين إذ وفيت عدتها ... لم تبق باقية مني ولم تذر)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":27,"spl":"مغنية تهرب من هجائه — الخلفاء يضربونه","loc":1348},
{"id":"b74-32","bab":"الجزء 7","sec":"أخبار أبي زكار الأعمى","page":"ج7 ص246","text":"قال أبو الفرج أبو زكار هذا رجل من أهل بغداد من قدماء المغنين وكان منقطعا إلى آل برمك وكانوا يؤثرونه ويفضلون عليه إفضالا فحدثني محمد بن جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك الخزاعي قال سمعت مسرورا يحدث أبي قال لما أمرني الرشيد بقتل جعفر بن يحيى دخلت عليه وعنده أبو زكار الأعمى وهو يغنيه بصوت لم أسمع بمثله\n(فلا تبعد فكل فتى سيأتي ... عليه الموت يطرق أو يغادي)\n(وكل ذخيرة لا بد يوما ... وإن بقيت تصير إلى نفاد)\n(ولو يفدى من الحدثان شيء ... فديتك بالطريف وبالتلاد)\nفقلت له في هذا والله أتيتك فأخذت بيده فأقمته وأمرت بضرب عنقه فقال لي أبو زكار نشدتك الله إلا ألحقتني به فقلت وما رغبتك في ذلك قال إنه أغناني عمن سواه بإحسانه فما أحب أن أبقى بعده فقلت\nأستأمر أمير المؤمنين في ذلك فلما أتيت الرشيد برأس جعفر أخبرته بقصة أبي زكار فقال لي هذا رجل فيه مصطنع فاضممه إليك وانظر ما كان يجريه عليه فأتممه له حدثني الحسين بن يحيى عن حماد بن إسحاق قال غنى علويه يوما بحضرة أبي فقال أبي مه هذا الصوت معرق في العمى الشعر لبشار الأعمى والغناء لأبي زكار الأعمى وأول الصوت عميت أمري","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":28,"spl":"أخبار أبي زكار الأعمى — من المائة المختارة من رواية جحظة عن أصحابه","song":1,"loc":1349},
{"id":"b74-33","bab":"الجزء 7","sec":"من المائة المختارة من رواية جحظة عن أصحابه","page":"ج7 ص247","text":"(ما جرت خطرة على القلب مني ... فيك إلا استترت عن أصحابي)\n(من دموع تجري فإن كنت وحدي ... خاليا أسعدت دموعي انتحابي)\n(إن حبي إياك قد سل جسمي ... ورماني بالشيب قبل الشباب)\n(لو منحت اللقا شفى بك صبا ... هائم القلب قد ثوى في التراب)\nلشعر في الأبيات للسيد الحميري والغناء لمحمد نعجة الكوفي مغن غير مشهور ولا ممن خدم الخلفاء وليس له خبر ولحنه المختار ثاني ثقيل مطلق في مجرى البنصر وذكر حبش أن لمحمد نعجة فيه أيضا خفيف رمل بالبنصر","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":28,"spl":"أخبار أبي زكار الأعمى — من المائة المختارة من رواية جحظة عن أصحابه","loc":1350},
{"id":"b74-35","bab":"الجزء 7","sec":"أخبار السيد الحميري — على مذهب الكيسانية","page":"ج7 ص248 – ج7 ص250","text":"السيد لقبه واسمه إسماعيل بن محمد بن يزيد بن ربيعة بن مفرغ الحميري ويكنى أبا هاشم وأمه امرأة من الأزد ثم من بني الحدان وجده يزيد بن ربيعة شاعر مشهور وهو الذي هجا زيادا وبنيه ونفاهم عن آل حرب وحبسه عبيد الله بن زياد لذلك وعذبه ثم أطلقه معاوية وخبره في هذا طويل يذكر في موضعه مع سائر أخباره إذ كان الغرض ها هنا ذكر أخبار السيد ووجدت في بعض الكتب عن إسحاق بن محمد النخعي قال\nسمعت ابن عائشة والقحذمي يقولان هو يزيد بن مفرغ ومن قال إنه يزيد ابن معاوية فقد أخطأ ومفرغ لقب ربيعة لأنه راهن أن يشرب عسا من لبن فشربه حتى فرغه فلقب مفرغا وكان شعابا بسيالة ثم صار إلى البصرة وكان شاعرا متقدما مطبوعا يقال إن أكثر الناس شعرا في الجاهلية والإسلام ثلاثة بشار وأبو العتاهية والسيد فإنه لا يعلم أن أحدا قدر على تحصيل شعر أحد منهم أجمع وإنما مات ذكره وهجر الناس شعره لما كان يفرط فيه من سب أصحاب رسول الله في شعره ويستعمله من قذفهم والطعن عليهم فتحومي شعره من هذا الجنس وغيره لذلك وهجره الناس تخوفا وتراقبا وله طراز من الشعر ومذهب قلما يلحق فيه أو يقاربه ولا يعرف له من الشعر كثير وليس يخلو من مدح بني هاشم أو ذم غيرهم ممن هو عنده ضد لهم ولولا أن أخباره كلها تجري هذا المجرى ولا تخرج عنه لوجب ألا نذكر منها شيئا ولكنا شرطنا أن نأتي بأخبار من نذكره من الشعراء فلم نجد بدا من ذكر أسلم ما وجدناه له وأخلاها من سيء اختياره على قلة ذلك أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد ألنوفلي عن إسماعيل بن الساحر راوية السيد قال ابن عمار وحدثني أحمد بن سليمان بن أبي شيخ عن أبيه أن أبوي السيد كانا إباضيين وكان منزلهما بالبصرة في غرفة بني\nضبة وكان السيد يقول طالما سب أمير المؤمنين في هذه الغرفة فإذا سئل عن التشيع من أين وقع له قال غاصت علي الرحمة غوصا وروي عن السيد أن أبويه لما علما بمذهبه هما بقتله فأتى عقبة بن سلم الهنائي فأخبره بذلك فأجاره وبوأه منزلا وهبه له فكان فيه حتى ماتا فورثهما\nوقد أخبرني الحسن بن علي البري عن محمد بن عامر عن القاسم بن الربيع عن أبي داود سليمان بن سفيان المعروف بالحنزق راوية السيد الحميري قال ما مضى والله إلا على مذهب الكيسانية وهذه القصائد التي يقولها الناس مثل\n(تجعفرت باسم الله والله أكبر ... )\nو\n(تجعفرت باسم الله فيمن تجعفرا ... )\nوقوله\n(أيا راكبا نحو المدينة جسرة ... عذافرة تهوي بها كل سبسب)\n(إذا ما هداك الله لاقيت جعفرا ... فقل يا أمين الله وابن المهذب)\nلغلام للسيد يقال له قاسم الخياط قالها ونحلها للسيد وجازت على\nكثير من الناس ممن لم يعرف خبرها بمحل قاسم منه وخدمته إياه","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":29,"spl":"أخبار السيد الحميري — على مذهب الكيسانية","loc":1351,"partial":1},
{"id":"b74-36","bab":"الجزء 7","sec":"بعض أوصافه","page":"ج7 ص251","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي قال حدثني أبو جعفر الأعرج ابن بنت الفضيل بن بشار قال كان السيد أسمر تام القامة أشنب ذا وفرة حسن الألفاظ جميل الخطاب إذا تحدث في مجلس قوم أعطى كل رجل في المجلس نصيبه من حديثه أخبرني أحمد قال حدثني محمد بن عباد عن أبي عمرو الشيباني عن لبطة بن الفرزدق قال تذاكرنا الشعراء عند أبي فقال إن ها هنا لرجلين لو أخذا في معنى الناس لما كنا معهما في شيء فسألناه من هما فقال السيد الحميري وعمران بن حطان السدوسي ولكن الله عز و جل قد شغل كل واحد منهما بالقول في مذهبه أخبرني عيسى بن الحسين الوراق قال حدثني علي بن محمد النوفلي قال حدثني أبو جعفر ابن بنت الفضيل بن بشار قال\nكان السيد أسمر تام الخلقة أشنب ذا وفرة حسن الألفاظ وكان مع ذلك أنتن الناس إبطين لا يقدر أحد على الجلوس معه لنتن رائحتهما قال حدثني التوزي قال رأى الأصمعي جزءا فيه من شعر السيد فقال لمن هذا فسترته عنه لعلمي بما عنده فيه فأقسم علي أن أخبره فأخبرته فقال أنشدني قصيدة منه فأنشدته قصيدة ثم أخرى وهو يستزيدني ثم قال قبحه الله ما أسلكه لطريق الفحول لولا مذهبه ولولا ما في شعره ما قدمت عليه أحدا من طبقته أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم قال سمعت أبا عبيدة يقول أشعر المحدثين السيد الحميري وبشار أخبرني عمي قال حدثني الحسن بن عليل العنزي عن أبي شراعة القيسي عن مسعود بن بشر إن جماعة تذاكروا أمر السيد وأنه رجع عن مذهبه في ابن الحنفية وقال بإمامة جعفر بن محمد فقال ابن الساحر راويته والله ما رجع عن ذلك ولا القصائد الجعفريات إلا منحولة له قيلت بعده وآخر عهدي به قبل\nموته بثلاث وقد سمع رجلا يروي عن النبي قال لعلي عليه السلام ( إنه سيولد لك بعدي ولد وقد نحلته اسمي وكنيتي\nفقال في ذلك وهي آخر قصيدة قالها\n(أشاقتك المنازل بعد هند ... وتربيها وذات الدل دعد)\n(منازل أقفرت منهن محت ... معالمهن من سبل ورعد)\n(وريح حرجف تستن فيها ... بسافي الترب تلحم ما تسدي)\n(ألم يبلغك والأنباء تنمي ... مقال محمد فيما يؤدي)\n(إلى ذي علمه الهادي علي ... وخولة خادم في البيت تردي)\n(ألم تر أن خولة سوف تأتي ... بواري الزند صافي الخيم نجد)\n(يفوز بكنيتي واسمي لأني ... نحلتهماه والمهدي بعدي)\n(يغيب عنهم حتى يقولوا ... تضمنه بطيبة بطن لحد)\n(سنين وأشهرا ويرى برضوى ... بشعب بين أنمار وأسد)\n(مقيم بين آرام وعين ... وحفان تروح خلال ربد)\n(تراعيها السباع وليس منها ... ملاقيهن مفترسا بحد)\n(أمن به الردى فرتعن طورا ... بلا خوف لدى مرعى وورد)\n(حلفت برب مكة والمصلى ... وبيت طاهر الأركان فرد)\n(يطوف به الحجيج وكل عام ... يحل لديه وفد بعد وفد)\n(لقد كان ابن خولة غير شك ... صفاء ولايتي وخلوص ودي)\n(فما أحد أحب إلي فيما ... أسر وما أبوح به وأبدي)\n(سوى ذي الوحي أحمد أو علي ... ولا أزكى وأطيب منه عندي)\n(ومن ذا يابن خولة إذ رمتني ... بأسهمها المنية حين وعدي)\n(يذيب عنكم ويسد مما ... تثلم من حصونكم كسدي)\n(وما لي أن أمر به ولكن ... أؤمل أن يؤخر يوم فقدي)\n(فأدرك دولة لك لست فيها ... بجبار فتوصف بالتعدي)\n(على قوم بغوا فيكم علينا ... لتعدي منكم يا خير معد)\n(لتعل بنا عليهم حيث كانوا ... بغور من تهامة أو بنجد)\n(إذا ما سرت من بلد حرام ... إلى من بالمدينة من معد)\n(وماذا غرهم والخير منهم ... بأشوس أعصل الأنياب ورد)\n(وأنت لمن بغى وعدا وأذكى ... عليك الحرب واسترداك مرد)\nي البيتين الأولين من هذه القصيدة غناء نسبته\n(أشاقتك المنازل بعد هند ... وتربيها وذات الدل دعد)\n(منازل أقفرت منهن محت ... معالمهن من سبل ورعد)\nروضه من الوافر الشعر للسيد الحميري والغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر عن يحيى المكي وذكر الهشامي أنه لكردم وذكر عمرو بن بانة أن اللحن لمالك ثقيل أول بالوسطى وقال إسماعيل بن الساحر راوية السيد كنت عنده يوما في جناح له فأجال بصره فيه ثم قال يا إسماعيل طال والله ما شتم أمير المؤمنين علي\nفي هذا الجناح قلت ومن كان يفعل قال أبواي وكان يذهب مذهب الكيسانية ويقول بإمامة محمد بن الحنفية وله في ذلك شعر كثير وقد روى بعض من لم تصح روايته أنه رجع عن مذهبه وقال بمذهب الإمامية وله في ذلك","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":30,"spl":"بعض أوصافه","song":1,"loc":1352},
{"id":"b74-37","bab":"الجزء 7","sec":"بعض أوصافه","page":"ج7 ص251","text":"(تجعفرت باسم الله والله أكبر ... وأيقنت أن الله يعفو ويغفر)\nوما وجدنا ذلك في رواية محصل ولا شعره أيضا من هذا الجنس ولا في هذا المذهب لأن هذا شعر ضعيف يتبين التوليد فيه وشعره في قصائده الكيسانية مباين لهذا جزالة ومتانة وله رونق ومعنى ليسا لما يذكر عنه في غيره","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":31,"spl":"بعض أوصافه — الأصمعي يمدح شعره ويذم مذهبه","loc":1353},
{"id":"b74-38","bab":"الجزء 7","sec":"الأصمعي يمدح شعره ويذم مذهبه","page":"ج7 ص255","text":"أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد الثمالي قال حدثني التوزي قال قال لي الأصمعي أحب أن تأتيني بشيء من شعر هذا الحميري فعل الله به وفعل فأتيته بشيء منه فقرأه فقال قاتله الله ما أطبعه وأسلكه لسبيل الشعراء والله لولا ما في شعره من سب السلف لما تقدمه من طبقته أحد أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال أتيت أبا عبيدة معمر بن المثنى يوما وعنده رجل من بني هاشم يقرأ عليه كتابا فلما رآني أطبقه فقال له أبو عبيدة إن أبا زيد ليس ممن يحتشم منه فأقرأ فأخذ الكتاب وجعل يقرأه فإذا هو شعر السيد فجعل أبو عبيدة يعجب منه ويستحسنه قال أبو زيد وكان أبو عبيدة يرويه قال وسمعت\nمحمد بن أبي بكر المقدمي يقول سمعت جعفر بن سليمان الضبعي ينشد شعر السيد أخبرني ابن دريد قال سئل أبو عبيدة من أشعر المولدين قال السيد وبشار وقال الموصلي حدثني عمي قال جمعت للسيد في بني هاشم ألفين وثلثمائة قصيدة فخلت أن قد استوعبت شعره حتى جلس إلي يوما رجل ذو أطمار رثة فسمعني أنشد شيئا من شعره فأنشدني له ثلاث قصائد لم تكن عندي فقلت في نفسي لو كان هذا يعلم ما عندي كله ثم أنشدني بعده ما ليس عندي لكان عجيبا فكيف وهو لا يعلم وإنما أنشد ما حضره وعرفت حينئذ أن شعره ليس مما يدرك ولا يمكن جمعه كله","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":31,"spl":"بعض أوصافه — الأصمعي يمدح شعره ويذم مذهبه","loc":1354},
{"id":"b74-39","bab":"الجزء 7","sec":"رأي بشار بالسيد الحميري","page":"ج7 ص256","text":"أخبرني عمي قال حدثني الكراني عن ابن عائشة قال وقف السيد على بشار وهو ينشد الشعر فأقبل عليه وقال\n(أيها المادح العباد ليعطى ... إن لله ما بأيدي العباد)\n(فاسأل الله ما طلبت إليهم ... وارج نفع المنزل العواد)\n(لا تقل في الجواد ما ليس فيه ... وتسمي البخيل باسم الجواد)\nقال بشار من هذا فعرفه فقال لولا أن هذا الرجل قد شغل عنا بمدح بني هاشم لشغلنا ولو شاركنا في مذهبنا لأتعبنا وروي في هذا الخبر أن\nعمران بن حطان الشاري خاطب الفرزدق بهذه المخاطبة وأجابه بهذا الجواب أخبرني علي بن سليمان الأخفش عن سعيد بن المسيب عن أبي سعيد السكري عن الطوسي قال إذا رأيت في شعر السيد دع ذا فدعه فإنه لا يأتي بعده إلا سب السلف أو بلية من بلاياه وروى الحسن بن علي بن المعتز الكوفي عن أبيه عن السيد قال رأيت النبي النوم وكأنه في حديقة سبخة فيها نخل طوال وإلى جانبها أرض كأنها الكافور ليس فيها شيء فقال أتدري لمن هذا النخل قلت لا يا رسول الله قال لامرىء القيس بن حجر فاقلعها واغرسها في هذه الأرض ففعلت وأتيت ابن سيرين فقصصت رؤياي عليه فقال أتقول الشعر قلت لا قال أما إنك ستقول شعرا مثل شعر امرىء القيس إلا أنك تقوله في قوم بررة أطهار قال فما انصرفت إلا وأنا أقول الشعر قال الحسن وحدثني غانم الوراق قال خرجت إلى بادية البصرة فصرت إلى عمرو بن تميم فأثبتني بعضهم فقال هذا الشيخ والله راوية فجلسوا إلي وأنسوا بي وأنشدتهم وبدأت بشعر ذي الرمة فعرفوه وبشعر جرير\nوالفرزدق فعرفوهما ثم أنشدتهم للسيد\n(أتعرف رسما بالسويين قد دثر ... عفته أهاضيب السحائب والمطر)\n(وجرت به الأذيال ريحان خلفة ... صبا ودبور بالعشيات والبكر)\n(منازل قد كانت تكون بجوها ... هضيم الحشاريا الشوى سحرها النظر)\n(قطوف الخطا خمصانة بخترية ... كأن محياها سنا دارة القمر)\n(رمتني ببعد بعد قرب بها النوى ... فبانت ولما أقض من عبدة الوطر)\n(ولما رأتني خشية البين موجعا ... أكفكف مني أدمعا فيضها درر)\n(أشارت بأطراف إلي ودمعها ... كنظم جمان خانه السلك فانتثر)\n(وقد كنت مما أحدث البين حاذرا ... فلم يغن عني منه خوفي والحذر)\nال فجعلوا يمرقون لإنشادي ويطربون وقالوا لمن هذا فأعلمتهم فقالوا هو والله أحد المطبوعين لا والله ما بقي في هذا الزمان مثله أخبرني الحسن بن علي قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار قال سمعت عمي يقول لو أن قصيدة السيد التي يقول فيها\n(إن يوم التطهير يوم عظيم ... خص بالفضل فيه أهل الكساء)\nقرئت على منبر ما كان فيها بأس ولو أن شعره كله كان مثله لرويناه وما عيبناه وأخبرني أبو الحسن الأسدي قال حدثنا العباس بن ميمون طائع قال حدثنا نافع عن التوزي بهذه الحكاية بعينها فإنه قالها في\n(إن يوم التطهير يوم عظيم ... )\nقال ولم يكن التوزي متشيعا قال علي بن المغيرة حدثني الحسين بن ثابت قال قدم علينا رجل بدوي وكان أروى الناس لجرير فكان ينشدني الشيء من شعره فأنشد في معناه للسيد حتى أكثرت فقال لي ويحك من هذا هو والله أشعر من صاحبنا","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":32,"spl":"رأي بشار بالسيد الحميري","loc":1355,"partial":1},
{"id":"b74-40","bab":"الجزء 7","sec":"مع السفاح وجعفر بن محمد","page":"ج7 ص259","text":"أخبرني أبو الحسن الأسدي قال حدثني الحسن بن عليل العنزي عن ابن عائشة قال لما استقام الأمر لبني العباس قام السيد إلى أبي العباس السفاح حين نزل عن المنبر فقال\n(دونكموها يا بني هاشم ... فجددوا من عهدها الدارسا)\n(دونكموها لا علا كعب من ... كان عليكم ملكها نافسا)\n(دونكموها فالبسوا تاجها ... لا تعدموا منكم له لابسا)\n(لو خير المنبر فرسانه ... ما اختار إلا منكم فارسا)\n(قد ساسها قبلكم ساسة ... لم يتركوا رطبا ولا يابسا)\n(ولست من أن تملكوها إلى ... مهبط عيسى فيكم آيسا)\nفسر أبو العباس بذلك وقال له أحسنت يا إسماعيل سلني حاجتك قال تولي سليمان بن حبيب الأهواز ففعل وذكر التميمي وهو علي بن إسماعيل عن أبيه قال كنت عند أبي عبد الله جعفر بن محمد إذ استأذن آذنه للسيد فأمره بإيصاله وأقعد حرمه خلف ستر ودخل فسلم وجلس فاستنشده فأنشده قوله\n(أمرر على جدث الحسين ... فقل لأعظمه الزكيه)\n(آأعظما لا زلت من ... وطفاء ساكبة رويه)\n(وإذا مررت بقبره ... فأطل به وقف المطيه)\n(وابك المطهر للمطهر ... والمطهرة النقيه)\n(كبكاء معولة أتت ... يوما لواحدها المنيه)\nال فرأيت دموع جعفر بن محمد تتحدر على خديه وارتفع الصراخ والبكاء من داره حتى أمره بالإمساك فأمسك قال فحدثت أبي بذلك لما انصرفت فقال لي ويلي على الكيساني الفاعل ابن الفاعل يقول\n(فإذا مررت بقبره ... فأطل به وقف المطيه)\nفقلت يا أبت وماذا يصنع قال أو لا ينحر أو لا يقتل نفسه فثكلته أمه حدثني أبو جعفر الأعرج وهو ابن بنت الفضيل بن بشار عن إسماعيل بن الساحر راوية السيد وهو الذي يقول فيه السيد في بعض قصائده\n(وإسماعيل يبرز من فلان ... ويزعم أنه للنار صالي)\nال تلاحى رجلان من بني عبد الله بن دارم في المفاضلة بعد رسول الله فرضيا بحكم أول من يطلع فطلع السيد فقاما إليه وهما لا يعرفانه فقال له مفضل علي بن أبي طالب رضي الله عنه منهما إني وهذا اختلفنا في خير الناس بعد رسول الله علي بن أبي طالب فقطع السيد كلامه ثم قال وأي شيء قال هذا الآخر ابن الزانية فضحك من حضر ووجم الرجل ولم يحر جوابا وقال التميمي وحدثني أبي قال قال لي فضيل الرسان أنشد جعفر بن محمد قصيدة السيد\n(لأم عمرو باللوى مربع ... دارسة أعلامه بلقع)\nفسمعت النحيب من داره فسألني لمن هي فأخبرته أنها للسيد وسألني عنه فعرفته وفاته فقال رحمه الله قلت إني رأيته يشرب النبيذ في\nالرستاق قال أتعني الخمر قلت نعم قال وما خطر ذنب عند الله أن يغفره لمحب علي","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":33,"spl":"مع السفاح وجعفر بن محمد — كان يقول بالرجعة","loc":1356},
{"id":"b74-41","bab":"الجزء 7","sec":"كان يقول بالرجعة","page":"ج7 ص262","text":"وأخبرني الحسن بن علي قال حدثنا محمد بن موسى قال جاء رجل إلى السيد فقال بلغني أنك تقول بالرجعة فقال صدق الذي أخبرك وهذا ديني قال أفتعطيني دينارا بمائة دينار إلى الرجعة قال السيد نعم وأكثر من ذلك إن وثقت لي بأنك ترجع إنسانا قال وأي شيء أرجع قال أخشى أن ترجع كلبا أو خنزيرا فيذهب مالي فأفحمه أخبرني الحسن بن علي قال حدثني عبد الله بن أبي سعد قال قال جعفر ابن عفان الطائي الشاعر أهدى إلي سليمان بن علي مهرا أعجبني وعزمت تربيته فلما مضت علي أشهر عزمت على الحج ففكرت في صديق لي أودعه المهر ليقوم عليه فأجمع رأيي على رجل من أهلي يقال له عمر بن حفص فصرت إليه فسألته أن يأمر سائسه بالقيام عليه وخبرته بمكانه من قلبي ودعا بسائسه فتقدم إليه في ذلك ووهبت للسائس دراهم وأوصيته به ومضيت إلى الحج ثم انصرفت وقلبي متعلق فبدأت بمنزل عمر بن حفص قبل منزلي لأعرف حال المهر فإذا هو قد ركب حتى دبر ظهره وعجف من قلة القيام عليه فقلت له يا أبا حفص أهكذا أوصيتك في هذا المهر فقال وما ذنبي لم ينجع فيه العلف فانصرفت به وقلت\n(من عاذري من أبي حفص وثقت به ... وكان عندي له في نفسه خطر)\n(فلم يكن عند ظني في أمانته ... والظن يخلف والإنسان يختبر)\n(أضاع مهري ولم يحسن ولايته ... حتى تبين فيه الجهد والضرر)\n(عاتبته فيه في رفق فقلت له ... يا صاح هل لك من عذر فتعتذر)\n(فقال داء به قدما أضر به ... وداؤه الجوع والإتعاب والسفر)\n(قد كان لي في اسمه عنه وكنيته ... لو كنت معتبرا ناه ومعتبر)\n(فكيف ينصحني أو كيف يحفظني ... يوما إذا غبت عنه واسمه عمر)\n(لو كان لي ولد شتى لهم عدد ... فيهم سميوه إن قلوا وإن كثروا)\n(لم ينصحوا لي ولم يبقوا علي ولو ... ساوى عديدهم الحصباء والشجر)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":33,"spl":"مع السفاح وجعفر بن محمد — كان يقول بالرجعة","loc":1357},
{"id":"b74-42","bab":"الجزء 7","sec":"نصيحته للمهدي","page":"ج7 ص263","text":"قال وحدثني أبو سليمان الناجي قال جلس المهدي يوما يعطي قريشا صلات لهم وهو ولي عهد فبدأ ببني هاشم ثم بسائر قريش فجاء السيد فرفع إلى الربيع رقعة مختومة وقال إن فيها نصيحة للأمير فأوصلها إليه فأوصلها فإذا فيها\n(قل لابن عباس سمي محمد ... لا تعطين بني عدي درهما)\n(احرم بني تيم بن مرة إنهم ... شر البرية آخرا ومقدما)\n(إن تعطهم لا يشكروا لك نعمة ... ويكافئوك بأن تذم وتشتما)\n(وإن ائتمنتهم أو استعملتهم ... خانوك واتخذوا خراجك مغنما)\n(ولئن منعتهم لقد بدأوكم ... بالمنع إذ ملكوا وكانوا أظلما)\n(منعوا تراث محمد أعمامه ... وابنيه وابنته عديلة مريما)\n(وتأمروا من غير أن يستخلفوا ... وكفى بما فعلوا هنالك مأثما)\n(لم يشكروا لمحمد إنعامه ... أفيشكرون لغيره إن أنعما)\n(والله من عليهم بمحمد ... وهداهم وكسا الجنوب وأطعما)\n(ثم انبروا لوصيه ووليه ... بالمنكرات فجرعوه العلقما)\nهي قصيدة طويلة حذف باقيها لقبح ما فيه قال فرمى بها إلى أبي عبيد الله ثم قال اقطع العطاء فقطعه وانصرف الناس ودخل السيد إليه فلما رآه ضحك وقال قد قبلنا نصيحتك يا اسماعيل ولم يعطهم شيئا أخبرني به عمي عن محمد بن داود بن الجراح عن إسحاق النخعي عن أبي سلمان الرياحي مثله","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":34,"spl":"نصيحته للمهدي","loc":1358},
{"id":"b74-43","bab":"الجزء 7","sec":"السيد الحميري وشيطان الطاق","page":"ج7 ص264","text":"أخبرني الحسن بن محمد بن الجمهور القمي قال حدثني أبي قال حدثني أبو داود المسترق راوية السيد أنه حضر يوما وقد ناظره محمد بن علي بن النعمان المعروف بشيطان الطاق في الإمامة فغلبه محمد في دفع ابن الحنفية عن الإمامة فقال السيد\n(ألا يأيها الجدل المعني ... لنا ما نحن ويحك والعناء)\n(أتبصر ما تقول وأنت كهل ... تراك عليك من ورع رداء)\n(ألا إن الأئمة من قريش ... ولاة الحق أربعة سواء)\n(علي والثلاثة من بنيه ... هم أسباطه والأوصياء)\n(فأنى في وصيته إليهم ... يكون الشك منا والمراء)\n(بهم أوصاهم ودعا إليه ... جميع الخلق لو سمع الدعاء)\n(فسبط سبط إيمان وحلم ... وسبط غيبته كربلاء)\n(سقى جدثا تضمنه ملث ... هتوف الرعد مرتجز رواء)\n(تظل مظلة منها عزال ... عليه وتغتدي أخرى ملاء)\n(وسبط لا يذوق الموت حتى ... يقود الخيل يقدمها اللواء)\n(من البيت المحجب في سراة ... شراة لف بينهم الإخاء)\n(عصائب ليس دون أغر أجلي ... بمكة قائم لهم انتهاء)\nوهذه الأبيات بعينها تروى لكثير ذكر ذلك ابن أبي سعد فقال وأخبرني أحمد بن عبد العزيز قال حدثنا علي بن محمد النوفلي قال حدثني إبراهيم بن هاشم العبدي البصري قال رأيت النبي في المنام وبين يديه السيد الشاعر وهو ينشد\n(أجد بآل فاطمة البكور ... فدمع العين منهمر غزير)\nحتى أنشده إياها على آخرها وهو يسمع قال فحدثت هذا الحديث رجلا جمعتني وإياه طوس عند قبر علي بن موسى الرضا فقال لي والله لقد كنت على خلاف فرأيت النبي في المنام وبين يديه رجل ينشد\n(أجد بآل فاطمة البكور ... )\nإلى آخرها فاستيقظت من نومي وقد رسخ في قلبي من حب علي بن أبي طالب رضي الله عنه ما كنت أعتقده أخبرني وكيع قال حدثني إسحاق بن محمد قال حدثنا أبو سليمان الناجي ومحمد بن حليم الأعرج قالا كان السيد إذا استنشد شيئا من شعره لم يبدأ بشيء إلا بقوله\n(أجد بآل فاطمة البكور ... فدمع العين منهمر غزير)\nقال إسحاق وسمعت العتبي يقول ليس في عصرنا هذا أحسن مذهبا في شعره ولا أنقى ألفاظا من السيد ثم قال لبعض من حضر أنشدنا قصيدته اللامية التي أنشدتناها اليوم فأنشده قوله\n(هل عند من أحببت تنويل ... أم لا فإن اللوم تضليل)\n(أم في الحشى منك جوى باطن ... ليس تداويه الأباطيل)\n(علقت يا مغرور خداعة ... بالوعد منها لك تخييل)\n(ريا رداح النوم خمصانة ... كأنها أدماء عطبول)\n(يشفيك منها حين تخلو بها ... ضم إلى النحر وتقبيل)\n(وذوق ريق طيب طعمه ... كأنه بالمسك معلول)\n(في نسوة مثل المها خرد ... تضيق عنهن الخلاخيل)\nيقول فيها\n(أقسم بالله وآلائه ... والمرء عما قال مسؤول)\n(إن علي بن أبي طالب ... على التقى والبر مجبول)\nقال العتبي أحسن والله ما شاء هذا والله الشعر الذي يهجم على القلب بلا حجاب في البيتين الأولين من هذه القصيدة لمخارق رمل بالبنصر عن الهشامي وذكر حبش أنه للغريض وفيه لحن لسليمان من كتب بذل غير مجنس أخبرني عمي قال حدثني محمد بن داود بن الجراح قال حدثني إسحاق\nابن محمد النخعي عن عبد الحميد بن عقبة عن إسحاق بن ثابت العطار قال كنا كثيرا ما نقول للسيد مالك لا تستعمل في شعرك من الغريب ما تسأل عنه كما يفعل الشعراء قال لأن أقول شعرا قريبا من القلوب يلذه من سمعه خير من أن أقول شيئا متعقدا تضل فيه الأوهام","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":35,"spl":"السيد الحميري وشيطان الطاق","loc":1359,"partial":1}]);
window.__BOOK__['p04'].push([{"id":"b74-44","bab":"الجزء 7","sec":"يسب محارب بن دثار ويترحم على أبي الأسود","page":"ج7 ص268","text":"أخبرني أحمد بن عمار قال أخبرنا يعقوب بن نعيم قال حدثني إبراهيم ابن عبد الله الطلحي راوية الشعراء بالكوفة قال حدثنا أبو مسعود عمرو بن عيسى الرباح ومحمد بن سلمة يزيد بعضهم على بعض أن السيد لما قدم الكوفة أتاه محمد بن سهل راوية الكميت فأقبل عليه السيد فقال من الذي يقول\n(يعيب علي أقوام سفاها ... بأن أرجي أبا حسن عليا)\n(وإرجائي أبا حسن صواب ... عن العمرين برا أو شقيا)\n(فإن قدمت قوما قال قوم ... أسأت وكنت كذابا رديا)\n(إذا أيقنت أن الله ربي ... وأرسل أحمدا حقا نبيا)\n(وأن الرسل قد بعثوا بحق ... وأن الله كان لهم وليا)\n(فليس علي في الإرجاء بأس ... ولا لبس ولست أخاف شيا)\nفقال محمد بن سهل هذا يقوله محارب بن دثار الذهلي فقال\nالسيد لا كان الله وليا للعاض بظر أمه من ينشدنا قصيدة أبي الأسود\n(أحب محمدا حبا شديدا ... وعباسا وحمزة والوصيا)\nفأنشده القصيدة بعض من كان حاضرا فطفق يسب محارب بن دثار ويترحم على أبي الأسود فبلغ الخبر منصورا النمري فقال ما كان على أبي هاشم لو هجاه بقصيدة يعارض بها أبياته ثم قال\n(يود محارب لو قد رآها ... وأبصرهم حواليها جثيا)\n(وأن لسانه من ناب أفعى ... وما أرجا أبا حسن عليا)\n(وأن عجوزه مصعت بكلب ... وكان دماء ساقيها جريا)\n(متى ترجىء أبا حسن عليا ... فقد أرجيت يا لكع نبيا)\nخبرني محمد بن جعفر النحوي قال حدثنا أحمد بن القاسم البزي قال حدثني إسحاق بن محمد النخعي قال حدثني إبراهيم بن الحسن الباهلي قال دخلت على جعفر بن سليمان الضبعي ومعي أحاديث لأسأله عنها وعنده قوم لم أعرفهم وكان كثيرا ما ينشد شعر السيد فمن أنكره عليه لم يحدثه فسمعته ينشدهم\n(ما تعدل الدنيا جميعا كلها ... من حوض أحمد شربة من ماء)\nثم جاءه خبر فقام فقلت للذين كانوا عنده من يقول هذا الشعر قالوا السيد الحميري\nحدثني عمي والكراني قالا حدثنا عبد الله بن أبي سعد عن عبد الله بن الحسين عن أبي عمرو الشيباني عن الحارث بن صفوان وأخبرني به الحسين ابن يحيى عن حماد بن إسحاق عن أبيه أن السيد كان بالأهواز فمرت به امرأة من آل الزبير تزف إلى إسماعيل ابن عبد الله بن العباس وسمع الجلبة فسأل عنها فأخبر بها فقال\n(أتتنا تزف على بغلة ... وفوق رحالتها قبه)\n(زبيرية من بنات الذي ... أحل الحرام من الكعبه)\n(تزف إلى ملك ماجد ... فلا اجتمعا وبها الوجبه)\nوى هذا الخبر إسماعيل بن الساحر فقال فيه فدخلت في طريقها إلى خربة للخلاء فنهشتها أفعى فماتت فكان السيد يقول لحقتها دعوتي حدثني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل عن أبي طالب الجعفري وهو محمد بن عبد الله بن الحسين بن عبد الله بن إسماعيل بن جعفر قال أخبرني أبي قال خرج أهل البصرة يستسقون وخرج فيهم السيد وعليه ثياب خز وجبة ومطرف وعمامة فجعل يجر مطرفه ويقول\n(اهبط إلى الأرض فخذ جلمدا ... ثم ارمهم يا مزن بالجلمد)\n(لا تسقهم من سبل قطرة ... فإنهم حرب بني أحمد)\nخبرني محمد بن العباس اليزيدي قال حدثنا محمد بن إسحاق البغوي\nقال حدثنا الحرمازي قال حدثني رجل قال كنت أختلف إلى ابني قيس وكانا يرويان عن الحسن فلقيني السيد يوما وأنا منصرف من عندهما فقال أرني ألواحك أكتب فيها شيئا وإلا أخذتها فمحوت ما فيها فأعطيته ألواحي فكتب فيها\n(لشربة من سويق عند مسغبة ... وأكلة من ثريد لحمه واري)\n(أشد مما روى حبا إلي بنو ... قيس ومما روى صلت بن دينار)\n(مما رواه فلان عن فلانهم ... ذاك الذي كان يدعوهم إلى النار)\nخبرني أحمد بن علي الخفاف قال حدثني أبو إسماعيل إبراهيم بن أحمد بن إسماعيل بن إبراهيم بن حسن بن طباطبا قال سمعت زيد بن موسى بن جعفر يقول رأيت رسول الله في النوم وقدامه رجل جالس عليه ثياب بيض فنظرت إليه فلم أعرفه إذ التفت إليه رسول الله يا سيد أنشدني قولك\n(لأم عمرو في اللوى مربع ... )\nفأنشده إياها كلها ما غادر منها بيتا واحدا فحفظتها عنه كلها في النوم قال أبو إسماعيل وكان زيد بن موسى لحانة رديء الإنشاد فكان إذا أنشد هذه القصيدة لم يتتعتع فيها ولم يلحن وقال محمد بن داود بن الجراح في روايته عن إسحاق النخعي حدثني","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":36,"spl":"يسب محارب بن دثار ويترحم على أبي الأسود","loc":1360,"partial":1},
{"id":"b74-45","bab":"الجزء 7","sec":"يسب محارب بن دثار ويترحم على أبي الأسود","page":"ج7 ص268","text":"عبد الرحمن بن محمد الكوفي عن علي بن إسماعيل الهيثمي عن فضيل الرسان قال دخلت على جعفر بن محمد أعزيه عن عمه زيد ثم قلت له ألا أنشدك شعر السيد فقال أنشد فأنشدته قصيدة يقول فيها\n(فالناس يوم البعث راياتهم ... خمس فمنها هالك أربع)\n(قائدها العجل وفرعونهم ... وسامري الأمة المفظع)\n(ومارق من دينه مخرج ... أسود عبد لكع أوكع)\n(وراية قائدها وجهه ... كأنه الشمس إذا تطلع)\nفسمعت مجيبا من وراء الستور فقال من قائل هذا الشعر فقلت السيد فقال رحمه الله فقلت جعلت فداك إني رأيته يشرب الخمر فقال رحمه الله فما ذنب على الله أن يغفره لآل علي إن محب علي لا تزل له قدم إلا تثبت له أخرى حدثني الأخفش عن أبي العيناء عن علي بن الحسن بن علي بن الحسين عن أبيه عن جعفر بن محمد أنه ذكر السيد فترحم عليه وقال إن زلت له قدم فقد ثبتت الأخرى نسخت من كتاب الشاهيني حدثني محمد بن سهل الحميري عن أبيه قال انحدر السيد الحميري في سفينة إلى الأهواز فماراه رجل في تفضيل علي وباهله على ذلك فلما كان الليل قام الرجل ليبول على حرف\nالسفينة فدفعه السيد فغرفه فصاح الملاحون غرق والله الرجل فقال السيد دعوه فإنه باهلي أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد المبرد قال حدثني التوزي قال جلس السيد يوما إلى قوم فجعل ينشدهم وهم يلغطون فقال\n(قد ضيع الله ما جمعت من أدب ... بين الحمير وبين الشاء والبقر)\n(لا يسمعون إلى قول أجيء به ... وكيف تستمع الأنعام للبشر)\n(أقول ما سكتوا إنس فإن نطقوا ... قلت الضفادع بين الماء والشجر)\nخبرني محمد بن جعفر النحوي قال حدثنا أحمد بن القاسم البزي قال حدثنا إسحاق بن محمد النخعي عن محمد بن الربيع عن سويد بن حمدان ابن الحصين قال كان السيد يختلف إلينا ويغشانا فقام من عندنا ذات يوم فخلفه رجل وقال لكم شرف وقدر عند السلطان فلا تجالسوا هذا فإنه مشهور بشرب الخمر وشتم السلف فبلغ ذلك السيد فكتب إليه\n(وصفت لك الحوض يابن الحصين ... على صفة الحارث الأعور)\n(فإن تسق منه غدا شربة ... تفز من نصيبك بالأوفر)\n(فما لي ذنب سوى أنني ... ذكرت الذي فر عن خيبر)\n(ذكرت امرأ فر عن مرحب ... فرار الحمار من القسور)\n(فأنكر ذاك جليس لكم ... زنيم أخو خلق أعور)\n(لحاني بحب إمام الهدى ... وفاروق أمتنا الأكبر)\n(سأحلق لحيته إنها ... شهود على الزور والمنكر)\nقال فهجر والله مشايخنا جميعا ذلك الرجل ولزموا محبة السيد ومجالسته","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":37,"spl":"يسب محارب بن دثار ويترحم على أبي الأسود","loc":1361},
{"id":"b74-46","bab":"الجزء 7","sec":"هجاؤه سوار القاضي","page":"ج7 ص274","text":"أخبرني الحسن بن علي قال حدثنا محمد بن زكريا الغلابي قال حدثنا مهدي بن سابق أن السيد تقدم إلى سوار القاضي ليشهد عنده وقد كان دافع المشهود له بذلك وقال أعفني من الشهادة عند سوار وبذل له مالا فلم يعفه فلما تقدم إلى سوار فشهد قال ألست المعروف بالسيد قال بلى قال استغفر الله من ذنب تجرأت به على الشهادة عندي قم لا أرضى بك\nفقام مغضبا من مجلسه وكتب إلى سوار رقعة فيها يقول\n(إن سوار بن عبد الله ... من شر القضاة)\nفلما قرأها سوار وثب عن مجلسه وقصد أبا جعفر المنصور وهو يومئذ نازل بالجسر فسبقه السيد إليه فأنشده\n(قل للإمام الذي ينجى بطاعته ... يوم القيامة من بجبوحة النار)\n(لا تستعينن جزاك الله صالحة ... يا خير من دب في حكم بسوار)\n(لا تستعن بخبيث الرأي ذي صلف ... جم العيوب عظيم الكبر جبار)\n(تضحي الخصوم لديه من تجبره ... لا يرفعون إليه لحظ أبصار)\n(تيها وكبرا ولولا ما رفعت له ... من ضبعه كان عين الجائع العاري)\nودخل سوار فلما رآه المنصور تبسم وقال أما بلغك خبر إياس بن معاوية حيث قبل شهادة الفرزدق واستزاد في الشهود فما أحوجك للتعريض للسيد ولسانه ثم أمر السيد بمصالحته وقال إسحاق بن محمد النخعي حدثني عبد الله بن محمد الجعفري قال حدثني محمد بن عبد الله الحميري قال دخل السيد على المهدي لما بايع لابنيه موسى وهارون فأنشأ يقول\n(ما بال مجرى دمعك الساجم ... أمن قذى بات بها لازم)\n(أم من هوى أتت له ساهر ... صبابة من قلبك الهائم)\n(آليت لا أمدح ذا نائل ... من معشر غير بني هاشم)\n(أولتهم عندي يد المصطفى ... ذي الفضل والمن أبي القاسم)\n(فإنها بيضاء محمودة ... جزاؤها الشكر على العالم)\n(جزاؤها حفظ أبي جعفر ... خليفة الرحمن والقائم)\n(وطاعة المهدي ثم ابنه ... موسى على ذي الإربة الحازم)\n(وللرشيد الرابع المرتضى ... مفترض من حقه اللازم)\n(ملكهم خمسون معدودة ... برغم أنف الحاسد الراغم)\n(ليس علينا ما بقوا غيرهم ... في هذه الأمة من حاكم)\n(حتى يردوها إلى هابط ... عليه عيسى منهم ناجم)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":38,"spl":"هجاؤه سوار القاضي","loc":1362},
{"id":"b74-47","bab":"الجزء 7","sec":"حبه لعلي بن أبي طالب","page":"ج7 ص276","text":"وقال علي بن المغيرة حدثني علي بن عبد الله السدوسي عن المدائني قال كان السيد يأتي الأعمش فيكتب عنه فضائل علي رضي الله عنه ويخرج من عنده ويقول في تلك المعاني شعرا فخرج ذات يوم من عند بعض أمراء الكوفة وقد حمله على فرس وخلع عليه فوقف بالكناسة ثم\nقال يا معشر الكوفيين من جاءني منكم بفضيلة لعلي بن أبي طالب لم أقل فيها شعرا أعطيته فرسي هذا وما علي فجعلوا يحدثونه وينشدهم حتى أتاه رجل منهم وقال إن أمير المؤمنين علي بن أبي طالب رضي الله تعالي عنه عزم على الركوب فلبس ثيابه وأراد لبس الخف فلبس أحد خفيه ثم أهوى إلى الآخر ليأخذه فانقض عقاب من السماء فحلق به ثم ألقاه فسقط منه أسود وانساب فدخل حجرا فلبس علي رضي الله عنه الخف قال ولم يكن قال في ذلك شيئا ففكر هنيهة ثم قال\n(ألا يا قوم للعجب العجاب ... لخف أبي الحسين وللحباب)\n(أتى خفا له وانساب فيه ... لينهش رجله منه بناب)\n(فخر من السماء له عقاب ... من العقبان أو شبه العقاب)\n(فطار به فحلق ثم أهوى ... به للأرض من دون السحاب)\n(إلى حجر له فانساب فيه ... بعيد القعر لم يرتج بباب)\n(كريه الوجه أسود ذو بصيص ... حديد الناب أزرق ذو لعاب)\n(ودوفع عن أبي حسن علي ... نقيع سمامه بعد انسياب)\nثم حرك فرسه ومضى وجعل تشبيبها بعد ذلك\n(صبوت إلى سليمى والرباب ... وما لأخي المشيب وللتصابي)\nخبرني أحمد بن محمد بن محمد بن سعيد قال حدثني عبد الله بن أحمد بن مستورد قال\nوقف السيد يوما بالكوفة فقال من أتاني بفضيلة لعلي بن أبي طالب ما قلت فيها شعرا فله دينار وذكر باقي الحديث فأما العقاب الذي انقض على خف علي بن أبي طالب رضى الله عنه فحدثني بخبره أحمد بن محمد ابن محمد بن سعيد الهمداني قال حدثني جعفر بن علي بن نجيح قال حدثنا أبو عبد الرحمن المسعودي عن أبي داود الطهوي عن أبي الزعل المرادي قال قام علي بن أبي طالب رضي الله عنه فتطهر للصلاة ثم نزع خفه فانساب فيه أفعى فلما عاد ليلبسه انقضت عقاب فأخذته فحلقت به ثم ألقته فخرج الأفعى منه وقد روي مثل هذا لرسول الله حدثني به أحمد بن محمد بن محمد بن سعيد قال حدثني محمد بن عبيد بن عقبة قال حدثنا محمد بن الصلت قال حدثنا حيان بن علي عن أبي سعيد عن عكرمة عن ابن عباس قال كان النبي إذا أراد حاجة تباعد حتى لا يراه أحد فنزع خفه فإذا عقاب قد تدلى فرفعه فسقط منه أسود سالخ فكان النبي يقول ( اللهم إني أعوذ بك من شر ما يمشي على بطنه ومن شر ما يمشي على رجليه ومن شر ما يمشي على أربع ومن شر الجن والإنس\nال أبو سعيد وحدثنا محمد بن إسماعيل الراشدي قال حدثنا عثمان بن سعيد قال حدثنا حيان بن علي عن سعد بن طريف عن عكرمة عن ابن عباس مثله أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا حاتم بن قبيصة قال سمع السيد محدثا يحدث أن النبي كان ساجدا فركب الحسن والحسين على ظهره فقال عمر رضي الله عنه نعم المطي مطيكما فقال\nالنبي الراكبان هما فانصرف السيد من فوره فقال في ذلك\n(أتى حسنا والحسين النبي ... وقد جلسا حجرة يلعبان)\n(ففداهما ثم حياهما ... وكانا لديه بذاك المكان)\n(فراحا وتحتهما عاتقاه ... فنعم المطية والراكبان)\n(وليدان أمهما برة ... حصان مطهرة للحصان)\n(وشيخهما ابن أبي طالب ... فنعم الوليدان والوالدان)\n(خليلي لا ترجيا واعلما ... بأن الهدى غير ما تزعمان)\n(وأن عمى الشك بعد اليقين ... وضعف البصيرة بعد العيان)\n(ضلال فلا تلججا فيهما ... فبئست لعمركما الخصلتان)\n(أيرجى علي إمام الهدى ... وعثمان ما أعند المرجيان)\n(ويرجى ابن حرب وأشياعه ... وهوج الخوارج بالنهروان)\n(يكون إمامهم في المعاد ... خبيث الهوى مومن الشيصبان)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":39,"spl":"حبه لعلي بن أبي طالب","loc":1363},
{"id":"b74-48","bab":"الجزء 7","sec":"مدح المنصور","page":"ج7 ص279","text":"وذكر إسماعيل بن الساحر قال أخبرنا أحمد بن عبد العزيز الجوهري قال حدثني محمد عن أبيه قال حدثني أبي وعمي عن أحمد بن إبراهيم بن سليمان بن يعقوب بن سعيد بن عمرو قال حدثنا الحارث بن عبد المطلب قال\nكنت جالسا في مجلس أبي جعفر المنصور وهو بالجسر وهو قاعد مع جماعة على دجلة بالبصرة وسوار بن عبد الله العنبري قاضي البصرة جالس عنده والسيد بن محمد بين يديه ينشد قوله\n(إن الاله الذي لا شيء يشبهه ... أعطاكم الملك للدنيا وللدين)\n(أعطاكم الله ملكا لا زوال له ... حتى يقاد اليكم صاحب الصين)\n(وصاحب الهند مأخوذا برمته ... وصاحب الترك محبوسا على هون)\nوالمنصور يضحك سرورا بما ينشده فحانت منه التفاتة فرأى وجه سوار يتربد غيظا ويسود حنقا ويدلك إحدى يديه بالأخرى ويتحرق فقال له المنصور مالك أرابك شيء قال نعم هذا الرجل يعطيك بلسانه ما ليس في قلبه والله يا أمير المؤمنين ما صدقك ما في نفسه وإن الذين يواليهم لغيركم فقال المنصور مهلا هذا شاعرنا وولينا وما عرفت منه إلا صدق محبة وإخلاص نية فقال له السيد يا أمير المؤمنين والله ما تحملت غضكم لأحد وما وجدت أبوي عليه فافتتنت بهما وما زلت مشهورا بموالاتكم في أيام عدوكم فقال له صدقت قال ولكن هذا وأهلوه أعداء الله ورسوله قديما والذين نادوا رسول الله وراء الحجرات فنزلت فيهم آية من القرآن ( أكثرهم لا يعقلون\nوجرى بينهما خطاب طويل فقال السيد قصيدته التي أولها\n(قف بنا يا صاح واربع ... بالمغاني الموحشات)\nأنشدها أحمد بن عبيد الله بن عمار عن النوفلي وأخبرنا محمد بخبره مع سوار بالقصة من ها هنا إلى آخرها وقال فيها\n(يا أمين الله يا منصور ... يا خير الولاة)\n(إن سوار بن عبد الله ... من شر القضاة)\n(نعثلي جملي ... لكم غير موات)\n(جده سارق عنز ... فجرة من فجرات)\n(لرسول الله والقاذفه ... بالمنكرات)\n(وابن من كان ينادي ... من وراء الحجرات)\n(يا هناة أخرج إلينا ... إننا أهل هنات)\n(مدحنا المدح ومن نرم ... يصب بالزفرات)\n(فاكفنيه لا كفاه الله ... شر الطارقات)\nفشكاه سوار إلى أبي جعفر فأمره بأن يصير إليه معتذرا ففعل فلم يعذره فقال\n(أتيت دعي بني العنبر ... أروم اعتذارا فلم أعذر)\n(فقلت لنفسي وعاتبتها ... على اللؤم في فعلها أقصري)\n(أيعتذر الحر مما أتى ... إلى رجل من بني العنبر)\n(أبوك ابن سارق عنز النبي ... وأمك بنت أبي جحدر)\n(ونحن على رغمك الرافضون ... لأهل الضلالة والمنكر)\nقال وبلغ السيد أن سوارا قد أعد جماعة يشهدون عليه بسرقة ليقطعه فشكاه إلى أبي جعفر فدعا بسوار وقال له قد عزلتك عن الحكم للسيد أو عليه فما تعرض له بسوء حتى مات وروى عبد الله بن أبي بكر العتكي أن أبا الخلال العتكي دخل على عقبة بن سلم والسيد عنده وقد أمر له بجائزة وكان أبو الخلال شيخ العشيرة وكبيرها فقال له أيها الأمير أتعطي هذه العطايا رجلا ما يفتر عن سب أبي بكر وعمر فقال له عقبة ما علمت ذاك ولا أعطيته إلا على العشرة والمودة القديمة وما يوجبه حقه وجواره مع ما هو عليه من موالاة قوم يلزمنا حقهم ورعايتهم فقال له أبو الخلال فمره إن كان صادقا أن يمدح أبا بكر وعمر حتى نعرف براءته مما ينسب إليه من الرفض فقال قد سمعك فإن شاء فعل فقال السيد\n(إذا أنا لم أحفظ وصاة محمد ... ولا عهده يوم الغدير المؤكدا)\n(فإني كمن يشري الضلالة بالهدى ... تنصر من بعد التقى وتهودا)\n(وما لي وتيم أو عدي وإنما ... أولو نعمتي في الله من آل أحمدا)\n(تتم صلاتي بالصلاة عليهم ... وليست صلاتي بعد أن أتشهدا)\n(بكاملة إن لم أصل عليهم ... وأدع لهم ربا كريما ممجدا)\n(بذلت لهم ودي ونصحي ونصرتي ... مدى الدهر ما سميت يا صاح سيدا)\n(وإن امرأ يلحى على صدق ودهم ... أحق وأولى فيهم أن يفندا)\n(فإن شئت فاختر عاجل الغم ضلة ... وإلا فأمسك كي تصان وتحمدا)\nثم نهض مغضبا فقام أبو الخلال إلى عقبة فقال أعذني من شره أعاذك الله من السوء أيها الأمير قال قد فعلت على ألا تعرض له بعدها","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":40,"spl":"مدح المنصور","loc":1364},
{"id":"b74-49","bab":"الجزء 7","sec":"خبر زواجه من امرأة تميمية","page":"ج7 ص283","text":"ومما يحكى عنه أنه اجتمع في طريقه بامرأة تميمية إباضية فأعجبها وقالت أريد أن أتزوج بك ونحن على ظهر الطريق قال يكون كنكاح أم خارجة قبل حضور ولي وشهود فاستضحكت وقالت ننظر في هذا وعلى ذلك فمن أنت فقال\n(إن تسأليني بقومي تسألي رجلا ... في ذروة العز من أحياء ذي يمن)\n(حولي بها ذو كلاع في منازلها ... وذو رعين وهمدان وذو يزن)\n(والأزد أزد عمان الأكرمون إذا ... عدت مآثرهم في سالف الزمن)\n(بانت كريمتهم عني فدارهم ... داري وفي الرحب من أوطانهم وطني)\n(لي منزلان بلحج منزل وسط ... منها ولي منزل للعز في عدن)\n(ثم الولاء الذي أرجو النجاة به ... من كبة النار للهادي أبي حسن)\nفقالت قد عرفناك ولا شيء أعجب من هذا يمان وتميمية ورافضي وإباضية فكيف يجتمعان فقال بحسن رأيك في تسخو نفسك ولا يذكر أحدنا سلفا ولا مذهبا قالت أفليس التزويج إذا علم انكشف معه المستور وظهرت خفيات الأمور قال فأنا أعرض عليك أخرى قالت ما هي قال المتعة التي لا يعلم بها أحد قالت تلك أخت الزنا قال أعيذك بالله أن تكفري بالقرآن بعد الإيمان قالت فكيف قال قال الله تعال ( فما استمتعتم به منهن فآتوهن أجورهن فريضة ولا جناح عليكم فيما تراضيتم به من بعد الفريضة\nفقالت أستخير الله وأقلدك إن كنت صاحب قياس ففعلت فانصرفت معه وبات معرسا بها وبلغ أهلها من الخوارج أمرها فتوعدوها بالقتل وقالوا تزوجت بكافر فجحدت ذلك ولم يعلموا بالمتعة فكانت مدة تختلف إليه على هذه السبيل من المتعة وتواصله حتى افترقا","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":41,"spl":"خبر زواجه من امرأة تميمية — ابن سليمان بن علي يعارضه في مذهبه","loc":1365},
{"id":"b74-50","bab":"الجزء 7","sec":"ابن سليمان بن علي يعارضه في مذهبه","page":"ج7 ص285","text":"وقال الحسن بن علي بن المغيرة حدثني أبي قال كنت مع السيد على باب عقبة بن سلم ومعنا ابن لسليمان بن علي ننتظره وقد أسرج له ليركب إذ قال ابن سليمان بن علي يعرض بالسيد أشعر الناس والله الذي يقول\n(محمد خير من يمشي على قدم ... وصاحباه وعثمان بن عفانا)\nفوثب السيد وقال أشعر والله منه الذي يقول\n(سائل قريشا إذا ما كنت ذا عمه ... من كان أثبتها في الدين أوتادا)\n(من كان أعلمها علما وأحلمها ... حلما وأصدقها قولا وميعادا)\n(إن يصدقوك فلن يعدوا أبا حسن ... إن أنت لم تلق للأبرار حسادا)\nثم أقبل على الهاشمي فقال يا فتى نعم الخلف أنت لشرف سلفك أراك تهدم شرفك وتثلب سلفك وتسعى بالعداوة على أهلك وتفضل من ليس أصلك من أصله على من فضلك من فضله وسأخبر أمير المؤمنين عنك بذا حتى يضعك فوثب الفتى خجلا ولم ينتظر عقبة بن سلم وكتب إليه صاحب خبره بما جرى عند الركوبة حتى خرجت الجائزة للسيد أخبرني محمد بن جعفر النحوي قال حدثنا ابن القاسم البزي عن إسحاق بن محمد النخعي عن عقبة بن مالك الديلي عن الحسن بن علي بن أبي حرب بن أبي الأسود الدؤلي قال كنا جلوسا عند أبي عمرو بن العلاء فتذاكرنا السيد فجاء فجلس وخضنا في ذكر الزرع والنخل ساعة فنهض فقلنا يا أبا هاشم مم القيام فقال\n(إني لأكره أن أطيل بمجلس ... لا ذكر فيه لفضل آل محمد)\n(لا ذكر فيه لأحمد ووصيه ... وبنيه ذلك مجلس نطف ردي)\n(إن الذي ينساهم في مجلس ... حتى يفارقه لغير مسدد)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":41,"spl":"خبر زواجه من امرأة تميمية — ابن سليمان بن علي يعارضه في مذهبه","loc":1366},
{"id":"b74-51","bab":"الجزء 7","sec":"العسس يحبس السيد الحميري","page":"ج7 ص286","text":"وروى أبو سليمان الناجي أن السيد قدم الأهواز وأبو بجير بن سماك\nالأسدي يتولاها وكان له صديقا وكان لأبي بجير مولى يقال له يزيد بن مذعور يحفظ شعر السيد ينشده أبا بجير وكان أبو بجير يتشيع فذهب السيد إلى قوم من إخوانه بالأهواز فنزل بهم وشرب عندهم فلما أمسى انصرف فأخذه العسس فحبس فكتب من غده بهذه الأبيات وبعث بها إلى يزيد بن مذعور فدخل على أبي بجير وقال قد جنى عليك صاحب عسسك ما لا قوام لك به قال وما ذلك قال اسمع هذه الأبيات كتبها السيد من الحبس فأنشده يقول\n(قف بالديار وحيها يا مربع ... واسأل وكيف يجيب من لا يسمع)\n(إن الديار خلت وليس بجوها ... إلا الضوابح والحمام الوقع)\n(ولقد تكون بها أوانس كالدمى ... جمل وعزة والرباب وبوزع)\n(حور نواعم لا ترى في مثلها ... أمثالهن من الصيانة أربع)\n(فعرين بعد تألف وتجمع ... والدهر صاح مشتت ما تجمع)\n(فاسلم فإنك قد نزلت بمنزل ... عند الأمير تضر فيه وتنفع)\n(تؤتى هواك إذا نطقت بحاجة ... فيه وتشفع عنده فيشفع)\n(قل للأمير إذا ظفرت بخلوة ... منه ولم يك عنده من يسمع)\n(هب لي الذي أحببته في أحمد ... وبنيه إنك حاصد ما تزرع)\n(يختص آل محمد بمحبة ... في الصدر قد طويت عليها الأضلع)\nفي هذا الغناء لسعيد وحكى ابن الساحر أن السيد دعي لشهادة عند سوار القاضي فقال لصاحب الدعوى أعفني من الشهادة عند سوار فلم يعفه صاحبها منها\nوطالبه بإقامتها عند سوار فلما حضر عنده وشهد قال له ألم أعرفك وتعرفني وكيف مع معرفتك بي تقدم على الشهادة عندي فقال له إني تخوفت إكراهه ولقد افتديت شهادتي عندك بمال فلم يقبل مني فأقمتها فلا يقبل الله لك صرفا ولا عدلا إن قبلتها وقام من عنده ولم يقدر سوار له على شيء لما تقدم به المنصور إليه في أمره واغتاظ غيظا شديدا وانصرف من مجلسه فلم يقض يومئذ بين اثنين ثم إن سوارا اعتل علته التي مات فيها فلم يقدر السيد على هجائه في حياته لنهي المنصور إياه عن ذلك ومات سوار فأخرج عشيا وحفر له فوقع الحفر في موضع كنيف وكان بين الأزد وبين تميم عداوة فمات عقب موته عباد بن حبيب بن المهلب فهجا السيد سوارا في قصيدة رثى بها عبادا ودفعها إلى نوائح الأزد لما بينهم وبين تميم من العداوة ولقربهم من دار سوار ينحن بها وأولها\n(يا من غدا حاملا جثمان سوار ... من داره ظاعنا منها إلى النار)\n(لا قدس الله روحا كان هيكلها ... فقد مضت بعظيم الخزي والعار)\n(حتى هوت قعر برهوت معذبة ... وجسمه في كنيف بين أقذار)\n(لقد رأيت من الرحمن معجبة ... فيه وأحكامه تجري بمقدار)\n(فاذهب عليك من الرحمن بهلته ... يا شر حي براه الخالق الباري)\nخبرني أحمد بن عبد العزيز الجوهري قال حدثني علي بن محمد البقال قال حدثنا شيبان بن محمد الحراني وكان يلقب بعوضة وصار من سادات الأزد قال\nكان السيد جاري وكان أدلم وكان ينادم فتيانا من فتيان الحي فيهم فتى مثله أدلم غليظ الأنف والشفتين مزنج الخلقة وكان السيد من أنتن الناس إبطين وكانا يتمازحان فيقول له السيد أنت زنجي الأنف والشفتين ويقول الفتى للسيد أنت زنجي اللون والإبطين فقال السيد\n(أعارك يوم بعناه رباح ... مشافره وأنفك ذا القبيحا)\n(وكانت حصتي إبطي منه ... ولونا حالكا أمسى فضوحا)\n(فهل لك في مبادلتيك إبطي ... بأنفك تحمد البيع الربيحا)\n(فإنك أقبح الفتيان أنفا ... وإبطي أنتن الآباط ريحا)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":42,"spl":"العسس يحبس السيد الحميري","loc":1367},
{"id":"b74-52","bab":"الجزء 7","sec":"بعض من هجائه ومدحه وغزله","page":"ج7 ص289","text":"أخبرني أحمد قال حدثني شيبان قال مات منا رجل موسر وخلف ابنا له فورث ماله وأتلفه بالإسراف وأقبل على الفساد واللهو وقد تزوج امرأة تسمى ليلى واجتمع على السيد وكان من أظرف الناس وكان الفتى لا يصبر عنه وأنفق عليه مالا كثيرا وكانت ليلى تعذله على إسرافه وتقول له كأني بك قد افتقرت فلم يغن عنك شيئا فهجاها السيد وكان مما قال فيها\n(أقول يا ليت ليلى في يدي حنق ... من العداوة من أعدى أعاديها)\n(يعلو بها فوق رعن ثم يحدرها ... في هوة فتدهدى يومها فيها)\n(أوليتها في غمار البحر قد عصفت ... فيه الرياح فهاجت من أواذيها)\n(أوليتها قرنت يوما إلى فرسي ... قد شد منها إلى هاديه هاديها)\n(حتى يرى لحمها من حضره زيما ... وقد أتى القوم بعد الموت ناعيها)\n(فمن بكاها فلا جفت مدامعه ... لا أسخن الله إلا عين باكيها)\nخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني إسحاق بن محمد النخعي وعبد الحميد بن عقبة قالا حدثنا الحسن بن علي بن المغيرة الكسلان عن محمد بن كناسة قال أهدى بعض ولاة الكوفة إلى السيد رداء عدنيا فكتب إليه السيد فقال\n(وقد أتانا رداء من هديتكم ... فلا عدمتك طول الدهر من وال)\n(هو الجمال جزاك الله صالحة ... لو أنه كان موصولا بسربال)\nفبعث إليه بخلعة تامة وفرس جواد وقال يقطع عتاب أبي هاشم واستزادته إيانا حدثني عمي قال حدثنا الكراني عن بعض البصريين عن سليمان بن أرقم قال كنت مع السيد فمر بقاص على باب أبي سفيان بن العلاء وهو يقول يوزن رسول الله القيامة في كفة بأمته أجمع فيرجع بهم ثم يؤتى بفلان فيوزن بهم فيرجح ثم يؤتى بفلان فيوزن بهم فيرجح فأقبل على أبي سفيان فقال لعمري إن رسول اللهليرجح على أمته في الفضل والحديث حق وإنما رجح الآخران الناس في سيئاتهم لأن من سن سنة سيئة فعمل بها بعده كان عليه وزرها ووزر من عمل بها قال فما أجابه أحد فمضى فلم يبق أحد من القوم إلا سبه\nوقال أبو جعفر الأعرج حدثني إسماعيل بن الساحر قال خرجت من منزل نصر بن مسعود أنا وكاتب عقبة بن سلم والسيد ونحن سكارى فلما كنا بزهران لقيتنا بنت الفجاءة بن عمرو بن قطري بن الفجاءة وكانت امرأة برزة حسناء فصيحة فواقفها السيد وتخاطب عليها وأنشدها من شعره بتجميش فأعجب كل واحد منهما صاحبه فقال السيد\n(من ناكثين وقاسطين الأروع ... )\n(حول الأمين وقال هات ليسمعوا ... )\n(قم يابن مذعور فأنشد نكسوا ... خضع الرقاب بأعين لا ترفع)\n(لولا حذار أبي بجير أظهروا ... شنآنهم وتفرقوا وتصدعوا)\n(لا تجزعوا فلقد صبرنا فاصبروا ... سبعين عاما والأنوف تجدع)\n(إذ لا يزال يقوم كل عروبة ... منكم بصاحبنا خطيب مصقع)\n(مسحنفر في غيه متتايع ... في الشتم مثله بخيل يسجع)\n(ليسر مخلوقا ويسخط خالقا ... إن الشقي بكل شر مولع)\nفلما سمعها أبو بجير دعا صاحب عسسه فشتمه وقال جنيت علي ما لا يد لي به اذهب صاغرا إلى الحبس وقل أيكم أبو هاشم فإذا أجابك فأخرجه واحمله على دابتك وامش معه صاغرا حتى تأتيني به ففعل فأبى السيد ولم يجبه إلى الخروج إلا بعد أن يطلق له كل من أخذ معه فرجع إلى أبي بجير فأخبره فقال الحمد لله الذي لم يقل أخرجهم وأعط كل واحد منهم مالا فما كنا نقدر على خلافه افعل ما أحب برغم أنفك الآن فمضى فخلى سبيله وسبيل كل من كان معه ممن أخذ في تلك الليلة وأتي به إلى أبي بجير فتناوله بلسانه وقال قدمت علينا فلم تأتنا وأتيت بعض أصحابك الفساق وشربت ما حرم عليك حتى جرى ما جرى فاعتذر من ذلك إليه فأمر له أبو بجير بجائزة سنية وحمله وأقام عنده مدة قال النوفلي وحدثني أبي أن جماعة من أهل الثغور قدموا على أبي بجير بتسبيب بهم فأطلقهم ثم جاؤوه فعاتبوه على التشيع وسألوه الرجوع فغضب من ذلك ودعا بمولاه يزيد بن مذعور فقال أنشدني ويلك لأبي هاشم فأنشده قوله\n(يا صاحبي لدمنتين عفاهما ... مر الرياح عليهما فمحاهما)\nحتى فرغ ثم قال هات النونية فأنشده\n(يا صاحبي تروحا وذراني ... ليس الخلي كمسعر الأحزان)\nفلما فرغ قال أنشدني الدماغة الرائية فأنشده إياها فلما فرغ أقبل عليه الثغريون فقالوا له ما أعتبتنا فيما عاتبناك عليه فقال يا حمير هل في الجواب أكثر مما سمعتم والله لولا أني لا أعلم كيف يقع فعلي من أمير المؤمنين لضربت أعناقكم قوموا إلى غير حفظ الله فقاموا وبلغ السيد الخبر فقال","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":43,"spl":"بعض من هجائه ومدحه وغزله","loc":1368,"partial":1},
{"id":"b74-53","bab":"الجزء 7","sec":"بعض من هجائه ومدحه وغزله","page":"ج7 ص289","text":"(إذا قال الأمير أبو بجير ... أخو أسد لمنشده يزيدا)\n(طربت إلى الكرام فهات فيهم ... مديحا من مديحك أو نشيدا)\n(رأيت لمن بحضرته وجوها ... من الشكاك والمرجين سودا)\n(كأن يزيد ينشد بامتداح ... أبا حسن نصارى أو يهودا)\nروى أبو داود المسترق أن السيد والعبدي اجتمعا فأنشد السيد\n(إني أدين بما دان الوصي به ... يوم الخريبة من قتل المحلينا)\n(وبالذي دان يوم النهروان به ... وشاركت كفه كفي بصفينا)\nفقال له العبدي أخطأت لو شاركت كفك كفه كنت مثله ولكن قل تابعت كفي كفه لتكون تابعا لا شريكا فكان السيد بعد ذلك يقول أنا أشعر الناس إلا العبدي","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":44,"spl":"بعض من هجائه ومدحه وغزله — أبو بجير يهين السيد الحميري","loc":1369},
{"id":"b74-54","bab":"الجزء 7","sec":"أبو بجير يهين السيد الحميري","page":"ج7 ص293","text":"وقال إسحاق النخعي عن عبد الحميد بن عقبة عن أبي جعفر الأعرج عن إسماعيل بن الساحر قال كنت مع السيد وقد اكترينا سفينة إلى الأهواز فجلس فيها معنا قوم شراة فجعلوا ينالون من عثمان فأخرج السيد رأسه إليهم وقال\n(شفيت من نعثل في نحت أثلته ... فاعمد هديت إلى نحت الغويين)\n(اعمد هديت إلى نحت اللذين هما ... كانا عن الشر لو شاءا غنيين)\nال إسماعيل فلما قدمنا الأهواز قدم السيد وقد سكر فأتي به أبا بجير ابن سماك الأسدي وكان ابن النجاشي عند ابن سماك بعد العشاء الآخرة وكان يعرفه باسمه ولم يعرفه فقال له يا شيخ السوء تخرج سكران في هذا\nالوقت لأحسنن أدبك فقال له والله لا فعلت ولتكرمني ولتخلعن علي وتحملني وتجيزني قال أو تهزأ أيضا قال لا والله ثم اندفع ينشده فقال\n(من كان معتذرا من شتمه عمرا ... فابن النجاشي منه غير معتذر)\n(وابن النجاشي براء غير محتشم ... في دينه من أبي بكر ومن عمر)\nثم أنشده قوله\n(إحداهما نمت عليه حديثه ... وبغت عليه نفسه إحداهما)\n(فهما اللتان سمعت رب محمد ... في الذكر قص على العباد نباهما)\nفقال أبو هاشم فقال نعم قال ارتفع فحمله وأجازه وقال والله لأصدقن قولك في جميع ما حلفت عليه قال إسماعيل رأى أبو بجير السيد متغير اللون فسأله عن حاله فقال فقدت الشراب الذي ألفته لكراهة الأمير إياه قال فاشربه فإننا نحتمله لك قال ليس عندي قال لكاتبه اكتب له بمائتي دورق ميبختج فقال له السيد ليس هذا من البلاغة قال وما هي قال البلاغة أن تأتي من الكلام بما يحتاج إليه وتدع ما يستغنى عنه قال وكيف\nذلك قال اكتب بمائتي دورق مي ولا تكتب بختج فإنك تستغني عنه فضحك ثم أمر فكتب له بذلك قال والمي النبيذ قال إسماعيل وبلغ السيد وهو بالأهواز أن أبا بجير قد أشرف على الموت فأظهرت المرجئة الشماتة به فخرج السيد متحرقا حتى اكترى سفينة وخرج إليها وأنشأ يقول\n(تباشر أهل تدمر إذا أتاهم ... بأمر أميرنا لهم بشير)\n(ولا لأميرنا ذنب إليهم ... صغير في الحياة ولا كبير)\n(سوى حب النبي وأقربيه ... ومولاهم بحبهم جدير)\n(وقالوا لي لكيما يحزنوني ... ولكن قولهم إفك وزور)\n(لقد أمسى أخوك أبو بجير ... بمنزلة يزار ولا يزور)\n(وظلت شيعة الهادي علي ... كأن الأرض تحتهم تمور)\n(فبت كأنني مما رموني ... به في قد ذي حلق أسير)\n(كأن مدامعي وجفون عيني ... توخز بالقتاد فهن عور)\n(أقول علي للرحمن نذر ... صحيح حيث تحتبس النذور)\n(بمكة إن لقيت أبا بجير ... صحيحا واللواء له يسير)\nوهي قصيدة طويلة وروى محمد بن عاصم عن أبي داود المسترق عن السيد أنه رأى النبي النوم فاستنشده فأنشده قوله\n(لأم عمرو باللوى مربع ... طامسة أعلامه بلقع)\nحتى انتهى إلى قوله\n(قالوا له لو شئت أعلمتنا ... إلى من الغاية والمفزع)\nفقال حسبك ثم نفض يده وقال قد والله أعلمتهم","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":44,"spl":"بعض من هجائه ومدحه وغزله — أبو بجير يهين السيد الحميري","loc":1370},
{"id":"b74-55","bab":"الجزء 7","sec":"مرضه ووفاته","page":"ج7 ص296","text":"وروى أبو داود وإسماعيل بن الساحر أنهما حضرا السيد عند وفاته بواسط وقد أصابه شرى وكرب فجلس ثم قال اللهم أهكذا جزائي في حب آل محمد قال فكأنها كانت نارا فطفئت عنه وأخبرني محمد بن العباس اليزيدي بإسناد له لم يحضرني وأنا أخرجه إن شاء الله تعالى قال حدثني من حضر السيد وقد احتضر فقال\n(برئت إلى الإله من ابن أروى ... ومن دين الخوارج أجمعينا)\n(ومن فعل برئت ومن فعيل ... غداة دعي أمير المؤمنينا)\nثم كأن نفسه كانت حصاة فسقطت أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة عن أبي الهذيل العلاف عن أبي جعفر المنصور قال بلغني أن السيد مات بواسط فلم يدفنوه والله لئن تحقق عندي لأحرقنها ووجدت في بعض الكتب حدثني محمد بن يحيى اللؤلئي قال حدثني محمد بن عباد بن صهيب عن أبيه قال\nكنت عند جعفر بن محمد فأتاه نعي السيد فدعا له وترحم عليه فقال رجل يا بن رسول الله تدعو له وهو يشرب الخمر ويؤمن بالرجعة فقال حدثني أبي عن جدي أن محبي آل محمد لا يموتون إلا تائبين وقد تاب ورفع مصلى كانت تحته فأخرج كتابا من السيد يعرفه فيه أنه قد تاب ويسأله الدعاء له وذكر محمد بن إدريس العتبي أن معاذ بن يزيد الحميري حدثه أن السيد عاش إلى خلافة هارون الرشيد وفي أيامه مات وأنه مدحه بقصيدتين فأمر له ببدرتين ففرقهما فبلغ ذلك الرشيد فقال أحسب أبا هاشم تورع عن قبول جوائزنا أخبرني ابن عمار قال حدثنا يعقوب بن نعيم قال حدثنا إبراهيم بن عبد الله الطلحي قال حدثني إسحاق بن محمد بن بشير بن عمار الصيرفي عن جده بشير بن عمار قال حضرت وفاة السيد في الرميلة ببغداد فوجه رسولا إلى صف الجزارين الكوفيين يعلمهم بحاله ووفاته فغلط الرسول فذهب إلى صف السموسين فشتموه ولعنوه فعلم أنه قد غلط فعاد إلى الكوفيين يعلمهم بحاله ووفاته فوافاه سبعون كفنا قال وحضرناه جميعا وإنه ليتحسر تحسرا شديدا وإن وجهه لأسود كالقار وما يتكلم إلى أن أفاق إفاقة وفتح عينيه فنظر إلى ناحية القبلة ثم قال يا أمير المؤمنين أتفعل هذا بوليك قالها ثلاث مرات مرة بعد أخرى قال فتجلى والله في جبينه عرق بياض فما زال يتسع ويلبس وجهه حتى صار كله كالبدر وتوفي فأخذنا في جهازه ودفناه في الجنينة ببغداد وذلك في خلافة الرشيد","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":45,"spl":"مرضه ووفاته — من المائة المختارة","loc":1371},
{"id":"b74-56","bab":"الجزء 7","sec":"من المائة المختارة","page":"ج7 ص298","text":"(فلا زلن حسرى ظلعا لم حملنها ... إلى بلد ناء قليل الأصادق)\n(ولا ذنب لي إذ قلت إذ نحن جيرة ... أثيبي بود قبل إحدى البوائق)\nعروضه من الطويل قوله فلا زلن حسرى دعاء على الإبل التي ظعنت بها وأبعدتها عنه وحسرى قد حسرن أي بلغ منهن الجهد فلم يبق فيهم بقية يقال حسر ناقته فهو يحسرها وهي حسرى والذكر حسير قال الله عز و جل ( ينقلب إليك البصر خاسئا وهو حسير\nوفي الحديث فإن أتعبتها حسرتها والظلع في كل شيء أن تألم رجله فلا يقدر أن يمشي عليها فيغمز في مشيه كالأعرج إذا مشى ويقال ظلع فهو ظالع والنائي البعيد والنية الناحية التي تنوي إليها والنوى البعد والتنائي التباعد والبوائق الحوادث التي تأتي بما يحذر بغتة وهي مثل المصائب والنوائب البيت الأول من الشعر لكثير ويقال إنه لأبي جندب الهذلي والبيت\nالثاني لرجل من كنانة ثم من بني جذيمة وزعم ابن دأب أنه عبد الله بن علقمة أحد بني عامر بن عبد مناة بن كنانة وقيل أيضا إنه يقال له عمرو الذي قتله خالد بن الوليد في بعض مغازيه التي وجهه رسول الله الغناء في اللحن المختار لمتيم مولاة علي بن هشام وأم أولاده ولحنها رمل بالبنصر من رواية إسحاق وعمرو وهو من الأرمال النادرة المختارة وفيه خفيف ثقيل يقال إنه لحسين بن محرز ويقال إنه قديم من غناء أهل مكة","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":45,"spl":"مرضه ووفاته — من المائة المختارة","loc":1372},
{"id":"b74-57","bab":"الجزء 7","sec":"عبد الله بن علقمة وحبيشة","page":"ج7 ص299","text":"أخبرني الحسن بن علي قال حدثنا محمد بن زكريا الغلابي قال حدثنا العباس بن بكار قال حدثنا ابن دأب قال كان من حديث عبد الله بن علقمة أحد بني عامر بن عبد مناة بن كنانة أنه خرج مع أمه وهو مع ذلك غلام يفعة دون المحتلم لتزور جارة لها وكان لها بنت يقال لها حبيشة بنت حبيش أحد بني عامر بن عبد مناة بن كنانة فلما رآها عبد الله بن علقمة أعجبته ووقعت في نفسه وانصرف وترك أمه عند جارتها فلبثت عندها يومين ثم أتاها عبد الله بن علقمة ليرجعها إلى منزلها فوجد حبيشة قد زينت لأمر كان في الحي فازداد بها عجبا وانصرف بأمه في غداة تمطر فمشى معها شيئا ثم أنشأ يقول\n(وما أدري بلى إني لأدري ... أصوب القطر أحسن أم حبيش)\n(حبيشة والذي خلق الهدايا ... وما عن بعدها للصب عيش)\nفسمعت ذلك أمه فتغافلت عنه وكرهت قوله ثم مشيا مليا فإذا هو بظبي على ربوة من الأرض فقال\n(يا أمتا أخبريني غير كاذبة ... وما يريد مسول الحق بالكذب)\n(أتلك أحسن أم ظبي برابية ... لا بل حبيشة في عيني وفي أربي)\nفزجرته أمه وقالت له ما أنت وهذا نزوجك بنت عمك فهي أجمل من تلك وأتت امرأة عمه فأخبرتها خبره وقالت زيني ابنتك له ففعلت وأدخلتها عليه فلما رآها أطرق فقالت له أمه أيهما الآن أحسن فقال\n(إذا غيبت عني حبيشة مرة ... من الدهر لم أملك عزاء ولا صبرا)\n(كأن الحشى حر السعير يحشه ... وقود الغضى والقلب مستعرا)\nوجعل يراسل الجاريه وتراسله حتى علقته كما علقها وكثر قوله للشعر فيها فمن ذلك قال\n(حبيشة هل جدي وجدك جامع ... بشملكم شملي وأهلكم أهلي)\n(وهل أنا ملتف بثوبك مرة ... بصحراء بين الأليتين إلى النخل)\n(وهل أشتفي من ريق ثغرك مرة ... كراح ومسك خالطا ضرب النحل)\nفلما بلغ أهلها خبرهما حجبوها عنه مدة وهو يزيد غراما بها ويكثر قول الشعر فيها فأتوها فقالوا لها عديه السرحة فإذا أتاك فقولي له نشدتك الله إن كنت أحببتني فوالله ما على الأرض شيء أبغض إلي منك ونحن قريب نستمع ما تقولين فوعدته وجلسوا قريبا يستمعون وجلست عند السرحة وأقبل عبد الله لوعدها فلما دنا منها دمعت عينها والتفتت إلى حيث أهلها جلوس فعرف أنهم قريب فرجع وبلغه ما قالوا لها أن تقوله فأنشأ يقول\n(لو قلت ما قالوا لزدت جوى بكم ... على أنه لم يبق ستر ولا صبر)\n(ولم يك حبي عن نوال بذلته ... فيسليني عنه التجهم والهجر)\n(وما أنس م الأشياء لا أنس دمعها ... ونظرتها حتى يغيبني القبر)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":46,"spl":"عبد الله بن علقمة وحبيشة","loc":1373},
{"id":"b74-58","bab":"الجزء 7","sec":"سرية خالد بن الوليد إلى بني عامر","page":"ج7 ص301","text":"وبعث النبي أثر ذلك خالد بن الوليد إلى بني عامر بن عبد مناة ابن كنانة وأمره أن يدعوهم إلى الإسلام فإن أجابوه وإلا قاتلهم فصبحهم خالد بن الوليد بالغميصاء وقد سمعوا به فخافوه فظعنوا وكانوا قتلوا أخاه الفاكه بن الوليد وعمه الفاكه بن المغيرة في الجاهلية وكانوا من أشد حي في كنانة بأسا يسمون لعقة الدم فلما صبحهم خالد ومعه بنو\nسليم وكانت بنو سليم طلبتهم بمالك بن خالد بن صخر بن الشريد وإخوته كرز وعمرو والحارث وكانوا قتلوهم في موطن واحد فلما صبحهم خالد في ذلك اليوم ورأوا معه بني سليم زادهم ذلك نفورا فقال لهم خالد أسلموا تسلموا قالوا نحن قوم مسلمون قال فألقوا سلاحكم وانزلوا قالوا لا والله فقال جذيمة بن الحارث أحد بني أقرم يا قوم لا تضعوا سلاحكم والله ما بعد وضع السلاح إلا القتل قالوا لا والله لا نلقي سلاحنا ولا ننزل ما نحن منك ولا لمن معك بآمنين قال خالد فلا أمان لكم إن لم تنزلوا فنزلت فرقة منهم فأسرهم وتفرق بقية القوم فرقتين فأصعدت فرقة وسفلت فرقة أخرى قال ابن دأب فأخبرني من لا أتهم عن عبد الله بن أبي حدرد الأسلمي قال كنت يومئذ في جند خالد فبعثنا في أثر ظعن مصعدة يسوق بهن فتية فقال أدركوا أولئك قال فخرجنا في أثرهم حتى أدركناهم وقد مضوا ووقف لنا غلام شاب على الطريق فلما انتهينا إليه جعل يقاتلنا وهو يقول\n(بين أطراف الذيول واربعن ... مشي حييات كأن لم يفزعن)\n(إن يمنع اليوم نساء تمنعن ... )\nفقاتلنا طويلا فقتلناه ومضينا حتى لحقنا الظعن فخرج إلينا غلام كأنه الأول فجعل يقاتلنا ويقول\n(أقسم ما إن خادر ذو لبده ... يزأر بين أيكة ووهده)\n(يفرس شبان الرجال وحده ... بأصدق الغداة مني نجده)\nفقاتلنا حتى قتلناه وأدركنا الظعن فأخذناهن فإذا فيهن غلام وضيء به صفرة في لونه كالمنهوك فربطناه بحبل وقدمناه لنقتله فقال لنا هل لكم في خير قلنا وما هو قال تدركون بي الظعن أسفل الوادي ثم تقتلونني قلنا نفعل فخرجنا حتى نعارض الظعن أسفل الوادي فلما كان بحيث يسمعن الصوت نادى بأعلى صوته اسلمي حبيش عند نفاد العيش فأقبلت إليه جارية بيضاء حسناء فقالت وأنت فاسلم على كثرة الأعداء وشدة البلاء فقال سلام عليكم دهرا وإن بقيت عصرا قالت وأنت سلام عليك عشرا وشفعا تترى وثلاثا وترا فقال\n(إن يقتلوني يا حبيش فلم يدع ... هواك لهم مني سوى غلة الصدر)\n(وأنت التي أخليت لحمي من دمي ... وعظمي وأسبلت الدموع على نحري)\nفقالت له\n(ونحن بكينا من فراقك مرة ... وأخرى وآسيناك في العسر واليسر)\n(وأنت فلا تبعد فنعم فتى الهوى ... جميل العفاف في المودة والستر)\nفقال لها\n(أريتك إن طالبتكم فوجدتم ... بحلية أو أدركتكم بالخوانق)\n(ألم يك حقا أن ينول عاشق ... تكلف إدلاج السرى والودائق)\nفقالت بلى والله فقال\n(فلا ذنب لي إذ قلت إذ نحن جيرة ... أثيبي بود قبل إحدى البوائق)\n(أثيبي بود قبل أن تشحط النوى ... وينأى خليط بالحبيب المفارق)\nال ابن أبي حدرد فضربنا عنقه فتقحمت الجارية من خدرها حتى أتت نحوه فالتقمت فاه فنزعنا منها رأسه وإنها لتكسع بنفسها حتى ماتت مكانها وأفلت من القوم غلام من بني أقرم يقال له السميدع حتى اقتحم على رسول الله بما صنع خالد وشكاه","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":47,"spl":"سرية خالد بن الوليد إلى بني عامر","loc":1374,"partial":1},
{"id":"b74-59","bab":"الجزء 7","sec":"علي يدي أهل قتلى خالد","page":"ج7 ص304","text":"قال ابن دأب فأخبرني صالح بن كيسان أن رسول الله هل أنكر عليه أحد ما صنع فقال نعم رجل أصفر ربعة ورجل أحمر طويل فقال عمر أنا والله يا رسول الله أعرفهما أما الأول فهو ابني وصفته وأما الثاني فهو سالم مولى أبي حذيفة وكان خالد قد أمر كل من أسر أسيرا أن يضرب عنقه فأطلق عبد الله بن عمر وسالم مولى أبي حذيفة أسيرين كانا معهما فبعث رسول الله رضي الله عنه بعد فراغه من حنين وبعث معه بإبل وورق وأمره أن يديهم فوداهم ثم رجع إلى رسول الله فسأله فقال علي قدمت عليهم فقلت لهم هل لكم أن تقبلوا هذا الجمل بما أصيب منكم من القتلى والجرحى وتحللوا رسول الله نعم فقلت لهم فهل لكم أن تقبلوا الثاني بما دخلكم من الروع والفزع قالوا نعم فقلت لهم فهل لكم أن تقبلوا الثالث وتحللوا رسول الله مما علم ومما لم يعلم قالوا نعم قال فدفعته إليهم وجعلت أديهم حتى إني لأدي ميلغة الكلب وفضلت فضلة فدفعتها إليهم فقال رسول الله\nأفقبلوها قال نعم قال فوالذي أنا عبده لهي أحب إلي من حمر النعم وقالت سلمى بنت عميس\n(وكم غادروا يوم الغميصاء من فتى ... أصيب فلم يجرح وقد كان جارحا)\n(ومن سيد كهل عليه مهابة ... أصيب ولما يعله الشيب واضحا)\n(أحاطت بخطاب الأيامى وطلقت ... غداتئذ من كان منهن ناكحا)\n(ولولا مقال القوم للقوم أسلموا ... للاقت سليم يوم ذلك ناطحا)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":48,"spl":"علي يدي أهل قتلى خالد — قريش وبنو عامر","loc":1375},
{"id":"b74-60","bab":"الجزء 7","sec":"قريش وبنو عامر","page":"ج7 ص305","text":"قال ابن دأب وأما سبب قتلهم القرشيين فإنه كان نفر من قريش بضعة عشر أقبلوا من اليمن حتى نزلوا على ماء من مياه بني عامر بن عبد مناة ابن كنانة وكان يقال لهم لعقة الدم وكانوا ذوي بأس شديد فجاءت إليهم بنو عامر فقالوا للقرشيين إياكم أن يكون معكم رجل من فهم لأنه كان له عندهم ذحل قالوا لا والله ما هو معنا وهو معهم فلما راحوا أدركهم العامريون ففتشوهم فوجدوا الفهمي معهم في رحالهم فقتلوه وقتلوهم وأخذوا أموالهم فقال راجزهم\n(إن قريشا غدرت وعاده ... نحن قتلنا منهم بغاده)\n(عشرين كهلا ما لهم زياده ... )\nوكان فيمن قتل يومئذ عفان بن أبي العاصي أبو عثمان بن عفان وعوف ابن عوف أبو عبد الرحمن بن عوف والفاكه بن المغيرة والفاكه بن الوليد بن\nالمغيرة فأرادت قريش قتالهم حتى خذلتهم بنو الحارث بن عبد مناة فلم يفعلوا شيئا وكان خالد بن عبيد الله أحد بني الحارث بن عبد مناة فيمن حضر الوقعة هو وضرار فأشار إلى ذلك ضرار بن الخطاب بقوله\n(دعوت إلى خطة خالدا ... من المجد ضيعها خالد)\n(فوالله أدري أضاهي بها ... بني العم أم صدره بارد)\n(ولو خالد عاد في مثلها ... لتابعه عنق وارد)\nوقال ضرار أيضا\n(أرى ابني لؤي أسرعا أن تسالما ... وقد سلكت أبناؤها كل مسلك)\n(فإن أنتم لم تثأروا برجالكم ... فدوكوا الذي أنتم عليه بمدوك)\n(فإن أداة الحرب ما قد جمعتم ... ومن يتق الأقوام بالشر يترك)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":48,"spl":"علي يدي أهل قتلى خالد — قريش وبنو عامر","loc":1376,"partial":1},
{"id":"b74-61","bab":"الجزء 7","sec":"سرايا النبي ص إلى قبائل كنانة","page":"ج7 ص306","text":"فلما كان يوم فتح مكة بعث رسول الله بالجيوش إلى قبائل بني كنانة حوله فبعث إلى بني ضمرة نميلة بن عبد الله الليثي وإلى بني الدئل عمرو ابن أمية الضمري وبعث إلى بني مدلج عياش بن أبي ربيعة المخزومي\nوبعث إلى بني بغيض ومحارب بن فهر عبد الله بن نهيك أحد بني مالك بن حسل وبعث إلى بني عامر بن عبد مناة خالدا فوافاهم خالد بماء يقال له الغميصاء وقد كان خبره سقط إليهم فمضى منهم سلف قتله بقوم منهم يقال لهم بنو قيس بن عامر وبنو قعين بن عامر وهم خير القوم وأشرفهم فأصيب من أصيب فلما أقبل خالد ودخل المدينة قال له النبي خالد ما دعاك إلى هذا قال يا رسول الله آيات سمعتهن أنزلت عليك قال وما هي قال قول الله عز ذكره ( قاتلوهم يعذبهم الله بأيديكم ويخزهم وينصركم عليهم ويشف صدور قوم مؤمنين ويذهب غيظ قلوبهم\nوجاءني ابن أصرم فقال لي إن رسول الله أن تقاتل فحينئذ بعث رسول الله أخبرنا محمد بن خلف وكيع قال حدثنا سعيد بن أبي نصر قال حدثنا سفيان بن عيينة عن عبد الملك بن نوفل بن مساحق عن رجل من مزينة يقال له ابن عاصم عن أبيه قال بعثنا رسول الله سرية وأمرنا ألا نقتل أحدا إن رأينا مسجدا أو سمعنا أذانا قال وكيع وأخبرني أحمد بن أبي خيثمة قال حدثنا إبراهيم بن بشار الرمادي قال حدثنا سفيان بن عيينة عن عبد الملك بن نوفل عن ابن عاصم هذا عن أبيه بهذا الحديث قال فبينا نحن نسير إذا بفتى يسوق ظعائن فعرضنا عليه الإسلام فإذا هو لا يعرفه فقال ما أنتم صانعون بي إن لم أسلم قلنا نحن قاتلوك قال فدعوني ألحق هذه الظعائن فتركناه فأتى هودجا منها وأدخل رأسه فيه وقال اسلمي حبيش قبل نفاد العيش فقالت وأنت فاسلم تسعا وترا وثمانيا تترى وعشرا أخرى\nفقال لها\n(فلا ذنب لي قد قلت إذ نحن جيرة ... أثيبي بود قبل إحدى البوائق)\n(أثيبي بود قبل أن تشحط النوى ... وينأى أمير بالحبيب المفارق)\nقال ثم جاء فضربنا عنقه فخرجت من ذلك الهودج جارية جميلة فجنأت عليه فما زالت تبكي حتى ماتت","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":49,"spl":"سرايا النبي ص إلى قبائل كنانة","loc":1377},
{"id":"b74-62","bab":"الجزء 7","sec":"غزوة خالد لبني جذيمة","page":"ج7 ص308","text":"أخبرني أحمد بن عبد العزيز الجوهري وعمرو بن عبد الله العتكي قالا حدثنا عمر بن شبة قال يروى أن خالد بن الوليد كان جالسا عند النبي عن غزوته بني جذيمة فقال إن أذن رسول الله فقال تحدث فقال لقيناهم بالغميصاء عند وجه الصبح فقاتلناهم حتى كاد قرن الشمس يغيب فمنحنا الله أكتافهم فتبعناهم نطلبهم فإذا بغلام له ذوائب على فرس ذنوب في أخريات القوم فبوأت له الرمح فوضعته بين كتفيه فقال لا إله فقبضت عنه الرمح فقال إلا اللات أحسنت أو أساءت فهمسته همسة أذريته وقيذا ثم أخذته أسيرا فشددته وثاقا ثم كلمته فلم يكلمني واستخبرته فلم يخبرني فلما كان ببعض الطريق رأى نسوة من بني جذيمة يسوق بهن المسلمون فقال أيا خالد قلت ما تشاء قال هل أنت واقفي\nعلى هؤلاء النسوة فأتيت على أصحابي ففعلت وفيهن جارية تدعى حبيشة فقال لها ناوليني يدك فناولته يدها في ثوبها فقال اسلمي حبيش قبل نفاد العيش فقالت حييت عشرا وتسعا وترا وثمانيا تترى فقال\n(أريتك إن طالبتكم فوجدتكم ... بحلية أو أدركتكم بالخوانق)\n(ألم يك حقا أن ينول عاشق ... تكلف إدلاج السرى والودائق)\n(وقد قلت إذ أهلي لأهلك جيرة ... أثيبي بود قبل إحدى الصعائق)\n(أثيبي بود قبل أن تشحط النوى ... وينأى أمير بالحبيب المفارق)\n(فإني لا ضيعت سر أمانتي ... ولا راق عيني بعد عينك رائق)\nسوى أن ما نال العشيرة شاغل ... عن الود إلا أن يكون التوامق\nفلما جاء على حاله تلك قدمته فضربت عنقه فأقبلت الجارية ووضعت رأسه في حجرها وجعلت ترشفه وتقول\n(لا تبعدن يا عمرو حيا وهالكا ... فحق بحسن المدح مثلك من مثلي)\n(لا تبعدن يا عمرو حيا وهالكا ... فقد عشت محمود الثنا ماجد الفعل)\n(فمن لطراد الخيل تشجر بالقنا ... وللفخر يوما عند قرقرة البزل)\nوجعلت تبكي وتردد هذه الأبيات حتى ماتت وإن رأسه لفي حجرها فقال رسول الله رفعت لي يا خالد وإن سبعين ملكا لمطيفون بك يحضونك على قتل عمرو حتى قتلته أخبرني محمد بن العباس اليزيدي قال حدثنا أحمد بن يحيى ثعلب قال\nحدثنا الزبير بن بكار قال حدثني عبد الله بن المنذر عن صفية بنت الزبير بن هشام قالت كان أبو السائب المخزومي رجلا صالحا زاهدا متقللا يصوم الدهر وكان أرق خلق الله وأشدهم غزلا فوجه ابنه يوما يأتيه بما يفطر عليه فأبطأ الغلام إلى العتمة فلما جاء قال له يا عدو نفسه ما أخرك إلى هذا الوقت قال جزت بباب بني فلان فسمعت منه غناء فوقفت حتى أخذته فقال هات يا بني فوالله لئن كنت أحسنت لأحبونك ولئن كنت أسأت لأضربنك فاندفع يغني بشعر كثير\n(ولما علوا شغبا تبينت أنه ... تقطع من أهل الحجاز علائقي)\n(فلا زلن حسرى ظلعا لم حملنها ... إلى بلد ناء قليل الأصادق)\nفلم يزل يغنيه إلى نصف الليل فقالت له زوجته يا هذا قد انتصف الليل وما أفطرنا قال لها أنت طالق إن كان فطورنا غيره فلم يزل يغنيه إلى السحر فلما كان السحر قالت له زوجته هذا السحر وما أفطرنا فقال أنت طالق إن كان سحورنا غيره فلما أصبح قال لابنه خذ جبتي هذه وأعطني خلقك ليكون الحباء فضل ما بينهما فقال له يا أبت أنت شيخ وأنا شاب وأنا أقوى على البرد منك قال يا بني ما ترك صوتك هذا للبرد علي سبيلا ما حييت أخبرني وكيع قال أنشدنا أحمد بن يزيد الشيباني عن مصعب الزبيري لسليمان بن أبي دباكل قال\n(فهلا نظرت الصبح يا بعل زينب ... فتقضى لبانات الحبيب المفارق)\n(يروح إذا يمسي حنينا ويغتدي ... وتهجيره عند احتدام الودائق)\n(فطر جاهدا أو كن حليفا لصخرة ... ممنعة في رأس أرعن شاهق)\n(فما زال هذا الدهر من شؤم صرفه ... يفرق بين العاشقين الأوامق)\n(فيبعدنا ممن نريد اقترابه ... ويدني إلينا من نحب نفارق)\n(ولما علوا شغبا تبينت أنه ... تقطع من أهل الحجاز علائقي)\n(فلا زلن حسرى ظلعا لم حملنها ... إلى بلد ناء قليل الأصادق)","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":50,"spl":"غزوة خالد لبني جذيمة","loc":1378},
{"id":"b74-63","bab":"الجزء 7","sec":"ذكر متيم الهشامية وبعض أخبارها","page":"ج7 ص312","text":"كانت متيم صفراء مولدة من مولدات البصرة وبها نشأت وتأدبت وغنت وأخذت عن إسحاق وعن أبيه من قبله وعن طبقتهما من المغنين وكانت من تخريج بذل وتعليمها وعلى ما أخذت عنها كانت تعتمد فاشتراها علي بن هشام بعد ذلك فازدادت أخذا ممن كان يغشاه من أكابر المغنين وكانت من أحسن الناس وجها وغناء وأدبا وكانت تقول الشعر ليس مما يستجاد ولكنه يستحسن من مثلها وحظيت عند علي بن هشام حظوة شديدة وتقدمت على جواريه جمع عنده وهي أم ولده كلهم وقال عبد الله بن المعتز فيما أخبرني عنه محمد بن إبراهيم قريش قال أخبرني الحسن بن أحمد المعروف بأبي عبد الله الهشامي قال كانت متيم للبانة بنت عبد الله بن إسماعيل المراكبي مولى عريب فاشتراها علي بن هشام منها بعشرين ألف درهم وهي إذ ذاك جويرية فولدت له صفية وتكنى أم العباس ثم ولدت محمدا ويعرف بأبي عبد الله ثم ولدت بعده ابنا يقال له هارون ويعرف بأبي جعفر سماه المأمون وكناه لما ولد بهذا\nالإسم والكنية قال ولما توفي علي بن هشام عتقت وكان المأمون يبعث إليها فتجيئه فتغنيه فلما خرج المعتصم إلى سر من رأى أرسل إليها فأشخصها وأنزلها داخل الجوسق في دار كانت تسمى الدمشقي وأقطعها غيرها وكانت تستأذن المعتصم في الدخول إلى بغداد إلى ولدها فتزورهم وترجع ثم ضمها لما خرجت قلم وقلم جارية كانت لعلي بن هشام وكانت متيم صفراء حلوة الوجه فذكر محمد بن الحسن الكاتب أن الحسين بن يحيى بن أكثم حدثه عن الحسن بن إبراهيم بن رياح قال سألت عبد الله بن العباس الربيعي من أحسن من أدركت صنعة قال إسحاق قلت ثم من قال علويه قلت ثم من قال متيم قلت ثم من قال ثم أنا فعجبت من تقديمه متيم على نفسه فقال الحق أحق أن يتبع أخبرني محمد بن الحسن قال حدثنا عمر بن شبة قال سئل عبد الله بن العباس الربيعي عن أحسن الناس غناء فذكر مثل هذه الحكاية وزاد فيها أن قال له ما أحسن أن أصنع كما صنعت متيم في قوله\n(فلا زلن حسرى ظلعا لم حملنها ... )\nولا كما صنع علويه في قول الصمة\n(فواحسرتي لم أقض منك لبانة ... ولم أتمتع بالجوار وبالقرب)\nقال فأين عمرو بن بانة قال عمرو لا يضع نفسه في الصنعة هذا الموضع ولكنه صنع لحنا في هذا الغناء","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":51,"spl":"ذكر متيم الهشامية وبعض أخبارها","loc":1379,"partialRef":{"sid":"b74-56","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b74-64","bab":"الجزء 7","sec":"نسبة صوت علويه","page":"ج7 ص314","text":"\n(فواحسرتي لم أقض منك لبانة ... ولم أتمتع بالجوار وبالقرب)\n(يقولون هذا آخر العهد منهم ... فقلت وهذا آخر العهد من قلبي)\n(ألا يا حمام الشعب شعب مراهق ... سقتك الغوادي من حمام ومن شعب)\nلشعر للصمة بن عبد الله القشيري والغناء فيه لعلويه ثقيل أول مطلق في مجرى الوسطى وفيه لمخارق خفيف رمل بالوسطى أوله ألا يا حمام الشعب ثم الثاني ثم الأول وذكر حبش أن فيه لإسحاق ثاني ثقيل بالبنصر وقال ابن المعتز أخبرني الهشامي قال كانت متيم ذات يوم جالسة بين يدي المعتصم ببغداد وإبراهيم بن المهدي حاضر فغنت متيم في الثقيل الأول\n(لزينب طيف تعتريني طوارقه ... هدوا إذا ما النجم لاحت لواحقه)\nفأشار إليها إبراهيم أن تعيده فقالت متيم للمعتصم يا سيدي إبراهيم يستعيدني الصوت وكأنه يريد أن يأخذه فقال لها لا تعيديه فلما كان بعد أيام كان إبراهيم حاضرا مجلس المعتصم ومتيم غائبة فانصرف إبراهيم بعد حين إلى منزله ومتيم في منزلها بالميدان وطريقه عليها وهي في منظرة\nلها مشرفة على الطريق وهي تغني هذا الصوت وتطرحه على جواري علي بن هشام فتقدم إلى المنظرة وهو على دابته فتطاول حتى أخذ الصوت ثم ضرب باب المنظرة بمقرعته وقال قد أخذناه بلا حمدك وقال ابن المعتز وحدثت أن المأمون سأل علي بن هشام أن يهبها له وكان بغنائها معجبا فدفعه بذلك ولم يكن له منها ولد فلما ألح المأمون في طلبها حرص علي على أن تعلق منه حتى حبلت ويئس المأمون منها فيقال إن ذلك كان سببا لغضبه عليه حتى قتله وحدثني سليمان الطبال أنه رأى متيم في بعض مجالس المعتصم يمازحها ويجبذ بردائها وحكى علي بن محمد الهشامي قال أهدي إلى علي بن هشام برذون أشهب قرطاسي وكان في النهاية من الحسن والفراهة وكان علي به معجبا وكان إسحاق يشتهيه شهوة شديدة وعرض لعلي بطلبه مرارا فلم يرض أن يعطيه له فسار إسحاق إلى علي يوما بعقب صنعة متيم فلا زلن حسرى فاحتبسه علي وبعث إلى متيم أن تجعل صوتها هذا في صدر غنائها ففعلت فأطرب إسحاق إطرابا شديدا وجعل يسترده فترده وتستوفيه ليزيد في إطرابه إسحاق وهو يصغي إليها ويتفهمه حتى صح له ثم قال لعلي ما فعل البرذون الأشهب قال على ما عهدت من حسنه وفراهته قال فاختر الآن مني خلة من اثنتين إما أن طبت لي نفسا به وحملتني عليه وإما أن أبيت فأدعي والله هذا الصوت لي وقد أخذته أفتراك تقول إنه لمتيم وأقول إنه لي ويؤخذ قولك ويترك قولي قال لا والله ما\nأظن هذا ولا أراه يا غلام قد البرذون إلى منزل أبي محمد بسرجه ولجامه لا بارك الله له فيه قال علي بن محمد وحدثني أحمد بن حمدون أن إسحاق قال لمتيم لما سمع هذا الصوت منها أنت أنا فأنا من يريد أنها قد حلت محله وساوته قال علي بن محمد وقال جدي أبو جعفر كانت متيم تقول\n(فلا زلن حسرى ظلعا لم حملنها ... )\nالرمل كله وحدثني الهشامي قال مد علي بن هشام يده إلى بذل جاريته في عتاب يعاتبها ثم ندم على فعله ذلك ثم أنشأ يقول\n(فليت يدي بانت غداة مددتها ... إليك ولم ترجع بكف وساعد)\nوغنت متيم جاريته فيه في الثقيل الأول فكان يقال لبذل جارية علي بذل الصغيرة وحدثني الهشامي قال","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":52,"spl":"نسبة صوت علويه","song":2,"loc":1380,"partialRef":{"sid":"b74-56","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b74-65","bab":"الجزء 7","sec":"موت بذل","page":"ج7 ص316","text":"كان سبب موت بذل هذه أنها كانت ذات يوم جالسة عند المأمون فغنته وكان حاضرا في ذلك المجلس موسوس يكنى بأبي الكركدن من أهل طبرستان يضحك منه المأمون فعبثوا به فوثب عليهم وهرب الناس من بين يديه فلم يبق أحد حتى هرب المأمون وبقيت بذل جالسة والعود في حجرها\nفأخذ العود من يدها وضرب به رأسها فشجها في شابورتها اليمنى فانصرفت وحمت وكان سبب موتها وحدثني الهشامي قال لما مات علي بن هشام ومات المأمون أخذ المعتصم جواري علي بن هشام كلهن فأدخلهن القصر فتزوج ببذل المغنية وبقيت عنده إلى أن مات فخرجت بذل الكبيرة والباقون إلا بذل الصغيرة لأنها كانت حرمته فلم يخرجوها ويقال إنه لم يكن في المغنين أحسن صنعة من علويه وعبد الله بن العباس ومتيم وفي أولادها يقول علي بن الجهم\n(بني متيم هل تدرون ما الخبر ... وكيف يستر أمر ليس يستتر)\n(حاجيتكم من أبوكم يا بني عصب ... شتى ولكنما للعاهر الحجر)\nقال وحدثني جدي قال كلم علي بن هشام متيم فأجابته جوابا لم يرضه فدفع يده في صدرها فغضبت ونهضت فتثاقلت عن الخروج إليه فكتب إليها\n(فليت يدي بانت غداة مددتها ... إليك ولم ترجع بكف وساعد)\n(فإن يرجع الرحمن ما كان بيننا ... فلست إلى يوم التنادي بعائد)\nغنته متيم خفيف رمل بالبنصر قال وعتبت عليه مرة فتمادى عتبها وترضاها فلم ترض فكتب إليها الإدلال يدعو إلى الإملال ورب هجر دعا إلى صبر وإنما سمي القلب قلبا لتقلبه ولقد صدق العباس بن الأحنف حيث يقول\n(ما أراني الا سأهجر من ليس ... يراني أقوى على الهجران)\n(قد حدا بي إلى الجفاء وفائي ... ما أضر الوفاء بالإنسان)\nقال فخرجت إليه من وقتها ورضيت وحدثني الهشامي قال كانت متيم تحبني حبا شديدا يتجاوز محبة الأخت لأخيها وكانت تعلم أني أحب النبق فكانت لا تزال تبعث إلي منه فإني لأذكر في ليلة من الليالي في وقت السحر إذا أنا ببابي يدق فقيل من هذا فقالوا خادم متيم يريد أن يدخل إلى أبي عبد الله فقلت يدخل فدخل ومعه إلي صينية فيها نبق فقال لي تقرئك السلام وتقول لك كنت عند أمير المؤمنين المعتصم بالله فجاؤوه بنبق من أحسن ما يكون فقلت له يا سيدي أطلب من أمير المؤمنين شيئا فقال لي تطلبين ما شئت قالت يطعمني أمير المؤمنين من هذا النبق فقال لسمانة اجعل من هذا النبق في صينية واجعلوها قدام متيم فأخذته وذللته لك وقد بعثت به إليك معي ثم دفعت إلي دراهم وقالت هب للحراس هذه الدراهم لكي يفتحوا الدروب لك حتى تصير به اليه ثم حدثنا الهشامي قال بعث علي بن هشام إلى إسحاق فجاء فأخرج متيم جاريته إليه فغنت بين يديه\n(فلا زلن حسرى ظلعا لم حملنها ... إلى بلد ناء قليل الأصادق)\nفاستعاده إسحاق واستحسنه ثم قال له بكم تشتري مني هذا الصوت فقال له علي بن هشام جاريتي تصنع هذا الصوت وأشتريه منك قال قد\nأخذته الساعة وأدعيه فقول من يصدق قولي أو قولك فافتداه منه ببرذون اختاره له وحدثني الهشامي قال سمع علي بن هشام قدام المأمون من قلم جارية زبيدة صوتا عجيبا فرشا لمن أخرجه من دار زبيدة بمائة ألف دينار حتى صار إلى داره وطرح الصوت على جواريه ولو علمت بذلك زبيدة لاشتد عليها لو سألها أن توجه به ما فعلت وحدثني يحيى بن علي بن يحيى المنجم عن أبيه قال لما صنعت متيم اللحن في قوله\n(فلا زلن حسرى ظلعا لم حملنها ... )\nأعجب به علي بن هشام وأسمعه إسحاق فاستحسنه وقال من أين لك هذا فقال من بعض الجواري فقال إنه لعريب ولم يزل يستعيده حتى قال إنه لمتيم فأطرق وكان متحاملا على المغنين شديد النفاسة عليهم كثير الظلم لهم مسرفا في حط درجاتهم وما رأيته في غنائه ذكر لعلويه ولا مخارق ولا عمرو بن بانة ولا عبد الله بن عباس ولا محمد بن الحارث صوتا واحدا ترفعا عن ذكرهم منتصبا لهم وذكر في آخر الكتاب قوله\n(فلا زلن حسرى ظلعا لم حملنها ... إلى بلد ناء قليل الأصادق)\nووقع تحته لمتيم وذكر آخر كل صوت في الكتاب ونسب إلى كل مغن صوته غير مخارق وعلويه وعمرو بن بانة وعبد الله بن عباس فما ذكرهم بشيء\nأخبرنا أحمد بن جعفر جحظة قال حدثني ابن المكي عن أبيه قال قال لي علي بن هشام لما قدمت علي شاهك جدتي من خراسان قالت أعرض جواريك علي فعرضتهن عليها ثم جلسنا على الشراب وغنتنا متيم وأطالت جدتي الجلوس فلم أنبسط إلى جواري كما كنت أفعل فقلت هذين البيتين","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":53,"spl":"موت بذل","song":2,"loc":1381,"partialRef":{"sid":"b74-56","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b74-66","bab":"الجزء 7","sec":"موت بذل","page":"ج7 ص316","text":"(أنبقى على هذا وأنت قريبة ... وقد منع الزوار بعض التكلم)\n(سلام عليكم لا سلام مودع ... ولكن سلام من حبيب متيم)\nوكتبتهما في رقعة ورميت بها إلى متيم فأخذتها ونهضت إلى الصلاة ثم عادت وقد صنعت فيه اللحن الذي يغنى فيه اليوم فغنت فقالت شاهك ما أرانا إلا قد ثقلنا عليكم اليوم وأمرت الجواري فحملن محفتها وأمرت بجوائز للجواري وساوت بينهن وأمرت لمتيم بمائة ألف درهم وأخبرني قال أول من عقد من النساء في طرف الإزار زنارا وخيط إبريسم ثم تجعله في رأسها فيثبت الإزار ولا يتحرك ولا يزول متيم أخبرني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون قال مرت متيم في نسوة وهي مستخفية بقصر علي بن هشام بعد أن قتل فلما رأت بابه مغلقا لا أنيس عليه وقد علاه التراب والغبرة وطرحت في أفنيته المزابل وقفت عليه وتمثلت\n(يا منزلا لم تبل أطلاله ... حاشا لأطلالك أن تبلى)\n(لم أبك أطلالك لكنني ... بكيت عيشي فيك إذ ولى)\n(قد كان بي فيك هوى مرة ... غيبه الترب وما ملا)\n(فصرت أبكي جاهدا فقده ... عند ادكاري حيثما حلا)\n(فالعيش أولى ما بكاه الفتى ... لا بد للمحزون أن يسلى)\nفيه رمل بالوسطى لابن جامع قال ثم بكت حتى سقطت من قامتها وجعل النسوة يناشدنها ويقلن الله الله في نفسك فإنك تؤخذين الآن فبعد لأي ما حملت تتهادى بين امرأتين حتى تجاوزت الموضع نسخت من كتاب أبي سعيد السكري حدثني الحارث بن أبي أسامة قال حدثني محمد بن الحسن عن عبد الله بن العباس الربيعي قال قالت لي متيم بعث إلي المعتصم بعد قدومه بغداد فذهبت إليه فأمرني بالغناء فغنيت\n(هل مسعد لبكاء ... بعبرة أو دماء)\nفقال أعد لي عن هذا البيت إلى غيره فغنيته غيره من معناه فدمعت عيناه وقال غني غير هذا فغنيت في لحني\n(أولئك قومي بعد عز ومنعة ... تفانوا وإلا تذرف العين أكمد)\nفبكى وقال ويحك لا تغنيني في هذا المعنى شيئا البتة فغنيت في لحني\n(لا تأمن الموت في حل وفي حرم ... إن المنايا تغشى كل إنسان)\n(واسلك طريقك هونا غير مكترث ... فسوف يأتيك ما يمني لك الماني)\nفقال والله لولا أني أعلم أنك إنما غنيت بما في قلبك لصاحبك وأنك\nلم تريديني لمثلت بك ولكن خذوا بيدها فأخرجوها فأخذوا بيدي فأخرجت","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":54,"spl":"موت بذل — نسبة ما في هذا الخبر من الغناء","song":1,"loc":1382},
{"id":"b74-67","bab":"الجزء 7","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج7 ص322","text":"\n(هل مسعد لبكاء ... بعبرة أو دماء)\n(وذا لفقد خليل ... لسادة نجباء)\nالشعر لمراد شاعرة علي بن هشام ترثيه لما قتله المأمون والغناء لمتيم ولحنه من الثقيل الأول بالوسطى منها\n(ذهبت من الدنيا وقد ذهبت مني ... )\nوقد أخرج في أخبار إبراهيم بن المهدي لأنه من غنائه وشعره وشرحت أخباره فيه ولحنه رمل بالوسطى ومنها\n(أولئك قومي بعد عز ومنعة ... تفانوا وإلا تذرف العين أكمد)\nوقد أخرج في أخبار أبي سعيد مولى فائد والعبلي وغنيا فيه من مراثيهما في بني أمية ولحن متيم هذا الذي غنت فيه المعتصم ثاني ثقيل بالوسطى ومنها\n(لا تأمن الموت في حل وفي حرم ... )\nذكر الهشامي انه مما وجده من غناء متيم غير أن لها لحنا فيه يذكر في\nموضع غير هذا على شرح إن شاء الله تعالى وإنما ألفت صوتا تولعت به وغنته فنسبه إليها وأخبرني قال كنا في مجلسنا نياما فلما كان مع الفجر إذا متيم قد دخلت علينا وقالت أطعموني شيئا فأخرجوا إليها شيئا تأكله فأكلت ودعت بنبيذ وابتدأت الشرب ودعت بعود فاندفعت تغني لنفسها وتشرب وكان مما غنت\n(كيف الثواء بأرض لا أراك بها ... يا أكثر الناس عندي منة ويدا)\nخفيف رمل وقال ما رأيت أحدا من المغنين والمغنيات إذا غنوا لأنفسهم يكادون يغنون إلا خفيف رمل","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":54,"spl":"موت بذل — نسبة ما في هذا الخبر من الغناء","song":3,"loc":1383,"partialRef":{"sid":"b74-66","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b74-68","bab":"الجزء 7","sec":"نوح متيم على سيدها","page":"ج7 ص323","text":"وأخبرني قال حدثني بعض أهلها قال لما أصبنا بعلي بن هشام جاء النوائح فطرح بعض من حضر من مغناته عليهن نوحا من نوح متيم وكان حسنا جيدا فأبطأ نوح النوائح اللاتي جئن لحسنه وجودته وكانت زين حاضرة فاستحسنه جدا وقالت رضي الله عنك يا متيم كنت علما في السرور وأنت علم في المصائب وأخبرني قال إني لأذكر من بعض نوحها\n(لعلي وأحمد وحسين ... ثم نصر وقبله للخليل)\nهزج قال ابن المعتز وأخبرني الهشامي قال وجهت مؤنسة جارية المأمون إلى متيم جارية علي بن هشام في يوم احتجمت فيه مخنقة في وسطها حبة\nلها قيمة جليلة كبيرة وعن يمين الحبة ويسارها أربع يواقيت وأربع زمردات وما بينها من شذور الذهب وباقي المخنقة قد طيب بغالية وأخبرني قال كانت متيم يعجبها البنفسج جدا وكان عندها آثر من كل ريحان وطيب حتى إنها من شدة إعجابها به لا يكاد يخلو من كمها الريحان ولا نراه إلا كما قطف من البستان وقد أخبرني رحمه الله قال حدثنا أبو جعفر بن الدهقانة إن جارية للمعتصم قالت له لما ماتت متيم وإبراهيم بن المهدي وبذل يا سيدي أظن أن في الجنة عرسا فطلبوا هؤلاء إليه فنهاها المعتصم عن هذا القول وأنكره فلما كان بعد أيام وقع حريق في حجرة هذه القائلة فاحترق كل ما تملكه وسمع المعتصم الجلبة فقال ما هذا فأخبر عنه فدعا بها فقال ما قصتك فبكت وقالت يا سيدي احترق كل ما أملكه فقال لا تجزعي فإن هذا لم يحترق وإنما استعاره أصحاب ذلك العرس وقد ذكرت في متقدم أخبار متيم أنها كانت تقول الشعر ولم أذكر شيئا فمن ذلك ما أخبرنا به الحرمي بن أبي العلاء قال حدثنا الحسن بن أحمد بن أبي طالب الديناري قال حدثني الفضل بن العباس بن يعقوب قال حدثني أبي قال قال المأمون لمتيم جارية علي بن هشام أجيزي لي هذين البيتين\n(تعالي تكون الكتب بيني وبينكم ... ملاحظة نومي بها ونشير)\n(ورسلي بحاجاتي وهن كثيرة ... إليك إشارات بها وزفير)\n","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":55,"spl":"نوح متيم على سيدها — من المائة المختارة","song":1,"loc":1384},
{"id":"b74-69","bab":"الجزء 7","sec":"من المائة المختارة","page":"ج7 ص324","text":"(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\n(يصرعن ذا اللب حتى لا حراك له ... وهن أضعف خلق الله أركانا)\nروضه - من البسيط - والشعر لجرير والغناء لابن محرز ولحنه المختار من القدر الأوسط من الثقيل وفي هذه القصيدة أبيات أخر تغنى فيها ألحان سوى هذا اللحن منها قوله","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":55,"spl":"نوح متيم على سيدها — من المائة المختارة","song":1,"loc":1385},
{"id":"b74-70","bab":"الجزء 7","sec":"من المائة المختارة","page":"ج7 ص325","text":"(أتبعتهم مقلة إنسانها غرق ... هل ما ترى تارك للعين إنسانا)\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\nلغناء في هذين البيتين ثقيل أول مطلق بإطلاق الوتر في مجرى البنصر ومنها أيضا\n(بان الأخلا وما ودعت من بانا ... وقطعوا من حبال الوصل أركانا)\n(أصبحت لا أبتغي من بعدهم بدلا ... بالدار دارا ولا الجيران جيرانا)\n(وصرت مذ ودع الأظعان ذا طرب ... مروعا من حذار البين محزانا)\nي الأول والثاني والثالث من الأبيات خفيف رمل بالبنصر وفيها للغريض ثاني ثقيل بالبنصر من رواية عمرو بن بانة والهشامي وذكر حبش أن فيه لمالك خفيف رمل بالوسطى وابن سرجس في الأول والثاني وبعدهمها\n(أتبعتهم مقلة إنسانها غرق ... )\nرمل بالوسطى وذكر الهشامي أن لابن محرز في الأول والثاني بعدهما أتبعتهم مقلة لحنا من الثقيل الأول بالبنصر وذكر المكي أنه لمعبد . . انتهى بحمد الله","topic":"أخبار حسين بن الضحاك ونسبه","topicNo":74,"sp":55,"spl":"نوح متيم على سيدها — من المائة المختارة","song":1,"loc":1386,"partial":1},
{"id":"b75-1","bab":"الجزء 8","sec":"بسم الله الرحمن الرحيم نسب جرير وأخباره","page":"ج8 ص5","text":"جرير بن عطية بن الخطفي والخطفي لقب واسمه حذيفة بن بدر بن سلمة بن عوف بن كليب بن يربوع بن حنظلة بن مالك بن زيد مناة بن تميم بن مر بن أد بن طابخة بن إلياس بن مضر بن نزار ويكنى أبا حزرة ولقب الخطفي لقوله\n(يرفعن لليل إذا ما أسدفا ... أعناق جنان وهاما رجفا)\n(وعنقا بعد الكلال خيطفا ... )\nيروى خطفى\nوهو الفرزدق والأخطل المقدمون على شعراء الإسلام الذين لم يدركوا الجاهلية جميعا ومختلف في أيهم المتقدم ولم يبق أحد من شعراء عصرهم إلا تعرض لهم فافتضح وسقط وبقوا يتصاولون على أن الأخطل إنما دخل بين جرير والفرزدق في آخر أمرهما وقد أسن ونفد أكثر عمره وهو وإن كان له فضله وتقدمه فليس نجره من نجار هذين في شيء وله أخبار مفردة عنهما ستذكر بعد هذا مع ما يغنى من شعره أخبرني أبو خليفة الفضل بن الحباب الجمحي قال حدثنا محمد بن سلام الجمحي وأخبرني محمد بن العباس اليزيدي وعلي بن سليمان الأخفش قالا حدثنا أبو سعيد السكري عن محمد بن حبيب وأبي غسان دماذ وإبراهيم بن سعدان عن أبيه جميعا عن أبي عبيدة معمر بن المثنى بنسب جرير على ما ذكرته وسائر ما أذكره في الكتاب من أخباره فأحكيه عن أبي عبيدة أو عن محمد بن سلام قالوا جميعا وأم جرير أم قيس بنت معيد بن عمير بن مسعود بن حارثة بن عوف بن كليب بن يربوع وأم عطية النوار بنت يزيد بن عبد العزى بن مسعود بن حارثة بن عوف بن كليب\nقال أبو عبيدة ومحمد بن سلام ووافقهما الأصمعي فيما أخبرنا به أحمد بن عبد العزيز عن عمر بن شبة عنه اتفقت العرب على أن أشعر أهل الإسلام ثلاثة جرير والفرزدق والأخطل واختلفوا في تقديم بعضهم على بعض قال محمد بن سلام والراعي معهم في طبقتهم ولكنه آخرهم والمخالف في ذلك قليل وقد سمعت يونس يقول ما شهدت مشهدا قط قد ذكر فيه جرير والفرزدق فاجتمع أهل المجلس على أحدهما وكان يونس فرزدقيا (","topic":"نسب جرير وأخباره","topicNo":75,"sp":0,"spl":"بسم الله الرحمن الرحيم نسب جرير وأخباره — الفرزدق أشعر عامة وجرير أشعر خاصة","loc":1387,"partial":1},
{"id":"b75-2","bab":"الجزء 8","sec":"الفرزدق أشعر عامة وجرير أشعر خاصة","page":"ج8 ص7","text":"ال ابن سلام وقال ابن دأب الفرزدق أشعر عامة وجرير أشعر خاصة وقال أبو عبيدة كان أبو عمرو يشبه جريرا بالأعشى والفرزدق بزهير والأخطل بالنابغة قال أبو عبيدة يحتج من قدم جريرا بأنه كان أكثرهم فنون شعر وأسهلهم ألفاظا وأقلهم تكلفا وأرقهم نسيبا وكان دينا عفيفا وقال عامر بن عبد الملك جرير كان أشبههما وأنسبهما\nونسخت من كتاب عمرو بن أبي عمرو الشيباني قال خالد بن كلثوم ما رأيت أشعر من جرير والفرزدق قال الفرزدق بيتا مدح فيه قبيلتين وهجا قبيلتين قال\n(عجبت لعجل إذ تهاجي عبيدها ... كما آل يربوع هجوا آل دارم)\nعني بعبيدها بني حنيفة وقال جرير بيتا هجا فيه أربعة\n(إن الفرزدق والبعيث وأمه ... وأبا البعيث لشر ما إستار)\nال وقال جرير لقد هجوت التيم في ثلاث كلمات ما هجا فيهن شاعر شاعرا قبلي قلت\n(من الأصلاب ينزل لؤم تيم ... وفي الأرحام يخلق والمشيم)\nقال محمد بن سلام قال العلاء بن جرير العنبري وكان شيخا قد جالس الناس إذا لم يجىء الأخطل سابقا فهو سكيت والفرزدق لا يجيء سابقا ولا سكيتا وجرير يجيء سابقا ومصليا وسكيتا قال محمد بن سلام ورأيت أعرابيا من بني أسد أعجبني ظرفه وروايته فقلت له أيهما عندكم أشعر قال بيوت الشعر أربعة فخر ومديح وهجاء ونسيب وفي كلها غلب جرير قال في الفخر\n(إذا غضبت عليك بنو تميم ... حسبت الناس كلهم غضابا)\nوالمديح\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nالهجاء\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\nالنسيب\n(إن العيون التي في طرفها حور ... قتلننا ثم لم يحيين قتلانا)\nال أبو عبد الله محمد بن سلام وبيت النسيب عندي\n(فلما التقى الحيان ألقيت العصا ... ومات الهوى لما أصيبت مقاتله)\nقال كيسان أما والله لقد أوجعكم يعني في الهجاء فقال يا أحمق أوذاك يمنعه أن يكون شاعرا","topic":"نسب جرير وأخباره","topicNo":75,"sp":0,"spl":"بسم الله الرحمن الرحيم نسب جرير وأخباره — الفرزدق أشعر عامة وجرير أشعر خاصة","loc":1388},
{"id":"b75-3","bab":"الجزء 8","sec":"عبيدة بن هلال يفضل جريرا على الفرزدق","page":"ج8 ص9","text":"أخبرني أحمد بن عبد العزيز قال حدثني عمر بن شبة قال قال أبو عبيدة وأخبرنا أبو خليفة قال حدثني محمد بن سلام الجمحي قال حدثني أبان بن عثمان البلخي قال تنازع في جرير والفرزدق رجلان في عسكر المهلب فارتفعا إليه وسألاه فقال لا أقول بينهما شيئا ولكني أدلكما على من يهون عليه سخطهما\nعبيدة بن هلال اليشكري وكان بإزائه مع قطري وبينهما نهر وقال عمر بن شبة في هؤلاء الخوارج من تهون عليه سبال كل واحد منهما فأما أنا فما كنت لأعرض نفسي لهما فخرج أحد الرجلين وقد تراضيا بحكم الخوارج فبدر من الصف ثم دعا بعبيدة بن هلال للمبارزة فخرج إليه فقال إني أسألك عن شيء تحاكمنا إليك فيه فقال وما هو عليكما لعنة الله قال فأي الرجلين عندك أشعر أجرير أم الفرزدق فقال لعنكما الله ولعن جريرا والفرزدق أمثلي يسأل عن هذين الكلبين قالا لابد من حكمك قال فإني سائلكم قبل ذلك عن ثلاث قالوا سل قال ما تقولون في إمامكم إذا فجر قالوا نطيعه وإن عصى الله عز و جل قال قبحكم الله فما تقولون في كتاب الله وأحكامه قالوا ننبذه وراء ظهورنا ونعطل أحكامه قال لعنكم الله إذا فما تقولون في اليتيم قالوا نأكل ماله وننيك أمه قال أخزاكم الله إذا والله لقد زدتموني فيكم بصيرة ثم ذهب لينصرف فقالوا له إن الوفاء يلزمك وقد سألتنا فأخبرناك ولم تخبرنا فرجع فقال من الذي يقول\n(إنا لنذعر يا قفير عدونا ... بالخيل لاحقة الأياطل قودا)\n(وتحوط حوزتنا وتحمي سرحنا ... جرد ترى لمغارها أخدودا)\n(أجرى قلائدها وقدد لحمها ... ألا يذقن مع الشكائم عودا)\n(وطوى القياد مع الطراد متونها ... طي التجار بحضرموت برودا)\nالا جرير قال فهو ذاك فانصرفا أخبرني عم أبي عبد العزيز بن أحمد قال حدثنا الرياشي قال قال الأصمعي وذكر جريرا فقال كان ينهشه ثلاثة وأربعون شاعرا فينبذهم وراء ظهره ويرمي بهم واحدا واحدا ومنهم من كان ينفحه فيرمي به وثبت له الفرزدق والأخطل وقال جرير والله ما يهجوني الأخطل وحده وإنه ليهجوني معه خمسون شاعرا كلهم عزيز ليس بدون الأخطل وذلك أنه كان إذا أراد هجائي جمعهم على شراب فيقول هذا بيتا وهذا بيتا وينتحل هو القصيدة بعد أن يتمموها قال ابن سلام وحدثني أبو البيداء الرياحي قال قال الفرزدق إني وإياه لنغترف من بحر واحد وتضطرب دلاؤه عند طول النهر أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني زيرك بن هبيرة المناني قال كان جرير ميدان الشعر من لم يجر فيه لم يرو شيئا وكان من هاجى جريرا فغلبه جرير أرجح عندهم ممن هاجى شاعرا آخر غير جرير فغلب أخبرنا أبو خليفة عن محمد بن سلام قال تذاكروا جريرا والفرزدق في حلقة يونس بن معاوية بن أبي عمرو بن العلاء وخلف الأحمر ومسمع وعامر\nابنا عبد الملك المسمعيان فسمعت عامرا وهو شيخ بكر بن وائل يقول كان جرير والله أنسبهما وأسبهما وأشبههما (","topic":"نسب جرير وأخباره","topicNo":75,"sp":1,"spl":"عبيدة بن هلال يفضل جريرا على الفرزدق — الراعي يقر بأسبقيته","loc":1389},
{"id":"b75-4","bab":"الجزء 8","sec":"الراعي يقر بأسبقيته","page":"ج8 ص11","text":"قال ابن سلام وحدثني أبو البيداء قال مر راكب بالراعي وهو يغني بيتين لجرير وهما\n(وعاو عوى من غير شيء رميته ... بقارعة أنفاذها تقطر الدما)\n(خروج بأفواه الرواة كأنها ... قرا هندواني إذا هز صمما)\nأتبعه الراعي رسولا يسأله لمن البيتان قال لجرير قال لو اجتمع على هذا جميع الجن والإنس ما أغنوا فيه شيئا ثم قال لمن حضر ويحكم أألام على أن يغلبني مثل هذا","topic":"نسب جرير وأخباره","topicNo":75,"sp":1,"spl":"عبيدة بن هلال يفضل جريرا على الفرزدق — الراعي يقر بأسبقيته","loc":1390},
{"id":"b75-5","bab":"الجزء 8","sec":"رأي بشار فيه","page":"ج8 ص12","text":"قال ابن سلام وسألت بشارا المرعث أي الثلاثة أشعر فقال لم يكن الأخطل مثلهما ولكن ربيعة تعصبت له وأفرطت فيه قلت فهذان قال كانت لجرير ضروب من الشعر لا يحسنها الفرزدق ولقد ماتت النوار فقاموا ينوحون عليها بشعر جرير فقلت لبشار وأي شيء لجرير من المراثي إلا\nالتي رثى بها امرأته فأنشدني لجرير يرثي ابنه سوادة ومات بالشام\n(قالوا نصيبك من أجر فقلت لهم ... كيف العزاء وقد فارقت أشبالي)\n(فارقتني حين كف الدهر من بصري ... وحين صرت كعظم الرمة البالي)\n(أمسى سوادة يجلو مقلتي لحم ... باز يصرصر فوق المربأ العالي)\n(قد كنت أعرفه مني إذا غلقت ... رهن الجياد ومد الغاية الغالي)\n(إن الثوي بذي الزيتون فاحتسبي ... قد أسرع اليوم في عقلي وفي حالي)\n(إلا تكن لك بالديرين معولة ... فرب باكية بالرمل معوال)\n(كأم بو عجول عند معهده ... حنت إلى جلد منه وأوصال)\n(حتى إذا عرفت أن لا حياة به ... ردت هماهم حرى الجوف مثكال)\n(زادت على وجدها وجدا وإن رجعت ... في الصدر منها خطوب ذات بلبال)\nخبرني عبد الواحد بن عبيد عن قعنب بن المحرز الباهلي عن المغيرة بن حجناء وعمارة بن عقيل قالا خرج جرير إلى دمشق يؤم الوليد فمرض ابن له يقال له سوادة وكان به معجبا فمات بالشام فجزع عليه ورثاه جرير فقال\n(أودى سوادة يجلو مقلتي لحم ... باز يصرصر فوق المربأ العالي)","topic":"نسب جرير وأخباره","topicNo":75,"sp":2,"spl":"رأي بشار فيه — رأي الفرزدق فيه","loc":1391},
{"id":"b75-6","bab":"الجزء 8","sec":"رأي الفرزدق فيه","page":"ج8 ص14","text":"خبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أحمد بن معاوية قال حدثني رجل من أصحاب الحديث يقال له الحسن قال حدثني أبو نصر اليشكري عن مولى لبني هاشم قال امترى أهل المجلس في جرير والفرزدق أيهما أشعر فدخلت على الفرزدق فما سألني عن شيء حتى قال يا نوار أدركت برنيتك قالت قد فعلت أو كادت قال فابعثي بدرهم فاشتري لحما ففعلت وجعلت تشرحه وتلقيه على النار ويأكل ثم قال هاتي برنيتك فشرب قدحا ثم ناولني وشرب آخر ثم ناولني ثم قال هات حاجتك يابن أخي فأخبرته قال أعن ابن الخطفي تسألني ثم تنفس حتى قلت انشقت حيازيمه ثم قال قاتله الله فما أخشن ناحيته وأشرد قافيته والله لو تركوه لأبكى العجوز على شبابها والشابة على أحبابها ولكنهم هروه فوجدوه عند الهراش نابحا وعند الجراء قارحا وقد قال بيتا لأن أكون قلته أحب إلي مما طلعت عليه الشمس\n(إذا غضبت عليك بنو تميم ... حسبت الناس كلهم غضابا)\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة وأخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبيدة قالا\nنزل الفرزدق على الأحوص حين قدم المدينة فقال الأحوص ما تشتهي قال شواء وطلاء وغثاء قال ذلك لك ومضى به إلى قينة بالمدينة فغنته\n(ألا حي الديار بسعد إني ... أحب لحب فاطمة الديارا)\n(إذا ما حل أهلك يا سليمى ... بدارة صلصل شحطوا مزارا)\n(أراد الظاعنون ليحزنوني ... فهاجوا صدع قلبي فاستطارا)\nناه ابن محرزخفيف ثقيل أول بالبنصر فقال الفرزدق ما أرق أشعاركم يا أهل الحجاز وأملحها قال أوما تدري لمن هذا الشعر قال لا والله قال فهو والله لجرير يهجوك به فقال ويل ابن المراغة ما كان\nأحوجه مع عفافه إلى صلابة شعري وأحوجني مع شهواتي إلى رقة شعره (","topic":"نسب جرير وأخباره","topicNo":75,"sp":2,"spl":"رأي بشار فيه — رأي الفرزدق فيه","song":1,"loc":1392},
{"id":"b75-7","bab":"الجزء 8","sec":"تغنى أشعب بشعره فأجازه","page":"ج8 ص16","text":"خبرني أحمد قال حدثنا عمر بن شبة عن إسحاق الموصلي وأخبرني محمد بن مزيد عن حماد عن أبيه قال قال إسحاق بن يحيى بن طلحة قدم علينا جرير المدينة فحشدنا له فبينا نحن عنده ذات يوم إذ قام لحاجته وجاء الأحوص فقال أين هذا فقلنا قام آنفا ما تريد منه قال أخزيه والله إن الفرزدق لأشعر منه وأشرف فأقبل جرير علينا وقال من الرجل قلنا الأحوص بن محمد بن عاصم بن ثابت بن أبي الأقلح قال هذا الخبيث ابن الطيب ثم أقبل عليه فقال قد قلت\n(يقر بعيني ما يقر بعينها ... وأحسن شيء ما به العين قرت)\nإنه يقر بعينها أن يدخل فيها مثل ذراع البكر أفيقر ذلك بعينك قال وكان الأحوص يرمى بالأبنة فانصرف وأرسل إليه بتمر وفاكهة وأقبلنا نسأل جريرا وهو في مؤخر البيت وأشعب عند الباب فأقبل أشعب يسأله فقال له جرير والله إنك لأقبحهم وجها ولكني أراك أطولهم حسبا وقد أبرمتني\nفقال أنا والله أنفعهم لك فانتبه جرير فقال كيف قال إني لأملح شعرك واندفع يغنيه قوله\n(يا أخت ناجية السلام عليكم ... قبل الفراق وقبل لوم العذل)\n(لو كنت أعلم أن آخر عهدكم ... يوم الفراق فعلت ما لم أفعل)\nال فأدناه جرير منه حتى ألصق ركبته بركبته وجعله قريبا منه ثم قال أجل والله إنك لأنفعهم لي وأحسنهم تزيينا لشعري أعد فأعاده عليه وجرير يبكي حتى أخضلت لحيته ثم وهب لأشعب دراهم كانت معه وكساه حلة من حلل الملوك وكان يرسل إليه طول مقامه بالمدينة فيغنيه أشعب ويعطيه جرير شعره فيغني فيه قال وكان أشعب من أحسن الناس صوتا قال حماد والغناء الذي غناه فيه أشعب لابن سريج أخبرني علي بن سليمان قال حدثنا أبو سعيد السكري عن الرياشي عن الأصمعي قال وذكر المغيرة بن حجناء قال حدثني أبي عن أبيه عن جده يحيى بن أعين وذكر ذلك هشام بن الكلبي قال حدثني النهشلي من بني مسعود بن خالد بن مالك بن ربعي بن سلمى بن جندل قال حدثني مسحل بن كسيب بن عمران بن عطاء بن الخطفي وأمه الربداء بنت جرير وهذا الخبر وإن كان فيه طول محتو على سائر أخبار من ناقض جريرا أو اعتن بينه وبين\nالفرزدق وغيره فذكرته هنا لاشتماله على ذلك في بلاغ واختصار (","topic":"نسب جرير وأخباره","topicNo":75,"sp":3,"spl":"تغنى أشعب بشعره فأجازه — شعره في مدح الحكم بن أيوب","song":1,"loc":1393},
{"id":"b75-8","bab":"الجزء 8","sec":"شعره في مدح الحكم بن أيوب","page":"ج8 ص18","text":"ن جريرا قدم على الحكم بن أيوب بن يحيى بن الحكم بن أبي عقيل وهو خليفة للحجاج يومئذ فمدحه جرير فقال\n(أقبلت من ثهلان أو جنبي خيم ... على قلاص مثل خيطان السلم)\nهلان جبل كان لباهلة ثم غلبت عليه نمير وخيم جبل يناوحه من طرفه الأقصى فيما بين ركنه الأقصى وبين مطلع الشمس به ماء ونخل\n(قد طويت بطونها طي الأدم ... يبحثن بحثا كمضلات الخدم)\n(إذا قطعن علما بدا علم ... حتى تناهين إلى باب الحكم)\n(خليفة الحجاج غير المتهم ... في معقد العز وبؤبوء الكرم)\n(بعد انفضاج البدن واللحم زيم ... )\nلما قدم عليه استنطقه فأعجبه ظرفه وشعره فكتب إلى الحجاج إنه قدم علي أعرابي شيطان من الشياطين فكتب إليه أن ابعث به إلي ففعل فقدم عليه فأكرمه الحجاج وكساه جبة صبرية وأنزله فمكث أياما ثم أرسل\nإليه بعد نومه فقالوا أجب الأمير فقال ألبس ثيابي فقالوا لا والله لقد أمرنا أن نأتيه بك على الحال التي نجدك عليها ففزع جرير وعليه قميص غليظ وملاءة صفراء فلما رأى ما به رجل من الرسل دنا منه وقال لا بأس عليك إنما دعاك للحديث (","topic":"نسب جرير وأخباره","topicNo":75,"sp":3,"spl":"تغنى أشعب بشعره فأجازه — شعره في مدح الحكم بن أيوب","loc":1394,"partial":1},
{"id":"b75-9","bab":"الجزء 8","sec":"هجوه للشعراء","page":"ج8 ص19","text":"ال جرير فلما دخلت عليه قال إيه يا عدو الله علام تشتم الناس وتظلمهم فقلت جعلني الله فداء الأمير والله إني ما أظلمهم ولكنهم يظلمونني فأنتصر ما لي ولابن أم غسان وما لي وللبعيث وما لي وللفرزدق وما لي وللأخطل وما لي وللتيمي حتى عددهم واحدا واحدا فقال الحجاج ما أدري ما لك ولهم قال أخبر الأمير أعزه الله أما غسان بن ذهيل فإنه رجل من قومي هجاني وهجا عشيرتي وكان شاعرا قال فقال لك ماذا قال قال لي\n(لعمري لئن كانت بجيلة زانها ... جرير لقد أخزى كليبا جريرها)\n(رميت نضالا عن كليب فقصرت ... مراميك حتى عاد صفرا جفيرها)\n(ولا يذبحون الشاة إلا بميسر ... طويل تناجيها صغار قدورها)\nال فما قلت له قال قلت\n(ألا ليت شعري عن سليط ألم تجد ... سليط سوى غسان جارا يجيرها)\n(فقد ضمنوا الأحساب صاحب سوءة ... يناجي بها نفسا خبيثا ضميرها)\n(كأن سليطا في حواشنها الخصى ... إذا حل بين الأملحين وقيرها)\n(أضجوا الروايا بالمزاد فإنكم ... ستكفون ركض الخيل تدمى نحورها)\n(كأن السليطيات مجناة كمأة ... لأول جان بالعصا يستثيرها)\n(غضاريط يشوون الفراسن بالضحى ... إذا ما السرايا حث ركضا مغيرها)\n(فما في سليط فارس ذو حفيظة ... ومعقلها يوم الهياج جعورها)\n(عجبت من الداعي جحيشا وصائدا ... وعيساء يسعى بالعلاب نفيرها)\nال ثم من قال البعيث قال ما لك وله قال اعترض دون ابن أم غسان يفضله علي ويعينه قال فما قال لك قال قال لي\n(كليب لئام الناس قد تعلمونه ... وأنت إذا عدت كليب لئيمها)\n(أترجوا كليب أن يجيء حديثها ... بخير وقد أعيا كليبا قديمها)\nال فما قلت له قال قلت\n(ألم تر أني قد رميت ابن فرتنى ... بصماء لا يرجو الحياة اميمها)\n(له أم سوء بئس ما قدمت له ... إذا فرط الأحساب عد قديمها)\nال ثم من قلت الفرزدق قال وما لك وله قلت أعان البعيث علي قال فما قلت له قال قلت\n(تمنى رجال من تميم لي الردى ... وما ذاد عن أحسابهم ذائد مثلي)\n(كأنهم لا يعلمون مواطني ... وقد جربوا أني أنا السابق المبلي)\n(فلو شاء قومي كان حلمي فيهم ... وكان على جهال أعدائهم جهلي)\n(وقد زعموا أن الفرزدق حية ... وما قتل الحيات من أحد قبلي)\nال ثم من قلت الأخطل قال ما لك وله قلت رشاه محمد بن عمير بن عطارد زقا من خمر وكساه حلة على أن يفضل علي الفرزدق ويهجوني قال فما قال لك قال قال\n(إخسأ إليك كليب إن مجاشعا ... وأبا الفوارس نهشلا أخوان)\n(وإذا وردت الماء كان لدارم ... جماته وسهولة الأعطان)\n(وإذا قذفت أباك في ميزانهم ... رجحوا وشال أبوك في الميزان)\nال فما قلت له قال قلت\n(يا ذا العباءة إن بشرا قد قضى ... ألا تجوز حكومة النشوان)\n(فدعوا الحكومة لستم من أهلها ... إن الحكومة في بني شيبان)\n(قتلوا كليبكم بلقحة جارهم ... يا خزر تغلب لستم بهجان)\nقال ثم من قلت عمر بن لجأ التيمي قال ما لك وله قال قلت بيتا من شعر فقبحه وقاله على غير ما قلته قلت\n(لقومي أحمى للحقيقة منكم ... وأضرب للجبار والنقع ساطع)\n(وأوثق عند المرهفات عشية ... لحاقا إذا ما جرد السيف لامع)\nزعم أني قلت\n(وأوثق عند المردفات عشية ... لحاقا إذا ما جرد السيف لامع)\nفقال لحقتهن عند العشي وقد أخذن غدوة والله ما يمسين حتى يفضحن قال فما قلت له قال قلت\n(يا تيم تيم عدي لا أبا لكم ... لا يوقعنكم في سوءة عمر)\n(خل الطريق لمن يبني المنار به ... وابرز ببرزة حيث اضطرك القدر)\nتى أتى على الشعر قال ثم من قلت سراقة بن مرداس البارقي قال ما لك وله قال قلت لا شيء حمله بشر من مروان وأكرهه على هجائي ثم بعث إلي رسولا وأمرني أن أجيبه قال فما قال لك قال قال\n(إن الفرزدق برزت أعراقه ... عفوا وغودر في الغبار جرير)\n(ما كنت أول محمر قعدت به ... مسعاته إن اللئيم عثور)\n(هذا قضاء البارقي وإنه ... بالميل في ميزانكم لبصير)\nال فما قلت له قال قلت\n(يا بشر حق لوجهك التبشير ... هلا غضبت لنا وأنت أمير)\n(بشر أبو مروان إن عاسرته ... عسر وعند يساره ميسور)\n(إن الكريمة ينصر الكرم ابنها ... وابن اللئيمة للئام نصور)\n(قد كان حقك أن تقول لبارق ... يا آل بارق فيم سب جرير)\n(وكسحت بآستك للفخار وبارق ... شيخان أعمى مقعد وكسير)\nال ثم من قلت البلتع وهو المستنير بن سبرة العنبري قال ما لك\nوله قلت أعان علي آبن لجأ قال فما قال لك قلت قال","topic":"نسب جرير وأخباره","topicNo":75,"sp":4,"spl":"هجوه للشعراء","loc":1395},
{"id":"b75-10","bab":"الجزء 8","sec":"هجوه للشعراء","page":"ج8 ص19","text":"(إن التي ربتك لما طلقت ... قعدت على جحش المراغة تمرغ)\n(أتعيب من رضيت قريش صهره ... وأبوك عبد بالخورنق)\nأذلغ\nال فما قلت له قال قلت\n(فما مستنير الخبث إلا فراشة ... هوت بين مؤتج الحريقين ساطع)\n(نهيت بنات المستنير عن الرقى ... وعن مشيهن الليل بين المزارع)\nيروى\n(. . بين مؤتج من النار ساطع ... )\nال ثم من قلت راعي الإبل قال ما لك وله قلت قدمت البصرة وكان بلغني أنه قال لي\n(يا صاحبي دنا الرواح فسيرا ... غلب الفرزدق في الهجاء جريرا)\nقال أيضا\n(رأيت الجحش جحش بني كليب ... تيمم حوض دجلة ثم هابا)\nقلت يا أبا جندل إنك شيخ مضر وشاعرها وقد بلغني أنك تفضل علي الفرزدق وأنت يسمع قولك وهو ابن عمي دونك فإن كان لا بد من تفضيل فأنا أحق به لمدحي قومك وذكري إياهم قال وابنه جندل على فرس\nله فأقبل يسير بفرسه حتى ضرب عجز دابتي وأنا قائم فكاد يقطع أصبع رجلي وقال لا أراك واقفا على هذا الكلب من بني كليب فمضى وناديته أنا ابن يربوع إن أهلك بعثوك مائرا من هبود وبئس المائر وإنما بعثني أهلي لأقعد على قارعة هذا المربد فلا يسبهم أحد إلا سببته وإن علي نذرا إن جعلت في عيني غمضا حتى أخزيك قال فما أصبحت حتى هجوته فقلت\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\nال فغدوت عليه من الغد فأخذت بعنانه فما فارقته حتى أنشدته إياها فلما مررت على قولي\n(أجندل ما تقول بنو نمير ... إذا ما الأير في است أبيك غابا)\nال فأرسل يدي وقال يقولون والله شرا قال ثم من قلت العباس بن يزيد الكندي قال ما لك وله قال لما قلت\n(إذا غضبت عليك بنو تميم ... حسبت الناس كلهم غضابا)\nقال\n(ألا رغمت أنوف بني تميم ... فساة التمر إن كانوا غضابا)\n(لقد غضبت عليك بنو تميم ... فما نكأت بغضبتها ذبابا)\n(لو اطلع الغراب على تميم ... وما فيها من السوءات شابا)\nال فتركته خمس سنين لا أهجوه ثم قدمت الكوفة فأتيت مجلس\nكندة فطلبت إليهم أن يكفوه عني فقالوا ما نكفه وإنه لشاعر وأوعدوني فقلت\n(ألا أبلغ بني حجر بن وهب ... بأن التمر حلو في الشتاء)\n(فعودوا للنخيل فأبروها ... وعيثوا بالمشقر فالصفاء)\nال فمكثت قليلا ثم بعثوا إلي راكبا فأخبروني بمثالبه وجواره في طيىء حيث جاور عتابا وحبل أخته هضيبة حيث حبلت قال فقلت ماذا قال قلت\n(إذا جهل الشقي ولم يقدر ... لبعض الأمر أوشك أن يصابا)\n(أعبدا حل في شعبى غريبا ... ألؤما لا أبالك واغترابا)\n(فما خفيت هضيبة حين جرت ... ولا إطعام سخلتها الكلابا)\n(تخرق بالمشاقص حالبيها ... وقد بلت مشيمتها الترابا)\n(فقد حملت ثمانية وأوفت ... بتاسعها وتحسبها كعابا)\nال ثم من قلت جفنة الهزاني بن جعفر بن عباية بن شكس من عنزة قال وما لك وله قال أقبل سائلا حتى أتاني وأنا أمدر حوضا لي فقال يا جرير قم إلي ها هنا قلت نعم ثم أتيته فقلت ما حاجتك قال مدحتك فاستمع مني قلت أنشدني فأنشد فقلت قد والله أحسنت\nوأجملت فما حاجتك قال تكسوني الحلة التي كساكها الوليد بن عبد الملك العام فقلت إني لم أقف فيها بالموسم ولا بد من أن أقف فيها العام ولكني أكسوك حلة خيرا منها كان كسانيها الوليد عاما أول فقال ما أقبل غيرها بعينها فقلت بلى فأقبل وأزيدك معها دنانير نفقة فقال ما أفعل ومضى فأتى المرار بن منقذ أحد بني العدوية فحمله على ناقة له يقال لها القصواء فقال جفنة\n(لعمرك للمرار يوم لقيته ... على الشحط خير من جرير وأكرم)\nال فما قلت له قال قلت\n(لقد بعثت هزان جفنة مائرا ... فآب وأحذى قومه شر مغنم)\n(فيا راكب القصواء ما أنت قائل ... لهزان إذ أسلمتها شر مسلم)\n(أظن عجان التيس هزان طالبا ... علالة سباق الأضاميم مرجم)\n(كأن بني هزان حين رديتهم ... وبار تضاغت تحت غار مهدم)\n(بني عبد عمرو قد فرغت إليكم ... وقد طال زجري لو نهاكم تقدمي)\n(ورصعاء هزانية قد تحفشت ... على مثل حرباء الفلاة المعمم)\nال ثم من قلت المرار بن منقذ قال ما لك وله قلت أعان علي الفرزدق قال فما قلت له قال قلت\n(بني منقذ لا صلح حتى تضمكم ... من الحرب صماء القناة زبون)\n(وحتى تذوقوا كأس من كان قبلكم ... ويسلح منكم في الحبال قرين)\n(فإن كنتم كلبى فعندي شفاؤكم ... وللجن إن كان اعتراك جنون)","topic":"نسب جرير وأخباره","topicNo":75,"sp":5,"spl":"هجوه للشعراء","loc":1396,"partial":1},
{"id":"b75-11","bab":"الجزء 8","sec":"هجوه للشعراء","page":"ج8 ص19","text":"ال ثم من قلت حكيم بن معية من بني ربيعة بن مالك بن زيد مناة بن تميم قال وما لك وله قلت بلغني أنه اعان علي غسان السليطي قال فما قلت له قال قلت\n(إذا طلع الركبان نجدا وغوروا ... بها فارجزا يا بني معية أو دعا)\n(أتسمن أستاه المجر وقد رأوا ... مجرا بوعساوي رماح مصرعا)\nألا إنما كانت غضوب محاميا ... غداة اللوى لم تدفع الضيم مدفعا\nال ثم من قلت ثور بن الأشهب بن رميلة النهشلي قال وما لك وله قلت أعان علي الفرزدق قال فما قلت له قال قلت\n(سيخزى إذا ضنت حلائب مالك ... ثوير ويخزى عاصم وجميع)\n(وقبلك ما أعيا الرماة إذا رموا ... صفا ليس في قاراتهن صدوع)\nقال ثم من قلت الدلهمس أحد بني ربيعة بن مالك بن زيد مناة قال ما لك وله قلت أعان علي الفرزدق قال فما قلت له قال قلت\n(لقد نفخت منك الوريدين علجة ... خبيثة ريح المنكبين قبوع)\n(ولو أنجبت أم الدلهمس لم يعب ... فوارسنا لا عاش وهو جميع)\n(أليس ابن حمراء العجان كأنما ... ثلاثة غربان عليه وقوع)\n(فلا تدنيا رحل الدلهمس إنه ... بصير بما يأتي اللئام سميع)\n(هو النخبة الخوار ما دون قلبه ... حجاب ولا حول الحجاب ضلوع)\nال ثم مررت على مجلس لهم فاعتذرت إليهم فلم يقبلوا عذري وأنشدوني شعرا لم يخبروني من قاله\n(غضبت علينا أن علاك ابن غالب ... فهلا على جديك في ذاك تغضب)\n(هما إذ علا بالمرء مسعاة قومه ... أناخا فشداك العقال المؤرب)\nال فعلمت أنه شعر قبضة الكلب قال فجمعتهم في شعري فقلت\n(وأكثر ما كانت ربيعة أنها ... خباءان شتى لا أنيس ولا قفر)\n(محالفهم فقر شديد وذلة ... وبئس الحليفان المذلة والفقر)\n(فصبرا على ذل ربيع بن مالك ... وكل ذليل خير عادته الصبر)\nال ثم من قلت هبيرة بن الصلت الربعي من ربيعة بن مالك أيضا كان يروي شعر الفرزدق قال فما قلت له قال قلت\n(يمشي هبيرة بعد مقتل شيخه ... مشي المراسل أوذنت بطلاق)\n(ماذا أردت إلي حين تحرقت ... ناري وشمر مئزري عن ساقي)\n(إن القراف بمنخريك لبين ... وسواد وجهك يآبن أم عفاق)\n(سيروا فرب مسبحين وقائل ... هذا شقا لبني ربيعة باقي)\n(أبني ربيعة قد أخس بحظكم ... لؤم الجدود ودقة الأخلاق)\nال ثم من قلت علقة والسرندى من بني الرباب كانا يعينان ابن لجأ قال فما قلت لهما قال قلت\n(عض السرندى على تثليم ناجذه ... من أم علقة بظرا غمه الشعر)\n(وعض علقة لا يألوا بعرعرة ... من بظر أم السرندى وهو منتصر)\nال ثم من قلت الطهوي كان يروي شعر الفرزدق قال ما قلت له قال قلت\n(أتنسون وهبا يا بني زبد استها ... وقد كنتم جيران وهب بن أبجرا)\n(فما تتقون الشر حتى يصيبكم ... ولا تعرفون الأمر إلا تدبرا)\n(ألا رب أعشى ظالم متخمط ... جعلت لعينيه جلاء فأبصرا)\nقال ثم من قلت عقبة بن السنيع الطهوي وكان نذر دمي قال\nفما قلت له قال قلت\n(يا عقب يابن سنيع ليس عندكم ... مأوى الرفاق ولا ذو الراية الغادي)\n(يا عقب يابن سنيع بعض قولكم ... إن الوثاب لكم عندي بمرصاد)\n(ما ظنكم ببني ميثاء إن فزعوا ... ليلا وشد عليهم حية الوادي)\n(يغدوا علي أبو ليلى ليقتلني ... جهلا علي ولم يثأر بشداد)\n(إرووا علي وأرضوا بي صديقكم ... واستسمعوا يا بني ميثاء إنشادي)\nميثاء هي بنت زهير بن شداد الطهوي وهي أم عوف بن أبي سود بن مالك بن حنظلة وقال أيضا لبني ميثاء\n(نبئت عقبة خصافا توعدني ... يا رب آدر من ميثاء مأفون)\n(لو في طهية أحلام لما اعترضوا ... دون الذي كنت أرميه ويرميني)\nقال ثم من قلت سحمة الأعور النبهاني كانت له امرأة من طيىء ولدت في بني سليط فأعطوه وحملوه علي فسألني فآشتط ولم يكن عندي فحرمته فقال\n(أقول لأصحابي النجاء فإنه ... كفى الذم أن يأتي الضيوف جرير)\n(جرير ابن ذات البظر هل أنت زائل ... لقدرك دون النازلين ستور)\n(وهل يكرم الأضياف كلب لكلبة ... لها عند أطناب البيوت هرير)\n(فلو عند غسان السليطي عرست ... رغا قرن منها وكس عقير)\n(فتى هو خير منك نفسا ووالدا ... عليك إذا كان الجوار يجير)\nقال جرير\n(وجدنا بني نبهان أذناب طيىء ... وللناس أذناب ترى وصدور)\n(تغنى ابن نبهانية طال بظرها ... وباع ابنها عند الهياج قصير)\n(وأعور من نبهان أما نهاره ... فأعمى وأما ليله فبصير)\n(ستأتي بني نبهان مني قصائد ... تطلع من سلمى وهن وعور)\n(ترى قزم المعزى مهور نسائهم ... وفي قزم المعزى لهن مهور)","topic":"نسب جرير وأخباره","topicNo":75,"sp":6,"spl":"هجوه للشعراء","loc":1397},
{"id":"b75-13","bab":"الجزء 8","sec":"هجوه للشعراء — خبره مع راعي الإبل وابنه جندل","page":"ج8 ص19 – ج8 ص32","text":"ال وطلع الصبح فنهض ونهضت قال فأخبرني من كان قاعدا معه أنه قال قاتله الله أعرابيا إنه لجرو هراش\nأخبرني علي بن سليمان قال حدثنا أبو سعيد السكري عن الرياشي عن الأصمعي قال وذكر المغيرة بن حجناء قال حدثني أبي عن أبيه قال كان راعي الإبل يقضي للفرزدق على جرير ويفضله وكان راعي الإبل قد ضخم أمره وكان من شعراء الناس فلما أكثر من ذلك خرج جرير إلى رجال من قومه فقال هلا تعجبون لهذا الرجل الذي يقضي للفرزدق علي وهو يهجو قومه وأنا أمدحهم قال جرير فضربت رأيي فيه ثم خرج جرير ذات يوم\nيمشي ولم يركب دابته وقال والله ما يسرني أن يعلم أحد وكان لراعي الإبل والفرزدق وجلسائهما حلقة بأعلى المربد بالبصرة يجلسون فيها قال فخرجت أتعرض له لألقاه من حيال حيث كنت أراه يمر إذا انصرف من مجلسه وما يسرني أن يعلم أحد حتى إذا هو قد مر على بغلة له وابنه جندل يسير وراءه على مهر له أحوى محذوف الذنب وإنسان يمشي معه يسأله عن بعض السبب فلما استقبلته قلت مرحبا بك يا أبا جندل وضربت بشمالي على معرفة بغلته ثم قلت يا أبا جندل إن قولك يستمع وإنك تفضل الفرزدق علي تفضيلا قبيحا وأنا أمدح قومك وهو يهجوهم وهو ابن عمي ويكفيك من ذاك هين إذا ذكرنا أن تقول كلاهما شاعر كريم ولا تحتمل مني ولا منه لائمة قال فبينا أنا وهو كذاك واقفا علي وما رد علي بذلك شيئا حتى لحق ابنه جندل فرفع كرمانية معه فضرب بها عجز بغلته ثم قال لا أراك واقفا على كلب من بني كليب كأنك تخشى منه شرا أو ترجو منه خيرا وضرب البغلة ضربة فرمحتني رمحة وقعت منها قلنسوتي فوالله لو يعرج علي الراعي لقلت سفيه غوى يعني جندلا ابنه ولكن لا والله ما عاج علي فأخذت قلنسوتي فمسحتها ثم أعدتها على راسي ثم قلت\n(أجندل ما تقول بنو نمير ... إذا ما الأير في است أبيك غابا)\nسمعت الراعي قال لابنه أما والله لقد طرحت قلنسوته طرحة مشؤومة قال جرير ولا والله ما القلنسوة بأغيظ أمره إلي لو كان عاج علي فانصرف جرير غضبان حتى إذا صلى العشاء بمنزله في علية له قال ارفعوا إلي\nباطية من نبيذ وأسرجوا لي فأسرجوا له وأتوه بباطية من نبيذ قال فجعل يهمهم فسمعت صوته عجوز في الدار فاطلعت في الدرجة حتى نظرت إليه فإذا هو يحبو على الفراش عريانا لما هو فيه فانحدرت فقالت ضيفكم مجنون رأيت منه كذا وكذا فقالوا لها اذهبي لطيتك نحن أعلم به وبما يمارس فما زال كذلك حتى كان السحر ثم إذا هو يكبر قد قالها ثمانين بيتا في بني نمير فلما ختمها بقوله\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\nبر ثم قال أخزيته ورب الكعبة ثم أصبح حتى إذا عرف أن الناس قد جلسوا في مجالسهم بالمربد وكان يعرف مجلسه ومجلس الفرزدق دعا بدهن فادهن وكف رأسه وكان حسن الشعر ثم قال يا غلام أسرج لي فأسرج له حصانا ثم قصد مجلسهم حتى إذا كان بموضع السلام قال يا غلام ولم يسلم قل لعبيد ابعثك نسوتك تكسبهن المال بالعراق أما والذي نفس جرير بيده لترجعن إليهن بمير يسوءهن ولا يسرهن ثم اندفع فيها فأنشدها قال فنكس الفرزدق وراعي الإبل وأرم القوم حتى إذا فرغ منها سار وثبت راعي الإبل ساعة ثم ركب بغلته بشر وعر وخلى المجلس حتى ترقى إلى منزله الذي ينزله قال لأصحابه ركابكم فليس لكم ها هنا مقام فضحكم والله جرير فقال له بعض القوم ذاك شؤمك وشؤم ابنك قال فما كان إلا ترحلهم قال فسرنا إلى أهلنا سيرا ما ساره أحد وهم بالشريف\nوهو أعلى دار بني نمير فيحلق بالله راعي الإبل إنا وجدنا في أهلنا\n(فغض الطرف إنك من نمير ... )\nوأقسم بالله ما بلغه إنسي قط وإن لجرير لأشياعا من الجن فتشاءمت به بنو نمير وسبوه وابنه فهم يتشاءمون به إلى الآن","topic":"نسب جرير وأخباره","topicNo":75,"sp":7,"spl":"هجوه للشعراء — خبره مع راعي الإبل وابنه جندل","loc":1398,"partialRef":{"sid":"b75-2","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b75-14","bab":"الجزء 8","sec":"قصيدته في هجو الراعي","page":"ج8 ص35","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي عن أبيه قال حدثني مولى لبني كليب بن يربوع كان يبيع الرطب بالبصرة أنسيت اسمه قال كنت أجمع شعر جرير وأشتهي أن أحفظه وأرويه فجاءني ليلة فقال إن راعي الإبل النميري قد هجاني وإني آتيك الليلة فأعد لي شواء رشراشا ونبيذا مخفسا فأعددت له ذلك فلما أعتم جاءني فقال هلم عشاءك فأتيته به فأكل ثم قال هلم نبيذك فأتيته به فشرب أقداحا ثم قال هات دواة وكتفا فأتيته بهما فجعل يملي علي قوله\n(أقلي اللوم عاذل والعتابا ... وقولي إن أصبت لقد أصابا)\nتى بلغ إلى قوله\n(فغض الطرف إنك من نمير ... )\nجعل يردده ولا يزيد عليه حتى حملتني عيني فضربت بذقني صدري نائما فإذا به قد وثب حتى أصاب السقف رأسه وكبر ثم صاح أخزيته والله اكتب\n(فلا كعبا بلغت ولا كلابا ... )\nضضته وقدمت إخوته عليه والله لا يفلح بعدها أبدا فكان والله كما قال ما افلح هو ولا نميري بعدها أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال اقبل راكب من اليمامة فمر بالفرزدق وهو جالس في المربد فقال له من اين أقبلت قال من اليمامة فقال هل رأيت ابن المراغة قال نعم قال فأي شيء أحدث بعدي فأنشده\n(هاج الهوى لفؤادك المهتاج ... )\nقال الفرزدق\n(فانظر بتوضح باكر الأحداج ... )\nفأنشده الرجل\n(هذا هوى شغف الفؤاد مبرح ... )\nقال الفرزدق\n(ونوى تقاذف غير ذات خلاج ... )\nأنشده الرجل\n(إن الغراب بما كرهت لمولع ... )\nفقال الفرزدق\n(بنوى الأحبة دائم التشحاج ... )\nقال الرجل هكذا والله قال أفسمعتها من غيري قال لا ولكن هكذا ينبغي أن يقال أوما علمت أن شيطاننا واحد ثم قال أمدح بها الحجاج قال نعم قال إياه أراد أخبرني محمد بن خلف وكيع قال حدثنا محمد بن إسحاق بن عبد الرحمن قال حدثني إسحاق بن إبراهيم الموصلي قال حدثني أبو عبيدة قال التقى جرير والفرزدق بمنى وهما حاجان فقال الفرزدق لجرير\n(فإنك لاق بالمنازل من منى ... فخارا فخبرني بمن أنت فاخر)\nقال له جرير بلبيك اللهم لبيك قال إسحاق فكان أصحابنا يستحسنون هذا الجواب من جرير ويعجبون منه أخبرني أبو خليفة عن محمد بن سلام وأخبرني وكيع عن محمد بن إسماعيل عن ابن سلام قال حدثنا أبو الخطاب عن أبيه عن حجناء بن جرير قال قلت لأبي يا ابت ما هجوت قوما قط إلا أفسدتهم سوى التيم فقال\nإني لم أجد حسبا أضعه ولا بناء أهدمه قال ابن سلام أخبرني أبو قيس عن عكرمة بن جرير قال قلت لأبي يا أبت من أشعر الناس فقال ألجاهلية تريد أم الإسلام قلت أخبرني عن الجاهلية قال شاعر الجاهلية زهير قلت فالإسلام قال نبعة الشعر الفرزدق قلت فالأخطل قال يجيد صفة الملوك ويصيب نعت الخمر قلت فما تركت لنفسك قال دعني فإني نحرت الشعر نحرا (","topic":"نسب جرير وأخباره","topicNo":75,"sp":8,"spl":"قصيدته في هجو الراعي — الفرزدق توقع سلفا ما هجاه به جرير","loc":1399,"partialRef":{"sid":"b75-2","gi":5,"vi":0,"side":1},"partial":1},
{"id":"b75-15","bab":"الجزء 8","sec":"الفرزدق توقع سلفا ما هجاه به جرير","page":"ج8 ص38","text":"خبرني هاشم بن محمد قال حدثني الحسن بن عليل قال حدثني محمد بن عبد الله العبدي عن عمارة بن عقيل عن جده قال وقف الفرزدق على أبي بمربد البصرة وهو ينشد قصيدته التي هجا بها الراعي فلما بلغ إلى قوله\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\nأقبل الفرزدق على روايته فقال غضه والله فلا يجيبه أبدا ولا يفلح بعدها فلما بلغ إلى قوله\n(بها برص بجانب إسكتيها ... )\nضع الفرزدق يده على فيه وغطى عنفقته فقال أبي\n(كعنفقة الفرزدق حين شابا ... )\nفانصرف الفرزدق وهو يقول اللهم أخزه والله لقد علمت حين بدأ بالبيت أنه لا يقول غير هذا ولكن طمعت ألا يأبه فغطيت وجهي فما أغناني ذلك شيئا قال العنزي حدثني مسعود بن بشر عن أبي عبيدة قال قال يونس ما أرى جريرا قال هذا المصراع إلا حين غطى الفرزدق عنفقته فإنه نبهه عليه بتغطيته إياها","topic":"نسب جرير وأخباره","topicNo":75,"sp":8,"spl":"قصيدته في هجو الراعي — الفرزدق توقع سلفا ما هجاه به جرير","loc":1400,"partial":1},
{"id":"b75-16","bab":"الجزء 8","sec":"الفرزدق يعترف بمجاراة جرير له","page":"ج8 ص39","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا المدائني عن أبي بكر الهذلي قال قال رجل من بني دارم للفرزدق وهو بالبصرة يا ابا فراس هل تعلم اليوم أحدا يرمي معك فقال لا والله ما أعرف نابحا إلا وقد استكان ولا ناهشا إلا وقد انجحر إلا القائل\n(فإن لم أجد في القرب والبعد حاجتي ... تشأمت أو حولت وجهي يمانيا)\n(فردي جمال الحي ثم تحملي ... فما لك فيهم من مقام ولا ليا)\n(فإني لمغرور أعلل بالمنى ... ليالي أرجو أن ما لك ما ليا)\n(وقائلة والدمع يحدر كحلها ... ابعد جرير تكرمون المواليا)\n(بأي نجاد تحمل السيف بعدما ... قطعت القوى من محمل كان باقيا)\n(بأي سنان تطعن القرم بعدما ... نزعت سنانا من قناتك ماضيا)\n(لساني وسيفي صارمان كلاهما ... وللسيف أشوى وقعة من لسانيا)\nقال وهذا الشعر لجرير أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد عن عمارة بن عقيل عن أبيه قال قال جرير وفدت إلى يزيد بن معاوية وأنا شاب يومئذ فاستؤذن لي عليه في جملة الشعراء فخرج الحاجب إلي وقال يقول لك أمير المؤمنين إنه لا يصل إلينا شاعر لا نعرفه ولا نسمع بشيء من شعره وما سمعنا لك بشيء فنأذن لك على بصيرة فقلت له تقول لأمير المؤمنين أنا القائل\n(وإني لعف الفقر مشترك الغنى ... سريع إذا لم أرض داري انتقاليا)\n(جريء الجنان لا أهاب من الردى ... إذا ما جعلت السيف قبض بنانيا)\n(وليس لسيفي في العظام بقية ... وللسيف أشوى وقعة من لسانيا)\nفدخل الحاجب عليه فأنشده الأبيات ثم خرج إلي وأذن لي فدخلت وأنشدته وأخذت الجائزة مع الشعراء فكانت أول جائزة أخذتها من خليفة وقال لي لقد فارق أبي الدنيا وما يظن أبياتك التي توسلت بها إلي إلا لي (","topic":"نسب جرير وأخباره","topicNo":75,"sp":9,"spl":"الفرزدق يعترف بمجاراة جرير له — حماد الرواية يوازن بينه وبين الفرزدق","loc":1401},
{"id":"b75-17","bab":"الجزء 8","sec":"حماد الرواية يوازن بينه وبين الفرزدق","page":"ج8 ص40","text":"خبرني عمي قال حدثني الكراني قال حدثنا العمري عن الهيثم بن عدي عن حماد الراوية قال أتيت الفرزدق فأنشدني ثم قال لي هل أتيت الكلب جريرا قلت نعم قال فأنا أشعر أو هو فقلت أنت في بعض الأمر وهو في بعض فقال لم تناصحني فقلت هو أشعر إذا أرخى من خناقه وأنت أشعر منه إذا خفت أو رجوت فقال وهل الشعر إلا في الخوف والرجاء وعند الخير والشر\nأخبرني عمي قال حدثني أحمد بن الحارث قال حدثنا المدائني عن يحيى بن عنبسة القرشي وعوانة بن الحكم أن جريرا والفرزدق اجتمعا عند بشر بن مروان فقال لهما بشر إنكما قد تقارضتما الأشعار وتطالبتما الآثار وتقاولتما الفخر وتهاجيتما فأما الهجاء فليست بي إليه حاجة فجددا بين يدي فخرا ودعاني مما مضى فقال الفرزدق\n(نحن السنام والمناسم غيرنا ... فمن ذا يساوي بالسنام المناسما)\nقال جرير\n(على موضع الأستاه أنتم زعمتم ... وكل سنام تابع للغلاصم)\nقال الفرزدق\n(على محرث للفرث أنتم زعمتم ... ألا إن فوق الغلصمات الجماجما)\nقال جرير\n(وأنبأتمونا أنكم هام قومكم ... ولا هام إلا تابع للخراطم)\nقال الفرزدق\n(فنحن الزمام القائد المقتدى به ... من الناس ما زلنا ولسنا لهازما)\nقال جرير\n(فنحن بني زيد قطعنا زمامها ... فتاهت كسار طائش الرأس عارم)\nفقال بشر غلبته يا جرير بقطعك الزمام وذهابك بالناقة وأحسن الجائزة لهما وفضل جريرا قال المدائني وحدثني عوانة بن الحكم قال جاء جرير إلى باب سكينة بنت الحسين عليه السلام يستأذن عليها فلم تاذن له وخرجت إليه جارية لها فقالت تقول لك سيدتي أنت القائل\n(طرقتك صائدة القلوب وليس ذا ... حين الزيارة فارجعي بسلام)\nال نعم قالت فألا أخذت بيدها فرحبت بها وأدنيت مجلسها وقلت لها ما يقال لمثلها أنت عفيف وفيك ضعف فخذ هذين الألفي الدرهم فالحق بأهلك","topic":"نسب جرير وأخباره","topicNo":75,"sp":9,"spl":"الفرزدق يعترف بمجاراة جرير له — حماد الرواية يوازن بينه وبين الفرزدق","loc":1402},
{"id":"b75-18","bab":"الجزء 8","sec":"سكينة بنت الحسين فضلته على الفرزدق","page":"ج8 ص42","text":"قال المدائني في خبره هذا وحدثني أبو يعقوب الثقفي عن الشعبي أن الفرزدق خرج حاجا فلما قضى حجه عدل إلى المدينة فدخل إلى سكينة بنت الحسين عليهما السلام فسلم فقالت له يا فرزدق من أشعر الناس قال أنا قالت كذبت أشعر منك الذي يقول\n(بنفسي من تجنبه عزيز ... علي ومن زيارته لمام)\n(ومن أمسي وأصبح لا أراه ... ويطرقني إذا هجع النيام)\nقال والله لو أذنت لي لأسمعتك أحسن منه قالت أقيموه فأخرج\nثم عاد إليها من الغد فدخل عليها فقالت يا فرزدق من أشعر الناس قال أنا قالت كذبت صاحبك جرير أشعر منك حيث يقول\n(لولا الحياء لعادني استعبار ... ولزرت قبرك والحبيب يزار)\n(كانت إذا هجر الضجيع فراشها ... كتم الحديث وعفت الأسرار)\n(لا يلبث القرناء أن يتفرقوا ... ليل يكر عليهم ونهار)\nقال والله لئن أذنت لي لأسمعنك أحسن منه فأمرت به فأخرج ثم عاد إليها في اليوم الثالث وحولها مولدات لها كأنهن التماثيل فنظر الفرزدق إلى واحدة منهن فأعجب بها وبهت ينظر إليها فقالت له سكينة يا فرزدق من أشعر الناس قال أنا قالت كذبت صاحبك أشعر منك حيث يقول\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\n(يصرعن ذا اللب حتى لا حراك به ... وهن أضعف خلق الله اركانا)\n(أتبعتهم مقلة إنسانها غرق ... هل ما ترى تارك للعين إنسانا)\nقال والله لئن تركتني لأسمعنك أحسن منه فأمرت بإخراجه فالتفت إليها وقال يا بنت رسول الله إن لي عليك حقا عظيما قالت وما هو قال ضربت إليك آباط الإبل من مكة إرادة التسليم عليك فكان جزائي من ذلك تكذيبي وطردي وتفضيل جرير علي ومنعك إياي أن أنشدك شيئا من شعري وبي ما قد عيل منه صبري وهذه\nالمنايا تغدوا وتروح ولعلي لا أفارق المدينة حتى أموت فإذا أنا مت فمري بي أن أدرج في كفني وأدفن في حر هذه يعني الجارية التي أعجبته فضحكت سكينة وأمرت له بالجارية فخرج بها آخذا بريطتها وأمرت الجواري فدفعن في أقفيتهما ونادته يا فرزدق احتفظ بها وأحسن صحبتها فإني آثرتك بها على نفسي قال المدائني في خبره هذا وحدثني أبو عمران بن عبدالملك بن عمير عن أبيه وحدثنيه عوانة أيضا قالا صنع عبدالملك بن مروان طعاما فأكثر وأطاب ودعا إليه الناس فأكلوا فقال بعضهم ما أطيب هذا الطعام ما نرى أن أحدا رأى أكثر منه ولا أكل أطيب منه فقال أعرابي من ناحية القوم أما أكثر فلا وأما أطيب فقد والله أكلت أطيب منه فطفقوا يضحكون من قوله فأشار إليه عبدالملك فأدني منه فقال ما أنت بمحق فيما تقول إلا أن تخبرني بما يبين به صدقك فقال نعم يا أمير المؤمنين بينا أنا بهجر في برث أحمر في أقصى حجر إذ توفي أبي وترك كلا وعيالا وكان له نخل فكانت فيه نخلة لم ينظر الناظرون إلى مثلها كأن تمرها أخفاف الرباع لم ير تمر قط أغلظ ولا أصلب ولا أصغر نوى ولا أحلى حلاوة منه وكانت تطرقها أتان وحشية قد ألفتها تأوي الليل تحتها\nفكانت تثبت رجليها في أصلها وترفع يديها وتعطو بفيها فلا تترك فيها إلا النبيذ والمتفرق فأعظمني ذلك ووقع مني كل موقع فانطلقت بقوسي وأسهمي وأنا أظن أني أرجع من ساعتي فمكثت يوما وليلة لا اراها حتى إذا كان السحر أقبلت فتهيأت لها فرشقتها فأصبتها وأجهزت عليها ثم عمدت إلى سرتها فاقتددتها ثم عمدت إلى حطب جزل فجمعته إلى رضف وعمدت إلى زندي فقدحت وأضرمت النار في ذلك الحطب وألقيت سرتها فيه وأدركني نوم الشباب فلم يوقظني إلا حر الشمس في ظهري فانطلقت إليها فكشفتها وألقيت ما عليها من قذى وسواد ورماد ثم قلبت منها مثل الملاءة البيضاء فألقيت عليها من رطب تلك النخلة المجزعة والمنصفة فسمعت لها أطيطا كتداعي عامر وغطفان ثم أقبلت أتناول الشحمة واللحمة فأضعها بين التمرتين وأهوي إلى فمي فبما أحلف إني ما أكلت طعاما مثله قط فقال له عبد الملك لقد أكلت طعاما طيبا فمن أنت قال أنا رجل جانبتني عنعنة تميم وأسد وكشكشة ربيعة وحوشي أهل اليمن وإن كنت منهم فقال من ايهم أنت قال من أخوالك من عذرة قال أولئك فصحاء الناس فهل لك علم بالشعر قال سلني عما بدا لك يا أمير المؤمنين قال أي بيت قالته العرب أمدح قال قول جرير\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nال وكان جرير في القوم فرفع رأسه وتطاول لها ثم قال فأي بيت قالته العرب أفخر قال قول جرير","topic":"نسب جرير وأخباره","topicNo":75,"sp":10,"spl":"سكينة بنت الحسين فضلته على الفرزدق","loc":1403},
{"id":"b75-19","bab":"الجزء 8","sec":"سكينة بنت الحسين فضلته على الفرزدق","page":"ج8 ص42","text":"(إذا غضبت عليك بنو تميم ... حسبت الناس كلهم غضابا)\nال فتحرك لها جرير ثم قال له فأي بيت أهجى قال قول جرير\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\nال فاستشرف لها جرير قال فأي بيت أغزل قال قول جرير\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\nقال فاهتز جرير وطرب ثم قال له فأي بيت قالته العرب أحسن تشبيها قال قول جرير\n(سرى نحوهم ليل كأن نجومه ... قناديل فيهن الذبال المفتل)\nقال جرير جائزتي للعذري يا أمير المؤمنين فقال له عبد الملك وله مثلها من بيت المال ولك جائزتك يا جرير لا تنتقص منها شيئا وكانت جائزة جرير أربعة آلاف درهم وتوابعها من الحملان والكسوة فخرج العذري وفي يده اليمنى ثمانية آلاف درهم وفي اليسرى رزمة ثياب أخبرنا هاشم بن محمد الخزاعي قال حدثنا عمر بن شبة قال حدثنا المدائني عن أبي عبد الرحمن عن عبد الله بن عياش الهمداني قال بينا المهلب ذات يوم ( أو ليلة\nبفارس وهو يقاتل الأزارقة إذ سمع في عسكره جلبة وصياحا فقال ما هذا قالوا جماعة من العرب تحاكموا إليك\nفي شيء فأذن لهم فقالوا إنا اختلفنا في جرير والفرزدق فكل فريق منا يزعم أن أحدهما أشعر من الآخر وقد رضينا بحكم الأمير فقال كأنكم أردتم أن تعرضوني لهذين الكلبين فيمزقا جلدتي لا أحكم بينهما ولكني ادلكم على من يهون عليه سبال جرير وسبال الفرزدق عليكم بالأزارقة فإنهم قوم عرب يبصرون بالشعر ويقولون فيه بالحق فلما كان الغد خرج عبيدة بن هلال اليشكري ودعا إلى المبارزة فخرج إليه رجل من عسكر المهلب كان لقطري صديقا فقال له يا عبيدة سألتك الله إلا أخبرتني عن شيء أسألك عنه قال سل قال أوتخبرني قال نعم إن كنت أعلمه قال أجرير أشعر أم الفرزدق قال قبحك الله أتركت القرآن والفقه وسألتني عن الشعر قال إنا تشاجرنا في ذلك ورضينا بك فقال من الذي يقول\n(وطوى الطراد مع القياد بطونها ... طي التجار بحضرموت برودا)\nقال جرير قال هذا أشعر الرجلين (","topic":"نسب جرير وأخباره","topicNo":75,"sp":11,"spl":"سكينة بنت الحسين فضلته على الفرزدق","loc":1404},
{"id":"b75-20","bab":"الجزء 8","sec":"لم ينسب ولم يرجز","page":"ج8 ص47","text":"خبرني هاشم بن محمد قال حدثنا الرياشي عن العتيبي قال قال جرير ما عشقت قط ولو عشقت لنسبت نسيبا تسمعه العجوز فتبكي على ما فاتها من شبابها وإني لأرى من الرجز أمثال آثار الخيل في الثرى ولولا أني أخاف أن يستفزعني لأكثرت منه أخبرني حبيب بن نصر المهلبي وعمي قالا حدثنا ابن الأعرابي\nقال حدثنا عبد الرحمن بن سعيد بن بيهس بن صهيب الجرمي عن عامر بن شبل الجرمي قال قدم جرير على عبدالعزيز بن الوليد بن عبد الملك وهو نازل بدير مران فكنا نغدوا إليه بكرا فيخرج إلينا ويجلس في برنس خز له لا يكلمنا كلمة حتى يجيء طباخ عبد العزيز إليه بقدح من طلاء مسخن يفور وبكتلة من سمن كأنها هامة رجل فيخوضها فيه ثم يدفعه إليه فيأتي عليه ويقبل علينا ويحدثنا في كل فن وينشدنا لنفسه ولغيره حتى يحضر غداء عبد العزيز فنقوم إليه جميعا وكان يختم مجلسه بالتسبيح فيطيل فقال له رجل ما يغني عنك هذا التسبيح مع قذفك للمحصنات فتبسم وقال يابن أخي ( خلطوا عملا صالحا وآخر سيئا عسى الله أن يتوب عليهم\nإنهم والله يابن أخي يبدأوني ثم لا أحلم أخبرني عمي قال حدثنا ابن أبي سعد قال حدثني إبراهيم بن عبد الرحمن بن سعيد بن جعفر بن يوسف بن محمد بن موسى قال حدثني الأخفش عن أبي محذورة الوراق عن أبي مالك الراوية قال سمعت الفرزدق يقول وأخبرني بهذا الخبر محمد بن خلف بن المرزبان قال حدثني إبراهيم بن محمد الطائفي قال حدثني محمد بن مسعدة الأخفش عن أبي محذورة الوراق عن أبي مالك الراوية قال\nسمعت الفرزدق يقول أبق غلامان لرجل منا يقال له الخضر فحدثني قال خرجت في طلبهما وأنا على ناقة لي عيساء كوماء أريد اليمامة فلما صرت في ماء لبني حنيفة يقال له الصرصران ارتفعت سحابة فرعدت وبرقت وأرخت عزاليها فعدلت إلى بعض ديارهم وسألت القرى فأجابوا فدخلت دارا لهم وأنخت الناقة وجلست تحت ظلة لهم من جريد النخل وفي الدار جويرية لهم سوداء إذ دخلت جارية كأنها سبيكة فضة وكأن عينيها كوكبان دريان فسألت الجارية لمن هذه العيساء تعني ناقتي فقالت لضيفكم هذا فعدلت إلي فقالت السلام عليكم فرددت عليها السلام فقالت لي ممن الرجل فقلت من بني حنظلة فقالت من أيهم فقلت من بني نهشل فتبسمت وقالت أنت إذا ممن عناه الفرزدق بقوله\n(إن الذي سمك السماء بنى لنا ... بيتا دعائمه أعز وأطول)\n(بيتا بناه لنا المليك وما بنى ... ملك السماء فإنه لا ينقل)\n(بيتا زرارة محتب بفنائه ... ومجاشع وأبو الفوارس نهشل)\nال فقلت نعم جعلت فداك وأعجبني ما سمعت منها فضحكت وقالت فإن ابن الخطفي قد هدم عليكم بيتكم هذا الذي فخرتم به حيث يقول\n(أخزى الذي رفع السماء مجاشعا ... وبنى بناءك بالحضيض الأسفل)\n(بيتا يحمم قينكم بفنائه ... دنسا مقاعده خبيث المدخل)\nقال فوجمت فلما رأت ذلك في وجهي قالت لا عليك فإن الناس يقال فيهم ويقولون ثم قالت اين تؤم قلت اليمامة فتنفست الصعداء ثم قالت ها هي تلك أمامك ثم أنشأت تقول\n(تذكرني بلادا خير أهلي ... بها أهل المروءة والكرامه)\n(ألا فسقى الإله أجش صوبا ... يسح بدره بلد اليمامه)\n(وحيا بالسلام أبا نجيد ... فأهل للتحية والسلامه)\nقال فأنست بها وقلت لها أذات خدن أم ذات بعل فأنشأت تقول\n(إذا رقد النيام فإن عمرا ... تؤرقه الهموم إلى الصباح)\n(تقطع قلبه الذكرى وقلبي ... فلا هو بالخلي ولا بصاح)\n(سقى الله اليمامة دار قوم ... بها عمرو يحن إلى الرواح)\nفقلت لها من عمرو هذا فأنشأت تقول\n(سألت ولو علمت كففت عنه ... ومن لك بالجواب سوى الخبير)\n(فإن تك ذا قبول إن عمرا ... هو القمر المضيء المستنير)\n(وما لي بالتبعل مستراح ... ولو رد التبعل لي أسيري)\nال ثم سكتت سكتة كأنها تتسمع إلى كلام ثم تهافتت وأنشأت تقول\n(يخيل لي هيا عمرو بن كعب ... كأنك قد حملت على سرير)\n(يسير بك الهوينى القوم لما ... رماك الحب بالعلق العسير)\n(فإن تك هكذا يا عمرو إني ... مبكرة عليك إلى القبور)\nم شهقت شهقة فخرت ميتة فقلت لهم من هذه فقالوا هذه عقيلة بنت الضحاك بن عمرو بن محرق بن النعمان بن المنذر بن ماء السماء فقلت لهم فمن عمرو هذا قالوا ابن عمها عمرو بن كعب بن محرق بن النعمان بن المنذر فارتحلت من عندهم فلما دخلت اليمامة سألت عن عمرو هذا فإذا هو قد دفن في ذلك الوقت الذي قالت فيه ما قالت","topic":"نسب جرير وأخباره","topicNo":75,"sp":12,"spl":"لم ينسب ولم يرجز","loc":1405},
{"id":"b75-21","bab":"الجزء 8","sec":"خبره مع عمر بن عبد العزيز","page":"ج8 ص51","text":"أخبرني محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا محمد بن الحكم وأخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا أبو الهيثم بدر بن سعيد العطار قال حدثنا عبد العزيز بن عمر بن عبد العزيز قال لما استخلف عمر بن عبد العزيز جاءه الشعراء فجعلوا لا يصلون إليه فجاء عون بن عبد الله بن عتبة بن مسعود وعليه عمامة قد أرخى طرفيها فدخل فصاح به جرير\n(يأيها القارىء المرخي عمامته ... هذا زمانك إني قد مضى زمني)\n(أبلغ خليفتنا إن كنت لاقيه ... أني لدى الباب كالمصفود في قرن)\nال فدخل على عمر فاستأذن له فأدخله عليه وقد كان هيأ له شعرا فلما دخل عليه غيره وقال\n(إنا لنرجو إذا ما الغيث أخلفنا ... من الخليفة ما نرجوا من المطر)\n(نال الخلافة إذ كانت له قدرا ... كما أتى ربه موسى على قدر)\n(أأذكر الجهد والبلوى التي نزلت ... أم تكتفي بالذي بلغت من خبري)\n(ما زلت بعدك في دار تعرقني ... قد طال بعدك إصعادي ومنحدري)\n(لا ينفع الحاضر المجهود بادينا ... ولا يجود لنا باد على حضر)\n(كم بالمواسم من شعثاء أرملة ... ومن يتيم ضعيف الصوت والبصر)\n(يدعوك دعوة ملهوف كأن به ... خبلا من الجن أو مسا من النشر)\n(ممن يعدك نكفي فقد والده ... كالفرخ في العش لم ينهض ولم يطر)\nال فبكى عمر ثم قال يابن الخطفي أمن أبناء المهاجرين أنت فنعرف لك حقهم أم من ابناء الأنصار فيجب لك ما يجب لهم أم من فقراء المسلمين فنأمر صاحب صدقات قومك فيصلك بمثل ما يصل به قومك فقال يا أمير المؤمنين ما أنا بواحد من هؤلاء وإني لمن أكثر قومي مالا وأحسنهم حالا ولكني اسألك ما عودتنيه الخلفاء أربعة آلاف درهم وما يتبعها من كسوة وحملان فقال له عمر كل امرىء يلقى فعله وأما أنا فما أرى لك في مال الله حقا ولكن انتظر يخرج فانظر ما يكفي عيالي سنة منه فأدخره لهم ثم إن فضل فضل صرفناه إليك فقال جرير لا بل يوفر أمير المؤمنين ويحمد وأخرج راضيا قال فذلك أحب إلي فخرج فلما ولى قال عمر إن شر هذا ليتقى ردوه إلي فردوه فقال إن عندي أربعين دينارا وخلعتين إذا غسلت إحداهما لبست الأخرى وأنا مقاسمك ذلك على أن الله جل وعز يعلم أن عمر أحوج إلى ذلك منك فقال له قد وفرك الله يا أمير المؤمنين وأنا والله راض قال أما وقد حلفت فإن ما وفرته علي ولم تضيق به معيشتنا آثر في نفسي من المدح فامض مصاحبا فخرج فقال له أصحابه وفيهم الفرزدق\nما صنع بك أمير المؤمنين يا أبا حزرة قال خرجت من عند رجل يقرب الفقراء ويباعد الشعراء وأنا مع ذلك عنه راض ثم وضع رجله في غرز راحلته وأتى قومه فقالوا له ما صنع بك أمير المؤمنين أبا حزرة فقال\n(تركت لكم بالشام حبل جماعة ... أمين القوى مستحصد العقد باقيا)\n(وجدت رقى الشيطان لا تستفزه ... وقد كان شيطاني من الجن راقيا)\nذه رواية عمر بن شبة وأما اليزيدي فإنه قال في خبره فقال له جرير يا أمير المؤمنين فإني ابن سبيل قال لك ما لأبناء السبيل زادك ونفقة تبلغك وتبدل راحلتك إن لم تحملك فألح عليه فقالت له بنو أمية يا أبا حزرة مهلا عن أمير المؤمنين ونحن نرضيك من أموالنا عنه فخرج وجمعت له بنو أمية مالا عظيما فما خرج من عند خليفة بأكثر مما خرج من عند عمر أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن أبي عبيدة قال رأت أم جرير وهي حامل به كأنها ولدت حبلا من شعر أسود فلما سقط منها جعل ينزو فيقع في عنق هذا فيخنقه حتى فعل ذلك برجال كثير فانتبهت فزعة فأولت الرؤيا فقيل لها تلدين غلاما شاعرا ذا شر وشدة شكيمة وبلاء على الناس فلما ولدته سمته جريرا باسم الحبل الذي رأت أنه خرج منها قال والجرير الحبل قال إسحاق وقال الأصمعي حدثني بلال بن جرير أو حدثت عنه أن رجلا قال لجرير من أشعر الناس قال له قم حتى أعرفك الجواب فأخذ بيده وجاء به إلى أبيه عطية وقد أخذ عنزا له فاعتقلها وجعل يمص ضرعها","topic":"نسب جرير وأخباره","topicNo":75,"sp":13,"spl":"خبره مع عمر بن عبد العزيز","loc":1406},
{"id":"b75-22","bab":"الجزء 8","sec":"خبره مع عمر بن عبد العزيز","page":"ج8 ص51","text":"فصاح به اخرج يا أبت فخرج شيخ دميم رث الهيئة وقد سال لبن العنز على لحيته فقال ألا ترى هذا قال نعم قال أوتعرفه قال لا قال هذا أبي أفتدري لم كان يشرب من ضرع العنز قلت لا قال مخافة أن يسمع صوت الحلب فيطلب منه لبن ثم قال أشعر الناس من فاخر بمثل هذا الأب ثمانين شاعرا وقارعهم به فغلبهم جميعا حدثني عمي قال حدثنا عبدالله بن أبي سعد قال حدثني عبدالله بن محمد بن موسى مولى بني هاشم قال حدثني عمارة بن عقيل عن المغيرة بن حجناء عن أبيه قال ولد جرير لسبعة اشهر فكان الفرزدق يعيره ذلك وفيه يقول\n(وأنت أبن صغرى لم تتم شهورها ... )\nقال وولد عطية جريرا وأمه أم قيس بنت معيد من بني كليب وعمرا وأبا الورد فأما ابو الورد فكان يحسد جريرا فذهبت لجرير إبل فشمت به أبو الورد فقال له جرير\n(أبا الورد أبقى الله منها بقية ... كفت كل لوام خذول وحاسد)\nأما عمرو فكان أكبر من جرير وكان يقارضه الشعر فقال له جرير\n(وعمرو قد كرهت عتاب عمرو ... وقد كثر المعاتب والذنوب)\n(وقد صدعت صخرة من رماكم ... وقد يرمى بي الحجر الصليب)\n(وقد قطع الحديد فلا تماروا ... فرند لا يفل ولا يذوب)","topic":"نسب جرير وأخباره","topicNo":75,"sp":14,"spl":"خبره مع عمر بن عبد العزيز","loc":1407,"partial":1},
{"id":"b75-23","bab":"الجزء 8","sec":"يزيد بن معاوية يعاتب أباه بشعر جرير وينسبه إلى نفسه","page":"ج8 ص54","text":"قال وأول شعر قاله جرير في زمن معاوية قاله لابنه\n(فردي جمال البين ثم تحملي ... فما لك فيهم من مقام ولا ليا)\n(لقد قادني الجيران يوما وقدتهم ... وفارقت حتى ما تصب جماليا)\n(وإني لمغرور أعلل بالمنى ... ليالي أرجو أن مالك ماليا)\n(بأي سنان تطعن القرم بعدما ... نزعت سنانا من قناتك ماضيا)\n(بأي نجاد تحمل السيف بعدما ... قطعت القوى من محمل كان باقيا)\nال وكان يزيد بن معاوية عاتب أباه بهذه الأبيات ونسبها إلى نفسه لأن جريرا لم يكن شعره شهر حينئذ فقدم جرير على يزيد في خلافته فاستؤذن له مع الشعراء فأمر يزيد ألا يدخل عليه شاعر إلا من عرف شعره فقال جرير قولوا له أنا القائل\n(فردي جمال الحي ثم تحملي ... فما لك فيهم من مقام ولا ليا)\nفأمر بإدخاله فلما أنشده قال يزيد لقد فارق أبي الدنيا وما يحسب إلا أني قائلها وأمر له بجائزة وكسوة أخبرني أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح قال قال ابو عبيدة قال أبو عمرو استعار جرير من أبيه فحلا يطرقه في إبله فلما استغنى عنه جاءه أبوه في بت خلق يسترده فدفعه إليه وقال يا ابت هذا ترد إلى عطية تعتل يعرض بقول الفرزدق فيه\n(ليس الكرام بناحليك اباهم ... حتى ترد إلى عطية تعتل)\nأخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي وعمر بن شبة قالا حدثنا الأصمعي قال أخبرنا أبو عمرو بن العلاء قال جلس جرير يملي على رجل قوله\n(ودع أمامة حان منك رحيل ... إن الوداع لمن تحب قليل)\nفمروا عليه بجنازة فقطع الإنشاد وجعل يبكي ثم قال شيبتني هذه الجنازة قال أبو عمرو فقلت له فعلام تقذف المحصنات منذ كذا وكذا فقال إنهم يبدأونني ثم لا أعفو أخبرني عمي قال حدثنا يزيد بن محمد المهلبي قال حدثنا عبد الله بن المعذل قال كان أبي وجماعة من علمائنا يقولون إنما فضل جرير لمقاومته الفرزدق وأفضل شعر قاله جرير\n(حي الهدملة من ذات المواعيس ... )\nخبرني ابو خليفة قال حدثنا محمد بن سلام قال حدثنا ابو الغراف قال أتى الفرزدق مجلس بني الهجيم في مسجدهم فأنشدهم وبلغ ذلك جريرا فأتاهم من الغد لينشدهم كما أنشدهم الفرزدق فقال له شيخ منهم يا هذا اتق الله فإن هذا المسجد إنما بني لذكر الله والصلاة فقال جرير أقررتم للفرزدق ومنعتموني وخرج مغضبا وهو يقول\n(إن الهجيم قبيلة ملعونة ... حص اللحى متشابهو الألوان)\n(هم يتركون بنيهم وبناتهم ... صعر الأنوف لريح كل دخان)\n(لو يسمعون بأكلة أو شربة ... بعمان أصبح جمعهم بعمان)\nال وخفة اللحى في بني هجيم ظاهرة وقيل لرجل منهم ما بالكم يا بني الهجيم حص اللحى قال إن الفحل واحد أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني محمد بن عبد الله بن آدم قال سمعت عمارة بن عقيل يحدث عن أبيه عن جده قال قال عبد الملك أو الوليد ابنه لجرير من اشعر الناس قال فقال ابن العشرين قال فما رأيك في ابني أبي سلمى قال كان شعرهما نيرا يا أمير المؤمنين قال فما تقول في امرىء القيس قال اتخذ الخبيث الشعر نعلين وأقسم بالله لو أدركته لرفعت ذلاذله قال فما تقول في ذي الرمة قال قدر من ظريف الشعر وغريبه وحسنه على ما لم يقدر عليه أحد قال فما تقول في الأخطل قال ما أخرج لسان ابن النصرانية\nما في صدره من الشعر حتى مات قال فما تقول في الفرزدق قال في يده والله يا أمير المؤمنين نبعة من الشعر قد قبض عليها قال فما أراك أبقيت لنفسك شيئا قال بلى والله يا أمير المؤمنين إني لمدينة الشعر التي منها يخرج وإليها يعود نسبت فأطربت وهجوت فأرديت ومدحت فسنيت وأرملت فأغزرت ورجزت فأبحرت فأنا قلت ضروب الشعر كلها وكل واحد منهم قال نوعا منها قال صدقت","topic":"نسب جرير وأخباره","topicNo":75,"sp":15,"spl":"يزيد بن معاوية يعاتب أباه بشعر جرير وينسبه إلى نفسه — شعره في جارية له طلبت منه أن يبيعها","loc":1408,"partial":1},
{"id":"b75-24","bab":"الجزء 8","sec":"شعره في جارية له طلبت منه أن يبيعها","page":"ج8 ص58","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثنا علي بن الصباح عن ابن الكلبي قال كانت لجرير أمة وكان بها معجبا فاستخفت المطعم والملبس والغشيان واستقلت ما عنده وكانت قبله عند قوم يقال لهم بنو زيد أهل خصب ونعمة فسامته أن يبيعها وألحت في ذلك فقال فيها\n(تكلفني معيشة آل زيد ... ومن لي بالمرقق والصناب)\n(تقول ألا تضم كضم زيد ... وما ضمي وليس معي شبابي)\nقال الفرزدق يعيره ذلك\n(فإن تفقرك علجة آل زيد ... ويعجزك المرقق والصناب)\n(فقدما كان عيش أبيك مرا ... يعيش بما تعيش به الكلاب)","topic":"نسب جرير وأخباره","topicNo":75,"sp":15,"spl":"يزيد بن معاوية يعاتب أباه بشعر جرير وينسبه إلى نفسه — شعره في جارية له طلبت منه أن يبيعها","loc":1409},
{"id":"b75-25","bab":"الجزء 8","sec":"خبره مع ذي الرمة","page":"ج8 ص59","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا العباس بن ميمون قال حدثنا التوزي عن أبي عبيدة عن أيوب بن كسيب قال دخل جرير على المهاجر بن عبد الله وهو والي اليمامة وعنده ذو الرمة ينشده فقال المهاجر بن عبد الله لجرير كيف ترى قال لقد قال وما أنعم فغضب ذو الرمة ونهض وهو يقول\n(أنا أبو الحارث واسمي غيلان ... )\nنهض جرير وقال\n(إني امرؤ خلقت شكسا أشوسا ... إن تضرساني تضرسا مضرسا)\n(قد لبس الدهر وأبقى ملبسا ... من شاء من نار الجحيم اقتبسا)\nال فجلس ذو الرمة وحاد عنه فلم يجبه أخبرني أبو الحسن الأسدي قال حدثنا ابن النطاح عن أبي عبيدة قال كان ذو الرمة ممن أعان على جرير ولم يصحر له فقال جرير فيه\n(أقول نصاحة لبني عدي ... ثيابكم ونضح دم القتيل)\nهي قصيدة قال وكانوا يتعاونون عليه ولا يصحرون له أخبرنا ابو خليفة الفضل بن الحباب قال حدثنا محمد بن سلام قال حدثني أبو الغراف قال قال الفرزدق لذي الرمة ألهاك البكاء في الديار وهذا العبد يرجز بك\n(يعني هشاما المرئي ... )\nبمقبرة بني حصن قال وكان السبب في الهجاء بين ذي الرمة وهشام أن ذا الرمة نزل بقرية لبني امرىء القيس يقال لها مرأة فلم يقروه ولم يعلفوا له فارتحل وهو يقول\n(نزلنا وقد طال النهار وأوقدت ... علينا حصى المعزاء شمس تنالها)\n(أنخنا فظللنا بأبراد يمنة ... رقاق وأسياف قديم صقالها)\n(فلما رآنا أهل مرأة أغلقوا ... مخادع لم ترفع لخير ظلالها)\n(وقد سميت باسم امرىء القيس قرية ... كرام صواديها لئام رجالها)\n(يظل الكرام المرملون بجوها ... سواء عليهم حملها وحيالها)\n(ولو وضعت أكوارها عند بيهس ... على ذات غسل لم تشمس رحالها)\nقال جرير لهشام وكان يتهم ذا الرمة بهجائه التيم وهم إخوة عدي عليك العبد يعني ذا لرمة قال فما أصنع يا أبا حزرة وهو يقول القصيد وأنا أقول الرجز والرجز لا يقوم للقصيد فلو رفدتني قال قل له\n(عجبت لرحل من عدي مشمس ... وفي أي يوم لم تشمس رحالها)\n(وفيم عدي عند تيم من العلا ... وأيامنا اللاتي يعد فعالها)\n(مددت بكف من عدي قصيرة ... لتدرك من زيد يدا لا تنالها)\n(وضبة عمي يابن جل فلا ترم ... مساعي قوم ليس منك سجالها)\n(يماشي عديا لؤمها ما تجنه ... من الناس ماشت عديا ظلالها)\n(فقل لعدي تستعن بنسائها ... علي فقد أعيا عديا رجالها)\n(أذا الرم قد قلدت قومك رمة ... بطيئا بأيدي المطلقين انحلالها)\n(ترى اللؤم ما عاشت عدي مخلدا ... سرابيلها منه ومنه نعالها)\nال فلج الهجاء بين ذي الرمة وهشام فلما أنشد المرئي هذه الأبيات وسمعها ذو الرمة قال كذب العبد السوء ليس هذا الكلام له هذا كلام نجدي حنظلي هذا كلام آبن الأتان قال ولم يزل ذو الرمة مستعليا على هشام حتى لقيه جرير فرفده هذه الأبيات أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن أبي عدنان قال حدثني أبو صخر من ولد حجناء بن نوح بن جرير قال سمعت أبي يحدث عن أبيه قال أتى هشام بن قيس المرئي أبي يعني جريرا فاسترفده على ذي الرمة وقد كانا تهاجيا دهرا وكان سبب ذلك أن ذا الرمة نزل على أهل قرية لبني آمرىء القيس فلم يدخلوا رحله فذمهم في القرى ومدح بيهسا صاحب ذات غسل وهو مرئي وذات غسل قرية له فقال ذو الرمة\n(ولما وردنا مرأة اللؤم أغلقت ... دساكر لم تفتح لخير ظلالها)\n(ولو عريت أصلابها عند بيهس ... على ذات غسل لم تشمس رحالها)\n(إذا ما امرؤ القيس ابن لؤم تطعمت ... بكأس الندامى خبثتها سبالها)\nقال جرير للمرئي قل له\n(غضبت لرحل من عدي مشمس ... وفي أي يوم لم تشمس رحالها)\nوذكر الأبيات الماضية المذكورة في رواية أبي خليفة قال فلقي ذو الرمة جريرا فقال له تعصبت للمرئي وأنا خالك قال حين قلت ماذا قال حين قلت له أن يقول لي\n(عجبت لرحل من عدي مشمس ... )\nقال له جرير لا بل ألهاك البكاء في دار مية حتى أبيحت محارمك قال وكان قد بلغ جريرا ميل ذي الرمة عليه فجعل يعتذر إليه ويحلف له فقال له جرير اذهب الآن فقل للمرئي\n(يعد الناسبون إلى تميم ... بيوت المجد أربعة كبارا)\n(يعدون الرباب وآل سعد ... وعمرا ثم حنظلة الخيارا)\n(ويهلك بينها المرئي لغوا ... كما ألغيت في الدية الحوارا)\nقال ذو الرمة قصيدته التي أولها\n(نبت عيناك عن طلل بحزوى ... عفته الريح وامتنح القطارا)","topic":"نسب جرير وأخباره","topicNo":75,"sp":16,"spl":"خبره مع ذي الرمة","loc":1410,"partial":1},
{"id":"b75-26","bab":"الجزء 8","sec":"خبره مع ذي الرمة","page":"ج8 ص59","text":"ألحق فيها هذه الأبيات فلما أنشدها وسمعها المرئي جعل يلطم رأسه ووجهه ويدعو بويله وحربه ويقول ما لي ولجرير فقيل له وأين جرير منك هذا رجل يهاجيك وتهاجيه فقال هيهات لا والله ما يحسن ذو الرمة أن يقول\n(ويذهب بينها المرئي لغوا ... كما ألغيت في الدية الحوارا)\nذا والله كلام جرير ما تعداه قط قال ومر الفرزدق بذي الرمة وهو ينشد هذه القصيدة فلما أنشد الأبيات الثلاثة فيها قال له الفرزدق أعد يا غيلان فأعاد فقال له أأنت تقول هذا قال نعم يا أبا فراس قال كذب فوك والله لقد نحلكها أشد لحيين منك هذا شعر ابن الأتان قال وجاء المرئيون إلى جرير فقالوا يا أبا حزرة قد آستعلى علينا ذو الرمة فأعنا على عادتك الجميلة فقال هيهات قد والله ظلمت خالي لكم مرة وجاءني فاعتذر وحلف وما كنت لأعينكم عليه بعدها قال ومات ذو الرمة في تلك الأيام","topic":"نسب جرير وأخباره","topicNo":75,"sp":17,"spl":"خبره مع ذي الرمة — نصيب يقر بأسبقيته عليه وعلى جميل","loc":1411},
{"id":"b75-27","bab":"الجزء 8","sec":"نصيب يقر بأسبقيته عليه وعلى جميل","page":"ج8 ص63","text":"أخبرني عمي قال حدثني الكراني قال حدثني العمري عن لقيط قال حدثني أبو بكر بن نوفل قال حدثني من سأل النصيب قال قلت له يا أبا محجن بيت قلته نازعك فيه جرير وجميل فأحب أن تخبرني أيكم فيه أشعر قال وما هو قلت قولك\n(أضر بها التهجير حتى كأنها ... أكب عليها جازر متعرق)\nقال جميل\n(أضر بها التهجير حتى كأنها ... بقايا سلال لم يدعها سلالها)\nقال جرير\n(إذا بلغوا المنازل لم تقيد ... وفي طول الكلال لها قيود)\nفقال نصيب قاتل الله آبن الخطفي ما أشعره قال فقال له الرجل أما أنت فقد فضلته فقال هو ما أقول لك أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني عبد الرحمن بن القاسم العجلي قال حدثني الحسن بن علي المنقري قال قال مسعود بن بشر قلت لابن مناذر بمكة من أشعر الناس قال من إذا شئت لعب وإذا شئت جد فإذا لعب أطمعك لعبه فيه وإذا رمته بعد عليك وإذا جد فيما قصد له أيأسك من نفسه قلت مثل من قال مثل جرير حين يقول إذا لعب\n(إن الذين غدوا بلبك غادروا ... وشلا بعينك ما يزال معينا)\nثم قال حين جد\n(إن الذي حرم المكارم تغلبا ... جعل الخلافة والنبوة فينا)\n(مضر أبي وأبو الملوك فهل لكم ... يا آل تغلب من أب كأبينا)\n(هذا ابن عمي في دمشق خليفة ... لو شئت ساقكم إلي قطينا)\nخبرني هاشم بن محمد قال حدثني الرياشي قال حدثنا الأصمعي عن أبي عمرو قال لما بلغ عبد الملك قول جرير\n(هذا ابن عمي في دمشق خليفة ... لو شئت ساقكم إلي قطينا)\nقال ما زاد ابن المراغة على أن جعلني شرطيا أما إنه لو قال\n(لو شاء ساقكم إلي قطينا ... )\nسقتهم إليه كما قال","topic":"نسب جرير وأخباره","topicNo":75,"sp":17,"spl":"خبره مع ذي الرمة — نصيب يقر بأسبقيته عليه وعلى جميل","loc":1412,"partial":1},
{"id":"b75-29","bab":"الجزء 8","sec":"بشار يفضله على الفرزدق والأخطل — مناقضة بينه وبين الفرزدق","page":"ج8 ص64 – ج8 ص65","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام قال سألت بشارا العقيلي عن الثلاثة فقال لم يكن الأخطل مثلهما ولكن ربيعة تعصبت له وأفرطت فيه قلت فجرير والفرزدق قال كان جرير يحسن ضروبا من الشعر لا يحسنها الفرزدق وفضل جريرا عليه وقال ابن سلام قال العلاء بن جرير وكان قد أدرك الناس وسمع كان يقال الأخطل إذا لم يجىء سابقا فهو سكيت والفرزدق لا يجيء سابقا ولا سكيتا فهو بمنزلة المصلي أبدا وجرير يجيء سابقا ومصليا وسكيتا قال ابن سلام وتأول قوله إن للأخطل خمسا أو ستا أو سبعا طوالا روائع غررا جيادا هو بهن سابق وسائر شعره دون اشعارهما فهو فيما بقي بمنزلة السكيت والسكيت آخر الخيل في الرهان والفرزدق دونه في هذه الروائع وفوقه في بقية شعره فهو كالمصلي أبدا وهو الذي يجيء بعد السابق وقبل السكيت وجرير له روائع هو بهن سابق وأوساط هو بهن مصل وسفسافات هو بهن سكيت\nأخبرنا أبو خليفة قال حدثني محمد بن سلام قال حدثني حاجب بن زيد بن شيبان بن علقمة بن زرارة قال\nقال جرير بالكوفة\n(لقد قادني من حب ماوية الهوى ... وما كنت تلقاني الجنيبة أقودا)\n(أحب ثرى نجد وبالغور حاجة ... فغار الهوى يا عبد قيس وأنجدا)\n(أقول له يا عبد قيس صبابة ... بأي ترى مستوقد النار أوقدا)\n(فقال أرى نارا يشب وقودها ... بحيث استفاض الجزع شيحا وغرقدا)\nأعجبت الناس وتناشدوها قال فحدثني جابر بن جندل قال فقال لنا جرير أعجبتكم هذه الأبيات قالوا نعم قال كأنكم بابن القين وقد قال\n(أعد نظرا يا عبد قيس لعلما ... أضاءت لك النار الحمار المقيدا)\nال فلم يلبثوا أن جاءهم قول الفرزدق هذا البيت وبعده\n(حمار بمروت السحامة قاربت ... وظيفيه حول البيت حتى ترددا)\n(كليبية لم يجعل الله وجهها ... كريما ولم يسنح بها الطير أسعدا)\nال فتناشدها الناس فقال الفرزدق كأنكم بابن المراغة قد قال\n(وما عبت من نار أضاء وقودها ... فراسا وبسطام بن قيس مقيدا)\nقال فإذا بالبيت قد جاء لجرير ومعه\n(وأوقدت بالسيران نارا ذليلة ... وأشهدت من سوءات جعثن مشهدا)","topic":"نسب جرير وأخباره","topicNo":75,"sp":18,"spl":"بشار يفضله على الفرزدق والأخطل — مناقضة بينه وبين الفرزدق","loc":1413},
{"id":"b75-30","bab":"الجزء 8","sec":"رآه الأخطل عند عبد الملك فعرفه","page":"ج8 ص67","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني محمد بن عبد الله بن آدم بن جشم عن عمارة بن عقيل عن أبيه قال وقف جرير على باب عبد الملك بن مروان والأخطل داخل عنده وقد كانا تهاجيا ولم ير أحد منهما صاحبه فلما استأذنوا عليه لجرير أذن له فدخل فسلم ثم جلس وقد عرفه الأخطل فطمح طرف جرير إلى الأخطل وقد رآه ينظر إليه نظرا شديدا فقال له من أنت فقال أنا الذي منعت نومك وتهضمت قومك فقال له جرير ذلك أشقى لك كائنا من كنت ثم أقبل على عبد الملك بن مروان فقال من هذا يا أمير المؤمنين جعلني الله فداءك فضحك ثم قال هذا الأخطل يا أبا حزرة فرد عليه بصره ثم قال فلا حياك الله يابن النصرانية أما منعك نومي فلو نمت عنك لكان خيرا لك وأما تهضمك قومي فكيف تهضمهم وأنت ممن ضربت عليه الذلة وباء بغضب من الله وأدى الجزية عن يد وهو صاغر وكيف تتهضم لا أم لك قوما فيهم النبوة والخلافة وأنت لهم عبد مأمور ومحكوم عليه لا حاكم ثم أقبل على عبد الملك فقال ائذن لي يا أمير المؤمنين في ابن النصرانية فقال لا يجوز أن يكون ذلك بحضرتي أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثني أبو يحيى الضبي قال\nنازع جرير بني حمان في ركية لهم فصاروا إلى إبراهيم بن عدي باليمامة يتحاكمون إليه فقال جرير\n(أعوذ بالأمير غير الجبار ... من ظلم حمان وتحويل الدار)\n(ما كان قبل حفرنا من محفار ... وضربي المنقار بعد المنقار)\n(في جبل أصم غير خوار ... يصيح بالجب صياح الصرار)\n(له صهيل كصهيل الأمهار ... فاسأل بني صحب ورهط الجرار)\n(والسلميين العظام الأخطار ... والجار قد يخبر عن دار الجار)\nقال الحماني\n(ما لكليب من حمى ولا دار ... غير مقام أتن وأعيار)\n(قعس الظهور داميات الأثفار ... )\nال فقال جرير فعن مقامهن جعلت فداك أجادل فقال ابن عدي للحماني قد أقررت لخصمك وحكم بها لجرير قال ابن سلام وأخبرني أبو يحيى الضبي قال بينا جرير يسير على راحلته إذ هجم على أبيات من مازن وهلال وهما بطنان من ضبة فخافهم لسوء أثره في ضبة فقال\n(فلا خوف عليك ولن تراعي ... بعقوة مازن وبني هلال)\n(هما الحيان إن فزعا يطيرا ... إلى جرد كامثال السعالي)\n(أمازن يابن كعب إن قلبي ... لكم طول الحياة لغير قالي)\n(غطاريف يبيت الجار فيهم ... قرير العين في أهل ومال)\nال أجل يا أبا حزرة فلا خوف عليك","topic":"نسب جرير وأخباره","topicNo":75,"sp":19,"spl":"رآه الأخطل عند عبد الملك فعرفه — تجمع الناس حوله في المسجد دون الفرزدق","loc":1414,"partial":1},
{"id":"b75-31","bab":"الجزء 8","sec":"تجمع الناس حوله في المسجد دون الفرزدق","page":"ج8 ص69","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال قال شعيب بن صخر حدثني هارون بن إبراهيم قال رأيت جريرا والفرزدق في مسجد دمشق وقد قدماها على الوليد بن عبد الملك والناس عنق واحد على جرير قيس وموالي بني أمية يسلمون عليه ويسألونه كيف كنت يا أبا حزرة في مسيرك وكيف أهلك وأسبابك وما يطيف بالفرزدق إلا نفر من خندف جلوس معه قال شعيب فقلت لهارون ولم ذلك قال لمدحه قيسا وقوله في العجم\n(فيجمعنا والغر أولاد سارة ... أب لا نبالي بعده من تعذرا)\nال شعيب بلغني أنه أهديت له يومئذ مائة حلة أهداها إليه الموالي سوى غيرهم وأخبرني بهذا الخبر أبو خليفة عن محمد بن سلام عن شعيب بن صخر فذكر نحوا من حكاية أبي زيد إلا أنها أتم من حكاية ابن سلام وقال\nأبو خليفة في خبره سمعت عمارة بن عقيل بن بلال يقول وافته في يومه ذلك مائة حلة من بني الأحرار أخبرني جعفر بن قدامة قال حدثني أحمد بن الهيثم الفراسي قال بينا جرير بقباء إذ طلع الأحوص وجرير ينشد قوله\n(لولا الحياء لعادني استعبار ... ولزرت قبرك والحبيب يزار)\nلما نظر إلى الأحوص قطع الشعر ورفع صوته يقول\n(عوى الشعراء بعضهم لبعض ... علي فقد أصابهم انتقام)\n(إذا أرسلت قافية شرودا ... رأوا أخرى تحرق فاستداموا)\n(فمصطلم المسامع أو خصي ... وآخر عظم هامته حطام)\nم عاد من حيث قطع فلما فرغ قيل له ولم قلت هذا قال قد نهيت الأحوص أن يعين علي الفرزدق فأنا والله يا بني عمرو بن عوف ما تعوذت من شاعر قط ولولا حقكم ما تعوذت منه","topic":"نسب جرير وأخباره","topicNo":75,"sp":19,"spl":"رآه الأخطل عند عبد الملك فعرفه — تجمع الناس حوله في المسجد دون الفرزدق","loc":1415},
{"id":"b75-32","bab":"الجزء 8","sec":"محمد بن الحجاج يلح على عبد الملك بالإذن لجرير بالدخول عليه لإنشاده","page":"ج8 ص70","text":"أخبرنا علي بن سليمان الأخفش قال حدثنا الحسن بن الحسين السكري قال قال عمارة بن عقيل حدثني أبي عن أبيه أن الحجاج أوفد ابنه محمد بن الحجاج إلى عبد الملك وأوفد إليه\nجريرا معه ووصاه به وأمره بمسألة عبد الملك في الاستماع منه ومعاونته عليه فلما وردوا استأذن له محمد على عبد الملك فلم يأذن له وكان لا يسمع من شعراء مضر ولا يأذن لهم لأنهم كانوا زبيرية فلما استأذن له محمد على عبد الملك ولم يأذن له أعلمه أن أباه الحجاج يسأله في أمره ويقول إنه لم يكن ممن والى ابن الزبير ولا نصره بيده ولا لسانه وقال له محمد يا أمير المؤمنين إن العرب تتحدث أن عبدك وسيفك الحجاج شفع في شاعر قد لاذ به وجعله وسيلته ثم رددته فأذن له فدخل فاستأذن في الإنشاد فقال له وما عساك أن تقول فينا بعد قولك في الحجاج ألست القائل\n(من سد مطلع النفاق عليكم ... أم من يصول كصولة الحجاج)\nن الله لم ينصرني بالحجاج وإنما نصر دينه وخليفته أولست القائل\n(أم من يغار على النساء حفيظة ... إذ لا يثقن بغيرة الأزواج)\nا عاض كذا وكذا من أمه والله لهممت أن أطير بك طيرة بطيئا سقوطها أخرج عني فأخرج بشر فلما كان بعد ثلاث شفع إليه محمد لجرير وقال له يا أمير المؤمنين إني أديت رسالة عبدك الحجاج وشفاعته في جرير فلما أذنت له خاطبته بما أطار لبه منه وأشمت به عدوه ولو لم تأذن له لكان خيرا له مما سمع فإن رأيت أن تهب كل ذنب له لعبدك الحجاج ولي فافعل فأذن له فاستأذنه في الإنشاد فقال لا تنشدني إلا في الحجاج فإنما أنت للحجاج خاصة فسأله أن ينشده مديحه فيه فأبى وأقسم ألا ينشده إلا من قوله في الحجاج فأنشده وخرج بغير جائزة فلما أزف الرحيل قال جرير لمحمد إن رحلت عن أمير المؤمنين ولم يسمع مني ولم آخذ له جائزة سقطت آخر الدهر ولست بارحا بابه أو يأذن لي في الإنشاد وأمسك عبد الملك عن الإذن له فقال جرير ارحل أنت وأقيم أنا فدخل\nمحمد على عبد الملك فأخبره بقول جرير واستأذنه له وسأله أن يسمع منه وقبل يده ورجله فأذن له فدخل فاستأذن في الإنشاد فأمسك عبد الملك فقال له محمد أنشد ويحك فأنشده قصيدته التي يقول فيها\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nتبسم عبد الملك وقال كذلك نحن وما زلنا كذلك ثم اعتمد على ابن الزبير فقال\n(دعوت الملحدين أبا خبيب ... جماحا هل شفيت من الجماح)\n(وقد وجدوا الخليفة هبرزيا ... ألف العيص ليس من النواحي)\n(وما شجرات عيصك في قريش ... بعشات الفروع ولا ضواحي)\nال ثم أنشده إياها حتى أتى على ذكر زوجته فيها فقال\n(تعزت أم حزرة ثم قالت ... رأيت الموردين ذوي لقاح)\n(تعلل وهي ساغبة بنيها ... بأنفاس من الشبم القراح)\nفقال عبد الملك هل ترويها مائة لقحة فقال إن لم يروها ذلك فلا أرواها الله فهل إليها جعلني الله فداك يا أمير المؤمنين من سبيل فأمر له بمائة لقحة وثمانية من الرعاء وكانت بين يديه جامات من ذهب فقال له جرير يا أمير المؤمنين تأمر لي بواحدة منهن تكون محلبا فضحك وندس إليه واحدة منهن بالقضيب وقال خذها لا نفعتك فأخذها وقال بلى والله يا أمير المؤمنين لينفعني كل ما منحتنيه وخرج من عنده قال وقد ذكر ذلك جرير في شعره فقال يمدح يزيد بن عبد الملك\n(أعطوا هنيدة يحدوها ثمانية ... ما في عطائهم من ولا سرف)","topic":"نسب جرير وأخباره","topicNo":75,"sp":20,"spl":"محمد بن الحجاج يلح على عبد الملك بالإذن لجرير بالدخول عليه لإنشاده","loc":1416},
{"id":"b75-33","bab":"الجزء 8","sec":"هجا سراقة لأنه أعان الفرزدق عليه","page":"ج8 ص73","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا دماذ أبو غسان عن أبي عبيدة قال بذل محمد بن عمير بن عطارد بن حاجب بن زرارة أربعة آلاف درهم وفرسا لمن فضل من الشعراء الفرزدق على جرير فلم يقدم عليه أحد منهم إلا سراقة البارقي فإنه قال يفضل الفرزدق\n(أبلغ تميما غثها وسمينها ... والحكم يقصد مرة ويجور)\n(أن الفرزدق برزت أعراقه ... سبقا وخلف في الغبار جرير)\n(ذهب الفرزدق بالفضائل والعلا ... وابن المراغة مخلف محسور)\n(هذا قضاء البارقي وإنني ... بالميل في ميزانهم لبصير)\nال أبو عبيدة فحدثني أيوب بن كسيب قال حدثني أبي قال كنت مع\nجرير فأتاه رسول بشر بن مروان فدفع إليه كتابه وقال له إنه قد أمرني أن أوصله إليك ولا أبرح حتى تجيب عن الشعر في يومك إن لقيتك نهارا أو ليلتك إن لقيتك ليلا وأخرج إليه كتاب بشر وقد نسخ له القصيدة وأمره بأن يجيب عنها فأخذها ومكث ليلته يجتهد أن يقول شيئا فلا يمكنه فهتف به صاحبه من الجن من زاوية البيت فقال له أزعمت أنك تقول الشعر ما هو إلا أن غبت عنك ليلة حتى لم تحسن أن تقول شيئا فهلا قلت\n(يا بشر حق لوجهك التبشير ... هلا قضيت لنا وأنت أمير)\nقال له جرير حسبك كفيتك قال وسمع قائلا يقول لآخر قد أنار الصبح فقال جرير\n(يا صاحبي هل الصباح منير ... أم هل للوم عواذلي تفتير)\nلى أن فرغ منها وفيها يقول\n(قد كان حقك أن تقول لبارق ... يا آل بارق فيم سب جرير)\n(يعطى النساء مهورهن كرامة ... ونساء بارق ما لهن مهور)\nأخذها الرسول ومضى بها إلى بشر فقرئت بالعراق وأفحم سراقة فلم ينطق بعدها بشيء من مناقضته","topic":"نسب جرير وأخباره","topicNo":75,"sp":21,"spl":"هجا سراقة لأنه أعان الفرزدق عليه","loc":1417},
{"id":"b75-34","bab":"الجزء 8","sec":"مناقضة بينه وبين عمر بن لجأ","page":"ج8 ص74","text":"أخبرني أبو خليفة قال حدثني محمد بن سلام قال حدثني أبو يحيى الضبي قال\nكان الذي هاج الهجاء بين جرير وعمر بن لجأ أن عمر كان ينشد أرجوزة له يصف فيها إبله وجرير حاضر فقال فيها\n(قد وردت قبل إنا ضحائها ... تفرس الحيات في خرشائها)\n(جر العجوز الثني من ردائها ... )\nقال له جرير أخفقت فقال كيف اقول قال تقول\n(جر العروس الثني من ردائها ... )\nفقال له التيمي أنت أسوأ قولا مني حيث تقول\n(وأوثق عند المردفات عشية ... لحاقا إذا ما جرد السيف لامع)\nفجعلتهن مردفات غدوة ثم تداركتهن عشية فقال كيف أقول قال تقول\n(وأوثق عند المرهفات عشية ... )\nقال جرير والله لهذا البيت أحب إلي من بكري حزرة ولكنك مجلب للفرزدق وقال فيه جرير\n(هلا سوانا ادرأتم يا بني لجأ ... شيئا يقارب أو وحشا لها غرر)\n(أحين كنت سماما يا بني لجأ ... وخاطرت بي عن أحسابها مضر)\n(خل الطريق لمن يبني المنار به ... وابرز ببرزة حيث اضطرك القدر)\n(أنت ابن برزة منسوبا إلى لجأ ... عند العصارة والعيدان تعتصر)\nيروى\n(ألست نزوة خوار على أمة ... عند العصارة والعيدان تعتصر)\nقال ابن لجأ يرد عليه\n(لقد كذبت وشر القول أكذبه ... ما خاطرت بك عن أحسابها مضر)\n(بل أنت نزوة خوار على أمة ... لا يسبق الحلبات اللؤم والخور)\n(ما قلت من هذه إلا سأنقضها ... يابن الأتان بمثلي تنقض المرر)\nقال عمر بن لجأ\n(عجبت لما لاقت رياح من الأذى ... وما اقتبسوا مني وللشر قابس)\n(غضابا لكلب من كليب فرسته ... هوى ولشدات الأسود فرائس)\n(إذا ما ابن يربوع أتاك لمأكل ... على مجلس إن الأكيل مجالس)\n(فقل لابن يربوع ألست براحض ... سبالك عنا إنهن نجائس)\n(تمسح يربوع سبالا لئيمة ... بها من مني العبد رطب ويابس)\nال ثم اجتمع جرير وابن لجأ بالمدينة وقد وردها الوليد بن عبد الملك وكان يتأله في نفسه فقال أتقذفان المحصنات وتغضبانهن ثم أمر ابا بكر محمد بن حزم الأنصاري وكان واليا له بالمدينة بضربهما فضربهما وأقامهما على البلس مقرونين والتيمي يومئذ أشب من جرير فجعل يشول بجرير وجرير يقول وهو المشول به\n(فلست مفارقا قرني حتى ... يطول تصعدي بك وانحداري)\nفقال أبن لجأ\n(ولما أن قرنت إلى جرير ... أبى ذو بطنه إلا انحدارا)\nقال له قدامة بن إبراهيم الجمحي وبئسما قلت جعلت نفسك المقرون إليه قال فكيف أقول قال تقول\n(ولما لز في قرني جرير ... )\nقال جزيت خيرا لا أقوله والله ابدا إلا هكذا حدثني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني محمد بن عبد الله العبدي قال حدثني عمارة بن عقيل عن أبيه قال وقف جرير على باب عبد الملك بن مروان والأخطل داخل عنده وقد كانا تهاجيا ولم يلق أحدهما صاحبه فلما أستأذنوا لجرير أذن له فسلم وجلس وقد عرفه الأخطل فطمح بصر جرير إليه فقال له من أنت فقال أنا الذي منعت نومك وهضمت قومك فقال له جرير ذاك أشقى لك كائنا من كنت ثم اقبل على عبد الملك فقال من هذا يا أمير المؤمنين فضحك وقال هذا الأخطل يا ابا حزرة فرد بصره إليه وقال فلا حياك الله يابن النصرانية أما منعك نومي فلو نمت عنك لكان خيرا لك واما تهضمك قومي فكيف تهضمهم وأنت ممن ضربت عليهم الذلة والمسكنة وباءوا بغضب من الله ائذن لي يا أمير المؤمنين في ابن النصرانية فقال لا يكون ذلك بين يدي فوثب جرير مغضبا فقال عبد الملك قم يا أخطل واتبع صاحبك فإنما قام غضبا علينا فيك فنهض الأخطل فقال عبد الملك لخادم له انظر ما يصنعان إذا برز له الأخطل فخرج جرير فدعا بغلام له فقدم إليه حصانا له أدهم فركبه وهدر\nوالفرس يهتز من تحته وخرج الأخطل فلاذ بالباب وتوارى خلفه ولم يزل واقفا حتى مضى جرير فدخل الخادم إلى عبد الملك فأخبره فضحك وقال قاتل الله جريرا ما أفحله أما والله لو كان النصراني برز إليه لأكله أخبرني هاشم بن محمد قال حدثنا الرياشي قال حدثنا الأصمعي عن أبي عمرو قال سئل جرير أي الثلاثة أشعر فقال أما الفرزدق فيتكلف مني ما لا يطيقه وأما الأخطل فأشدنا اجتراء وأرمانا للغرض وأما أنا فمدينة الشعر وقد حدثني بهذا الخبر حبيب بن نصر عن عمر بن شبة عن الأصمعي فذكر نحو ما ذكره الرياشي وقال في خبره وأما الأخطل فأنعتنا للخمر وأمدحنا للملوك","topic":"نسب جرير وأخباره","topicNo":75,"sp":22,"spl":"مناقضة بينه وبين عمر بن لجأ","loc":1418,"partialRef":{"sid":"b75-9","gi":7,"vi":1,"side":0},"partial":1},
{"id":"b75-35","bab":"الجزء 8","sec":"ابو مهدي الباهلي فضله على جميع الشعراء","page":"ج8 ص78","text":"أخبرنا عمي قال حدثنا الكراني قال حدثنا العمري عن عطاء بن مصعب قال قلت لأبي مهدي الباهلي وكان من علماء العرب أيما أشعر أجرير أم الفرزدق فغضب ثم قال جرير أشعر العرب كلها ثم قال لا يزال الشعراء موقوفين يوم القيامة حتى يجيء جرير فيحكم بينهم أخبرني هاشم بن محمد قال حدثني العباس بن ميمون قال سمعت أبا عثمان المازني يقول قال جرير هجوت بني طهية أنواع الهجاء فلم يحفلوا بقولي حتى قلت\nفي قصيدة الراعي\n(كأن بني طهية رهط سلمى ... حجارة خارىء يرمي كلابا)\nجزعوا حينئذ ولاذوا بي أخبرني الحسن بن علي الخفاف قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني قال كان جرير من أعق الناس بأبيه وكان بلال ابنه أعق الناس به فراجع جرير بلالا الكلام يوما فقال له بلال الكاذب مني ومنك ناك أمه فأقبلت أمه عليه وقالت له يا عدو الله أتقول هذا لأبيك فقال جرير دعيه فوالله لكأنه سمعها مني وأنا أقولها لأبي","topic":"نسب جرير وأخباره","topicNo":75,"sp":23,"spl":"ابو مهدي الباهلي فضله على جميع الشعراء — هجا عمر بن يزيد لأنه أعان الفرزدق عليه","loc":1419},
{"id":"b75-36","bab":"الجزء 8","sec":"هجا عمر بن يزيد لأنه أعان الفرزدق عليه","page":"ج8 ص79","text":"أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم قال حدثنا العمري عن لقيط قال كان عمر بن يزيد بن عمير الأسدي يتعصب للفرزدق على جرير فتزوج امرأة من بني عدس بن زيد بن عبد الله بن دارم فقال جرير\n(نكحت إلى بني عدس بن زيد ... فقد هجنت خيلهم العرابا)\n(أتنسى يوم مسكن إذ تنادي ... وقد أخطأت بالقدم الركابا)\nهي قصيدة فأجتمعوا على عمر بن يزيد ولم يزالوا به حتى خلعوا المرأة منه أخبرني محمد بن خلف قال حدثني محمد بن الهيثم قال حدثني عمي\nأبو فراس قال حدثني ودقة بن معروف قال نزل جرير على عنبسة بن سعيد بواسط ولم يكن أحد يدخلها إلا بإذن الحجاج فلما دخل على عنبسة قال له ويحك لقد غررت بنفسك فما حملك على ما فعلت قال شعر قلته اعتلج في صدري وجاشت به نفسي وأحببت أن يسمعه الأمير قال فعنفه وأدخله بيتا في جانب داره وقال لا تطلعن رأسك حتى ننظر كيف تكون الحيلة لك قال فأتاه رسول الحجاج من ساعته يدعوه في يوم قائظ وهو قاعد في الخضراء وقد صب فيها ماء استنقع في أسفلها وهو قاعد على سرير وكرسي موضوع ناحية قال عنبسة فقعدت على الكرسي وأقبل علي الحجاج يحدثني فلما رأيت تطلقه وطيب نفسه قلت اصلح الله الأمير رجل من شعراء العرب قال فيك شعرا اجاد فيه فاستخفه عجبه به حتى دعاه إلى أن رحل إليك ودخل مدينتك من غير أن يستأذن له قال ومن هو قلت ابن الخطفي قال وأين هو قلت في المنزل قال يا غلام فأقبل الغلمان يتسارعون قال صف لهم موضعه من دارك فوصفت لهم البيت الذي هو فيه فانطلقوا حتى جاؤوا به فأدخل عليه وهو مأخوذ بضبعيه حتى رمي به في الخضراء فوقع على وجهه في الماء ثم قام يتنفش كما يتنفش الفرخ فقال له هيه ما اقدمك علينا بغير إذننا لا أم لك قال أصلح الله الأمير قلت في الأمير شعرا لم يقل مثله أحد فجاش به صدري وأحببت أن يسمعه مني الأمير فأقبلت به إليه قال فتطلق الحجاج وسكن واستنشده فأنشده ثم قال يا غلام فجاؤوا يسعون فقال علي\nبالجارية التي بعث بها إلينا عامل اليمامة فأتي بجارية بيضاء مديدة القامة فقال إن أصبت صفتها فهي لك فقال ما أسمها قال أمامة فأنشأ يقول\n(ودع أمامة حان منك رحيل ... إن الوداع لمن تحب قليل)\n(مثل الكثيب تهيلت أعطافه ... فالريح تجبر متنه وتهيل)\n(تلك القلوب صواديا تيمتها ... وأرى الشفاء وما إليه سبيل)\nقال خذ بيدها فبكت الجارية وانتحبت فقال ادفعوها إليه بمتاعها وبغلها ورحالها أخبرنا أبو خليفة قال حدثنا محمد بن سلام قال حدثني أبو الغراف قال قال الحجاج لجرير والفرزدق وهو في قصره بحزيز البصرة ائتياني في لباس آبائكما في الجاهلية فلبس الفرزدق الديباج والخز وقعد في قبة وشاور جرير دهاة بني يربوع فقالوا له ما لباس آبائنا إلا الحديد فلبس جرير درعا وتقلد سيفا وأخذ رمحا وركب فرسا لعباد بن الحصين يقال له المنحاز وأقبل في أربعين فارسا من بني يربوع وجاء الفرزدق في هيئته فقال جرير\n(لبست سلاحي والفرزدق لعبة ... عليه وشاحا كرج وجلاجله)\n(أعدوا مع الحلي الملاب فإنما ... جرير لكم بعل وأنتم حلائله)\nم رجعا فوقف جرير في مقبرة بني حصن ووقف الفرزدق في المربد قال فأخبرني أبي عن محمد بن زياد قال كنت أختلف إلى جرير والفرزدق وكان جرير يومئذ كأنه أصغرهما في عيني","topic":"نسب جرير وأخباره","topicNo":75,"sp":23,"spl":"ابو مهدي الباهلي فضله على جميع الشعراء — هجا عمر بن يزيد لأنه أعان الفرزدق عليه","loc":1420},
{"id":"b75-37","bab":"الجزء 8","sec":"هجاؤه للفرزدق","page":"ج8 ص82","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثنا ابو اليقظان عن جويرية بن أسماء قال قدم الفرزدق اليمامة وعليها المهاجر بن عبد الله الكلابي فقال لودخلت على هذا فأصبت منه شيئا ولم يعلم بي جرير فلم تستقر به الدار حتى قال جرير\n(رأيتك إذ لم يغنك الله بالغنى ... رجعت إلى قيس وخدك ضارع)\n(وما ذاك إن أعطى الفرزدق باسته ... بأول ثغر ضيعته مجاشع)\nلما بلغ ذلك الفرزدق قال لا جرم والله لا أدخل عليه ولا أرزؤه شيئا ولا أقيم باليمامة ثم رحل أخبرنا أبو خليفة قال حدثنا محمد بن سلام قال قال أبو البيداء لقي الفرزدق عمر بن عطية أخا جرير وهو حينئذ يهاجي ابن لجأ فقال له ويلك قل لأخيك ثكلتك أمك ائت التيمي من عل كما أصنع أنا بك وكان الفرزدق قد أنف لجرير وحمي من أن يتعلق به التيمي قال ابن سلام فأنشدني له خلف الأحمر يقوله للتيمي\n(وما أنت إن قرما تميم تساميا ... أخا التيم إلا كالوشيظة في العظم)\n(فلو كنت مولى العز أو في ظلاله ... ظلمت ولكن لا يدي لك بالظلم)\nقال له التيمي\n(كذبت أنا القرم الذي دق مالكا ... وأفناء يربوع وما أنت بالقرم)\nال أبن سلام فحدثني ابو الغراف أن رجال تميم مشت بين جرير والتيمي وقالوا والله ما شعراؤنا إلا بلاء علينا ينشرون مساوينا ويهجون أحياءنا وموتانا فلم يزالوا بهما حتى أصلحوا بينهما بالعهود والمواثيق المغلظة الا يعودا في هجاء فكف التيمي وكان جرير لا يزال يسل الواحدة بعد الواحدة فيه فيقول التيمي والله ما نقضت هذه ولا سمعتها فيقول جرير هذه كانت قبل الصلح قال ابن سلام فحدثني عثمان بن عثمان عن عبد الرحمن بن حرملة قال لما ورد علينا هجاء جرير والتيمي قال لي سعيد بن المسيب ترو شيئا مما قالا فأتيته وقد أستقبل القبلة يريد أن يكبر فقال لي ارويت قلت نعم فأقبل علي بوجهه فأنشدته للتيمي وهو يقول هيه هيه ثم أنشدته لجرير فقال أكله اكله قال أبن سلام وحدثني الرازي عن حجناء بن جرير قال قلت لأبي يا ابت ما هجوت قوما قط إلا فضحتهم إلا التيم فقال يا بني لم أجد بناء أهدمه ولا شرفا أضعه وكانت تيم رعاء غنم يغدون في غنمهم ثم يروحون وقد جاء كل رجل منهم بأبيات فينتحلها ابن لجأ فقيل لجرير ما صنعت في التيم شيئا فقال إنهم شعراء لئام أخبرنا أحمد بن عبيد الله بن عمار قال حدثنا عمر بن محمد بن عبد الملك الزيات قال حدثني ابن النطاح قال حدثني أبو اليقظان قال قال جرير لرجل من بني طهية ايما اشعر أنا أم الفرزدق فقال له أنت\nعند العامة والفرزدق عند العلماء فصاح جرير أنا ابو حزرة غلبته ورب الكعبة والله ما في كل مائة رجل عالم واحد","topic":"نسب جرير وأخباره","topicNo":75,"sp":24,"spl":"هجاؤه للفرزدق","loc":1421},
{"id":"b75-38","bab":"الجزء 8","sec":"طلب من الوليد بن عبد الملك أن يأذن له في ابن الرقاع","page":"ج8 ص84","text":"حدثنا أحمد بن عمار قال حدثني عمر بن محمد بن عبد الملك قال حدثني أبن النطاح قال وحدثني أبو الأخضر لمخارق بن الأخضر القيسي قال إني كنت والله الذي لا إله إلا هو أخص الناس بجرير وكان ينزل إذا قدم على الوليد بن عبد الملك عند سعيد بن عبد الله بن خالد بن أسيد وكان عدي بن الرقاع خاصا بالوليد مداحا له فكان جرير يجيء إلى باب الوليد فلا يجالس أحدا من النزارية ولا يجلس إلا إلى رجل من اليمن بحيث يقرب من مجلس ابن الرقاع إلى أن يأذن الوليد للناس فيدخل فقلت له يا ابا حزرة اختصصت عدوك بمجلسك فقال إني والله ما أجلس إليه إلا لأنشده اشعارا تخزيه وتخزي قومه قال ولم يكن ينشده شيئا من شعره وإنما كان ينشده شعر غيره ليذله ويخوفه نفسه فأذن الوليد للناس ذات عشية فدخلوا ودخلنا فأخذ الناس مجالسهم وتخلف جرير فلم يدخل حتى دخل الناس وأخذوا مجالسهم واطمأنوا فيها فبينما هم كذلك إذا بجرير قد مثل بين السماطين يقول السلام عليك يا أمير المؤمنين ورحمة الله إن رأى أمير المؤمنين أن يأذن لي في ابن الرقاع المتفرقة أؤلف بعضها إلى بعض قال وأنا جالس أسمع فقال الوليد والله لهممت أن أخرجه على ظهرك إلى الناس فقال جرير وهو قائم كما هو\n(فإن تنهني عنه فسمعا وطاعة ... وإلا فإني عرضة للمراجم)\nال فقال له الوليد لا كثر الله في الناس أمثالك فقال له جرير يا أمير المؤمنين إنما أنا واحد قد سعرت الأمة فلو كثر أمثالي لأكلوا الناس أكلا قال فنظرت والله إلى الوليد تبسم حتى بدت ثناياه تعجبا من جرير وجلده قال ثم أمره فجلس أخبرني ابن عمار قال حدثني عمر بن محمد بن عبد الملك الزيات قال حدثنا أبن النطاح عن أبي عبيدة قال كان جرير عند الوليد وعدي بن الرقاع ينشده فقال الوليد لجرير كيف تسمع قال ومن هو يا أمير المؤمنين قال عدي بن الرقاع قال فإن شر الثياب الرقاع ثم قال جرير ( عاملة ناصبة تصلى نارا حامية\nفغضب الوليد وقال يابن اللخناء ما بقي لك إلا أن تتناول كتاب الله والله ليركبنك يا غلام أوكفه حتى يركبه فغمز عمر بن الوليد الغلام الذي أمره الوليد فأبطأ بالإكاف فلما سكن غضب الوليد قام إليه عمر فكلمه وطلب إليه وقال هذا شاعر مضر ولسانها فإن رأى أمير المؤمنين ألا يغض منه ولم يزل به حتى أعفاه وقال له والله لئن هجوته أو عرضت به لأفعلن بك ولأفعلن فقال فيه تلك القصيدة التي يقول فيها\n(أقصر فإن نزارا لن يفاخرها ... فرع لئيم وأصل غير مغروس)\nذكر وقائع نزار في اليمن فعلمنا أنه عناه ولم يجبه الآخر بشيء\nحدثني عمي قال حدثنا الكراني قال حدثنا العمري عن العتبي قال قال هشام بن عبد الملك لشبة بن عقال وعنده جرير والفرزدق والأخطل وهو يومئذ أمير ألا تخبرني عن هؤلاء الذين قد مزقوا أعراضهم وهتكوا أستارهم وأغروا بين عشائرهم في غير خير ولا بر ولا نفع أيهم أشعر فقال شبة أما جرير فيغرف من بحر وأما الفرزدق فينحت من صخر وأما الأخطل فيجيد المدح والفخر فقال هشام ما فسرت لنا شيئا نحصله فقال ما عندي غير ما قلت فقال لخالد بن صفوان صفهم لنا يأبن الأهتم فقال أما أعظمهم فخرا وابعدهم ذكرا وأحسنهم عذرا وأسيرهم مثلا وأقلهم غزلا وأحلاهم عللا الطامي إذا زخر والحامي إذا زأر والسامي إذا خطر الذي إن هدر قال وإن خطر صال الفصيح اللسان الطويل العنان فالفرزدق وأما أحسنهم نعتا وامدحهم بيتا وأقلهم فوتا الذي إن هجا وضع وإن مدح رفع فالأخطل وأما أغزرهم بحرا وارقهم شعرا وأهتكهم لعدوه سترا الأغر الأبلق الذي إن طلب لم يسبق وإن طلب لم يلحق فجرير وكلهم ذكي الفؤاد رفيع العماد واري الزناد فقال له مسلمة بن عبد الملك ما سمعنا بمثلك يا خالد في الأولين ولا رأينا في الآخرين وأشهد أنك أحسنهم وصفا وألينهم عطفا وأعفهم مقالا وأكرمهم فعالا فقال خالد أتم الله عليكم نعمه وأجزل لديكم قسمه وآنس بكم الغربة وفرج بكم الكربة وأنت والله ما علمت أيها الأمير كريم الغراس عالم بالناس جواد في المحل بسام عند البذل حليم عند الطيش في ذروة قريش ولباب عبد شمس ويومك خير من أمس فضحك هشام وقال ما رأيت كتخلصك يابن صفوان في مدح هؤلاء ووصفهم حتى أرضيتهم جميعا وسلمت منهم","topic":"نسب جرير وأخباره","topicNo":75,"sp":25,"spl":"طلب من الوليد بن عبد الملك أن يأذن له في ابن الرقاع","loc":1422},
{"id":"b75-39","bab":"الجزء 8","sec":"قرنهما عمر بن عبد العزيز لأنهما تقاذفا","page":"ج8 ص87","text":"أخبرني محمد بن خلف وكيع قال حدثنا أبو أيوب المديني قال حدثني مصعب الزبيري قال حدثني إبراهيم بن عبد الله مولى بني زهرة قال حضرت عمر بن لجأ وجرير بن الخطفي موقوفين للناس بسوق المدينة لما تهاجيا وتقاذفا وقد أمر بهما عمر بن عبد العزيز فقرنا وأقيما قال وعمر بن لجأ شاب كأنه حصان وجرير شيخ قد أسن وضعف قال فيقول ابن لجأ\n(رأوا قمرا بساحتهم منيرا ... وكيف يقارن القمر الحمارا)\nال ثم ينزو به وهما مقرونان في حبل فيسقطان إلى الأرض فأما ابن لجأ فيقع قائما وأما جرير فيخر لركبتيه ووجهه فإذا قام نفض الغبار عنه ثم قال بغنته قولا يخرج الكلام به من أنفه وكان كلامه كأن فيه نونا\n(فلست مفارقا قرني حتى ... يطول تصعدي بك وانحداري)\nال فقال رجل من جلساء عمر له حين حضر غداؤه لو دعا الأمير بأسيريه فغداهما معه ففعل ذلك عمر وإنما فعله بهما لأنهما تقاذفا وكان جرير قال له\n(تقول والعبد مسكين يجررها ... أرفق فديتك أنت الناكح الذكر)\nال وهذه قصيدته التي يقول فيها\n(يا تيم تيم عدي لا أبا لكم ... لا يوقعنكم في سوءة عمر)\nخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي قال حدثني أبي قال\nكنت باليمامة وأنا واليها فكان ابن لجرير يكثر عندي الدخول وكنت أوثره فلم اقل له قط أنشدني أجود شعر لأبيك إلا أنشدني الدالية\n(أهوى أراك برامتين وقودا ... أم بالجنينة من مدافع أودا)\nأقول له ويحك لا تزيدني على هذه فيقول سألتني عن أجود شعر أبي وهذه أجود شعره وقد كان يقدمها على جميعه حدثني ابن عمار قال حدثني النوفلي قال حدثني علي بن عبد الملك الكعبي من ولد كعب مولى الحجاج قال حدثني فلان العلامة التميمي يرويه عن جرير قال ما ندمت على هجائي بني نمير قط إلا مرة واحدة فإني خرجت إلى الشام فنزلت بقوم نزول في قصر لهم في ضيعة من ضياعهم وقد نظرت إليه من بين القصور مشيدا حسنا وسألت عن صاحبه فقيل لي هو رجل من بني نمير فقلت هذا شآم وأنا بدوي لا يعرفني فجئت فاستضفت فلما أذن لي ودخلت عليه عرفني فقراني أحسن القرى ليلتين فلما أصبحت جلست ودعا بنية له فضمها إليه وترشفها فإذا هي أحسن الناس وجها ولها نشر لم اشم أطيب منه فنظرت إلى عينيها فقلت تالله ما رأيت أحسن من عيني هذه الصبية ولا من حورها قط وعوذتها فقال لي يا ابا حزرة أسوداء المحاجر هي فذهبت أصف طيب رائحتها فقال أصن وبر هي فقلت يرحمك\nالله إن الشاعر ليقول ووالله لقد ساءني ما قلته ولكن صاحبكم بدأني فانتصرت وذهبت أعتذر فقال دع ذا عنك أبا حزرة فوالله ما لك عندي إلا ما تحب قال وأحسن والله إلي وزودني وكساني فانصرفت وأنا أندم الناس على ما سلف مني إلى قومه أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن يعقوب بن داود قال حدثني ابن أبي علقمة الثقفي قال كان المفضل يقدم الفرزدق فأنشدته قول جرير\n(حي الهدملة من ذات المواعيس ... فالحنو أصبح قفرا غير مأنوس)\nقلت أنشدني لغيره مثلها فسكت قال وكان الفرزدق إذا أنشدها يقول مثلها فليقل ابن اللخناء أخبرنا ابو خليفة الفضل بن الحباب قال حدثنا محمد بن سلام قال حدثني عبد الجبار بن سعيد بن سليمان المساحقي عن المحرر بن أبي هريرة قال إني لفي عسكر سليمان بن عبد الملك وفيه جرير والفرزدق في غزاة إذا أتانا الفرزدق في غداة ثم قال اشهدوا أن محمد ابن أخي ثم أنشأ يقول\n(فبت بديري أريحاء بليلة ... خدارية يزداد طولا تمامها)\n(أكابد فيها نفس أقرب من مشى ... أبوه بأم غاب عنها نيامها)\n(وكنا نرى من غالب في محمد ... شمائل تعلو الفاعلين كرامها)\n(وكان إذا ما حل أرضا تزينت ... بزينتها صحراؤها وإكامها)\n(سقى أريحاء الغيث وهي بغيضة ... إلينا ولكن بي لتسقاه هامها)\nقال ثم انصرف وجاء جرير فقال قد رأيت هذا وسمعت ما قال في ابن أخيه وما ابن أخيه فعل الله به وفعل قال ومضى جرير فوالله ما لبثنا إلا جمعا حتى جاءنا جرير فقام مقامه ونعى ابنه سواده فقال","topic":"نسب جرير وأخباره","topicNo":75,"sp":26,"spl":"قرنهما عمر بن عبد العزيز لأنهما تقاذفا","loc":1423},
{"id":"b75-40","bab":"الجزء 8","sec":"رثاؤه ابنه","page":"ج8 ص90","text":"(أودى سوادة يجلو مقلتي لحم ... باز يصرصر فوق المربأ العالي)\n(فارقتني حين كف الدهر من بصري ... وحين صرت كعظم الرمة البالي)\n(إلا تكن لك بالديرين باكية ... فرب باكية بالرمل معوال)\n(قالوا نصيبك من أجر فقلت لهم ... كيف العزاء وقد فارقت أشبالي)\nخبرنا أبو خليفة قال حدثنا محمد بن سلام قال حدثني حاجب بن زيد وأبو الغراف قالا تزوج الفرزدق حدراء بنت زيق بن بسطام بن قيس على حكم أبيها فاحتكم مائة من الإبل فدخل على الحجاج يسأله ذلك فعذله وقال له أتتزوج امرأة على حكمها فقال عنبسة بن سعيد وأراد نفعه إنما هي من حواشي إبل الصدقة فأمر له الحجاج بها فوثب جرير فقال\n(يا زيق قد كنت من شيبان في حسب ... يا زيق ويحك من أنكحت يا زيق)\n(أنكحت ويحك قينا باسته حمم ... يا زيق ويحك هل بارت بك السوق)\n(غاب المثنى فلم يشهد نجيكما ... والحوفزان ولم يشهدك مفروق)\n(يا رب قائلة بعد البناء بها ... لا الصهر راض ولا ابن القين معشوق)\n(أين الألى استنزلوا النعمان ضاحية ... أم أين ابناء شيبان الغرانيق)\nال فلم يجبه الفرزدق عنها فقال جرير ايضا\n(فلا أنا معطي الحكم عن شف منصب ... ولا عن بنات الحنظليين راغب)\n(وهن كماء المزن يشفى به الصدى ... وكانت ملاحا غيرهن المشارب)\n(فلو كنت حرا كان عشرا سياقكم ... إلى آل زيق والوصيف المقارب)\nقال الفرزدق\n(فنل مثلها من مثلهم ثم لمهم ... على دارمي بين ليلى وغالب)\n(هم زوجوا قبلي لقيطا وأنكحوا ... ضرارا وهم أكفاؤنا في المناسب)\n(ولو قبلوا مني عطية سقته ... إلى مال زيق من وصيف مقارب)\n(ولو تنكح الشمس النجوم بناتها ... إذا لنكحناهن قبل الكواكب)\nال ابن سلام فحدثني الرازي عن أبيه قال ما كانت امرأة من بني حنظلة\nإلا ترفع لجرير اللوية في عظمها لتطرفه بها لقوله\n(وهن كماء المزن يشفى به الصدى ... وكانت ملاحا غيرهن المشارب)\nقلت للرازي ما اللوية قال الشريحة من اللحم أو الفدرة من التمر أو الكبة من الشحم أو الحفنة من الأقط فإذا ذهب الألبان وضاقت المعيشة كانت طرفة عندهم قال وقال جرير أيضا في شأن حدراء\n(أثائرة حدراء من جر بالنقا ... وهل لأبي حدراء في الوتر طالب)\n(أتثأر بسطاما إذا ابتلت استها ... وقد بولت في مسمعيه الثعالب)\nال ابن سلام والنقا الذي عناه جرير هو الموضع الذي قتلت فيه بنو ضبة بسطاما وهو بسطام بن قيس قال فكرهت بنو شيبان أن يهتك جرير أعراضهم فلما أراد الفرزدق نقل حدراء اعتلوا عليه وقالوا له إنها ماتت فقال جرير\n(فأقسم ما ماتت ولكنما التوى ... بحدراء قوم لم يروك لها أهلا)\n(رأوا أن صهر القين عار عليهم ... وأن لبسطام على غالب فضلا)\nخبرني حبيب بن نصر المهلبي قال حدثنا ابن أبي سعد قال حدثنا محمد بن إدريس اليمامي قال حدثنا علي بن عبد الله بن محمد بن مهاجر عن أبيه عن جده قال دخلنا على جرير في نفر من قريش نعوده في علته التي مات فيها فالتفت إلينا فقال\n(أهلا وسهلا بقوم زينوا حسبي ... وإن مرضت فهم أهلي وعوادي)\n(إن تجر طير بأمر فيه عافية ... أو بالفراق فقد أحسنتم زادي)\nلو أن ليثا أبا شبلين أوعدني ... لم يسلموني لليث الغابة العادي","topic":"نسب جرير وأخباره","topicNo":75,"sp":27,"spl":"رثاؤه ابنه — من المائة المختارة من رواية علي بن يحيى","loc":1424},
{"id":"b75-41","bab":"الجزء 8","sec":"رثاؤه الفرزدق","page":"ج8 ص93","text":"أخبرني أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح قال حدثني أبو جناح أحد بني كعب بن عمرو بن تميم قال نعي الفرزدق إلى المهاجر بن عبد الله وجرير عنده فقال\n(مات الفرزدق بعد ما جدعته ... ليت الفرزدق كان عاش قليلا)\nقال له المهاجر بئس لعمر الله ما قلت في ابن عمك أتهجو ميتا أما والله لو رثيته لكنت أكرم العرب وأشعرها فقال إن رأى الأمير أن يكتمها علي فإنها سوءة ثم قال من وقته\n(فلا وضعت بعد الفرزدق حامل ... ولا ذات بعل من نفاس تعلت)\n(هو الوافد الميمون والراتق الثأى ... إذا النعل يوما بالعشيرة زلت)\nال ثم بكى ثم قال أما والله إني لأعلم أني قليل البقاء بعده ولقد كان نجمنا واحدا وكل واحد منا مشغول بصاحبه وقلما مات ضد أو صديق إلا\nتبعه صاحبه فكان كذلك مات بعد سنة وقد زاد الناس في بيتي جرير هذين أبياتا أخر ولم يقل غيرهما وإنما أضيف إلى ما قاله","topic":"نسب جرير وأخباره","topicNo":75,"sp":27,"spl":"رثاؤه ابنه — من المائة المختارة من رواية علي بن يحيى","song":1,"loc":1425},
{"id":"b75-42","bab":"الجزء 8","sec":"من المائة المختارة من رواية علي بن يحيى","page":"ج8 ص94","text":"(رحل الخليط جمالهم بسواد ... وحدا على إثر البخيلة حادي)\n(ما إن شعرت ولا علمت ببينهم ... حتى سمعت به الغراب ينادي)\nلشعر لجميل والغناء لإبراهيم ولحنه المختار من الثقيل الأول بإطلاق الوتر في مجرى الوسطى","topic":"نسب جرير وأخباره","topicNo":75,"sp":27,"spl":"رثاؤه ابنه — من المائة المختارة من رواية علي بن يحيى","loc":1426},
{"id":"b76-1","bab":"الجزء 8","sec":"نسب جميل وأخباره","page":"ج8 ص95","text":"هو جميل بن عبد الله بن معمر بن الحارث بن ظبيان وقيل ابن معمر بن حن بن ظبيان بن قيس بن جزء بن ربيعة بن حرام بن ضنة بن عبد بن كثير بن عذرة بن سعد وهو هذيم وسمي بذلك إضافة لاسمه إلى عبد لأبيه يقال له هذيم كان يحضنه فغلب عليه ابن زيد بن سود بن اسلم بن الحاف بن قضاعة والنسابون مختلفون في قضاعة فمنهم من يزعم أن قضاعة بن معد وهو أخو نزار بن معد لأبيه وأمه وهي معانة بنت جوسم بن جلهمة بن عامر بن عوف بن عدي بن دب بن جرهم ومنهم من يزعم أنهم من حمير وقد ذكر جميل ذلك في شعره فانتسب معديا فقال\n(أنا جميل في السنام من معد ... في الأسرة الحصداء والعيص الأشد)\nقال راجز من قضاعة ينسبهم إلى حمير\n(قضاعة الأثرون خير معشر ... قضاعة بن مالك بن حمير)\nلهم في هذا أراجيز كثيرة إلا أن قضاعة اليوم تنسب كلها في حمير فتزعم أن قضاعة بن مالك بن مرة بن زيد بن مالك بن حمير بن سبأ بن\nيشجب بن يعرب بن قحطان وقال القحذمي اسم سبأ عامر وإنما قيل له سبأ لأنه أول من سبى النساء وكان يقال له عب الشمس أي عديل الشمس سمي بذلك لحسنه ومن زعم من هؤلاء أن قضاعة ليس ابن معد ذكر أن أمه عكبرة امرأة من سبأ كانت تحت مالك بن عمر فمات عنها وهي حامل فخلفه عليها معد بن عدنان فولدت قضاعة على فراشه وقال مؤرج بن عمرو هذا قول أحدثوه بعد وصنعوا شعرا ألصقوه به ليصححوا هذا القول وهو\n(يا أيها الداعي ادعنا وأبشر ... وكن قضاعيا ولا تنزر)\n(قضاعة الأثرون خير معشر ... قضاعة بن مالك بن حمير)\n(النسب المعروف غير المنكر ... )\nال مؤرج وهذا شيء قيل في آخر أيام بني أمية وشعراء قضاعة في الجاهلية والإسلام كلها تنتمي إلى معد قال جميل\n(وأي معد كان فيء رماحهم ... كما قد أفأنا والمفاخر منصف)\nقال زيادة بن زيد يهجو بني عمه بني عامر رهط هدبة بن خشرم\n(وإذا معد أوقدت نيرانها ... للمجد أغضت عامر وتضعضعوا)","topic":"نسب جميل وأخباره","topicNo":76,"sp":0,"spl":"نسب جميل وأخباره","loc":1427,"partial":1},
{"id":"b76-2","bab":"الجزء 8","sec":"روى له كثير","page":"ج8 ص96","text":"وجميل شاعر فصيح مقدم جامع للشعر والرواية كان راوية هدبة بن\nخشرم وكان هدبة شاعرا راوية للحطيئة وكان الحطيئة شاعرا راوية لزهير وابنه وقال أبو محلم آخر من اجتمع له الشعر والرواية كثير وكان راوية جميل وجميل راوية هدبة وهدبة راوية الحطيئة والحطيئة راوية زهير أخبرني هاشم بن محمد قال حدثنا عيسى بن إسماعيل عن القحذمي قال كان جميل يهوى بثينة بنت حبأ بن ثعلبة بن الهوذ بن عمرو بن الأحب بن حن بن ربيعة تلتقي هي وجميل في حن من ربيعة في النسب حدثني أبو الحسن أحمد بن محمد الأسدي وهاشم بن محمد أو دلف الخزاعي قالا حدثنا الرياشي قال حدثنا الأصمعي عن ابن أبي الزناد قال كان كثير راوية جميل وكان يقدمه على نفسه ويتخذه إماما وإذا سئل عنه قال وهل علم الله عز و جل ما تسمعون إلا منه أخبرني محمد بن مزيد عن حماد عن أبيه عن صباح بن خاقان عن عبد الله بن معاوية الزبيري قال كان كثير إذا ذكر له جميل قال وهل علم الله ما تسمعون إلا منه أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد بن إسماعيل عن عبد العزيز بن عمران عن المسور بن عبد الملك عن نصيب مولى عبد العزيز بن مروان قال\nقدمت المدينة فسألت عن اعلم أهلها بالشعر فقيل لي الوليد بن سعيد بن أبي سنان الأسلمي فوجدته بشعب سلع مع عبد الرحمن بن حسان وعبد الرحمن بن أزهر فإنا لجلوس إذ طلع علينا رجل طويل بين المنكبين طوال يقود راحلة عليها بزة حسنة فقال عبد الرحمن بن حسان لعبد الرحمن بن أزهر يا أبا جبير هذا جميل فأدعه لعله أن ينشدنا فصاح به عبد الرحمن هيا جميل هيا جميل فالتفت فقال من هذا فقال أنا عبد الرحمن بن أزهر فقال قد علمت أنه لا يجترىء علي إلا مثلك فأتاه فقال له أنشدنا فأنشدهم\n(نحن منعنا يوم أول نساءنا ... ويوم أفي والأسنة ترعف)\n(ويوم ركايا ذي الجذاة ووقعة ... ببنيان كانت بعض ما قد تسلفوا)\n(يحب الغواني البيض ظل لوائنا ... إذا ما أتانا الصارخ المتلهف)\n(نسير أمام الناس والناس خلفنا ... فإن نحن أومأنا إلى الناس وقفوا)\n(فأي معد كان فيء رماحه ... كما قد أفأنا والمفاخر ينصف)\n(وكنا إذا ما معشر نصبوا لنا ... ومرت جواري طيرهم وتعيفوا)\n(وضعنا لهم صاع القصاص رهينة ... بما سوف نوفيها إذا الناس طففوا)\n(إذا استبق الأقوام مجدا وجدتنا ... لنا مغرفا مجد وللناس مغرف)\nال ثم قال له أنشدنا هزجا قال وما الهزج لعله هذا القصير قال\nنعم فأنشده قال الزبير لم يذكر في هذا الخبر من هذه القصيدة الهزج سوى بيتين وأنشدنا باقيها بهلول بن سليمان بن قرضاب البلوي\n(رسم دار وقفت في طلله ... كدت أقضي الغداة من جلله)\n(موحشا ما ترى به أحدا تنتسج ... الريح ترب معتدله)\n(وصريعا من الثمام ترى ... عارمات المدب في أسله)\n(بين علياء وابش فبلي ... فالغميم الذي إلى جبله)\n(واقفا في ديار أم جسير ... من ضحى يومه إلى أصله)\n(يا خليلي إن أم جسير ... حين يدنو الضجيج من غلله)\n(روضة ذات حنوة وخزامى ... جاد فيها الربيع من سبله)\n(بينما هن بالأراك معا ... إذ بدا راكب على جمله)\n(فتأطرن ثم قلن لها ... أكرميه حييت في نزله)\n(فظللنا بنعمة واتكأنا ... وشربنا الحلال من قلله)\n(قد أصون الحديث دون خليل ... لا أخاف الأذاة من قبله)\n(غير ما بغضة ولا لاجتناب ... غير أني ألحت من وجله)\n(وخليل صاقبت مرتضيا ... وخليل فارقت من ملله)\nال فأنشده إياها حتى فرغ منها ثم اقتاد راحلته موليا فقال ابن الأزهر هذا أشعر أهل الإسلام فقال ابن حسان نعم والله وأشعر أهل الجاهلية والله ما لأحد منهم مثل هجائه ولا نسيبه فقال عبد الرحمن بن الأزهر صدقت قال نصيب وأنشدت الوليد فقال لي أنت أشعر أهل جلدتك والله ما زاد عليها فقلت يا أبا محجن أرضيت منه بأن تكون أشعر السودان قال وددت والله يا أبن أخي أنه أعطاني أكثر من هذا ولكنه لم يفعل ولست بكاذبك","topic":"نسب جميل وأخباره","topicNo":76,"sp":1,"spl":"روى له كثير","song":1,"loc":1428},
{"id":"b76-3","bab":"الجزء 8","sec":"كان مقدما في النسيب على غيره","page":"ج8 ص100","text":"أخبرني أبو خليفة عن محمد بن سلام قال كان لكثير في النسب حظ وافر وجميل مقدم عليه وعلى أصحاب النسيب في النسيب وكان كثير راوية جميل وكان جميل صادق الصبابة والعشق ولم يكن كثير بعاشق ولكنه كان يتقول وكان الناس يستحسنون بيت كثير في النسيب\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nال ورأيت من يفضل عليه بيت جميل\n(خليلي فيما عشتما هل رأيتما ... قتيلا بكى من حب قاتله قبلي)\nقال ابن سلام وهذا البيت الذي لكثير أخذه من جميل حيث يقول\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى على كل مرقب)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار عن محمد بن إسماعيل عن عبد العزيز بن عمران عن محمد بن عبد العزيز عن أبي شهاب طلحة بن عبد الله بن عوف قال لقي الفرزدق كثيرا بقارعة البلاط وأنا وهو نمشي نريد المسجد فقال له الفرزدق يا أبا صخر أنت أنسب العرب حين تقول\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nعرض له بسرقته من جميل فقال له كثير وأنت يا أبا فراس أفخر الناس حين تقول\n(ترى الناس ما سرنا يسيرون خلفنا ... وإن نحن أومأنا إلى الناس وقفوا)\nال عبد العزيز وهذا البيت أيضا لجميل سرقة الفرزدق فقال الفرزدق لكثير هل كانت أمك مرت بالبصرة قال لا ولكن أبي فكان نزيلا لأمك قال طلحة بن عبد الله فوالذي نفسي بيده لعجبت من كثير وجوابه وما رأيت أحدا قط أحمق منه رأيتني دخلت عليه يوما في نفر من قريش وكنا كثيرا ما نتهزأ به فقلنا كيف تجدك يا أبا صخر قال بخير أما سمعتم الناس يقولون شيئا قلنا نعم يتحدثون أنك الدجال فقال والله\nلئن قلتم ذاك إني لأجد في عيني هذه ضعفا منذ أيام أخبرني الحرمي قال حدثنا الزبير قال كتب إلي أبو محمد إسحاق بن إبراهيم يقول حدثني أبو عبيدة عن جويرية بن أسماء قال كان أبو صخر كثير صديقا لي وكان يأتيني كثيرا فقلما استنشدته إلا بدأ بجميل وأنشد له ثم أنشد لنفسه وكان يفضله ويتخذه إماما قال الزبير وكتب إلي إسحاق يقول حدثني صباح بن خاقان عن عبد الله بن معاوية بن عاصم بن المنذر بن الزبير قال ذكر جميل لكثير فقالوا ما تقول فيه فقال منه علم الله عز و جل أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني أبو يحيى الزهري عن إسحاق بن قبيصة الكوفي عن رجل سماه قال سألت نصيبا أجميل أنسب أم كثير فقال أنا سألت كثيرا عن ذاك فقال وهل وطأ لنا النسيب إلا جميل قال عمر بن شبة وقال إسحاق حدثني السعيدي عن أبي مالك النهدي قال جلس إلينا نصيب فذكرنا جميلا فقال ذاك إمام المحبين وهل هدى الله عز و جل لما ترى إلا بجميل أخبرني هاشم بن محمد قال حدثنا دماذ عن أبي عبيدة عن جويرية بن\nأسماء قال ما استنشدت كثيرا قط إلا بدأ بجميل وأنشدني له ثم أنشدني بعده لنفسه وكان يفضله ويتخذه إماما أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني بهلول بن سليمان بن قرضاب البلوي قال","topic":"نسب جميل وأخباره","topicNo":76,"sp":2,"spl":"كان مقدما في النسيب على غيره","loc":1429},
{"id":"b76-4","bab":"الجزء 8","sec":"خبر تعرفه ببثينة","page":"ج8 ص103","text":"كان جميل ينسب بأم الجسير وكان أول ما علق بثينة أنه أقبل يوما بإبله حتى أوردها واديا يقال له بغيض فاضطجع وأرسل إبله مصعدة وأهل بثينة بذنب الوادي فأقبلت بثينة وجارة لها واردتين الماء فمرتا على فصال له بروك فعرمتهن بثينة يقول نفرتهن وهي إذ ذاك جويرية صغيرة فسبها جميل فأفترت عليه فملح إليه سبابها فقال\n(وأول ما قاد المودة بيننا ... بوادي بغيض يا بثين سباب)\n(وقلنا لها قولا فجاءت بمثله ... لكل كلام يا بثين جواب)\nال الزبير وحدثني محمد بن إسماعيل بن جعفر عن سعيد بن نبيه بن الأسود العذري وكانت بثينة عند أبيه نبيه بن الأسود وإياه يعني جميل بقوله\n(لقد أنكحوا جهلا نبيها ظعينة ... لطيفة طي الكشح ذات شوى خدل)\nال الزبير وحدثني أيضا الأسباط بن عيسى بن عبد الجبار العذري أن جميل بن معمر خرج في يوم عيد والنساء إذ ذاك يتزين ويبدو بعضهن لبعض ويبدون للرجال وأن جميلا وقف على بثينة وأختها أم الجسير في نساء من بني\nالأحب وهن بنات عم عبيد الله بن قطبة أخي أبيه لحا فرأى منهن منظرا وأعجبنه وعشق بثينة وقعد معهن ثم راح وقد كان معه فتيان من بني الأحب فعلم أن القوم قد عرفوا في نظره حب بثينة ووجدوا عليه فراح وهو يقول\n(عجل الفراق وليته لم يعجل ... وجرت بوادر دمعك المتهلل)\n(طربا وشاقك ما لقيت ولم تخف ... بين الحبيب غداة برقة مجول)\n(وعرفت انك حين رحت ولم يكن ... بعد اليقين وليس ذاك بمشكل)\n(لن تستطيع إلى بثينة رجعة ... بعد التفرق دون عام مقبل)\nال وإن بثينة لما أخبرت أن جميلا قد نسب بها حلفت بالله لا يأتيها على خلاء إلا خرجت إليه ولا تتوارى منه فكان يأتيها عند غفلات الرجال فيتحدث إليها ومع أخواتها حتى نمي إلى رجالها أنه يتحدث إليها إذا خلا منهم وكانوا أصلافا غيرا أو قال غيارى فرصدوه بجماعة نحو من بضعة عشر رجلا وجاء على الصهباء ناقته حتى وقف على بثينة وأم الجسير وهما يحدثانه وهو ينشدهما يومئذ\n(حلفت برب الراقصات إلى منى ... هوي القطا يجتزن بطن دفين)\n(لقد ظن هذا القلب أن ليس لاقيا ... سليمى ولا أم الجسير لحين)\n(فليت رجالا فيك قد نذروا دمي ... وهموا بقتلي يا بثين لقوني)\nبينا هو على تلك الحال إذ وثب عليه القوم فرماهم بها فسبقت به وهو يقول\n(إذا جمع الاثنان جمعا رميتهم ... بأركانها حتى تخلى سبيلها)\nكان هذا أول سبب المهاجاة بينه وبين عبيد الله بن قطبة","topic":"نسب جميل وأخباره","topicNo":76,"sp":3,"spl":"خبر تعرفه ببثينة","loc":1430},
{"id":"b76-5","bab":"الجزء 8","sec":"تشكيه في شعره","page":"ج8 ص105","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثنا بهلول بن سليمان عن مشيخة من عذرة أن بثينة واعدت جميلا أن يلتقيا في بعض المواضع فأتى لوعدها وجاء أعرابي يستضيف القوم فأنزلوه وقروه فقال لهم قد رأيت في بطن هذا الوادي ثلاثة نفر متفرقين متوارين في الشجر وأنا خائف عليكم أن يسلبوا بعض إبلكم فعرفوا أنه جميل وصاحباه فحرسوا بثينة ومنعوها من الوفاء بوعده فلما أسفر له الصبح انصرف كئيبا سيء الظن بها ورجع إلى أهله فجعل نساء الحي يقرعنه بذلك ويقلن له إنما حصلت منها على الباطل والكذب والغدر وغيرها أولى بوصلك منها كما أن غيرك يحظى بها فقال في ذلك\n(أبثين إنك قد ملكت فأسجحي ... وخذي بحظك من كريم واصل)\n(فأجبتها في القول بعد تستر ... حبي بثينة عن وصالك شاغلي)\n(فلرب عارضة علينا وصلها ... بالجد تخلطه بقول الهازل)\n(لو كان في صدري كقدر قلامة ... فضلا وصلتك أو أتتك رسائلي)\nلغناء ليحيى المكي ثقيل أول بالوسطى من رواية ابنه أحمد عنه\n(ويقلن إنك قد رضيت بباطل ... منها فهل لك في اجتناب الباطل)\n(ولباطل مما أحب حديثه ... أشهى إلي من البغيض الباذل)\n(ليزلن عنك هواي ثم يصلنني ... وإذا هويت فما هواي بزائل)\nلغناء لسليم رمل بالوسطى عن عمرو وذكر في نسخته الثانية أنه ليزيد حوراء وروى حماد عن أبيه في أخبار ابن سريج أن لابن سريج فيه لحنا ولم يجنسه\n(صادت فؤادي يا بثين حبالكم ... يوم الحجون وأخطأتك حبائلي)\n(منيتني فلويت ما منيتني ... وجعلت عاجل ما وعدت كآجل)\n(وتثاقلت لمأ رأت كلفي بها ... أحبب إلي بذاك من متثاقل)\n(وأطعت في عواذلا فهجرتني ... وعصيت فيك وقد جهدن عواذلي)\n(حاولنني لأبت حبل وصالكم ... مني ولست وإن جهدن بفاعل)\n(فرددتهن وقد سعين بهجركم ... لما سعين له بأفوق ناصل)\n(يعضضن من غيظ علي أناملا ... ووددت لو يعضضن صم جنادل)\n(ويقلن إنك يا بثين بخيلة ... نفسي فداؤك من ضنين باخل)\nالوا وقال جميل في وعد بثينة بالتلاقي وتأخرها قصيدة أولها\n(يا صاح عن بعض الملامة أقصر ... إن المنى للقاء أم المسور)\nمما يغنى فيه منها قوله\n(وكأن طارقها على علل الكرى ... والنجم وهنا قد دنا لتغور)\n(يستاف ريح مدامة معجونة ... بذكي مسك أو سحيق العنبر)\nلغناء لابن جامع ثقيل أول بالبنصر من رواية الهشامي وذكر عمرو بن بانة أنه لابن المكي ومما يغنى فيه منها قوله\n(إني لأحفظ غيبكم ويسرني ... إذ تذكرين بصالح أن تذكري)\n(ويكون يوم لا أرى لك مرسلا ... أو نلتقي فيه علي كأشهر)\n(يا ليتني ألقى المنية بغتة ... إن كان يوم لقائكم لم يقدر)\n(أو أستطيع تجلدا عن ذكركم ... فيفيق بعض صبابتي وتفكري)\nلغناء لابن محرز خفيف رمل بالوسطى عن الهشامي وفيه يقول\n(لو قد تجن كما أجن من الهوى ... لعذرت أو لظلمت إن لم تعذر)\n(والله ما للقلب من علم بها ... غير الظنون وغير قول المخبر)\n(لا تحسبي أني هجرتك طائعا ... حدث لعمرك رائع أن تهجري)\n(فلتبكين الباكيات وإن أبح ... يوما بسرك معلنا لم أعذر)\n(يهواك ما عشت الفؤاد فإن أمت ... يتبع صداي صداك بين الأقبر)\n(صوت ... )\n(إني إليك بما وعدت لناظر ... نظر الفقير إلى الغني المكثر)\n(يعد الديون وليس ينجز موعدا ... هذا الغريم لنا وليس بمعسر)\n(ما أنت والوعد الذي تعدينني ... إلا كبرق سحابة لم تمطر)\n(قلبي نصحت له فرد نصيحتي ... فمتى هجرتيه فمنه تكثري)\nلغناء في هذه الأبيات لسليم رمل عن الهشامي وفيه قدح طنبوري اظنه لجحظة أو لعلي بن مودة قالوا وقال في إخلافها إياه هذا الموعد\n(ألا ليت ريعان الشباب جديد ... ودهرا تولى يا بثين يعود)\n(فنغنى كما كنا نكون وأنتم ... قريب وإذ ما تبذلين زهيد)\nويروى\n(ومما لا يزيد بعيد ... )\nهكذا يغنى فيه الغناء لسليم خفيف ثقيل أول بالوسطى ومما يغنى فيه من هذه القصيدة\n(ألا ليت شعري هل أبيتن ليلة ... بوادي القرى إني إذا لسعيد)\n(وهل ألقين فردا بثينة مرة ... تجود لنا من ودها ونجود)\n(علقت الهوى منها وليدا فلم يزل ... إلى اليوم ينمي حبها ويزيد)\n(وأفنيت عمري بانتظاري وعدها ... وأبليت فيها الدهر وهو جديد)\n(فلا أنا مردود بما جئت طالبا ... ولا حبها فيما يبيد يبيد)\nلغناء لمعبد ثقيل أول بالوسطى ومما يغنى فيه منها\n\n(وما أنس م الأشياء لا أنس قولها ... وقد قربت بصرى أمصر تريد)","topic":"نسب جميل وأخباره","topicNo":76,"sp":4,"spl":"تشكيه في شعره","song":7,"loc":1431,"partial":1},
{"id":"b76-6","bab":"الجزء 8","sec":"تشكيه في شعره","page":"ج8 ص105","text":"(ولا قولها لولا العيون التي ترى ... لزرتك فاعذرني فدتك جدود)\n(خليلي ما ألقى من الوجد قاتلي ... ودمعي بما قلت الغداة شهيد)\n(يقولون جاهد يا جميل بغزوة ... وأي جهاد غيرهن أريد)\n(لكل حديث بينهن بشاشة ... وكل قتيل عندهن شهيد)\nلغناء للغريض خفيف ثقيل من رواية حماد عن أبيه وفي هذه القصيدة يقول\n(إذا قلت ما بي يا بثينة قاتلي ... من الحب قالت ثابت ويزيد)\n(وإن قلت ردي بعض عقلي أعش به ... مع الناس قالت ذاك منك بعيد)\n(ألا قد أرى والله أن رب عبرة ... إذا الدار شطت بيننا سترود)\n(إذا فكرت قالت قد ادركت وده ... وما ضرني بخلي فكيف أجود)\n(فلو تكشف الأحشاء صودف تحتها ... لبثنة حب طارف وتليد)\nتذكرنيها كل ريح مريضة ... لها بالتلاع القاويات وئيد\n(وقد تلتقي الأشتات بعد تفرق ... وقد تدرك الحاجات وهي بعيد)","topic":"نسب جميل وأخباره","topicNo":76,"sp":5,"spl":"تشكيه في شعره — التقى بثينة بعد غياب فتعاتبا","loc":1432},
{"id":"b76-7","bab":"الجزء 8","sec":"التقى بثينة بعد غياب فتعاتبا","page":"ج8 ص111","text":"أخبرني علي بن صالح قال حدثني عمر بن شبة عن إسحاق قال لقي جميل بثينة بعد تهاجر كان بينهما طالت مدته فتعاتبا طويلا فقالت له ويحك يا جميل أتزعم أنك تهواني وأنت الذي تقول\n(رمى الله في عيني بثينة بالقذى ... وفي الغر من أنيابها بالقوادح)\nأطرق طويلا يبكي ثم قال بل أنا القائل\n(ألا ليتني أعمى أصم تقودني ... بثينة لا يخفى علي كلامها)\nقالت له ويحك ما حملك على هذه المنى أوليس في سعة العافية ما كفانا جميعا قال إسحاق وحدثني أيوب بن عباية قال سعت أمة لبثينة بها إلى أبيها وأخيها وقالت لهما إن جميلا عندها الليلة فأتياها مشتملين على سيفين فرأياه جالسا حجرة منها يحدثها ويشكو إليها بثه ثم قال لها يا بثينة أرأيت ودي إياك وشغفي بك ألا تجزينيه قالت بماذا قال بما يكون بين المتحابين فقالت له يا جميل أهذا تبغي والله لقد كنت عندي بعيدا منه ولئن عاودت تعريضا بريبة لا رأيت وجهي أبدا فضحك وقال والله ما قلت لك هذا إلا لأعلم ما عندك فيه ولو علمت أنك تجيبينني إليه لعلمت أنك تجيبين غيري ولو رأيت منك مساعدة عليه لضربتك\nبسيفي هذا ما استمسك في يدي ولو أطاعتني نفسي لهجرتك هجرة الأبد أو ما سمعت قولي\n(وإني لأرضى من بثينة بالذي ... لو ابصره الواشي لقرت بلابله)\n(بلا وبأن لا أستطيع وبالمنى ... وبالأمل المرجو قد خاب آمله)\n(وبالنظرة العجلى وبالحول تنقضي ... أواخره لا نلتقي وأوائله)\nال فقال أبوها لأخيها قم بنا فما ينبغي لنا بعد اليوم أن نمنع هذا الرجل من لقائها فانصرفا وتركاهما أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن أيوب بن عباية عن رجل من عذرة قال كنت تربا لجميل وكان يألفني فقال لي ذات يوم هل تساعدني على لقاء بثينة فمضيت معه فكمن لي في الوادي وبعث بي إلى راعي بثينة بخاتمه فدفعته إليه فمضى به إليها ثم عاد بموعد منها إليه فلما كان الليل جاءته فتحدثا طويلا حتى أصبحا ثم ودعها وركب ناقته فلما استوى في غرزها وهي باركة قالت له ادن مني يا جميل\n(إن المنازل هيجت أطرابي ... واستعجمت آياتها بجوابي)\n(قفرا تلوح بذي اللجين كأنها ... أنضاء رسم أو سطور كتاب)\n(لما وقفت بها القلوص تبادرت ... مني الدموع لفرقة الأحباب)\n(وذكرت عصرا يا بثينة شاقني ... وذكرت أيامي وشرخ شبابي)\nلغناء في هذه الأبيات للهذلي ثاني ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق","topic":"نسب جميل وأخباره","topicNo":76,"sp":5,"spl":"تشكيه في شعره — التقى بثينة بعد غياب فتعاتبا","song":1,"loc":1433},
{"id":"b76-8","bab":"الجزء 8","sec":"كثير يسعى لجمعهما","page":"ج8 ص113","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا إسحاق الموصلي عن السعيدي وأخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال حدثنا أبو مالك النهدي قال جلس إلينا كثير ذات يوم فتذاكرنا جميلا فقال لقيني مرة فقال لي من أين أقبلت قلت من عند أبي الحبيبة أعني بثينة فقال وإلى أين تمضي قلت إلى الحبيبة أعني عزة فقال لا بد من أن ترجع عودك على بدئك فتستجد لي موعدا من بثينة فقلت عهدي بها الساعة وأنا أستحيي أن أرجع فقال لا بد من ذلك فقلت له فمتى عهدك ببثينة فقال في أول الصيد وقد وقعت سحابة بأسفل وادي الدوم فخرجت ومعها جارية لها تغسل ثيابها فلما أبصرتني أنكرتني فضربت بيديها إلى ثوب في الماء فالتحفت به وعرفتني الجارية فأعادت الثوب في الماء وتحدثنا حتى غابت الشمس وسألتها الموعد فقالت أهلي سائرون وما وجدت أحدا آمنه فأرسله إليها فقال له كثير فهل لك في أن آتي الحي فأنزع بأبيات من شعر أذكر فيها هذه العلامة إن لم أقدر على الخلوة بها قال ذلك الصواب فأرسله إليها فقال له انتظرني ثم خرج كثير حتى أناخ بهم فقال له أبوها ما ردك قال ثلاثة\nأبيات عرضت لي فأحببت أن أعرضها عليك قال هاتها قال كثير فأنشدته وبثينة تسمع\n(فقلت لها يا عز أرسل صاحبي ... إليك رسولا والموكل مرسل)\n(بأن تجعلي بيني وبينك موعدا ... وأن تأمريني ما الذي فيه أفعل)\n(وآخر عهدي منك يوم لقيتني ... بأسفل وادي الدوم والثوب يغسل)\nال فضربت بثينة جانب خدرها وقالت إخسأ إخسأ فقال أبوها مهيم يا بثينة قالت كلب يأتينا إذا نوم الناس من وراء الرابية ثم قالت للجارية ابغينا من الدومات حطبا لنذبح لكثير شاة ونشويها له فقال كثير أنا أعجل من ذلك وراح إلى جميل فأخبره فقال له جميل الموعد الدومات وقالت لأم الحسين وليلى ونجيا بنات خالتها وكانت قد أنست إليهن واطمأنت بهن إني قد رأيت في نحو نشيد كثير أن جميلا معه وخرج كثير وجميل حتى أتيا الدومات وجاءت بثينة ومن معها فما برحوا حتى برق الصبح فكان كثير يقول ما رأيت مجلسا قط أحسن من ذلك ولا مثل علم أحدهما بضمير الآخر ما أدري أيهما كان أفهم أخبرني محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري عن الهيثم بن عدي وأخبرني عمي عن الكراني عن العمري عن الهيثم بن عدي قال قال لي صالح بن حسان\nهل تعرف بيتا نصفه أعرابي في شملة وآخره مخنث من أهل العقيق يتقصف تقصفا قلت لا قال قد أجلتك حولا قلت لا أدري ما هو فقال قول جميل\n(ألا أيها النوام ويحكم هبوا ... )\nأنه أعرابي في شملة ثم أدركه ما يدرك العاشق فقال\n(أسائلكم هل يقتل الرجل الحب ... )\nأنه من كلام مخنثي العقيق","topic":"نسب جميل وأخباره","topicNo":76,"sp":6,"spl":"كثير يسعى لجمعهما — ماذا فعل بعد أن أهدر السلطان دمه","loc":1434,"partialRef":{"sid":"b33-64","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b76-9","bab":"الجزء 8","sec":"ماذا فعل بعد أن أهدر السلطان دمه","page":"ج8 ص115","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير بن حرب قال أخبرنا عبد الله بن أبي كريم عن أبي عمرو وإسحاق بن مروان قال عشق جميل بثينة وهو غلام فلما بلغ خطبها فمنع منها فكان يقول فيها الأشعار حتى اشتهر وطرد فكان يأتيها سرا ثم تزوجت فكان يزورها في بيت زوجها في الحين خفية إلى أن استعمل دجاجة بن ربعي على وادي القرى فشكوه إليه فتقدم إليه ألا يلم بأبياتها وأهدر دمه لهم إن عاود زيارتها فاحتبس حينئذ أخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل مولى المنصور قال حدثنا أحمد بن أبي العلاء قال حدثني إبراهيم الرماح قال حدثنا جابر أبو العلاء التنوخي قال لما نذر أهل بثينة دم جميل وأهدره لهم السلطان ضاقت الدنيا بجميل\nفكان يصعد بالليل على قور رمل يتنسم الريح من نحو حي بثينة ويقول\n(أيا ريح الشمال أما تريني ... أهيم وأنني بادي النحول)\n(هبي لي نسمة من ريح بثن ... ومني بالهبوب إلى جميل)\n(وقولي يا بثينة حسب نفسي ... قليلك أو أقل من القليل)\nإذا بدا وضح الصبح انصرف وكانت بثينة تقول لجوار من الحي عندها ويحكن إني لأسمع أنين جميل من بعض القيران فيقلن لها اتقي الله فهذا شيء يخيله لك الشيطان لا حقيقة له","topic":"نسب جميل وأخباره","topicNo":76,"sp":6,"spl":"كثير يسعى لجمعهما — ماذا فعل بعد أن أهدر السلطان دمه","loc":1435},
{"id":"b76-10","bab":"الجزء 8","sec":"تذاكر النسيب مع كثير","page":"ج8 ص116","text":"حدثني أحمد بن عمار قال حدثني يعقوب بن نعيم قال حدثني أحمد بن يعلى قال حدثني سويد بن عصام قال حدثني روح أبو نعيم قال التقى جميل وكثير فتذاكرا النسيب فقال كثير يا جميل اترى بثينة لم تسمع بقولك\n(يقيك جميل كل سوء أما له ... لديك حديث أو إليك رسول)\n(وقد قلت في حبي لكم وصبابتي ... محاسن شعر ذكرهن يطول)\n(فإن لم يكن قولي رضاك فعلمي ... هبوب الصبا يا بثن كيف أقول)\n(فما غاب عن عيني خيالك لحظة ... ولا زال عنها والخيال يزول)\nقال جميل أترى عزة يا كثير لم تسمع بقولك\n(يقول العدا يا عز قد حال دونكم ... شجاع على ظهر الطريق مصمم)\n(فقلت لها والله لو كان دونكم ... جهنم ما راعت فؤادي جهنم)\n(وكيف يروع القلب يا عز رائع ... ووجهك في الظلماء للسفر معلم)\n(وما ظلمتك النفس يا عز في الهوى ... فلا تنقمي حبي فما فيه منقم)\nال فبكيا قطعة من الليل ثم انصرفا وقال الهيثم بن عدي ومن ذكر روايته معه من أصحابه زار جميل بثينة ذات يوم فنزل قريبا من الماء يترصد أمة لها أو راعية فلم يكن نزوله بعيدا من ورود أمة حبشية معها قربة وكانت به عارفة وبما بينها وبينه فسلمت عليه وجلست معه وجعل يحدثها ويسألها عن أخبار بثينة ويحدثها بخبره بعدها ويحملها رسائله ثم أعطاها خاتمه وسألها دفعه إلى بثينة وأخذ موعد عليها ففعلت وانصرفت إلى أهلها وقد أبطأت عليهم فلقيها أبو بثينة وزوجها وأخوها فسألوها عما أبطأ بها فالتوت عليهم ولم تخبرهم وتعللت فضربوها ضربا مبرحا فأعلمتهم حالها مع جميل ودفعت إليهم خاتمه ومر بها في تلك الحال فتيان من بني عذرة فسمعا القصة كلها وعرفا الموضع الذي فيه جميل فأحبا أن يثبطا عنه فقالا للقوم إنكم إن لقيتم جميلا وليست بثينة معه ثم قتلتموه لزمكم في ذلك كل مكروه وأهل بثينة أعز عذرة فدعوا الأمة توصل خاتمه إلى بثينة فإذا زارها بيتموهما جميعا قالوا صدقتما لعمري إن هذا الرأي فدفعوا الخاتم إلى الأمة وأمروها بإيصاله وحذروها أن تخبر بثينة بأنهم علموا القصة ففعلت ولم تعلم بثينة بما جرى ومضى الفتيان فأنذرا جميلا فقال والله ما أرهبهم وإن في كنانتي ثلاثين سهما والله لا أخطأ كل واحد منها رجلا منهم وهذا سيفي والله ما أنا به رعش اليد ولا جبان الجنان فناشداه الله وقالا البقية أصلح فتقيم عندنا\nفي بيوتنا حتى يهدأ الطلب ثم نبعث إليها فتزورك وتقضي من لقائها وطرا وتنصرف سليما غير مؤبن فقال أما الآن فابعثا إليها من ينذرها فأتياه براعية لهما وقالا له قل بحاجتك فقال ادخلي إليها وقولي لها إني أردت اقتناص ظبي فحذره ذلك جماعة اعتوروه من القناص ففاتني الليلة فمضت فأعلمتها ما قال لها فعرفت قصته وبحثت عنها فعرفتها فلم تخرج لزيارته تلك الليلة ورصدوها فلم تبرح مكانها ومضوا يقتصون أثره فرأوه بعر ناقته فعرفوا أنه قد فاتهم فقال جميل في ذلك\n(خليلي عوجا اليوم حتى تسلما ... على عذبة الأنياب طيبة النشر)\n(ألما بها ثم اشفعا لي وسلما ... عليها سقاها الله من سبل القطر)\n(إذا ما دنت زدت اشتياقا وإن نأت ... جزعت لنأي الدار منها وللبعد)\n(أبى القلب إلآ حب بثنة لم يرد ... سواها وحب القلب بثنة لا يجدي)\nال وقال أيضا ومن الناس من يضيف هذه الأبيات إلى هذه القصيدة وفيها أبيات معادة القوافي تدل على أنها مفردة عنها وهي\n(ألم تسأل الدار القديمة هل لها ... بأم جسير بعد عهدك من عهد)\nوفيها يقول\n(سلي الركب هل عجنا لمغناك مرة ... صدور المطايا وهي موقرة تخدي)\n(وهل فاضت العين الشروق بمائها ... من اجلك حتى اخضل من دمعها بردي)\nالغناء لأحمد بن المكي ثاني ثقيل بالوسطى\n(وإني لأستجري لك الطير جاهدا ... لتجري بيمن من لقائك من سعد)\n(وإني لأستبكي إذا الركب غردوا ... بذكراك أن يحيا بك الركب إذ يخدي)\n(فهل تجزيني أم عمرو بودها ... فإن الذي أخفي بها فوق ما أبدي)\n(وكل محب لم يزد فوق جهده ... وقد زدتها في الحب مني على الجهد)","topic":"نسب جميل وأخباره","topicNo":76,"sp":7,"spl":"تذاكر النسيب مع كثير","song":1,"loc":1436},
{"id":"b76-11","bab":"الجزء 8","sec":"خبره مع أم منظور التي اؤتمنت على بثينة","page":"ج8 ص119","text":"خبرني الحرمي قال حدثنا الزبير قال حدثني عمر بن إبراهيم وغيره وبهلول بن سليمان البلوي أن رهط بثينة ائتمنوا عليها عجوزا منهم يثقون بها يقال لها أم منظور فجاءها جميل فقال لها يا أم منظور أريني بثينة فقالت لا والله ما أفعل قد ائتمنوني عليها فقال أما والله لأضرنك فقالت المضرة والله في أن أريكها فخرج من عندها وهو يقول\n(ما أنس لا أنس منها نظرة سلفت ... بالحجر يوم جلتها أم منظور)\n(ولا انسلابتها خرسا جبائرها ... إلي من ساقط الأرواق مستور)\nال فما كان إلا قليل حتى انتهى إليهم هذان البيتان قال فتعلقوا بأم منظور فحلفت لهم بكل يمين فلم يقبلوا منها هكذا ذكر الزبير بن بكار في خبر أم منظور وقد ذكر فيه غير ذلك","topic":"نسب جميل وأخباره","topicNo":76,"sp":8,"spl":"خبره مع أم منظور التي اؤتمنت على بثينة — مصعب يستفسر أم منظور عن قصة جميل وبثينة","loc":1437},
{"id":"b76-12","bab":"الجزء 8","sec":"مصعب يستفسر أم منظور عن قصة جميل وبثينة","page":"ج8 ص120","text":"أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثني العمري عن الهيثم بن عدي وأخبرني به ابن أبي الأزهر عن حماد عن أبيه عن الهيثم بن عدي أن رجلا أنشد مصعب بن الزبير قول جميل\n(ما أنس لا أنس منها نظرة سلفت ... بالحجر يوم جلتها أم منظور)\nفقال لوددت أني عرفت كيف جلتها فقيل له إن أم منظور هذه حية فكتب في حملها إليه مكرمة فحملت إليه فقال لها أخبريني عن قول جميل\n(ما أنس لا أنس منها نظرة سلفت ... بالحجر يوم جلتها أم منظور)\nيف كانت هذه الجلوة قالت ألبستها قلادة بلح ومخنقة بلح واسطتها تفاحة وضفرت شعرها وجعلت في فرقها شيئا من الخلوق ومر بنا جميل راكبا ناقته فجعل ينظر إليها بمؤخر عينه ويلتفت إليها حتى غاب عنا فقال لها مصعب فإني أقسم عليك إلا جلوت عائشة بنت طلحة مثل ما جلوت بثينة ففعلت وركب مصعب ناقته وأقبل عليهما وجعل ينظر إلى عائشة بمؤخر عينه ويسير حتى غاب عنهما ثم رجع\nأخبرني الحرمي قال حدثنا الزبير قال حدثني بهلول عن بعض مشايخه أن جميلا جاء إلى بثينة ليلة وقد أخذ ثياب راع لبعض الحي فوجد عندها ضيفانا لها فانتبذ ناحية فسألته من أنت فقال مسكين مكاتب فجلس وحده فعشت ضيفانها وعشته وحده ثم جلست هي وجارية لها على صلائهما واضطجع القوم منتحين فقال جميل\n(هل البائس المقرور دان فمصطل ... من النار أو معطى لحافا فلابس)\nقالت لجاريتها صوت جميل والله اذهبي فانظري فرجعت إليها فقالت هو والله جميل فشهقت شهقة سمعها القوم فأقبلوا يجرون وقالوا مالك فطرحت بردا لها من حبرة في النار وقالت احترق بردي فرجع القوم وارسلت جاريتها إلى جميل فجاءتها به فحبسته عندها ثلاث ليال ثم سلم عليها وخرج وقال الهيثم وأصحابه في أخبارهم كانت بثينة قد واعدت جميلا للالتقاء في بعض المواضع فأتى لوعدها وجاء أعرابي يستضيف القوم فأنزلوه وقروه فقال لهم إني قد رأيت في بطن هذا الوادي ثلاثة نفر متفرقين متوارين في الشجر وأنا خائف عليكم أن يسلوا بعض إبلكم فعرفوا أنه جميل وصاحباه فحرسوا بثينة ومنعوها من الوفاء بوعده فلما أسفر له الصبح انصرف كئيبا سيىء الظن بها ورجع إلى أهله فجعل نساء الحي يقرعنه بذلك ويقلن له إنما حصلت منها على الباطل والكذب والغدر وغيرها أولى بوصلك منها كما أن غيرك يحظى بها فقال في ذلك\n(أبثين إنك قد ملكت فأسجحي ... وخذي بحظك من كريم واصل)\n\n(فلرب عارضة علينا وصلها ... بالجد تخلطه بقول الهازل)\n(فأجبتها بالقول بعد تستر ... حبي بثينة عن وصالك شاغلي)\n(لو كان في قلبي كقدر قلامة ... فضلا وصلتك أو أتتك رسائلي)\nلغناء ليحيى المكي ثقيل أول بالوسطى من رواية أحمد\n(ويقلن إنك قد رضيت بباطل ... منها فهل لك في اجتناب الباطل)\n(ولباطل ممن أحب حديثه ... أشهى إلي من البغيض الباذل)\nلغناء لسليم رمل بالوسطى عن عمرو وذكر عمر أنه ليزيد حوراء","topic":"نسب جميل وأخباره","topicNo":76,"sp":8,"spl":"خبره مع أم منظور التي اؤتمنت على بثينة — مصعب يستفسر أم منظور عن قصة جميل وبثينة","song":1,"loc":1438},
{"id":"b76-13","bab":"الجزء 8","sec":"شعره بعد أن علم زوج بثينة بمقامه معها","page":"ج8 ص122","text":"وذكر الهيثم بن عدي وأصحابه أن جماعة من بني عذرة حدثوا أن جميلا رصد بثينة ذات ليلة في نجعة لهم حتى إذا صادف منها خلوة سكر ودنا منها وذلك في ليلة ظلماء ذات غيم وريح ورعد فحذفها بحصاة فأصابت بعض أترابها ففزعت وقالت والله ما حذفني في هذا الوقت بحصاة إلا الجن فقالت لها بثينة وقد فطنت إن جميلا فعل ذلك فانصرفي ناحية إلى منزلك حتى ننام فانصرفت وبقيت مع بثينة أم الجسير وأم منظور فقامت إلى جميل فأدخلته الخباء معها وتحدثا طويلا ثم اضطجع واضطجعت إلى جنبه فذهب النوم بهما حتى أصبحا وجاءها غلام زوجها بصبوح من اللبن بعث به إليها فرآها نائمة مع جميل فمضى لوجهه حتى خبر سيده ورأته ليلى والصبوح معه وقد عرفت خبر جميل وبثينة فاستوقفته كأنها تسأله عن حاله وبعثت بجارية لها\nوقالت حذري بثينة وجميلا فجاءت الجارية فنبهتهما فلما تبينت بثينة الصبح قد أضاء والناس منتشرين ارتاعت وقالت يا جميل نفسك نفسك فقد جاءني غلام نبيه بصبوحي من اللبن فرآنا نائمين فقال لها جميل وهو غير مكترث لما خوفته منه\n(لعمرك ما خوفتني من مخافة ... بثين ولا حذرتني موضع الحذر)\n(فأقسم لا يلفى لي اليوم غرة ... وفي الكف مني صارم قاطع ذكر)\nأقسمت عليه أن يلقي نفسه تحت النضد وقالت إنما أسألك ذلك خوفا على نفسي من الفضيحة لا خوفا عليك ففعل ذلك ونامت كما كانت واضجعت أم الجسير إلى جانبها وذهبت خادم ليلى إليها فأخبرتها الخبر فتركت العبد يمضي إلى سيده فمضى والصبوح معه وقال له إني رأيت بثينة مضطجعة وجميل إلى جنبها فجاء نبيه إلى أخيها وأبيها فأخذ بأيديهما وعرفهما الخبر وجاؤوا بأجمعهم إلى بثينة وهي نائمة فكشفوا عنها الثوب فإذا أم الجسير إلى جانبها نائمة فخجل زوجها وسب عبده وقالت ليلى لأخيها وأبيها قبحكما الله أفي كل يوم تفضحان فتاتكما ويلقاكما هذا الأعور فيها بكل قبيح قبحه الله وإياكما وجعلا يسبان زوجها ويقولان له كل قول قبيح وأقام جميل عند بثينة حتى أجنه الليل ثم ودعها وانصرف وحذرتهم بثينة لما جرى من لقائه إياها فتحامته مدة فقال في ذلك\n(أأن هتفت وورقاء ظلت سفاهة ... تبكي على جمل لورقاء تهتف)\n(فلو كان لي بالصرم يا صاح طاقة ... صرمت ولكني عن الصرم أضعف)\nلهذلي في هذين البيتين لحنان أحدهما ثقيل أول بالسبابة في مجرى البنصر عن إسحاق والآخر خفيف ثقيل بالوسطى عن عمرو وذكر غيره أنه لابن جامع وفيه لبذل الكبرى خفيف ثقيل بالخنصر في مجرى البنصر عن أحمد بن المكي ومما يغنى فيه من هذه القصيدة قوله\n(لها في سواد القلب بالحب ميعة ... هي الموت أو كادت على الموت تشرف)\n(وما ذكرتك النفس با بثن مرة ... من الدهر إلا كادت النفس تتلف)\n(وإلا اعترتني زفرة واستكانة ... وجاد لها سجل مع الدمع يذرف)\n(وما استطرفت نفسي حديثا لخلة ... أسر به إلا حديثك أطرف)\nلغناء لإبراهيم ثقيل أول بالوسطى عن الهشامي وأول هذه القصيدة\n(أمن منزل قفر تعفت رسومه ... شمال تغاديه ونكباء حرجف)\n(فأصبح قفرا بعد ما كان آهلا ... وجمل المنى تشتو به وتصيف)\n(ظللت ومستن من الدمع هامل ... من العين لما عجت بالدار ينزف)\n(أمنصفتي جمل فتعدل بيننا ... إذا حكمت والحاكم العدل ينصف)\n(تعلقتها والجسم مني مصحح ... فما زال ينمي حب جمل وأضعف)\n(إلى اليوم حتى سل جسمي وشفني ... وأنكرت من نفسي الذي كنت أعرف)\n(قناة من المران مما فوق حقوها ... وما تحته منها نقا يتقصف)\n(لها مقلتا ريم وجيد جداية ... وكشح كطي السابرية أهيف)\n(ولست بناس أهلها حين أقبلوا ... وجالوا علينا بالسيوف وطوفوا)\n(وقالوا جميل بات في الحي عندها ... وقد جردوا أسيافهم ثم وقفوا)\n(وفي البيت ليث الغاب لولا مخافة ... على نفس جمل والإله لأرعفوا)\n(هممت وقد كادت مرارا تطلعت ... إلى حربهم نفسي وفي الكف مرهف)\n(وما سرني غير الذي كان منهم ... ومني وقد جاؤوا إلي وأوجفوا)\n(فكم مرتج أمرا أتيح له الردى ... ومن خائف لم ينتقصه التخوف)\nدثني عمي قال حدثنا الكراني قال حدثنا العمري وأخبرنا محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري عن الهيثم بن عدي قال قال لي صالح بن حسان هل تعرف بيتا نصفه أعرابي في شملة وآخره مخنث يتفكك من مخنثي العقيق فقلت لا أدري قال قد أجلتك فيه حولا فقلت لو أجلتني حولين ما علمت قال قول جميل","topic":"نسب جميل وأخباره","topicNo":76,"sp":9,"spl":"شعره بعد أن علم زوج بثينة بمقامه معها","song":2,"loc":1439},
{"id":"b76-14","bab":"الجزء 8","sec":"شعره بعد أن علم زوج بثينة بمقامه معها","page":"ج8 ص122","text":"(ألا أيها النوام ويحكم هبوا ... )\nذا أعرابي في شملة ثم قال\n(نسائلكم هل يقتل الرجل الحب ... )\nكأنه والله من مخنثي العقيق في هذا الشعر غناء نسبته وشرحه\n(ألا أيها النوام ويحكم هبوا ... نسائلكم هل يقتل الرجل الحب)\n(ألا رب ركب قد دفعت وجيفهم ... إليك ولولا أنت لم يوجف الركب)\nلغناء لابن محرز خفيف رمل بالسبابة والوسطى عن يحيى المكي وذكره إسحاق في هذه الطريقة ولم ينسبه إلى أحد وفيه لسليم ماخوري عن الهشامي وفيه لمالك ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق وقيل إنه لمعبد وفيه لعريب هزج من رواية ابن المعتز وذكر عبد الله بن موسى أن لحن مالك من الثقيل الأول وأن خفيف الرمل لابن سريج وأن الهزج لحمدونة بنت الرشيد","topic":"نسب جميل وأخباره","topicNo":76,"sp":10,"spl":"شعره بعد أن علم زوج بثينة بمقامه معها — حل جفاء بينه وبين بثينة بعد تعلقها بحجنة الهلالي","song":1,"loc":1440,"partialRef":{"sid":"b33-64","gi":1,"vi":0,"side":1},"partial":1},
{"id":"b76-15","bab":"الجزء 8","sec":"حل جفاء بينه وبين بثينة بعد تعلقها بحجنة الهلالي","page":"ج8 ص126","text":"أخبرنا لحسين بن يحيى المرداسي قال أخبرنا حماد بن إسحاق عن أبيه عن أيوب بن عباية المحرزي عن شيخ من رهط جميل من عذرة\nأن بثينة لما علقت حجنة الهلالي جفاها جميل قال وأنشدني لجميل في ذلك\n\n(بينا جبال ذات عقد لبثنة ... أتيح لها بعض الغواة فحلها)\n(فعدنا كأنا لم يكن بيننا هوى ... وصار الذي حل الحبال هوى لها)\n(وقالوا نراها يا جميل تبدلت ... وغيرها الواشي فقلت لعلها)\nلغناء للهذلي خفيف ثقيل مطلق في مجرى الوسطى وذكره إسحاق في هذه الطريقة والإصبع ولم ينسبه إلى أحد أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال حدثنا أبو عوف عن عبد الرحمن بن مقرن قال بعثني المنصور لأبتاع له جارية من المدينة وقال لي اعمل برأي ابن نفيس فكنت أفعل ذلك وأغشى ابنه وكانت له جارية مغنية قد كلف بها فتى من آل عثمان بن عفان فكان يبيع عقدة من ماله وينفق ثمنها عليها وابتلي برجل من أهل إفريقية ومعه ابن له فغشي ابن الإفريقي بيت ابن نفيس فجعل يكسو الجارية وأهلها ويبرهم حتى حظي عندهم وغلب عليهم وتثاقلوا العثماني فقضي أن اجتمعنا عشية وحضر ابن الإفريقي والعثماني فنزع ابن الإفريقي خفه فتناثر المسك منه وأراد العثماني أن يكيده بفعله فجلسنا ساعة فقال لها ابن الإفريقي غني\n(بينا حبال ذات عقد لبثنة ... أتيح لها بعض الغواة فحلها)\nعرض بالعثماني فقال لها العثماني لا حاجة لنا في هذا ولكن غني\n(ومن يرع نجدا يلفني قد رعيته ... بجنيته الأولى ويورد على وردي)\nال فنكس ابن الإفريقي رأسه وخرج العثماني فذهب وخمد أهل البيت فما انتفعوا بقية يومهم","topic":"نسب جميل وأخباره","topicNo":76,"sp":10,"spl":"شعره بعد أن علم زوج بثينة بمقامه معها — حل جفاء بينه وبين بثينة بعد تعلقها بحجنة الهلالي","song":1,"loc":1441},
{"id":"b76-16","bab":"الجزء 8","sec":"شعره بعد زواج بثينة من نبيه","page":"ج8 ص128","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عمر بن أبي بكر المؤملي وبهلول بن سليمان البلوي أن جميلا قال لما زوجت بثينة نبيها\n(ألا ناد عيرا من بثينة ترتعي ... نودع على شحط النوى ونودع)\n(وحثوا على جمع الركاب وقربوا ... جمالا ونوقا جلة لم تضعضع)\nي هذين البيتين رمل لابن سريج عن الهشامي ومما يغني فيه من هذه القصيدة\n(أعيذك بالرحمن من عيش شقوة ... وأن تطمعي يوما إلى غير مطمع)\n(إذا ما ابن ملعون تحدر رشحه ... عليك فموتي بعد ذلك أو دعي)\n(مللن ولم أملل وما كنت سائما ... لأجمال سعدى ما أنخن بجعجع)\n(وحثوا على جمع الركاب وقربوا ... جمالا ونوقا جلة لم تضعضع)\n(ألا قد أرى إلا بثينة ها هنا ... لنا بعد ذا المصطاف والمتربع)\nمعبد في الثالث والرابع من هذه الأبيات ثقيل أول بالخنصر في مجرى الوسطى عن إسحاق ولابن سريج في الأول والثاني والخامس خفيف رمل بالبنصر عن عمرو وللأبجر في الأول والخامس والثالث والرابع رمل بالبنصر وفي الأول والثاني خفيف ثقيل ينسب إلى معبد وغيره ولم تعرف صحته من جهة يوثق بها أخبرني الحرمي قال حدثنا الزبير قال أنشدنا بهلول بن سليمان لجميل لما بعد عن بثينة وخاف السلطان وكان بهلول يعجب به\n(ألا قد أرى إلا بثينة للقلب ... بوادي بدا لا بجسمى ولا الشغب)\n(ولا ببصاق قد تيممت فاعترف ... لما أنت لاق أو تنكب عن الركب)\n(أفي كل يوم أنت محدث صبوة ... تموت لها بدلت غيرك من قلب)\nخبرنا الحرمي قال حدثنا الزبير قال حدثنا أبي عن يعقوب بن محمد الزهري عن سليمان بن صخر الحرشي قال حدثنا سليمان بن زياد الثقفي أن بثينة دخلت على عبد الملك بن مروان فرأى امرأة خلفاء مولية\nفقال لها ما الذي رأى فيك جميل قالت الذي رأى فيك الناس حين استخلفوك فضحك عبد الملك حتى بدت له سن سوداء كان يسترها أخبرني الحرمي قال حدثنا الزبير قال حدثني عمر بن إبراهيم العويثي أن جمل جميل الذي كان يزور عليه بثينة يقال له جديل وفيه يقول\n(أنخت جديلا عند بثنة ليلة ... ويوما أطال الله رغم جديل)\n(أليس مناخ النضو يوما وليلة ... لبثنة فيما بيننا بقليل)\nخبرني هاشم بن محمد الخزاعي قال حدثنا عمر بن شبة قال حدثني أبو غسان محمد بن يحيى المكي أن جميلا لما اشتهرت بثينة بحبه إياها اعترضه عبيد الله بن قطبة أحد بني الأحب وهو من رهطها الأدنين فهجاه وبلغ ذلك جميلا فأجابه وتطاولا فغلبه جميل وكف عنه ابن قطبة واعترضه عمير بن رمل رجل من بني الأحب فهجاه وإياه عنى جميل بقوله\n(إذا الناس هابوا خزية ذهبت بها ... أحب المخازي كهلها ووليدها)\n(لعمر عجوز طرقت بك إنني ... عمير بن رمل لابن حرب أقودها)\n(بنفسي فلا تقطع فؤادك ضلة ... كذلك حزني وعثها وصعودها)\nال فاستعدوا عليه عامر بن ربعي بن دجاجة وكانت إليه بلاد عذرة وقالوا يهجونا ويغشى بيوتنا وينسب بنسائنا فأباحهم دمه وطلب فهرب منه وغضبت بثينة لهجائه أهلها جميعا فقال جميل\n(وما صائب من نابل قذفت به ... يد وممر العقدتين وثيق)\n(له من خوافي النسر حم نظائر ... ونصل كنصل الزاعبي فتيق)\n(على نبعة زوراء أما خطامها ... فمتن وأما عودها فعتيق)\n(بأوشك قتلا منك يوم رميتني ... نوافذ لم تظهر لهن خروق)\n(تفرق أهلانا بثين فمنهم ... فريق أقاموا واستمر فريق)\n(فلو كنت خوارا لقد باح مضمري ... ولكنني صلب القناة عريق)\n(كأن لم نحارب يا بثين لو انه ... تكشف غماها وأنت صديق)\nال ويدل على طلب عامر بن ربعي إياه قوله\n(أضر بأخفاف البغيلة أنها ... )\n(حذار ابن ربعي بهن رجوم ... )","topic":"نسب جميل وأخباره","topicNo":76,"sp":11,"spl":"شعره بعد زواج بثينة من نبيه","song":2,"loc":1442,"partial":1},
{"id":"b76-17","bab":"الجزء 8","sec":"هرب إلى اليمن بعد أن أهدر دمه","page":"ج8 ص131","text":"أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن عبد الله الحزنبل الأصبهاني قال حدثني عمرو بن ابي عمرو الشيباني عن أبيه قال حدثني بعض رواة عذرة أن السلطان أهدر دم جميل لرهط بثينة إن وجدوه قد غشي دورهم فحذرهم مدة ثم وجدوه عندها فأعذروا إليه وتوعدوه وكرهوا أن ينشب بينهم\nوبين قومه حرب في دمه وكان قومه أعز من قومها فأعادوا شكواه إلى السلطان فطلبه طلبا شديدا فهرب إلى اليمن فأقام بها مدة وأنشدني له في ذلك\n(ألم خيال من بثينة طارق ... على النأي مشتاق إلي وشائق)\n(سرت من تلاع الحجر حتى تخلصت ... إلي ودوني الأشعرون وغافق)\n(كأن فتيت المسك خالط نشرها ... تغل به أردانها والمرافق)\n(تقوم إذا قامت به عن فراشها ... ويغدو به من حضنها من تعانق)\nقال أبو عمرو وحدثني هذا العذري أن جميلا لم يزل باليمن حتى عزل ذلك الوالي عنهم وانتجعوا ناحية الشام فرحل إليهم قال فلقيته فسألته عما أحدث بعدي فأنشدني\n(سقى منزلينا يا بثين بحاجر ... على الهجر منا صيف وربيع)\n(ودورك يا ليلى وإن كن بعدنا ... بلين بلى لم تبلهن ربوع)\nوخيماتك اللاتي بمنعرج اللوى ... لقمريها بالمشرقين سجيع تزعزع منها الريح كل عشية ... هزيم بسلاف الرياح رجيع وإني أن يعلى بك اللوم أو تري ... بدار أذى من شامت لجزوع وإني على الشيء الذي يلتوى به ... وإن زجرتني زجرة لوريع\n(فقدتك من نفس شعاع فإنني ... نهيتك عن هذا وأنت جميع)\n(فقربت لي غير القريب وأشرفت ... هناك ثنايا ما لهن طلوع)\n(يقولون صب بالغواني موكل ... وهل ذاك من فعل الرجال بديع)\n(وقالوا رعيت اللهو والمال ضائع ... فكالناس فيهم صالح ومضيع)\nلغناء لصالح بن الرشيد رمل بالوسطى عن الهشامي وابن خرداذبة وإبراهيم وذكر حبش أن في هذه الأبيات لإسحاق لحنا من الثقيل بالوسطى ولم يذكر هذا أحد غيره ولا سمعناه ولا قرأناه إلا في كتابه ومن الناس من يدخل هذه الأبيات في قصيدة المجنون التي على روي وقافية هذه القصيدة وليست له","topic":"نسب جميل وأخباره","topicNo":76,"sp":12,"spl":"هرب إلى اليمن بعد أن أهدر دمه","loc":1443},
{"id":"b76-18","bab":"الجزء 8","sec":"كثير ينعته بأشعر الناس","page":"ج8 ص133","text":"أخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال حدثني عمر بن أبي بكر المؤملي عن أبي عبيدة عن أبيه قال دخل علينا كثير يوما وقد أخذ بطرف ريطته وألقى طرفها الآخر وهو يقول هو والله أشعر الناس حيث يقول\n(وخبرتماني أن تيماء منزل ... لليلى إذا ما الصيف ألقى المراسيا)\n(فهذي شهور الصيف عني قد انقضت ... فما للنوى ترمي بليلى المراميا)\nيجر ريطته حتى يبلغ إلينا ثم يولي عنا ويجرها ويقول هو والله اشعر الناس حيث يقول\n(وأنت التي إن شئت كدرت عيشتي ... وإن شئت بعد الله أنعمت باليا)\n(وأنت التي ما من صديق ولا عدا ... يرى نضو ما أبقيت إلا رثى ليا)\nم يرجع إلينا ويقول هو والله أشعر الناس فقلنا من تعني يا أبا صخر فقال ومن أعني سوى جميل هو والله أشعر الناس حيث يقول هذا وتيماء خاصة منزل لبني عذرة وليس من منازل عامر وإنما يرويه عن المجنون من لا يعلمه وفي هذه القصيدة يقول جميل\n(وما زلتم يا بثن حتى لوانني ... من الشوق أستبكي الحمام بكى ليا)\n(إذا خدرت رجلي وقيل شفاؤها ... دعاء حبيب كنت أنت دعائيا)\n(وما زادني النأي المفرق بعدكم ... سلوا ولا طول التلاقي تقاليا)\n(ولا زادني الواشون إلا صبابة ... ولا كثرة الناهين إلا تماديا)\n(ألم تعلمي يا عذبة الريق أنني ... أظل إذا لم ألق وجهك صاديا)\n(لقد خفت أن ألقى المنية بغتة ... وفي النفس حاجات إليك كما هيا)\nخبرنا الحرمي بن ابي العلاء قال حدثنا الزبير قال حدثني بعض أصحابنا عن محمد بن معن الغفاري عن الأصبغ بن عبد العزيز قال كنت عند طلحة بن عبد الله بن عوف فدخل عليه كثير فلما دخل من\nالباب أخذ برجله فثناها ثم حجل حتى بلغ الفراش وهو يقول جميل والله أشعر العرب حيث يقول\n(وخبرتماني أن تيماء منزل ... )\nم ذكر باقي الخبر الذي رواه محمد بن مزيد أخبرني الحرمي قال حدثني الزبير قال حدثني عمر بن إبراهيم السعدي أن رهط بثينة قالوا إنما يتبع جميل أمة لنا فواعد جميل بثينة حين لقيها ببرقاء ذي ضال فتحادثا ليلا طويلا حتى أسحرا ثم قال لها هل لك أن ترقدي قالت ما شئت وأنا خائفة أن نكون قد أصبحنا فوسدها جانبه ثم اضطجعا ونامت فانسل واستوى على راحلته فذهبت وأصبحت في مضجعها فلم يرع الحي إلا بها راقدة عند مناخ راحلة جميل فقال جميل في ذلك\n(فمن يك في حبي بثينة يمتري ... فبرقاء ذي ضال علي شهيد)\nخبرني عمي قال حدثنا عبد الله بن شبيب عن الحزامي عن فليح بن إسماعيل بمثل هذه القصة وزاد فيها فلما انتبهت بثينة علمت ما اراده جميل بها فهجرته وآلت ألا تظهر له فقال\n(ألا هل إلى إلمامة أن ألمها ... بثينة يوما في الحياة سبيل)\n(فإن هي قالت لا سبيل فقل لها ... عناء على العذري منك طويل)\n(على حين يسلو الناس عن طلب الصبا ... وينسى اتباع الوصل منه خليل)","topic":"نسب جميل وأخباره","topicNo":76,"sp":13,"spl":"كثير ينعته بأشعر الناس","loc":1444,"partialRef":{"sid":"b7-4","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b76-19","bab":"الجزء 8","sec":"لامه أهله على حبه بثينة","page":"ج8 ص136","text":"وقال الهيثم وأصحابه في أخبارهم تشكى زوج بثينة إلى أبيها وأخيها إلمام جميل بها فوجهوا إلى جميل وأعذروا إليه وشكوه إلى عشيرته وأعذروا إليهم فيه وتوعدوه وأتاهم فلامه أهله وعنفوه وقالوا إنا نستحلف إليهم ونتبرأ منك ومن جريرتك فأقام مدة لا يلم بها ثم لقي ابني عمه روقا ومسعودا فشكا إليهما ما به وأنشدهما قوله\n(وإني على الشيء الذي يلتوى به ... وإن زجرتني زجرة لوريع)\n(فقدتك من نفس شعاع فإنني ... نهيتك عن هذا وأنت جميع)\n(فقربت لي غير القريب وأشرفت ... هناك ثنايا ما لهن طلوع)\n(يقولون صب بالغواني موكل ... وهل ذاك من فعل الرجال بديع)\n(وقالوا رعيت اللهو والمال ضائع ... فكالناس فيهم صالح ومضيع)\nخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني مصعب بن عبد الله قال كانت تحت محمد بن عبد الله بن حسن امرأة من ولد الزبير يقال لها فليحة وكانت لها صبية يقال لها رخية قد ربتها لغير رشدة وكانت من أجمل النساء وجها فرأت محمدا وقد نظر إليها ذات يوم نظرا شديدا ثم تمثل قول جميل\n(بثينة من صنف يقلبن أيدي الرماة ... وما يحملن قوسا ولا نبلا)\n(ولكنما يظفرن بالصيد كلما ... جلون الثنايا الغر والأعين النجلا)\n(يخالسن ميعادا يرعن لقولها ... إذا نطقت كانت مقالتها فصلا)\n(يرين قريبا بيتها وهي لا ترى ... سوى بيتها بيتا قريبا ولا سهلا)\nقالت له فليحة كأنك تريد رخية قال إي والله قالت إني أخشى أن تجيء منك بولد وهي لغير رشدة فقال لها إن الدنس لا يلحق الأعقاب ولا يضر الأحساب فقالت له فماذا يضر إذا والله ما يضر إلا الأعقاب والأحساب وقد وهبتها لك فسر بذلك وقال أما والله لقد أعطيتك خيرا منها قالت وما هو قال أبيات جميل التي أنشدتك إياها لقد مكثت أسعى في طلبها حولين فضحكت وقالت ما لي ولأبيات جميل والله ما ابتغيت إلا مسرتك قال فولدت منه غلاما وكانت فليحة تدعو الله إلا يبقيه فبينا محمد في بعض هربه من المنصور والجارية وابنها معه إذ رهقهما الطلب فسقط الصبي من الجبل فتقطع فكان محمد بعد ذلك يقول أجيب في هذا الصبي دعاء فليحة وقال الهيثم بن عدي وأصحابه في أخبارهم لما نذر أهل بثينة دم جميل وأباحهم السلطان قتله أعذروا إلى أهله وكانت منازلهم متجاورة إنما هم بيوتات يفترقون كما يفترق البطون والأفخاذ والقبائل غير متباعدين ألم تر قول جميل\n(أبيت مع الهلاك ضيفا لأهلها ... وأهلي قريب موسعون أولو فضل)\nمشت مشيخة الحي إلى أبيه وكان يلقب صباحا وكان ذا مال وفضل وقدر في أهله فشكوه إليه وناشدوه الله والرحم وسألوه كف ابنه عما يتعرض له ويفضحهم به في فتاتهم فوعدهم كفه ومنعه ما استطاع ثم انصرفوا فدعا به فقال له يا بني حتى متى أنت عمه في ضلالك لا تأنف من أن تتعلق بذات بعل يخلو بها وينكحها وأنت عنها بمعزل ثم تقوم من تحته إليك فتغرك\nبخداعها وتريك الصفاء والمودة وهي مضمرة لبعلها ما تضمره الحرة لمن ملكها فيكون قولها لك تعليلا وغرورا فإذا انصرفت عنها عادت إلى بعلها على حالتها المبذولة إن هذا لذل وضيم ما أعرف أخيب سهما ولا أضيع عمرا منك فأنشدك الله إلا كففت وتأملت أمرك فإنك تعلم أن ما قلته حق ولو كان إليها سبيل لبذلت ما أملكه فيها ولكن هذا أمر قد فات واستبد به من قدر له وفي النساء عوض فقال له جميل الرأي ما رأيت والقول كما قلت فهل رأيت قبلي أحدا قدر أن يدفع عن قلبه هواه أو ملك أن يسلي نفسه أو استطاع أن يدفع ما قضي عليه والله لو قدرت أن أمحو ذكرها من قلبي أو أزيل شخصها عن عيني لفعلت ولكن لا سبيل إلى ذلك وإنما هو بلاء بليت به لحين قد أتيح لي وأنا أمتنع من طروق هذا الحي والإلمام بهم ولو مت كمدا وهذا جهدي ومبلغ ما أقدر عليه وقام وهو يبكي فبكى ابوه ومن حضر جزعا لما رأوا منه فذلك حين يقول جميل\n(ألا من لقلب لا يمل فيذهل ... أفق فالتعزي عن بثينة أجمل)\n(سلا كل ذي ود علمت مكانه ... وأنت بها حتى الممات موكل)\n(فما هكذا أحببت من كان قبلها ... ولا هكذا فيما مضى كنت تفعل)\nلغناء لمالك ثقيل أول بالسبابة في مجرى البنصر عن إسحاق\n(فيا قلب دع ذكرى بثينة إنها ... وإن كنت تهواها تضن وتبخل)\n(وقد أيأست من نيلها وتجهمت ... ولليأس إن لم يقدر النيل أمثل)\n(وإلا فسلها نائلا قبل بينها ... وأبخل بها مسؤولة حين تسأل)","topic":"نسب جميل وأخباره","topicNo":76,"sp":14,"spl":"لامه أهله على حبه بثينة","song":1,"loc":1445},
{"id":"b76-20","bab":"الجزء 8","sec":"لامه أهله على حبه بثينة","page":"ج8 ص136","text":"(وكيف ترجي وصلها بعد بعدها ... وقد جذ حبل الوصل ممن تؤمل)\n(إن التي أحببت قد حيل دونها ... فكن حازما والحازم المتحول)\n(ففي اليأس ما يسلي وفي الناس خلة ... وفي الأرض عمن لا يواتيك معزل)\n(بدا كلف مني بها فتثاقلت ... وما لا يرى من غائب الوجد أفضل)\n(هبيني بريئا نلته بظلامة ... عفاها لكم أو مذنبا يتنصل)\n(قناة من المران ما فوق حقوها ... وما تحته منها نقا يتهيل)\nال وقال أيضا في هذه الحال\n(أعن ظعن الحي الألى كنت تسأل ... بليل فردوا عيرهم وتحملوا)\n(فأمسوا وهم أهل الديار وأصبحوا ... ومن أهلها الغربان بالدار تحجل)\nي هذين البيتين لسياط خفيف رمل بالسبابة في مجرى البنصر عن إسحاق وفيه لابن جامع ثاني ثقيل بالوسطى عن عمرو\n(على حين ولى الأمر عنا وأسمحت ... عصا البين وانبت الرجاء المؤمل)\n(فما هو إلا أن أهيم بذكرها ... ويحظى بجدواها سواي ويجذل)\n(وقد أبقت الأيام مني على العدا ... حساما إذا مس الضريبة يفصل)\n(ولست كمن إن سيم ضيما أطاعه ... ولا كامرىء إن عضه الدهر ينكل)\nعمري لقد أبدى لي البين صفحه ... وبين لي ما شئت لو كنت اعقل وآخر عهدي من بثينة نظرة ... على موقف كادت من البين تقتل فلله عينا من رأى مثل حاجة ... كتمتكها والنفس منها تململ\n(وإني لأستبكي إذا ذكر الهوى ... إليك وإني من هواك لأوجل)\n(نظرت ببشر نظرة ظلت أمتري ... بها عبرة والعين بالدمع تكحل)\n(إذا ما كررت الطرف نحوك رده ... من البعد فياض من الدمع يهمل)","topic":"نسب جميل وأخباره","topicNo":76,"sp":15,"spl":"لامه أهله على حبه بثينة","song":1,"loc":1446},
{"id":"b76-21","bab":"الجزء 8","sec":"خروجه إلى الشام","page":"ج8 ص140","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن أيوب بن عباية قال لما أراد جميل الخروج إلى الشام هجم ليلا على بثينة وقد وجد غفلة فقالت له أهلكتني والله وأهلكت نفسك ويحك أما تخاف فقال لها هذا وجهي إلى الشام إنما جئتك مودعا فحادثها طويلا ثم ودعها وقال يا بثينة ما أرانا نلتقي بعد هذا وبكيا طويلا ثم قال لها وهو يبكي\n(ألا لا أبالي جفوة الناس ما بدا ... لنا منك رأي يا بثين جميل)\n(وما لم تطيعي كاشحا أو تبدلي ... بنا بدلا أو كان منك ذهول)\n(وإني وتكراري الزيارة نحوكم ... بثين بذي هجر بثين يطول)\n(وإن صباباتي بكم لكثيرة ... بثين ونسيانيكم لقليل)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني شيوخ من عذرة أن مروان بن الحكم خرج مسافرا في نفر من قريش ومعه جميل بن معمر وجواس بن قطبة أخو عبيد الله بن قطبة فقال مروان لجواس إنزل فارجز بنا وهو يريد أن يمدحه فنزل جواس وقال\n(يقول أميري هل تسوق ركابنا ... فقلت له حاد لهن سوائيا)\n(تكرمت عن سوق المطي ولم يكن ... سياق المطي همتي ورجائيا)\n(جعلت أبي رهنا وعرضي سادرا ... إلى أهل بيت لم يكونوا كفائيا)\n(إلى شر بيت من قضاعة منصبا ... وفي شر قوم منهم قد بدا ليا)\nفقال مروان إركب لا ركبت ثم قال لجميل إنزل فارجز بنا وهو يريد أن يمدحه فنزل جميل فقال\n(أنا جميل في السنام الأعظم ... الفارع الناس الأعز الأكرم)\n(أحمي ذماري ووجدت أقرمي ... كانوا على غارب طود خضرم)\n(أعيا على الناس فلم يهدم ... )\nقال عد عن هذا فقال جميل\n(لهفا على البيت المعدي لهفا ... من بعد ما كان قد استكفا)\n(ولو دعا الله ومد الكفا ... لرجفت منه الجبال رجفا)\nقال له إركب لا ركبت قال الزبير وحدثني عمر بن أبي بكر المؤملي قال كان جميل مع الوليد بن عبد الملك في سفر والوليد على نجيب فرجز به مكين العذري فقال\n(يا بكر هل تعلم من علاكا ... خليفة الله على ذراكا)\nقال الوليد لجميل إنزل فارجز وظن الوليد أنه يمدحه فنزل فقال\n(أنا جميل في السنام من معد ... في الذروة العلياء والركن الأشد)\n(والبيت من سعد بن زيد والعدد ... ما يبتغي الأعداء مني ولقد)\n(أضري بالشتم لساني ومرد ... أقود من شئت وصعب لم أقد)\nقال له الوليد إركب لا حملك الله قال وما مدح جميل أحدا قط أخبرني الحرمي قال حدثنا الزبير قال حدثنا يونس بن عبد الله بن سالم قال وقف جميل على الحزين الديلي والحزين ينشد الناس فقال له الحزين وهو لا يعرفه كيف تسمع شعري قال صالح وسط فغضب الحزين وقال له ممن أنت فوالله لأهجونك وعشيرتك فقال جميل إذا تندم فأقبل الحزين يهمهم يريد هجاءه فقال جميل\n(الديل أذناب بكر حين تنسبهم ... وكل قوم لهم من قومهم ذنب)\nقامت له بنو الديل وناشدوه الله إلا كف عنهم ولم يزالوا به حتى أمسك وانصرف أخبرني الحرمي ومحمد بن مزيد واللفظ له قالا حدثنا الزبير بن بكار قال حدثني محمد بن الضحاك عن أبيه قال لما هاجى عبيد الله بن قطبة جميلا واستعلى عليه جميل أعرض عنه واعترضه أخوه جواس بن قطبة فهجاه وذكر أختا لجميل وكان جميل قبل ذلك يحتقره ولا ينصب له حتى هجا أخته فقال فيما ذكرها به من شعره\n(إلى فخذيها العبلتين وكانتا ... بعهدي لفاوين أردفتا ثقلا)\nفغضب جميل حينئذ فواعده للمراجزة قال الزبير فحدثني بعض آل العباس بن سهل بن سعد عن عباس قال\nقدمت من عند عبد الملك بن مروان وقد أجازني وكساني بردا كان ذلك البرد أفضل جائزتي فنزلت وادي القرى فوافقت الجمعة بها فاستخرجت بردي الذي من عند عبد الملك وقلت أصلي مع الناس فلقيني جميل وكان صديقا لي فسلم بعضنا على بعض وتساءلنا ثم افترقنا فلما أمسيت إذا هو قد أتاني في رحلي فقال البرد الذي رأيته عليك تعيرنيه حتى أتجمل به فإن بيني وبين جواس مراجزة وتحضر فتسمع قال قلت لا بل هو لك كسوة فكسوته إياه وقلت لأصحابي ما من شيء أحب إلي من أن أسمع مراجزتهما فلما أصبحنا جعل الأعاريب يأتون أرسالا حتى اجتمع منهم بشر كثير وحضرت وأصحابي فإذا بجميل قد جاء وعليه حلتان ما رأيت مثلهما على أحد قط وإذا بردي الذي كسوته إياه قد جعله جلا لجمله فتراجزا فرجز جميل وكانت بثينة تكنى أم عبد الملك فقال\n(يا أم عبد الملك اصرميني ... فبيني صرمي أو صليني)\n(أبكي وما يدريك ما يبكيني ... أبكي حذار أن تفارقيني)","topic":"نسب جميل وأخباره","topicNo":76,"sp":16,"spl":"خروجه إلى الشام","loc":1447,"partial":1},
{"id":"b76-22","bab":"الجزء 8","sec":"خروجه إلى الشام","page":"ج8 ص140","text":"(وتجعلي أبعد مني دوني ... إن بني عمك أوعدوني)\n(أن يقطعوا رأسي إذا لقوني ... ويقتلوني ثم لا يدوني)\n(كلا ورب البيت لو لقوني ... شفعا ووترا لتواكلوني)\n(قد علم الأعداء أن دوني ... ضربا كإيزاغ المخاض الجون)\n(ألا أسب القوم إذ سبوني ... بلى وما مر على دفين)\n(وسابحات بلوى الحجون ... قد جربوني ثم جربوني)\n(حتى إذا شابوا وشيبوني ... أخزاهم الله ولا يخزيني)\n(أشباه أعيار على معين ... أحسسن حس أسد حرون)\n(فهن يضرطن من اليقين ... أنا جميل فتعرفوني)\n(وما تقنعت فتنكروني ... وما أعنيكم لتسألوني)\n(أنمى إلى عادية طحون ... ينشق عنها السيل ذو الشؤون)\n(غمر يدق رجح السفين ... ذو حدب إذا يرى حجون)\n(تنحل أحقاد الرجال دوني ... )\nال ورجز جميل أيضا\n(أنا جميل في السنام من معد ... )\nقد تقدمت هذه الأرجوزة ثم رجز بعده جواس فلم يصنع شيئا قال فما رأيت غلبة مثلها قط","topic":"نسب جميل وأخباره","topicNo":76,"sp":17,"spl":"خروجه إلى الشام — شعره في هجاء خوات العذري وبني الأحب","loc":1448,"partialRef":{"sid":"b76-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b76-23","bab":"الجزء 8","sec":"شعره في هجاء خوات العذري وبني الأحب","page":"ج8 ص145","text":"أخبرنا الحرمي قال حدثنا الزبير قال حدثنا بهلول بن سليمان عن العلاء بن سعيد البلوي وجماعة غيره من قومه أن رجلا من بني عذرة كان يقال له خوات أمه بلوية وكان شاعرا وكان جميل بن جذامية فخرج جميل إلى أخواله بجذام وهو يقول\n(جذام سيوف الله في كل موطن ... إذا أزمت يوم اللقاء أزام)\n(هم منعوا ما بين مصر فذي القرى ... إلى الشام من حل به وحرام)\n(بضرب يزيل الهام عن سكناته ... وطعن كإيزاغ المخاض تؤام)\n(إذا قصرت يوما أكف قبيلة ... عن المجد نالته أكف جذام)\nأعطوه مائة بكرة قال وخرج خوات إلى أخواله من بلي وهو يقول\n(إن بليا غرة يهتدى بها ... كما يهتدي الساري بمطلع النجم)\n(هم ولدوا أمي وكنت ابن أختهم ... ولم أتخول جذم قوم بلا علم)\nقال فأعطوه مائة غرة ما بين فرس إلى وليدة ففخر على صاحبه وذكر أن الغرة الواحدة مما أتى به مما معه تعدل كل شيء أتى به جميل فقال عبيد الله بن قطبة\n(ستقضي بيننا حكماء سعد ... أقطبة كان خيرا أم صباح)\nال وكان عبد الله بن معمر أبو جميل يلقب صباحا وكان عبيد الله بن قطبة يلقب حماظا فقال النخار العذري أحد بني الحارث بن\nسعد قطبة كان خيرا من صباح فقال جميل يهجو بني الأحب رهط قطبة ويهجو النخار\n(إن أحب سفل أشرار ... حثالة عودهم خوار)\n(أذل قوم حين يدعى الجار ... كما أذل الحارث النخار)\nقال الأبيرق العتبي قطبة كان خيرا من صباح فقال جميل\n(يابن الأبيرق وطب بت مسنده ... إلى وسادك من حم الذرى جون)\n(وأكلتان إذا ما شئت مرتفقا ... بالسير من نغل الدفين مدهون)\n(أذكر وأمك مني حين تنكبني ... جني فيغلب جني كل مجنون)\nقال جماعة من شعراء سعد في تفضيل قطبة على صباح أقوالا اجابهم عنها جميل فأفحمهم حتى قال له جعفر بن سراقة أحد بني قرة\n(نحن منعنا ذا القرى من عدونا ... وعذرة إذ نلقى يهودا ويعشرا)\n(منعناه من عليا معد وأنتم ... سفاسيف روح بين قرح وخيبرا)\n(فريقان رهبان بأسفل ذي القرى ... وبالشام عرافون فيمن تنصرا)\nلما بلغت جميلا اتقاه وعلم أنه سيعلو عليه فقال جميل\n(بني عامر أنى انتجعتم وكنتم ... إذا حصل الأقوام كالخصية الفرد)\n(فأنتم ولأي موضع الذل حجرة ... وقرة أولى بالعلاء وبالمجد)\nأعرض عنه جعفر قال الزبير بنو عامر بن ثعلبة بن عبد الله بن ذبيان بن الحارث بن سعد رهط هدبة بن خشرم بن كرز بن ابي حية بن الكاهن وهو سلمة بن أسحم بن عامر بن ثعلبة بن عبد الله بن ذبيان بن سعد هذيم بن زيد وزيادة بن زيد بن مالك بن عامر بن قرة بن خنبس بن عمرو بن ثعلبة بن عبد الله بن ذبيان بن الحارث بن سعد هذيم ولأي بن عبد مناة بن الحارث بن سعد هذيم قال فدخل جميل على هدبة بن خشرم السجن وهو محبوس بدم زيادة بن زيد وأهدى له بردين من ثياب كساه إياهما سعيد بن العاصي وجاءه بنفقة فلما دخل عليه عرض ذلك عليه فقال هدبة أنت يابن قميئة الذي تقول\n(بني عامر أنى انتجعتم وكنتم ... إذا عدد الأقوام كالخصية الفرد)\nما والله لئن خلص الله لي ساقي لأمدن لك مضمارك خذ برديك ونفقتك فخرج جميل فلما بلغ باب السجن خارجا قال اللهم أغن عني أجدع بني عامر وكانت بنو عامر قد قلوا فحالفوا لأيا","topic":"نسب جميل وأخباره","topicNo":76,"sp":17,"spl":"خروجه إلى الشام — شعره في هجاء خوات العذري وبني الأحب","loc":1449},
{"id":"b76-24","bab":"الجزء 8","sec":"لقاؤه بعمر بن أبي ربيعة وتناشدهما الشعر","page":"ج8 ص147","text":"اخبرني الحرمي بن أبي العلاء ومحمد بن مزيد بن أبي الأزهر قالا حدثنا الزبير بن بكار قال حدثنا محمد بن إسماعيل بن إبراهيم المخزومي قال حدثني شيخ من أهلي عن أبيه عن الحارث مولى هشام بن المغيرة الذي يقول له عمر بن أبي ربيعة\n(يا أبا الحارث قلبي طائر ... )\nال شهدت عمر بن أبي ربيعة وجميل بن عبد الله بن معمر وقد اجتمعا بالأبطح فأنشد جميل قصيدته\n(لقد فرح الواشون أن صرمت حبلي ... بثينة أو أبدت لنا جانب البخل)\n(يقولون مهلا يا جميل وإنني ... لأقسم ما بي عن بثينة من مهل)\n(أحلما فقبل اليوم كان أوانه ... أم اخشى فقبل اليوم أوعدت بالقتل)\n(لقد أنكحوا حربي نبيها ظعينة ... لطيفة طي البطن ذات شوى خدل)\n(وكم قد رأينا ساعيا بنميمة ... لآخر لم يعمد بكف ولا رجل)\nإذا ما تراجعنا الذي كان بيننا ... جرى الدمع من عيني بثينة بالكحل\n\n(كلانا بكى أو كاد يبكي صبابة ... إلى إلفه واستعجلت عبرة قبلي)\n(فلو تركت عقلي معي ما طلبتها ... ولكن طلابيها لما فات من عقلي)\n(فيا ويح نفسي حسب نفسي الذي بها ... ويا ويح أهلي ما أصيب به أهلي)\n(وقالت لأتراب لها لا زعانف ... قصار ولا كس الثنايا ولا ثعل)\n(إذا حميت شمس النهار اتقينها ... بأكسية الديباج والخز ذي الخمل)\n(تداعين فاستعجمن مشيا بذي الغضا ... دبيب القطا الكدري في الدمث السهل)\n(إذا ارتعن أو فزعن قمن حوالها ... قيام بنات الماء في جانب الضحل)\n(أجدي لا ألقى بثينة مرة ... من الدهر إلا خائفا أو على رجل)\n(خليلي فيما عشتما هل رأيتما ... قتيلا بكى من حب قاتله قبلي)\nال وأنشده عمر قوله\n(جرى ناصح بالود بيني وبينها ... فقربني يوم الحصاب إلى قتلي)\n(فما أنس م الأشياء لا أنس موقفي ... وموقفها وهنا بقارعة النخل)\n(فلما تواقفنا عرفت الذي بها ... كمثل الذي بي حذوك النعل بالنعل)\n(فقلن لها هذا عشاء وأهلنا ... قريب ألما تسأمي مركب البغل)\n(فقالت فما شئتن قلن لها انزلي ... فللأرض خير من وقوف على رحل)\n(فأقبلن أمثال الدمى فاكتنفنها ... وكل يفدي بالمودة والأهل)\n(نجوم دراري تكنفن صورة ... من البدر وافت غير هوج ولا ثجل)\n(فسلمت واستأنست خيفة أن يرى ... عدو مكاني أو يرى كاشح فعلي)\n(فقالت وألقت جانب الستر إنما ... معي فتحدث غير ذي رقبة أهلي)\n(فقلت لها ما بي لهم من ترقب ... ولكن سري ليس يحمله مثلي)\n(فلما اقتصرنا دونهن حديثنا ... وهن طبيبات بحاجة ذي التبل)\n(عرفن الذي نهوى فقلن ائذني لنا ... نطف ساعة في برد ليل وفي سهل)\n(فقالت فلا تلبثن قلن تحدثي ... أتيناك وانسبن انسياب مها الرمل)\n(وقمن وقد أفهمن ذا اللب إنما ... أتين الذي يأتين من ذاك من أجلي)\nقال جميل هيهات يا أبا الخطاب لا أقول والله مثل هذا سجيس الليالي وما خاطب النساء مخاطبتك أحد وقام مشمرا","topic":"نسب جميل وأخباره","topicNo":76,"sp":18,"spl":"لقاؤه بعمر بن أبي ربيعة وتناشدهما الشعر","song":1,"loc":1450,"partialRef":{"sid":"b2-26","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b76-25","bab":"الجزء 8","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج8 ص150","text":"\n(خليلي فيما عشتما هل رأيتما ... قتيلا بكى من حب قاتله قبلي)\n(أبيت مع الهلاك ضيفا لأهلها ... وأهلي قريب موسعون ذوو فضل)\n(فلو تركت عقلي معي ما طلبتها ... ولكن طلابيها لما فات من عقلي)\nلغناء للغريض ثاني ثقيل بالوسطى عن عمرو وذكر حماد والهشامي أن فيه لنافع الخير مولى عبد الله بن جعفر لحنا من الثقيل الأول ومنها\n(ألا أيها البيت الذي حيل دونه ... بنا أنت من بيت وأهلك من أهل)\n(ثلاثة أبيات فبيت أحبه ... وبيتان ليسا من هواي ولا شكلي)\n(كلانا بكى أو كاد يبكي صبابة ... إلى إلفه واستعجلت عبرة قبلي)\nالغناء لإسحاق خفيف ثقيل الثاني بالبنصر ومنها\n(لقد فرح الواشون أن صرمت حبلي ... بثينة أو أبدت لنا جانب البخل)\n(يقولون مهلا يا جميل وإنني ... لأقسم ما بي عن بثينة من مهل)\nلغناء لابن محرز من كتاب يونس ولم يجنسه وذكر إسحاق أنه مما ينسب إلى ابن محرز وابن مسجح ولم يصح عنده لأيهما هو ولا ذكر طريقته أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني غير واحد من الرواة عن صالح بن حسان قال أخبرني نافع مولى عبد الله بن جعفر وما رأيت أحدا قط كان أشكل ظرفا ولا أزين في مجلس ولا أحسن غناء منه قال قدمنا مع عبد الله بن جعفر مرة على معاوية فأرسل إلي يزيد يدعوني ليلا فقلت أكره أن يعلم أمير المؤمنين مكاني عندك فيشكوني إلى ابن جعفر قال فامهل حتى إذا سمر أمير المؤمنين فإن ابن جعفر يكون معه فلا يفتقدك ونخلو نحن بما نريد قبل قيامهما قأتيته فغنيته فوالله ما رأيت فتى أشرف أريحية منه والله لألقى علي من الكسا الخز والوشي وغيره ما لم استطع حمله ثم أمر لي بخمسمائة دينار قال وذهب بنا الحديث وما كنا فيه حتى قام معاوية ونهض ابن جعفر معه وكان باب يزيد في سقيفة معاوية فسمع صوتي فقال لابن جعفر ما هذا يابن جعفر قال هذا والله صوت نافع فدخل علينا فلما أحس به يزيد تناوم فقال له معاوية ما لك يا بني قال\nصدعت فرجوت أن يسكن عني بصوت هذا قال فتبسم معاوية وقال يا نافع ما كان أغنانا عن قدومك فقال له ابن جعفر يا أمير المؤمنين إن هذا في بعض الأحايين يذكي القلب قال فضحك معاوية وانصرف فقال لي ابن جعفر ويلك هل شرب شيئا قلت لا والله قال والله إني لأرجو أن يكون من فتيان بني عبد مناف الذين ينتفع بهم قال نافع ثم قدمنا على يزيد مع عبد الله بن جعفر بعدما استخلف فأجلسه معه على سريره ودخلت حاشيته تسلم عليه ودخلت معهم فلما نظر إلي تبسم ثم نهض ابن جعفر وتبعناه فقيل له نظر إلى نافع وتبسم فقال ابن جعفر هذا تأويل تلك الليلة فقضى حوائج ابن جعفر وأضعف ما كان يصله به معاوية فلما أراد الانصراف أتاه يودعه ونحن معه فأرسل إلي يزيد فدخلت عليه قال ويحك يا نافع ما أخرتك إلا لأتفرغ لك هات لحنك\n(خليلي فيما عشتما هل رايتما ... قتيلا بكى من حب قاتله قبلي)\nأسمعته فقال أعد ويلك فأعدته ثم قال أعد فأعدته ثلاثا فقال أحسنت فسل حاجتك فما سألته في ذلك اليوم شيئا إلا أعطانيه ثم قال إن يصلح لنا هذا الأمر من قبل ابن الزبير فلعلنا أن نحج فتلقانا بالمدينة فإن هذا الأمر لا يصلح إلا هناك قال نافع فمنعنا والله من ذلك شؤم ابن الزبير أخبرني الحرمي قال حدثنا الزبير قال حدثنا محمد بن إسماعيل بن إبراهيم الجعفري قال حدثنا القاسم بن أبي الزناد قال خرج عمر بن أبي ربيعة يريد الشام فلما كان بالجناب لقيه جميل فقال له عمر أنشدني فأنشده\n(خليلي فيما عشتما هل رايتما ... قتيلا بكى من حب قاتله قبلي)\nثم قال جميل أنشدني يا ابا الخطاب فأنشده\n(ألم تسأل الأطلال والمتربعا ... ببطن حليات دوارس بلقعا)\nلما بلغ إلى قوله\n(فلما تواقفنا وسلمت أشرقت ... وجوه زهاها الحسن أن تتقنعا)\n(تبالهن بالعرفان لما عرفنني ... وقلن امرؤ باغ أكل وأوضعا)\n(وقربن اسباب الهوى لمتيم ... يقيس ذراعا كلما قسن إصبعا)","topic":"نسب جميل وأخباره","topicNo":76,"sp":19,"spl":"نسبة ما في هذا الخبر من الأغاني","song":3,"loc":1451},
{"id":"b76-26","bab":"الجزء 8","sec":"عمر بن أبي ربيعة يطلب منه أن يأخذ به إلى بثينة","page":"ج8 ص153","text":"قال فصاح جميل واستخذى وقال ألا إن النسيب أخذ من هذا وما أنشده حرفا فقال له عمر إذهب بنا إلى بثينة حتى نسلم عليها فقال له جميل قد أهدر لهم السلطان دمي إن وجدوني عندها وهاتيك أبياتها فأتاها عمر حتى وقف على ابياتها وتأنس حتى كلم فقال يا جارية أنا عمر بن أبي ربيعة فأعلمي بثينة مكاني فخرجت إليه بثينة في مباذلها وقالت والله يا عمر لا أكون من نسائك اللاتي يزعمن أن قد قتلهن الوجد بك فانكسر عمر قال وإذا امرأة أدماء طوالة\nوأخبرني بهذا الخبر علي بن صالح عن أبي هفان عن إسحاق عن المسيبي والزبير فذكر مثل ما ذكره الزبير وزاد فيه قال فقال لها قول جميل\n(وهما قالتا لوان جميلا ... عرض اليوم نظرة فرآنا)\n(بينما ذاك منهما وإذا بي ... أعمل النص سيرة زفيانا)\n(نظرت نحو تربها ثم قالت ... قد أتانا وما علمنا منانا)\nقالت إنه استملى منك فما أفلح وقد قيل اربط الحمار مع الفرس\nفإن لم يتعلم من جريه تعلم من خلقه وذكر الهيثم بن عدي وأصحابه في أخبارهم أن جميلا طال مقامه بالشام ثم قدم وبلغ بثينة خبره فراسلته مع بعض نساء الحي تذكر شوقها إليه ووجدها به وطلبها للحيلة في لقائه وواعدته لموضع يلتقيان فيه فسار إليها وحدثها طويلا وأخبرها خبره بعدها وقد كان أهلها رصدوها فلما فقدوها تبعها أبوها وأخوها حتى هجما عليهما فوثب جميل فانتضى سيفه وشد عليهما فاتقياه بالهرب وناشدته بثينة الله إلا انصرف وقالت له إن أقمت فضحتني ولعل الحي أن يلحقوك فأبى وقال أنا مقيم وامضي أنت وليصنعوا ما أحبوا فلم تزل تناشده حتى انصرف وقال في ذلك وقد هجرته وانقطع التلاقي بينهما مدة\n(ألم تسأل الربع الخلاء فينطق ... وهل تخبرنك اليوم بيداء سملق)\n(وقفت بها حتى تجلت عمايتي ... ومل الوقوف الأرحبي المنوق)\n(تعز وإن كانت عليك كريمة ... لعلك من رق لبثنة تعتق)\n(لعمركم إن البعاد لشائقي ... وبعض بعاد البين والنأي أشوق)\n(لعلك محزون ومبد صبابة ... ومظهر شكوى من أناس تفرقوا)\n(وبيض غريرات تثني خصورها ... إذا قمن أعجاز ثقال وأسؤق)\n(غرائر لم يلقين بؤس معيشة ... يجن بهن الناظر المتنوق)\n(وغلغلت من وجد إليهن بعدما ... سريت وأحشائي من الخوف تخفق)\n(معي صارم قد أخلص القين صقله ... له حين أغشيه الضريبة رونق)\n(فلولا احتيالي ضقن ذرعا بزائر ... به من صبابات إليهن أولق)\n(تسوك بقضبان الأراك مفلجا ... يشعشع فيه الفارسي المروق)\n(أبثنة للوصل الذي كان بيننا ... نضا مثل ما ينضو الخضاب فيخلق)\n(أبثنة ما تنأين إلا كأنني ... بنجم الثريا ما نأيت معلق)\nخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال دخلت على الرشيد يوما فقال لي يا إسحاق أنشدني أحسن ما تعرف في عتاب محب وهو ظالم متعتب فقلت يا أمير المؤمنين قول جميل\n(رد الماء ما جاءت بصفو ذنائبه ... ودعه إذا خيضت بطرق مشاربه)\n(أعاتب من يحلو لدي عتابه ... وأترك من لا أشتهي وأجانبه)\n(ومن لذة الدنيا وإن كنت ظالما ... عناقك مظلوما وأنت تعاتبه)\nقال أحسن والله أعدها علي فأعدتها حتى حفظها وأمر لي بثلاثين ألف درهم وتركني وقام فدخل إلى دار الحرم","topic":"نسب جميل وأخباره","topicNo":76,"sp":20,"spl":"عمر بن أبي ربيعة يطلب منه أن يأخذ به إلى بثينة","loc":1452},
{"id":"b76-27","bab":"الجزء 8","sec":"فشل محاولته في لقاء بثينة","page":"ج8 ص156","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن السعيدي قال حدثني رجل كان يصحب جميلا من أهل تيماء قال كنت يوما جالسا مع جميل وهو يحدثني وأحدثه إذ ثار وتربد وجهه فأنكرته ورأيت منه غير ما كنت أرى ووثب نافرا مقشعر الشعر متغير اللون حتى أتي بناقة له قريبة من الأرض مجتمعة موثقة الخلق فشد عليها رحله ثم أتي بمحلب فيه لبن فشربه ثم ثنى فشربت حتى رويت ثم قال لي اشدد أداة رحلك واشرب واسق جملك فإني ذاهب بك إلى بعض مذاهبي ففعلت فجال في ظهر ناقته وركبت ناقتي فسرنا بياض يومنا وسواد ليلتنا ثم أصبحنا فسرنا يومنا كله لا والله ما نزلنا إلا للصلاة فلما كان اليوم الثالث دفعنا إلى نسوة فمال إليهن ووجدنا الرجال خلوفا وإذا قدر لبن ثم وقد جهدت جوعا وعطشا فلما رأيت القدر اقتحمت عن بعيري وتركته جانبا ثم أدخلت رأسي في القدر ما يثنيني حرها حتى رويت فذهبت أخرج رأسي من القدر فضاقت علي وإذا هي على رأسي قلنسية فضحكن مني وغسلن ما أصابني وأتي جميل بقرى فوالله ما التفت إليه فبينا هو يحدثهن إذا رواعي الإبل وقد كان السلطان أحل لهم دمه إن وجدوه في بلادهم وجاء الناس فقالوا له ويحك انج وتقدم فوالله ما أكبرهم كل الإكبار وغشيه الرجال فجعلوا يرمونه ويطردونه فإذا قربوا منه قاتلهم ورمى فيهم وهام بي جملي فقال لي يسر لنفسك مركبا خلفي فأردفني خلفه ولا والله ما انكسر ولا انحل عن\nفرصته حتى رجع إلى أهله وقد سار ست ليال وستة ايام وما التفت إلى طعام","topic":"نسب جميل وأخباره","topicNo":76,"sp":21,"spl":"فشل محاولته في لقاء بثينة","loc":1453},
{"id":"b76-28","bab":"الجزء 8","sec":"ابن عمه روق يلومه على حبه بثينة","page":"ج8 ص157","text":"وشكا زوج بثينة إلى أبيها وأخيها إلمام جميل بها فوجهوا إلى جميل فأعذروا إليه وشكوه إلى عشيرته وأعذروا إليهم وتوعدوه وإياهم فلامه أهله وعنفوه وقالوا استخلص إليهم ونبرأ منك ومن جريرتك فأقام مدة لا يلم بها ثم لقي ابني عمه روقا ومسعدة فشكا إليهما ما به وأنشدهما قوله\n(زورا بثينة فالحبيب مزور ... إن الزيارة للمحب يسير)\n(إن الترحل إن تلبس أمرنا ... واعتاقنا قدر أحم بكور)\nلغناء لعريب رمل بالوسطى\n(إني عشية رحت وهي حزينة ... تشكو إلي صبابة لصبور)\n(وتقول بت عندي فديتك ليلة ... أشكو إليك فإن ذاك يسير)\nلغناء لسليم خفيف رمل بالوسطى عن عمرو وفيه ثقيل أول بالبنصر ذكر الهشامي أنه لمخارق وذكر حبش أنه لإبراهيم وذكر حبش أن لحن\nمخارق خفيف رمل\n(غراء مبسام كأن حديثها ... در تحدر نظمه منثور)\n(محطوطة المتنين مضمرة الحشى ... ريا الروادف خلقها ممكور)\n(لا حسنها حسن ولا كدلالها ... دل ولا كوقارها توقير)\n(إن اللسان بذكرها لموكل ... والقلب صاد والخواطر صور)\n(ولئن جزيت الود مني مثله ... إني بذلك يا بثين جدير)\nقال له روق إنك لعاجر ضعيف في استكانتك لهذه المرأة وتركك الاستبدال بها مع كثرة النساء ووجود من هو أجمل منها وإنك منها بين فجور أرفعك عنه أو ذل لا أحبه لك أو كمد يؤديك إلى التلف أو مخاطرة بنفسك لقومها إن تعرضت لها بعد إعذارهم إليك وإن صرفت نفسك عنها وغلبت هواك فيها وتجرعت مرارة الحزم حتى تألفها وتصبر نفسك عليها طائعة أو كارهة الفت ذلك وسلوت فبكى جميل وقال يا أخي لو ملكت اختياري لكان ما قلت صوابا ولكني لا أملك الاختيار ولا أنا إلا كالأسير لا يملك لنفسه نفعا وقد جئتك لأمر أسالك ألا تكدر ما رجوته عندك فيه بلوم وأن تحمل على نفسك في مساعدتي فقال له فإن كنت لا بد مهلكا نفسك فاعمل على زيارتها ليلا فإنها تخرج مع بنات عم لها إلى ملعب لهن فأجيء معك حينئذ سرا ولي أخ من رهط بثينة من بني الأحب نأوي عنده نهارا وأسأله مساعدتك على هذا فتقيم عنده أياما نهارك وتجتمع معها بالليل إلى أن تقضي أربك فشكره ومضى روق إلى الرجل الذي من رهط بثينة فأخبره الخبر واستعهده كتمانه وسأله مساعدته فيه فقال له لقد جئتني بإحدى العظائم ويحك إن في هذا\nمعاداتي الحي جميعا إن فطن به فقال انا أتحرز في أمره من أن يظهر فواعده في ذلك ومضى إلى جميل فأخبره القصة فأتيا الرجل ليلا فأقاما عنده وأرسل إلى بثينة بوليدة له بخاتم جميل فدفعته إليها فلما رأته عرفت فتبعتها وجاءته فتحدثا ليلتهما واقام بموضعه ثلاثة أيام ثم ودعها وقال لها عن غير قلى والله ولا ملل يا بثينة كان وداعي لك ولكني قد تذممت من هذا الرجل الكريم وتعريضه نفسه لقومه وأقمت عنده ثلاثا ولا مزيد على ذلك ثم انصرف وقال في عذل روق ابن عمه إياه\n(لقد لامني فيها أخ ذو قرابة ... حبيب إليه في ملامته رشدي)\n(وقال أفق حتى متى أنت هائم ... ببثنة فيها قد تعيد وقد تبدي)\n(فقلت له فيها قضى الله ما ترى ... علي وهل فيما قضى الله من رد)\n(فإن يك رشدا حبها أو غواية ... فقد جئته ما كان مني على عمد)\n\n(لقد لج ميثاق من الله بيننا ... وليس لمن لم يوف لله من عهد)\n(فلا وأبيها الخير ما خنت عهدها ... ولا لي علم بالذي فعلت بعدي)\n(وما زادها الواشون إلا كرامة ... علي وما زالت مودتها عندي)\nلغناء لمتيم ثقيل أول عن الهشامي وذكر ابن المعتز أنه لشارية وذكر ابن خرداذبه أنه لقلم الصالحية\n(أفي الناس أمثالي أحب فحالهم ... كحالي أم أحببت من بينهم وحدي)\n(وهل هكذا يلقى المحبون مثل ما ... لقيت بها أم لم يجد أحد وجدي)\nوقال جميل فيها\n(خليلي عوجا اليوم حتى تسلما ... على عذبة الأنياب طيبة النشر)\n(ألما بها ثم اشفعا لي وسلما ... عليها سقاها الله من سائغ القطر)\n(وبوحا بذكري عند بثنة وانظرا ... أترتاح يوما أم تهش إلى ذكري)\n(فإن لم تكن تقطع قوى الود بيننا ... ولم تنس ما أسلفت في سالف الدهر)","topic":"نسب جميل وأخباره","topicNo":76,"sp":22,"spl":"ابن عمه روق يلومه على حبه بثينة","song":3,"loc":1454},
{"id":"b76-29","bab":"الجزء 8","sec":"ابن عمه روق يلومه على حبه بثينة","page":"ج8 ص157","text":"سوف يرى منها اشتياق ولوعة ... ببين وغرب من مدامعها يجري وإن تك قد حالت عن العهد بعدنا ... وأصغت إلى قول المؤنب والمزري فسوف يرى منها صدود ولم تكن ... بنفسي من أهل الخيانة والغدر أعوذ بك اللهم أن تشحط النوى ... ببثنة في أدنى حياتي ولا حشري وجاور إذا ما مت بيني وبينها ... فيا حبذا موتي إذا جاورت قبري عدمتك من حب أما منك راحة وما بك عني من توان ولا فتر ألا أيها الحب المبرح هلى ترى ... أخا كلف يغري بحب كما أغري أجدك لا تبلى وقد بلي الهوى ... ولا ينتهي حبي بثينة للزجر\nوت\n(هي البدر حسنا والنساء كواكب ... وشتان ما بين الكواكب والبدر)\n(لقد فضلت حسنا على الناس مثلما ... على ألف شهر فضلت ليلة القدر)\nنت شارية في هذين البيتين خفيف رمل من رواية ابن المعتز","topic":"نسب جميل وأخباره","topicNo":76,"sp":23,"spl":"ابن عمه روق يلومه على حبه بثينة — صلح بعد تهاجر","loc":1455},
{"id":"b76-30","bab":"الجزء 8","sec":"صلح بعد تهاجر","page":"ج8 ص160","text":"أخبرني محمد بن خلف بن المرزبان قال أخبرنا إسحاق بن محمد بن أبان قال حدثني الرحال بن سعد المازني قال وقع بين جميل وبثينة هجر في غيرة كان غارها عليها من فتى كان يتحدث إليها من بني عمها فكان جميل يتحدث إلى غيرها فيشق ذلك على بثينة وعلى جميل وجعل كل واحد منهما يكره أن يبدي لصاحبه شأنه فدخل جميل يوما وقد غلبه الأمر إلى البيت الذي كان يجتمع فيه مع بثينة فلما رأته بثينة جاءت إلى البيت ولم تبرز له فجزع لذلك جميل وجعل كل واحد منهما يطالع صاحبه وقد بلغ الأمر من جميل كل مبلغ فأنشأ يقول\n(لقد خفت أن يغتالني الموت عنوة ... وفي النفس حاجات إليك كما هيا)\n(وإني لتثنيني الحفيظة كلما ... لقيتك يوما أن أبثك ما بيا)\n(ألم تعلمي يا عذبة الريق أنني ... أظل إذا لم أسق ريقك صاديا)\nال فرقت له بثينة وقالت لمولاة لها كانت معها ما أحسن الصدق بأهله ثم اصطلحا فقالت له بثينة أنشدني قولك\n(تظل وراء الستر ترنو بلحظها ... إذا مر من أترابها من يروقها)\nأنشدها إياها فبكت وقالت كلا يا جميل ومن ترى أنه يروقني غيرك","topic":"نسب جميل وأخباره","topicNo":76,"sp":23,"spl":"ابن عمه روق يلومه على حبه بثينة — صلح بعد تهاجر","loc":1456},
{"id":"b76-31","bab":"الجزء 8","sec":"كيف نعي جميل إلى بثينة","page":"ج8 ص161","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال ذكر أيوب بن عباية قال\nخرجت من تيماء في أغباش السحر فرأيت عجوزا على أتان فتكلمت فإذا أعرابية فصيحة فقلت ممن أنت فقالت عذرية فأجريت ذكر جميل وبثينة فقالت والله إنا لعلى ماء لنا بالجناب وقد تنكبنا الجادة لجيوش كانت تأتينا من قبل الشام تريد الحجاز وقد خرج رجالنا لسفر وخلفوا معنا أحداثا فانحدروا ذات عشية إلى صرم قريب منا يتحدثون إلى جوار منهم فلم يبق غيري وغير بثينة إذ انحدر علينا منحدر من هضبة تلقاءنا فسلم ونحن مستوحشون وجلون فتأملته ورددت السلام فإذا جميل فقلت أجميل قال إي والله وإذا به لا يتماسك جوعا فقمت إلى قعب لنا فيه أقط مطحون وإلى عكة فيها سمن ورب فعصرتها على الأقط ثم أدنيتها منه وقلت أصب من هذا فأصاب منه وقمت إلى سقاء فيه لبن فصببت عليه ماء باردا فشرب منه وتراجعت نفسه فقلت له لقد بلغت ولقيت شرا فما أمرك قال أنا والله في هذه الهضبة التي ترين منذ ثلاث ما أريمها أنتظر أن أرى فرجة فلما رأيت منحدر فتيانكم أتيتكم لأودعكم وأنا عامد إلى مصر فتحدثنا ساعة ثم ودعنا وشخص فلم تطل غيبته أن جاءنا نعيه فزعموا أنه قال حين حضرته الوفاة\n(صدع النعي وما كنى بجميل ... وثوى بمصر ثواء غير قفول)\n(ولقد أجر الذيل في وادي القرى ... نشوان بين مزارع ونخيل)\n(قومي بثينة فاندبي بعويل ... وابكي خليلك دون كل خليل)\nأخبرني أبو الحسن الأسدي قال حدثني محمد بن القاسم عن الأصمعي قال حدثني رجل شهد جميلا لما حضرته الوفاة بمصر أنه دعاه فقال هل لك في أن أعطيك كل ما أخلفه على أن تفعل شيئا أعهده إليك فقال قلت اللهم نعم قال إذا أنا مت فخذ حلتي هذه التي في عيبتي فاعزلها جانبا ثم كل شيء سواها لك وارحل إلى رهط بني الأحب من عذرة وهم رهط بثينة فإذا صرت إليهم فارتحل ناقتي هذه واركبها ثم البس حلتي هذه واشققها ثم اعل على شرف وصح بهذه الأبيات وخلاك ذم ثم أنشدني هذه الأبيات\n(صدع النعي وما كنى بجميل ... وثوى بمصر ثواء غير قفول)\nذكر الأبيات المتقدمة فلما قضى وواريته أتيت رهط بثينة ففعلت ما أمرني به جميل فما استتممت الأبيات حتى برزت إلي امرأة يتبعها نسوة قد فرعتهن طولا وبرزت أمامهن كأنها بدر قد برز في دجنة وهي تتعثر في مرطها حتى أتتني فقالت يا هذا والله لئن كنت صادقا لقد قتلتني ولئن كنت كاذبا لقد فضحتني قلت والله ما أنا إلا صادق وأخرجت حلته فلما رأتها صاحت بأعلى صوتها وصكت وجهها واجتمع نساء الحي يبكين معها ويندبنه حتى صعقت فمكثت مغشيا عليها ساعة ثم قامت وهي تقول\n(وإن سلوي عن جميل لساعة ... من الدهر ما حانت ولا حان حينها)\n(سواء علينا يا جميل بن معمر ... إذا مت بأساء الحياة ولينها)\nال فلم أر يوما كان أكثر باكيا وباكية منه يومئذ\n","topic":"نسب جميل وأخباره","topicNo":76,"sp":24,"spl":"كيف نعي جميل إلى بثينة — من المائة المختارة من رواية جحظة عن أصحابه","song":1,"loc":1457},
{"id":"b76-32","bab":"الجزء 8","sec":"من المائة المختارة من رواية جحظة عن أصحابه","page":"ج8 ص164","text":"(أمسى الشباب مودعا محمودا ... والشيب مؤتنف المحل جديدا)\n(وتغير البيض الأوانس بعد ما ... حملتهن مواثقا وعهودا)\nروضه من الكامل الشعر ليزيد بن الطثرية والغناء لإسحاق ولحنه المختار من الثقيل الأول بالبنصر وفيه لبابويه خفيف ثقيل بالوسطى كلاهما من رواية عمرو بن بانة","topic":"نسب جميل وأخباره","topicNo":76,"sp":24,"spl":"كيف نعي جميل إلى بثينة — من المائة المختارة من رواية جحظة عن أصحابه","loc":1458},
{"id":"b77-1","bab":"الجزء 8","sec":"ذكر يزيد بن الطثرية وأخباره ونسبه","page":"ج8 ص165","text":"ذكر ابن الكلبي أن اسمه يزيد بن الصمة أحد بني سلمة الخير بن قشير وذكر البصريون أنه من ولد الأعور بن قشير وقال ابو عمرو الشيباني اسمه يزيد بن سلمة بن سمرة بن سلمة الخير بن قشير بن كعب بن ربيعة بن عامر بن صعصعة وإنما قيل إنه يزيد بن المنتشر بن سلمة\nوالطثرية أمه فيما أخبرني به علي بن سليمان الأخفش عن السكري عن محمد بن حبيب امرأة من طثر وهم حي من اليمن عدادهم في جرم وقال غيره إن طثرا من عنز بن وائل إخوة بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار وكان أبو جراد أحد بني المنتفق بن عامر بن عقيل أسر طثرا فمكث عنده زمانا ثم خلاه وأخذ عليه إصرا ليبعثن إليه بفدائه أو ليأتينه بنفسه وأهله فلم يجد فداء فاحتمل بأهله حتى دخل على أبي جراد فوسمه سمة إبله فهم حلفاء لبني المنتفق إلى اليوم نحو من خمسمائة رجل متفرقين في بني عقيل يوالون بني المنتفق وهم يعيرون ذلك الوسم وقال بعض من يهجو\n(عليه الوسم وسم أبي جراد ... )\nفيهم يقول يزيد بن الطثرية\n(الا بئسما أن تجرموني وتغضبوا ... علي إذا عاتبتكم يا بني طثر)\nزعم بعض البصريين أن الطثرية أم يزيد كانت مولعة بإخراج زبد اللبن فسميت الطثرية وطثرة اللبن زبدته","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":0,"spl":"ذكر يزيد بن الطثرية وأخباره ونسبه","loc":1459,"partial":1},
{"id":"b77-2","bab":"الجزء 8","sec":"سبب تلقيبه بالمودق","page":"ج8 ص166","text":"ويكنى يزيد أبا المكشوح وكان يلقب مودقا سمي بذلك لحسن وجهه وحسن شعره وحلاوة حديثه فكانوا يقولون إنه إذا جلس بين النساء ودقهن أخبرني محمد بن خلف عن حماد بن إسحاق عن أبيه قال كان يزيد بن الطثرية يقول من أفحم عند النساء فلينشد من شعري قال وكان كثيرا ما يتحدث إلى النساء وكان يقال إنه عنين وروى عنه عبد الله بن عمر عن يحيى بن جابر أحد بني عمرو بن كلاب عن سعاد بنت يزيد بن زريق امرأة منهم أن يزيد بن الطثرية كان من أحسن من مضى وجها وأطيبه حديثا وأن النساء كانت مفتونة به وذكر الناس أنه كان عنينا وذلك أنه لا عقب له وأن الناس أمحلوا حتى ذهبت الدقيقة من المال ونهكت الجليلة فأقبل صرم\nمن جرم ساقته السنة والجدب من بلاده إلى بلاد بني قشير وكان بينهم وبين بني قشير حرب عظيمة فلم يجدوا بدا من رمي قشير بأنفسهم لما قد ساقهم من الجدب والمجاعة ودقة الأموال وما أشرفوا عليه من الهلكة ووقع الربيع في بلاد بني قشير فانتجعها الناس وطلبوها فلم يعد أن لقيت جرم قشيرا فنصبت قشير لهم الحرب فقالت جرم إنما جئنا مستجيرين غير محاربين قالوا مما ذا قالوا من السنة والجدب والهلكة التي لا باقية لها فأجارتهم قشير وسالمتهم وأرعتهم طرفا من بلادها وكان في جرم فتى يقال له مياد وكان غزلا حسن الوجه تام القامة آخذا بقلوب النساء والغزل في جرم جائز حسن وهو في قشير نائرة فلما نازلت جرم قشيرا وجاورتها اصبح مياد الجرمي فغدا إلى القشيريات يطلب منهن الغزل والصبا والحديث واستبراز الفتيات عند غيبة الرجال واشتغالهم بالسقي والرعية وما أشبه ذلك فدفعنه عنهن وأسمعنه ما يكره وراحت رجالهن عليهن وهن مغضبات فقال عجائز منهن والله ما ندري أرعيتم جرما المرعى أم أرعيتموهم نساءكم فاشتد ذلك عليهم فقالوا وما أدراكنه قلن رجل منذ اليوم ظل مجحرا لنا ما يطلع منا رأس واحدة يدور بين بيوتنا فقال بعضهم بيتوا جرما فاصطلموها وقال بعضهم قبيح قوم قد سقيتموهم مياهكم وأرعيتموهم مراعيكم وخلطتموهم بأنفسكم وأجرتموهم من القحط والسنة تفتانون عليهم هذا الافتيات لا تفعلوا ولكن تصبحوا وتقدموا إلى هؤلاء القوم في هذا الرجل فإنه سفيه من سفهائهم فليأخذوا على يديه فإن يفعلوا فأتموا لهم إحسانكم وإن يمتنعوا ويقروا ما كان منه يحل لكم البسط عليهم وتخرجوا من ذمتهم فأجمعوا على ذلك فلما\nأصبحوا غدا نفر منهم إلى جرم فقالوا ما هذه البدعة التي قد جاورتمونا بها إن كانت هذه البدعة سجية لكم فليس لكم عندنا إرعاء ولا إسقاء فبرزوا عنا أنفسكم وأذنوا بحرب وإن كان افتتانا فغيروا على من فعله وإنهم لم يعدوا أن قالوا لجرم ذلك فقام رجال من جرم وقالوا ما هذا الذي نالكم قالوا رجل منكم أمس ظل يجر أذياله بين ابياتنا ما ندري علام كان أمره فقهقهت جرم من جفاء القشيرين وعجرفيتها وقالوا إنكم لتحسون من نسائكم ببلاء ألا فابعثوا إلى بيوتنا رجلا ورجلا فقالوا والله ما نحس من نسائنا ببلاء وما نعرف منهن إلا العفة والكرم ولكن فيكم الذي قلتم قالوا فإنا نبعث رجلا إلى بيوتكم يا بني قشير إذا غدت الرجال وأخلف النساء وتبعثون رجلا إلى البيوت ونتحالف أنه لا يتقدم رجل منا إلى زوجة ولا أخت ولا بنت ولا يعلمها بشيء مما دار بين القوم فيظل كلاهما في بيوت أصحابه حتى يردا علينا عشيا الماء وتخلى لهما البيوت ولا تبرز عليهما امرأة ولا تصادق منهما واحدا فيقبل منهما صرف ولا عدل إلا بموثق يأخذه عليها وعلامة تكون معه منها قالوا اللهم نعم فظلوا يومهم ذلك وباتوا ليلتهم حتى إذا كان من الغد غدوا إلى الماء وتحالفوا أنه لا يعود إلى البيوت منهم أحد دون الليل وغدا مياد الجرمي إلى القشيريات وغدا يزيد بن الطثرية القشيري إلى الجرميات فظل عندهن بأكرم مظل لا يصير إلى واحدة منهن إلا افتتنت به وتابعته إلى المودة والإخاء وقبض منها رهنا وسألته ألا يدخل من بيوت جرم إلا بيتها فيقول لها واي شيء تخافين وقد أخذت مني المواثيق والعهود وليس لأحد في قلبي نصيب غيرك حتى صليت العصر فانصرف يزيد بفتخ كثير وذبل","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":1,"spl":"سبب تلقيبه بالمودق","loc":1460},
{"id":"b77-3","bab":"الجزء 8","sec":"سبب تلقيبه بالمودق","page":"ج8 ص166","text":"وبراقع وانصرف مكحولا مدهونا شبعان ريان مرجل اللمة وظل مياد الجرمي يدور بين بيوت القشيريات مرجوما مقصى لا يتقرب إلى بيت إلا استقبلته الولائد بالعمد والجندل فتهالك لهن وظن أنه ارتياد منهن له حتى أخذه ضرب كثير بالجندل ورأى البأس منهن وجهده العطش فانصرف حتى جاء إلى سمرة قريبا إلى نصف النهار فتوسد يده ونام تحتها نويمة حتى أفرجت عنه الظهيرة وفاءت الأظلال وسكن بعض ما به من ألم الضرب وبرد عطشه قليلا ثم قرب إلى الماء حتى ورد على القوم قبل يزيد فوجد أمة تذود غنما في بعض الظعن فأخذ برقعها فقال هذا برقع واحدة من نسائكم فطرحه بين يدي القوم وجاءت الأمة تعدو فتعلقت ببرقعها فرد عليها وخجل مياد خجلا شديدا وجاء يزيد ممسيا وقد كاد القوم أن يتفرقوا فنثر كمه بين ايديهم ملآن براقع وذبلا وفتخا وقد حلف القوم ألا يعرف رجل شيئا إلا رفعه فلما نثر ما معه اسودت وجوه جرم وأمسكوا بأيديهم إمساكة فقالت قشير أنتم تعرفون ما كان بيننا أمس من العهود والمواثيق وتحرج الأموال والأهل فمن شاء أن ينصرف إلى حرام فليمسك يده فبسط كل رجل يده إلى ما عرف فأخذه وتفرقوا عن حرب وقالوا هذه مكيدة يا قشير فقال في ذلك يزيد بن الطثرية\n(فإن شئت يا مياد زرنا وزرتم ... ولم ننفس الدنيا على من يصيبها)\n(أيذهب مياد بألباب نسوتي ... ونسوة مياد صحيح قلوبها)\nقال مياد الجرمي\n(لعمرك إن جمع بني قشير ... لجرم في يزيد لظالمونا)\n(أليس الظلم أن اباك منا ... وأنك في كتيبة آخرينا)\n(أحالفة عليك بنو قشير ... يمين الصبر أم متحرجونا)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":2,"spl":"سبب تلقيبه بالمودق","loc":1461},
{"id":"b77-4","bab":"الجزء 8","sec":"حبه لوحشية ومرضه لغيابها","page":"ج8 ص170","text":"قال وبلي يزيد بعشق جارية من جرم في ذلك اليوم يقال لها وحشية وكانت من أحسن النساء ونافرتهم جرم فلم يجد إليها سبيلا فصار من العشق إلى أن أشرف على الموت واشتد به الجهد فجاء إلى ابن عم له يقال له خليفة بن بوزل بعد اختلاف الأطباء إليه ويأسهم منه فقال له يابن عم قد تعلم أنه ليس إلى هذه المرأة سبيل وأن التعزي أجمل فما أربك في أن تقتل نفسك وتأثم بربك قال وما همي يابن عم بنفسي وما لي فيها أمر ولا نهي ولا همي إلا نفس الجرمية فإن كنت تريد حياتي فأرنيها قال كيف الحيلة قال تحملني إليها فحمله إليها وهو لا يطمع في الجرمية إلا أنهم كانوا إذا قالوا له نذهب بك إلى وحشية أبل قليلا وراجع وطمع وإذا أيس منها اشتد به الوجع فخرج به خليفة بن بوزل فحمله فتخلل به اليمن حتى إذا دخل في قبيلة انتسب إلى أخرى ويخبر أنه طالب حاجة وأبل حتى صلح بعض الصلاح وطمع فيه ابن عمه وصارا بعد زمان إلى حي وحشية فلقيا الرعيان وكمنا في جبل من الجبال فجعل خليفة ينزل فيتعرض لرعيان الشاء فيسألهم عن راعي وحشية حتى لقي غلامها وغنمها فواعدهم موعدا وسألهم ما حال\nوحشية فقال غلامها هي والله بشر لا حفظ الله بني قشير ولا يوما رأيناهم فيه فما زالت عليلة منذ رأيناهم وكان بها طرف مما بابن الطثرية فقال ويحك فإن ها هنا إنسانا يداويها فلا تقل لأحد غيرها قال نعم إن شاء الله تعالى فأعلمها الراعي ما قال له الرجل حين صار إليها فقالت له ويحك فجىء به ثم إنه خرج فلقيه بالغد فأعلمه وظل عنده يرعى غنمه وتأخر عن الشاء حتى تقدمته الشاء وجنح الليل وانحدر بين يدي غنمه حتى أراحها ومشى فيها يزيد حتى قربت من البيت على أربع وتجلل شملة سوداء بلون شاة من الغنم فصار إلى وحشية فسرت به سرورا شديدا وأدخلته سترا لها وجمعت عليه من الغد من تثق به من صواحباتها وأترابها وقد كان عهد إلى ابن عمه أن يقيم في الجبل ثلاث ليال فإن لم يره فلينصرف فأقام يزيد عندها ثلاث ليال ورجع إلى أصح ما كان عليه ثم انصرف فصار إلى صاحبه فقال ما وراءك يا يزيد ورأى من سروره وطيب نفسه ما سره فقال\n(لوانك شاهدت الصبا يابن بوزل ... بفرع الغضى إذ راجعتني غياطله)\n(لشاهدت لهوا بعد شحط من النوى ... على سخط الأعداء حلوا شمائله)\n\n(ويوما كإبهام القطاة مزينا ... لعيني ضحاه غالبا لي باطله)\nنى في البيت الثالث وبعده البيت الثاني وروايته\n(تشاهد لهوا بعد شحط من النوى ... )\nخارق ثاني ثقيل بالوسطى عن حبش\nأخبرني الحسن بن علي قال حدثنا عبد الله بن عمرو قال حدثني علي بن الصباح قال قال أبو محضة الأعرابي وأنشد هذه الأبيات ليزيد بن الطثرية فلما بلغ إلى قوله\n(بنفسي من لو مر برد بنانه ... على كبدي كانت شفاء أنامله)\n(ومن هابني في كل أمر وهبته ... فلا هو يعطيني ولا أنا سائله)\nرب لذلك وقال هذا والله من مغنج الكلام","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":3,"spl":"حبه لوحشية ومرضه لغيابها","song":1,"loc":1462,"partial":1},
{"id":"b77-5","bab":"الجزء 8","sec":"وحشية تجيبه شعرا على رسالته","page":"ج8 ص172","text":"ونسخت من كتاب الحسن بن علي حدثنا عبد الله بن عمرو قال حدثني هشام بن محمد بن موسى قال حدثنا عبد الله بن إبراهيم الطائي قال حدثني عبد الله بن روح الغنوي قال حدثتني ظبية بنت وزير الباهلية قالت كتب يزيد بن الطثرية إلى وحشية\n(أحبك أطراف النهار بشاشة ... وبالليل يدعوني الهوى فأجيب)\n(لئن أصبحت ريح المودة بيننا ... شمالا لقدما كنت وهي جنوب)\nأجابته بقولها\n(أحبك حب اليأس إن نفع الحيا ... وإن لم يكن لي من هواك طبيب)\nخبرني يحيى بن علي إجازة عن حماد بن إسحاق عن أبيه قال حدثني هانىء بن سعد أن ابن الطثرية وابن بوزل وهو قطري بن بوزل خرجا يسيران حتى نزلا برملة حائل بين قفار الملح فقال يزيد لابن بوزل إذهب فاسق راحلتك\nواسقنا فلما جاوز أوفى يزيد على أجرع فرأى اشباحا فأتاها فقيل له هذه والله فلانة وأهلها عجيبة بها أي معجبون بها فأتاها فظل عشيته وبات ليلته وأقام الغد حتى راح عشيا وقد لقي ابن بوزل كل شر ومات غيظا فلما دنا منه قال\n(لو انك شاهدت الصبا يابن بوزل ... بجزع الغضى إذ راجعتني غياطله)\n(بأسفل خل الملح إذ دين ذي الهوى ... مؤدى وإذ خير الوصال أوائله)\n(لشاهدت يوما بعد شحط من النوى ... وبعد تنائي الدار حلوا شمائله)\nقد روي\n(وغيم الصبا إذ راجعتني غياطله ... )\nاخترط سيفه ابن بوزل وحاوطه يزيد بعصاه ثم اعتذر إليه وأخبره خبره فقبل منه وقد روى هذه الأبيات أبو عمرو الشيباني وغيره فزاد فيها على إسحاق هذه الأبيات\n(ألا حبذا عيناك يا أم شنبل ... إذا الكحل في جفنيهما جال جائله)\n(فداك من الخلان كل ممزج ... تكون لأدنى من يلاقي وسائله)\n(فرحنا تلقانا به أم شنبل ... ضحيا وأبكتنا عشيا أصائله)\n(وكنت كأني حين كان كلامها ... وداعا وخلى موثق العهد حامله)\n(رهين بنفس لم تفك كبوله ... عن الساق حتى جرد السيف قاتله)\n(فقال دعوني سجدتين وأرعدت ... حذار الردى أحشاؤه ومفاصله)\nال إسحاق وقال أبو عثمان سعيد بن طارق نزلت سارية من بني سدرة على بني قشير بمالهم فجعلت فتيان قشير تترجل وتتزين وتزور بيوت سدرة فاستنهوهم فقال يزيد بن الطثرية وما في هذا عليكم زوروا بيوتنا كما نزور بيوتكم وقال\n(دعوهن يتبعن الصبا وتبادلوا ... بنا ليس بأس بيننا بالتبادل)\nم إن بني سدرة قالوا لنسائهم ويحكن فضحتننا نأتي نساء هؤلاء فلا نقدر عليهن ويأتونكن فلا تحتجبن عنهم فقالت كهلة منهن مروا نساءكم يجتمعن إلى بيتي فإذا جاؤوا لم يجدوا امرأة إلا عندي فإن يزيد أتاني لم يعد في بيوتكم ففعلوا فجاء يزيد فقال\n(سلام عليكن الغداة فما لنا ... إليكن إلا أن تشأن سبيل)\nقالت الكهلة ومن أنت فقال\n(أنا الهائم الصب الذي قاده الهوى ... إليك فأمسى في حبالك مسلما)\n(برته دواعي الحب حتى تركنه ... سقيما ولم يتركن لحما ولا دما)\nقالت اختر إحدى ثلاث خصال إما أن تمضي ثم ترجع علينا فإنا نرقب عيون الرجال فإنهم قد سبونا فيك وإما أن تختار أحبنا إليك وأن تطلب\nامرأة واحدة خير من أن يشهرك الناس ونسي الثالثة فقال سآخذ إحداهن فاختاري أنت إحدى ثلاث خصال قالت وما هن قال إما أن أحملك على مرضوف من أمري فتركيبه وإما أن تحمليني على مشروج من أمرك فأركبه وإما أن تلزي بكري بين قلوصيك قالت لو وقع بكرك بين قلوصي لطمرتا به طمرة يتطامن عنقه منها قال كلا إنه شديد الوجيف عارم الوظيف فغلبها فلما أتاها القوم قالت لهم إنه أتاني رجل لا تمتنع عليه امرأة فإما أن تغمضوا له وإما أن ترحلوا عن مكانكم هذا فرحلوا وذهبوا فقال حكيم بن أبي الخلاف السدري في قصيدة له يذكر أنه إنما ارتحلوا عنهم لأنهم آذوهم بكثرة ما يصنعون بهم\n(فكان الذي تهدون للجار منكم ... بخاتج حبات كثيرا سعالها)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":4,"spl":"وحشية تجيبه شعرا على رسالته","loc":1463,"partial":1},
{"id":"b77-6","bab":"الجزء 8","sec":"خبره مع اسماء الجعفرية","page":"ج8 ص175","text":"قال إسحاق فأخبرني الفزاري أن قوما من بني نمير وقوما من بني جعفر تزاوروا فزار شبان من بني جعفر بيوت بني نمير فقبلوا وحدثوا وزار بنو نمير بني جعفر فلم يقبلوا فاستنجدوا ابن الطثرية فزار معهم بيوت بني جعفر فأنشدهن وحدثهن فأعجبن به واجتمعن إليه من البيوت فتوعد بنو جعفر ابن\nالطثرية فتتاركوا وأمسك بعضهم عن بعض فأرسلت أسماء الجعفرية إلى ابن الطثرية أن لا تقطعني وإن منعت فإني سأتخلص إلى لقائك فأنشأ يقول\n(خليلي بين المنحنى من مخمر ... وبين اللوى من عرفجاء المقابل)\n(قفا بين أعناق اللوى لمرية ... جنوب تداوي غل شوق مماطل)\n(لكيما أرى أسماء أو لتمسني ... رياح برياها لذاذ الشمائل)\n(لقد حادلت أسماء دونك باللوى ... عيون العدا سقيا لها من محادل)\n(ودست رسولا أن حولي عصابة ... هم الحرب فاستبطن سلاح المقاتل)\n(عشية ما لي من نصير بأرضها ... سوى السيف ضمته إلي حمائلي)\n(فيأيها الواشون بالغش بيننا ... فرادى ومثنى من عدو وعاذل)\n(دعوهن يتبعن الهوى وتبادلوا ... بنا ليس بأس بيننا بالتبادل)\n(تروا حين نأتيهن نحن وأنتم ... لمن وعلى من وطأة المتثاقل)\n(ومن عريت للهو قدما ركابه ... وشاعت قوافي شعره في القبائل)\n(تبرز وجوه السابقين ويختلط ... على المقرف الكافي غبار القنابل)\n(فإن تمنعوا أسماء أو يك نفعها ... لكم أو تدبوا بيننا بالغوائل)\n(فلن تمنعوني أن أعلل صحبتي ... على كل شيء من مدى العين قابل)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":5,"spl":"خبره مع اسماء الجعفرية","loc":1464},
{"id":"b77-7","bab":"الجزء 8","sec":"حبس لديون عليه","page":"ج8 ص177","text":"قال إسحاق وحدثني أبو زياد الكلابي أن يزيد بن الطثرية كان شريفا متلافا يغشاه الدين فإذا أخذ به قضاه عنه أخ له يقال له ثور ثم إنه كثر عليه دين لمولى لعقبة بن شريك الحرشي يقال له البربري فحبسه له عقبة بالعقيق من بلاد بني عقيل وعقبة عليها يومئذ أمير وقال المفضل بن سلمة قال أبو عمرو الشيباني كان يزيد قد هرب منه فرجع إليه من حب اسماء وكانت جارة البربري فأخذه البربري ويقال إنه أعطاه بعيرا من إبل ثور أخيه فقال يزيد في السجن\n(قضى غرمائي حب أسماء بعد ما ... تخونني ظلم لهم وفجور)\n(فلو قل دين البربري قضيته ... ولكن دين البربري كثير)\n(وكنت إذا حلت علي ديونهم ... أضم جناحي منهم فأطير)\n(علي لهم في كل شهر أدية ثمانون واف نقدها وجزور ... )\n(نجيء إلى ثور ففيم رحيلنا ... وثور علينا في الحياة صبور)\n(أشد على ثور وثور إذا رأى ... بنا خلة جزل العطاء غفور)\n(فذلك دأبي ما بقيت وما مشى ... لثور على ظهر البلاد بعير)\nيروى فهذا له ما دمت حيا ثم إن عقبة حج على جمل له يقال له ابن الكميت أنجب ما ركب الناس وثبت ابن الطثرية في السجن حتى انصرف عقبة بن شريك من مكة فأرسل ابن الكميت في مخاضة مستقبلة الربيع وهي حاضرة العقيق تأكل الغضى وتشرب بأحسائه وانحدر عقبة نحو اليمامة وعليها المهاجر بن عبد الله الكلابي فلما ضاقت بابن الطثرية المخارج قال له صاحب له لا أعلم لك أنجى إن قدرت على الخروج من\nالسجن إلا أن تركب ابن الكميت فينجيك نحو بلد من البلاد فلم يزل حتى جعل للحداد على أن يرسله ليلة إلى ابن عمه جعلا فشكا إليه وجده بها فأرسله فمضى يزيد نحو الإبل عشاء فاحتكم ابن الكميت حتى جلس عليه فوجهه قصد اليمامة يريد عقبة بن شريك وقال في طريقه\n(لعمري إن ابن الكميت على الوجا ... وسيري خمسا بعد خمس مكمل)\n(لطلق الهوادي بالوجيف إذا ونى ... ذوات البقايا والعتيق الهمرجل)\nورد اليمامة فأناخ بابن الكميت على باب المهاجر فكان أول من خرج عليه عقبة بن شريك فلما نظر إليه عرفه وعرف الجمل فقال ويحك أيزيد أنت قال نعم وهذا ابن الكميت قال نعم قال ويحك فما شأنك قال يا عقبة فار منك إليك وأنشده قصيدته التي يقول فيها\n(يا عقب قد شذب اللحاء عن العصا ... عني وكنت مؤزرا محمودا)\n(صل لي جناحي واتخذني عدة ... ترمي بي المتعاشي الصنديدا)\nقال له عقبة وكانت من خير فعلة علمناه فعلها أشهدكم أني قد أبرأته من دين البربري وأن له ابن الكميت وأمره أن يحتكم فيما سوى ذلك من ماله وهذان البيتان من القصيدة التي أولها\n(أمسى الشباب مودعا محمودا ... )\nهي من جيد شعره يقول فيها\n(ومدلة عند التبذل يفتري ... منها الوشاح مخصرا أملودا)\n(نازعتها غنم الصبا إن الصبا ... قد كان مني للكواعب عيدا)\n(يا للرجال وإنما يشكو الفتى ... مر الحوادث أو يكون جليدا)\n(بكرت نوار تجد باقية القوى ... يوم الفراق وتخلف الموعودا)\n(ولرب أمر هوى يكون ندامة ... وسبيل مكرهة يكون رشيدا)\nم قال يفخر\n(لا أتقي حسك الضغائن بالرقى ... فعل الدليل وإن بقيت وحيدا)\n(لكن أجرد للضغائن مثلها ... حتى تموت وللحقود حقودا)\nخبرني الحسن بن علي قال حدثنا عبد الله بن عمرو بن أبي سعد قال حدثنا علي بن الصباح قال قال أبو محضة الأعرابي وأنشد هذه الأبيات ليزيد بن الطثرية هي والله من مغنج الكلام\n(بنفسي من لو مر برد بنانه ... على كبدي كانت شفاء أنامله)\n(ومن هابني في كل شيء وهبته ... فلا هو يعطيني ولا أنا سائله)\nهذه الأبيات من قصيدته التي قالها في وحشية الجرمية التي مضى ذكرها","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":6,"spl":"حبس لديون عليه — أعداؤه يستولون على راحلته","loc":1465,"partialRef":{"sid":"b76-32","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b77-8","bab":"الجزء 8","sec":"أعداؤه يستولون على راحلته","page":"ج8 ص179","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثتني ظبية قالت مر يزيد بن الطثرية بأعداء له فأرادوه وهو على راحلته فركضها وركضوا الإبل على أثره فخشي أن يدركوه وكانت نفسه عنده أوثق من الراحلة فنزل فسبقهم عدوا وأدركوا الراحلة فعقروها فقال في ذلك\n(ألا هل أتى ليلى على نأي دارها ... بأن لم أقاتل يوم صخر مذودا)\n(وأني أسلمت الركاب فعقرت وقد كنت مقداما بسيفي مفردا ... )\n(أثرت فلم أسطع قتالا ولا ترى ... أخا شيعة يوما كآخر أوحدا)\n(فهل تصرمن الغانيات مودتي ... إذا قيل قد هاب المنون فعردا)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":6,"spl":"حبس لديون عليه — أعداؤه يستولون على راحلته","loc":1466,"partial":1},
{"id":"b77-9","bab":"الجزء 8","sec":"هجوه لفديك الجرمي لأنه عذب وحشية","page":"ج8 ص180","text":"أخبرني يحيى إجازة عن حماد بن إسحاق عن أبيه عن أبي زياد قال كان يزيد بن الطثرية يتحدث إلى نساء فديك بن حنظلة الجرمي ومنزلهما بالفلج فبلغ ذلك فديكا فشق عليه فزجر نساءه عن ذلك فأبين إلا أن يدخل عليهن يزيد فدخل عليهن فديك ذات يوم وقد جمعهن جميعا أخواته وبنات عمه وغيرهن من حرمه ثم قال لهن قد بلغني أن يزيد دخل عليكن وقد نهيتكن عنه وإن لله علي نذرا واجبا واخترط سيفه إن لم أضرب\nأعناقكن به فلما ملأهن رعبا ضرب عنق غلام له مولد يقال له عصام فقتله ثم أنشأ يقول\n(جعلت عصاما عبرة حين رابني ... أناسي من أهلي مراض قلوبها)\nثم إن فديكا رأى يزيد قائما عند باب أهله فظن أنه يواعد بعض نسائه فارتصده على طريقه وأمر بزبية فحفرت على الطريق ثم أوقد فيها نارا لينة ثم اختبأ في مكان ومعه عبدان له وقال لهما تبصرا هل تريان أحدا فلم يلبثا إلا قليلا حتى خرجت بنت أخي فديك وكان يقال لها وحشية تتهادى في برودها لميعاد يزيد فأيقظه العبدان ومضت حتى وقعت على الزبية فاحترق بعضها وأمر بها فأخرجت واحتملها العبدان فانطلقا بها إلى داره فقال فديك\n(شفى النفس من وحشية اليوم أنها ... تهادى وقد كانت سريعا عنيقها)\n(فإلا تدع خبط الموارد في الدجى ... تكن قمنا من غشية لا تفيقها)\n(دواء طبيب كان يعلم أنه ... يداوي المجانين المخلى طريقها)\nبلغ ذلك يزيد فقال\n(ستبرأ من بعد الضمانة رجلها ... وتأتي الذي تهوى مخلى طريقها)\n(علي هدايا البدن إن لم ألاقها ... وإن لم يكن إلا فديك يسوقها)\n(يحصنها مني فديك سفاهة ... وقد ذهبت فيها الكباس وحوقها)\n(تذيقونها شيئا من النار كلما ... رأت من بني كعب غلاما يروقها)\nقال وإنما كانت وضعت رجلها فأحرقتها النار وقال يزيد أيضا\n(يا سخنة العين للجرمي إذ جمعت ... بيني وبين نوار وحشة الدار)\n(خبرتهم عذبوا بالنار جارتهم ... ومن يعذب غير الله بالنار)\nبلغ ذلك فديكا فقال\n(أحالفة عليك بنو قشير ... يمين الصبر أم متحرجونا)\nيروى يمين الله\n(فإن تنكل قشير تقض جرم ... وتقض لها مع الشبه اليقينا)\n(أليس الجور أن أباك منا ... وانك في قبيلة آخرينا)\n(لعمر الله إن بني قشير ... لجرم في يزيد لظالمونا)\nفإلا يحلفوا فعليك شكل ... ونجر ليس مما يعرفونا وأعرف فيك سيما آل صقر ... ومشيتهم إذا يتخيلونا\nال وكانت جرم تدعيه وقشير تدعيه فأراد أن يخبر أنه دعي وقال فديك بن حنظلة يهجوه\n(وإنا لسيارون بالسنة التي ... أحلت وفينا جفوة حين نظلم)\n(ومنا الذي لاقته أمك خاليا ... فلم تدر ما أي الشهور المحرم)\nقال يزيد يهجو فديكا\n(أنعت عيرا من عيور القهر ... أقمر من شر حمير قمر)\n(صبح أبيات فديك يجري ... منزلة اللؤم ودار الغدر)\n(فلقيته عند باب العقر ... ينشطها والدرع عند الصدر)\n(نشطك بالدلو قراح الجفر ... )\nخبرنا يحيى بن علي إجازة عن حماد بن إسحاق عن أبيه قال حدثنا أبو الحارث هانىء بن سعد الخفاجي قال ذكرت ليزيد بن الطثرية امرأة حدثة جميلة فخرج حتى يدفع إليها فوجد عندها رجلين قاعدين يتحدثان فسلم عليهم فأوجست أنه يزيد ولم تتثبت ورأت عليه مسحة فقالت أي ريح جاءت بك يا رجل قال الجنوب قالت فأي طير جرت لك الغداة قال عنز زنمة رأيتها يداورها ثعلبان فانقض عليها سرحان فراغ الثعلبان قال فطفرت وراء سترها وعرفت أنه يزيد قال إسحاق وحدثني عطرد قال قال قطري بن بوزل ليزيد بن الطثرية انطلق معي إلى فلانة وفلانة فإنهن يبرزن لك ويستترن عني عسى أن أراهن اليوم على وجهك فذهب به معه فخرج عليهما النسوة وظلا يتحدثان عندهن حتى تروحا وقال يزيد في ذلك\n(على قطري نعمة إن جرى بها ... يزيد وإلا يجزه الله لي أجرا)\n(دنوت به حتى رمى الوحش بعدما ... رأى قطري من أوائلها نفرا)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":7,"spl":"هجوه لفديك الجرمي لأنه عذب وحشية","loc":1467,"partial":1},
{"id":"b77-10","bab":"الجزء 8","sec":"خبره مع رجل من صداء أحب خثعمية فأعانه يزيد عليها","page":"ج8 ص184","text":"أخبرنا يحيى إجازة عن حماد بن إسحاق عن أبيه عن عطرد قال\nنزل نفر من صداء بناحية العقيق وهو منزل ابن الطثرية نصف النهار فلم يأتهم أحد فأبصرهم ابن الطثرية فمر عليهم وهو منصرف وليسوا قريبا من أهله فلما رآهم مرملين أنفذ إليهم هدية ومضى على حياله ولم يراجعهم فسألوا عنه بعد حتى عرفوه فحلا عندهم وأعجبهم ثم إن فتى منهم واده فآخاه فأهدى له بردا وجبة ونعلين ثم أغار المقدم بن عمرو بن همام بن مطرف بن الأعلم بن ربيعة بن عقيل على ناس من خثعم وفي ذلك يقول الشاعر\n(مغار ابن همام على حي خثعما ... )\nأخذ منهم إبلا ورقيقا وكانت فيهن جارية من حسان الوجوه وكان يهواها الذي آخى يزيد فأصابه عليها بلاء عظيم حتى نحل جسمه وتغيرت حاله فأقبل الفتى حتى نزل العقيق متنكرا فشكا إلى يزيد ما أصابه في تلك الجارية فقال أفيك خير قال نعم قال فإني أدفعها إليك فخبأه في عريش له اياما حتى خطف الجارية فدفعها إليه فبعث إليها قطري بن بوزل فاعترض لها بين أهلها وبين السوق فذهب بها حتى دفعها إليه وقد وطن له ناقة مفاجة فقال النجاة فإنك لن تصبح حتى تخرج من بلاد قشير وتصير إلى دار\nنهد فقد نجوت وأنا أخفي أثرك فعفى أثره وقال لابنة خمارة كان يشرب عندها إسحبي ذيلك على أثره ففعلت ثم بحث على ذلك حتى قيل قد كان قطري أحدث الناس بها عهدا فاستعدي عليه فظفر بيزيد فأخذ مكانه فحبس بحجر حبسه المهاجر ففي ذلك يقول يزيد\n(ألا لا أبالي إن نجا لي ابن بوزل ... ثوائي وتقييدي بحجر لياليا)\n(إذا حم أمر فهو لا بد واقع ... له لا أبالي ما علي ولا ليا)\n(هو العسل الماذي طورا وتارة ... هو السم والذيفان والليث عاديا)\nخبرني أبو خليفة الفضل بن الحباب عن محمد بن سلام الجمحي قال حدثني أبو الغراف قال كان يزيد بن الطثرية صاحب غزل ومحادثة للنساء وكان ظريفا جميلا من أحسن الناس كلهم شعرا وكان أخوه ثور سيدا كثير المال والنخل والرقيق وكان متنسكا كثير الحج والصدقة كثير الملازمة لإبله ونخله فلا يكاد يلم بالحي إلا الفلتة والوقعة وكانت إبله ترد مع الرعاء على أخيه يزيد بن الطثرية فتسقى على عينه فبينا يزيد مار في الإبل وقد صدر عن الماء إذ مر بخباء فيه نسوة من الحاضر فلما رأينه قلن يا يزيد أطعمنا لحما فقال أعطينني سكينا فأعطينه ونحر لهن ناقة من إبل أخيه وبلغ الخبر أخاه فلما جاءه أخذ بشعره وفسقه وشتمه فأنشأ يزيد يقول\n(يا ثور لا تشتمن عرضي فداك أبي ... فإنما الشتم للقوم العواوير)\n(ما عقر ناب لأمثال الدمى خرد ... عين كرام وأبكار معاصير)\n(عطفن حولي يسألن القرى أصلا ... وليس يرضين مني بالمعاذير)\n(هبهن ضيفا عراكم بعد هجعتكم ... في قطقط من سقيط الليل منثور)\n(وليس قربكم شاء ولا لبن ... أيرجل الضيف عنكم غير مجبور)\n(ما خير واردة للماء صادرة ... لا تنجلي عن عقير الرجل منحور)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":8,"spl":"خبره مع رجل من صداء أحب خثعمية فأعانه يزيد عليها","loc":1468,"partial":1},
{"id":"b77-11","bab":"الجزء 8","sec":"شعره في امرأة أحبها سبعة رجال","page":"ج8 ص186","text":"أخبرني أبو خليفة قال قال ابن سلام كان يزيد بن الطثرية يتحدث إلى امرأة ويعجب بها فبينما هو عندها إذ حدث لها شاب سواه قد طلع عليه ثم جاء آخر ثم آخر فلم يزالوا كذلك حتى تموا سبعة وهو الثامن فقال\n(أرى سبعة يسعون للوصل كلهم ... له عند ليلى دينة يستدينها)\n(فألقيت سهمي وسطهم حين أوخشوا ... فما صار لي من ذاك إلا ثمينها)\n(وكنت عزوف النفس أشنأ أن أرى ... على الشرك من ورهاء طوع قرينها)\n(فيوما تراها بالعهود وفية ... ويوما على دين ابن خاقان دينها)\n(يدا بيد من جاء بالعين منهم ... ومن لم يجىء بالعين حيزت رهونها)\nقال فيها وقد صارمها\n(ألا بأبي من قد برى الجسم حبه ... ومن هو مرموق إلي حبيب)\n(ومن هو لا يزداد إلا تشوقا ... وليس يرى إلا عليه رقيب)\n(وإني وإن أحموا علي كلامها ... وحالت أعاد دونها وحروب)\n(لمثن على ليلى ثناء يزيدها ... قواف بأفواه الرواة تطيب)\n(أليلى احذري نقض القوى لا يزل لنا ... على النأي والهجران منك نصيب)\n(وكوني على الواشين لداء شغبة ... كما أنا للواشي ألد شغوب)\n(فإن خفت ألا تحكمي مدة القوى ... فردي فؤادي والمزار قريب)\nخبرنا محمد بن الحسن بن دريد قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه عن رجل من بني عامر ثم من بني خفاجة قال استعذب جرم على ابن الطثرية في وحشية أمرأة منهم كان يشبب بها فكتب بها صاحب اليمامة إلى ثور أخي يزيد بن الطثرية وأمره بأدبه فجعل عقوبته حلق لمته فحلقها فقال يزيد\n(أقول لثور وهو يحلق لمتي ... بحجناء مردود عليها نصابها)\nال عبد الرحمن كان عمي يحتج في تأنيث الموسى بهذا البيت\n(ترفق بها يا ثور ليس ثوابها ... بهذا ولكن غير هذا ثوابها)\n(ألا ربما يا ثور قد غل وسطها ... أنامل رخصات حديث خضابها)\n(وتسلك مدرى العاج في مدلهمة ... إذا لم تفرج مات غما صؤابها)\n(فراح بها ثور ترف كأنها ... سلاسل درع خيرهاوانسكابها)\n(منعمة كالشرية الفرد جادها ... نجاء الثريا هطلها وذهابها)\n(فأصبح رأسي كالصخيرة أشرفت ... عليها عقاب ثم طارت عقابها)\nنظير هذا الخبر أخبار من حلقت جمته فرثاها وليس من هذا الباب ولكن يذكر الشيء بمثله أخبرني محمد بن الحسن بن دريد قال أخبرني عبد الرحمن عن عمه قال شرب طخيم الأسدي بالحيرة فأخذه العباس بن معبد المري وكان على شرط يوسف بن عمر فحلق رأسه فقال\n(وبالحيرة البيضاء شيخ مسلط ... إذا حلف الأيمان بالله برت)\n(لقد حلقوا منا غدافا كأنها ... عناقيد كرم أينعت فاسبطرت)\n(يظل العذارى حين تحلق لمتي ... على عجل يلقطنها حين جزت)\nخبرني محمد عن عبد الرحمن عن عمه عن بعض بني كلاب قال أخذ فتى منا مع بعض فتيات الحي فحلق رأسه فقال\n(يا لمتي ولقد خلقت جميلة ... وكرمت حين أصابك الجلمان)\n(أمست تروق الناظرين وأصبحت ... قصصا تكون فواصل المرجان)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":9,"spl":"شعره في امرأة أحبها سبعة رجال — شعره في أخيه ثور","loc":1469},
{"id":"b77-12","bab":"الجزء 8","sec":"شعره في أخيه ثور","page":"ج8 ص188","text":"أخبرني وكيع قال حدثني علي بن الحسين بن عبد الأعلى قال حدثنا أبو محلم قال كان ليزيد بن الطثرية أخ يقال له ثور أكبر منه فكان يزيد يغير على ماله ويتلفه فيتحمله ثور لمحبته إياه فقال يزيد في ذلك\n(نغير على ثور وثور يسرنا ... وثور علينا في الحياة صبور)\n(وذلك دأبي ما حييت وما مشى ... لثور على عفر التراب بعير)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":9,"spl":"شعره في امرأة أحبها سبعة رجال — شعره في أخيه ثور","loc":1470},
{"id":"b77-13","bab":"الجزء 8","sec":"مقتله ورثاء الشعراء له","page":"ج8 ص189","text":"وقتل يزيد بن الطثرية في خلافة بني العباس قتلته بنو حنيفة أخبرني علي بن سليمان الأخفش قال أخبرنا أبو سعيد السكري عن محمد بن حبيب عن ابن الأعرابي عن المفضل بن سلمة عن أبي عبيدة وابن الكلبي وأخبرنا يحيى بن علي عن حماد بن إسحاق عن أبيه عن أبي الجراح العقيلي قال\nأغارت بنو حنيفة على طائفة من بني عقيل ومعهم رجل من بني قشير جار لهم فقتل القشيري ورجل من بني عقيل واطردت إبل من العقيليين فأتى الصريخ عقيلا فلحقوا القوم فقاتلوهم فقتلوا من بني حنيفة رجلا وعقروا أفراسا ثلاثة من خيل حنيفة وانصرفوا فلبثوا سنة ثم إن عقيلا انحدرت منتجعة من بلادها إلى بلاد بني تميم فذكر لحنيفة وهم بالكوكبة والقيضاف فغزتهم حنيفة وحذر العقيليون وأتتهم النذر من نمير فانكشفوا فلم يقدروا عليهم فبلغ ذلك من بني عقيل وتلهفوا على بني حنيفة فجمعوا جمعا ليغزوا حنيفة ثم تشاوروا فقال بعضهم لا تغزوا قوما في منازلهم ودورهم فيتحصنوا دونكم ويمتنعوا منكم ولا نأمن أن يفضحوكم فأقاموا بالعقيق وجاءت حنيفة غازية كعبا لا تتعداها حتى وقعت بالفلج فتطاير الناس ورأس حنيفة يومئذ المندلف وجاء صريخ كعب إلى أبي لطيفة بن مسلم العقيلي وهو بالعقيق أمير عليها فضاق بالرسول ذرعا وأتاه هول شديد فأرسل في عقيل يستمدها فأتته ربيعة بن عقيل وقشير بن كعب والحريش بن كعب وأفناء خفاجة وجاش إليه الناس فقال إني قد أرسلت طليعة فانتظروها حتى تجيء ونعلم ما تشير به قال أبو الجراح فأصبح صبح ثالثة على فرس له يهتف أعز الله نصركم وأمتعنا بكم انصرفوا راشدين فلم يكن بأس فانصرف الناس وصار في بني عمه ورهطه دنية وإنما فعل ذلك لتكون له السمعة والذكر فكان فيمن سار معه القحيف بن خمير ويزيد بن الطثرية الشاعران فساروا حتى واجهوا القوم فواقعوهم فقتلوا المندلف رموه في عينه وسبوا وأسروا ومثلوا بهم وقطعوا أيدي اثنين منهم وأرسلوهما إلى اليمامة وصنعوا ما أرادوا ولم يقتل ممن كان\nمع أبي لطيفة غير يزيد بن الطثرية نشبب ثوبه في جذل من عشرة فانقلب وخبطه القوم فقتل فقال القحيف يرثيه\n(ألا تبكي سراة بني قشير ... على صنديدها وعلى فتاها)\n(فإن يقتل يزيد فقد قتلنا ... سراتهم الكهول على لحاها)\n(أبا المكشوح بعدك من يحامي ... ومن يزجي المطي على وجاها)\nقال القحيف أيضا يرثيه\n(إن تقتلوا منا شهيدا صابرا ... فقد تركنا منكم مجازرا)\n(عشرين لما يدخلوا المقابرا ... قتلى أصيبت قعصا نحائرا)\n(نعجا ترى أرجلها شواغرا ... )\nهذه من رواية ابن حبيب وحده وقال القحيف أيضا ولم يروها إلا ابن حبيب\n(يا عين بكي هملا على همل ... على يزيد ويزيد بن حمل)\n(قتال أبطال وجرار حلل ... )\nال ويزيد بن حمل قشيري قتل يومئذ أيضا وقالت زينب بنت الطثرية ترثي أخاها يزيد وعن أبي عمرو الشيباني أن الأبيات لأم يزيد قال وهي من الأزد ويقال إنها لوحشية الجرمية\n(أرى الأثل من بطن العقيق مجاوري ... مقيما وقد غالت يزيد غوائله)\n(فتى قد قد السيف لا متضائل ... ولا رهل لباته وبآدله)\n(فتى لا ترى قد القميص بخصره ... ولكنما توهي القميص كواهله)\n(إذا نزل الضيفان كان عذورا ... على الحي حتى تستقل مراجله)\n(يسرك مظلوما ويرضيك ظالما ... وكل الذي حملته فهو حامله)\n(إذا جد عند الجد أرضاك جده ... وذو باطل إن شئت ألهاك باطله)\n(مضى وورثناه دريس مفاضة ... وأبيض هنديا طويلا حمائله)\n(وقد كان يحمي المحجرين بسيفه ... ويبلغ أقصى حجرة الحي نائله)\n(فتى ليس لابن العم كالذئب إن رأى ... بصاحبه يوما دما فهو آكله)\n(سيبكيه مولاه إذا ما ترفعت ... عن الساق عند الروع يوما ذلاذله)\nلذلذل هدب الثياب وقد أخبرنا الحرمي عن الزبير عن عمر بن إبراهيم السعدي عن عباس بن عبد الصمد قال قال هشام بن عبد الملك للعجير السلولي اصدقت فيما قلت في ابن\nعمك قال نعم يا أمير المؤمنين ألا إني قلت\n(فتى قد قد السيف لا متضائل ... ولا رهل لباته وأباجله)\nفذكر هذا البيت وحده ونسبه إلى العجير السلولي من الأبيات المنسوبة إلى أخت يزيد بن الطثرية أو إلى أمه وأتى بأبيات أخر ليست منها وسيذكر ذلك في أخبار العجير مشروحا إن شاء الله تعالى\n(ومما يغنى فيه من شعر يزيد بن الطثرية قوله ... )\n(صوت ... )\n(بنفسي من لا بد اني هاجره ... ومن أنا في الميسور والعسر ذاكره)","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":10,"spl":"مقتله ورثاء الشعراء له","loc":1471,"partialRef":{"sid":"b76-5","gi":6,"vi":5,"side":0},"partial":1},
{"id":"b77-14","bab":"الجزء 8","sec":"مقتله ورثاء الشعراء له","page":"ج8 ص189","text":"(ومن قد رماه الناس بي فاتقاهم ... ببغضي إلا ما تجن ضمائره)\nروضه من الطويل غنى في هذين البيتين عبد الله بن العباس الربيعي لحنا من خفيف الثقيل بالبنصر وغنت فيه عريب وفي أبيات أضافتها إليها لحنا من خفيف الثقيل الأول آخر وغنت علية بنت المهدي فيها خفيف رمل وذكر الهشامي أن لإبراهيم فيها لحنا ماخوريا والأبيات المضافة\n(بنفسي من لا أخبر الناس باسمه ... وإن حملت حقدا علي عشائره)\n(بأهلي ومالي من جلبت له الأذى ... ومن ذكره مني قريب أسامره)\n(ومن لو جرت شحناء بيني وبينه ... وحاورني لم أدر كيف أحاوره)\n","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":11,"spl":"مقتله ورثاء الشعراء له — من المائة المختارة","song":1,"loc":1472},
{"id":"b77-15","bab":"الجزء 8","sec":"من المائة المختارة","page":"ج8 ص194","text":"(شأتك المنازل بالأبرق ... دوارس كالعين في المهرق)\n(لآل جميلة قد أخلقت ... ومهما يطل عهده يخلق)\n(فإن يقل الناس لي عاشق ... فأين الذي هو لم يعشق)\n(ولم يبك نؤيا على عبرة ... بداء الصبابة والمعلق)\nأتك بعدت عنك والشأو البعد يقال جرى الفرس شأوا يريد طلقا والمهرق الصحيفة والجمع المهارق يريد أن الدار قد بقيت منها طرائق كالصحف وما فيها الشعر للأحوص والغناء لجميلة ولحنها المختار خفيف رمل بالوسطى عن إسحاق وفيه لعطرد ثقيل أول بالخنصر في مجرى الوسطى وفيه لمعبد خفيف ثقيل عن حبش وفيه رمل يقال إنه لفريدة ويقال إنه لمالك وقيل إن الثقيل الأول لابن عائشة وذكر عمرو بن بانة أن خفيف الرمل لعطرد أيضا\nحذف","topic":"ذكر يزيد بن الطثرية وأخباره ونسبه","topicNo":77,"sp":11,"spl":"مقتله ورثاء الشعراء له — من المائة المختارة","loc":1473}]);
window.__BOOK__['p04'].push([{"id":"b78-1","bab":"الجزء 8","sec":"ذكر جميلة وأخبارها","page":"ج8 ص195","text":"هي جميلة مولاة بني سليم ثم مولاة بطن منهم يقال لهم بنو بهز وكان لها زوج من موالي بني الحارث بن الخزرج وكانت تنزل فيهم فغلب عليها ولاء زوجها فقيل إنها مولاة للأنصار تنزل بالسنح وهو الموضع الذي كان ينزله أبو بكر الصديق ذكر ذلك إبراهيم بن زياد الأنصاري الأموي السعيدي وذكر عبد العزيز بن عمران أنها مولاة للحجاج بن علاط السلمي وهي أصل من أصول الغناء وعنها أخذ معبد وابن عائشة وحبابة وسلامة وعقيلة العقيقية والشماسيتان خليدة وربيحة وفيها يقول عبد الرحمن بن أرطأة\n(إن الدلال وحسن الغناء ... وسط بيوت بني الخزرج)\n(وتلكم جميلة زين النساء ... إذا هي تزدان للمخرج)\n(إذا جئتها بذلت ودها ... بوجه منير لها أبلج)\nلشعر لعبد الرحمن بن أرطأة والغناء لمالك خفيف ثقيل أول مطلق في مجرى الوسطى ويقال فيه للدلال وجميلة لحنان","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":0,"spl":"ذكر جميلة وأخبارها — جميلة هي أصل الغناء — أنى لها هذا الغناء","song":1,"loc":1474},
{"id":"b78-3","bab":"الجزء 8","sec":"جميلة هي أصل الغناء — أنى لها هذا الغناء","page":"ج8 ص195 – ج8 ص196","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي جعفر القرشي عن المحرزي قال كانت جميلة أعلم خلق الله بالغناء وكان معبد يقول أصل الغناء جميلة وفرعه نحن ولولا جميلة لم نكن نحن مغنين\nقال إسحاق وحدثني ايوب بن عباية قال حدثني رجل من الأنصار قال سئلت جميلة أنى لك هذا الغناء قالت والله ما هو إلهام ولا تعليم ولكن ابا جعفر سائب خاثر كان لنا جارا وكنت أسمعه يغني ويضرب بالعود فلا أفهمه فأخذت تلك النغمات فبنيت عليها غنائي فجاءت أجود من تأليف ذلك الغناء فعلمت وألقيت فسمعني موالياتي يوما وأنا أغني سرا ففهمنني ودخلن علي وقلن قد علمنا فما تكتمينا فأقسمن علي فرفعت صوتي وغنيتهن بشعر زهير بن ابي سلمى\n(وما ذكرتك إلا هجت لي طربا ... إن المحب ببعض الأمر معذور)\n(ليس المحب بمن إن شط غيره ... هجر الحبيب وفي الهجران تغير)\n\n(نام الخلي فنوم العين تعذير ... مما ادكرت وهم النفس مذكور)\n(ذكرت سلمى وما ذكري براجعها ... ودونها سبسب يهوي به المور)\nلشعر لزهير والغناء في هذين البيتين لجميلة فقط رمل بالوسطى عن حبش فحينئذ ظهر أمري وشاع ذكري فقصدني الناس وجلست للتعليم فكان الجواري يتكاوسنني فربما انصرف أكثرهن ولم يأخذن شيئا سوى ما يمنعنني أطارح لغيرهن ولقد كسبت لموالي ما لم يخطر لهن ببال وأهل ذلك كانوا وكنت وحدثني أبو خليفة قال حدثني ابن سلام قال حدثني مسلمة بن محمد بن مسلمة الثقفي قال كانت جميلة ممن لا يشك في فضيلتها في الغناء ولم يدع أحد مقاربتها في ذلك وكل مدني ومكي يشهد لها بالفضل","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":0,"spl":"ذكر جميلة وأخبارها — جميلة هي أصل الغناء — أنى لها هذا الغناء","song":1,"loc":1475},
{"id":"b78-4","bab":"الجزء 8","sec":"وصف مجلس من مجالسها غنت فيه وغنى فيه كبار مغنى مكة والمدينة","page":"ج8 ص197","text":"قال إسحاق وحدثني هشام بن المرية المدني قال حدثني جرير المدني قال إسحاق وكانا جميعا مغنيين حاذقين شيخين جليلين عالمين ظريفين وكانا قد أسنا فأما هشام فبلغ الثمانين وأما جرير فلا أدري قال جرير\nوفد ابن سريج والغريض وسعيد بن مسجح ومسلم بن محرز المدينة لبعض من وفدوا عليه فأجمع رأيهم على النزول على جميلة مولاة بهز فنزلوا عليها فخرجوا يوما إلى العقيق متنزهين فوردوا على معبد وابن عائشة فجلسوا إليهما فتحدثوا ساعة ثم سأل معبد ابن سريج وأصحابه أن يعرضوا عليهم بعض ما ألفوا فقال ابن عائشة إن للقوم أعمالا كثيرة حسنة ولك أيضا يا ابا عباد ولكن قد اجتمع علماء مكة وأنا وأنت من اهل المدينة فليعمل كل واحد منا صوتا ساعته ثم يغن به قال معبد يابن عائشة قد أعجبتك نفسك حتى بلغتك هذه المرتبة قال ابن عائشة أوغضبت يا ابا عباد إني لم اقل هذا وأنا أريد أن أتنقصك فإنك لأنت المفاد منه قال معبد أما إذ قد اختلفنا واصحابنا المكيون سكوت فلنجعل بيننا حكما قال ابن عائشة إن أصحابنا شركاء في الحكومة قال ابن سريج على شريطة قال على أن يكون ما نغني به من الشعر ما حكمت فيه امرأة قال ابن عائشة ومعبد رضينا وهي أم جندب فأجمع رأيهم على الاجتماع في منزل جميلة من غد فلما حضروا قال ابن عائشة ما ترى يا ابا عباد قال أرى أن يبتدىء أصحابنا أو أحدهم قال ابن سريج بل أنتما أولى قالا لم نكن لنفعل فأقبل ابن سريج على سعيد بن مسجح فسأله أن يبتدىء فأبى فأجمع رأي المكيين على أن يبتدىء ابن سريج فغنى ابن سريج\n\n(ذهبت من الهجران في غير مذهب ... ولم يك حقا كل هذا التجنب)\n(خليلي مرا بي على أم جندب ... أقض لبانات الفؤاد المعذب)\n(فإنكما إن تنظراني ساعة ... من الدهر تنفعني لدى أم جندب)\n(ألم ترياني كلما جئت طارقا ... وجدت بها طيبا وإن لم تطيب)\nلشعر لامرىء القيس ولابن سريج فيه لحنان ثاني ثقيل بالسبابة في مجرى الوسطى وخفيف رمل بالسبابة في مجرى الوسطى جميعا عن إسحاق وغنى معبد\n(فلله عينا من رأى من تفرق ... أشت وأنأى من فراق المحصب)\n(علون بأنطاكية فوق عقمة ... كجرمة نخل أو كجنة يثرب)\n(فريقان منهم سالك بطن نخلة ... وآخرمنهم جازع نجد كبكب)\n(فعيناك غربا جدول في مفاضة ... كمر خليج في سنيح مثقب)\nوغنى ابن مسجح\n(وقالت فإن يبخل عليك ويعتلل ... يسؤك وإن يكشف غرامك تدرب)\n(وإنك لم يفخر عليك كفاخر ... ضعيف ولم يغلبك مثل مغلب)\n(وإنك لم تقطع لبانة عاشق ... بمثل بكور أو رواح مؤوب)\n(بأدماء حرجوج كأن قتودها ... على أبلق الكشحين ليس بمغرب)\n(يغرد بالأسحار في كل سدفة ... تغرد مياح الندامى المطرب)\nغنى ابن عائشة\n(وقد أغتدي والطير في وكناتها ... وماء الندى يجري على كل مذنب)\n(بمنجرد قيد الأوابد لاحه ... طراد الهوادي كل شأو مغرب)\n(إذا ما جرى شأوين وابتل عطفه ... تقول هزيز الريح مرت بأثأب)\n(له أيطلا ظبي وساقا نعامة ... وصهوة عير قائم فوق مرقب)\nغنى أبن محرز\n(فللسوط ألهوب وللساق درة ... وللزجر منه وقع أخرج مهذب)\n(فأدرك لم يجهد ولم يبل شده ... يمر كخذروف الوليد المثقب)\n(تذب به طورا وطورا تمره ... كذب البشير بالرداء المهدب)\n(إذا ما ضربت الدف أو صلت صولة ... ترقب مني غير أدنى ترقب)\nوغنى الفريض\n(أخا ثقة لا يلعن الحي شخصه ... صبورا على العلات غير مسبب)\n(رأينا شياها يرتعين خميلة ... كمشي العذارى في الملاء المجوب)\n(وما أنت أم ما ذكرها ربعية ... تحل بإير أو بأكناف شربب)\n(أطعت الوشاة والمشاة بصرمها ... فقد أنهجت حبالها للتقضب)\nقالت جميلة كلكم محسن وكلكم مجيد في معناه ومذهبه قال ابن عائشة ليس هذا بمقنع دون التفضيل فقالت أما أنت يا أبا يحيى فتضحك الثكلى بحسن صوتك ومشاكلته للنفوس وأما أنت يا أبا عباد فنسيج وحدك بجودة تأليفك وحسن نظمك مع عذوبة غنائك وأما أنت يا أبا عثمان فلك أولية هذا الأمر وفضيلته وأما أنت يا أبا جعفر فمع الخلفاء تصلح وأما أنت يا أبا الخطاب فلو قدمت أحدا على نفسي لقدمتك وأما انت يا مولى العبلات فلو ابتدأت لقدمتك عليهم ثم سألوها جميعا أن تغنيهم لحنا كما غنوا فغنتهم بيتا لامرىء القيس وأربعة أبيات لعلقمة وهي\n(خليلي مرا بي على أم جندب ... أقض لبانات الفؤاد المعذب)","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":1,"spl":"وصف مجلس من مجالسها غنت فيه وغنى فيه كبار مغنى مكة والمدينة","song":6,"loc":1476},
{"id":"b78-5","bab":"الجزء 8","sec":"وصف مجلس من مجالسها غنت فيه وغنى فيه كبار مغنى مكة والمدينة","page":"ج8 ص197","text":"(ليالي لا تبلى نصيحة بيننا ... ليالي حلوا بالستار فغرب)\n(مبتلة كأن أنضاء حليها ... على شادن من صاحة متربب)\n(محال كأجواز الجراد ولؤلؤ ... من القلقي والكبيس الملوب)\n(إذا ألحم الواشون للشر بيننا ... تبلغ رس الحب غير المكذب)\nكلهم أقروا لها وفضلوها فقالت لهم ألا أحدثكم بحديث يتم به حسن غنائكم وتمام اختياركم قالوا بلى والله قال الغريض قد والله فهمته يا سيدتي قالت لعنك الله يا مخنث ما أجود فهمك وأحسن وجهك وما يلام فيك أبو يحيى إذ عرفته فهاته حدثنا قال يا سيدتي وسيدة من حضر والله لا نطقت بحرف منه وأنت حاضرة ولك الفضل والعتبى قالت نازع أمرؤ القيس علقمة بن عبدة الفحل الشعر فقال له قد حكمت بيني وبينك أمرأتك أم جندب قال قد رضيت فقالت لهما قولا شعرا على روي واحد وقافية واحدة صفا فيه الخيل فقال أمرؤ القيس\n(خليلي مرا بي على أم جندب ... أقض لبانات الفؤاد المعذب)\nوقال علقمة\n(ذهبت من الهجران في غير مذهب ... ولم يك حقا كل هذا التجنب)\nأنشداها فغلبت علقمة فقال لها زوجها بأي شيء غلبته قالت لأنك قلت\n(فللسوط ألهوب وللساق درة ... وللزجر منه وقع أهوج منعب)\nجهدت فرسك بسوطك ومريته بساقك وزجرك وأتعبته بجهدك وقال علقمة\n(فولى على آثارهن بحاصب ... وغبية شؤبوب من الشد ملهب)\n(فأدركهن ثانيا من عنانه ... يمر كمر الرائح المتحلب)\nفلم يضرب فرسه بسوط ولم يمره بساق ولم يتعبه بزجر فقال ابن عائشة جعلت فداك أتأذنين أن أحدث قالت هيه قال إنما تزوج أم جندب حين هرب من المنذر بن ماء السماء فأتى جبلي طيىء وكان مفركا فبينا هو معها ذات ليلة إذ قالت له قم يا خير الفتيان فقد أصبحت فلم يقم فكررت عليه فقام فوجد الفجر لم يطلع فرجع فقال لها ما حملك على ما صنعت فأمسكت وألح عليها فقالت حملني أنك ثقيل الصدر خفيف العجيزة سريع الإراقة بطيء الإفاقة فعرف تصديق قولها وسكت فلما\nأصبح أتى علقمة وهو في خيمته وخلفه أم جندب فتذاكروا الشعر فقال امرؤ القيس أنا أشعر منك وقال علقمة مثل ذلك فتحاكما إلى أم جندب ففضلت أم جندب علقمة على امرىء القيس فقال لها بم فضلته علي قالت فرس ابن عبدة أجود من فرسك زجرت وضربت وحركت ساقيك وابن عبدة جامد لا مقتدر فغضب من قولها وطلقها وخلف عليها علقمة فقالت جميلة ما أحسن مجلسنا لو دام اجتماعنا ثم دعت بالغداء فأتي بألوان الأطعمة وأنواع من الفاكهة ثم قالت لولا شناعة مجلسنا لكان الشراب معدا ولكن الليل بيننا فلم يزالوا يومهم ذلك بأطيب مجلس وأحسن حديث فلما جنهم الليل دعت بالشراب ودعت لكل رجل منهم بعود وأخذت هي عودا فضربت ثم قالت اضربوا فضربوا عليها بضرب واحد وغنت بشعر امرىء القيس\n(أأذكرت نفسك ما لن يعودا ... فهاج التذكر قلبا عميدا)\n(تذكرت هندا وأترابها ... وأيام كنت لها مستقيدا)\n(ويعجبك اللهو والمسمعات ... فأصبحت أزمعت منها صدودا)\n(ونادمت قيصر في ملكه ... فأوجهني وركبت البريدا)\nما سمع السامعون بشيء أحسن من ذلك ثم قالت تغنوا جميعا بلحن واحد فغنوها هذا الشعر والصوت بعينه كما غنته وعلم القوم ما أرادت بهذا الشعر فقال ابن عائشة جعلت فداك نرجو أن يدوم مجلسنا ويؤثر أصحابنا المقام بالمدينة فنواسيهم من كل ما نملكه قال أبو عباد وكيف بذاك فباتوا\nبأنعم ليلة وأحسنها قال إسحاق قال أبي قال لي يونس قال أبو عباد لا أعرف يوما واحدا منذ علقت ولا ليلة عند خليفة ولا غيره مثل ذلك اليوم ولا أحسبه يكون بعد قال يونس ولا أدركنا نحن مثل ذلك اليوم ولا بلغنا قال إسحاق ولا أنا ولا أحسب ذلك اليوم يكون بعد","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":2,"spl":"وصف مجلس من مجالسها غنت فيه وغنى فيه كبار مغنى مكة والمدينة","loc":1477},
{"id":"b78-6","bab":"الجزء 8","sec":"عبد الله بن جعفر يزورها في منزلها لأنها آلت على نفسها أن لا تغني خارجه","page":"ج8 ص206","text":"وحدثني أبي قال حدثنا يونس قال قال لي أبو عباد أتيت جميلة يوما وكان لي موعد ظننت أني سبقت الناس إليها فإذا مجلسها غاص فسألتها أن تعلمني شيئا فقالت لي إن غيرك قد سبقك ولا يجمل تقديمك على من سواك فقلت جعلت فداك إلى متى تفرغين ممن سبقني قالت هو ذاك الحق يسعك ويسعهم فينا نحن كذلك إذ أقبل عبد الله بن جعفر وإنه لأول يوم رأيته وآخره وكنت صغيرا كيسا وكانت جميلة شديدة الفرح فقامت وقام الناس فتلقته وقبلت رجليه ويديه وجلس في صدر المجلس على كوم لها وتحوق أصحابه حوله وأشارت إلى من عندها بالانصراف وتفرق الناس وغمزتني أن لا أبرح فأقمت وقالت يا سيدي وسيد آبائي وموالي كيف نشطت إلى أن تنقل قدميك إلى أمتك قال يا جميلة قد علمت ما آليت على نفسك ألا تغني أحدا إلا في منزلك وأحببت الاستماع وكان ذلك طريقا مادا فسيحا قالت جعلت فداك فأنا أصير إليك وأكفر قال لا أكلفك ذلك وبلغني أنك تغنين بيتين لامرىء القيس تجيدين الغناء فيهما وكان الله أنقذ بهما جماعة من المسلمين من الموت قالت يا سيدي نعم فاندفعت تغني فغنت بعودها فما سمعت منها قبل ذلك\nولا بعد إلى أن ماتت مثل ذلك الغناء فسبح عبد الله بن جعفر والقوم معه وهما\n(ولما رأت أن الشريعة همها ... وأن البياض من فرائصها دامي)\n(تيممت العين التي عند ضارج ... يفيء عليها الظل عرمضها طامي)\nلابن مسجح في هذا الشعر صوت وهذا أحسنهما فلما فرغت قالت جميلة أي سيدي أزيدك قال حسبي فقال بعض من كان معه بأبي جعلت فداك وكيف أنقذ الله من المسلمين جماعة بهذين البيتين قال نعم أقبل قوم من أهل اليمن يريدون النبي فضلوا الطريق ووقعوا على غيرها ومكثوا ثلاثا لا يقدرون على الماء وجعل الرجل منهم يستذري بفيء السمر والطلح يائسا من الحياة إذ أقبل راكب على بعير له وأنشد بعض القوم هذين البيتين فقال\n(ولما رأت أن الشريعة همها ... وأن البياض من فرائصها دامي)\n(تيممت العين التي عند ضارج ... يفيء عليها الظل عرمضها طامي)\nقال الراكب من يقول هذا قال امرؤ القيس قال والله ما كذب هذا ضارج عندكم وأشار لهم إليه فحبوا على الركب فإذا ماء عذب وإذا عليه العرمض والظل يفيء عليه فشربوا منه ريهم وحملوا ما اكتفوا به حتى بلغوا الماء فأتوا النبي فأخبروه وقالوا يا رسول الله أحيانا الله عز و جل ببيتين من شعر امرىء القيس وأنشدوه الشعر فقال رسول الله\nذلك رجل مذكور في الدنيا شريف فيها منسي في الآخرة خامل فيها يجيء يوم القيامة معه لواء الشعراء إلى النار فكل استحسن الحديث ونهض عبد الله بن جعفر ونهض القوم معه فما رأيت مجلسا كان أحسن منه","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":3,"spl":"عبد الله بن جعفر يزورها في منزلها لأنها آلت على نفسها أن لا تغني خارجه","loc":1478},
{"id":"b78-8","bab":"الجزء 8","sec":"عمر بن الخطاب يفضل امرأ القيس على غيره من الشعراء — معبد ومالك يجتمعان في منزل جميلة","page":"ج8 ص208 – ج8 ص209","text":"قال إسحق حدثني بعض أهل العلم عن ابن عياش عن الشعبي قال\nرأيت دغفلا النسابة يحدث أنه رأى العباس بن عبد المطلب سأل عمر بن الخطاب عن الشعراء فقال امرؤ القيس سابقهم خسف لهم عين الشعر فافتقر عن معان عور أصح بصرا قال إسحاق معنى خسف احتفر وهو من كندة من اليمن وليست لهم فصاحة مضر ولا شعرهم بجيد فجعل معاني اليمن معاني عورا وما قاله أصح بصرا أي أجود شعرا ومعنى افتقر احتفر والفقيرة الحفيرة تحفر للفسيلة لتغرس وكل ما ابتدأت حفره فهو فقير والمعنى أنه قال شعرا جيدا وليس هو في معنى شعر مضر\nوقال عمارة بن عقيل بن بلال بن جرير بن الخطفي\nسمعت أبي يقول دخل جدي على بعض ملوك بني أمية فقال ألا تخبرني عن الشعراء قال بلى قال من أشعر الناس قال ابن العشرين يعني طرفة قال فما تقول في امرىء القيس قال اتخذ الخبيث الشعر نعلين فأقسم بالله لو أدركته لرفعت له ذلاذله قال فما رأيك في ابن\nأبي سلمى قال كان يبري الشعر قال فما رأيك في ذي الرمة قال قدر من طريف الكلام وغريبه وحسنه على ما لم يقدر عليه حتى أحد صنف الشعر\nأخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني أيوب بن عباية عن رجل من الأنصار قال زار معبد مالك بن أبي السمح فقال له هل لك أن نصير إلى جميلة فمضيا جميعا فقصداها فأذنت لهما فدخلا فأخرجت إليها رقعة فيها أبيات فقالت لمعبد بعث بهذه الرقعة إلي فلان أغني فيها فقال معبد فابتدئي فابتدأت جميلة فغنت\n(إنما الذلفاء همي ... فليدعني من يلوم)\nغنى معبد\n(أحسن الناس جميعا ... حين تمشي وتقوم)\nغنت جميلة\n(حبب الذلفاء عندي ... منطق منها رخيم)\n(فغنى معبد ... )\n(أصل الحبل لترضى ... وهي للحبل صروم)\nفغنت جميلة\n(حبها في القلب داء ... مستكن لا يريم)\nطريقة واحدة الشعر للأحوص وذكر ابن النطاح أنه للبختري العبادي والغناء لمعبد وله فيه لحنان خفيف ثقيل أول بالسبابة في مجرى البنصر عن ابن المكي وثقيل أول بالوسطى عن عمرو وذكر أحمد بن سعيد المالكي أن له فيه خفيف ثقيل آخر وذكر حماد بن إسحاق أن فيه لمالك وجميلة لحنين وقالت لمعبد ولمالك يغني كل واحد منكما لحنا مما عمله فغناها معبد بشعر قاله فيها الأحوص يصفها به وكان معجبا بها وكانت هي له مكرمة وهو قوله\n(شأتك المنازل بالأبرق ... دوارس كالعين في المهرق)\n(لآل جميلة قد أخلقت ... ومهما يطل عهده يخلق)\n(فإن يقل الناس لي عاشق ... فأين الذي هو لم يعشق)\n(ولم يبك نؤيا على عبرة ... بداء الصبابة والمعلق)\nي هذه الأبيات ثقيل أول بالخنصر في مجرى الوسطى ذكر إسحاق أنه لعطرد وذكر ابن المكي أنه لجميلة وفيها خفيف رمل بالوسطى في مجراها ذكر إسحاق أنه لعطرد أيضا وعمرو وذكر الهشامي أن الثقيل الأول لابن عائشة وذكر حبش أن فيه خفيف ثقيل لمعبد وأن خفيف الرمل لمالك قال معبد فسرت جميلة بما غنيتها به وتبسمت وقالت حسبك يا أبا عباد ولم تكنني قبلها ولا بعدها ثم قالت لمالك يا أخا طيىء هات ما عندك وجنبنا مثل قول عبد ابن قطن فاندفع وغنى بلحن لها وقد تغنى به أيضا معبد لها واللحن\n(ألا من لقلب لا يمل فيذهل ... أفق فالتعزي عن بثينة أجمل)\n(فما هكذا أحببت من كان قبلها ... ولا هكذا فيما مضى كنت تفعل)\n(فإن التي أحببت قد حيل دونها ... فكن حازما والحازم المتحول)\nحن جميلة هكذا ثقيل أول بالبنصر وفيه ألحان عدة مع أبيات أخر من القصيدة وهي لجميل فقالت جميلة أحسنت والله في غنائك وفي الأداء عني أما قوله شأتك فأراد بعدت عنك والشأو البعد يقال جرى الفرس شأوا أو شأوين أي طلقا أو طلقين والمهرق الصحيفة بما فيها من الكتابة والجمع مهارق قال ذو الرمة\n(كمستعبر في رسم دار كأنها ... بوعساء تنضوها الجماهير مهرق)\nالعين أن تتعين الإداوة أو القربة التي تخرز ويسيل الماء عن عيون الخرز فشبه ما بقي من الدار بتعين القربة وطرائق خروقها التي ينزل منها الماء شيئا بعد شيء فأما الذلفاء الذي ذكرت فيها فهي التي فتن بها أهل المدينة وقال بعض من كانت عنده بعد ما طلقها\n(لا بارك الله في دار عددت بها ... طلاق ذلفاء من دار ومن بلد)\n(فلا يقولن ثلاثا قائل أبدا ... إني وجدت ثلاثا أنكد العدد)\nكان إذا عد شيئا يقول واحد اثنان أربعة ولا يقول ثلاثة","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":4,"spl":"عمر بن الخطاب يفضل امرأ القيس على غيره من الشعراء — معبد ومالك يجتمعان في منزل جميلة","song":1,"loc":1479,"partial":1},
{"id":"b78-9","bab":"الجزء 8","sec":"بثينة تبوح لجميلة عن حب جميل لها وعفته","page":"ج8 ص211","text":"وقالت جميلة حدثتني بثينة وكانت صدوقة اللسان جميلة الوجه\nحسنة البيان عفيفة البطن والفرج قالت والله ما أرادني جميل رحمة الله عليه بريبة قط ولا حدثت أنا نفسي بذلك منه وإن الحي انتجعوا موضعا وإني لفي هودج لي أسير إذا أنا بهاتف ينشد أبياتا فلم أتمالك أن رميت بنفسي وأهل الحي ينظرون فبقيت أطلب المنشد فلم أقف عليه فناديت أيها الهاتف بشعر جميل ما وراءك منه وأنا أحسبه قد قضى نحبه ومضى لسبيله فلم يجبني مجيب فناديت ثلاثا وفي كل ذلك لا يرد علي أحد شيئا فقال صواحباتي أصابك يا بثينة طائف من الشيطان فقلت كلا لقد سمعت قائلا يقول قلن نحن معك ولم نسمع فرجعت فركبت مطيتي وأنا حيرى والهة العقل كاسفة البال ثم سرنا فلما كان في الليل إذا ذلك الهاتف يهتف بذلك الشعر بعينه فرميت بنفسي فسعيت إلى الصوت فلما قربت منه انقطع فقلت أيها الهاتف ارحم حيرتي وسكن عبرتي بخبر هذه الأبيات فإن لها شأنا فلم يرد علي شيئا فرجعت إلى رحلي فركبت وسرت وأنا ذاهبة العقل وفي كل ذلك لا يخبرني صواحباتي أنهن سمعن شيئا فلما كانت الليلة القابلة نزلنا وأخذ الحي مضاجعهم ونامت كل عين فإذا الهاتف يهتف بي ويقول يا بثينة أقبلي إلي أنبئك عما تريدين فأقبلت نحو الصوت فإذا شيخ كأنه من رجال الحي فسألته عن اسمه وبيته فقال دعي هذا وخذي فيما هو أهم عليك فقلت له وإن هذا لمما يهمني قال اقنعي بما قلت لك قلت له أنت المنشد الأبيات قال نعم قلت فما خبر جميل قال نعم فارقته وقد قضى نحبه وصار إلى حفرته رحمة الله عليه فصرخت صرخة آذنت منها الحي وسقطت لوجهي فأغمي علي فكأن صوتي لم يسمعه أحد وبقيت سائر ليلتي ثم أفقت عند طلوع الفجر وأهلي يطلبونني فلا يقفون على موضعي ورفعت صوتي بالعويل والبكاء ورجعت إلى مكاني فقال لي أهلي ما خبرك وما شأنك فقصصت عليهم القصة فقالوا يرحم الله جميلا واجتمع نساء الحي وأنشدتهن الأبيات فأسعدنني بالبكاء فأقمن كذلك لا يفارقنني ثلاثا وتحزن الرجال أيضا وبكوا ورثوه وقالوا كلهم يC فإنه كان عفيفا\nصدوقا فلم أكتحل بعده بإثمد ولا فرقت رأسي بمخيط ولا مشط ولا دهنته إلا من صداع خفت على بصري منه ولا لبست خمارا مصبوغا ولا إزارا ولا أزال أبكيه إلى الممات قالت جميلة فأنشدتني الشعر كله وهذا الغناء بعضه وهو\n(ألا من لقلب لا يمل فيذهل ... أفق فالتعزي عن بثينة أجمل)\nال ابن سلام حدثني جرير قال زار ابن سريج جميلة ليسمع منها ويأخذ عنها فلما قدم عليها أنزلته وأكرمته وسألته عن أخبار مكة فأخبرها وبلغ معبدا الخبر وكانت تطارحه وتسأله عن أخبار مكة فيخبرها وكانت عندها جارية محسنة لبقة ظريفة فابتدأت تطارحها فقال ابن سريج سبحان الله نحن كنا أحق بالابتداء قالت جميلة كل إنسان في بيته أمير وليس للداخل أن يتأمر عليه فقال ابن سريج صدقت جعلت فداءك وما أدري أيهما أحسن أدبك أم غناؤك فقالت له كف يا عبيد فإن النبي قال احثوا في وجوه المداحين التراب فسكت ابن سريج وطارحت الجارية بشعر حاتم الطائي\n(أتعرف آثار الديار توهما ... كخطك في رق كتابا منمنما)\n(أذاعت به الأرواح بعد أنيسها ... شهورا وأياما وحولا مجرما)\n(فأصبحن قد غيرن ظاهر تربه ... وغيرت الأنواء ما كان معلما)\n(وغيرها طول التقادم والبلى ... فما أعرف الأطلال إلا توهما)\nقال فحدثت أنه حضر ذلك المجلس جماعة من حذاق أهل الغناء فكلهم قال مزامير داود قال ابن سريج لها أفأسمعك صوتا لي في هذا الشعر قالت هاته فغنى\n(ديار التي قامت تريك وقد عفت ... وأقوت من الزوار كفا ومعصما)\n(تهادى عليها حليها ذات بهجة ... وكشحا كطي السابرية أهضما)\n(فبانت لطيات لها وتبدلت ... به بدلا مرت به الطير أشؤما)\nعاذلتان هبتا بعد هجعة ... تلومان متلافا مفيدا ملوما\nالت جميلة أحسنت يا عبيد وقد غفرنا لك زلتك لحسن غنائك قال معبد جعلت فداءك أفلا أسمعك أنا ايضا لحنا عملته في هذا الشعر قالت هات وإني لأعلم انك تحسن فاندفع فغنى\n(فقلت وقد طال العتاب عليهما ... وأوعدتاني أن تبينا وتصرما)\n(ألا لا تلوماني على ما تقدما ... كفى بصروف الدهر للمرء محكما)\n(تلومان لما غور النجم ضلة ... فتى لا يرى الإنفاق في الحق مغرما)","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":5,"spl":"بثينة تبوح لجميلة عن حب جميل لها وعفته","loc":1480},
{"id":"b78-10","bab":"الجزء 8","sec":"بثينة تبوح لجميلة عن حب جميل لها وعفته","page":"ج8 ص211","text":"الت جميلة ما عدوت الظن بك ولا تجاوزت الطريقة التي أنت عليها قال مالك أفلا أغنيك أنا ايضا قالت ما علمتك إلا تجيد الغناء وتحسن فهات فاندفع فغنى في هذا الشعر\n(يضيء لنا البيت الظليل خصاصه ... إذا هي ليلا حاولت أن تبسما)\n(إذا انقلبت فوق الحشية مرة ... ترنم وسواس الحلي ترنما)\n(ونحرا كفاثور اللجين يزينه ... توقد ياقوت وشذر منظما)\n(كجمر الغضى هبت به بعد هجعة ... من الليل أرواح الصبا فتنسما)\nقالت جميل ما قلت وحسن ما نظمت وإن صوتك يا مالك لمما يزيد العقل قوة والنفس طيبا والطبيعة سهولة وما أحسب أن مجلسنا هذا إلا سيكون علما وفي آخر الزمان متواصفا والخبر ليس كالمشاهدة والواصف ليس كالمعاين وخاصة في الغناء","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":6,"spl":"بثينة تبوح لجميلة عن حب جميل لها وعفته — جميلة تغني ابن أبي عتيق وابن أبي ربيعة والأحوص","loc":1481},
{"id":"b78-11","bab":"الجزء 8","sec":"جميلة تغني ابن أبي عتيق وابن أبي ربيعة والأحوص","page":"ج8 ص215","text":"وحدثني الحسن بن عتبة اللهبي قال حدثني من رأى ابن أبي عتيق وابن أبي ربيعة والأحوص بن محمد الأنصاري وقد أتوا منزل جميلة فاستأذنوا عليها فأذنت لهم فلما جلسوا سألت عمر وأحفت فقال لها إني قصدتك من مكة للسلام عليك فقالت له أهل الفضل أنت قال وقد أحببت أن تفرغي لنا نفسك اليوم وتخلي لنا مجلسك قالت أفعل قال لها الأحوص أحب ألا تغني إلا ما أسألك قالت ليس المجلس لك والقوم شركاؤك فيه قال أجل قال عمر إن ترد أن تفعل ذلك بك يكن قال الأحوص كلا قال عمر فإني أرى أن نجعل الخيار إليها قال ابن أبي عتيق وفقك الله فدعت بالعود وغنت\n(تمشي الهوينى إذا مشت فضلا ... مشي النزيف المخمور في الصعد)\n(تظل من زور بيت جارتها ... واضعة كفها على الكبد)\n(يا من لقلب متيم سدم ... عان رهين مكلم كمد)\n(أزجره وهو غير مزدجر ... عنها وطرفي مكحل السهد)\nفلقد سمعت للبيت زلزلة وللدار همهمة فقال عمر لله درك يا جميلة ماذا أعطيت أنت أول الغناء وآخره ثم سكتت ساعة وأخذوا في الحديث ثم أخذت العود وغنت\n(شطت سعاد وأمسى البين قد أفدا ... وأورثوك سقاما يصدع الكبدا)\n(لا أستيطع لها هجرا ولا ترة ... ولا تزال أحاديثي بها جددا)\nلغناء فيه لسياط خفيف رمل مطلق في مجرى الوسطى عن إسحاق ولم يذكر حبش لحن جميلة وذكر إبراهيم أن فيه لحنا لحكم الوادي وذكر الهشامي وابن خرداذبة أنه من الحان عمر بن عبد العزيز بن مروان في سعاد وأن طريقته من الثقيل الثاني بالوسطى وذكر إبراهيم أن لابن جامع فيه أيضا صنعة فاستخف القوم أجمعين وصفقوا بأيديهم وفحصوا بأرجلهم وحركوا رؤوسهم وقالوا نحن فداؤك من السوء ووقاؤك من المكروه ما أحسن ما غنيت وأجمل ما قلت وأحضر الغداء فتغدى القوم بأنواع من الأطعمة الحارة والباردة ومن الفاكهة الرطبة واليابسة ثم دعت بأنواع من الأشربة فقال عمر لا أشرب وقال ابن أبي عتيق مثل ذلك فقال الأحوص لكنني اشرب وما جزاء جميلة أن يمتنع من شرابها قال عمر ليس ذلك كما ظننته قالت جميلة من شاء أن يحملني بنفسه ويخلط روحي بروحه شكرناه ومن أبى ذلك عذرناه ولم يمنعه ذلك عندنا ما يريد من قضاء حوائجه والأنس\nبمحادثته قال ابن أبي عتيق ما يحسبن بنا إلا مساعدتك قال عمر لا أكون أخسكم افعلوا ما شئتم تجدوني سميعا مطيعا فشرب القوم أجمعون فغنت صوتا بشعر لعمر\n(ولقد قالت لجارات لها ... كالمها يلعبن في حجرتها)\nذن عني الظل لا يتبعني ... ومضت تسعى إلى قبتها لم تعانق رجلا فيما مضى ... طفلة غيداء في حلتها لم يطش قط لها سهم ومن ... ترمه لا ينج من رميتها\nم يذكر طريقة لحنها في هذا الصوت وذكر الهشامي أن فيه لابن المكي رملا بالبنصر وذكر علي بن يحيى أن فيه لابن سريج رملا بالوسطى فصاح عمر ويلاه ويلاه ثلاثا ثم عمد إلى جيب قميصه فشقه إلى أسفله فصار قباء ثم آب إليه عقله فندم واعتذر وقال لم أملك من نفسي شيئا قال القوم قد أصابنا كالذي أصابك وأغمي علينا غير أنا فارقناك في تخريق الثياب فدعت جميلة بثياب فخلعتها على عمر فقبلها ولبسها وانصرف القوم إلى منازلهم وكان عمر نازلا على ابن أبي عتيق فوجه عمر إلى جميلة بعشرة آلاف درهم وبعشرة أثواب كانت معه فقبلتها جميلة وانصرف عمر إلى مكة جذلان مسرورا","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":6,"spl":"بثينة تبوح لجميلة عن حب جميل لها وعفته — جميلة تغني ابن أبي عتيق وابن أبي ربيعة والأحوص","loc":1482},
{"id":"b78-12","bab":"الجزء 8","sec":"رافقها الشعراء والمغنون والمغنيات في حجها إلى مكة","page":"ج8 ص217","text":"قال إسحاق وحدثني أبي عن سياط وابن جامع عن يونس قالا حجت جميلة وأخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا إسحاق بن إبراهيم قال حدثني أبي عن سياط وابن جامع عن يونس الكاتب\nوأخبرني الحسن بن علي قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قالوا جميعا إن جميلة حجت وقد جمعت رواياتهم لتقاربها وأحسب الخبر كله مصنوعا وذلك بين فيه فخرج معها من المغنين مشيعين حتى وافوا مكة ورجعوا معها من الرجال المشهورين الحذاق بالغناء هيت وطويس والدلال وبرد الفؤاد ونومة الضحى وفند ورحمة وهبة الله هؤلاء مشايخ وكلهم طيب الغناء ومعبد ومالك وابن عائشة ونافع بن طنبورة وبديح المليح ونافع الخير ومن المغنيات الفرهة وعزة الميلاء وحبابة وسلامة وخليدة وعقيلة والشماسية وفرعة وبلبلة ولذة العيش وسعيدة والزرقاء ومن غير المغنين ابن أبي عتيق والأحوص وكثير عزة ونصيب وجماعة من الأشراف وكذلك من النساء من مواليها وغيرهن واما سياط فذكر أنه حج معها من القيان مشيعات لها ومعظمات لقدرها ولحقها زهاء خمسين قينة وجه بهن مواليهن معها فأعطوهن النفقات وحملوهن على الإبل في الهوادج والقباب وغير ذلك فأبت جميلة أن تنفق واحدة منهن درهما فما فوقه حتى رجعن وأما يونس فذكر أنه حج معها من الرجال المغنين مع من سمينا زهاء ثلاثين رجلا وتخايروا في اتخاذ أنواع اللباس العجيب الظريف وكذلك في الهوادج والقباب وقيل فيما قال أهل المدينة إنهم ما رأوا مثل ذلك الجمع سفرا طيبا وحسنا وملاحة قالوا ولما\nقاربوا مكة تلقاهم سعيد بن مسجح وابن سريج والغريض وابن محرز والهذليون وجماعة من المغنين من أهل مكة وقيان كثير لم يسمين لنا ومن غير المغنين عمر بن أبي ربيعة والحارث بن خالد المخزومي والعرجي وجماعة من الأشراف فدخلت جميلة مكة وما بالحجاز مغن حاذق ولا مغنية إلا وهو معها وجماعة من الأشراف ممن سمينا وغيرهم من الرجال والنساء وخرج أبناء أهل مكة من الرجال والنساء ينظرون إلى جمعها وحسن هيئتهم فلما قضت حجها سألها المكيون أن تجعل لهم مجلسا فقالت للغناء أم للحديث قالوا لهما جميعا قالت ما كنت لأخلط جدا بهزل وأبت أن تجلس للغناء فقال عمر بن أبي ربيعة أقسمت على من كان في قلبه حب لاستماع غنائها إلا خرج معها إلى المدينة فإني خارج فعزم القوم الذين سميناهم كلهم على الخروج ومعهم جماعة ممن نشط فخرجت في جمع أكثر من جمعها بالمدينة فلما قدمت المدينة تلقاها أهلها وأشرافهم من الرجال والنساء فدخلت أحسن مما خرجت به منها وخرج الرجال والنساء من بيوتهم فوقفوا على أبواب دورهم ينظرون إلى جمعها وإلى القادمين معها فلما دخلت منزلها وتفرق الجمع إلى منازلهم ونزل أهل مكة على أقاربهم وإخوانهم أتاها الناس مسلمين وما استنكف من ذلك كبير ولا صغير فلما مضى لمقدمها عشرة أيام جلست للغناء فقالت لعمر بن أبي ربيعة إني جالسة لك ولأصحابك وإذا شئت فعد الناس لذلك اليوم فغصت الدار بالأشراف من الرجال والنساء فابتدأت جميلة فغنت صوتا بشعر عمر\n(هيهات من أمة الوهاب منزلنا ... إذا حللنا بسيف البحر من عدن)\n(واحتل أهلك أجيادا فليس لنا ... إلا التذكر أو حظ من الحزن)\n(لو أنها أبصرت بالجزع عبرته ... وقد تغرد قمري على فنن)\n(إذا رأت غير ما ظنت بصاحبها ... وأيقنت أن عكا ليس من وطني)\n(ما أنس لا أنس يوم الخيف موقفها ... وموقفي وكلانا ثم ذو شجن)\n(وقولها للثريا وهي باكية ... والدمع منها على الخدين ذو سنن)\n(بالله قولي له في غير معتبة ... ماذا أردت بطول المكث في اليمن)\n(إن كنت حاولت دنيا أو نعمت بها ... فما أصبت بترك الحج من ثمن)\nكلهم استحسن الغناء وضج القوم من حسن ما سمعوا ويقال إنهم ما سمعوا غناء قط أحسن من غنائها ذلك الصوت في ذلك اليوم ودمعت عين عمر حتى جرى الدمع على ثيابه ولحيته وإنه ما رئي عمر كذلك في محفل غيره قط ثم أقبلت على ابن سريج فقالت هات فاندفع يغني ورفع صوته بشعر عمر","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":7,"spl":"رافقها الشعراء والمغنون والمغنيات في حجها إلى مكة — غناء ابن سريج في مجلسها بشعر عمر بن أب","loc":1483},
{"id":"b78-13","bab":"الجزء 8","sec":"غناء ابن سريج في مجلسها بشعر عمر بن أبي ربيعة","page":"ج8 ص219","text":"(أليست بالتي قالت ... لمولاة لها ظهرا)\n(أشيري بالسلام له ... إذا هو نحونا نظرا)\n(وقولي في ملاطفة ... لزينب نولي عمرا)\n(وهذا سحرك النسوان ... قد خبرنني الخبرا)","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":7,"spl":"رافقها الشعراء والمغنون والمغنيات في حجها إلى مكة — غناء ابن سريج في مجلسها بشعر عمر بن أب","loc":1484},
{"id":"b78-14","bab":"الجزء 8","sec":"سماعها لعدد كبير من المغنين","page":"ج8 ص220","text":"فسمع من ابن سريج في هذا اللحن من الحسن ما يقال إنه ما سمع مثله ثم قالت لسعيد بن مسجح هات يا أبا عثمان فاندفع فغنى\n(قد قلت قبل البين لما خشيته ... لتعقب ودا أو لتعلم ما عندي)\n(لك الخير هل من مصدر تصدرينه ... يريح كما سهلت لي سبل الورد)\n(فلما شكوت الحب صدت كأنما ... شكوت الذي ألقى إلى حجر صلد)\n(تولت فأبدت غلة دون نقعها ... كما أرصدت من بخلها إذ بدا وجدي)\nاستحسن ذلك منه وبرع فيه ثم قالت يا معبد هات فغنى\n(أحارب من حاربت من ذي عداوة ... وأحبس مالي إن غرمت فأعقل)\n(وإني أخوك الدائم العهد لم أحل ... إن ابزاك خصم أو نبا بك منزل)\n(ستقطع في الدنيا إذا ما قطعتني ... يمينك فانظر أي كف تبدل)\nالت جميلة أحسنت يا معبد اختيار الشعر والغناء هذا الشعر لمعن بن أوس ثم قالت هات يابن محرز فإني لم أؤخرك لخساسة بك ولا جهلا بالذي يجب في الصناعة ولكنني رأيتك تحب من الأمور كلها أوسطها وأعدلها فجعلتك حيث تحب واسطة بين المكيين والمدنيين فغنى\n(وقفت بربع قد تحمل أهله ... فأذريت دمعا يسبق الطرف هامله)\n(بسائلة الروحاء أو بطن مثغر ... لها الضاحكات الرابيات سواهله)\n(هو الموت إلا أن للموت مدة ... متى يلق يوما فارغا فهو شاغله)\nفقالت جميلة يا أبا الخطاب كيف بدا لك في ثلاثة وأنت لا ترى ذلك قال أحببت أن أواسي معبدا قال معبد والله ما عدوت ما أردت ثم قالت للغريض هات يا مولى العبلات فاندفع يغني\n(فواندمي على الشباب وواندم ... ندمت وبان اليوم مني بغير ذم)\n(وإذ إخوتي حولي وإذ انا شائخ ... وإذ لا أجيب العاذلات من الصمم)\n(أرادت عرارا بالهوان ومن يرد ... عرارا لعمري بالهوان فقد ظلم)\nالت جميلة أحسن عمرو بن شأس ولم تحسن إذ أفسدت غناءك بالتعريض والله ما وضعناك إلا موضعك ولا نقصنا من حظك فبماذا أهناك ثم أقبلت على الجماعة فقالت يا هؤلاء اصدقوه وعرفوه نفسه ليقنع بمكانه فأقبل القوم عليه وقالوا له قد أخطأت إن كنت عرضت فقال قد كان ذلك ولست بعائد وقام إلى جميلة فقبل طرف ثوبها واعتذر فقبلت عذره وقالت له لا تعد ثم أقبلت على ابن عائشة فقالت يا ابا جعفر هات فتغنى بشعر النابغة\n(سقى الغيث قبرا بين بصرى وجاسم ... عليه من الوسمي جود ووابل)\n(وأنبت حوذانا وعوفا منورا ... سأتبعه من خير ما قال قائل)\n(بكى حارث الجولان من هلك ربه ... فحوران منه خاشع متضائل)\n(وما كان بيني لو لقيتك سالما ... وبين الغنى إلا ليال قلائل)\nالت جميلة حسن ما قلت يا ابا جعفر ثم اقبلت على نافع وبديح فقالت أحب أن تغنياني صوتا واحدا فغنيا جميعا بصوت واحد ولحن واحد\n(ألا يا من يلوم على التصابي ... أفق شيئا لتسمع من جوابي)\n(بكرت تلومني في الحب جهلا ... وما في حب مثلي من معاب)\n(أليس من السعادة غير شك ... هوى متواصلين على اقتراب)\n(كريم نال ودا في عفاف ... وستر من منعمة كعاب)\nقالت جميلة هواكما والله واحد وغناؤكما واحد وأنتما نحتما من بقية الكرم وواحد الشرف عبد الله بن جعفر بن أبي طالب ثم أقبلت على الهذليين الثلاثة فقالت غنوا صوتا واحدا فاندفعوا فغنوا بشعر عنترة العبسي\n(حييت من طلل تقادم عهده ... أقوى وأقفر بعد أم الهيثم)\n(كيف المزار وقد تربع أهلها ... بعنيزتين وأهلنا بالغيلم)\n(إن كنت أزمعت الفراق فإنما ... زمت ركابكم بليل مظلم)\n(شربت بماء الدحرضين فأصبحت ... زوراء تنفر عن حياض الديلم)\nقالت ما رأيت شيئا أشبه بغنائكم من اتفاق أرواحكم ثم أقبلت على نافع بن طنبورة فقالت هات يا نقش الغضار ويا حسن اللسان فاندفع يغني\n(يا طول ليلي وبت لم أنم ... وسادي الهم مبطن سقمي)\n(أن قمت يوما على البلاط فأبصرت ... رقاشا وليت لم أقم)\nقالت جميلة حسن والله ولابن سريج في هذا اللحن أربعة أبيات في صوت ثم قالت يا مالك هات فإني لم أؤخرك لأنك في طبقة آخرهم ولكني أردت أن أختم بك يومنا تبركا بك وكي يكون أول مجلسنا كآخره ووسطه كطرفه وإنك عندي ومعبدا لفي طريقة واحدة ومذهب واحد لا يدفع ذلك إلا ظالم ولا ينكره إلا عاضل الحق أقول فمن شاء فلينكر فسكت القوم كلهم إقرارا لما قالت واندفع يغني\n(عدو فمن عادت وسلم لسلمها ... ومن قربت سلمى أحب وقربا)\n(هبيني امرأ إما بريئا ظلمته ... وإما مسيئا تاب بعد وأعتبا)\n(أقول التماس العذر لما ظلمتني ... وحملتني ذنبا وما كنت مذنبا)","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":8,"spl":"سماعها لعدد كبير من المغنين","loc":1485},
{"id":"b78-15","bab":"الجزء 8","sec":"سماعها لعدد كبير من المغنين","page":"ج8 ص220","text":"(ليهنئك إشمات العدو بهجرنا ... وقطعك حبل الوصل حتى تقضبا)\nالت جميلة ليت صوتك يا مالك قد دام لنا ودمنا له وقطعت المجلس وانصرف عامة الناس وبقي خواصهم فلما كان اليوم الثاني حضر القوم جميعا فقالت لطويس هات يا أبا عبد النعيم قال فأنكر ما فعلت جميلة في اليوم الأول لأن طويسا لم يكن يرضى بذلك فأخبرني ابن جامع أن جميلة صنفتهم طويسا واصحابه وابن سريج وأصحابه ثم أقرعت بينهم فخرجت القرعة\nالأولى لابن سريج وأصحابه والثانية لطويس وأصحابه فابتدأ طويس فغنى\n(قد طال ليلي وعاد لي طربي ... من حب خود كريمة الحسب)\n(غراء مثل الهلال آنسة ... أو مثل تمثال صورة الذهب)\n(صادت فؤادي بجيد مغزلة ... ترعى رياضا ملتفة العشب)\nقالت جميلة حسن والله يا أبا عبد النعيم ثم قالت للدلال هات يا أبا يزيد فاندفع فغنى\n(قد كنت آمل فيكم أملا ... والمرء ليس بمدرك أمله)\n(حتى بدا لي منكم خلف ... فزجرت قلبي فارعوى جهله)\n(ليس الفتى بمخلد أبدا ... حيا وليس بفائت أجله)\n(حي البغوم ومن بعقوتها ... وقفا العمود وإن خلا أهله)\nالت حسن والله يا أبا يزيد ثم قالت لهيت إنا نجلك اليوم لكبر سنك ورقة عظمك قال أجل يا ماما ثم قالت لبرد الفؤاد ونومة الضحى هاتيا جميعا لحنا واحدا فغنيا\n(إني تذكرت فلا تلحني ... لؤلؤة مكنونة تنطق)\nسكنها طيبة لم يغذها ... بؤس ولا وال بها يخرق قد قلت والعيس سراع بنا ... ترقل إرقالا وما تعنق\n(يا صاحبي شوقي أرى قاتلي ... وموردي منها جوى يقلق)\nالت جميلة أحسنتما ثم قالت لفند ورحمة وهبة الله هاتوا جميعا صوتا واحدا فإنكم متفقون في الأصوات والألحان فاندفعوا فغنوا\n(أشاقك من نحو العقيق بروق ... لموامع تخفى تارة وتشوق)\n(وما لي لا أهوى جواري بربر ... وروحي إلى أرواحهن تتوق)\n(لهن جمال فائق وملاحة ... ودل على دل النساء يفوق)\nكان بربر حاضرا فقال جواري والله على ما وصفتم فمن شاء أقر ومن شاء انكر فقالت جميلة صدق ثم غنت جميلة بشعر الأعشى ولمعبد فيه صوت أخذه عنها\n(بانت سعاد وأمسى حبلها انقطعا ... واحتلت الغور فالجدين فالفرعا)\n(واستنكرتني وما كان الذي نكرت ... من الحوادث إلا الشيب والصلعا)\n(تقول بنتي وقد قربت مرتحلا ... يا رب جنب أبي الأوصاب والوجعا)\n(وكان شيء إلى شيء فغيره ... دهر ملح على تفريق ما جمعا)\nلم يسمع شيء أحسن من ابتدائنا بالأمس وختمها في اليوم الثاني وقطعت المجلس فانصرف القوم واقام آخرون فلما كان اليوم الثالث اجتمع الناس فضربت ستارة وأجلست الجواري كلهن فضربن وضربت فضربن على خمسين وترا فتزلزلت الدار ثم غنت على عودها وهن يضربن على ضربها بهذا الشعر\n(فإن خفيت كانت لعينك قرة ... وإن تبد يوما لم يعممك عارها)\n(من الخفرات البيض لم تر غلظة ... وفي الحسب الضخم الرفيع نجارها)\n(فما روضة بالحزن طيبة الثرى ... يمج الندا جثجاثها وعرارها)\n(بأطيب من فيها إذا جئت طارقا ... وقد أوقدت بالمندل الرطب نارها)\nدمعت أعين كثير منهم حتى بل ثوبه وتنفس الصعداء وقال بنفسي أنت يا جميلة ثم قالت للجواري أكففن فكففن وقالت يا عزة غني فغنت بشعر لعمر\n(تذكرت هندا وأعصارها ... ولم تقض نفسك أوطارها)\n(تذكرت النفس ما قد مضى ... وهاجت على العين عوارها)\n(لتمنح رامة منا الهوى ... وترعى لرامة أسرارها)\n(إذا لم نزرها حذار العدا ... حسدنا على الزور زوارها)\nقالت جميلة يا عزة إنك لباقية على الدهر فهنيئا لك حسن هذا الصوت مع جودة هذا الغناء ثم قالت لحبابة وسلامة هاتيا لحنا واحدا فغنتا\n(كفى حزنا أني أغيب وتشهد ... وما نلتقي والقلب حران مقصد)\n(ومن عجب أني إذا الليل جنني ... أقوم من الشوق الشديد وأقعد)\n(أحن إليكم مثل ما حن تائق ... إلى الورد عطشان الفؤاد مصرد)\n(ولي كبد حرى يعذبها الهوى ... ولي جسد يبلى ولا يتجدد)\nفاستحسن غناؤهما ثم أقبلت على خليدة فقالت لها بنفسي أنت غني فغنت\n(ألا يا من يلوم على التصابي ... أفق شيئا لتسمع من جوابي)\n(بكرت تلومني في الحب جهلا ... وما في حب مثلي من معاب)\n(أليس من السعادة غير شك ... هوى متواصلين على اقتراب)\n(كريم نال ودا في عفاف ... وستر من منعمة كعاب)\nفاستحسن منها ما غنت وهو بلحنها حسن جدا ثم قالت لعقيلة والشماسية هاتيا فغنتا\n(هجرت الحبيب اليوم في غير ما اجترم ... وقطعت من ذي ودك الحبل فانصرم)","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":9,"spl":"سماعها لعدد كبير من المغنين","loc":1486},
{"id":"b78-16","bab":"الجزء 8","sec":"سماعها لعدد كبير من المغنين","page":"ج8 ص220","text":"(أطعت الوشاة الكاشحين ومن يطع ... مقالة واش يقرع السن من ندم)\nم قالت لفرعة وبلبلة ولذة العيش هاتين فغنين فاندفعن بصوت واحد\n(لعمري لئن كان الفؤاد من الهوى ... بغى سقما إني إذا لسقيم)\n(علي دماء البدن إن كان حبها ... على النأي في طول الزمان يريم)\n(تلم ملمات فينسين بعدها ... ويذكر منها العهد وهو قديم)\n(فأقسم ما صافيت بعدك خلة ... ولا لك عندي في الفؤاد قسيم)\nالت أحسنتن وهو لعمري حسن وقالت لسعدة والزرقاء غنيا فغنتا\n(قد أرسلوني يعزوني فقلت لهم ... كيف العزاء وقد سارت بها الرفق)\n(استهدت الريم عينيه فجادلها ... بمقلتيه ولم تترك له عنق)\nاستحسن ذلك ثم قالت للجماعة فغنوا وانقضى المجلس وعاد كل إنسان إلى وطنه فما رئي مجلس ولا جمع أحسن من اليوم الأول ثم الثاني ثم الثالث\nوحدثتني عمتي وكانت أسن من أبي وعمرت بعده قالت كان السبب في طلب أبيك الغناء والمواظبة عليه لحنا سمعه لجميلة في منزل يونس بن محمد الكاتب فانصرف وهو كئيب حزين مغموم لم يطعم ولم يقبل علينا بوجهه كما كان يفعل فسألته عن السبب فأمسك فألححت عليه فانتهرني وكان لي مكرما فغضبت وقمت من ذلك المجلس إلى بيت آخر فتبعني وترضاني وقال لي أحدثك ولا كتمان منك عشقت صوتا لامرأة قد ماتت فأنا بها وبصوتها هائم إن لم يتداركني الله منه برحمته فقالت أتظن أن الله يحيي لك ميتا قال بل لا أشك قالت فما تعليقك قلبك بما لا يعطاه إلا نبي ولا نبي بعد محمد وأما عشقك الصوت فهو أن تحذقه وتغنيه عشر مرار فتمله ويذهب عشقك له فكأنه ارعوى ورجع إلى نفسه وقام فقبل رأسي ويدي ورجلي وقال لي فرجت عني ما كنت فيه من الكرب والغم ثم تمثل حبك الشيء يعمي ويصم ولزم بيت يونس حتى حذق الصوت ولم يمكث إلا زمنا يسيرا حتى مات يونس وانضم إلى سياط وكان من أحذق أهل زمانه بالغناء وأحسنهم أداء عمن مضى قالت عمتي فقلت لإبراهيم وما الصوت فأنشدني الشعر ولم يحسن أداء الغناء\n(من البكرات عراقية ... تسمى سبيعة أطريتها)\n(من آل أبي بكرة الأكرمين ... خصصت بودي فأصفيتها)\n(ومن حبها زرت أهل العراق ... وأسخطت أهلي وأرضيتها)\n(أموت إذا شحطت دارها ... وأحيا إذا أنا لاقيتها)\nأقسم لو أن ما بي بها ... وكنت الطبيب لداويتها\nالت عمتي هذا شعر حسن فكيف به إذا قطع ومدد تمديد الأطربة\nوضرب عليها بقضبان الدفلى على بطون المعزى فما مضت الأيام والليالي حتى سمعت اللحن مؤدى فما خرق مسامعي شيء قط أحسن منه ولقد أذكرني بما يؤثر من حسن صوت داود وجمال يوسف فبينا أنا يوما جالسة إذ طلع علي إبراهيم ضاحكا مستبشرا فقال لي ألا أحدثك بعجب قلت وما هو قال إن لي شريكا في عشق صوت جميلة قلت وكيف ذلك قال كنت عند سياط في يومنا هذا وأنا أغنيه الصوت وقد وقفني فيه على شيء لم أكن أحكمته عن يونس وحضر عند سياط شيخ نبيل فسبح على الصوت تسبيحا طويلا فظننت أنه فعل ذلك لاستحسانه الصوت فلما فرغت أنا وسياط من اللحن قال الشيخ ما أعجب أمر هذا الشعر وأحسن ما غني به وأحسن ما قال قائله فقلت له دون القوم وما بلغ من العجب به قال نعم","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":10,"spl":"سماعها لعدد كبير من المغنين","loc":1487},
{"id":"b78-17","bab":"الجزء 8","sec":"غنت بشعر عمر بن أبي ربيعة في سبيعة أجمل النساء","page":"ج8 ص230","text":"حجت سبيعة من ولد عبد الرحمن بن أبي بكرة وكانت من أجمل النساء فأبصرها عمر بن أبي ربيعة فلما انحدرت إلى العراق اتبعها يشيعها حتى بلغ معها موضعا يقال له الخورنق فقالت له لو بلغت إلى أهلي وخطبتني لزوجوك فقال لها ما كنت لأخلط تشييعي إياك بخطبة ولكن أرجع ثم آتيكم خاطبا فرجع ومر بالمدينة فقال فيها\n(من البكرات عراقية ... تسمى سبيعة أطريتها)\nم أتى بيت جميلة فسألها أن تغني بهذا الشعر ففعلت فأعجبه ما سمع من حسن غنائها وجودة تأليفها فحسن موقع ذلك منه فوجه إلى بعض موالياته ممن كانت تطلب الغناء أن تأتي جميلة وتأخذ الصوت منها فطارحتها إياه أياما حتى حذقت ومهرت به فلما رأى ذلك عمر قال أرى أن تخرجي إلى سبيعة\nوتغنيها هذا الصوت وتبلغيها رسالتي قالت نعم جعلني الله فداك فأتتها فرحبت بها وأعلمتها الرسالة فحيت وأكرمت ثم غنتها فكادت أن تموت فرحا وسرورا لحسن الغناء والشعر ثم عادت رسول عمر فأعلمته ما كان وقالت له إنها خارجة في تلك السنة فلما كان أوان الحج استأذنت سبيعة أباها في الحج فأبى عليها وقال لها قد حججت حجة الإسلام قالت له تلك الحجة هي التي أسهرت ليلي وأطالت نهاري وتوقتني إلى أن أعود وأزور البيت وذلك القبر وإن أنت لم تأذن لي مت كمدا وغما وذلك أن بقائي إنما كان لحضور الوقت فإن يئست فالموت لا شك نازل بي فلما رأى ذلك أبوها رق لها وقال ليس يسعني منعها مع ما أرى بها فأذن لها ووافى عمر المدينة ليعرف خبرها فلما قدمت علم بذلك وسألها أن تأتي منزل جميلة وقد سبق إليه عمر فأكرمتها جميلة وسرت بمكانها فقالت لها سبيعة جعلني الله فداك اقلقني وأسهرني صوتك بشعر عمر في فأسمعيني إياه قالت جميلة وعزازة لوجهك الجميل فغنتها الصوت فأغمي عليها ساعة حتى رش على وجهها الماء وثاب إليها عقلها ثم قالت أعيدي علي فأعادت الصوت مرار في كل مرة يغشى عليها ثم خرجت إلى مكة وخرج معها فلما رجعت مرت بالمدينة وعمر معها فأتت جميلة فقالت لها أعيدي علي الصوت ففعلت وأقامت عليها ثلاثا تسألها أن تعيد الصوت فقالت لها جميلة إني أريد أن أغنيك صوتا فاسمعيه قالت هاتيه يا سيدتي فغنتها\n(أبت المليحة أن تواصلني ... وأظن أني زائر رمسي)\n(لا خير في الدنيا وزينتها ... ما لم توافق نفسها نفسي)\n(لا صبر لي عنها إذا حسرت ... كالبدر أو قرن من الشمس)\n(ورمت فؤادك عند نظرتها ... بملاحة الإيثار والأنس)\nقالت سبيعة لولا أن الأول شعر عمر لقدمت هذا على كل شيء سمعته فقال عمر فإنه والله أحسن من ذلك فأما الشعر فلا قالت جميلة صدقت\nوالله قالت عمتي قال لها أبي لعمري إن ذلك على ما قالا ولابن سريج في هذا الشعر لحن عن جميلة وربما حكي بزيادة أو نقصان أو مثلا بمثل","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":11,"spl":"غنت بشعر عمر بن أبي ربيعة في سبيعة أجمل النساء","loc":1488},
{"id":"b78-18","bab":"الجزء 8","sec":"شيخ يثنيها عن عزمها اعتزال الغناء","page":"ج8 ص232","text":"أخبرني من يفهم الغناء قال بلغني أن جميلة قعدت يوما على كرسي لها وقالت لآذنتها لا تحجبي عنا أحدا اليوم واقعدي بالباب فكل من يمر بالباب فاعرضي عليه مجلسي ففعلت ذلك حتى غصت الدار بالناس فقالت جميلة اصعدوا إلى العلالي فصعدت جماعة حتى امتلأت السطوح فجاءتها بعض جواريها فقالت لها يا سيدتي إن تمادى أمرك على ما أرى لم يبق في دارك حائط إلا سقط فأظهري ما تريدين قالت اجلسي فلما تعالى النهار واشتد الحر استسقى الناس الماء فدعت لهم بالسويق فشرب من أراد فقالت أقسمت على كل رجل وامرأة دخل منزلي إلا شرب فلم يبق في سفل الدار ولا علوها أحد إلا شرب وقام على رؤوسهم الجواري بالمناديل والمراوح الكبار وأمرت جواريها فقمن على كراسي صغار فيما بين كل عشرة نفر جارية تروح ثم قالت لهم إني قد رأيت في منامي شيئا أفزعني وأرعبني ولست أعرف ما سبب ذلك وقد خفت أن يكون قرب أجلي وليس ينفعني إلا صالح عملي وقد رأيت أن أترك الغناء كراهة أن يلحقني منه شيء عند ربي فقال قوم منهم وفقك الله وثبت عزمك وقال آخرون بل لا حرج عليك في الغناء وقال شيخ منهم ذو سن وعلم وفقه وتجرية قد تكلمت الجماعة وكل حزب بما لديهم فرحون ولم أعترض عليهم في قولهم ولا شركتهم في رأيهم فاستمعوا الآن لقولي\nوأنصتوا ولا تشغبوا إلى وقت انقضاء كلامي فمن قبل قولي فالله موفقه ومن خالفني فلا بأس عليه إذ كنت في طاعة ربي فسكت القوم جميعا فتكلم الشيخ فحمد الله وأثنى عليه وصلى على محمد النبي ثم قال يا معشر أهل الحجاز إنكم متى تخاذلتم فشلتم ووثب عليكم عدوكم وظفر بكم ولا تفلحوا بعدها أبدا إنكم قد انقلبتم على أعقابكم لأهل العراق وغيرهم ممن لا يزال ينكر عليكم ما هو وارثه عنكم لا ينكره عالمكم ولا يدفعه عابدكم بشهادة شريفكم ووضيعكم يندب إليه كما يندب جموعكم وشرفكم وعزكم فأكثر ما يكون عند عابدكم فيه الجلوس عنه لا للتحريم له لكن للزهد في الدنيا لأن الغناء من أكبر اللذات وأسر للنفوس من جميع الشهوات يحيي القلب ويزيد في العقل ويسر النفس ويفسح في الرأي ويتيسر به العسير وتفتح به الجيوش ويذلل به الجبارون حتى يمتهنوا أنفسهم عند استماعه ويبرىء المرضى ومن مات قلبه وعقله وبصره ويزيد أهل الثروة غنى وأهل الفقر قناعة ورضا باستماعه فيعزفون عن طلب الأموال من تمسك به كان عالما ومن فارقه كان جاهلا لأنه لا منزلة أرفع ولا شيء أحسن منه فكيف يستصوب تركه ولا يستعان به على النشاط في عبادة ربنا عز و جل وكلام كثير غير هذا ذهب عن المحدث به فما رد عليه أحد ولا أنكر ذلك منهم بشر وكل عاد بالخطأ على نفسه وأقر بالحق له ثم قال لجميلة أوعيت ما قلت ووقع من نفسك وما ذكرت قالت أجل وأنا أستغفر الله قال لها فاختمي مجلسنا وفرقي جماعتنا بصوت فقط فغنت\n(أفي رسم دار دمعك المترقرق ... سفاها وما استنطاق ما ليس ينطق)\n(بحيث التقى جمع وأقصى محسر ... مغانيه قد كادت عن العهد تخلق)\n(مقام لنا بعد العشاء ومنزل ... به لم يكدره علينا معوق)\n(فأحسن شيء كان أول ليلنا ... وآخره حزن إذا نتفرق)\nفقال الشيخ حسن والله أمثل هذا يترك فيم يتشاهد الرجال لا والله ولا كرامة لمن خالف الحق ثم قام وقام الناس معه وقال الحمد لله الذي لم يفرق جماعتنا على اليأس من الغناء ولا جحود فضيلته وسلام عليك ورحمة الله يا جميلة","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":12,"spl":"شيخ يثنيها عن عزمها اعتزال الغناء","loc":1489},
{"id":"b78-19","bab":"الجزء 8","sec":"وصف مجلس آخر لها","page":"ج8 ص234","text":"وقال أبو عبد الله جلست جميلة يوما ولبست برنسا طويلا وألبست من كان عندها برانس دون ذلك وكان في القوم ابن سريج وكان قبيح الصلع قد اتخذ وفرة شعر يضعها على رأسه وأحبت جميلة أن ترى صلعته فلما بلغ البرنس إلى ابن سريج قال دبرت علي ورب الكعبة وكشف صلعته ووضع القلنسية على رأسه وضحك القوم من قبح صلعته ثم قامت جميلة ورقصت وضربت بالعود وعلى رأسها البرنس الطويل وعلى عاتقها بردة يمانية وعلى القوم أمثالها وقام ابن سريج يرقص ومعبد والغريض وابن عائشة ومالك وفي يد كل واحد منهم عود يضرب به على ضرب جميلة ورقصها فغنت وغنى القوم على غنائها\n(ذهب الشباب وليته لم يذهب ... وعلا المفارق وقع شيب مغرب)\n(والغانيات يردن غيرك صاحبا ... ويعدنك الهجران بعد تقرب)\n(إني أقول مقالة بتجارب ... حقا ولم يخبرك مثل مجرب)\n(صاف الكريم وكن لعرضك صائنا ... وعن اللئيم ومثله فتنكب)\nثم دعت بثياب مصبغة ووفرة شعر مثل وفرة ابن سريج فوضعتها على رأسها ودعت للقوم بمثل ذلك فلبسوا ثم ضربت بالعود وتمشت وتمشى القوم خلفها وغنت وغنوا بغنائها بصوت واحد\n(يمشين مشي قطا البطاح تأودا ... قب البطون رواجح الأكفال)\n(فيهن آنسة الحديث حيية ... ليست بفاحشة ولا متفال)\n(وتكون ريقتها إذا نبهتها ... كالمسك فوق سلافة الجريال)\nم نعرت ونعر القوم طربا ثم جلست وجلسوا وخلعوا ثيابهم ورجعوا إلى زيهم وأذنت لمن كان ببابها فدخلوا وانصرف المغنون وبقي عندها من يطارحها من الجواري وحدثتني عمتي قالت سمعت سياطا يحدث أباك يوما بأحاديث جميلة فقال بنفسي هي وأمي فما كان أحسن وجهها وخلقها وغناءها ما خلفت النساء مثلها شبيها فأعجبني ذلك ثم قال سياط جلست جميلة يوما للوفادة عليها وجعلت على رؤوس جواريها شعورا مسدلة كالعناقيد إلى أعجازهن وألبستهن أنواع الثياب المصبغة ووضعت فوق الشعور التيجان وزينتهن بأنواع الحلي ووجهت إلى عبد الله بن جعفر تستزيره وقالت لكاتب أملت عليه بأبي أنت وأمي قدرك يجل عن رسالتي وكرمك يحتمل زلتي وذنبي لا تقال عثرته ولا تغفر حوبته فإن صفحت فالصفح لكم معشر أهل البيت يؤثر والخير والفضل كله فيكم مدخر ونحن العبيد وأنتم الموالي فطوبى لمن كان لكم مقاربا وإلى وجوهكم ناظرا وطوبى لمن كان لكم مجاورا وبعزكم\nقاهرا وبضيائكم مبصرا والويل لمن جهل قدركم ولم يعرف ما أوجبه الله على هذا الخلق لكم فصغيركم كبير بل لا صغير فيكم وكبيركم جليل بل الجلالة التي وهبها الله عز و جل للخلق هي لكم ومقصورة عليكم وبالكتاب نسألك وبحق الرسول ندعوك إن كنت نشيطا لمجلس هيأته لك لا يحسن إلا بك ولا يتم إلا معك ولا يصلح أن ينقل عن موضعه ولا يسلك به غير طريقه فلما قرأ عبد الله الكتاب قال إنا لنعرف تعظيمها لنا وإكرامها لصغيرنا وكبيرنا وقد علمت أنها قد آلت ألية ألا تغني أحدا إلا في منزلها وقال للرسول والله قد كنت على الركوب إلى موضع كذا وكان في عزمي المرور بها فأما إذا وافق ذلك مرادها فإني جاعل بعد رجوعي طريقي عليها فلما صار إلى بابها أدخل بعض من كان معه إليها وصرف بعضهم فنظر إلى ذلك الحسن البارع والهيئة الباذة فأعجبه ووقع في نفسه فقال يا جميلة لقد أوتيت خيرا كثيرا ما أحسن ما صنعت فقالت يا سيدي إن الجميل للجميل يصلح ولك هيأت هذا المجلس فجلس عبد الله بن جعفر وقامت على رأسه وقامت الجواري صفين فأقسم عليها فجلست غير بعيد ثم قالت يا سيدي ألا أغنيك قال بلى فغنت\n(بني شيبة الحمد الذي كان وجهه ... يضيء ظلام الليل كالقمر البدر)\n(كهولهم خير الكهول ونسلهم ... كنسل الملوك لا يبور ولا يجري)\n(أبو عتبة الملقي إليك جماله ... أغر هجان اللون من نفر زهر)\n(لساقي الحجيج ثم للخير هاشم ... وعبد مناف ذلك السيد الغمر)\n(أبوكم قصي كان يدعى مجمعا ... به جمع الله القبائل من فهر)","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":13,"spl":"وصف مجلس آخر لها","loc":1490},
{"id":"b78-21","bab":"الجزء 8","sec":"وصف مجلس آخر لها — أنزلت العرجي على الأحوص بعد فراره من مكة","page":"ج8 ص234 – ج8 ص237","text":"قال عبد الله أحسنت يا جميلة وأحسن حذافة ما قال بالله أعيديه علي فأعادته فجاء الصوت أحسن من الارتجال ثم دعت لكل جارية بعود وأمرتهن بالجلوس على كراسي صغار قد أعدتها لهن فضربن وغنت عليهن هذا الصوت وغنى جواريها على غنائها فلما ضربن جميعا قال عبد الله ما ظننت أن مثل هذا يكون وإنه لمما يفتن القلب ولذلك كرهه كثير من الناس لما علموا فيه ثم دعا ببغلته فركبها وانصرف إلى منزله وقد كانت جميلة أعدت طعاما كثيرا وكان أراد المقام فقال لأصحابه تخلفوا للغداء فتغدوا وانصرفوا مسرورين وهذا الشعر لحذافة بن غانم بن عبيد الله بن عويج بن عدي بن كعب يمدح به عبد المطلب\nقال وحدثني بعض المكيين قال كان العرجي وهو عبد الله بن عمرو بن عثمان شاعرا سخيا شجاعا أديبا ظريفا ويشبه شعره بشعر عمر بن ابي ربيعة والحارث بن خالد بن هشام وإن كانا قدما عليه وقد نسب كثير من شعره إلى شعرهما وكان صاحب صيد فخرج يوما متنزها من مكة ومعه جماعة من غلمانه ومواليه ومعه كلابه وفهوده وصقوره وبوازيه نحو الطائف إلى مال له بالعرج وبهذا الموضع سمي\nالعرجي فجرى بينه وبين مولى لبني أمية كلام فأمضه المولى فكف عنه العرجي حتى أوى إلى منزله ثم هجم عليه ومعه غلمانه فأمرهم أن يوثقوه ثم أمرهم أن ينكحوا امرأته وهو يراهم ففعلوا ثم أخرجه فقتله فبلغ أمير مكة ما فعل فطلبه فخرج من منزله وأخرج معه غلمانه ومواليه وآلة الصيد وتوجه نحو المدينة وقد ركب أفراسه وأعد عدته فلم يزل يتصيد ويقصف في طريقه حتى دخل المدينة ليلا وأراد المقام في منزل جميلة وكانت آلت ألا تغني بشعره ولا تدخله منزلها لكثرة عبثه وسفهه وحداثة سنه فلما أعلمت بمكانه ليلا قالت طارق إن له لشأنا فاستخبرت خبره فقيل لها إنه قدم مستخفيا ولم ير بالمدينة موضعا هو أطيب له من منزلك والأيمان تكفر والأشراف لا يردون فقالت لرسولها إليه منزلي منزل جوار ولا يمكن مثلك الاستخفاء فيه فعليك بالأحوص وكان الأحوص مجانبا له لشيء جرى بينه وبينه في منزل جميلة فقال أنى لي بالأحوص مع الذي كان بيننا قالت ائته عني وقل له قد غنينا بذلك الشعر فإن أحببت أن تظهر وتبقى مودتنا لك فأصلح ما بينك وبين عبد الله إذ أصلح ما بيننا وأنزله منزلك قال لها ليس هذا بمقنعي أما إذ أبيت أن أقيم بمنزلك فوجهي معي رسولا إلى الأحوص فإن منزله أحب المنازل إلي بعد منزلك فوجهت معه إلى الأحوص بعض مولياتها فأنزله الأحوص وأكرمه وأحسن جواره وستر أمره فقال شعرا ووجه به إلى جميلة\n(ألا قاتل الله الهوى كيف أخلقا ... فلم تلفه إلآ مشوبا ممذقا)\n(وما من حبيب يستزير حبيبه ... يعاتبه في الود إلا تفرقا)\n(أمر وصال الغانيات فأصبحت ... مضاضته يشجى بها من تمطقا)\n(تعلق هذا القلب للحين معلقا ... غزالا تحلى عقد در ويارقا)\n(إذا قلت مهلا للفؤاد عن التي ... دعتك إليها العين أغضى وأطرقا)\n(دعانا فلم نستبق حبا بما نرى ... فما منك هذا العذل إلا تخرقا)\n(فقد سن هذا الحب من كان قبلنا ... وقاد الصبا المرء الكريم فأعنقا)\nلما قرأت شعره رقت له وقالت كيف لي بإيلائي ألا يدخل منزلي ولا أغنيه بشعره فقيل لها يدخل منزلك وتغنين وتكفرين عن يمينك فوجهت إليه أن صر إلينا والأحوص في تلك الليلة فجاءاها وعرفت الأحوص تكفير اليمين فقال لها وأنا والله شفيعه إليك ففرجي ما به من غم فقد فارق من يحب ويهوى فتؤنسينه وتسرينه وتغنينه بشعره فغنت\n(ألا قاتل الله الهوى كيف أخلقا ... فلم تلفه إلا مشوبا ممذقا)","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":14,"spl":"وصف مجلس آخر لها — أنزلت العرجي على الأحوص بعد فراره من مكة","loc":1491},
{"id":"b78-22","bab":"الجزء 8","sec":"إعجاب الأحوص بها ودعوتها له في مجلس خاص","page":"ج8 ص239","text":"وحدثني بعض أهلنا قال قال يونس بن محمد كان الأحوص معجبا بجميلة ولم يكن يكاد يفارق منزلها إذا جلست فصار إليها يوما بغلام جميل الوجه يفتن من رآه فشغل أهل المجلس وذهبت اللحون عن الجواري وخلطن في غنائهن فأشارت جميلة إلى الأحوص أن أخرج الغلام فالخلل قد عم مجلسي وأفسد علي أمري فأبى الأحوص وتغافل وكان بالغلام معجبا فآثر لذته بالنظر إلى الغلام مع السماع ونظر الغلام إلى الوجوه الحسان من الجواري ونظرن إليه وكان مجلسا عاما فلما خافت عاقبة المجلس وظهور أمره أمرت بعض من حضر بإخراج الغلام فأخرج وغضب الأحوص وخرج مع الغلام ولم يقل شيئا فأحمد أهل المجلس ما كان من جميلة وقال لها بعضهم هذا كان الظن بك أكرمك الله فقالت إنه\nوالله ما استأذنني في المجيء به ولا علمت به حتى رأيته في داري ولا رأيت له وجها قبل ذلك وإنه ليعز علي غضب الأحوص ولكن الحق أولى وكان ينبغي له ألا يعرض نفسه وإياي لما نكره مثله فلما تفرق أهل المجلس بعثت إليه الذنب لك ونحن منه برءاء إذ كنت قد عرفت مذهبي فلم عرضتني للذي كان فقد ساءني ذلك وبلغ مني ولكن لم أجد بدا من الذي رأيت إما حياء وإما تصنعا فرد عليها ليس هذا لك بعذر إن لم تجعلي لي وله مجلسا نخلو فيه جميعا تمحين به ما كان منك قالت أفعل ذلك سرا قال الأحوص قد رضيت فجاءاها ليلا فأكرمتهما ولم تظهر واحدة من جواريها على ذلك إلا عجائز من مواليها وسألها الأحوص وأقسم عليها أن تغنيه من شعره\n(وبالقفر دار من جميلة هيجت ... سوالف حب في فؤادك منصب)\n(وكانت إذا تنأى نوى أو تفرقت ... شداد الهوى لم تدر ما قول مشغب)\n(أسيلة مجرى الدمع خمصانة الحشا ... برود الثنايا ذات خلق مشرعب)\n(ترى العين ما تهوى وفيها زيادة ... من الحسن إذ تبدو وملهى لملعب)\nال يونس ما لها صوت أحسن منه وابن محرز يغنيه وعنها أخذه وأنا أغنيه فتعجبني نفسي ويدخلني شيء لا أعرفه من النخوة والتيه وقال المحدث لي بهذا الحديث عن يونس إن هذا للأحوص في جميلة والذي عندي أنه لطفيل\nالغنوي قاله في ابن زيد الخيل وهو زيد بن المهلهل بن المختلس بن عبد رضا أحد بني نبهان ونبهان لقب له ولكنه سودان بن عمرو بن الغوث بن طيىء أغار على بني عامر فأصاب بني كلاب وبني كعب واستحر القتل في غني بن أعصر ومالك بن أعصر وأعصر هو الدخان ولذلك قيل لهما ابنا دخان وأخوهما الحارث وهو الطفاوة وهو مالك بن سعد بن قيس بن عيلان وغطفان بن سعد عمهم وكانت غني مع بني عامر في دارهم موالي لنمير وكان فيهم فرسان وشعراء ثم إن غنيا أغارت على طيىء وعليهم سيار بن هريم فقال في ذلك قصيدته الطويلة\n(وبالقفر دار من جميلة هيجت ... سوالف شوق في فؤادك منصب)\nحدثني ايوب بن عباية قال كان عمرو بن أحمر بن العمرد بن عامر بن عبد شمس بن فراص بن معن بن مالك بن أعصر بن قيس بن عيلان بن مضر من شعراء الجاهلية المعدودين وكان ينزل الشام وقد أدرك الإسلام وأسلم وقال في الجاهلية والإسلام شعرا كثيرا وفي الخلفاء الذين أدركهم عمر بن الخطاب فمن دونه إلى عبد الملك بن مروان وكان في خيل خالد بن الوليد حين وجه أبو بكر خالدا إلى الشام ولم يأت أبا بكر وقال في خالد رحمه الله\n(إذا قال سيف الله كروا عليهم ... كررت بقلب رابط الجأش صارم)\nوقال في عمر بن الخطاب رضي الله عنه قصيدة له طويلة جيدة\n(أدركت آل أبي حفص وأسرته ... وقبل ذاك ودهرا بعده كلبا)\n(قد ترتمي بقواف بيننا دول ... بين الهناتين لا جدا ولا لعبا)\n(الله يعلم ما قولي وقولهم ... إذ يركبون جنانا مسهبا وربا)\nقال في عثمان بن عفان رضي الله عنه\n(حثي فليس إلى عثمان مرتجع ... إلا العداء وإلا مكنع ضرر)\n(إخالها سمعت عزفا فتحسبه ... إهابة القسر ليلا حين تنتشر)\nقال في علي بن أبي طالب رضي الله عنه\n(من مبلغ مألكا عني أبا حسن ... فارتح لخصم هداك الله مظلوم)\nلما أنشدت جميلة قصيدته في عمر بن الخطاب قالت والله لأعملن فيها لحنا لا يسمعه أحد أبدا إلا بكى قال إبراهيم وصدقت والله ما سمعته قط إلا ابكاني لأني أجد حين أسمعه شيئا يضغط قلبي ويحرقه فلا أملك عيني وما رأيت أحدا قط سمعه إلا كانت هذه حاله","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":15,"spl":"إعجاب الأحوص بها ودعوتها له في مجلس خاص","song":1,"loc":1492},
{"id":"b78-23","bab":"الجزء 8","sec":"من المائة المختارة","page":"ج8 ص242","text":"(يا دار عبلة من مشارق مأسل ... درس الشؤون وعهدها لم ينجل)\n(فاستبدلت عفر الظباء كأنما ... أبعارها في الصيف حب الفلفل)\n(تمشي النعام به خلاء حوله ... مشي النصارى حول بيت الهيكل)\n(إحذر محل السوء لا تحلل به ... وإذا نبا بك منزل فتحول)\nلشعر فيما ذكر يحيى بن علي عن إسحاق لعنترة بن شداد العبسي وما رأيت هذا الشعر في شيء من دواوين شعر عنترة ولعله من رواية لم تقع إلينا فذكر غير أبي أحمد أن الشعر لعبد قيس بن خفاف البرجمي إلا أن البيت الأخير لعنترة صحيح لا يشك فيه والغناء لأبي دلف القاسم بن عيسى العجلي ولحنه المختار على ما ذكره أبو أحمد من الثقيل الأول وذكر ابن خرداذبه أن لحن أبي دلف خفيف ثقيل بالوسطى وذكر إسحاق أن فيه لمعبد لحنا من الثقيل الأول المطلق في مجرى الوسطى وأن فيه لأبي دلف لحنا ولم يجنسه وذكر حبش أن فيه لابن محرز ثاني ثقيل بالوسطى وأن لابن سريج في البيت الثاني ثقيلا أول وذكر ابن خرداذبه أن خفيف الثقيل لمالك وليس ممن يعتمد على قوله وقد ذكر يونس أيضا أن فيه غناء لمالك ولم يذكر جنسه ولا طريقته","topic":"ذكر جميلة وأخبارها","topicNo":78,"sp":16,"spl":"من المائة المختارة","loc":1493},
{"id":"b79-1","bab":"الجزء 8","sec":"ذكر عنترة ونسبه وشيء من أخباره","page":"ج8 ص244","text":"هو عنترة بن شداد وقيل ابن عمرو بن شداد وقيل عنترة بن شداد بن عمرو بن معاوية بن قراد بن مخزوم بن ربيعة وقيل مخزوم بن عوف بن مالك بن غالب بن قطيعة بن عبس بن بغيض بن الريث بن غطفان بن سعد بن قيس بن عيلان بن مضر وله لقب يقال له عنترة الفلحاء وذلك لتشقق شفتيه وأمه أمة حبشية يقال لها زبيبة وكان لها ولد عبيد من غير شداد وكانوا إخوته لأمه وقد كان شداد نفاه مرة ثم اعترف به فألحق بنسبه وكانت العرب تفعل ذلك تستعبد بني الإماء فإن أنجب اعترفت به وإلا بقي عبدا فأخبرني علي بن سليمان النحوي الأخفش قال أخبرنا أبو سعيد الحسن بن الحسين السكري عن محمد بن حبيب قال أبو سعيد وذكر ذلك أبو عمرو الشيباني قالا كان عنترة قبل أن يدعيه أبوه حرشت عليه امرأة أبيه وقالت إنه يراودني عن نفسي فغضب من ذلك شداد غضبا شديدا وضربه ضربا مبرحا وضربه بالسيف فوقعت عليه امرأة أبيه وكفته عنه فلما رأت ما به من الجراح بكت وكان اسمها سمية وقيل سهية فقال عنترة\n(أمن سمية دمع العين مذروف ... لو أن ذا منك قبل اليوم معروف)\n(كأنها يوم صدت ما تكلمني ... ظبي بعسفان ساجي العين مطروف)\n(تجللتني إذ أهوى العصا قبلي ... كأنها صنم يعتاد معكوف)\n(العبد عبدكم والمال مالكم ... فهل عذابك عني اليوم مصروف)\n(تنسى بلائي إذا ما غارة لحقت ... تخرج منها الطوالات السراعيف)\n(يخرجن منها وقد بلت رحائلها ... بالماء تركضها الشم الغطاريف)\n(قد أطعن الطعنة النجلاء عن عرض ... تصفر كف أخيها وهو منزوف)\nنى في البيت الأول والثاني علوية ولحنه من الثقيل الأول مطلق في مجرى البنصر وقيل إنه لإبراهيم وفيهما رمل بالوسطى يقال إنه لابن سريج وهو من منحول ابن المكي قوله مذروف من ذرفت عينه يقال ذرفت تذرف ذريفا وذرفا وهو قطر يكاد يتصل وقوله لو أن ذا منك قبل اليوم معروف أي قد أنكرت هذا الحنو والإشفاق منك لأنه لو كان معروفا قبل ذلك لم ينكره ساجي العين ساكنها والساجي الساكن من كل شيء مطروف أصابت عينه طرفة وإذا كان كذلك فهو أسكن لعينه تجللتني ألقت نفسها علي وأهوى اعتمد صنم يعتاد أي يؤتى مرة بعد مرة ومعكوف يعكف عليه والسراعيف السراع واحدتها سرعوفة والطوالات الخيل والرحائل السروج والشمم ارتفاع في الأنف والغطاريف الكرام والسادة أيضا والغطرفة ضرب من السير والمشي يختال فيه والنجلاء الواسعة يقال سنان منجل واسع الطعنة عن عرض أي\nعن شق وحرف وقال غيره أعترضه اعتراضا حين أقتله","topic":"ذكر عنترة ونسبه وشيء من أخباره","topicNo":79,"sp":0,"spl":"ذكر عنترة ونسبه وشيء من أخباره","song":1,"loc":1494},
{"id":"b79-2","bab":"الجزء 8","sec":"كيف ادعاه أبوه","page":"ج8 ص246","text":"أخبرني محمد بن الحسن بن دريد قال حدثني عمي عن ابن الكلبي وأخبرني إبراهيم بن أيوب عن ابن قتيبة قال قال ابن الكلبي شداد جد عنترة غلب على نسبه وهو عنترة بن عمرو بن شداد وقد سمعت من يقول إن شدادا عمه كان نشأ في حجره فنسب إليه دون أبيه قال وإنما ادعاه أبوه بعد الكبر وذلك لأن أمه كانت أمة سوداء يقال لها زبيبة وكانت العرب في الجاهلية إذا كان للرجل منهم ولد من أمة استعبدوه وكان لعنترة إخوة من أمه عبيد وكان سبب ادعاء أبي عنترة إياه أن بعض أحياء العرب أغاروا على بني عبس فأصابوا منهم واستاقوا إبلا فتبعهم العبسيون فلحقوهم فقاتلوهم عما معهم وعنترة يومئذ فيهم فقال له أبوه كر يا عنترة فقال عنترة العبد لا يحسن الكر إنما يحسن الحلاب والصر فقال كر وأنت حر فكر وهو يقول\n(أنا الهجين عنتره ... كل امرىء يحمي حره)\n(أسوده وأحمره ... )\n(والشعرات المشعره ... )\n(الواردات مشفره ... )\nقاتل يومئذ قتالا حسنا فادعاه أبوه بعد ذلك وألحق به نسبه وحكى غير ابن الكلبي أن السبب في هذا أن عبسا أغاروا على طيىء\nفأصابوا نعما فلما أرادوا القسمة قالوا لعنترة لا نقسم لك نصيبا مثل أنصبائنا لأنك عبد فلما طال الخطب بينهم كرت عليهم طيىء فاعتزلهم عنترة وقال دونكم القوم فإنكم عددهم واستنقذت طيىء الإبل فقال له أبوه كر يا عنترة فقال أو يحسن العبد الكر فقال له أبوه العبد غيرك فاعترف به فكر واستنقذ النعم وجعل يقول\n(أنا الهجين عنتره ... كل امرىء يحمي حره)\nلأبيات قال ابن الكلبي وعنترة أحد أغربة العرب وهم ثلاثة عنترة وأمه زبيبة وخفاف بن عمير الشريدي وأمه ندبة والسليك بن عمير السعدي وأمه السلكة وإليهن ينسبون وفي ذلك يقول عنترة\n(إني امرؤ من خير عبس منصبا ... شطري وأحمي سائري بالمنصل)\n(وإذا الكتيبة أحجمت وتلاحظت ... ألفيت خيرا من معم مخول)\nيقول إن أبي من أكرم عبس بشطري والشطر الآخر ينوب عن كرم أمي فيه ضربي بالسيف فأنا خير في قومي ممن عمه وخاله منهم وهو لا يغني غنائي وأحسب أن هذه القصيدة هي التي يضاف إليها البيتان اللذان يغنى فيهما وهذه الأبيات قالها في حرب داحس والغبراء","topic":"ذكر عنترة ونسبه وشيء من أخباره","topicNo":79,"sp":1,"spl":"كيف ادعاه أبوه","loc":1495,"partial":1},
{"id":"b79-3","bab":"الجزء 8","sec":"كان حامي لواء بني عبس","page":"ج8 ص247","text":"قال أبو عمرو الشيباني غزت بنو عبس بني تميم وعليهم قيس بن\nزهير فانهزمت بنو عبس وطلبتهم بنو تميم فوقف لهم عنترة ولحقتهم كبكبة من الخيل فحامى عنترة عن الناس فلم يصب مدبر وكان قيس بن زهير سيدهم فساءه ما صنع عنترة يومئذ فقال حين رجع والله ما حمى الناس إلا ابن السوداء وكان قيس أكولا فبلغ عنترة ما قال فقال يعرض به قصيدته التي يقول فيها\n(بكرت تخوفني الحتوف كأنني ... أصبحت عن عرض الحتوف بمعزل)\n(فأجبتها أن المنية منهل ... لا بد أن أسقى بكأس المنهل)\n(فاقني حياءك لا أبالك واعلمي ... أني امرؤ سأموت إن لم أقتل)\n(إن المنية لو تمثل مثلت ... مثلي إذا نزلوا بضنك المنزل)\n(إني امرؤ من خير عبس منصبا ... شطري وأحمي سائري بالمنصل)\n(وإذا الكتيبة أحجمت وتلاحظت ... ألفيت خيرا من معم مخول)\n(والخيل تعلم والفوارس أنني ... فرقت جمعهم بضربة فيصل)\n(إذ لا أبادر في المضيق فوارسي ... أو لا أوكل بالرعيل الأول)\n(إن يلحقوا أكرر وإن يستلحموا ... أشدد وإن يلفوا بضنك أنزل)\n(حين النزول يكون غاية مثلنا ... ويفر كل مضلل مستوهل)\n(والخيل ساهمة الوجوه كأنما ... تسقى فوارسها نقيع الحنظل)\n(ولقد أبيت على الطوى وأظله ... حتى أنال به كريم المأكل)\nروضه من الكامل غنت في الأربعة الأبيات الأول والبيت الثاني عريب خفيف رمل بالبنصر من رواية الهشامي وابن المعتز وأبي العبيس الحتوف ما عرض للإنسان من المكاره والمتالف عن عرض أي ما يعرض منها بمعزل أي في ناحية معتزلة عن ذلك ومنهل مورد وقوله فاقني حياءك أي احفظيه ولا تضيعيه والضنك الضيق يقول إن المنية لو خلقت مثالا لكانت في مثل صورتي والمنصب الأصل والمنصل السيف ويقال منصل أيضا بفتح الصاد وأحجمت كعت والكتيبة الجماعة إذا اجتمعت ولم تنتشر وتلاحظت نظرت من يقدم على العدو وأصل التلاحظ النظر من القوم بعضهم إلى بعض بمؤخر العين والفيصل الذي يفصل بين الناس وقوله لا أبادر في المضيق فوارسي أي لا أكون أول منهزم ولكني أكون حاميتهم والرعيل القطعة من كل شيء ويستلحموا يدركوا والمستلحم المدرك وأنشد الأصمعي\n(نجى علاجا وبشرا كل سلهبة ... واستلحم الموت أصحاب البراذين)\nساهمة ضامرة متغيرة قد كلح فوارسها لشدة الحرب وهولها وقوله ولقد أبيت على الطوى وأظله قال الأصمعي أبيت بالليل على الطوى وأظل بالنهار كذلك حتى أنال به كريم المأكل أي ما لا عيب فيه علي\nومثله قوله إنه ليأتي علي اليومان لا أذوقهما طعاما ولا شرابا أي لا أذوق فيهما والطوى خمص البطن يقال رجل طيان وطاوي البطن وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا ابن عائشة قال أنشد النبي قول عنترة\n(ولقد أبيت على الطوى وأظله ... حتى أنال به كريم المأكل)\nقال ما وصف لي أعرابي قط فأحببت أن أراه إلا عنترة","topic":"ذكر عنترة ونسبه وشيء من أخباره","topicNo":79,"sp":2,"spl":"كان حامي لواء بني عبس","song":1,"loc":1496},
{"id":"b79-4","bab":"الجزء 8","sec":"خبر إلحاقه إخوته لأمه بنسب قومه","page":"ج8 ص250","text":"أخبرني علي بن سليمان قال حدثنا أبو سعيد السكري عن محمد بن حبيب عن ابن الأعرابي وأبي عبيدة أن عنترة كان له إخوة من أمه فأحب عنترة أن يدعيهم قومه فأمر أخا له كان خيرهم في نفسه يقال له حنبل فقال له أرو مهرك اللبن ثم مر به علي عشاء فإذا قلت لكم ما شأن مهركم متخددا مهزولا ضامرا فاضرب بطنه بالسيف كأنك تريهم أنك قد غضبت مما قلت فمر عليهم فقال له يا حنبل ما شأن مهركم متخددا أعجر من اللبن فأهوى أخوه بالسيف إلى بطن مهره فضربه فظهر اللبن فقال في ذلك عنترة\n(أبني زبيبة ما لمهركم ... متخددا وبطونكم عجر)\n(ألكم بإيغال الوليد على ... أثر الشياه بشدة خبر)\nوهي قصيدة قال فاستلاطه نفر من قومه ونفاه آخرون ففي ذلك يقول عنترة\n(ألا يا دار عبلة بالطوي ... كرجع الوشم في كف الهدي)\nهي طويلة يعدد فيها بلاءه وآثاره عند قومه أخبرني عمي قال أخبرني الكراني عن النضر بن عمرو عن الهيثم بن عدي قال قيل لعنترة أنت أشجع العرب وأشدها قال لا قيل فبماذا شاع لك هذا في الناس قال كنت أقدم إذا رأيت الإقدام عزما وأحجم إذا رأيت الإحجام حزما ولا أدخل إلا موضعا أرى لي منه مخرجا وكنت أعتمد الضعيف الجبان فأضربه الضربة الهائلة يطير لها قلب الشجاع فأثني عليه فأقتله أخبرني حبيب بن نصر وأحمد بن عبد العزيز قالا حدثنا عمر بن شبة قال قال عمر بن الخطاب للحطيئة كيف كنتم في حربكم قال كنا ألف فارس حازم قال وكيف يكون ذلك قال كان قيس بن زهير فينا وكان حازما فكنا لا نعصيه وكان فارسنا عنترة فكنا نحمل إذا حمل ونحجم إذا أحجم وكان فينا الربيع بن زياد وكان ذا رأي فكنا نستشيره ولا نخالفه وكان فينا عروة بن الورد فكنا نأتم بشعره فكنا كما وصفت لك فقال عمر صدقت\nأخبرني علي بن سليمان قال حدثنا أبو سعيد السكري قال قال محمد بن حبيب عن ابن الأعرابي عن المفضل عن أبي عبيدة وابن الكلبي قالا","topic":"ذكر عنترة ونسبه وشيء من أخباره","topicNo":79,"sp":3,"spl":"خبر إلحاقه إخوته لأمه بنسب قومه — موته","loc":1497},
{"id":"b79-5","bab":"الجزء 8","sec":"موته","page":"ج8 ص252","text":"أغار عنترة على بني نبهان من طيىء فطرد لهم طريدة وهو شيخ كبير فجعل يرتجز وهو يطردها ويقول\n(آثار ظلمان بقاع محرب ... )\nال وكان زر بن جابر النبهاني في فتوة فرماه وقال خذها وأنا ابن سلمى فقطع مطاه فتحامل بالرمية حتى أتى أهله فقال وهو مجروح\n(وإن ابن سلمى عنده فاعلموا دمي ... وهيهات لا يرجى ابن سلمى ولا دمي)\n(يحل بأكناف الشعاب وينتمي ... مكان الثريا ليس بالمتهضم)\n(رماني ولم يدهش بأزرق لهذم ... عشية حلوا بين نعف ومخرم)\nال ابن الكلبي وكان الذي قتله يلقب بالأسد الرهيص وأما أبو عمرو الشيباني فذكر أنه غزا طيئا مع قومه فانهزمت عبس فخر عن فرسه ولم يقدر من الكبر أن يعود فيركب فدخل دغلا وأبصره ربيئة طيىء فنزل إليه وهاب أن يأخذه أسيرا فرماه وقتله\nوذكر أبو عبيدة أنه كان قد أسن واحتاج وعجز بكبر سنه عن الغارات وكان له على رجل من غطفان بكر فخرج يتقاضاه إياه فهاجت عليه ريح من صيف وهو بين شرج وناظرة فأصابته فقتلته قال أخبرني أبو خليفة عن محمد بن سلام قال كان عمرو بن معد يكرب يقول ما أبالي من لقيت من فرسان العرب ما لم يلقني حراها وهجيناها يعني بالحرين عامر بن الطفيل وعتيبة بن الحارث بن شهاب وبالعبدين عنترة والسليك بن السلكة هذه أخبار عنترة قد ذكرت فيها ما حضر","topic":"ذكر عنترة ونسبه وشيء من أخباره","topicNo":79,"sp":3,"spl":"خبر إلحاقه إخوته لأمه بنسب قومه — موته","loc":1498,"partial":1},
{"id":"b79-6","bab":"الجزء 8","sec":"نبذة عن ترجمة عبد قيس البرجمي","page":"ج8 ص254","text":"وأما عبد قيس بن خفاف البرجمي فإني لم أجد له خبرا أذكره إلا ما أخبرني به جعفر بن قدامة قال قرأت في كتاب لأبي عثمان المازني كان عبد قيس بن خفاف البرجمي أتى حاتم طيىء في دماء حملها عن قومه فأسلموه فيها وعجز عنها فقال والله لآتين من يحملها عني وكان شريفا شاعرا شجاعا فقدم على حاتم وقال له إنه وقعت بيني وبين قومي دماء فتواكلوها وإني حملتها في مالي وأهلي فقدمت مالي وأخرت أهلي وكنت أوثق الناس في نفسي فإن تحملتها فكم من حق قضيته وهم كفيته وإن حال دون ذلك حائل لم أذمم يومك ولم أنس غدك ثم أنشأ يقول\n(حملت دماء للبراجم جمة ... فجئتك لما أسلمتني البراجم)\n(وقالوا سفاها لم حملت دماءنا ... فقلت لهم يكفي الحمالة حاتم)\n(متى آته فيها يقل لي مرحبا ... وأهلا وسهلا أخطأتك الأشائم)\n(فيحملها عني وإن شئت زادني ... زيادة من حيزت إليه المكارم)\n(يعيش الندى ما عاش حاتم طيىء ... وإن مات قامت للسخاء مآتم)\n(ينادين مات الجود معك فلا نرى ... مجيبا له ما حام في الجو حائم)\n(وقال رجال أنهب العام ماله ... فقلت لهم إني بذلك عالم)\n(ولكنه يعطى من اموال طيىء ... إذا حلق المال الحقوق اللوازم)\n(فيعطي التي فيها الغنى وكأنه لتصغيره تلك العطية جارم ... )\n(بذلك أوصاه عدي وحشرج ... وسعد وعبد الله تلك القماقم)\nقال له حاتم إني كنت لأحب أن يأتيني مثلك من قومك وهذا\nمرباعي من الغارة على بني تميم فخذه وافرا فإن وفى بالحمالة وإلا أكملتها لك وهي مائتا بعير سوى نيبها وفصالها مع أني لا أحب أن تؤبس قومك بأموالهم فضحك أبو جبيل وقال لكم ما أخذتم منا ولنا ما أخذنا منكم وأي بعير دفعته إلي وليس ذنبه في يد صاحبه فأنت منه بريء فأخذها وزاده مائة بعير وانصرف راجعا إلى قومه فقال حاتم\n(أتاني البرجمي أبو جبيل ... لهم في حمالته طويل)\n(فقلت له خذ المرباع منها ... فإني لست أرضى بالقليل)\n(على حال ولا عودت نفسي ... على علاتها علل البخيل)\n(فخذها إنها مائتا بعير ... سوى الناب الرذية والفصيل)\n(ولا من عليك بها فإني ... رأيت المن بزري بالجميل)\n(فآب البرجمي وما عليه ... من اعباء الحمالة من فتيل)\n(يجر الذيل ينفض مذرويه ... خفيف الظهر من حمل ثقيل)","topic":"ذكر عنترة ونسبه وشيء من أخباره","topicNo":79,"sp":4,"spl":"نبذة عن ترجمة عبد قيس البرجمي","loc":1499,"partial":1},
{"id":"b80-1","bab":"الجزء 8","sec":"ذكر أبي دلف ونسبه وأخباره","page":"ج8 ص256","text":"هو القاسم بن عيسى بن إدريس أحد بني عجل بن لجيم بن صعب بن علي بن بكر بن وائل ومحله في الشجاعة وعلو المحل عند الخلفاء وعظم الغناء في المشاهد وحسن الأدب وجودة الشعر محل ليس لكبير أحد من نظرائه وذكر ذلك أجمع مما لا معنى له لطوله وفي هذا القدر من أخباره مقنع وله أشعار جياد وصنعة كثيرة حسنة فمن جيد شعره وله فيه صنعة قوله\n(بنفسي يا جنان وأنت مني ... محل الروح من جسد الجبان)\n(ولو أني أقول مكان نفسي ... خشيت عليك بادرة الزمان)\n(لإقدامي إذا ما الخيل حامت ... وهاب كماتها حر الطعان)\nله فيه لحن وهذا البيت الأول أخذه من كلام إبراهيم النظام أخبرني به علي بن سليمان الأخفش قال حدثني محمد بن الحسن بن الحرون قال لقي إبراهيم النظام غلاما حسن الوجه فاستحسنه وأراد كلامه فعارضه\nثم قال له يا غلام إنك لولا ما سبق من قول الحكماء مما جعلوا به السبيل لمثلي إلى مثلك في قولهم لا ينبغي لأحد أن يكبر عن أن يسأل كما أنه لا ينبغي لأحد أن يصغر عن أن يقول لما أنبت إلى مخاطبتك ولا انشرح صدري لمحادثتك لكنه سبب الإخاء وعقد المودة ومحلك من قلبي محل الروح من جسد الجبان فقال له الغلام وهو لا يعرفه لئن قلت ذلك أيها الرجل لقد قال أستاذنا إبراهيم النظام الطبائع تجاذب ما شاكلها بالمجانسة وتميل إلى ما قاربها بالموافقة وكياني مائل إلى كيانك بكليتي ولو كان الذي انطوى عليه عرضا لم أعتد به ودا ولكنه جوهر جسمي فبقاؤه ببقاء النفس وعدمه بعدمها وأقول كما قال الهذلي\n(فتيقني أن قد كلفت بكم ... ثم افعلي ما شئت عن علم)\nقال له النظام إنما كلمتك بما سمعت وأنت عندي غلام مستحسن ولو علمت أن محلك مثل محل معمر وطبقته في الجدل لما تعرضت لك قال أبو الحسن ومن هذا أخذ أبو دلف قوله\n(أحبك يا جنان وأنت مني ... محل الروح من جسد الجبان)\nمن جيد شعره وله فيه صنعة قوله\n(في كل يوم أرى بيضاء طالعة ... كأنما أنبتت في ناظر البصر)\n(لئن قصصتك بالمقراض عن بصري ... لما قطعتك عن همي وعن فكري)","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":0,"spl":"ذكر أبي دلف ونسبه وأخباره — حارب الشراة وهو بالسرادن","song":2,"loc":1500},
{"id":"b80-2","bab":"الجزء 8","sec":"حارب الشراة وهو بالسرادن","page":"ج8 ص257","text":"أخبرني علي بن عبد العزيز الكاتب قال حدثني أبي قال سمعت عبد العزيز بن دلف بن أبي دلف يقول حدثتني ظبية جارية أبي قالت إني لمعه ليلة بالسرادن وهو جالس يشرب معي وعليه ثياب ممسكة إذ أتاه الصريح بطروق الشراة أطراف عسكره فلبس الجوشن ومضى فقتل وأسر وانصرف إلي في آخر الليل وهو يغني قالت والشعر له\n(ليلتي بالسرادن ... كللت بالمحاسن)\n(وجوار أوانس ... كالظباء الشوادن)\n(بدلت بالممسكات ... ادراع الجواشن)\nالشعر لأبي دلف والغناء له رمل بالسبابة في مجرى البنصر","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":0,"spl":"ذكر أبي دلف ونسبه وأخباره — حارب الشراة وهو بالسرادن","song":1,"loc":1501},
{"id":"b80-4","bab":"الجزء 8","sec":"خرج مع الإفشين لحرب بابك — أحمد بن أبي دواد ينكر عليه غناءه","page":"ج8 ص258 – ج8 ص259","text":"وقال أحمد بن أبي طاهر كان أبو دلف القاسم بن عيسى في جملة من كان مع الإفشين خيذر بن كاووس لما خرج لمحاربة بابك ثم تنكر له فوجه يوما بمن جاء به ليقتله وبلغ المعتصم الخبر فبعث إليه بأحمد بن\nأبي دواد وقال له أدركه وما أراك تلحقه فاحتل في خلاصه منه كيف شئت قال ابن أبي دواد فمضيت ركضا حتى وافيته فإذا أبو دلف واقف بين يديه وقد أخذ بيديه غلامان له تركيان فرميت بنفسي على البساط وكنت إذا جئته دعا لي بمصلى فقال لي سبحان الله ما حملك على هذا قلت أنت أجلستني هذا المجلس ثم كلمته في القاسم وسألته فيه وخضعت له فجعل لا يزداد إلا غلظة فلما رأيت ذلك قلت هذا عبد وقد أغرقت في الرفق به فلم ينفع وليس إلا أخذه بالرهبة والصدق فقمت فقلت كم تراك قدرت تقتل أولياء أمير المؤمنين واحدا بعد واحد وتخالف أمره في قائد بعد قائد قد حملت إليك هذه الرسالة عن أمير المؤمنين فهات الجواب قال فذل حتى لصق بالأرض وبان لي الاضطراب فيه فلما رأيت ذلك نهضت إلى أبي دلف وأخذت بيده وقلت له قد أخذته بأمر أمير المؤمنين فقال لا تفعل يا أبا عبد الله فقلت قد فعلت وأخرجت القاسم فحملته على دابة ووافيت المعتصم فلما بصر بي قال بك يا ابا عبد الله وريت زنادي ثم رد علي خبري مع الإفشين حدسا بظنه ما أخطأ فيه حرفا ثم سألني عما ذكره لي وهو كما قال فأخبرته أنه لم يخطىء حرفا\nوقال علي بن محمد حدثني جدي قال كان أحمد بن أبي دواد ينكر أمر الغناء إنكارا شديدا فأعلمه المعتصم أن صديقه ابا دلف يغني فقال ما أراه مع عقله يفعل ذلك فستر احمد بن أبي دواد في موضع وأحضر ابا دلف وأمره أن يغني ففعل ذلك وأطال ثم خرج احمد بن أبي دواد عليه من موضعه والكراهة ظاهرة في وجهه فلما رآه\nأحمد قال له سوءة لهذا من فعل بعد هذه السن وهذا المحل تضع نفسك كما أرى فخجل ابو دلف وتشور وقال إنهم أكرهوني على ذلك فقال هبهم أكرهوك على الغناء أفأكرهوك على الإحسان والإصابة قال علي وحدثني جدي أن سبب منادمته للمعتصم أنه كان نديما للواثق وكان ابو دلف قد وصف للمعتصم فأحب أن يسمعه وسأل الواثق عنه فقال يا أمير المؤمنين أنا على الفصد غدا وهم عندي فقال له المعتصم أحب ألا تخفي علي شيئا من خبركم وفصد الواثق فأتاه أبو دلف وأتته رسل الخليفة بالهدايا وأعلمهم الواثق حضور أبي دلف عنده فلم يلبث أن أقبل الخدم يقولون قد جاء الخليفة فقام الواثق وكل من عنده حتى تلقوه حين برز من الدهليز إلى الصحن فجاء حتى جلس وأمر بندماء الواثق فردوا إلى مجالسهم قال حمدون وخنست عن مجلسي الذي كنت فيه لحداثتي فنظر المعتصم إلى مكاني خاليا فسأل عن صاحبه فسميت له فأمر بإحضاري فرجعت إلى مكاني وأمر بأن يؤتى برطل من شرابه فأتي به فأقبل على أبي دلف فقال له يا قاسم غن أمير المؤمنين صوتا فما حصر ولا تثاقل وقال أغني أمير المؤمنين صوتا بعينه أو ما اخترته قال بل غن صنعتك في شعر جرير\n(بان الخليط برامتين فودعوا ... )\nفغناه إياه فقال المعتصم أحسن أحسن ثلاثا وشرب الرطل ولم يزل يستعيده ويشرب عليه حتى والى بين سبعة أرطال ثم دعا بحمار فركبه وأمر أبا دلف أن ينصرف معه وأمرني بالانصراف معهما فخرجت أسعى مع ركابه فثبت في ندمائه من ذلك اليوم وأمر لأبي دلف بعشرين ألف دينار","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":1,"spl":"خرج مع الإفشين لحرب بابك — أحمد بن أبي دواد ينكر عليه غناءه","loc":1502,"partialRef":{"sid":"b58-7","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b80-5","bab":"الجزء 8","sec":"نسبة الصوت الذي غناه ابو دلف","page":"ج8 ص261","text":"\n(بان الخليط برامتين فودعوا ... أوكلما اعتزموا لبين تجزع)\n(كيف العزاء ولم أجد مذ غبتم ... قلبا يقر ولا شرابا ينقع)\nروضه من الكامل الشعر لجرير والغناء لأبي دلف ثاني ثقيل بالبنصر عن الهشامي وعمرو بن بانة أخبرني الحسين بن يحيى عن حماد عن أبيه قال كان جعفر بن أبي جعفر المنصور المعروف بابن الكردية يستخف مطيع بن إياس وكان منقطعا إليه وله منه منزلة حسنة فذكر له مطيع بن إياس حمادا الراوية وكان مطرحا مجفوا في أيامهم فقال له دعني فإن دولتي كانت في بني أمية وما لي عند هؤلاء خير فأبى مطيع إلا الذهاب به إليه فاستعار سوادا وسيفا ثم أتاه فدخل على جعفر فسلم عليه وجلس فقال له جعفر أنشدني فقال لمن أيها الأمير قال لجرير قال حماد فسلخ الله شعره أجمع من قلبي إلا قوله\n(بان الخليط برامتين فودعوا ... )\nاندفعت أنشده إياه حتى بلغت إلى قوله\n(وتقول بوزع قد دببت على العصا ... هلا هزئت بغيرنا يا بوزع)\nال حماد فقال لي جعفر أعد هذا البيت فأعدته فقال إيش هو بوزع قلت اسم امرأة قال امرأة اسمها بوزع هو بريء من الله ورسوله ومن العباس بن عبد المطلب إن كانت بوزع إلا غولا من الغيلان تركتني والله يا هذا لا أنام الليل من فزع بوزع يا غلمان قفاه قال فصفعت والله حتى لم أدر أين أنا ثم قال جروا برجله فجروا برجلي حتى أخرجت من بين يديه وقد تخرق السواد وانكسر جفن السيف ولقيت شرا عظيما مما جرى من ذلك وكان أغلظ من ذلك علي غرامتي السواد والسيف فلما انصرف إلي مطيع جعل يتوجع لي فقلت له ألم أخبرك أني لا أصيب منهم خيرا وأن حظي قد مضى مع من مضى من بني أمية رجع الحديث إلى اخبار أبي دلف وكان أبو دلف جوادا ممدحا وفيه يقول علي بن جبلة\n(إنما الدنيا أبو دلف ... بين مغزاه ومحتضره)\n(وإذا ولى أبو دلف ... ولت الدنيا على أثره)\nهي من جيد شعره وحسن مدائحه وفيها يقول\n(ذاد ورد الغي عن صدره ... وارعوى واللهو من وطره)\n(ندمي أن الشباب مضى ... لم أبلغه مدى أشره)\n(حسرت عني بشاشته ... وذوى المحمود من ثمره)\n(ودم أهدرت من رشأ ... لم يرد عقلا على هدره)\n(فأتت دون الصبا هنة ... قلبت فوقي على وتره)\n(دع جدا قحطان أو مضر ... في يمانيه وفي مضره)\n(وامتدح من وائل رجلا ... عصر الآفاق من عصره)\n(المنايا في مقانبه ... والعطايا في ذرا حجره)\n(ملك تندى أنامله ... كانبلاج النوء عن مطره)\n(مستهل عن مواهبه ... كابتسام الروض عن زهره)\n(جبل عزت مناكبه ... أمنت عدنان في نفره)\n(إنما الدنيا أبو دلف ... بين مغزاه ومحتضره)\n(فإذا ولى أبو دلف ... ولت الدنيا على أثره)\n(كل من في الأرض من عرب ... بين باديه إلى حضره)\n(مستعير منه مكرمة ... يكتسيها يوم مفتخره)\nهذان البيتان هما اللذان احفظا المأمون على علي بن جبلة حتى سل لسانه من قفاه وقوله في أبي دلف أيضا\n(أنت الذي تنزل الأيام منزلها ... وتنقل الدهر من حال إلى حال)\n(وما مددت مدى طرف إلى أحد ... إلا قضيت بأرزاق وآجال)\nسنذكر ذلك في موضعه من أخبار علي بن جبلة إن شاء الله تعالى\nإذ كان القصد ها هنا أمر أبي دلف","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":2,"spl":"نسبة الصوت الذي غناه ابو دلف","song":1,"loc":1503,"partialRef":{"sid":"b58-7","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b80-6","bab":"الجزء 8","sec":"أخبار عن شدة كرمه","page":"ج8 ص264","text":"أخبرني أحمد بن عبيد الله بن عمار قال كنا عند أبي العباس المبرد يوما وعنده فتى من ولد أبي البختري وهب بن وهب القاضي أمرد حسن الوجه وفتى من ولد أبي دلف العجلي شبيه به في الجمال فقال المبرد لابن أبي البختري أعرف لجدك قصة ظريفة من الكرم حسنة لم يسبق إليها قال وما هي قال دعي رجل من أهل الأدب إلى بعض المواضع فسقوه نبيذا غير الذي كانوا يشربون منه فقال فيهم\n(نبيذان في مجلس واحد ... لإيثار مثر على مقتر)\n(فلو كان فعلك ذا في الطعام ... لزمت قياسك في المسكر)\n(ولو كنت تطلب شأو الكرام ... صنعت صنيع أبي البختري)\n(تتبع إخوانه في البلاد ... فأغنى المقل عن المكثر)\nبلغت الأبيات أبا البختري فبعث إليه بثلثمائة دينار قال ابن عمار فقلت قد فعل جد هذا الفتى في هذا المعنى ما هو أحسن من هذا قال وما فعل قلت بلغه أن رجلا افتقر بعد ثروة فقالت له امرأته افترض في الجند فقال\n(إليك عني فقد كلفتني شططا ... حمل السلاح وقيل الدارعين قف)\n(تمشي المنايا إلى غيري فأكرهها ... )\n(فكيف أمشي إليها عاري الكتف ... )\n(حسبت أن نفاد المال غيرني ... وأن روحي في جنبي أبي دلف)\nأحضره أبو دلف ثم قال له كم أملت امرأتك أن يكون رزقك قال مائة دينار قال وكم أملت أن تعيش قال عشرين سنة قال فذلك لك علي\nعلى ما أملت امرأتك في مالنا دون مال السلطان وأمر بإعطائه إياه قال فرأيت وجه ابن أبي دلف يتهلل وانكسر ابن أبي البختري انكسارا شديدا أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد المبرد قال أخبرني علي بن القاسم قال قال علي بن جبلة زرت أبا دلف بالجبل فكان يظهر من إكرامي وبري والتحفي بي أمرا مفرطا حتى تأخرت عنه حينا حياء فبعث إلي معقل بن عيسى فقال يقول لك الأمير قد انقطعت عني وأحسبك استقللت بري بك فلا يغضبنك ذلك فسأزيد فيه حتى ترضى فقلت والله ما قطعني إلا إفراطه في البر وكتبت إليه\n(هجرتك لم أهجرك من كفر نعمة ... وهل يرتجى نيل الزيادة بالكفر)\n(ولكنني لما أتيتك زائرا ... فأفرطت في بري عجزت عن الشكر)\n(فم الان لا آتيك إلا مسلما ... أزورك في الشهرين يوما أو الشهر)\n(فإن زدتني برا تزايدت جفوة ... ولم تلقني طول الحياة إلى الحشر)\nلما قرأها معقل استحسنها جدا وقال أحسنت والله أما إن الأمير لتعجبه هذه المعاني فلما أوصلها إلى أبي دلف قال قاتله الله ما اشعره وأدق معانيه فأعجبته فأجابني لوقته وكان حسن البديهة حاضر الجواب\n(ألا رب ضيف طارق قد بسطته ... وآنسته قبل الضيافة بالبشر)\n(أتاني يرجيني فما حال دونه ... ودون القرى والعرف ما نائلي ستري)\n(وجدت له فضلا علي بقصده ... إلي وبرا زاد فيه على بري)\n(فزودته مالا يقل بقاؤه ... وزودني مدحا يدوم على الدهر)\nحذف\nقال وبعث إلي بالأبيات مع وصيف له وبعث معه إلي بألف دينار فقلت\n(حينئذ إنما الدنيا أبو دلف ... )\nالأبيات أخبرني علي بن سليمان قال أخبرنا المبرد قال أخبرني إبراهيم بن خلف قال بينا أبو دلف يسير مع معقل وهما إذ ذاك بالعراق إذ مرا بقصر فأشرفت منه جاريتان فقالت إحداهما للأخرى هذا أبو دلف الذي يقول فيه الشاعر\n(إنما الدنيا أبو دلف ... )\nقالت الأخرى أوهذا قد والله كنت أحب أن أراه منذ سمعت ما قيل فيه فالتفت أبو دلف إلى معقل فقال ما أنصفنا علي بن جبلة ولا وفيناه حقه إن ذلك لمن كبير همي وكان أعطاه ألف دينار","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":3,"spl":"أخبار عن شدة كرمه","loc":1504,"partialRef":{"sid":"b80-5","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b80-7","bab":"الجزء 8","sec":"صوت من المائة المختارة من رواية علي بن يحيى","page":"ج8 ص266","text":"(أما القطاة فإني سوف أنعتها ... نعتا يوافق منها بعض ما فيها)\n(سكاء مخطوبة في ريشها طرق ... صهب قوادمها كدر خوافيها)\nروضه من البسيط والشعر مختلف في قائله ينسب إلى أوس بن غلفاء الهجيمي وإلى مزاحم العقيلي وإلى العباس بن يزيد بن الأسود الكندي وإلى العجير السلولي وإلى عمرو بن عقيل بن الحجاج الهجيمي وهو أصح الأقوال\nرواه ثعلب عن أبي نصر عن الأصمعي وعلى أن في هذه الروايات أبياتا ليست مما يغنى فيه وأبياتا ليست في الرواية وقد روي أيضا أن الجماعة المذكورة تساجلوا هذه الأبيات فقال كل واحد منهم بعضا وأخبار ذلك وما يحتاج إليه في شرح غريبه يذكر بعد هذا والغناء في اللحن المختار لمعبد خفيف ثقيل أول بالوسطى وفي هذين البيتين مع أبيات أخر من القصيدة اشتراك كثير بين المغنين يتقدم بعض الأبيات فيه بعضا ويتأخر بعضها عن بعض على اختلاف تقديم ذلك وتأخيره والأبيات تكتب ها هنا ثم تنسب صنعة كل صانع في شيء منها إليه وهي بعد البيتين الأولين إذ كانا قد مضيا واستغني عن إعادتهما\n(لما تبدى لها طارت وقد علمت ... أن قد أظل وأن الحي غاشيها)\n(تشتق في حيث لم تبعد مصعدة ... ولم تصوب إلى أدنى مهاويها)\n(تنتاش صفراء مطروقا بقيتها ... قد كاد يأزي عن الدعموص آزيها)\n(ما هاج عينك أم قد كاد يبكيها ... من رسم دار كسحق البرد باقيها)\n(فلا غنيمة توفي بالذي وعدت ... ولا فؤادك حتى الموت ناسيها)\nبط مولى عبد الله بن جعفر خفيف ثقيل بإطلاق الوتر في مجرى البنصر من رواية إسحاق في أما القطاة والذي بعده وتنتاش صفراء خفيف ثقيل بالبنصر عن عمرو ولإبراهيم الموصلي في لما تبدى لها وأما القطاة خفيف رمل عن الهشامي ولعمر الوادي في أما القطاة ثقيل بالوسطى ولابن جامع في لما تبدى لها وبعده أما القطاة خفيف رمل ولسياط في الأول والثاني وبعدهما تشتق في حيث لم تبعد خفيف ثقيل بالبنصر ومن الناس من ينسب\nلحنه إلى عمر الوادي وينسب لحن عمر إليه ولعلويه في أما القطاة والذي بعده رمل هو من صدور أغانيه ومقدمها فجميع ما وجدته في هذه الأبيات من الصنعة أحد عشر لحنا","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":4,"spl":"صوت من المائة المختارة من رواية علي بن يحيى","loc":1505},
{"id":"b80-8","bab":"الجزء 8","sec":"أقوال بعض الشعراء في وصف القطاة","page":"ج8 ص268","text":"فأما خبر هذا الشعر فإن ابن الكلبي زعم أن السبب فيه أن العجير السلولي وأوس بن غلفاء الهجيمي ومزاحما العقيلي والعباس بن يزيد بن الأسود الكندي وحميد بن ثور الهلالي اجتمعوا فتفاخروا بأشعارهم وتناشدوا وادعى كل واحد منهم أنه أشعر من صاحبه ومر بهم سرب قطا فقال أحدهم تعالوا حتى نصف القطا ثم نتحاكم إلى من نتراضى به فأينا كان أحسن وصفا لها غلب أصحابه فتراهنوا على ذلك فقال أوس بن غلفاء الأبيات المذكورة وهي أما القطاة وقل حميد أبياتا وصف ناقته فيها ثم خرج إلى صفة القطاة فقال\n(كما انصلتت كدراء تسقي فراخها ... بشمظة رفها والمياه شعوب)\n(غدت لم تباعد في السماء ودونها ... إذا ما علت أهوية وصبوب)\n(قرينة سبع إن تواترن مرة ... ضربن فصفت أرؤس وجنوب)\n(فجاءت وما جاء القطا ثم قلصت ... بمفحصها والواردات تنوب)\n(وجاءت ومسقاها الذي وردت به ... إلى الصدر مشدود العصام كتيب)\n(تبادر أطفالا مساكين دونها ... فلا لا تخطاه العيون رغيب)\n(وصفن لها مزنا بأرض تنوفة ... فما هي إلا نهلة وتؤوب)\nقال العباس بن يزيد بن الأسود هكذا ذكر ابن الكلبي وغيره يرويها لبعض بني مرة\n(حذاء مدبرة سكاء مقبلة ... للماء في النحر منها نوطة عجب)\n(تسقي أزيغب ترويه مجاجتها ... وذاك من ظمأة من ظمئها شرب)\n(منهرت الشدق لم تنبت قوادمه ... في حاجب العين من تسبيده زبب)\n(تدعو القطا بقصير الخطو ليس له ... قدام منحرها ريش ولا زغب)\n(تدعو القطا وبه تدعى إذا انتسبت ... يا صدقها حين تدعوه وتنتسب)\nقال مزاحم العقيلي\n(أذلك أم كدرية هاج وردها ... من القيظ يوم واقد وسموم)\n(غدت كنواة القسب لا مضمحلة ... وناة ولا عجلى الفتور سؤوم)\n(تواشك رجع المنكبين وترتمي ... إلى كلكل للهاديات قدوم)\n(فما انخفضت حتى رأت ما يسرها ... وفيء الضحى قد مال فهو ذميم)\n(أباطح وانتصت على حيث تستقى ... بها شرك للواردات مقيم)\n(سقتها سيول المدجنات فأصبحت ... علاجيم تجري مرة وتدوم)\n(فلما استقت من بارد الماء وانجلى ... عن النفس منها لوحة وهموم)\n(دعت باسمها حين استقت فاستقلها ... قوادم حجن ريشهن مليم)\n(بجوز كحق الهاجرية زانه ... بأطراف عود الفارس وشوم)\nعني حق الطيب شبه حوصلتها بها والوشوم يعني الشية التي في صدرها\n(لتسقي زغبا بالتنوفة لم يكن ... خلاف مولاها لهن حميم)\n(ترائك بالأرض الفلاة ومن بدع ... بمنزلها الأولاد فهو مليم)\n(إذا استقبلتها الريح طمت رفيقة ... وهن بمهوى كالكرات جثوم)\n(يراطن وقصاء القفا وحشة الشوى ... بدعوى القطا لحن لهن قديم)\n(فبتن قريرات العيون وقد جرى ... عليهن شرب فاستقين منيم)\n(صبيب سقاء نيط قد بركت به ... معاودة سقي الفراخ رؤوم)\nقال العجير فيما روى ابن الكلبي وقد تروى لغيره\n(سأغلب والسماء ومن بناها ... قطاة مزاحم ومن انتحاها)\n(قطاة مزاحم وأبي المثنى ... على حوزية صلب شواها)\n(غدت كالقطرة السفواء تهوي ... أمام مجلجل زجل نفاها)\n(تكفأ كالجمانة لا تبالي ... أبالموماة أضحت أم سواها)\n(نبت منها العجيزة فاحزألت ... ونبس للتقتل منكباها)\n(كأن كعوبها أطراف نبل ... كساها الرازقية من براها)\nال واحتكموا إلى ليلى الأخيلية فحكمن لأوس بن غلفاء وأخبرني أحمد بن عبيد الله بن عمار قال حدثنا يعقوب بن إسرائيل عن قعنب بن محرز الباهلي قال حدثني رجل عن أبي عبيدة قال أخبرنا حميد بن ثور والعجير السلولي ومزاحم العقيلي وأوس بن غلفاء الهجيمي أنهم تحاكموا إلى ليلى الأخيلية لما وصفوا القطاة أيهم أحسن وصفا لها فقالت\n(ألا كل ما قال الرواة وأنشدوا ... بها غير ما قال السلولي بهرج)\nحكمت له فقال حميد بن ثور يهجوها\n(كأنك ورهاء العنانين بغلة ... رأت حصنا فعارضتهن تشحج)\nووجدت هذه الحكاية عن أبي عبيدة مذكورة عن دماذ عنه وأنه سأله عن أبيات العجير فأنشده\n(تجوب الدجى سكاء من دون فرخها ... بمطلى أريك نفنف وسهوب)\n(فجاءت وقرن الشمس باد كأنه ... هجان بصحراء الخبيب شبوب)\n(لتسقي أفراخا لها قد تبللت ... حلاقيم أسماط لها وقلوب)\n(قصار الخطا زغب الرؤوس كأنها ... كرات تلظى مرة وتلوب)\nفأما ما ذكرت من رواية ثعلب في الأبيات التي فيها الغناء فإنه أنشدها عن أبي حاتم عن الأصمعي أن أبا الحضير أنشده لعمرو بن عقيل بن الحجاج الهجيمي\n(أما القطاة فإني سوف أنعتها ... نعتا يوافق نعتي بعض ما فيها)","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":5,"spl":"أقوال بعض الشعراء في وصف القطاة","loc":1506},
{"id":"b80-9","bab":"الجزء 8","sec":"أقوال بعض الشعراء في وصف القطاة","page":"ج8 ص268","text":"(صفراء مطروقة في ريشها خطب ... صفر قوادمها سود خوافيها)\n(منقارها كنواة القسب قلمها ... بمبرد حاذق الكفين يبريها)\n(تمشي كمشي فتاة الحي مسرعة ... حذار قوم إلى ستر يواريها)\nال الأصمعي مطروقة يعني أن ريشها بعضه فوق بعض والخطب لون الرماد يقال للمشبه به أخطب\n(تنتاش صفراء مطروقا بقيتها ... قد كاد يأزي عن الدعموص آزيها)\nنتاش تتناويل بقية من الماء والمطروق الماء الذي قد خالطه البول وقوله يأزي أي يقل عن الدعموص فيخرج منه لقلته والدعموص الصغير من الضفادع وجمعه دعاميص\n(تسقي رذيين بالموماة قوتهما ... في ثغرة النحر من أعلى تراقيها)\nلرذي الساقط من الضعف يعني فرخيها\n(كأن هيدبة من فوق جؤجئها ... أو جرو حنظلة لم يعد راميها)\nجرو الحنظل صغاره وقوله لم يعد من العداء أي لم يعد عليها فيكسرها\n(تشتق من حيث لم تبعد مصعدة ... ولم تصوب إلى أدنى مهاويها)\n(حتى إذا استأنسا للوقت واحتضرت ... توجسا الوحي منها عند غاشيها)\nيروى حتى إذا استأنسا للصوت وتوجسا تسمعا وحيها أي سرعة طيرانها وغاشيها أي حين تغشاهما وتنتهي إليهما\n(ترفعا عن شؤون غير ذاكية ... على لديدي أعالي المهد أدحيها)\nلذاكية الشديدة الحركة والمهد أفحوصها ولديداه جانباه\n(مدا إليها بأفواه مزينة ... صعدا ليستنزلا الأرزاق من فيها)\n(كأنها حين مداها لجنأتها ... طلى بواطنها بالورس طاليها)\nنأتها أي جنأت عليهما بصدرها لتزقهما\n(حثلين رضا رفاض البيض عن زغب ... ورق أسافلها بيض أعاليها)\nثلين دقيقين ضاويين رضا كسرا والرفاض ما ارفض وتفرق\n(ترأدا حين قاما ثمت احتطبا ... على نحائف منآد محانيها)\nرأدا تثنيا واحتطبا دنوا والمنآد المنعطف ومحانيها حيث انحنت\n(تكاد من لينها تنآد أسؤقها ... تأود الربل لم تعرم نواميها)\nعرم تشتد ونواميها أعاليها\n(لا أشتكي نوشة الأيام من ورقي ... إلا إلى من أرى أن سوف يشكيها)\n(لدلهم مأثرات قد عددن له ... إن المآثر معدود مساعيها)\n(تنمي به في بني لأي دعائمها ... ومن جمانة لم تخضع سواريها)\n(بنى له في بيوت المجد والده ... وليس من ليس يبنيها كبانيها)\nأنشدني هذه الأبيات الحسن بن محمد الضبعي الشاعر المعروف بابن الحداد قال وجدتها بخط محمد بن داود بن الجراح عن إسماعيل بن يونس الشيعي شيخنا رحمه الله عن أخيه عن أبي محلم مثل رواية ثعلب وزاد فيها قال أبو محلم جمانة بن جرير بن عبد ثعلبة بن سعد بن الهجيم وهم أخوال دلهم هذا الممدوح ودلهم من بني لأي ثم من بني يزيد بن هلال بن بذل بن عمرو بن الهيثم وكان أحد الشجعان وهو قتل الضحاك بن قيس الخارجي\nبيده مع مروان بن محمد ليلة كفرتوثا","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":6,"spl":"أقوال بعض الشعراء في وصف القطاة — صوت من المائة المختارة","loc":1507},
{"id":"b80-10","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص275","text":"عن علي بن يحيى\n(أيها القلب لا أراك تفيق ... طالما قد تعلقتك العلوق)\n(من يكن من هوى حبيب قريبا ... فأنا النازح البعيد السحيق)\n(قدر الحب بيننا فالتقينا ... وكلانا إلى اللقاء مشوق)\nلشعر لعمر بن أبي ربيعة وقد مضت أخباره والغناء في اللحن المختار لبابويه الكوفي خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه لابن سريج ثقيل أول بالخنصر في مجرى البنصر عن إسحاق وفيه ايضا لمخارق خفيف ثقيل بالوسطى عن الهشامي وفيه لعلويه رمل بالبنصر عنه وعن الهشامي وبابويه رجل من أهل الكوفة قليل الصنعة ليس ممن خدم الخلفاء ولا الأكابر ولا أعلم له خبرا فأذكره صوت من المائة المختارة\n(من لقلب أضحى بكم مستهاما ... خائفا للوشاة يخفي الكلاما)\nن طرفي رسول نفسي ونفسي ... عن فؤادي تقرا عليك السلاما\nم يقع إلينا قائل الشعر فنذكر خبره والغناء لرياض جارية أبي حماد\nخفيف ثقيل بالوسطى وكان أبو حماد هذا أحد القواد الخراسانية ومن أولاد الدعاة وكان يعاشر إسحاق ويبره ويهاديه فأخذت رياض عنه غناء كثيرا وكانت محسنة ضاربة كثيرة الرواية وأحب إسحاق أن ينوه باسمها ويرفع من شأنها فذكر صنعتها في هذا الصوت فيما اختاره للواثق قضاء لحق مولاها وليس فيما قلته في هذا لأن الصوت غير مختار ولكن في الغناء ما هو أفضل منه بكثير ولم يذكره وقد فعل ذلك بجماعة ممن كان يوده ويتعصب له مثل متيم وأبي دلف وغيرهم ومن يعلم هذه الصناعة يعرف صحة ما قلناه وماتت رياض هذه مملوكة لمولاها لم تخرج من يده ولا شهرت ولا روي لها خبر","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":6,"spl":"أقوال بعض الشعراء في وصف القطاة — صوت من المائة المختارة","loc":1508},
{"id":"b80-11","bab":"الجزء 8","sec":"صوت من المائة المختارة عن علي بن يحيى","page":"ج8 ص276","text":"(راح صحبي وعاود القلب داء ... من حبيب طلابه لي عناء)\n(حسن الرأي والمواعيد لا يلفى ... لشيء مما يقول وفاء)\n(من تعزى عمن يحب فإني ... ليس لي ما حييت عنه عزاء)\n(أم عثمان قد قتلت قتيلا ... عمد عين قتلته لا خطاء)\nم يقع إلينا قائل هذا الشعر فنذكره والغناء لنافع بن طنبورة ولحنه المختار خفيف ثقيل أول بالسبابة في مجرى الوسطى وفي هذا الشعر لحن لعبد الله بن طاهر ثاني ثقيل من جيد صنعته وكان نسبه إلى لميس جاريته وله خبر سنذكره في أخباره إذا انتهينا وكان نافع بن طنبورة يكنى أبا عبد الله مغن محسن من أهل المدينة حسن الوجه نظيف الثوب يلقب نقش الغضار لحسن وجهه وجعلته جميلة في المرتبة لما اجتمع المغنون إليها بعد نافع وبديح وقبل مالك بن أبي السمح وغناها يومئذ\n(يا طول ليلي وبت لم أنم ... وسادي الهم مبطن سقمي)\n(أن قمت يوما على البلاط وأبصرت ... رقاشا فليت له أقم)\nقالت جميلة أحسنت والله يا نقش الغضار ويا حلو اللسان ويا حسن البيان ولم يفارق ابن طنبورة الحجاز ولا خدم الخلفاء ولا انتجعهم بصنعة فخمل ذكره صوت من المائة المختارة عن علي بن يحيى عتق الفؤاد من الصبا ... ومن السفاهة والعلاق وحططت رحلي عن قلوص ... الغي في قلص عتاق ورفعت فضل إزاري المجرور ... عن قدمي وساقي وكففت غرب النفس حتى ... ما تتوق إلى متاق\nلشعر لسعيد بن عبد الرحمن بن حسان بن ثابت والغناء لابن عباد الكاتب ولحنه المختار من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه لإبراهيم خفيف ثقيل وقيل إنه لغيره","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":7,"spl":"صوت من المائة المختارة عن علي بن يحيى","loc":1509},
{"id":"b80-12","bab":"الجزء 8","sec":"أخبار سعيد بن عبد الرحمن","page":"ج8 ص278","text":"وقد مضى نسبه في نسب جده حسان بن ثابت متقدما وهو شاعر من شعراء الدولة الأموية متوسط في طبقته ليس معدودا في الفحول وقد وفد إلى الخلفاء من بني أمية فمدحهم ووصلوه ولم تكن له نباهة أبيه وجده أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن الهيثم بن فراس قال حدثني ابو عمرو الخصاف عن العتبي قال خرج سعيد بن عبد الرحمن بن حسان مع جماعة من قريش إلى الشام في خلافة هشام بن عبد الملك وسألهم معاونته فلم يصادفوا من هشام له نشاطا وكان الوليد بن يزيد قد طلق امرأته العثمانية ليتزوج أختها فمنعه هشام عن ذلك ونهى أباها أن يزوجه فمر يوما بالوليد وقد خرج من داره ليركب فلما رآه وقف فأمر به الوليد فدعي إليه فلما جاءه قال أنت ابن عبد الرحمن بن حسان قال نعم أيها الأمير فقال له ما أقدمك قال وفدت على أمير المؤمنين منتجعا ومادحا ومستشفعا بجماعة صحبتهم من أهله فلم أنل منه حظوة ولا قبولا قال لكنك تجد عندي ما تحب فأقم حتى أعود فأقام ببابه حتى دخل إلى هشام وخرج من عنده فنزل ودعا بسعيد فدخل إليه فأمر بتغيير هيئته وإصلاح شأنه ثم قال له أنشدني قصيدة بلغتني لك فشوقتني\nإليك وغنيت في بعضها فلم أزل أتمنى لقاءك فقال أي قصيدة أيها الأمير قال قولك\n(أبائنة سعدى ولم توف بالعهد ... ولم تشف قلبا تيمته على عمد)\n(نعم أفمود أنت إن شطت النوى ... بسعدى وما من فرقة الدهر من رد)\n(كأن قد رأيت البين لا شيء دونه ... فم الآن أعلن ما تسر من الوجد)\n(لعلك منها بعد أن تشحط النوى ... ملاق كما لاقى ابن عجلان من هند)\n(فويل ابن سلمى خلة غير أنها ... تبلغ مني وهي مازحة جدي)\n(وتدنو لنا في القول وهي بعيدة ... فما إن بسلمى من دنو ولا بعد)\n(ومهما أكن جلدا عليه فإنني ... على هجرها غير الصبور ولا الجلد)\n(إذا سمت نفسي هجرها قطعت به ... فجانبته فيما أسر وما أبدي)\n(كأني أرى في هجرها أي ساعة ... هممت به موتي وفي وصلها خلدي)\n(ومن أجلها صافيت من لا تردني ... عليه له قربى ولا نعمة عندي)\n(وأغضيت عيني من رجال على القذى ... يقولون أقوالا أمضوا بها جلدي)\n(وأقصيت من قد كنت أدني مكانه ... وأدنيت من قد كنت أقصيته جهدي)\n(فإن يك أمسى وصل سلمى خلابة ... فما أنا بالمفتون في مثلها وحدي)\n(فأصبح ما منتك دينا مسوفا ... لواه غريم ذو اعتلال وذو جحد)\n(تجود بتقريب الذي هو آجل ... من الوعد ممطول وتبخل بالنقد)\n(وقد قلت إذ أهدت إلينا تحية ... عليها سلام الله من نازح مهدي)\n(سقى الغيث ذاك الغور ما سكنت به ... ونجدا إذا صارت نواها إلى نجد)\nال فجعل ينشدها ودموع الوليد تنحدر على خديه حتى فرغ منها ثم قال له لن تحتاج إلى رفد أحد ولا معونته ما بقيت وأمر له بخمسمائة درهم وقال ابعث بها إلى أهلك واقم عندي فلن تعدم ما تحبه ما بقيت فلم يزل معه زمانا ثم استأذنه وانصرف وفي بعض هذه الأبيات غناء نسبيته\n(أبائنة سعدى ولم توف بالعهد ... ولم تشف قلبا أقصدته على عمد)\n(ومهما أكن جلدا عليه فإنني ... على هجرها غير الصبور ولا الجلد)\nالغناء لمالك خفيف ثقيل أول بالوسطى عن الهشامي ومن هذه القصيدة صوت وأغضيت عيني من رجال على القذى ... يقولون أقوالا أمضوا بها جلدي إذا سمت نفسي هجرها قطعت به ... فجانيته فيما أسر وما أبدي\nلغناء لابن محرز ثاني ثقيل بالبنصر عن عمرو","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":8,"spl":"أخبار سعيد بن عبد الرحمن","song":1,"loc":1510},
{"id":"b80-13","bab":"الجزء 8","sec":"خبره مع عبد الصمد مؤدب الوليد بن يزيد","page":"ج8 ص280","text":"أخبرني الحسن بن علي الخفاف قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال حدثني عمي ومحمد بن الضحاك بن عثمان قالا\nوفد سعيد بن عبد الرحمن بن حسان على هشام بن عبد الملك وكان حسن الوجه فاختلف إلى عبد الصمد بن عبد الأعلى مؤدب الوليد بن يزيد بن عبد الملك فأراده على نفسه وكان لوطيا زنديقا فدخل سعيد على هشام مغضبا وهو يقول\n(إنه والله لولا أنت لم ... ينج مني سالما عبد الصمد)\nقال له هشام ولماذا قال\n(إنه قد رام مني خطة ... لم يرمها قبله مني أحد)\nقال وما هي قال\n(رام جهلا بي وجهلا بأبي ... يدخل الأفعى إلى خيس الأسد)\nال فضحك هشام وقال له لو فعلت به شيئا لم أنكر عليك أخبرني أحمد بن عبيد الله بن عمار قال حدثني عمر بن شبة قال أخبرنا ابن عائشة لا أعلمه إلا عن أبيه قال سأل سعيد بن عبد الرحمن بن حسان صديقا له حاجة وقال هاشم بن محمد في خبره سأل سعيد بن عبد الرحمن ابا بكر بن محمد بن عمرو بن حزم حاجة يكلم فيها سليمان بن عبد الملك فلم يقضها له ففزع فيها إلى غيره فقضاها فقال\n(سئلت فلم تفعل وأدركت حاجتي ... تولى سواكم حمدها واصطناعها)\n(أبى لك كسب الحمد رأي مقصر ... ونفس أضاق الله بالخير باعها)\n(إذا ما أرادته على الخير مرة ... عصاها وإن همت بشر أطاعها)\nقال ابن عمار وقد أنشدنا هذه الأبيات سليمان بن أبي شيخ لسعيد بن عبد الرحمن ولم يذكر لها خبرا","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":9,"spl":"خبره مع عبد الصمد مؤدب الوليد بن يزيد","loc":1511},
{"id":"b80-14","bab":"الجزء 8","sec":"عدي بن الرقاع يشهد له بشاعريته","page":"ج8 ص282","text":"أخبرني محمد بن يحيى الصولي قال حدثنا محمد بن زكريا الغلابي عن ابن عائشة قال قال رجل من الأنصار لعدي بن الرقاع أكتبني شيئا من شعرك قال ومن أي العرب أنت قال أنا رجل من الأنصار قال ومن منكم القائل\n(إن الحمام إلى الحجاز يهيج لي ... طربا ترنمه إذا يترنم)\n(والبرق حين أشيمه متيامنا ... وجنائب الأرواح حين تنسم)\nقال له سعيد بن عبد الرحمن بن حسان بن ثابت فقال عليكم بصاحبكم فاكتب شعره فلست تحتاج معه إلى غيره وفي أول هذه القصيدة غناء نسبته\n(برح الخفاء فأي ما بك تكتم ... والشوق يظهر ما تسر فيعلم)\n(وحملت سقما من علائق حبها ... والحب يعلقه الصحيح فيسقم)\nلغناء لحكم خفيف رمل بالوسطى عن الهشامي وذكره إبراهيم له ولم يجنسه وفي هذه القصيدة يقول\n(علوية أمست ودون وصالها ... مضمار مصر وعابد والقلزم)\n(خود تطيف بها نواعم كالدمى ... مما اصطفى ذو النيقة المتوسم)\n(حلين مرجان البحور وجوهرا ... كالجمر فيه على النحور ينظم)\n(قالت وماء العين يغسل كحلها ... عند الفراق بمستهل يسجم)\n(يا ليت أنك يا سعيد بأرضنا ... تلقي المراسي ثاويا وتخيم)\n(فتصيب لذة عيشنا ورخاءه ... فنكون أجوارا فماذا تنقم)\n(لا ترجعن إلى الحجاز فإنه ... بلد به عيش الكريم مذمم)\n(وهلم جاورنا فقلت لها اقصري ... عيش بطيبة ويح غيرك أنعم)\n(أيفارق الوطن الحبيب لمنزل ... ناء ويشرى بالحديث الأقدم)\n(إن الحمام إلى الحجاز يهيج لي ... طربا ترنمه إذا يترنم)\n(والبرق حين أشيمه متيامنا ... وجنائب الأرواح حين تنسم)\n(لو لح ذو قسم على أن لم يكن ... في الناس مشبهها لبر المقسم)\n(من أجلها تركي القرار وخفضه ... وتجشمي ما لم أكن أتجشم)\n(ولقد كتمت غداة بانت حاجة ... في الصدر لم يعلم بها متكلم)\n(تشفي برؤيتها السقيم وترتمي ... حب القلوب رميها لا يسلم)\n(رقراقة في عنفوان شبابها ... فيها عن الخلق الدني تكرم)\n(ضنت على مغرى بطول سؤالها صب كما يسل الغني المعدم ... )\nأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو مسلم عن الحرمازي قال\nخرج سعيد بن عبد الرحمن بن حسان إلى عسكر يزيد بن عبد الملك فأتى عنبسة بن سعيد بن العاصي وكان أبوه صديقا لأبيه فسأله أن يرفع أمره إلى الخليفة فوعده أن يفعل فلم يمكث إلا يسيرا حتى طرقه لص فسرق متاعه وكل شيء كان معه فأتى عنبسة فتنجزه ما وعده فاعتل عليه ودافعه فرجع سعيد من عنده فارتجل وقال\n(أعنبس قد كنت لا تعتزي ... إلى عدة منك كانت ضلالا)\n(وعدت عدات لوانجزتها ... إذا لحمدت ولم تزر مالا)\n(وما كان ضرك لو قد شفعت ... فأعطى الخليفة عفوا نوالا)\n(وقد ينجز الحر موعوده ويفعل ما كان بالأمس قالا ... )\n(فيا ليتني والمنى كاسمها ... وقد يصرف الدهر حالا فحالا)\n(قعدت ولم ألتمس ما وعدت ... ويا ليت وعدك كان اعتلالا)\n(وكانت نعم منك مخزونة ... وقلت من أول يوم ألالا)\n(أرى كذب القول من شر ما ... يعد إذا الناس عدوا الخصالا)\n(فأبقيت لي عنك مندوحة ... ونفسا عزوفا تقل السؤالا)\n(فإن عدت أرجوكم بعدها ... فبدلت بعد العلاء السفالا)\n(أأرجوك من بعد ما قد عزفت ... لعمري لقد جئت شيئا عضالا)","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":10,"spl":"عدي بن الرقاع يشهد له بشاعريته — صوت من المائة المختارة من رواية جحظة","song":1,"loc":1512,"partial":1},
{"id":"b80-15","bab":"الجزء 8","sec":"الوليد يستأنس به في الحج","page":"ج8 ص284","text":"نسخت من كتاب عمرو بن أبي عمرو الشيباني يأثر\nكان سعيد بن عبد الرحمن بن حسان إذا وفد إلى الشام نزل على الوليد بن يزيد فأحسن نزله وأعطاه وكساه وشفع له فلما حج الوليد لقيه سعيد بن عبد الرحمن في أول من لقيه فسلم عليه فرد الوليد عليه السلام وحياه وقربه وأمر بإنزاله معه وبسطه ولم يأنس بأحد أنسه به وأنشده سعيد قوله فيه\n(يا لقومي للهجر بعد التصافي ... وتنائي الجميع بعد ائتلاف)\n(ما شجا القلب بعد طول اندمال ... غير هاب كالفرخ بين أثافي)\n(ونعيب الغراب في عرصة الدار ... ونؤي تسفي عليه السوافي)\nوقد روى عن سعيد بن عبد الرحمن بن حسان قال رأى علي ابن عمر أوضاحا فقال ألقها عنك فقد كبرت","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":10,"spl":"عدي بن الرقاع يشهد له بشاعريته — صوت من المائة المختارة من رواية جحظة","loc":1513},
{"id":"b80-16","bab":"الجزء 8","sec":"صوت من المائة المختارة من رواية جحظة","page":"ج8 ص285","text":"(ما جرت خطرة على القلب مني ... فيك إلا استترت عن أصحابي)\n(من دموع تجري فإن كنت وحدي ... خاليا أسعدت دموعي انتحابي)\n(إن حبي إياك قد سل جسمي ... ورماني بالشيب قبل الشباب)\n(ارحمي عاشقا لك اليوم صبا ... هائم العقل قد ثوى في التراب)\nلشعر للسيد الحميري والغناء لمحمد نعجة خفيف رمل أيضا\nولم أجد لهذا المغني خبرا ولا ذكرا في موضع من المواضع اذكره وقد مضت أخبار السيد متقدما","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":10,"spl":"عدي بن الرقاع يشهد له بشاعريته — صوت من المائة المختارة من رواية جحظة","loc":1514},
{"id":"b80-17","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص286","text":"(أكرع الكرعة الروية منها ... ثم أصحو ما شفيت غليلي)\n(كم أتى دون عهد أم جميل ... من إنى حاجة ولبث طويل)\n(وصياح الغراب أن سر فأسرع ... سوف تحظى بنائل وقبول)\nلشعر للأحوص والغناء للبردان خفيف ثقيل مطلق في مجرى البنصر","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":11,"spl":"صوت من المائة المختارة — أخبار البردان — سياط المغني يأخذ عنه أصواتا","loc":1515},
{"id":"b80-19","bab":"الجزء 8","sec":"أخبار البردان — سياط المغني يأخذ عنه أصواتا","page":"ج8 ص286 – ج8 ص287","text":"البردان لقب غلب عليه ومن الناس من يقول بردان من أهل المدينة وأخذ الغناء عن معبد وقبله عن جميلة وعزة الميلاء وكان معدلا مقبول الشهادة وكان متولي السوق بالمدينة قال هارون بن الزيات حدثني أبو أيوب المديني عن محمد بن سلام قال هو بردان بضم الباء وتسكين الراء أخبرني محمد بن مزيد بن أبي الأزهر وحسين بن يحيى قالا حدثنا حماد بن إسحاق عن أبيه وأخبرني علي بن عبد العزيز عن ابن خرداذبه قال قال إسحاق كان بردان متولي السوق بالمدينة فقدم إليه رجل خصما يدعي عليه حقا فوجب الحكم عليه فأمر به إلى الحبس فقال له الرجل أنت بغير هذا أعلم منك بهذا فقال ردوه فرد فقال لعلك تعني الغناء إني والله به لعارف ولو سمعت شيئا جاء البارحة لازددت علما بأني عارف ومهما جهلت فإني بوجوب الحق عليك عالم اذهبوا به إلى الحبس حتى يخرج إلى غريمه من حقه\nقال وحدثني أبو أيوب عن حماد عن أبيه عن ابن جامع عن سياط قال\nرأيت البردان بالمدينة يتولى سوقها وقد أسن فقلت له يا عم إني رويت لك صوتا صنعته وأحببت أن تصححه لي فضحك ثم قال نعم يا بني وحبا وكرامة لعله\n(كم أتى دون عهد أم جميل ... )\nقلت قال مل بنا إلى ها هنا فمال بي إلى دار في السوق ثم قال غنه فقلت بل تتم إحسانك يا عم وتغنيني به فإنه أطيب لنفسي فإن سمعته كما أقول غنيته وأنا غير متهيب وإن كان فيه مستصلح استعدته فضحك ثم قال أنت لست تريد أن تصحح غناءك إنما تريد أن تقول سمعتني وأنا شيخ وقد انقطعت وأنت شاب فقلت للجماعة إن رأيتم أن تسألوه أن يشفعني فيما طلبت منه فسألوه فاندفع فغناه فأعاده ثلاث مرات فما رأيت أحسن من غنائه على كبر سنه ونقصان صوته ثم قال غنه فغنيته فطرب الشيخ حتى بكى وقال اذهب يا بني فأنت أحسن الناس غناء ولئن عشت ليكونن لك شأن قال وكان بردان خفيف الروح طيب الحديث مليح النادرة مقبول الشهادة قد لقي الناس فكان بعد ذلك إذا رآني يدعوني فيأخذني معه إلى منزله ويسألني أن أغنيه فأفعل فإذا طابت نفسه سألته أن يطرح علي شيئا من أغاني القدماء فيفعل إلى أن أخذت عنه عدة أصوات","topic":"ذكر أبي دلف ونسبه وأخباره","topicNo":80,"sp":11,"spl":"صوت من المائة المختارة — أخبار البردان — سياط المغني يأخذ عنه أصواتا","loc":1516,"partialRef":{"sid":"b80-17","gi":0,"vi":1,"side":0},"partial":1},
{"id":"b81-1","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص288","text":"(لمن الديار بحائل فوعال ... درست وغيرها سنون خوالي)\n(درج البوارح فوقها فتنكرت ... بعد الأنيس معارف الأطلال)\n(دمن تذعذعها الرياح وتارة ... تعفو بمرتجز السحاب ثقال)\n(فكأنما هي من تقادم عهدها ... ورق نشرن من الكتاب بوالي)\nلشعر للأخطل والغناء لسائب خاثر ولحنه المختار من الثقيل الأول بالبنصر من أصوات قليلة الأشباه وذكر عمرو بن بانة أن في الثاني والرابع من الأبيات للأبجر ثقيلا أول وذكر حبش أن لمعبد فيه ثقيلا أول بالوسطى وأنه أحد السبعة وأن لإسحاق فيه ثاني ثقيل وذكر الهشامي أن لحن إسحاق خفيف ثقيل","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":0,"spl":"صوت من المائة المختارة — ذكر الأخطل وأخباره ونسبه","loc":1517},
{"id":"b81-2","bab":"الجزء 8","sec":"ذكر الأخطل وأخباره ونسبه","page":"ج8 ص290","text":"هو غياث بن غوث بن الصلت بن الطارقة ويقال ابن سيحان بن عمرو بن الفدوكس بن عمرو بن مالك بن جشم بن بكر بن حبيب بن عمرو بن غنم بن تغلب ويكنى ابا مالك وقال المدائني هو غياث بن غوث بن سلمة بن طارقة قال ويقال لسلمة سلمة اللحام قال وبعث النعمان بن المنذر بأربعة أرماح لفرسان العرب فأخذ ابو براء عامر بن مالك رمحا وسلمة بن طارقة اللحام رمحا وهو جد الأخطل وأنس بن مدرك رمحا وعمرو بن معديكرب رمحا والأخطل لقب غلب عليه ذكر هارون بن الزيات عن ابن النطاح عن أبي عبيدة أن السبب فيه أنه هجا رجلا من قومه فقال له يا غلام إنك الأخطل فغلبت عليه وذكر يعقوب بن السكيت أن عتبة بن الزعل بن عبد الله بن عمر بن عمرو بن حبيب بن الهجرس بن تيم بن سعد بن جشم بن بكر بن حبيب بن عمرو بن غنم بن تغلب حمل حمالة فأتى قومه يسأل فيها فجعل الأخطل يتكلم وهو يومئذ غلام فقال عتبة من هذا الغلام الأخطل فلقب به\nقال يعقوب وقال غير أبي عبيدة إن كعب بن جعيل كان شاعر تغلب وكان لا يأتي منهم قوما إلا أكرموه وضربوا له قبة حتى إنه كان تمد له حبال بين وتدين فتملأ له غنما فأتى في مالك بن جشم ففعلوا ذلك به فجاء الأخطل وهو غلام فأخرج الغنم وطردها فسبه عتبة ورد الغنم إلى مواضعها فعاد وأخرجها وكعب ينظر إليه فقال إن غلامكم هذا الأخطل والأخطل السفيه فغلب عليه ولج الهجاء بينهما فقال الأخطل فيه\n(سميت كعبا بشر العظام ... وكان أبوك يسمى الجعل)\n(وإن محلك من وائل ... محل القراد من است الجمل)\nقال كعب قد كنت أقول لا يقهرني إلا رجل له ذكر ونبأ ولقد أعددت هذين البيتين لأن أهجى بهما منذ كذا وكذا فغلب عليهما هذا الغلام وقال هارون بن الزيات حدثني قبيصة بن معاوية المهلبي قال حدثني عيسى بن إسماعيل قال حدثني القحذمي قال وقع بين ابني جعيل وأمهما ذرء من كلام فأدخلوا الأخطل بينهم فقال الأخطل\n(لعمرك إنني وابني جعيل ... وأمهما لإستار لئيم)\nقال ابن جعيل يا غلام إن هذا لخطل من رأيك ولولا أن أمي سمية\nأمك لتركت أمك يحدو بها الركبان فسمي الأخطل بذلك وكان اسم أمهما وأم الأخطل ليلى وقال هارون حدثني إسماعيل بن مجمع عن ابن الكلبي عن قوم من تغلب في قصة كعب بن جعيل والأخطل بمثل ما ذكره يعقوب عن غير أبي عبيدة ممن لم يسمه وقال فيها وكان الأخطل يومئذ يقرزم والقرزمة الابتداء بقول الشعر فقال له أبوه أبقرزمتك تريد أن تقاوم ابن جعيل وضربه قال وجاء ابن جعيل على تفئة ذلك فقال من صاحب الكلام فقال أبوه لا تحفل به فإنه غلام أخطل فقال له كعب\n(شاهد هذا الوجه غب الحمه ... )\nقال الأخطل\n(فناك كعب بن جعيل أمه ... )\nقال كعب ما اسم أمك قال ليلى قال أردت أن تعيذها باسم أمي قال لا أعاذها الله إذا وكان اسم أم الأخطل ليلى وهي امرأة من إياد فسمي الأخطل يومئذ وقال\n(هجا الناس ليلى أم كعب فمزقت ... فلم يبق إلا نفنف أنا رافعه)\nقال فيه أيضا\n(هجاني المنتنان ابنا جعيل ... وأي الناس يقتله الهجاء)\n(ولدتم بعد إخوتكم من است ... فهلا جئتم من حيث جاؤوا)\nانصرف كعب ولج الهجاء بينهما","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":0,"spl":"صوت من المائة المختارة — ذكر الأخطل وأخباره ونسبه","loc":1518,"partial":1},
{"id":"b81-3","bab":"الجزء 8","sec":"من هو الأشعر الأخطل أم جرير أم الفرزدق","page":"ج8 ص293","text":"وكان نصرانيا من أهل الجزيرة ومحله في الشعر أكبر من أن يحتاج إلى وصف وهو وجرير والفرزدق طبقة واحدة فجعلها ابن سلام أول طبقات الإسلام ولم يقع إجماع على أحدهم أنه أفضل ولكل واحد منهم طبقة تفضله عن الجماعة أخبرنا محمد بن العباس اليزيدي قال حدثني عمي الفضل قال حدثني إسحاق بن إبراهيم عن أبي عبيدة قال جاء رجل إلى يونس فقال له من أشعر الثلاثة قال الأخطل قلنا من الثلاثة قال أي ثلاثة ذكروا فهو أشعرهم قلنا عمن تروي هذا قال عن عيسى بن عمر وابن أبي إسحاق الحضرمي وأبي عمرو بن العلاء وعنبسة الفيل وميمون الأقرن الذين ماشوا الكلام وطرقوه أخبرنا به أحمد بن عبد العزيز قال قال أبو عبيدة عن يونس فذكر مثله وزاد فيه لا كأصحابك هؤلاء لا بدويون ولا نحويون فقلت للرجل سله وبأي شيء فضلوه قال بأنه كان أكثرهم عدد طوال جياد ليس فيها سقط ولا فحش وأشدهم تهذيبا للشعر فقال ابو وهب الدقاق أما إن حمادا وجنادا كانا لا يفضلانه فقال وما حماد وجناد لا نحويان ولا بدويان ولا يبصران الكسور ولا يفصحان وأنا\nأحدثك عن أبناء تسعين أو أكثر أدوا إلى أمثالهم ماشوا الكلام وطرقوه حتى وضعوا أبنيته فلم تشذ عنهم زنة كلمة وألحقوا السليم بالسليم والمضاعف بالمضاعف والمعتل بالمعتل والأجوف بالأجوف وبنات الياء بالياء وبنات الواو بالواو فلم تخف عليهم كلمة عربية وما علم حماد وجناد قال هارون حدثني القاسم بن يوسف عن الأصمعي أن الأخطل كان يقول تسعين بيتا ثم يختار منها ثلاثين فيطيرها أخبرنا أبو خليفة الفضل بن الحباب قال أخبرنا محمد بن سلام قال سمعت سلمة بن عياش وذكر أهل المجلس جريرا والفرزدق والأخطل ففضله سلمة عليهما قال وكان إذا ذكر الأخطل يقول ومن مثل الأخطل وله في كل بيت شعر بيتان ثم ينشد قوله\n(ولقد علمت إذا العشار تروحت ... هدج الرئال تكبهن شمالا)\n(أنا نعجل بالعبيط لضيفنا ... قبل العيال ونضرب الأبطالا)\nم يقول ولو قال\n(ولقد علمت إذا العشار ... تروحت هدج الرئال)\nان شعرا وإذا زدت فيه تكبهن شمالا كان أيضا شعرا من روي آخر أخبرنا ابو خليفة قال حدثنا محمد بن سلام قال حدثني أبو يحيى الضبي قال\nكعب بن جعيل لقبه الأخطل سمعه ينشد هجاء فقال يا غلام إنك لأخطل اللسان فلزمته أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أحمد بن معاوية قال حدثنا بعض أصحابنا عن رجل من بني سعد قال كنت مع نوح بن جرير في ظل شجرة فقلت له قبحك الله وقبح أباك أما أبوك فأفنى عمره في مديح عبد ثقيف يعني الحجاج وأما أنت فامتدحت قثم بن العباس فلم تهتد لمناقبه ومناقب آبائه حتى امتدحته بقصر بناه فقال والله لئن سؤتني في هذا الموضع لقد سؤت فيه أبي بينا أنا آكل معه يوما وفي فيه لقمة وفي يده أخرى فقلت يا ابت أنت أشعر أم الأخطل فجرض باللقمة التي في فيه ورمى بالتي في يده وقال يا بني لقد سررتني وسؤتني فأما سرورك إياي فلتعهدك لي مثل هذا وسؤالك عنه وأما ما سؤتني به فلذكرك رجلا قد مات يا بني أدركت الأخطل وله ناب واحد ولو أدركته وله ناب آخر لأكلني به ولكني أعانتني عليه خصلتان كبر سن وخبث دين أخبرني الحسين بن يحيى عن حماد قال\n(سئل حماد الراوية عن الأخطل فقال ما تسألوني عن رجل قد حبب شعره إلي النصرانية ... )\nقال إسحاق وحدثني ابو عبيدة قال قال أبو عمرو لو أدرك الأخطل يوما واحدا من الجاهلية ما قدمت عليه أحدا\nقال إسحاق وحدثني الأصمعي أن أبا عمرو أنشد بيت شعر فاستجاده وقال لو كان للأخطل ما زاد","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":1,"spl":"من هو الأشعر الأخطل أم جرير أم الفرزدق","loc":1519,"partial":1},
{"id":"b81-4","bab":"الجزء 8","sec":"من هو الأشعر الأخطل أم جرير أم الفرزدق","page":"ج8 ص293","text":"وذكر يعقوب بن السكيت عن الأصمعي عن أبي عمرو أن جريرا سئل أي الثلاثة أشعر فقال أما الفرزدق فتكلف مني ما لا يطيق وأما الأخطل فأشدنا اجتراء وأرمانا للفرائص وأما أنا فمدينة الشعر وقال ابن النطاح حدثني الأصمعي قال إنما أدرك جرير الأخطل وهو شيخ قد تحطم وكان الأخطل أسن من جرير وكان جرير يقول أدركته وله ناب واحد ولو أدركت له نابين لأكلني قال وكان أبو عمرو يقول لو أدرك الأخطل يوما واحدا من الجاهلية ما فضلت عليه أحدا أخبرني أبو خليفة عن محمد بن سلام قال قال العلاء بن جرير إذا لم يجىء الأخطل سابقا فهو سكيت والفرزدق لا يجىء سابقا ولا سكيتا وجرير يجيء سابقا ومصليا وسكيتا وقال يعقوب بن السكيت قال الأصمعي قيل لجرير ما تقول في الأخطل قال كان أشدنا اجتزاء بالقليل وأنعتنا للحمر والخمر وروى إسماعيل عن عبيد الله عن مؤرج عن شعبة عن سماك بن حرب أن الفرزدق دخل الكوفة فلقيه ضوء بن اللجلاج فقال له من أمدح\nأهل الإسلام فقال له وما تريد إلى ذلك قال تمارينا فيه قال الأخطل أمدح العرب وقال هارون بن الزيات حدثني هارون بن مسلم عن حفص بن عمر قال سمعت شيخا كان يجلس إلى يونس كان يكنى أبا حفص فحدثه انه سأل جريرا عن الأخطل فقال أمدح الناس لكريم وأوصفه للخمر قال وكان ابو عبيدة يقول شعراء الإسلام الأخطل ثم جرير ثم الفرزدق قال أبو عبيدة وكان ابو عمرو يشبه الأخطل بالنابغة لصحة شعره وقال ابن النطاح حدثني عبد الله بن رؤية بن العجاج قال كان أبو عمرو يفضل الأخطل وقال ابن النطاح حدثني عبد الرحمن بن برزخ قال كان حماد يفضل الأخطل على جرير والفرزدق فقال له الفرزدق إنما تفضله لأنه فاسق مثلك فقال لو فضلته بالفسق لفضلتك قال ابن النطاح قال لي إسحاق بن مرار الشيباني الأخطل عندنا أشعر الثلاثة فقلت يقال أنه أمدحهم فقال لا والله ولكن أهجاهم من منهما يحسن أن يقول\n(ونحن رفعنا عن سلول رماحنا ... وعمدا رغبنا عن دماء بني نصر)\nخبرني الحسن بن علي قال حدثنا محمد بن موسى عن أحمد بن الحارث عن المدائني قال قال الأخطل أشعر الناس قبيلة بنو قيس بن ثعلبة وأشعر الناس بيتا آل\nأبي سلمى وأشعر الناس رجل في قميصي","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":2,"spl":"من هو الأشعر الأخطل أم جرير أم الفرزدق — عبد الملك بن مروان يجيزه على مدحه","loc":1520},
{"id":"b81-5","bab":"الجزء 8","sec":"عبد الملك بن مروان يجيزه على مدحه","page":"ج8 ص298","text":"أخبرني الحسن قال حدثني محمد قال حدثني الخراز عن المدائني عن علي بن حماد هكذا قال وأظنه علي بن مجاهد قال قال الأخطل لعبد الملك يا امير المؤمنين زعم ابن المراغة أنه يبلغ مدحتك في ثلاثة أيام وقد أقمت في مدحتك\n(خف القطين فراحوا منك أو بكروا ... )\nنة فما بلغت كل ما أردت فقال عبد الملك فأسمعناها يا أخطل فأنشده إياها فجعلت أرى عبد الملك يتطاول لها ثم قال ويحك يا أخطل أتريد أن أكتب إلى الآفاق أنك أشعر العرب قال أكتفي بقول أمير المؤمنين وأمر له بجفنة كانت بين يديه فملئت دراهم وألقى عليه خلعا وخرج به مولى لعبد الملك على الناس يقول هذا شاعر أمير المؤمنين هذا أشعر العرب وقال ابن الزيات حدثني جعفر بن محمد بن عيينة بن المنهال عن هشام عن عوانة قال أنشد عبد الملك قول كثير فيه\n(فما تركوها عنوة من مودة ... ولكن بحد المشرفي استقالها)\nفأعجب به فقال له الأخطل ما قلت لك والله يا أمير المؤمنين أحسن\nمنه قال وما قلت قال قلت\n(أهلوا من الشهر الحرام فأصبحوا ... موالي ملك لا طريف ولا غصب)\nعلته لك حقا وجعلك أخذته غصبا قال صدقت","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":2,"spl":"من هو الأشعر الأخطل أم جرير أم الفرزدق — عبد الملك بن مروان يجيزه على مدحه","loc":1521,"partial":1},
{"id":"b81-6","bab":"الجزء 8","sec":"ادعاؤه بأنه اشعر من جرير والفرزدق","page":"ج8 ص299","text":"قال أخبرنا أحمد بن عبد العزيز قال أخبرنا عمر بن شبة قال أخبرنا أبو دقاقة الشامي مولى قريش عن شيخ من قريش قال رأيت الأخطل خارجا من عند عبد الملك فلما انحدر دنوت منه فقلت يا أبا مالك من أشعر العرب قال هذان الكلبان المتعاقران من بني تميم فقلت فأين أنت منهما قال أنا واللات أشعر منهما قال فحلف باللات هزؤا واستخفافا بدينه وروى هذا الخبر أبو أيوب المديني عن المدائني عن عاصم بن شبل الجرمي أنه سأل الأخطل عن هذا فذكر نحوه وقال واللات والعزى أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني عبد الله بن أبي سعد قال ذكر الحرمازي أن رجلا من بني شيبان جاء إلى الأخطل فقال له يا أبا مالك إنا وإن كنا بحيث تعلم من افتراق العشيرة واتصال الحرب والعداوة تجمعنا ربيعة وإن لك عندي نصحا فقال هاته فما كذبت فقلت إنك قد هجوت جريرا ودخلت بينه وبين الفرزدق وأنت غني عن ذلك ولا سيما أنه يبسط لسانه بما ينقبض عنه لسانك ويسب ربيعة سبا لا تقدر على سب مضر بمثله والملك فيهم والنبوة قبله فلو شئت أمسكت عن مشارته ومهارته فقال صدقت في\nنصحك وعرفت مرادك وصلتك رحم فوالصليب والقربان لأتخلصن إلى كليب خاصة دون مضر بما يلبسهم خزيه ويشملهم عاره ثم اعلم أن العالم بالشعر لا يبالي وحق الصليب إذا مر به البيت المعاير السائر الجيد أمسلم قاله أم نصراني أخبرني وكيع قال حدثني أبو أيوب المديني عن أبي الحسن المدائني قال أصبح عبد الملك يوما في غداة باردة فتمثل قول الأخطل\n(إذا اصطبح الفتى منها ثلاثا ... بغير الماء حاول أن يطولا)\n(مشى قرشية لا شك فيها ... وأرخى من مآزره الفضولا)\nم قال كأني أنظر إليه الساعة مجلل الإزار مستقبل الشمس في حانوت من حوانيت دمشق ثم بعث رجلا يطلبه فوجده كما ذكره وقال هارون بن الزيات حدثني طائع عن الأصمعي قال أنشد أبو حية النميري يوما أبا عمرو\n(يا لمعد ويا للناس كلهم ... ويا لغائبهم يوما ومن شهدا)\nأنه معجب بهذا البيت فجعل أبو عمرو يقول له إنك لتعجب بنفسك كأنك الأخطل","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":3,"spl":"ادعاؤه بأنه اشعر من جرير والفرزدق","loc":1522},
{"id":"b81-7","bab":"الجزء 8","sec":"حواره مع عبد الملك بعد أن عرض عليه الإسلام","page":"ج8 ص300","text":"أخبرني الحسن بن علي قال حدثنا الغلابي عن عبد الرحمن التيمي عن\nهشام بن سليمان المخزومي أن الأخطل قدم على عبد الملك فنزل على ابن سرحون كاتبه فقال عبد الملك على من نزلت قال على فلان قال قاتلك الله ما أعلمك بصالح المنازل فما تريد أن ينزلك قال درمك من درمككم هذا ولحم وخمر من بيت رأس فضحك عبد الملك ثم قال له ويلك وعلى أي شيء اقتتلنا إلا على هذا ثم قال ألا تسلم فنفرض لك في الفيء ونعطيك عشرة آلاف قال فكيف بالخمر قال وما تصنع بها وإن أولها لمر وإن آخرها لسكر فقال أما إذا قلت ذلك فإن فيما بين هاتين لمنزلة ما ملكك فيها إلا كعلقة ماء من الفرات بالإصبع فضحك ثم قال ألا تزور الحجاج فإنه كتب يستزيرك فقال أطائع ام كاره قال بل طائع قال ما كنت لأختار نواله على نوالك ولا قربه على قربك إنني إذا لكما قال الشاعر\n(كمبتاع ليركبه حمارا ... تخيره من الفرس الكبير)\nأمر له بعشرة آلاف درهم وأمره بمدح الحجاج فمدحه بقوله\n(صرمت حبالك زينب ورعوم ... وبدا المجمجم منهما المكتوم)\nوجه بالقصيدة مع ابنه إليه وليست من جيد شعره وقال هارون بن الزيات حدثني محمد بن إسماعيل عن أبي غسان قال\nذكروا الفرزدق وجريرا في حلقة المدائني فقلت لصباح بن خاقان أنشدك بيتين للأخطل وتجيء لجرير والفرزدق بمثلهما قال هات فأنشدته\n(ألم يأتها أن الأراقم فلقت ... جماجم قيس بين راذان والحضر)\n(جماجم قوم لم يعافوا ظلامة ... ولم يعرفوا أين الوفاء من الغدر)\nال فسكت قال إسحاق وحدثني أبو عبيدة أن يونس سئل عن جرير والفرزدق والأخطل أيهم أشعر قال أجمعت العلماء على الأخطل فقلت لرجل إلى جنبه سله ومن هم فقال من شئت ابن أبي إسحاق وأبو عمرو بن العلاء وعيسى بن عمر وعنبسة الفيل وميمون الأقرن هؤلاء طرقوا الكلام وماشوه لا كمن تحكمون عنه لا بدويين ولا نحويين فقلت للرجل سله وبأي شيء فضل على هؤلاء قال بأنه كان أكثرهم عدد قصائد طوال جياد ليس فيها فحش ولا سقط قال أبو عبيدة فنظرنا في ذلك فوجدنا للأخطل عشرا بهذه الصفة وإلى جانبها عشرا إن لم تكن مثلها فليست بدونها ووجدنا لجرير بهذه الصفة ثلاثا قال إسحاق فسألت أبا عبيدة عن العشر فقال\n(عفا واسط من آل رضوى فنبتل ... )\nو\n(تأبد الربع من سلمى بأحفار ... )\nو\n(خف القطين فراحوا منك وابتكروا ... )\nو\n(كذبتك عينك أم رأيت بواسط ... )\nو\n(دع المعمر لا تسأل بمصرعه ... )\nو\n(لمن الديار بحائل فوعال ... )\nال إسحاق ولم احفظ بقية العشر قال وقصائد جرير\n(حي الهدملة من ذات المواعيس ... )\nو\n(ألا طرقتك وأهلي هجود ... )\nو\n(أهوى أراك برامتين وقودا ... )\nال وقال أبو عبيدة الأخطل أشبه بالجاهلية وأشدهم أسر شعر وأقلهم سقطا واخبرنا الجوهري عن عمر بن شبة عن أبي عبيدة مثله وفي بعض هذه القصائد التي ذكرت للأخطل اغان هذا موضع ذكرها منها\n(تأبد الربع من سلمى بأحفار ... وأقفرت من سليمى دمنة الدار)\n(وقد تحل بها سلمى تجاذبني ... تساقط الحلي حاجاتي وأسراري)\nناه عمر الوادي هزجا بالسبابة في مجرى الوسطى وسنذكر خبر هذا الشعر في أخبار عبد الرحمن بن حسان لما هجاه الأخطل وهجا الأنصار إذ كان هذا الشعر قيل في ذلك\nومنها\n(خف القطين فراحوا منك وابتكروا ... وأزعجتهم نوى في صرفها غير)\n(كانني شارب يوم استبد بهم ... من قهوة ضمنتها حمص أو جدر)\n(جادت بها من ذوات القار مترعة ... كلفاء ينحت عن خرطومها المدر)\nغناه إبراهيم خفيف ثقيل بالبنصر ولابن سريج فيه رمل بالوسطى عن عمرو وفيه رمل آخر يقال إنه لعلويه ويقال إنه لإبراهيم وفيه لعلويه خفيف ثقيل آخر لا يشك فيه","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":4,"spl":"حواره مع عبد الملك بعد أن عرض عليه الإسلام","song":2,"loc":1523,"partialRef":{"sid":"b75-39","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b81-8","bab":"الجزء 8","sec":"بماذا أجاب عمر بن الوليد عندما سأله عن أشعر الناس","page":"ج8 ص304","text":"وقال هارون بن الزيات حدثني ابن النطاح عن أبي عمرو الشيباني عن رجل من كلب يقال له مهوش عن أبيه\nأن عمر بن الوليد بن عبد الملك سأل الأخطل عن أشعر الناس قال الذي كان إذا مدح رفع وإذا هجا وضع قال ومن هو قال الأعشى قال ثم من قال ابن العشرين يعني طرفة قال ثم من قال أنا\nأخبرني أحمد بن عبد العزيز الجوهري قال أخبرنا عمر بن شبة قال حدثنا أبو بكر العليمي قال حدثنا أبو قحافة المري عن أبيه قال\nدخل الأخطل على بشر بن مروان وعنده الراعي فقال له بشر أنت\nأشعر أم هذا قال أنا أشعر منه واكرم فقال للراعي ما تقول قال أما أشعر مني فعسى وأما اكرم فإن كان في أمهاته من ولدت مثل الأمير فنعم فلما خرج الأخطل قال له رجل أتقول لخال الأمير أنا أكرم منك قال ويلك إن أبا نسطوس وضع في رأسي أكؤسا ثلاثا فوالله ما أعقل معها","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":5,"spl":"بماذا أجاب عمر بن الوليد عندما سأله عن أشعر الناس","loc":1524},
{"id":"b81-9","bab":"الجزء 8","sec":"أنشد عبد الملك وهو نشوان","page":"ج8 ص305","text":"قال ودخل الأخطل على عبد الملك بن مروان فاستنشده فقال قد يبس حلقي فمر من يسقيني فقال اسقوه ماء فقال شراب الحمار وهو عندنا كثير قال فاسقوه لبنا قال عن اللبن فطمت قال فاسقوه عسلا قال شراب المريض قال فتريد ماذا قال خمرا يا أمير المؤمنين قال أوعهدتني اسقي الخمر لا أم لك لولا حرمتك بنا لفعلت بك وفعلت فخرج فلقي فراشا لعبد الملك فقال ويلك إن أمير المؤمنين استنشدني وقد صحل صوتي فاسقني شربة خمر فسقاه فقال اعدله بآخر فسقاه آخر فقال تركتهما يعتركان في بطني اسقني ثالثا فسقاه ثالثا فقال تركتني أمشي على واحدة اعدل ميلي برابع فسقاه رابعا فدخل على عبد الملك فأنشده\n(خف القطين فراحوا منك وابتكروا ... وأزعجتهم نوى في صرفها غير)\nقال عبد الملك خذ بيده يا غلام فأخرجه ثم ألق عليه من الخلع ما يغمره واحسن جائزته وقال إن لكل قوم شاعرا وإن شاعر بني أمية الأخطل أخبرني أبو خليفة إجازة عن محمد بن سلام قال قال أبان بن عثمان حدثني سماك بن حرب عن ضوء بن اللجلاج قال\nدخلت حماما بالكوفة وفيه الأخطل قال فقال ممن الرجل قلت من بني ذهل قال أتروي للفرزدق شيئا قلت نعم قال ما أشعر خليلي على أنه ما أسرع ما رجع في هبته قلت وما ذاك قال قوله\n(أبني غدانة إنني حررتكم ... فوهبتكم لعطية بن جعال)\n(لولا عطية لاجتدعت أنوفكم ... من بين ألأم آنف وسبال)\nهبهم في الأول ورجع في الآخر فقلت لو أنكر الناس كلهم هذا ما كان ينبغي أن تنكره أنت قال كيف قلت هجوت زفر بن الحارث ثم خوفت الخليفة منه فقلت\n(بني أمية إني ناصح لكم ... فلا يبيتن فيكم آمنا زفر)\n(مفترشا كافتراش الليث كلكله ... لوقعة كائن فيها له جزر)\nدحت عكرمة بن ربعي فقلت\n(قد كنت أحسبه قينا وأخبره ... فاليوم طير عن أثوابه الشرر)\nال لو أردت المبالغة في هجائه ما زدت على هذا فقال له الأخطل والله لولا أنك من قوم سبق لي منهم ما سبق لهجوتك هجاء يدخل معك قبرك ثم قال\n(ما كنت هاجي قوم بعد مدحهم ... ولا تكدر نعمى بعد ما تجب)\nأخرج عني وقال هارون بن الزيات حدثني أحمد بن إسماعيل الفهري عن أحمد بن عبد العزيز بن علي بن ميمون عن معن بن خلاد عن ابيه قال لما استنزل عبد الملك زفر بن الحارث الكلابي من قرقيسيا أقعده معه على سريره فدخل عليه ابن ذي الكلاع فلما نظر إليه مع عبد الملك على السرير بكى فقال له ما يبكيك فقال يا أمير المؤمنين كيف لا أبكي وسيف هذا يقطر من دماء قومي في طاعتهم لك وخلافه عليك ثم هو معك على السرير وأنا على الأرض قال إني لم أجلسه معي أن يكون أكرم علي منك ولكن لسانه لساني وحديثه يعجبني فبلغت الأخطل وهو يشرب فقال أما والله لأقومن في ذلك مقاما لم يقمه ابن ذي الكلاع ثم خرج حتى دخل على عبد الملك فلما ملأ عينه منه قال\n(وكأس مثل عين الديك صرف ... تنسي الشاربين لها العقولا)\n(إذا شرب الفتى منها ثلاثا ... بغير الماء حاول أن يطولا)\n(مشى قرشية لا شك فيها ... وأرخى من مآزره الفضولا)\nفقال له عبد الملك ما أخرج هذا منك يا أبا مالك إلا خطة في رأسك قال اجل والله يا أمير المؤمنين حين تجلس عدو الله هذا معك على السرير وهو القائل بالأمس\n(وقد ينبت المرعى على دمن الثرى ... وتبقى حزازات النفوس كما هيا)\nقال فقبض عبد الملك رجله ثم ضرب بها صدر زفر فقلبه عن السرير وقال أذهب الله حزازات تلك الصدور فقال أنشدك الله يا أمير المؤمنين والعهد الذي أعطيتني فكان زفر يقول ما أيقنت بالموت قط إلا تلك الساعة حين قال الأخطل ما قال وقال هارون بن الزيات حدثني هارون بن مسلم عن سعيد بن الحارث عن عبد الخالق بن حنظلة الشيباني قال قال الأخطل فضلت الشعراء في المديح والهجاء والنسيب بما لا يلحق بي فيه فأما النسيب فقولي\n(ألا يا اسلمي يا هند هند بني بدر ... وإن كان حيانا عدى آخر الدهر)\n(من الخفرات البيض أما وشاحها ... فيجري وأما القلب منها فلا يجري)\n(تموت وتحيا بالضجيع وتلتوي ... بمطرد المتنين منبتر الخصر)\nقولي في المديح\n(نفسي فداء أمير المؤمنين إذا ... أبدى النواجذ يوما عارم ذكر)\n(الخائض الغمرة الميمون طائره ... خليفة الله يستسقى به المطر)\nقولي في الهجاء\n(وكنت إذا لقيت عبيد تيم ... وتيما قلت أيهم العبيد)\n(لئيم العالمين يسود تيما ... وسيدهم وإن كرهوا مسود)\nال عبد الخالق وصدق لعمري لقد فضلهم","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":6,"spl":"أنشد عبد الملك وهو نشوان","loc":1525},
{"id":"b81-10","bab":"الجزء 8","sec":"طلق زوجته وتزوج من مطلقة","page":"ج8 ص309","text":"أخبرني احمد بن عبد العزيز قال حدثني عمر بن شبة عن أحمد بن معاوية عن محمد بن داود قال طلق أعرابي امرأته فتزوجها الأخطل وكان الأخطل قد طلق امرأته قبل ذلك فبينا هي معه إذ ذكرت زوجها الأول فتنفست فقال الأخطل\n(كلانا على هم يبيت كأنما ... بجنبيه من مس الفراش قروح)\n(على زوجها الماضي تنوح وإنني ... على زوجتي الأخرى كذاك أنوح)\nخبرني الحسن بن علي قال أخبرنا أحمد بن زهير بن حرب عن خالد بن خداش أن الأخطل قال لعبد الملك بن المهلب ما نازعتني نفسي قط إلى مدح أحد ما نازعتني إلى مدحكم فأعطني عطية تبسط بها لساني فوالله لأردينكم أردية لا يذهب صقالها إلى يوم القيامة فقال أعلم والله يا أبا مالك أنك بذلك مليء ولكني أخاف أن يبلغ أمير المؤمنين أني أسأل في غرم وأعطي الشعراء فأهلك ويظن ذلك مني حيلة فلما قدم على إخوته لاموه كل اللوم فيما فعله فقال قد أخبرته بعذري أخبرني أبو خليفة عن محمد بن سلام قال قال أبو الخطاب حدثني نوح بن جرير قال قلت لأبي أنت أشعر أم الأخطل فنهرني وقال بئس ما قلت وما أنت وذاك لا أم لك فقلت وما أنا وغيره قال لقد أعنت عليه بكفر وكبر سن وما رأيته إلا خشيت أن يبتلعني\nأخبرني عمي عن الكراني عن دماذ عن أبي عبيدة قال\nقال رجل لأبي عمرو يا عجبا للأخطل نصراني كافر يهجو المسلمين فقال أبو عمرو يا لكع لقد كان الأخطل يجيء وعليه جبة خز وحرز خز في عنقه سلسة ذهب فيها صليب ذهب تنفض لحيته خمرا حتى يدخل على عبد الملك بن مروان بغير إذن","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":7,"spl":"طلق زوجته وتزوج من مطلقة — الفرزدق في ضيافته","loc":1526},
{"id":"b81-11","bab":"الجزء 8","sec":"ابو العسكر يصنف الشعراء الثلاثة","page":"ج8 ص310","text":"وقال هارون حدثني أحمد بن إسماعيل الفهري عن أحمد بن عبد الله بن علي الدوسي عن معقل بن فلان عن أبيه عن أبي العسكر قال كنا بباب مسلمة بن عبد الملك فتذاكرنا الشعراء الثلاثة فقال أصحابي حكمناك وتراضينا بك فقلت نعم هم عندي كأفراس ثلاثة أرسلتهن في رهان فأحدها سابق الدهر كله وأحدها مصل وأحدها يجيء أحيانا سابق الريح وأحيانا سكيتا وأحيانا متخلفا فأما السابق في كل حالاته فالأخطل وأما المصلي في كل حالاته فالفرزدق وأما الذي يسبق الريح أحيانا ويتخلف أحيانا فجرير ثم أنشد له\n(سرى لهم ليل كأن نجومه ... قناديل فيهن الذبال المفتل)\nقال أحسن في هذا وسبق ثم أنشد\n(التغلبية مهرها فلسان ... والتغلبي جنازة الشيطان)\nقال تخلف في هذه فخرجنا من عنده على هذا\nوقال هارون بن الزيات حدثني محمد بن عمرو الجرجاني عن أبيه أن الفرزدق والأخطل بينا هما يشربان وقد اجتمعا بالكوفة في إمارة بشر بن مروان إذ دخل عليهما فتى من أهل اليمامة فقالا له هل تروي لجرير شيئا فأنشدهما\n(لو قد بعثت على الفرزدق ميسمي ... وعلى البعيث لقد نكحت الأخطلا)\nأقبل الفرزدق فقال يا ابا مالك أتراه إن وسمني يتوركك على كبر سنك ففزع الفتى فقام وقال أنا عائذ بالله من شركما فقالا اجلس لا بأس عليك ونادماه بقية يومهما","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":7,"spl":"طلق زوجته وتزوج من مطلقة — الفرزدق في ضيافته","loc":1527},
{"id":"b81-12","bab":"الجزء 8","sec":"الفرزدق في ضيافته","page":"ج8 ص311","text":"أخبرني أحمد بن عبد العزيز الجوهري قال أخبرنا عمر بن شبة قال حدثنا أبو يعلى قال حدثني عبد السلام بن حرب قال نزل الفرزدق على الأخطل ليلا وهو لا يعرفه فجاءه بعشاء ثم قال له إني نصراني وأنت حنيف فأي الشراب أحب إليك قال شرابك ثم جعل الأخطل لا ينشد بيتا إلا أتم الفرزدق القصيدة فقال الأخطل لقد نزل بي الليلة شر من أنت قال الفرزدق بن غالب قال فسجد لي وسجدت له فقيل للفرزدق في ذلك فقال كرهت أن يفضلني فنادى الأخطل يا بني تغلب هذا الفرزدق فجمعوا له إبلا كثيرة فلما اصبح فرقها ثم شخص أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال كان مما يقدم به الأخطل أنه كان أخبثهم هجاء في عفاف عن الفحش وقال الأخطل ما هجوت أحدا قط بما تستحي العذراء أن تنشده أباها\nأخبرني أحمد وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني محمد بن عباد الموصلي قال خرج يزيد بن معاوية معه عام حج بالأخطل فاشتاق يزيد أهله فقال\n(بكى كل ذي شجو من الشام شاقه ... تهام فأنى يلتقي الشجيان)\nجز يا أخطل فقال\n(يغور الذي بالشام أو ينجد الذي ... بغور تهامات فيلتقيان)\nخبرني أحمد وحبيب قالا حدثنا عمر بن شبة قال قيل لأبي العباس أمير المؤمنين إن رجلا شاعرا قد مدحك فتسمع شعره قال وما عسى أن يقول في بعد قول ابن النصرانية في بني أمية\n(شمس العداوة حتى يستقاد لهم ... وأعظم الناس أحلاما إذا قدروا)","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":7,"spl":"طلق زوجته وتزوج من مطلقة — الفرزدق في ضيافته","loc":1528},
{"id":"b81-13","bab":"الجزء 8","sec":"خبر له مع أمه","page":"ج8 ص312","text":"أخبرني به وكيع عن حماد بن إسحاق عن أبيه عن الهيثم بن عدي بمثله قال هارون وحدثني هارون بن سليمان عن الحسن بن مروان التميمي عن أبي بردة الفزاري عن رجل من تغلب قال لحظ الأخطل شكوة لأمه فيها لبن وجرابا فيه تمر وزبيب وكان جائعا وكان يضيق عليه فقال لها يا أمه آل فلان يزورونك ويقضون حقك وأنت لا تأتينهم وعندهم عليل فلو أتيتهم لكان اجمل وأولى بك قالت جزيت خيرا يا بني لقد نبهت على مكرمة وقامت فلبست ثيابها ومضت إليهم فمضى\nالأخطل إلى الشكوة ففرغ ما فيها وإلى الجراب فأكل التمر والزبيب كله وجاءت فلحظت موضعها فرأته فارغا فعلمت أنه قد دهاها وعمدت إلى خشبة لتضربه بها فهرب وقال\n(ألم على عنبات العجوز ... وشكوتها من غياث لمم)\n(فظلت تنادي ألا ويلها ... وتلعن واللعن منها أمم)\nذكر يعقوب بن السكيت هذه القصة فحكى أنها كانت مع امرأة لأبيه لها منه بنون فكانت تؤثرهم باللبن والتمر والزبيب وتبعث به يرعى أعنزا لها وسائر القصة والشعر متفق وقال في خبره وهذا أول شعر قاله الأخطل","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":8,"spl":"خبر له مع أمه — هجا جارية بعد أن هجته","loc":1529},
{"id":"b81-14","bab":"الجزء 8","sec":"نسيبه بأمامة ورعوم","page":"ج8 ص313","text":"أخبرني الحسن بن علي عن ابن مهرويه عن علي بن فيروز عن الأصمعي عن أمامة ورعوم اللتين قال فيهما الأخطل\n(صرمت أمامة حبلها ورعوم ... )\nرعوم وأمامة بنتا سعيد بن إياس بن هانىء بن قبيصة وكان الأخطل نزل عليه فأطعمه وسقاه خمرا وخرجتا وهما جويريتان فخدمتاه ثم نزل عليه ثانية وقد كبرتا فحجبتا عنه فسأل عنهما وقال فأين ابنتاي فأخبر بكبرهما فنسب بهما قال والرعوم هي التي كانت عند قتيبة بن مسلم وكان يقال لها أم الأخماس تزوجت في أخماس البصرة محمد بن المهلب وعامر بن مسمع وعباد بن الحصين وقتيبة بن مسلم وكان يقال لها الجارود\nأخبرنا محمد بن العباس اليزيدي قال حدثنا الخراز عن المدائني قال قال أبو عبد الملك كانت بكر بن وائل إذا تشاجرت في شيء رضيت بالأخطل وكان يدخل المسجد فيقدمون إليه قال فرأيته بالجزيرة وقد شكي إلى القس وقد أخذ بلحيته وضربه بعصاه وهي يصيء كما يصيء الفرخ فقلت له أين هذا مما كنت فيه بالكوفة فقال يابن أخي إذا جاء الدين ذللنا وقال يعقوب بن السكيت زعم غيلان عن يحيى بن بلال عن عمر بن عبد الله عن داود بن المساور قال\n(دخلت إلى الأخطل فسلمت عليه فنسبني فانتسبت واستنشدته فقال أنشدك حبة قلبي ثم أنشدني ... )\n(لعمري لقد أسريت لا ليل عاجز ... بسلهبة الخدين ضاوية القرب)\n(إليك أمير المؤمنين رحلتها ... على الطائر الميمون والمنزل الرحب)\nقلت من أشعر الناس قال الأعشى قلت ثم من قال ثم أنا أخبرني الحسن بن علي قال حدثنا ابن مهرويه عن أبي أيوب المديني عن المدائني قال امتدح الأخطل هشاما فأعطاه خمسمائة درهم فلم يرضها وخرج فاشترى بها تفاحا وفرقه على الصبيان فبلغ ذلك هشاما فقال قبحه الله ما ضر إلا نفسه\nوقال يعقوب بن السكيت حدثني سلمة النميري وتوفي وله مائة وأربعون سنة أنه حضر هشاما وله يومئذ تسع عشرة سنة وحضر جرير والفرزدق والأخطل عنده فأحضر هشام ناقة له فقال متمثلا\n(أنيخها ما بدا لي ثم أرحلها ... )\n(ثم قال أيكم أتم البيت كما أريد فهي له فقال جرير ... )\n(كأنها نقنق يعدو بصحراء ... )\n(فقال لم تصنع شيئا فقال الفرزدق ... )\n(كأنها كاسر بالدو فتخاء ... )\nقال لم تغن شيئا فقال الأخطل\n(ترخي المشافر واللحيين إرخاء ... )\nفقال اركبها لا حملك الله","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":8,"spl":"خبر له مع أمه — هجا جارية بعد أن هجته","loc":1530,"partial":1},
{"id":"b81-15","bab":"الجزء 8","sec":"هجا جارية بعد أن هجته","page":"ج8 ص315","text":"وقال هارون بن الزيات حدثني الخراز عن المدائني قال هجت الأخطل جارية من قومه فقال لأبيها يا أبا الدلماء إن ابنتك تعرضت لي فاكففها فقال له هي امرأة مالكة لأمرها فقال الأخطل\n(ألا أبلغ أبا الدلماء عني ... بأن سنان شاعركم قصير)\n(فإن يطعن فليس بذي غناء ... وإن يطعن فمطعنه يسير)\n(متى ما ألقه ومعي سلاحي ... يخر على قفاه فلا يحير)\nفمشى أبوها في رجال من قومه إلى الأخطل فكلموه فقال أما ما مضى فقد مضى ولا أزيد أخبرنا ابو خليفة إجازة عن محمد بن سلام قال لما حضرت الأخطل الوفاة قيل له يا أبا مالك ألا توصي فقال\n(أوصي الفرزدق عند الممات ... بأم جرير وأعيارها)\n(وزار القبور ابو مالك ... برغم العداة وأوتارها)","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":8,"spl":"خبر له مع أمه — هجا جارية بعد أن هجته","loc":1531},
{"id":"b81-16","bab":"الجزء 8","sec":"راي كبار الرواة فيه","page":"ج8 ص316","text":"أخبرنا أبو خليفة إجازة عن محمد بن سلام قال قال لي معاوية بن أبي عمرو بن العلاء أي البيتين عندك أجود قول جرير\n(ألستم خير من ركب المطايا ... وأندى العالمين بطون راح)\nأم قول الأخطل\n(شمس العداوة حتى يستقاد لهم ... وأعظم الناس أحلاما إذا قدروا)\nقلت بيت جرير أحلى وأسير وبيت الأخطل أجزل وأرزن فقال صدقت وهكذا كانا في أنفسهما عند الخاصة والعامة أخبرني الحسين بن يحيى عن حماد عن أبيه عن الحلبي وجعفر بن سعيد أن رجلا سأل حمادا الراوية عن الأخطل فقال ويحكم ما أقول في شعر رجل قد والله حبب إلي شعره النصرانية أخبرني محمد بن الحسن بن دريد قال حدثنا أبو عثمان الأشنانداني عن أبي عبيدة قال كان يونس بن حبيب وعيسى بن عرم وابو عمرو يفضلون الأخطل على الثلاثة\nوقال هارون بن الزيات حدثني أبو عثمان المازني عن العتبي عن أبيه أن سليمان بن عبد الملك سأل عمر بن عبد العزيز أجرير اشعر أم الأخطل فقال له أعفني قال لا والله لا أعفيك قال إن الأخطل ضيق عليه كفره القول وإن جريرا وسع عليه إسلامه قوله وقد بلغ الأخطل منه حيث رأيت فقال له سليمان فضلت والله الأخطل قال هارون وحدثني أبو عثمان عن الأصمعي عن خالد بن كلثوم قال قال عبد الملك للفرزدق من أشعر الناس في الإسلام قال كفاك بابن النصرانية إذا مدح","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":9,"spl":"راي كبار الرواة فيه","loc":1532},
{"id":"b81-17","bab":"الجزء 8","sec":"قصة أبي سواج","page":"ج8 ص317","text":"أخبرنا أحمد وحبيب قالا حدثنا عمر بن شبة قال حدثت أن الحجاج بن يوسف أوفد وفدا إلى عبد الملك وفيهم جرير فجلس لهم ثم أمر بالأخطل فدعي له فلما دخل عليه قال له يا أخطل هذا سبك يعني جريرا وجرير جالس فأقبل عليه جرير فقال أين تركت خنازير أمك قال راعية مع أعيار أمك وإن أتيتنا قريناك منها فأقبل جرير على عبد الملك فقال يا أمير المؤمنين إن رائحة الخمر لتفوح منه قال صدق يا أمير المؤمنين وما اعتذاري من ذلك\n(تعيب الخمر وهي شراب كسرى ... ويشرب قومك العجب العجيبا)\n(مني العبد عبد ابي سواج ... ( أحق من المدامة أن تعيبا)\nقال عبد الملك دعوا هذا وأنشدني يا جرير فأنشده ثلاث قصائد كلها في الحجاج يمدحه بها فأحفظ عبد الملك وقال له يا جرير إن الله\nلم ينصر الحجاج وإنما نصر خليفته ودينه ثم أقبل على الأخطل فقال\n(شمس العداوة حتى يستقاد لهم ... وأعظم الناس أحلاما إذا قدروا)\nقال عبد الملك هذه المزمرة والله لو وضعت على زبر الحديد لأذابتها ثم أمر له بخلع فخلعت عليه حتى غاب فيها وجعل يقول إن لكل قوم شاعرا وإن الأخطل شاعر بني أمية فأما قول الأخطل\n(مني العبد عبد أبي سواج ... )\nأخبرني بخبر أبي سواج علي بن سليمان الأخفش ومحمد بن العباس اليزيدي قالا حدثنا أبو سعيد السكري قال حدثنا محمد بن حبيب وابو غسان دماذ عن أبي عبيدة معمر بن المثنى أن ابا سواج وهو عباد بن خلف الضبي جاور بني يربوع وكانت له فرس يقال لها بذوة وكان لصرد بن جمرة اليربوعي فرس يقال لها القضيب فتراهنا عشرين بعشرين فسبقت بذوة فظلمه ابن جمرة حقه ومنعه سبقه وجعل يفجر بامرأته ثم إن ابا سواج ذهب إلى البحرين يمتار فلما اقبل راجعا وكان رجلا شديدا معجبا بنفسه جعل يقول وهو يحدو\n(يا ليت شعري هل بغت من بعدي ... )\nفسمع قائلا يقول من خلفه\n(نعم بمكوي قفاه جعدي ... )\nعاد إلى قوله فأجابه بمثل ذلك وقدم إلى منزله فأقام به مدة فتغاضب\nصرد على امرأة أبي سواج وقال لا أرضى أو تقدي من است أبي سواج سيرا فأخبرت زوجها بذلك فقام إلى نعجة له فذبحها وقد من باطن أليتيها سيرا فدفعه إليها فجعله صرد بن جمرة في نعله فقال لقومه إذا أقبلت وفيكم أبو سواج فسلوني من أين أقبلت ففعلوا فقال من ذي بليان وأريد ذابليان وفي نعلي شراكان من است إنسان فقام ابو سواج فطرح ثوبه وقال أنشدكم الله هل ترون بأسا ثم أمر أبو سواج غلامين له راعيين أن يأخذا أمة له فيتراوحاها ودفع إليهما عسا وقال لئن قطرت منكما قطرة في غير العس لأقتلنكما فباتا يتراوحانها ويصبان ما جاء منهما في العس وأمرهما أن يحلبا عليه فحلبا حتى ملآه ثم قال لامرأته والله لتسقنه صرد أو لأقتلنك واختبأ وقال ابعثي إليه حتى يأتيك ففعلت واتاها لعادتها كما كان يأتيها فرحبت به واستبطأته ثم قامت إلى العس فناولته إياه فلما ذاقه رأى طعما خبيثا وجعل يتمطق من اللبن الذي يشرب وقال إني أرى لبنكم خاثرا أحسب إبلكم رعت السعدان فقالت إن هذا من طول مكثه في الإناء أقسمت عليك إلا شربته فلما وقع في بطنه وجد الموت فخرج إلى أهله ولا يعلم أصحابه بشيء من أمره فلما جن على أبي سواج الليل أتى أهله وغلمانه فانصرفوا إلى قومه وخلف الفرس وكلبه في الدار فجعل الكلب ينبح والفرس يصهل وذلك ليظن القوم أنه لم يرتحل فساروا ليلتهم والدار ليس فيها غيره وكلبه وفرسه وعسه فلما اصبح ركب فرسه وأخذ العس فأتى مجلس بني يربوع فقال جزاكم الله من جيران خيرا فقد أحسنتم الجوار وفعلتم ما كنتم له أهلا فقالوا له\nيا أبا سواج ما بدا لك في الانصراف عنا قال إن صرد بن جمرة لم يكن فيما بيني وبينه محسنا وقد قلت في ذلك\n(إن المني إذا سرى ... في العبد اصبح مسمغدا)\n(أتنال سلمى باطلا ... وخلقت يوم خلقت جلدا)\n(صرد بن جمرة هل لقيت ... رثيئة لبنا وعصدا)\nاعلموا أن هذا القدح قد أحبل منكم رجلا وهو صرد بن جمرة ثم رمى بالعس على صخرة فانكسر وركض فرسه وتنادوا عليكم الرجل فأعجزهم ولحق بقومه وقال في ذلك عمر بن لجأ التيمي\n(تمسح يربوع سبالا لئمية ... بها من مني العبد رطب ويابس)\nإياه عنى الأخطل بقوله\n(ويشرب قومك العجب العجيبا ... )","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":10,"spl":"قصة أبي سواج","loc":1533,"partial":1},
{"id":"b81-18","bab":"الجزء 8","sec":"قصة أبي سواج","page":"ج8 ص317","text":"بسه القس ثم أطلقه بعد شفاعة أخبرنا ابو خليفة قال حدثنا محمد بن سلام قال زعم محمد بن حفص بن عائشة التيمي عن إسحاق بن عبد الله بن الحارث بن نوفل بن الحارث بن عبد المطلب قال\nقدمت الشام وأنا شاب مع أبي فكنت أطوف في كنائسها ومساجدها فدخلت كنيسة دمشق وإذا الأخطل فيها محبوس فجعلت أنظر إليه فسأل عني فاخبر بنسبي فقال يا فتى إنك لرجل شريف وإني أسألك حاجة فقلت حاجتك مقضية قال إن القس حبسني ها هنا فتكلمه ليخلي عني فأتيت القس فانتسبت له فرحب وعظم قلت إن لي إليك حاجة قال ما حاجتك قلت الأخطل تخلي عنه قال أعيذك بالله من هذا مثلك لا يتكلم فيه فاسق يشتم أعراض الناس ويهجوهم فلم أزل أطلب إليه حتى مضى معي متكئا على عصاه فوقف عليه ورفع عصاه وقال يا عدو الله أتعود تشتم الناس وتهجوهم وتقذف المحصنات وهو يقول لست بعائد ولا أفعل ويستخذي له قال فقلت له يا ابا مالك الناس يهابونك والخليفة يكرمك وقدرك في الناس قدرك وأنت تخضع لهذا هذا الخضوع وتستخذي له قال فجعل يقول لي إنه الدين إنه الدين أخبرنا اليزيدي عن عمه عبيد الله عن ابن حبيب عن الهيثم بن عدي قال كانت امرأة الأخطل حاملا وكان متمسكا بدينه فمر به الأسقف يوما فقال لها الحقيه فتمسحي به فعدت فلم تلحق إلا ذنب حماره فتمسحت به ورجعت فقال لها هو وذنب حماره سواء أخبرنا أبو خليفة قال حدثنا ابن سلام قال حدثني يونس قال قال أبو الغراف سمع هشام بن عبد الملك الأخطل وهو يقول\n(إذا افتقرت إلى الذخائر لم تجد ... ذخرا يكون كصالح الأعمال)\nفقال هنيئا لك أبا مالك هذا الإسلام فقال له يا أمير المؤمنين ما زلت مسلما في ديني\nأخبرني أبو خليفة قال حدثنا ابن سلام قال حدثني يونس وعبد الملك وأبو الغراف فألفت ما قالوا قالوا أتى الأخطل الكوفة فأتى الغضبان بن القبعثري الشيباني فسأله في حمالة فقال إن شئت أعطيتك ألفين وإن شئت أعطيتك درهمين قال وما بال الألفين وما بال الدرهمين قال إن أعطيتك ألفين لم يعطكها إلا قليل وإن أعطيتك درهمين لم يبق في الكوفة بكري إلا أعطاك درهمين وكتبنا إلى إخواننا بالبصرة فلم يبق بكري بها إلا أعطاك درهمين فخفت عليهم المؤنة وكثر لك النيل فقال فهذه إذا فقال نقسمها لك على أن ترد علينا فكتب بالبصرة إلى سويد بن منجوف السدوسي فقدم البصرة فقال يونس في حديثه فنزل على مال الصلت بن حريث الحنفي فأخبر من سمعه يقول والله لا أزال أفعل ذلك ثم رجع الحديث الأول فأتى سويدا فأخبره بحاجته فقال نعم وأقبل على قومه فقال هذا أبو مالك قد اتاكم يسألكم أن تجمعوا له وهو الذي يقول\n(إذا ما قلت قد صالحت بكرا ... أبى البغضاء والنسب البعيد)\n(وأيام لنا ولهم طوال ... يعض الهام فيهن الحديد)\n(ومهراق الدماء بواردات ... تبيد المخزيات ولا تبيد)\n(هما أخوان يصطليان نارا ... رداء الحرب بينهما جديد)\nفقالوا فلا والله لا نعطيه شيئا فقال الأخطل\n(فإن تبخل سدوس بدرهميها ... فإن الريح طيبة قبول)\n(تواكلني بنو العلات منهم ... وغالت مالكا ويزيد غول)\n(صريعا وائل هلكا جميعا ... كأن الأرض بعدهما محول)\nقال في سويد بن منجوف وكان رجلا ليس بذي منظر\n(وما جذع سوء خرب السوس أصله ... لما حملته وائل بمطيق)","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":11,"spl":"قصة أبي سواج","loc":1534},
{"id":"b81-19","bab":"الجزء 8","sec":"كان مع مهارته يسقط أحيانا","page":"ج8 ص323","text":"أخبرنا أبو خليفة قال قال محمد بن سلام كان الأخطل مع مهارته وشعره يسقط أحيانا كان مدح سماكا الأسدي وهو سماك الهالكي من بني عمرو بن أسد وبنو عمرو يلقبون القيون ومسجد سماك بالكوفة معروف وكان من أهلها فخرج أيام علي هاربا فلحق بالجزيرة فمدحه الأخطل فقال\n(نعم المجير سماك من بني أسد ... بالقاع إذ قتلت جيرانها مضر)\n(قد كنت أحسبه قينا وأخبره ... فاليوم طير عن أثوابه الشرر)\n(إن سماكا بنى مجدا لأسرته ... حتى الممات وفعل الخير يبتدر)\nقال سماك يا أخطل أردت مدحي فهجوتني كان الناس يقولون قولا فحققته فلما هجا سويدا قال له سويد والله يا أبا مالك ما تحسن تهجو ولا تمدح لقد أردت مدح الأسدي فهجوته يعني قوله\n(قد كنت أحسبه قينا وأنبؤه ... فاليوم طير عن أثوابه الشرر)\n(إن سماكا بنى مجدا لأسرته ... حتى الممات وفعل الخير يبتدر)\nأردت هجائي فمدحتني جعلت وائلا حملتني أمورها وما طمعت في بني تغلب فضلا عن بكر أخبرنا أبو خليفة عن محمد بن سلام قال حدثني أبان البجلي قال مر الأخطل بالكوفة في بني رؤاس ومؤذنهم ينادي بالصلاة فقال له بعض فتيانهم ألا تدخل يا أبا مالك فتصلي فقال\n(أصلي حيث تدركني صلاتي ... وليس البر عند بني رؤاس)\nخبرنا أبو خليفة عن محمد بن سلام قال حدثني أبو الحصين الأموي قال بينا الأخطل قد خلا بخميرة له في نزهة مع صاحب له وطرأ عليهما طارىء لا يعرفانه ولا يستخفانه فشرب شرابهما وثقل عليهما فقال الأخطل في ذلك\n(وليس القذى بالعود يسقط في الإنا ... ولا بذباب خطبه أيسر الأمر)\n(ولكن شخصا لا نسر بقربه ... رمتنا به الغيطان من حيث لا ندري)\nيروى\n(ولكن قذاها زائر لا نحبه ... )\nوهو الجيد الغناء لإبراهيم خفيف ثقيل بالوسطى عن عمرو وقد أخبرنا بهذا الخبر محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري قال حدثنا الهيثم بن عدي عن ابن عياش قال بينا الأخطل جالس عند امرأة من قومه وكان أهل البدو إذ ذاك يتحدث رجالهم إلى النساء لا يرون بذلك بأسا وبين يديه باطية شراب والمرأة تحدثه وهو يشرب إذ دخل رجل فجلس فثقل على الأخطل وكره أن يقول له قم استحياء منه وأطال الرجل الجلوس إلى أن أقبل ذباب فوقع في الباطية في شرابه فقال الرجل يا أبا مالك الذباب في شرابك فقال\n(وليس القذى بالعود يسقط في الخمر ... ولا بذباب نزعه أيسر الأمر)\n(ولكن قذاها زائر لا نحبه ... رمتنا به الغيطان من حيث لا ندري)\nال فقام الرجل فانصرف وأخبرني عمي رحمه الله بهذا الحديث عن الكراني عن الزيادي عن علي بن الحفار أخي أبي الحجاج أن الأخطل جاء إلى معبد في قدمة قدمها إلى الشام فقال له معبد إني أحب محادثتك فقال له وأنا أحب ذلك وقاما يتصبحان الغدران حتى وقفا على غدير فنزلا وأكلا فتبعهما أعرابي فجلس معهما وذكر الخبر مثل الذي قبله أخبرنا أبو خليفة عن محمد بن سلام قال قال أبان بن عثمان حدثني أبي قال دعا الأخطل شاب من شباب أهل الكوفة إلى منزله فقال له يابن أخي\nأنت لا تحتمل المئونة وليس عندك معتمد فلم يزل به حتى انتجعه فأتى الباب فقال يا شقراء فخرجت إليه امرأة فقال لأمه هذا أبو مالك قد أتاني فباعت غزلا لها واشترت له لحما ونبيذا وريحانا فدخل خصا لها فأكل معه وشرب وقال في ذلك\n(وبيت كظهر الفيل جل متاعه ... أباريقه والشارب المتقطر)\n(ترى فيه أثلام الأصيص كأنها ... إذا بال فيها الشيخ جفر معور)\n(لعمرك ما لاقيت يوم معيشة ... من الدهر إلا يوم شقراء أقصر)\n(حوارية لا يدخل الذم بيتها ... مطهرة يأوي إليها مطهر)\nذكر هارون بن الزيات هذا الخبر عن حماد عن أبيه أنه كان نازلا على عكرمة الفياض وأنه خرج من عنده يوما فمر بفتيان يشربون ومعهم قينة يقال لها شقراء وذكر الخبر مثل ما قبله وزاد فيه فأقام عندهم أربعة أيام وظن عكرمة أنه غضب فانصرف عنه فلما أتاه اخبره بخبره فبعث إلى الفتيان بألف درهم وأعطاه خمسة آلاف فمضى بها إليهم وقال استعينوا بهذه على أمركم ولم يزل ينادمهم حتى رحل","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":12,"spl":"كان مع مهارته يسقط أحيانا","song":1,"loc":1535,"partial":1},
{"id":"b81-20","bab":"الجزء 8","sec":"اجتماع الشعراء الثلاثة عند بشر بن مروان","page":"ج8 ص326","text":"أخبرني أبو خليفة عن محمد بن سلام قال حدثني أبو يحيى الضبي قال اجتمع الفرزدق وجرير والأخطل عند بشر بن مروان وكان بشر يغري بين الشعراء فقال للأخطل احكم بين الفرزدق وجرير فقال اعفني أيها الأمير\nقال احكم بينهما فاستعفاه بجهده فأبى إلا أن يقول فقال هذا حكم مشؤوم ثم قال الفرزدق ينحت من صخر وجرير يغرف من بحر فلم يرض بذلك جرير وكان سبب الهجاء بينهما فقال جرير في حكومته\n(يا ذا الغباوة إن بشرا قد قضى ... ألا تجوز حكومة النشوان)\n(فدعوا الحكومة لستم من أهلها ... إن الحكومة في بني شيبان)\n(قتلوا كليبكم بلقحة جارهم ... يا خزر تغلب لستم بهجان)\nقال الأخطل يرد على جرير\n(ولقد تناسبتم إلى أحسابكم ... وجعلتم حكما من السلطان)\n(فإذا كليب لا تساوي دارما ... حتى يساوى حزرم من بأبان)\n(وإذا جعلت أباك في ميزانهم ... رجحوا وشال أبوك في الميزان)\n(وإذا وردت الماء كان لدارم ... عفواته وسهولة الأعطان)\nم استطار في الهجاء","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":13,"spl":"اجتماع الشعراء الثلاثة عند بشر بن مروان — مناقضة بينه وبين جرير","loc":1536},
{"id":"b81-21","bab":"الجزء 8","sec":"مناقضة بينه وبين جرير","page":"ج8 ص327","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثنا أبو الغراف قال\nلما قال جرير\n(إذا أخذت قيس عليك وخندف ... بأقطارها لم تدر من اين تسرح)\nال الأخطل لا أين سد والله علي الدنيا فلما أنشد قوله\n(فما لك في نجد حصاة تعدها ... وما لك من غوري تهامة أبطح)\nال الأخطل لا أبالي والله ألا يكون فتح لي والصليب القول ثم قال\n(ولكن لنا بر العراق وبحره ... وحيث ترى القرقور في الماء يسبح)\nخبرنا أبو خليفة عن محمد بن سلام قال حدثني محمد بن الحجاج الأسيدي قال خرجت إلى الصائفة فنزلت منزلا ببني تغلب فلم أجد به طعاما ولا شرابا ولا علفا لدوابي شرى ولا قرى ولم أجد ظلا فقلت لرجل منهم ما في داركم هذه مسجد يستظل فيه فقال ممن أنت قلت من بني تميم قال ما كنت أرى عمك جريرا إلا قد أخبرك حين قال\n(فينا المساجد والإمام ولا ترى ... في آل تغلب مسجدا معمورا)\nخبرني أبو خليفة قال أنبأنا محمد بن سلام قال حدثني شيخ من ضبيعة قال خرج جرير إلى الشام فنزل منزلا ببني تغلب فخرج متلثما عليه ثياب سفره فلقيه رجل لا يعرفه فقال ممن الرجل قال من بني تميم قال أما سمعت ما قلت لغاوي بني تميم فأنشده مما قال لجرير فقال أما سمعت\nما قال لك غاوي بني تميم فأنشده ثم عاد الأخطل وعاد جرير في نقضه حتى كثر ذلك بينهما فقال التغلبي من أنت لا حياك الله والله لكأنك جرير قال فأنا جرير قال وأنا الأخطل","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":13,"spl":"اجتماع الشعراء الثلاثة عند بشر بن مروان — مناقضة بينه وبين جرير","loc":1537},
{"id":"b81-22","bab":"الجزء 8","sec":"كان يدخل على عبد الملك وهو سكران","page":"ج8 ص329","text":"أخبرني عمي قال أنبأنا الكراني قال أنبأنا أبو عبد الرحمن عن المدائني قال دخل الأخطل على عبد الملك وقد شرب فكلمه فخلط في كلامه فقال له ما هذا فقال\n(إذا شرب الفتى منها ثلاثا ... بغير الماء حاول أن يطولا)\n(مشى قرشية لا عيب فيها ... وأرخى من مآزره الفضولا)\nخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل قال أخبرني إسماعيل بن أبي محمد اليزيدي قال أخبرني أبو محمد اليزيدي قال خرج الفرزدق يؤم بعض الملوك من بني أمية فرفع له في طريقه بيت أحمر من أدم فدنا منه وسأل فقيل له بيت الأخطل فأتاه فقال انزل فلما نزل قام إليه الأخطل وهو لا يعرفه إلا أنه ضيف فقعدا يتحدثان فقال له الأخطل ممن الرجل قال من بني تميم قال فإنك إذا من رهط أخي الفرزدق فقال تحفظ من شعره شيئا قال نعم كثيرا فما زالا يتناشدان ويتعجب الأخطل من حفظه شعر الفرزدق إلى أن عمل فيه الشراب وقد كان الأخطل قال له قبل ذلك أنتم معشر الحنيفية لا ترون أن تشربوا من شرابنا فقال له الفرزدق خفض قليلا وهات من شرابك فاسقنا فلما عملت الراح في أبي فراس قال أنا والله الذي أقول في جرير فأنشده فقام إليه الأخطل\nفقبل رأسه وقال لا جزاك الله عني خيرا لم كتمتني نفسك منذ اليوم وأخذا في شرابهما وتناشدهما إلى أن قال له الأخطل والله إنك وإياي لأشعر منه ولكنه أوتي من سير الشعر ما لم نؤته قلت أنا بيتا ما أعلم أن أحدا أهجى منه قلت\n(قوم إذا استنبح الأضياف كلبهم ... قالوا لأمهم بولي على النار)\nلم يروه إلا حكماء أهل الشعر وقال هو\n(والتغلبي إذا تنحنح للقرى ... حك استه وتمثل الأمثالا)\nفلم تبق سقاة ولا أمثالها إلا رووه فقضيا له أنه أسير شعرا منهما أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال قال المدائني كان للأخطل الشاعر دار ضيافة فمر به عكرمة الفياض وهو لا يعرفه فقيل له هذا رجل شريف قد نزل بنا فلما أمسى بعث إليه فتعشى معه ثم قال له أتصيب من الشراب شيئا قال نعم قال أيه قال كله إلا شرابك فدعا له بشراب يوافقه وإذا عنده قينتان هما خلفه وبينه وبينهما ستر وإذا الأخطل أشهب اللحية له ضفيرتان فغمز الستر بقضيب في يده وقال غنياني بأردية الشعر فغنتاه بقول عمرو بن شأس\n(وبيض تطلى بالعبير كأنما ... يطأن وإن أعنقن في جدد وحلا)\n(لهونا بها يوما ويوما بشارب ... إذا قلت مغلوبا وجدت له عقلا)\nفأما السبب في مدح الأخطل عكرمة بن ربعي الفياض فأخبرنا به أبو خليفة عن محمد بن سلام قال قدم الأخطل الكوفة فأتى حوشب بو رويم الشيباني فقال إني تحملت حمالتين لأحقن بهما دماء قومي فنهره فأتى سيار بن البزيعة فسأله فاعتذر إليه فأتى عكرمة الفياض وكان كاتبا لبشر بن مروان فسأله وأخبره بما رد عليه الرجلان فقال أما إني لا أنهرك ولا أعتذر إليك ولكني أعطيك إحداهما عينا والأخرى عرضا قال وحدث أمر بالكوفة فاجتمع له الناس في المسجد فقيل له إن أردت أن تكافىء عكرمة يوما فاليوم فلبس جبة خز وركب فرسا وتقلد صليبا من ذهب وأتى باب المسجد ونزل عن فرسه فلما رآه حوشب وسيار نفسا عليه ذلك وقال عكرمة يا ابا مالك فجاء فوقف وابتدأ ينشد قصيدته\n(لمن الديار بحائل فوعال ... )\nتى انتهى إلى قوله\n(إن ابن ربعي كفاني سيبه ... ضغن العدو وغدرة المحتال)\n(أغليت حين تواكلتني وائل ... إن المكارم عند ذاك غوال)\n(ولقد مننت على ربيعة كلها ... وكفيت كل مواكل خذال)\n(كابن البزيعة أو كآخر مثله ... أولى لك ابن مسيمة الأجمال)\n(إن اللئيم إذا سألت بهرته ... وترى الكريم يراح كالمختال)\n(وإذا عدلت به رجالا لم تجد ... فيض الفرات كراشح الأوشال)\nال فجعل عكرمة يبتهج ويقول هذه والله أحب إلي من حمر النعم\nومما في شعر الأخطل من الأصوات المختارة","topic":"ذكر الأخطل وأخباره ونسبه","topicNo":81,"sp":14,"spl":"كان يدخل على عبد الملك وهو سكران","loc":1538,"partialRef":{"sid":"b81-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b82-1","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص332","text":"(أراعك بالخابور نوق وأجمال ... ودار عفتها الريح بعدي بأذيال)\n(ومبنى قباب المالكية حولنا ... وجرد تعادى بين سهل وأجبال)\nروضه من الطويل الشعر للأخطل والغناء لابن محرز ولحنه المختار من خفيف الثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه خفيف رمل في هذا الوجه نسبه يحيى المكي إلى ابن محرز وذكر الهشامي أنه منحول وفيه لحنين الحيري ثقيل أول عن الهشامي","topic":"ذكر سائب خاثر ونسبه","topicNo":82,"sp":0,"spl":"صوت من المائة المختارة — نسبة هذا الصوت","loc":1539},
{"id":"b82-2","bab":"الجزء 8","sec":"ذكر سائب خاثر ونسبه","page":"ج8 ص333","text":"كان سائب خاثر مولى بني ليث وأصله من فيء كسرى واشترى عبد الله بن جعفر ولاءه من مواليه وقيل بل اشتراه فأعتقه وقيل بل كان على ولائه لبني ليث وإنما انقطع إلى عبد الله بن جعفر فلزمه وعرف به وكان يبيع الطعام بالمدينة واسم أبيه الذي أعتقه بنو ليث يشا\nقال ابن الكلبي وأبو غسان وغيرهما هو أول من عمل العود بالمدينة وغنى به وقال ابن خرداذبه كان عبد الله بن عامر اشترى إماء صناجات وأتى بهن المدينة فكان لهن يوم في الجمعة يلعبن فيه وسمع الناس منهن فأخذ عنهن ثم قدم رجل فارسي بنشيط فغنى فأعجب عبد الله بن جعفر به فقال له سائب خاثر أنا أصنع لك مثل غناء هذا الفارسي بالعربية ثم غدا على عبد الله بن جعفر وقد صنع\n(لمن الديار رسومها قفر ... )\nال ابن الكلبي وهو أول صوت غني به في الإسلام من الغناء العربي المتقن الصنعة قال ثم اشترى عبد الله بن جعفر نشيطا بعد ذلك فأخذ عن سائب خاثر الغناء العربي وأخذ عنه ابن سريج وجميلة ومعبد وعزة الميلاء وغيرهم قال ابن الكلبي وحدثني أبو مسكين قال\nكان سائب خاثر يكنى أبا جعفر ولم يكن يضرب بالعود إنما كان يقرع بقضيب ويغني مرتجلا ولم يزل يغني وقتل يوم الحرة ومر به بعض القرشيين وهو قتيل فضربه برجله وقال إن ها هنا لحنجرة حسنة وكان سائب من ساكني المدينة قال ابن الكلبي وكان سائب تاجرا موسرا يبيع الطعام وكان تحته أربع نسوة وكان انقطاعه إلى عبد الله بن جعفر وكان مع ذلك يخالط سروات الناس وأشرافهم لظرفه وحلاوته وحسن صوته وكان قد آلى ألا يغني أحدا سوى عبد الله بن جعفر إلا أن يكون خليفة أو ولي عهد أو ابن خليفة فكان على ذلك إلى أن قتل قال وأخذ معبد عنه غناء كثيرا فنحل الناس بعضه إليه وأهل العلم بالغناء يعرفون ذلك وزعم ابن خرداذبه أن أم محمد بن عمرو الواقدي القاضي المحدث بنت عيسى بن جعفر بن سائب خاثر","topic":"ذكر سائب خاثر ونسبه","topicNo":82,"sp":0,"spl":"صوت من المائة المختارة — نسبة هذا الصوت","loc":1540,"partial":1},
{"id":"b82-3","bab":"الجزء 8","sec":"هو أول من غنى بالعربية الغناء الثقيل","page":"ج8 ص334","text":"وقال ابن الكلبي سائب خاثر أول من غنى بالعربية الغناء الثقيل وأول لحن صنعه منه\n(لمن الديار رسومها قفر ... )\nال فألفت هذا الصوت الفروح قال وحدثني محمد بن يزيد أن أول صوت صنعه في شعر امرىء القيس\n(أفاطم مهلا بعض هذا التدلل ... )\nوأن معبدا أخذ لحنه فيه فغنى عليه\n(أمن آل ليلى باللوى متربع ... )\nخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن الكلبي عن لقيط قال وفد عبد الله بن جعفر على معاوية ومعه سائب خاثر فوقع له في حوائجه ثم عرض عليه حاجة لسائب خاثر فقال معاوية من سائب خاثر قال رجل من أهل المدينة ليثي يروي الشعر قال أوكل من روى الشعر أراد أن نصله قال إنه حسنه قال وإن حسنه قال أفأدخله إليك يا أمير المؤمنين قال نعم قال فألبسته ممصرتين إزارا ورداء فلما دخل قام على الباب ثم رفع صوته يتغنى\n(لمن الديار رسومها قفر ... )\nالتفت معاوية إلى عبد الله بن جعفر فقال أشهد لقد حسنه فقضى حوائجه وأحسن إليه","topic":"ذكر سائب خاثر ونسبه","topicNo":82,"sp":0,"spl":"صوت من المائة المختارة — نسبة هذا الصوت","loc":1541,"partialRef":{"sid":"b82-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b82-4","bab":"الجزء 8","sec":"نسبة هذا الصوت","page":"ج8 ص335","text":"(لمن الديار رسومها قفر ... لعبت بها الأرواح والقطر)\n(وخلا لها من بعد ساكنها ... حجج مضين ثمان او عشر)\n(والزعفران على ترائبها ... شرق به اللبات والنحر)\nلشعر ينسب إلى أبي بكر بن المسور بن مخرمة الزهري وإلى الحارث بن خالد المخزومي وإلى بعض القرشيين من السبعة المعدودين\nمن شعراء العرب والغناء لسائب خاثر ثقيل أول بالسبابة عن الكلبي وحبش وذكر أن لحن سائب خاثر ثقيل أول بالوسطى ووافق إسحاق في ذلك وذكر أن الثقيل الأول لنشيط وذكر يونس أن فيه لحنا لمعبد ولم يجنسه وذكر الهشامي أن لحن معبد خفيف ثقيل وأن فيه لابن سريج خفيف رمل","topic":"ذكر سائب خاثر ونسبه","topicNo":82,"sp":0,"spl":"صوت من المائة المختارة — نسبة هذا الصوت","loc":1542},
{"id":"b82-5","bab":"الجزء 8","sec":"سمعه معاوية فأعجب به","page":"ج8 ص336","text":"أخبرنا أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري وإسماعيل بن يونس قالوا حدثنا عمر بن شبة قال حدثني قبيصة بن عمرو قال حدثنا محمد بن المنهال عن رجل حدثه وذكر ذلك أيضا ابن الكلبي عن لقيط قال أشرف معاوية بن أبي سفيان ليلا على منزل يزيد ابنه فسمع صوتا أعجبه واستخفه السماع فاستمع قائما حتى مل ثم دعا بكرسي فجلس عليه واشتهى الاستزادة فاستمع بقية ليلته حتى مل فلما أصبح غدا عليه يزيد فقال له يا بني من كان جليسك البارحة قال أي جليس يا أمير المؤمنين واستعجم عليه قال عرفني فإنه لم يخف علي شيء من أمرك قال سائب خاثر قال فأخثر له يا بني من برك وصلتك فما رأيت بمجالسته بأسا قال ابن الكلبي قدم معاوية المدينة في بعض ما كان يقدم فأمر حاجبه بالإذن للناس فخرج الآذن ثم رجع فقال ما بالباب أحد فقال معاوية وأين الناس قال عند ابن جعفر فدعا ببغلته فركبها ثم توجه إليهم فلما جلس قال\nبعض القرشيين لسائب خاثر مطرفي هذا لك وكان من خز إن أنت اندفعت تغني ومشيت بين السماطين وأنت تغني فقام ومشى بين السماطين وغنى\n(لنا الجفنات الغر يلمعن بالضحى ... وأسيافنا يقطرن من نجدة دما)\nسمع منه معاوية وطرب وأصغى إليه حتى سكت وهو مستحسن لذلك ثم قام وانصرف إلى منزله وأخذ سائب خاثر المطرف","topic":"ذكر سائب خاثر ونسبه","topicNo":82,"sp":1,"spl":"سمعه معاوية فأعجب به — قتل يوم الحرة","loc":1543},
{"id":"b82-6","bab":"الجزء 8","sec":"قتل يوم الحرة","page":"ج8 ص337","text":"أخبرني حبيب بن نصر عن عمر بن شبة عن الزبيري وأخبرني ابو بكر بن أبي شيبة البزاز قال حدثنا أحمد بن الحارث الخزاز عن المدائني قال\nقتل سائب خاثر يوم الحرة وكان خشي على نفسه من أهل الشام فخرج إليهم وجعل يحدثهم ويقول أنا مغن ومن حالي وقصتي كيت وكيت وقد خدمت أمير المؤمنين يزيد وأباه قبله قالوا فغن لنا فجعل يغني فقام إليه أحدهم فقال له أحسنت والله ثم ضربه بالسيف فقتله وبلغ يزيد خبره ومر به اسمه في أسماء من قتل يومئذ فلم يعرفه وقال من سائب خاثر هذا فقيل له هو سائب خاثر المغني فعرفه فقال ويله ما له ولنا ألم نحسن إليه ونصله ونخلطه بأنفسنا فما الذي حمله على عداوتنا لا جرم أن بغيه صرعه وقال المدائني في خبره فقال إنا لله أو بلغ القتل إلى سائب خاثر وطبقته ما أرى أنه بقي بالمدينة أحد ثم قال قبحكم الله يا أهل الشام تجدهم صادفوه في حديقة أو حائط مستترا منهم فقتلوه\nأخبرني أحمد بن عبد العزيز قال أنبأنا عمر بن شبة قال حدثني قبيصة بن\nعمرو قال حدثني حاتم بن قبيصة قال حدثني ابن جعدبة قال حدثني مويلك عن أبيه قال قال لي سائب خاثر يوم الحرة هل سمعت شيئا صنعته فغناني صوتا\n(لمن طلل بين الكراع إلى القصر ... يغيب عنا آية سبل القطر)\n(إلى خالدات ما تريم وهامد ... وأشعث ترسيه الوليدة بالفهر)\nال فسمعت عجبا معجبا ثم ذكر أهله وولده فبكى فقلت له وما يمنعك منهم فقال أما بعد شيء سمعته ورأيته من يزيد بن معاوية فلا ثم تقدم حتى قتل","topic":"ذكر سائب خاثر ونسبه","topicNo":82,"sp":1,"spl":"سمعه معاوية فأعجب به — قتل يوم الحرة","song":1,"loc":1544},
{"id":"b83-1","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص338","text":"(أقفر من أهله مصيف ... فبطن نخلة فالعريف)\n(هل تبلغني ديار قومي ... مهرية سيرها زفيف)\n(يا أم نعمان نولينا ... قد ينفع النائل الطفيف)\n(أعمامها الصيد من لؤي ... حقا وأخوالها ثقيف)\nلشعر لأبي فرعة الكناني والغناء لجرادتي عبد الله بن جدعان ولحنه من خفيف الثقيل وفيه في الثالث والرابع ثقيل أول مطلق","topic":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان","topicNo":83,"sp":0,"spl":"صوت من المائة المختارة","loc":1545},
{"id":"b83-2","bab":"الجزء 8","sec":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان","page":"ج8 ص340","text":"هو عبد الله بن جدعان بن عمرو بن كعب بن سعد بن تيم بن مرة بن كعب بن لؤي بن غالب قال ابن الكلبي كانت لابن جدعان أمتان تسميان الجرادتين تتغنيان في الجاهلية سماهما بجرادتي عاد ووهبهما عبد الله بن جدعان لأمية بن أبي الصلت الثقفي وقد كان امتدحه وكان ابن جدعان سيدا جوادا فرأى أمية ينظر إليهما وهو عنده فأعطاه إياهما وأخبرني أبو الليث نصر بن القاسم الفرائضي قال حدثنا أبو بكر بن أبي شيبة قال حدثنا حفص بن غياث عن داود عن الشعبي عن مسروق عن عائشة قالت قلت يا رسول الله إن ابن جدعان كان في الجاهلية يصل الرحم ويطعم المسكين فهل ذلك نافعه قال لا لم يقل يوما اغفر لي خطيئتي يوم الدين أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني جعفر بن الحسين قال حدثني إبراهيم بن أحمد قال قدم أمية بن أبي الصلت على عبد الله بن جدعان فلما دخل عليه قال\nله عبد الله أمر ما أتى بك فقال أمية كلاب غرماء نبحتني ونهشتني فقال له عبد الله قدمت علي وأنا عليل من حقوق لزمتني ونهشتني فأنظرني قليلا ما في يدي وقد ضمنتك قضاء دينك ولا اسأل عن مبلغه قال فأقام أمية أياما فأتاه فقال\n(أأذكر حاجتي أم قد كفاني ... حياؤك إن شيمتك الحياء)\n(وعلمك بالأمور وأنت قرم ... لك الحسب المهذب والسناء)\n(كريم لا يغيره صباح عن الخلق السني ولا مساء ... )\n(تباري الريح مكرمة وجودا ... إذا ما الكلب أجحره الشتاء)\n(إذا أثنى عليك المرء يوما ... كفاه من تعرضه الثناء)\n(إذا خلفت عبد الله فاعلم ... بأن القوم ليس لهم جزاء)\n(فأرضك كل مكرمة بناها ... بنو تيم وأنت لهم سماء)\n(فأبرز فضله حقا عليهم ... كما برزت لناظرها السماء)\n(فهل تخفى السماء على بصير ... وهل بالشمس طالعة خفاء)\nلما أنشده أمية هذا الشعر كانت عنده قينتان فقال خذ أيتهما شئت فأخذ إحداهما وانصرف فمر بمجلس من مجالس قريش فلاموه على أخذها وقالوا له لقد لقيته عليلا فلو رددتها عليه فإن الشيخ يحتاج إلى خدمتها كان ذلك أقرب لك عنده وأكثر من كل حق ضمنه لك فوقع الكلام من أمية موقعا وندم ورجع إليه ليردها عليه فلما أتاه بها قال له ابن جدعان لعلك إنما رددتها لأن قريشا لاموك على أخذها وقالوا كذا وكذا فوصف لأمية ما قال له القوم فقال أمية والله ما أخطأت يا أبا زهير فقال عبد الله بن جدعان فما الذي قلت في ذلك فقال أمية\n\n(عطاؤك زين لامرىء إن حبوته ... ببذل وما كل العطاء يزين)\n(وليس بشين لامرىء بذل وجهه ... إليك كما بعض السؤال يشين)\nنت فيه جرادتا عبد الله بن جدعان فقال عبد الله لأمية خذ الأخرى فأخذهما جمعا وخرج فلما صار إلى القوم بهما أنشأ يقول وقد أنشدنا هذه الأبيات أحمد بن عبد العزيز الجوهري عن عمر بن شبة وفيها زيادة\n(وما لي لا أحييه وعندي ... مواهب يطلعن من النجاد)\n(لأبيض من بني تيم بن كعب ... وهم كالمشرفيات الحداد)\n(لكل قبيلة هاد ورأس ... وأنت الرأس تقدم كل هادي)\n(له بالخيف قد علمت معد ... وإن البيت يرفع بالعماد)\n(له داع بمكة مشمعل ... وآخر فوق دارته ينادي)\n(إلى ردح من الشيزى ملاء ... لباب البر يلبك بالشهاد)\nقال فيه أيضا\n(ذكر ابن جدعان بخير ... كلما ذكر الكرام)\n(من لا يخون ولا يعق ... ولا تغيره اللئام)\n(نجب النجيبة والنجيب ... له الرحالة والزمام)\nأخبرني محمد بن العباس اليزيدي قال حدثنا محمد بن إسحاق البغوي قال حدثنا الأثرم عن أبي عبيدة قال كان ابن جدعان سيدا من قريش فوفد على كسرى فأكل عنده الفالوذ فسأل عنه فقيل له هذا الفالوذ قال وما الفالوذ قالوا لباب البر يلبك مع عسل النحل قال ابغوني غلاما يصنعه فأتوه بغلام يصنعه فابتاعه ثم قدم به مكة معه ثم أمره فصنع له الفالوذ بمكة فوضع الموائد بالأبطح إلى باب المسجد ثم نادى مناديه ألا من أراد الفالوذ فليحضر فحضر الناس فكان فيمن حضر أمية بن أبي الصلت فقال فيه\n(وما لي لا أحييه وعندي ... مواهب يطلعن من النجاد)\n(إلي وإنه للناس نهي ... ولا يعتل بالكلم الصوادي)\nذكر باقي الأبيات التي مضت متقدما حدثنا أحمد بن عبيد الله بن عمار قال أخبرنا يعقوب بن إسرائيل مولى المنصور قال حدثني محمد بن عمران الجرجاني وليس بصاحب إسحاق الموصلي قال وهو شيخ لقيته بجرجان قال حدثنا الحسين بن الحسن المروزي قال","topic":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان","topicNo":83,"sp":1,"spl":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان","song":1,"loc":1546,"partial":1},
{"id":"b83-3","bab":"الجزء 8","sec":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان","page":"ج8 ص340","text":"سألت سفيان بن عيينة فقلت يا أبا محمد ما تفسير قول النبي وعلى آله كان من أكثر دعاء الأنبياء قبلي لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير وإنما هو ذكر وليس فيه من الدعاء شيء فقال لي أعرفت حديث مالك بن الحارث يقول الله جل ثناؤه إذا شغل عبدي ثناؤه علي عن مسألتي أعطيته أفضل\nما أعطي السائلين قلت نعم أنت حدثتنيه عن منصور عن مالك بن الحارث قال فهذا تفسير ذلك ثم قال أما علمت ما قال أمية بن الصلت حين خرج إلى ابن جدعان يطلب نائله وفضله قلت لا أدري قال قال\n(أأذكر حاجتي أم قد كفاني ... حياؤك إن شيمتك الحياء)\n(إذا أثنى عليك المرء يوما ... كفاه من تعرضه الثناء)\nم قال سفيان فهذا مخلوق ينسب إلى الجود فقيل له يكفينا من مسألتك أن نثني عليك ونسكت حتى تأتي على حاجتنا فكيف بالخالق\nأخبرني الحرمي قال حدثنا الزبير قال حدثنا حميد بن حميد قال حدثني جبار بن جابر قال\nدخل أمية بن أبي الصلت على عبد الله بن جدعان وهو يجود بنفسه فقال له أمية كيف تجدك أبا قال زهير إني لمدابر أي ذاهب فقال أمية\n(علم ابن جدعان بن عمرو ... أنه يوما مدابر)\n(ومسافر سفرا بعيدا ... لا يؤوب به المسافر)\n(فقدوره بفنائه ... للضيف مترعة زواخر)\n(تبدو الكسور من انضراج ... الغلي فيها والكراكر)\n(فكأنهن بما حمين ... وما شحن بها ضرائر)\n(بذ المعاشر كلها ... بالفضل قد علم المعاشر)\n(وعلا علو الشمس حتى ... ما يفاخره مفاخر)\n(دانت له أبناء فهر ... من بني كعب وعامر)\n(أنت الجواد ابن الجواد ... بكم ينافر من ينافر)","topic":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان","topicNo":83,"sp":2,"spl":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان — شعره في ذم الخمر","loc":1547},
{"id":"b83-4","bab":"الجزء 8","sec":"شعره في ذم الخمر","page":"ج8 ص344","text":"أخبرني علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري قال أخبرني أبو عبد الرحمن الغلابي عن الواقدي عن ابن أبي الزناد قال ما مات أحد من كبراء قريش في الجاهلية إلا ترك الخمر استحياء مما فيها من الدنس ولقد عابها ابن جدعان قبل موته فقال\n(شربت الخمر حتى قال قومي ... ألست عن السفاه بمستفيق)\n(وحتى ما أوسد في مبيت ... أنام به سوى الترب السحيق)\n(وحتى أغلق الحانوت رهني ... وآنست الهوان من الصديق)\nال وكان سبب تركه الخمر أن أمية بن أبي الصلت شرب معه فأصبحت عين أمية مخضرة يخاف عليها الذهاب فقال له ما بال عينك فسكت فلما ألح عليه قال له أنت صاحبها أصبتها البارحة فقال أوبلغ مني الشراب الذي أبلغ معه من جليسي هذا لا جرم لأدينها لك ديتين فأعطاه عشرة آلاف درهم وقال الخمر علي حرام أن أذوقها أبدا وتركها من يومئذ","topic":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان","topicNo":83,"sp":2,"spl":"ذكر جرادتي عبد الله بن جدعان وخبرهما وشيء من أخبار ابن جدعان — شعره في ذم الخمر","loc":1548},
{"id":"b84-1","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص345","text":"(قد لعمري بت ليلي ... كأخي الداء الوجيع)\n(ونجي الهم مني ... بات أدنى من ضجيعي)\n(كلما أبصرت ربعا ... خاليا فاضت دموعي)\n(لا تلمنا إن خشعنا ... أو هممنا بالخشوع)\n(إذ فقدنا سيدا كان ... لنا غير مضيع)\nلشعر للأحوص والغناء لسلامة القس ولحنه المختار من القدر الأوسط من الثقيل الأول بالوسطى في مجراها وقد قيل إن الشعر والغناء جميعا لها وقد قيل إن الغناء لمعبد وإنها أخذته عنه","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":0,"spl":"صوت من المائة المختارة — سبب افتتان القس بها","loc":1549},
{"id":"b84-2","bab":"الجزء 8","sec":"ذكر سلامة القس وخبرها","page":"ج8 ص347","text":"كانت سلامة مولدة من مولدات المدينة وبها نشأت وأخذت الغناء عن معبد وابن عائشة وجميلة ومالك بن أبي السمح وذويهم فمهرت وإنما سميت سلامة القس لأن رجلا يعرف بعبد الرحمن بن أبي عمار الجشمي من قراء أهل مكة وكان يلقب بالقس لعبادته شغف بها وشهر فغلب عليها لقبه واشتراها يزيد بن عبد الملك في خلافة سليمان وعاشت بعده وكانت إحدى من اتهم به الوليد من جواري أبيه حين قال له قتلته ننقم عليك أنك تطأ جواري أبيك وقد ذكرنا ذلك في خبر مقتله أخبرني الحسين بن يحيى عن حماد عن أبيه قال كانت حبابة وسلامة القس من قيان أهل المدينة وكانتا حاذقتين ظريفتين ضاربتين وكانت سلامة أحسنهما غناء وحبابة أحسنهما وجها وكانت سلامة تقول الشعر وكانت حبابة تتعاطاه فلا تحسن وأخبرني بذلك المدائني عن جرير وحدثني الزبيري قال حدثني من رأى سلامة قال ما رأيت من قيان المدينة فتاة ولا عجوزا أحسن غناء من سلامة وعن جميلة أخذت الغناء\nحدثني أحمد بن عبيد الله بن عمار وإسماعيل بن يونس قالا حدثنا أبو زيد عمر بن شبة قال حدثني المدائني قال كانت حبابة وسلامة قينتين بالمدينة أما سلامة فكانت لسهيل بن عبد الرحمن ولها يقول ابن قيس الرقيات\n(لقد فتنت ريا وسلامة القسا ... فلم تتركا للقس عقلا ولا نفسا)\n(فتاتان أما منهما فشبيهة الهلال ... وأخرى منهما تشبه الشمسا)\n(وغناه مالك بن أبي السمح وفيها يقول ابن قيس الرقيات ... )\n(أختان إحداهما كالشمس طالعة ... في يوم دجن وأخرى تشبه القمرا)\nال وفتن القس بسلامة وفيها يقول\n(أهابك أن أقول بذلت نفسي ... ولو أني أطيع القلب قالا)\n(حياء منك حتى سل جسمي ... وشق علي كتماني وطالا)","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":0,"spl":"صوت من المائة المختارة — سبب افتتان القس بها","loc":1550,"partial":1},
{"id":"b84-3","bab":"الجزء 8","sec":"سبب افتتان القس بها","page":"ج8 ص348","text":"قال والقس هو عبد الرحمن بن أبي عمار من بني جشم بن معاوية وكان منزله بمكة وكان سبب افتتانه بها فيما حدثني خلاد الأرقط قال سمعت من شيوخنا أهل مكة يقولون كان القس من أعبد أهل مكة وكان يشبه بعطاء بن أبي رباح وأنه سمع غناء سلامة القس على غير تعمد منه لذلك فبلغ غناؤها منه كل مبلغ فرآه مولاها فقال له هل لك أن أخرجها إليك\nأو تدخل فتسمع فأبى فقال مولاها أنا أقعدها في موضع تسمع غناءها ولا تراها فأبى فلم يزل به حتى دخل فأسمعه غناءها فأعجبه فقال له هل لك في أن أخرجها إليك فأبى فلم يزل به حتى أخرجها فأقعدها بين يديه فتغنت فشغف بها وشغفت به وعرف ذلك أهل مكة فقالت له يوما أنا والله أحبك قال وأنا والله أحبك قالت وأحب أن أضع فمي على فمك قال وأنا والله أحب ذلك قالت فما يمنعك فوالله إن الموضع لخال قال إني سمعت الله عز و جل يقول ( الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين\nوأنا أكره أن تكون خلة ما بيني وبينك تؤول إلى عداوة ثم قام وانصرف وعاد إلى ما كان عليه من النسك وقال من فوره فيها\n(إن التي طرقتك بين ركائب ... تمشي بمزهرها وأنت حرام)\n(لتصيد قلبك أو جزاء مودة ... إن الرفيق له عليك ذمام)\n(باتت تعللنا وتحسب أننا ... في ذاك أيقاظ ونحن نيام)\n(حتى إذا سطع الضياء لناظر ... فإذا وذلك بيننا أحلام)\n(قد كنت أعذل في السفاهة أهلها ... فاعجب لما تأتي به الأيام)\n(فاليوم أعذرهم وأعلم أنما ... سبل الضلالة والهدى أقسام)\nمن قوله فيها\n(ألم ترها لا يبعد الله دارها ... إذا رجعت في صوتها كيف تصنع)\n(تمد نظام القول ثم ترده ... إلى صلصل في صوتها يترجع)\nوفيها يقول ألا قل لهذا القلب هل أنت مبصر ... وهل أنت عن سلامة اليوم مقصر ألا ليت أني حين صارت بها النوى ... جليس لسلمى كلما عج مزهر\nقال في قصيدة له\n(سلام ويحك هل تحبين من ماتا ... أو ترجعين على المحزون ما فاتا)\nقال أيضا\n(سلام هلي لي منكم ناصر ... أم هل لقلبي عنكم زاجر)\n(قد سمع الناس بوجدي بكم ... فمنهم اللائم والعاذر)\nفي أشعار كثيرة يطول ذكرها","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":0,"spl":"صوت من المائة المختارة — سبب افتتان القس بها","loc":1551},
{"id":"b84-4","bab":"الجزء 8","sec":"هي وأختها ريا من أجمل النساء وأحسنهن غناء","page":"ج8 ص350","text":"وأخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني الجمحي قال كانت سلامة وريا أختين وكانتا من أجمل النساء وأحسنهن غناء فاجتمع الأحوص وابن قيس الرقيات عندهما فقال لهما ابن قيس الرقيات إني أريد أن أمدحكما بأبيات وأصدق فيها ولا أكذب فإن أنتما غنيتماني بذلك وإلا هجوتكما ولا أقربكما قالتا فما قلت قال قلت\n(لقد فتنت ريا وسلامة القسا ... فلم تتركا للقس عقلا ولا نفسا)\n(فتاتان أما منهما فشبيهة الهلال ... وأخرى منهما تشبه الشمسا)\n(تكنان أبشارا رقاقا وأوجها ... عتاقا وأطرافا مخضبة ملسا)\nغنته سلامة واستحسنتاه وقالتا للأحوص ما قلت يا أخا الأنصار قال قلت\n(أسلام هل لمتيم تنويل ... أم هل صرمت وغال ودك غول)\n(لا تصرفي عني دلالك إنه ... حسن لدي وإن بخلت جميل)\n(أزعمت أن صبابتي أكذوبة ... يوما وأن زيارتي تعليل)\nلغناء لسلامة القس خفيف ثقيل أول بالبنصر عن الهشامي وحماد وفيه لإبراهيم لحنان أحدهما خفيف ثقيل بالبنصر في مجراها عن إسحاق وعمرو والآخر ثقيل أوله استهلال عن الهشامي فغنت الأبيات فقال ابن قيس الرقيات يا سلامة أحسنت والله وأظنك عاشقة لهذا الحلقي فقال له الأحوص ما الذي أخرجك إلى هذا قال حسن غنائها بشعرك فلولا أن لك في قلبها محبة مفرطة ما جاءها هكذا حسنا على هذه البديهة فقال له الأحوص على قدر حسن شعري على شعرك هكذا حسن الغناء به وما هذا منك إلا حسد ونبين لك الآن ما حسدت عليه فقالت سلامة لولا أن الدخول بينكما يوجب بغضة لحكمت بينكما حكومة لا يردها أحد قال الأحوص فأنت من ذلك آمنة قال ابن قيس الرقيات كلا قد أمنت أن تكون الحكومة عليك فلذلك سبقت بالأمان لها قال الأحوص فرأيك يدلك على أن معرفتك بأن المحكوم عليه انت وتفرقا فلما صار الأحوص إلى منزله جاءه ابن قيس\nالرقيات فقرع بابه فأذن له وسلم عليه واعتذر ومما قاله الأحوص في سلامه القس وغني به\n(أسلام إنك قد ملكت فأسجحي ... قد يملك الحر الكريم فيسجح)\n(مني على عان أطلت عناءه ... في الغل عندك والعناة تسرح)\n(إني لأنصحكم وأعلم أنه ... سيان عندك من يغش وينصح)\n(وإذا شكوت إلى سلامة حبها ... قالت أجد منك ذا أم تمزح)\nلشعر للأحوص والغناء لابن مسجح في الأول والثاني ثقيل أول بالوسطى عن عمرو ولدحمان في الأربعة الأبيات ثقيل أول بالبنصر فيه استهلال وفيه خفيف ثقيل يقال إنه لمالك ويقال إنه لسلامة القس أخبرني الحسين عن حماد عن أبيه قال قال أيوب بن عباية كان عبد الرحمن بن عبد الله بن أبي عمار من بني جشم بن معاوية وكان فقيها عابدا من عباد مكة يسمى القس لعبادته وكانت سلامة بمكة لسهيل وكان يدخل عليها الشعراء فينشدونها وتنشدهم وتغني من أحب الغناء ففتن بها عبد الرحمن بن عبد الله بن أبي عمار القس فشاع ذاك وظهر فسميت سلامة القس بذلك","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":1,"spl":"هي وأختها ريا من أجمل النساء وأحسنهن غناء — غنت القس بشعر له","song":2,"loc":1552},
{"id":"b84-5","bab":"الجزء 8","sec":"غنت القس بشعر له","page":"ج8 ص352","text":"قال إسحاق وحدثني أيوب بن عباية قال سألها عبد الرحمن بن\nعبد الله بن أبي عمار القس أن تغنيه بشعر مدحها به ففعلت وهو\n(ما بال قلبك لا يزال يهيمه ... ذكر عواقب غيهن سقام)\n(إن التي طرقتك بين ركائب ... تمشي بمزهرها وأنت حرام)\n(لتصيد قلبك أو جزاء مودة ... إن الرفيق له عليك ذمام)\n(باتت تعللنا وتحسب أننا ... في ذاك أيقاظ ونحن نيام)\n(حتى إذا سطع الصباح لناظر ... فإذا وذلك بيننا أحلام)\n(قد كنت أعذل في السفاهة أهلها ... فاعجب لما تأتي به الأيام)\n(فاليوم أعذرهم وأعلم أنما ... سبل الغواية والهدى أقسام)\nال إسحاق وحدثني المدائني قال حدثني جرير قال لما قدم يزيد بن عبد الملك مكة وأراد شراء سلامة القس وعرضت عليه أمرها أن تغنيه فكان أول صوت غنته\n(إن التي طرقتك بين ركائب ... تمشي بمزهرها وأنت حرام)\n(والبيض تمشي كالبدور وكالدمى ... ونواغم يمشين في الأرقام)\nتصيد قلبك أو جزاء مودة ... إن الرفيق له عليك ذمام\nاستحسنه يزيد فاشتراها فكان أول صوت غنته لما اشتراها\n(ألا قل لهذا القلب هل أنت مبصر ... وهل أنت عن سلامة مقصر)\n(ألا ليت أني حين صار بها النوى ... جليس لسلمى حيث ما عج مزهر)\n(وإني إذا ما الموت زال بنفسها ... يزال بنفسي قبلها حين تقبر)\n(إذا أخذت في الصوت كاد جليسها ... يطير إليها قلبه حين ينظر)\n(كأن حماما راعبيا مؤديا ... إذا نطقت من صدرها يتغشمر)\nقال لها يزيد يا حبيبتي من قائل هذا الشعر فقصت عليه القصة فرق له وقال أحسن وأحسنت","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":1,"spl":"هي وأختها ريا من أجمل النساء وأحسنهن غناء — غنت القس بشعر له","loc":1553},
{"id":"b84-6","bab":"الجزء 8","sec":"غنت يزيد بن عبد الملك بشعر الأحوص","page":"ج8 ص353","text":"قال إسحاق وحدثني المدائني قال لما اشترى يزيد بن عبد الملك سلامة وكان الأحوص معجبا بها وبحسن غنائها وبكثرة مجالستها فلما أراد يزيد الرحلة قال ابياتا وبعث بها إلى سلامة فلما جاءها الشعر غنت به يزيد وأخبرته الخبر وهو\n(عاود القلب من سلامة نصب ... فلعيني من جوى الحب غرب)\n(ولقد قلت أيها القلب ذو الشوق ... الذي لا يحب حبك حب)\n(إنه قد دنا فراق سليمى ... وغدا مطلب عن الوصل صعب)\nناه ابن محرز ثاني ثقيل بالسبابة في مجرى البنصر عن إسحاق وفيه لابن مسجح خفيف ثقيل بالوسطى عن عمرو وفيه لابن عباد وعلويه رملان وفيه لدحمان خفيف رمل هذه الحكايات الثلاث عن الهشامي وذكر حبش أن لسلامة القس فيه ثاني ثقيل بالوسطى","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":2,"spl":"غنت يزيد بن عبد الملك بشعر الأحوص","song":1,"loc":1554},
{"id":"b84-7","bab":"الجزء 8","sec":"عتابها لحبابة لاستخفافها بها","page":"ج8 ص354","text":"قال إسحاق وحدثني أيوب بن عباية قال كانت سلامة وريا لرجل واحد\nوكانت حبابة لرجل وكانت المفدمة منهن سلامة حتى صارتا إلى يزيد بن عبد الملك فكانت حبابة تنظر إلى سلامة بتلك العين الجليلة المتقدمة وتعرف فضلها عليها فلما رأت أثرتها عند يزيد ومحبة يزيد لها استخفت بها فقال لها سلامة أي أخية نسيت لي فضلي عليك ويلك أين تأديب الغناء وأين حق التعليم أنسيت قول جميلة يوما وهي تطارحنا وهي تقول لك خذي إحكام ما أطارحك من أختك سلامة ولن تزالي بخير ما بقيت لك وكان أمركما مؤتلفا قالت صدقت خليلتي والله لا عدت إلى شيء تكرهينه فما عادت لها إلى مكروه وماتت حبابة وعاشت سلامة بعدها دهرا أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب عن عبد الرحمن بن المغيرة الحزامي الأكبر قال لما قدم عثمان بن حيان المري المدينة واليا عليها قال له قوم من وجوه الناس إنك قد وليت على كثرة من الفساد فإن كنت تريد أن تصلح فطهرها من الغناء والزنا فصاح في ذلك وأجل أهلها ثلاثا يخرجون فيها من المدينة وكان ابن أبي عتيق غائبا وكان من أهل الفضل والعفاف والصلاح فلما كان آخر ليلة من الأجل قدم فقال لا أدخل منزلي حتى أدخل على سلامة القس فدخل عليها فقال ما دخلت منزلي حتى جئتكم أسلم عليكم قالوا ما أغفلك عن أمرنا وأخبروه الخبر فقال اصبروا علي الليلة فقالوا نخاف ألا يمكنك شيء وننكظ قال إن خفتم شيئا فاخرجوا في السحر ثم خرج فاستأذن على عثمان بن حيان فأذن له فسلم عليه وذكر له غيبته وأنه جاءه\nليقضي حقه ثم جزاه خيرا على ما فعل من إخراج أهل الغناء والزنا وقال أرجو ألا تكون عملت عملا هو خير لك من ذلك قال عثمان قد فعلت ذلك وأشار به على أصحابك فقال قد أصبت ولكن ما تقول أمتع الله بك في امرأة كانت هذه صناعتها وكانت تكره على ذلك ثم تركته وأقبلت على الصلاة والصيام والخير وأتى رسولها إليك تقول اتوجه إليك وأعوذ بك أن تخرجني من جوار رسول الله ومسجده قال فإني أدعها لك ولكلامك قال ابن أبي عتيق لا يدعك الناس ولكن تأتيك وتسمع من كلامها وتنظر إليها فإن رأيت أن مثلها ينبغي أن يترك تركتها قال نعم فجاءه بها وقال لها اجعلي معك سبحة وتخشعي ففعلت فلما دخلت على عثمان حدثته وإذا هي من أعلم الناس بالناس وأعجب بها وحدثته عن آبائه وأمورهم ففكه لذلك فقال لها ابن أبي عتيق اقرئي للأمير فقرأت له فقال لها احدي له ففعلت فكثر تعجبه فقال كيف لو سمعتها في صناعتها فلم يزل ينزله شيئا شيئا حتى أمرها بالغناء فقال لها ابن أبي عتيق غني فغنت\n(سددن خصاص الخيم لما دخلنه ... بكل لبان واضح وجبين)\nغنته فقام عثمان من مجلسه فقعد بين يديها ثم قال لا والله ما مثل هذه تخرج قال ابن أبي عتيق لا يدعك الناس يقولون أقر سلامة وأخرج غيرها قال فدعوهم جميعا فتركوهم جميعا أخبرني الحرمي قال حدثنا الزبير قال حدثنا عبد الله بن أبي فروة قال قدمت رسل يزيد بن عبد الملك المدينة فاشتروا سلامة المغنية من آل\nرمانة بعشرين ألف دينار فلما خرجت من ملك أهلها طلبوا إلى الرسل أن يتركوها عندهم أياما ليجهزوها بما يشبهها من حلي وثياب وطيب وصبغ فقالت لهم الرسل هذا كله معنا لا حاجة بنا إلى شيء منه وأمروها بالرحيل فخرجت حتى نزلت سقاية سليمان بن عبد الملك وشيعها الخلق من أهل المدينة فلما بلغوا السقاية قالت للرسل قوم كانوا يغشونني ويسلمون علي ولا بد لي من وداعهم والسلام عليهم فأذن للناس عليها فانقضوا حتى ملأوا رحبة القصر ووراء ذلك فوقفت بينهم ومعها العود فغنتهم\n(فارقوني وقد علمت يقينا ... ما لمن ذاق ميتة من إياب)\n(إن أهل الحصاب قد تركوني ... مولعا موزعا بأهل الحصاب)\n(أهل بيت تتايعوا للمنايا ... ما على الدهر بعدهم من عتاب)\n(سكنوا الجزع جزع بيت أبي موسى ... إلى النخل من صفي السباب)\n(كم بذاك الحجون من حي صدق ... وكهول أعفة وشباب)\nال عيسى وكنت في الناس فلم تزل تردد هذا الصوت حتى راحت وانتحب الناس بالبكاء عند ركوبها فما شئت أن أرى باكيا إلا رأيته","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":3,"spl":"عتابها لحبابة لاستخفافها بها","loc":1555},
{"id":"b84-8","bab":"الجزء 8","sec":"وساطتها للغريض عند يزيد","page":"ج8 ص358","text":"وجه يزيد بن عبد الملك إلى الأحوص في القدوم عليه وكان الغريض معه فقال له أخرج معي حتى آخذ لك جائزة أمير المؤمنين وتغنيه فإني لا أحمل إليه شيئا هو أحب إليه منك فخرجا فلما قدم الأحوص على يزيد جلس له ودعا به فأنشده مدائح فاستحسنها وخرج من عنده فبعثت إليه سلامة جارية يزيد بلطف فأرسل إليها إن الغريض عندي قدمت به هدية إليك فلما جاءها الجواب اشتاقت إلى الغريض وإلى الاستماع منه فلما دعاها أمير المؤمنين تمارضت وبعثت إلى الأحوص إذا دعاك أمير المؤمنين فاحتل له في أن تذكر له الغريض فلما دعا يزيد الأحوص قال له يزيد ويحك يا أحوص هل سمعت شيئا في طريقك تطرفنا به قال نعم يا أمير المؤمنين مررت في بعض الطريق فسمعت صوتا أعجبني حسنه وجودة شعره فوقفت حتى استقصيت خبره فإذا هو الغريض وإذا هو يغني بأحسن صوت وأشجاه\n(ألا هاج التذكر لي سقاما ... ونكس الداء والوجع الغراما)\n(سلامة إنها همي ودائي ... وشر الداء ما بطن العظاما)\n(فقلت له ودمع العين يجري ... على الخدين أربعة سجاما)\n(عليك لها السلام فمن لصب ... يبيت الليل يهذي مستهاما)\nقال يزيد ويلك يا أحوص أنا ذاك في هوى خليلتي وما كنت أحسب مثل هذا يتفق وإن ذاك لمما يزيد لها في قلبي فما صنعت يا أحوص حين سمعت ذاك قال سمعت ما لم أسمع يا أمير المؤمنين أحسن منه فما صبرت\nحتى أخرجت الغريض معي وأخفيت أمره وعلمت أن أمير المؤمنين يسألني عما رأيت في طريقي فقال له يزيد ائتني بالغريض ليلا وأخف أمره فرجع الأحوص إلى منزله وبعث إلى سلامة بالخبر فقالت للرسول قل له جزيت خيرا قد انتهى إلي كل ما قلت وقد تلطفت وأحسنت فلما وارى الليل أهله بعث إلى الأحوص أن عجل المجيء إلي مع ضيفك فجاء الأحوص مع الغريض فدخلا عليه فقال غنني الصوت الذي أخبرني الأحوص أنه سمعه منك وكان الأحوص قد أخبر الغريض الخبر وإنما ذلك شعر قاله الأحوص يريد يحركه به على سلامة ويحتال للغريض في الدخول عليه فقال غنني الصوت الذي أخبرني الأحوص فلما غناه الغريض دمعت عين يزيد ثم قال ويحك هل يمكن أن تصير إلى مجلسي قيل له هي صالحة فأرسل إليها فأقبلت فقيل ليزيد قد جاءت فضرب لها حجاب فجلست وأعاد عليه الغريض الصوت فقالت أحسن والله يا أمير المؤمنين فاسمعه مني فأخذت العود فضربته وغنت الصوت فكاد يزيد أن يطير فرحا وسرورا وقال يا أحوص إنك لمبارك يا غريض غنني في ليلتي هذا الصوت فلم يزل يغنيه حتى قام يزيد وأمر لهما بمال وقال لا يصبح الغريض في شيء من دمشق فارتحل الغريض من ليلته وأقام الأحوص بعده أياما ثم لحق به وبعثت سلامة إليهما بكسوة ولطف كثير","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":4,"spl":"وساطتها للغريض عند يزيد","loc":1556},
{"id":"b84-9","bab":"الجزء 8","sec":"نوحها على يزيد حين مات","page":"ج8 ص359","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي قال حدثني رجل من أهلي من بني نوفل قال قدمت في جماعة من قريش على يزيد بن عبد الملك فألفيناه في علته التي مات فيها بعد وفاة حبابة فنزلنا منزلا لاصقا بقصر يزيد فكنا إذا\nأصبحنا بعثنا بمولى لنا يأتينا بخبره وربما أتينا الباب فسألنا فكان يثقل في كل يوم فإنا لفي منزلنا ليلة إذ سمعنا همسا من بكاء ثم يزيد ذلك ثم سمعنا صوت سلامة القس وهي رافعة صوتها تنوح وتقول\n(لا تلمنا إن خشعنا ... أو هممنا بخشوع)\n(قد لعمري بت ليلي ... كأخي الداء الوجيع)\n(كلما أبصرت ربعا ... خاليا فاضت دموعي)\n(قد خلا من سيد كان ... لنا غير مضيع)\nم صاحت وا أمير المؤمنين فعلمنا وفاته فأصبحنا فغدونا في جنازته أخبرني الحرمي قال حدثنا الزبير قال حدثنا إسماعيل بن أبي أويس عن أبيه قال قال يزيد بن عبد الملك ما يقر عيني ما أوتيت من أمر الخلافة حتى أشتري سلامة جارية مصعب بن سهيل الزهري وحبابة جارية آل لاحق المكية فأرسل فاشتريتا له فلما اجتمعتا عنده قال أنا الآن كما قال الشاعر\n(فألقت عصاها واستقر بها النوى ... كما قر عينا بالإياب المسافر)\nلما توفي يزيد رثته سلامة فقالت وهي تنوح عليه هذا الشعر\n(لا تلمنا إن خشعنا ... أو هممنا بخشوع)\n(إذ فقدنا سيدا كان ... لنا غير مضيع)\n(وهو كالليث إذا ما ... عد أصحاب الدروع)\n(يقنص الأبطال ضربا ... في مضي ورجوع)\nأخبرنا الحسين بن يحيى قال حدثنا الزبير والمدائني أن سلامة كانت لسهيل بن عبد الرحمن بن عوف فاشتراها يزيد بن عبد الملك وكانت مغنية حاذقة جميلة ظريفة تقول الشعر فما رأيت خصالا أربعا اجتمعن امرأة مثلها حسن وجهها وحسن غنائها وحسن شعرها قال والشعر الذي كانت تغني به\n(لا تلمنا إن خشعنا ... أو هممنا بخشوع)\n(للذي حل بنا اليوم ... من الأمر الفظيع)\nذكر باقي الأبيات مثل ما ذكره غيره قال إسحاق وحدثني الجمحي قال حدثنا من رأى سلامة تندب يزيد بن عبد الملك بمرثية رثته بها فما سمع السامعون بشيء أحسن من ذلك ولا أشجى ولقد أبكت العيون وأحرقت القلوب وأفتنت الأسماع وهي\n(يا صاحب القبر الغريب ... بالشام في طرف الكثيب)\n(بالشام بين صفائح ... صم ترصف بالجبوب)\n(لما سمعت أنينه ... وبكاءه عند المغيب)\n(أقبلت أطلب طبه ... والداء يعضل بالطبيب)\nلشعر لرجل من العرب كان خرج بابن له من الحجاز إلى الشام بسبب امرأة هويها وخاف أن يفسد بحبها فلما فقدها مرض بالشام وضني فمات ودفن بها كذا ذكر ابن الكلبي وخبره يكتب عقب أخبار سلامة القس والغناء لسلامة ثقيل أول بالوسطى عن حبش وفيه لحكم رمل مطلق في مجرى البنصر\nعن إسحاق وفيه لحن لابن غزوان الدمشقي من كتاب ابن خرداذبه غير مجنس أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال حدثني الجمحي قال حدثني من حضر الوليد بن يزيد وهو يسأل سلامة أن تغنيه شعرها في يزيد وهي تتنغص من ذلك وتدمع عيناها فأقسم عليها فغنته فما سمعت شيئا أحسن من ذلك فقال لها الوليد رحم الله أبي وأطال عمري وأمتعني بحسن غنائك يا سلامة بم كان أبي يقدم عليك حبابة قالت لا أدري والله قال لها لكنني والله أدري ذلك بما قسم الله لها قالت يا سيدي أجل","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":5,"spl":"نوحها على يزيد حين مات","loc":1557},
{"id":"b84-10","bab":"الجزء 8","sec":"انتحل إسحاق الموصلي ما ناحت به على يزيد","page":"ج8 ص362","text":"أخبرني يحيى بن علي بن يحيى قال حدثني عبد الله بن عبد الملك الهدادي عن بعض رجاله عن إسحاق بن إبراهيم الموصلي قال سمعت نائحة مدنية تنوح بهذا الشعر\n(قد لعمري بت ليلي ... كأخي الداء الوجيع)\n(ونجي الهم مني ... بات أدنى من ضلوعي)\n(كلما أبصرت ربعا ... دارسا فاضت دموعي)\n(مقفرا من سيد كان ... لنا غير مضيع)\nالشعر للأحوص والنوح لمعبد وكان صنعه لسلامة وناحت به سلامة على يزيد فلما سمعته منها استحسنته واشتهيته ولهجت به فكنت أترنم به كثيرا فسمع ذلك مني أبي فقال ما تصنع بهذا قلت شعر قاله الأحوص\nوصنعه معبد لسلامة وناحت به سلامة على يزيد ثم ضرب الدهر فلما مات الرشيد إذا رسول أم جعفر قد وافاني فأمرني بالحضور فسرت إليها فبعثت إلي إني قد جمعت بنات الخلفاء وبنات هاشم لننوح على الرشيد في ليلتنا هذه فقل الساعة أبياتا رقيقة واصنعهن صنعة حسنة حتى أنوح بهن فأردت نفسي على أن أقول شيئا فما حضرني وجعلت ترسل إلي تحثني فذكرت هذا النوح فأريت أني أصنع شيئا ثم قلت قد حضرني القول وقد صنعت فيه ما أمرت فبعثت إلي بكنيزة وقالت طارحها حتى تطارحنيه فأخذت كنيزة العود ورددته عليها حتى أخذته ثم دخلت فطارحته أم جعفر فبعثت إلي بمائة ألف درهم ومائة ثوب","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":6,"spl":"انتحل إسحاق الموصلي ما ناحت به على يزيد — نسبة ما في هذه الأخبار من الأصوات","loc":1558},
{"id":"b84-11","bab":"الجزء 8","sec":"نسبة ما في هذه الأخبار من الأصوات","page":"ج8 ص363","text":"\n(لقد فتنت ريا وسلامة القسا ... فلم تتركا للقس عقلا ولا نفسا)\n(فتاتان أما منهما فشبيهة الهلال ... وأخرى منهما تشبه الشمسا)\nلشعر لعبد الله بن قيس الرقيات والغناء لمالك خفيف ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لابن سريج ثقيل أول عن الهشامي وزعم عمرو بن بانة أن خفيف الثقيل لحنين الحيري وقيل إن الثقيل الأول لدحمان ومنها الشعر الذي أوله\n(أهابك أن أقول بذلت نفسي ... )\nوت\n(أأثلة جر جيرتك الزيالا ... وعاد ضمير ودكم خبالا)\n(فإني مستقيلك أثل لبي ... ولب المرء أفضل ما استقالا)\n(أهابك أن أقول بذلت نفسي ... ولو أني أطيع القلب قالا)\n(حياء منك حتى سل جسمي ... وشق علي كتماني وصالا)\nلشعر للقس والغناء لمعبد خفيف ثقيل أول مطلق في مجرى البنصر وفيه لمعبد ثقيل أول بالوسطى أوله\n(أهابك أن اقول بذلت نفسي ... )\nبر لها مع القس أخبرني الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك الزيات قال حدثنا الزبير بن بكار قال حدثنا بكار بن رباح قال كان عبد الرحمن بن عبد الله بن أبي عمار من بني جشم بن معاوية وقد كانت أصابت جدة منه من صفوان بن أمية وكان ينزل مكة وكان من عباد أهلها فسمي القس من عبادته فمر ذات يوم بسلامة وهي تغني فوقف فتسمع غناءها فرآه مولاها فدعاه إلى أن يدخله إليها فيسمع منها فأبى عليه فقال له فإني أقعدك في مكان تسمع منها ولا تراها فقال أما هذا فنعم فأدخله داره وأجلسه حيث يسمع غناءها ثم أمرها فخرجت إليه فلما رآها علقت بقلبه فهام بها واشتهر وشاع خبره بالمدينة قال وجعل يتردد إلى منزل مولاها مدة طويلة ثم إن مولاها خرج يوما لبعض شأنه وخلفه مقيما عندها فقالت له أنا والله أحبك فقال لها وأنا والله الذي لا إله إلا هو قالت وأنا والله أشتهي أن أعانقك وأقبلك قال وأنا والله قالت وأشتهي والله أن أضاجعك واجعل بطني على بطنك وصدري على صدرك قال وأنا والله قالت فما يمنعك من ذلك فوالله إن المكان لخال قال يمنعني منه قول الله عز و جل ( الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين\nفأكره أن تحول مودتي لك\nعداوة يوم القيامة ثم خرج من عندها وهو يبكي فما عاد إليها بعد ذلك وأخبرنا إسماعيل بن يونس قال حدثنا عمر بن شبة عن المدائني قال لما ملك يزيد بن عبد الملك حبابة وسلامة القس تمثل\n(فألقت عصاها واستقر بها النوى ... كما قر عينا بالإياب المسافر)\nم قال ما شاء بعد من أمر الدنيا فليفتني","topic":"ذكر سلامة القس وخبرها","topicNo":84,"sp":6,"spl":"انتحل إسحاق الموصلي ما ناحت به على يزيد — نسبة ما في هذه الأخبار من الأصوات","song":1,"loc":1559,"partialRef":{"sid":"b84-2","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b85-1","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص365","text":"(وإني ليرضيني قليل نوالكم ... وإن كنت لا أرضى لكم بقليل)\n(بحرمة ما قد كان بيني وبينكم ... من الوصل إلا عدتم بجميل)\nلشعر للعباس بن الأحنف والغناء لسليمان الفزازي ولحنه المختار من الرمل بالسبابة في مجرى البنصر عن إسحاق وفيه خفيف رمل أوله الثاني ثم الأول ينسب إلى حكم الوادي وإلى سليمان أيضا وفيه لحن من الثقيل الأول يقال إنه لمخارق ذكر حبش أن لحن مخارق ثاني ثقيل","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":0,"spl":"صوت من المائة المختارة — أخبار العباس بن الأحنف ونسبه — سخر شعره للغزل دون الهجاء أو المدي","loc":1560},
{"id":"b85-3","bab":"الجزء 8","sec":"أخبار العباس بن الأحنف ونسبه — سخر شعره للغزل دون الهجاء أو المديح","page":"ج8 ص366 – ج8 ص367","text":"هو فيما ذكر ابن النطاح العباس بن الأحنف بن الأسود بن طلحة بن جدان بن كلدة من بني عدي بن حنيفة وأخبرني محمد بن يحيى الصولي قال حدثني القاسم بن إسماعيل قال سمعت إبراهيم بن العباس يقول العباس بن الأحنف بن الأسود بن قدامة بن هميان من بني هفان بن الحارث بن الذهل بن الدول بن حنيفة قال وكان حاجب بن قدامة عم العباس من رجال الدولة قال محمد بن يحيى وحدثني أبو عبد الله الكندي قال حدثني محمد بن بكر الحنفي الشاعر قال حدثني أبي قال سمعت العباس بن الأحنف يذكر أن هوذة بن علي الحنفي قد ولده من قبل بعض أمهاته\nوكان العباس شاعرا غزلا ظريفا مطبوعا من شعراء الدولة العباسية وله مذهب حسن ولديباجة شعره رونق ولمعانيه عذوبة ولطف ولم يكن يتجاوز الغزل إلى مديح ولا هجاء ولا يتصرف في شيء من هذه المعاني وقدمه أبو العباس المبرد في كتاب الروضة على نظرائه وأطنب في وصفه وقال رأيت جماعة من الرواة للشعر يقدمونه قال وكان العباس من الظرفاء ولم يكن من الخلعاء وكان غزلا ولم يكن فاسقا وكان ظاهر النعمة ملوكي المذهب شديد التترف وذلك بين في شعره وكان قصده الغزل وشغله النسيب وكان حلوا مقبولا غزلا غزير الفكر واسع الكلام كثير التصرف في الغزل وحده ولم يكن هجاء ولا مداحا أخبرني محمد بن يحيى قال حدثنا أبو ذكوان قال سمعت إبراهيم بن العباس يصف العباس بن الأحنف فقال كان والله ممن إذا تكلم لم يحب سامعه أن يسكت وكان فصيحا جميلا ظريف اللسان لو شئت أن تقول كلامه كله شعر لقلت حدثني محمد بن يحيى قال حدثني عبيد الله بن عبد الله بن طاهر قال رأيت نسخا من شعر العباس بن الأحنف بخراسان وكان عليها مكتوب شعر الأمير أبي الفضل العباس أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال حدثني صالح بن عبد الوهاب\nأن العباس بن الأحنف كان من عرب خراسان ومنشؤه ببغداد ولم تزل العلماء تقدمه على كثير من المحدثين ولا تزال قد ترى له الشيء البارع جدا حتى تلحقه بالمحسنين أخبرني محمد بن يحيى قال حدثنا يموت بن المزرع قال سمعت خالي يعني الجاحظ يقول لولا أن العباس بن الأحنف أحذق الناس وأشعرهم وأوسعهم كلاما وخاطرا ما قدر أن يكثر شعره في مذهب واحد لا يجاوزه لأنه لا يهجو ولا يمدح ولا يتكسب ولا يتصرف وما نعلم شاعرا لزم فنا واحدا لزومه فأحسن فيه وأكثر حدثني محمد بن يحيى قال حدثنا محمد بن القاسم بن خلاد قال أنشد الحرمازي أبو علي وأنا حاضر للعباس بن الأحنف\n(لا جزى الله دمع عيني خيرا ... وجزى الله كل خير لساني)\n(نم دمعي فليس يكتم شيئا ... ورأيت اللسان ذا كتمان)\n(كنت مثل الكتاب أخفاه طي ... فاستدلوا عليه بالعنوان)\nلغناء لعريب رمل ثم قال الحرمازي هذا والله طراز يطلب الشعراء مثله فلا يقدرون عليه أخبرني محمد قال حدثني حسين بن فهم قال سمعت العطوي يقول\nكان العباس بن الأحنف شاعرا مجيدا غزلا وكان أبو الهذيل العلاف يبغضه ويلعنه لقوله\n(إذا أردت سلوا كان ناصركم ... قلبي وما أنا من قلبي بمنتصر)\n(فأكثروا أو أقلوا من إساءتكم ... فكل ذلك محمول على القدر)\nال فكان أبو الهذيل يلعنه لهذا ويقول يعقد الكفر والفجور في شعره قال محمد بن يحيى وأنشدني محمد بن العباس اليزيدي شعرا للعباس أظنه يهجو به أبا الهذيل وما سمعت للعباس هجاء غيره\n(يا من يكذب أخبار الرسول لقد ... أخطأت في كل ما تأتي وما تذر)\n(كذبت بالقدر الجاري عليك فقد ... أتاك مني بما لا تشتهي القدر)","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":0,"spl":"صوت من المائة المختارة — أخبار العباس بن الأحنف ونسبه — سخر شعره للغزل دون الهجاء أو المدي","song":1,"loc":1561},
{"id":"b85-4","bab":"الجزء 8","sec":"الأصمعي يعترف بأنه أحسن المحدثين","page":"ج8 ص369","text":"حدثني محمد بن يحيى قال حدثني محمد بن سعيد عن الرياشي قال قيل للأصمعي أو قلت له ما أحسن ما تحفظ للمحدثين قال قول العباس بن الأحنف\n(لو كنت عاتبة لسكن روعتي ... أملي رضاك وزرت غير مراقب)\n(لكن مللت فلم تكن لي حيلة ... صد الملول خلاف صد العاتب)\nلغناء للعباس أخي بحر رمل أخبرني هاشم بن محمد الخزاعي ومحمد بن العباس اليزيدي قالا واللفظ لهاشم قال حدثنا عبد الرحمن ابن أخي الأصمعي قال دخل عمي على الرشيد والعباس بن الأحنف عنده فقال العباس للرشيد دعني أعبث بالأصمعي قال له الرشيد إنه ليس ممن يحتمل العبث\nفقال لست أعبث به عبثا يشق عليه قال أنت اعلم فلما دخل عمي قال له يا أبا سعيد من الذي يقول\n(إذا أحببت أن تصنع ... شيئا يعجب الناسا)\n(فصور ها هنا فوزا ... وصور ثم عباسا)\n(فإن لم يدنوا حتى ... ترى رأسيهما راسا)\n(فكذبها بما قاست ... وكذبه بما قاسى)\nقال له عمي يعرض بأنه نبطي قاله الذي يقول\n(إذا أحببت أن تبصر ... شيئا يعجب الخلقا)\n(فصور ها هنا دورا ... وصور ها هنا فلقا)\n(فإن لم يدنوا حتى ... ترى خلقيهما خلقا)\n(فكذبها بما لاقت ... وكذبه بما يلقى)\nال فخجل العباس وقال له الرشيد قد نهيتك فلم تقبل حدثني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال أنشدني إبراهيم بن العباس للعباس بن الأحنف\n(قالت ظلوم سمية الظلم ... ما لي رأيتك ناحل الجسم)\n(يا من رمى قلبي فأقصده ... أنت العليم بموضع السهم)\nقلت له إن أبا حاتم السجستاني حكى عن الأصمعي أنه أنشد للعباس بن الأحنف\n\n(أتأذنون لصب في زيارتكم ... فعندكم شهوات السمع والبصر)\n(لا يضمر السوء إن طال الجلوس به ... عف الضمير ولكن فاسق النظر)\nقال الأصمعي ما زال هذا الفتى يدخل يده في جرابه فلا يخرج شيئا حتى أدخلها فأخرج هذا ومن أدمن طلب شيء ظفر ببعضه فقال إبراهيم بن العباس أنا لا أدري ما قال الأصمعي ولكن أنشدك للعباس ما لا تدفع أنت ولا غيرك فضله ثم أنشدني قوله\n(والله لو أن القلوب كقلبها ... ما رق للولد الضعيف الوالد)\nقوله\n(لكن مللت فلم تكن لي حيلة ... صد الملول خلاف صد العاتب)\nقوله\n(حتى إذا اقتحم الفتى لجج الهوى ... جاءت أمور لا تطاق كبار)\nم قال هذا والله ما لا يقدر أحد على أن يقول مثله أبدا حدثني عمي قال حدثني ميمون بن هارون قال كنا عند الحسن بن وهب فقال لبنان غنيني\n(أتأذنون لصب في زيارتكم ... فعندكم شهوات السمع والبصر)\n(لا يضمر السوء إن طال الجلوس به ... عف الضمير ولكن فاسق النظر)\nال فضحكت ثم قالت فأي خير فيه إن كان كذا أو أي معنى فخجل الحسن من نادرتها عليه وعجبنا من حدة جوابها وفطنتها\nحدثني الصولي قال أخبرنا أحمد بن إسماعيل النصيبيني قال سمعت سعيد بن جنيد يقول ما أعرف أحسن من شعر العباس في إخفاء أمره حيث يقول\n(أريدك بالسلام فأتقيهم ... فأعمد بالسلام إلى سواك)\n(وأكثر فيهم ضحكي ليخفى ... فسني ضاحك والقلب باك)","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":1,"spl":"الأصمعي يعترف بأنه أحسن المحدثين — الواثق يتمثل بشعره في غضبه","song":3,"loc":1562},
{"id":"b85-5","bab":"الجزء 8","sec":"الواثق يتمثل بشعره في غضبه","page":"ج8 ص372","text":"حدثني الصولي قال حدثني علي بن محمد بن نصر قال حدثني خالي أحمد بن حمدون قال كان بين الواثق وبين بعض جواريه شر فخرج كسلان فلم أزل أنا والفتح بن خاقان نحتال لنشاطه فرآني أضاحك الفتح فقال قاتل الله ابن الأحنف حيث يقول\n(عدل من الله أبكاني وأضحكها ... فالحمد لله عدل كل ما صنعا)\n(اليوم أبكي على قلبي وأندبه ... قلب ألح عليه الحب فانصدعا)\nقال الفتح أنت والله يا أمير المؤمنين في وضع التمثل موضعه أشعر منه وأعلم واظرف أخبرني الصولي قال حدثني أحمد بن يزيد المهلبي عن أبيه قال\nقالت للواثق جارية له كان يهواها وقد جرى بينهما عتب إن كنت تستطيل بعز الخلافة فأنا أدل بعز الحب أتراك لم تسمع بخليفة عشق قبلك قط فاستوفى من معشوقه حقه ولكني لا أرى لي نظيرا في طاعتك فقال الواثق لله در ابن الأحنف حيث يقول\n(أما تحسبيني أرى العاشقين ... بلى ثم لست أرى لي نظيرا)\n(لعل الذي بيديه الأمور ... سيجعل في الكره خيرا كثيرا)","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":1,"spl":"الأصمعي يعترف بأنه أحسن المحدثين — الواثق يتمثل بشعره في غضبه","loc":1563},
{"id":"b85-6","bab":"الجزء 8","sec":"الزبير بن بكار يقول ابن الأحنف أشعر الناس","page":"ج8 ص373","text":"حدثني الصولي قال حدثني المغيرة بن محمد المهلبي قال سمعت الزبير يقول ابن الأحنف أشعر الناس في قوله\n(تعتل بالشغل عنا ما تكلمنا ... الشغل للقلب ليس الشغل للبدن)\nيقول لا أعلم شيئا من أمور الدنيا خيرها وشرها إلا وهو يصلح أن يتمثل فيه بهذا النصف الأخير حدثني الصولي قال حدثني محمد بن سعيد عن حماد بن إسحاق قال كان أبي يقول لقد ظرف ابن الأحنف في قوله يصف طول عهده بالنوم\n(قفا خبراني أيها الرجلان ... عن النوم إن الهجر عنه نهاني)\n(وكيف يكون النوم أم كيف طعمه ... صفا النوم لي إن كنتما تصفان)\nال على قلة إعجابه بمثل هذه الأشعار حدثني الصولي قال حدثني ميمون بن هارون بن مخلد قال حدثنا أحمد بن إبراهيم قال رأيت سلمة بن عاصم ومعه شعر العباس بن الأحنف\nفعجبت منه وقلت مثلك أعزك الله يحمل هذا فقال ألا أحمل شعر من يقول\n(أسأت أن أحسنت ظني بكم ... والحزم سوء الظن بالناس)\n(يقلقني الشوق فآتيكم ... والقلب مملوء من الياس)\nنى هذين البيتين حسين بن محرز خفيف رمل بالوسطى وأول الصوت\n(يا فوز يا منية عباس ... واحربا من قلبك القاسي)\nروى أحمد بن إبراهيم قال أتاني أعرابي فصيح ظريف فجعلت أكتب عنه أشياء حسانا ثم قال أنشدني لأصحابكم الحضريين فأنشدته للعباس بن الأحنف\n(ذكرتك بالتفاح لم شممته ... وبالراح لما قابلت أوجه الشرب)\nتذكرت بالتفاح منك سوالفا ... وبالراح طعما من مقبلك العذب\nقال هذا عندك وأنت تكتب عني لا أنشدك حرفا بعد هذا وحدثني الصولي قال حدثني الحسين بن يحيى الكاتب قال سمعت عبد الله بن العباس بن الفضل يقول ما أعرف في العراق أحسن من قول ابن الأحنف\n(سبحان رب العلا ما كان أغفلني ... عما رمتني به الأيام والزمن)\n(من لم يذق فرقة الأحباب ثم يرى ... آثارهم بعدهم لم يدر ما الحزن)\nقال أبو بكر وقد غنى عبد الله بن العباس فيه صوتا خفيف رمل حدثني الصولي قال حدثنا ميمون بن هارون قال سمعت حسين ين الضحاك يقول لو جاء العباس بن الأحنف بقوله ما قاله في بيتين في أبيات لعذر وهو قوله\n(لعمرك ما يستريح المحب ... حتى يبوح بأسراره)\n(فقد يكتم المرء أسراره ... فتظهر في بعض أشعاره)\nم قال أما قوله في هذا المعنى الذي لم يتقدمه فيه أحد فهو\n(الحب أملك للفؤاد بقهره ... من أن يرى للستر فيه نصيب)\n(وإذا بدا سر اللبيب فإنه ... لم يبد إلا والفتى مغلوب)\nأخبرني الصولي قال حدثني الغلابي قال حدثني الزبير بن بكار قال قال أبو العتاهية ما حسدت أحدا إلا العباس بن الأحنف في قوله\n(إذا امتنع القريب فلم تنله ... على قرب فذاك هو البعيد)\nإني كنت أولى به منه وهو بشعري أشبه منه بشعره فقلت له صدقت هو يشبه شعرك","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":2,"spl":"الزبير بن بكار يقول ابن الأحنف أشعر الناس — الكندي يستجيد شعره","song":1,"loc":1564},
{"id":"b85-7","bab":"الجزء 8","sec":"الكندي يستجيد شعره","page":"ج8 ص375","text":"أخبرني الصولي قال حدثني أبو الحسن الأنصاري قال سمعت\nالكندي يقول العباس بن الأحنف مليح ظريف حكيم جزل في شعره وكان قليلا ما يرضيني الشعر فكان ينشد له كثيرا\n(ألا تعجبون كما أعجب ... حبيب يسيء ولا يعتب)\n(وأبغي رضاه على سخطه ... فيأبى علي ويستصعب)\n(فيا ليت حظي إذا ما أسأت ... أنك ترضى ولا تغضب)","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":2,"spl":"الزبير بن بكار يقول ابن الأحنف أشعر الناس — الكندي يستجيد شعره","song":1,"loc":1565},
{"id":"b85-8","bab":"الجزء 8","sec":"شغف إبراهيم الموصلي بشعره فتغنى به","page":"ج8 ص376","text":"أخبرني الصولي قال حدثنا محمد بن الفضل قال حدثني حماد بن إسحاق قال كان جدي إبراهيم مشغوفا بشعر العباس فتغنى في كثير من شعره فذكر أشعارا كثيرة حفظت منها\n(وقد ملئت ماء الشباب كأنها ... قضيب من الريحان ريان أخضر)\n(هم كتموني سيرهم حين أزمعوا ... وقالوا اتعدنا للرواح وبكروا)\nكر الهشامي أن اللحن في هذين البيتين لعلويه رمل وفي كتاب ابن المكي أنه لابن سريج وهو غلط وقد أخبرني الحسن بن علي عن الحسين بن فهم قال أنشد المأمون قول عباس بن الأحنف\n(هم كتموني سيرهم حين أزمعوا ... وقالوا اتعدنا للرواح وبكروا)\nقال المأمون سخروا بأبي الفضل قال وحفظت منها\n(تمنى رجال ما أحبوا وإنما ... تمنيت أن أشكو إليك وتسمعا)\n(أرى كل معشوقين غيري وغيرها ... قد استعذبا طول الهوى وتمتعا)\nلغناء لإبراهيم ثقيل أول بالبنصر وفيه ثقيل أول بالوسطى ينسب إلى يزيد حوراء وإلى سليم بن سلام قال وحفظت منها\n(بكت عيني لأنواع ... من الحزن وأوجاع)\n(وأني كل يوم عندكم ... يحظى بي الساعي)\n(أعيش الدهر إن عشت ... بقلب منك مرتاع)\n(وإن حل بي البعد ... سينعاني لك الناعي)\nلغناء لإبراهيم الموصلي ثاني ثقيل بالوسطى عن عمرو وفي كتاب إبراهيم بن المهدي الذي رواه الهشامي عنه أن لإبراهيم بن المهدي فيه لحنين ثقيلا أول وماخوريا وفيه هزج محدث أخبرني الصولي قال حدثنا أصحابنا عن محمد بن الفضل عن حماد بن إسحاق قال\nما غنى جدي في شعر أحد من الشعراء أكثر مما غنى في شعر ذي الرمة وعباس بن الأحنف أخبرني الصولي قال حدثني محمد بن عبد الله التميمي قال كنا في مجلس ابن الأعرابي إذ أقبل رجل من ولد سعيد بن سالم كان يلزم ابن الأعرابي وكان يحبه ويأنس به فقال له ما أخرك عني فاعتذر بأشياء ثم قال كنت مع مخارق عند بعض بني الرشيد فوهب له مائة ألف درهم على صوت غناه به فاستكثر ذلك ابن الأعرابي واستهاله وعجب منه وقال ما هو قال غناه بشعر عباس بن الأحنف\n(بكت عيني لأنواع ... )\n(من الحزن وأوجاع ... )\n(وأني كل يوم عندكم ... يحظى بي الساعي)\nقال ابن الأعرابي أما الغناء فما أدري ما هو ولكن هذا والله كلام قريب مليح حدثني الصولي قال حدثنا محمد بن الهيثم قال حدثني محمد بن عمرو الرومي قال كنا عند الواثق فقال أريد أن أصنع لحنا في شعر معناه أن الإنسان كائنا من كان لا يقدر على الاحتراس من عدوه فهل تعرفون في هذا شيئا فأنشدنا ضروبا من الأشعار فقال ما جئتم بشيء مثل قول عباس بن الأحنف\n(قلبي إلى ما ضرني داعي ... يكثر أسقامي وأوجاعي)\n(كيف احتراسي من عدوي إذا ... كان عدوي بين أضلاعي)\n(أسلمني للحب أشياعي ... لما سعى بي عندها الساعي)\n(لقلما أبقى على كل ذا ... يوشك أن ينعاني الناعي)\nال فعمل فيه الواثق لحنه الثقيل الأول النشيد بالوسطى","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":3,"spl":"شغف إبراهيم الموصلي بشعره فتغنى به","song":2,"loc":1566,"partial":1},
{"id":"b85-9","bab":"الجزء 8","sec":"خبر المتوكل وعلي بن الجهم في صدد شعره","page":"ج8 ص379","text":"حدثني الصولي قال حدثني محمد بن موسى أو حدثت به عنه عن علي بن الجهم قال انصرفت ليلة من عند المتوكل فلما دخلت منزلي جاءني رسوله يطلبني فراعني ذلك وقلت بلاء تتبعت به بعد انصرافي فرجعت إليه وجلا فأدخلت عليه وهو في مرقده فلما رآني ضحك فأيقنت بالسلامة فقال يا علي أنا مذ فارقتك ساهر خطر على قلبي هذا الشعر الذي يغني فيه أخي قول الشاعر\n(قلبي إلى ما ضرني داعي ... )\nلأبيات فحرصت أن أعمل مثل هذا فلم يجئني أو أن أعمل مثل اللحن فما أمكنني فوجدت في نفسي نقصا فقلت يا سيدي كان أخوك خليفة يغني وأنت خليفة لا تغني فقال قد والله أهديت إلى عيني نوما أعطوه الف دينار وحييته وانصرفت وجدت في كتاب الشاهيني بغير إسناد\nأنشد ابو الحارث جميز قول العباس بن الأحنف\n(قلبي إلى ما ضرني داعي ... )\nلأبيات فبكى ثم قال هذا شعر رجل جائع في جارية طباخة مليحة فقلت له من اين قلت ذاك قال لأنه بدأ فقال\n(قلبي إلى ما ضرني داعي ... )\nكذلك الإنسان يدعوه قلبه وشهوته إلى ما يضره من الطعام والشراب فيأكله فتكثر علله وأوجاعه وهذا تعريض ثم صرح فقال\n(كيف احتراسي من عدوي إذا ... كان عدوي بين أضلاعي)\nوليس للإنسان عدو بين أضلاعه إلا معدته فهي تتلف ماله وهي سبب أسقامه وهي مفتاح كل بلاء عليه ثم قال\n(إن دام لي هجرك يا مالكي ... أوشك أن ينعاني الناعي)\nعلمت أن الطباخة كانت صديقته وأنها هجرته ففقدها وفقد الطعام فلو دام ذلك عليه لمات جوعا ونعاه الناعي وحدثني الصولي قال حدثني محمد بن عيسى قال جاء عبد الله بن العباس بن الفضل بن الربيع إلى الحسن بن وهب وعنده بنان جارية محمد بن حماد وهي نائمة سكرى وهي يبكي عندها فقال له ما لك قال قد كنت نائما فجاءتني فأنبهتني وقالت اجلس حتى تشرب فجلست فوالله ما غنت عشرة أصوات حتى نامت وما شربت إلا قليلا فذكرت قول أشعر الناس وأظرفهم العباس بن الأحنف\n(أبكي الذين أذاقوني مودتهم ... حتى إذا أيقظوني للهوى رقدوا)\nأنا أبكي وأنشد هذا البيت","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":4,"spl":"خبر المتوكل وعلي بن الجهم في صدد شعره — نسبة هذين الصوتين منهما","song":1,"loc":1567,"partialRef":{"sid":"b85-8","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b85-10","bab":"الجزء 8","sec":"ابنه إبراهيم يمدح شعره وينشد له","page":"ج8 ص381","text":"وحدثني الصولي قال حدثني القاسم بن إسماعيل قال سمعت إبراهيم بن العباس يقول ما رأيت كلاما محدثا أجزل في رقة ولا أصعب في سهولة ولا أبلغ في إيجاز من قول العباس بن الأحنف\n(تعالي نجدد دارس العهد بيننا ... كلانا على طول الجفاء ملوم)\nال الصولي ووجدت بخط عبد الله بن الحسن أنشد ابو محمد الحسن بن مخلد قال أنشدني إبراهيم بن العباس بن الأحنف\n(إن قال لم يفعل وإن سيل لم ... يبذل وإن عوتب لم يعتب)\n(صب بعصياني ولو قال لي ... لا تشرب البارد لم أشرب)\n(إليك أشكو رب ما حل بي ... من صد هذا المذنب المغضب)\nنى في هذه الأبيات أحمد بن صدقة هزجا بالوسطى وفيها لحن آخر لغيره قال الحسن بن مخلد ثم قال لي إبراهيم بن العباس هذا والله الكلام الحسن المعنى السهل المورد القريب المتناول المليح اللفظ العذب المستمع حدثني الصولي قال حدثني أحمد بن يزيد المهلبي قال سمعت علي بن يحيى يقول من الشعر المرزوق من المغنين خاصة\nشعر العباس بن الأحنف وخاصة قوله\n(نام من أهدى لي الأرقا ... مستريحا سامني قلقا)\nإنه غنى فيه جماعة من المغنين منهم إبراهيم الموصلي وابنه إسحاق وغيرهما قال وكان يستحسن هذا الشعر وأظن استحسانه إياه حمله على أن قال في رويه وقافيته\n(بأبي والله من طرقا ... كابتسام البرق إذا خفقا)\nعمل فيه لحنا من خفيف الثقيل في الإصبع الوسطى هكذا رواه الصولي وأخبرني جحظة قال حدثني حماد بن إسحاق قال قال أبي هذا الصوت\n(نام من أهدى لي الأرقا ... )\nان محظوظا من المغنين من الأشعار المحظوظة في الغناء لكثرة ما فيه من الصنعة واشتراك المغنين في ألحانه وذكر محمد بن الحسن الكاتب عن علي بن محمد بن نصر عن جده حمدون أنه قال ذلك ولم يذكره عن إسحاق","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":4,"spl":"خبر المتوكل وعلي بن الجهم في صدد شعره — نسبة هذين الصوتين منهما","song":1,"loc":1568,"partial":1},
{"id":"b85-11","bab":"الجزء 8","sec":"نسبة هذين الصوتين منهما","page":"ج8 ص382","text":"\n(نام من أهدى لي الأرقا ... مستريحا زادني قلقا)\n(لو يبيت الناس كلهم ... بسهادي بيض الحذقا)\n(كان لي قلب أعيش به ... فاصطلى بالحب فاحترقا)\n(أنا لم أرزق مودتكم ... إنما للعبد ما رزقا)\nلإسحاق في هذا الشعر خفيف بالوسطى في مجراها ولأبيه إبراهيم أيضا فيه خفيف ثقيل آخر ولابن جامع فيه لحنان رمل مطلق في مجرى الوسطى في الأول والثالث وخفيف رمل مطلق في مجرى الوسطى ايضا في الأبيات كلها وفيه لسليم هزج وفيه لعلويه ثقيل أول","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":4,"spl":"خبر المتوكل وعلي بن الجهم في صدد شعره — نسبة هذين الصوتين منهما","song":1,"loc":1569},
{"id":"b85-12","bab":"الجزء 8","sec":"نسبة صوت علي بن يحيى","page":"ج8 ص383","text":"\n(بأبي والله من طرقا ... كابتسام البرق إذ خفقا)\n(زادني شوقا بزورته ... وملا قلبي به حرقا)\n(من لقلب هائم دنف ... كلما سليته قلقا)\n(زارني طيف الحبيب فما ... زاد أن أغرى بي الأرقا)\nلشعر لعلي بن يحيى وذكر الصولي أن الغناء له خفيف ثقيل أول بالوسطى وذكر أبو العبيس بن حمدون أن هذا الخفيف الثقيل من صنعته وفيه لعريب ثاني ثقيل بالوسطى أيضا حدثني الصولي قال سمعت عبد الله بن المعتز يقول لو قيل ما أحسن شيء تعرفه لقلت شعر العباس بن الأحنف\n(قد سحب الناس أذيال الظنون بنا ... وفرق الناس فينا قولهم فرقا)\n(فكاذب قد رمى بالحب غيركم ... وصادق ليس يدري أنه صدقا)\nال وللمسدود في هذا الشعر لحن قال ولم يغن المسدود أحسن\nمن غنائه في شعر العباس بن الأحنف هكذا ذكر الصولي ولم يأت بغير هذا ولإسحاق في هذين البيتين ثقيل أول بالبنصر من نسخة عمرو بن بانة الثانية ولابن جامع ثقيل أول بالوسطى عن الهشامي وليزيد حوراء خفيف ثقيل عنه وللمسدود رمل ولعبد الله بن العباس الربيعي خفيف رمل وأخبرني الصولي قال حدثني محمد بن سعيد قال حدثني حماد بن إسحاق عن أبيه قال غضب الفضل بن الربيع على جارية له كانت أحب الناس إليه فتأخرت عن استرضائه فغمه ذلك فوجه إلى أبي يعلمه ويشكوها إليه فكتب إليه أبي لك العزة والشرف ولأعدائك الذل والرغم استعمل قول العباس بن الأحنف\n(تحمل عظيم الذنب ممن تحبه ... وإن كنت مظلوما فقل أنا ظالم)\n(فإنك إلا تغفر الذنب في الهوى ... يفارقك من تهوى وأنفك راغم)\nقال صدقت وبعث إليها فترضاها","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":5,"spl":"نسبة صوت علي بن يحيى — الرياشي يمتدح شعره","song":2,"loc":1570},
{"id":"b85-13","bab":"الجزء 8","sec":"دفاع مصعب بن الزبير عن شعره","page":"ج8 ص384","text":"أخبرني الصولي قال حدثني أبو بكر بن أبي خثيمة قال قيل لمصعب الزبيري إن الناس يستبردون شعر العباس بن الأحنف فقال لقد ظلموه أليس الذي يقول\n(قالت ظلوم سمية الظلم ... ما لي رأيتك ناحل الجسم)\n(يا من رمى قلبي فأقصده ... أنت العليم بموقع السهم)\nلغناء لأبي العبيس أو ابنه إبراهيم ماخوري أخبرني الصولي قال حدثنا ميمون بن هارون قال حدثني أبو عبد الله الهشامي الحسن بن أحمد قال حدثنا عمرو بن بانة قال كنا في دار أم جعفر جماعة من الشعراء والمغنين فخرجت جارية لها وكمها مملوء دراهم فقالت أيكم القائل\n(من ذا يعيرك عينه تبكي بها ... أرأيت عينا للبكاء تعار)\nأومىء إلى العباس بن الأحنف فنثرت الدراهم في حجره فنفضها فلقطها الفراشون ثم دخلت ومعها ثلاثة نفر من الفراشين على عنق كل فراش بدرة فيها دراهم فمضوا بها إلى منزل العباس بن الأحنف أخبرني الحسن بن علي قال حدثني محمد بن موسى قال أنشد الرشيد قول العباس بن الأحنف\n(من ذا يعيرك عينه تبكي بها ... )\nقال من لا صحبه الله ولا حاطه حدثني الصولي قال حدثني عون بن محمد الكندي قال كنا مع مخلد الموصلي في مجلس وكان معنا عبد الله بن ربيعة الرقي فأنشد مخلد الموصلي قصيدة له يقول فيها\n(كل شيء أقوى عليه ولكن ... ليس لي بالفراق منك يدان)\nجعل يستحسنه ويردده فقال له عبد الله أنت الفداء لمن أبتدأ هذا\nالمعنى فأحسن فيه حيث يقول\n(سلبتني من السرور ثيابا ... وكستني من الهموم ثيابا)\n(كلما أغلقت من الوصل بابا ... فتحت لي إلى المنية بابا)\n(عذبيني بكل شيء سوى الصد ... فما ذقت كالصدود عذابا)\nال فضحك الموصلي والشعر للعباس بن الأحنف","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":5,"spl":"نسبة صوت علي بن يحيى — الرياشي يمتدح شعره","song":1,"loc":1571,"partialRef":{"sid":"b52-32","gi":2,"vi":1,"side":0},"partial":1},
{"id":"b85-14","bab":"الجزء 8","sec":"الرياشي يمتدح شعره","page":"ج8 ص385","text":"وأخبرني الصولي قال حدثني أبو الحسن الأسدي قال سمعت الرياشي يقول وقد ذكر عنده العباس بن الأحنف والله لو لم يقل من الشعر إلا هذين البيتين لكفيا\n(أحرم منكم بما أقول وقد ... نال به العاشقون من عشقوا)\n(صرت كأني ذبالة نصبت ... تضيء للناس وهي تحترق)\nفي هذين البيتين لحن لعبد الله بن العباس من الثقيل الثاني بالبنصر وفيه لخزرج رمل أول عن عبد الله بن العباس\n(أنت لا تعلمين ما الهم والحزن ... ولا تعلمين ما الأرق)","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":5,"spl":"نسبة صوت علي بن يحيى — الرياشي يمتدح شعره","song":1,"loc":1572},
{"id":"b85-15","bab":"الجزء 8","sec":"الرشيد وإسحاق الموصلي يختلفان في مدحه ومدح أبي العتاهية","page":"ج8 ص386","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد المبرد قال حدثني بعض مشايخ الأزد عن إسحاق بن إبراهيم الموصلي قال\nكان الرشيد يقدم أبا العتاهية حتى يجوز الحد في تقديمه وكنت أقدم العباس بن الأحنف فاغتابني بعض الناس عند الرشيد وعابني عنده وقال عقب ذلك وبحسبك يا أمير المؤمنين أنه يخالفك في العباس بن الأحنف على حداثة سنه وقلة حذقه وتجريبه ويقدمه على أبي العتاهية مع ميلك إليه وبلغني الخبر فدخلت على الرشيد فقال لي ابتداء أيما أشعر عندك العباس بن الأحنف أو أبو العتاهية فعلمت الذي يريد فأطرقت كأني مستثبت ثم قلت أبو العتاهية أشعر قال أنشدني لهذا ولهذا قلت فبأيهما أبدأ قال بالعباس قال فأنشدته أجود ما أرويه للعباس وهو قوله\n(أحرم منكم بما أقول وقد ... نال به العاشقون من عشقوا)\nقال لي أحسن فأنشدني لأبي العتاهية فأنشدته أضعف ما أقدر عليه وهو قوله\n(كأن عتابة من حسنها ... دمية قس فتنت قسها)\n(يا رب لو أنسيتنيها بما ... في جنة الفردوس لم أنسها)\n... ( إني إذا مثل التي لم تزل ... دائبة في طحنها كدسها حتى إذا لم يبق منها سوى ... حفنة بر قتلت نفسها\nال أتعيره هذا فأين أنت عن قوله\n(قال لي أحمد ولم يدر ما بي ... أتحب الغداة عتبة حقا)\n(فتنفست ثم قلت نعم حبا ... جرى في العروق عرقا فعرقا)\nيحك أتعرف لأحد مثل هذا أو تعرف أحدا سبقه إلى قوله فتنفست ثم قلت كذا وكذا اذهب ويحك فاحفظها فقلت نعم يا أمير المؤمنين\nولو كنت سمعت بها لحفظتها قال إسحاق وما أشك أني كنت أحفظ لها حينئذ من أبي العتاهية ولكني إنما أنشدت ما أنشدت تعصبا قال محمد بن يزيد وحدثت من غير وجه أن الرشيد ألف العباس بن الأحنف فلما خرج إلى خراسان طال مقامه بها ثم خرج إلى أرمينية والعباس معه ماشيا إلى بغداد فعارضه في طريقه فأنشده\n(قالوا خراسان أقصى ما يراد بنا ... ثم القفول فقد جئنا خراسانا)\n(ما أقدر الله أن يدني على شحط ... سكان دجلة من سكان جيحانا)\n(متى الذي كنت أرجوه وآمله ... أما الذي كنت أخشاه فقد كانا)\n(عين الزمان أصابتنا فلا نظرت ... وعذبت بصنوف الهجر ألوانا)\nي هذين البيتين الأخيرين رمل بالوسطى ينسب إلى مخارق وإلى غيره قال فقال له الرشيد قد اشتقت يا عباس وأذنت لك خاصة وأمر له بثلاثين ألف درهم أخبرني الصولي قال حدثنا محمد بن القاسم قال سمعت مصعبا الزبيري يقول العباس بن الأحنف وعمرو العراف ما ابتدلا شعرهما في رغبة ولا رهبة ولكن فيما أحباه فلزما فنا واحدا لو لزمه غيرهما ممن يكثر إكثارهما لضعف فيه","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":6,"spl":"الرشيد وإسحاق الموصلي يختلفان في مدحه ومدح أبي العتاهية","loc":1573},
{"id":"b85-16","bab":"الجزء 8","sec":"ذكر الأصوات التي تجمع النغم العشر","page":"ج8 ص389","text":"منها\n(توهمت بالخيف رسما محيلا ... لعزة تعرف منه الطلولا)\n(تبدل بالحي صوت الصدى ... ونوح الحمامة تدعو هديلا)\nروضه من المتقارب الخيف الذي عناه كثير ليس بخيف منى بل هو موضع آخر في بلاد ضمرة والطلول جمع طلل وهو ما كان له شخص وجسم عال من آثار الديار والرسم ما لم يكن له شخص وجسم والصدى ها هنا طائر وفي موضع آخر العطش ويزعم أهل الجاهلية أن الصدى طائر يخرج من رأس المقتول فلا يزال يصيح اسقوني حتى يدرك بثأره قال طرفة\n(كريم يروي نفسه في حياته ... ستعلم إن متنا صدى أينا الصدي)\nالحمام القماري ونحوها من الطير والهديل أصواتها الشعر لكثير والغناء لعبيد الله بن عبد الله بن طاهر ونسبه إلى جاريته وكنى عنها فذكر أن الصنعة لبعض من كثرت دربته بالغناء وعظم علمه وأتعب نفسه حتى جمع النغم العشر في هذا الصوت وذكر أن طريقته من الثقيل\nالأول وأنه ليس يجوز أن ينسبه إلى موضع إصبع مفردة لأن ابتداءه على المثنى مطلقا ثم بسبابة المثنى ثم وسطى المثنى ثم بنصر المثنى ثم خنصر المثنى ثم سبابة الزير ثم وسطاه ثم بنصره ثم خنصره ثم النغمة الحادة وهي العاشرة وفيه لابن محرز ثاني ثقيل مطلق في مجرى البنصر وفيه لابن الهربذ رمل بالوسطى عن عمرو وهذا الصوت من الثقيل الثاني وهو الذي ذكر إسحاق في كتاب النغم وعللها أن لحن ابن محرز فيه يجمع ثمانيا من النغم العشر وأنه لا يعرف صوتا يجمعها غيره وأنه يمكن من كان له علم ثاقب بالصناعة أن يأتي في صوت واحد بالنغم العشر بعد تعب طويل ومعاناة شديدة وذكر عبيد الله أن صانع هذا الصوت الذي كنى عنه فعل ذلك وتلطف له حتى أتى بالنغم العشر في هذا متوالية من أولها إلى آخرها وأتى بها في الصوت الذي بعده متفرقة على غير توال إلا أنها كلها فيه وذكر أن ذلك الصوت أحسن مسموعا وأحلى وحكى ذلك أيضا عنه يحيى بن علي بن يحيى في كتاب النغم وإذ فرغت من حكاية ما ذكره وحكاه عبيد الله في نسبة هذا الصوت فقد ينبغي ألا أجري الأمر فيه على التقليد دون القول الصحيح فيما ذكره وحكاه والذي وصفه من جهة النغم العشر متوالية في صوت واحد محال لا حقيقة له ولا يمكن أحدا بتة أن يفعله وأنا أبين العلة في ذلك على تقريب إذ كان استقصاء شرحها طويلا وقد ذكرته في رسالة إلى بعض إخواني في علل النغم وشرحت هناك العلة في أن قسم الغناء قسمين وجعل على مجريين الوسطى والبنصر دون غيرهما حتى لا يدخل واحدة منهما على صاحبتها في مجراها قرب مخرج الصوت إذا كان على الوسطى منه أو إذا كان على البنصر وشبهه به فإذا أراد مريد إلحاق هذا بهذا لم يمكنه بتة على وجه ولا سبب ولا يوجد في استطاعة حيوان أن يتلو إحداهما بالأخرى وإذا\nأتبعت إحداهما بالأخرى في ناي أو آلة من آلات الزمر تفصلت إحداهما من الأخرى وإنما قلت النغم في غناء الأوائل لأنهم قسموها قسمين بين هاتين الإصبعين فوجدوهما إذا دخلت إحداهما مع الأخرى في طريقتها لم يكن ذلك إلا بعد أن يفصل بينهما بنغم أخرى للسبابة والخنصر يدخل بينهما حتى تتباعد المسافة بينهما ثم لا يكون لذلك الغناء ملاحة ولا طيب للمضادة في المجريين بينهما فتركوه ولم يستعملوه فإن كان صح لعبيد الله عمل في النغم العشر في صوت فلعله صح له في الصوت الذي ذكر أنه فرقها فيه فأما المتوالية على ما ذكره ها هنا فمحال ولست أقدر في هذا الموضع على شرح أكثر من هذا وهو في الرسالة التي ذكرتها مشروح انتهى الجزء الثامن من كتاب الأغاني ويليه الجزء التاسع وأوله نسب كثير وأخباره","topic":"أخبار العباس بن الأحنف ونسبه","topicNo":85,"sp":7,"spl":"ذكر الأصوات التي تجمع النغم العشر","song":1,"loc":1574},
{"id":"b86-1","bab":"الجزء 8","sec":"صوت من المائة المختارة","page":"ج8 ص393","text":"(يا دار عبلة من مشارق مأسل ... درس الشؤون وعهدها لم ينجل)\n(واستبدلت عفر الظباء كأنما ... أبعارها في الصيف حب الفلفل)\nذكر يحيى بن علي أن الشعر لعنترة بن شداد وليس ذلك بصحيح وذكر غيره من الرواة أنه لعبد قيس بن خفاف البرجمي وليس ذلك بصحيح أيضا والشعر لحارثة بن بدر الغداني من قصيدة له طويلة يفتخر فيها ويذكر سالف أيامه وقد ذكرت المختار منها بعقب أخبار حارثة وبعد انقضائها والغناء المختار لأبي دلف العجلي ولحنه في المختار ثقيل اول وفيه ألحان كثيرة","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":0,"spl":"صوت من المائة المختارة — مرتبته بين الشعراء","loc":1575},
{"id":"b86-2","bab":"الجزء 8","sec":"نسب حارثة بن بدر وأخباره","page":"ج8 ص394","text":"حارثة بن بدر بن حصين بن قطن بن غدانة بن يربوع وقال خالد بن حبل حارثة بن بدر بن مالك بن كليب بن غدانة بن يربوع وأم حارثة بن بدر امرأة من بني صريم بن الحارث يقال لها الصدوف بنت صدى أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني العلاء بن الفضل بن عبد الملك بن أبي سوية المنقري قال مر عمرو بن الأهتم بحارثة بن بدر والأحنف بن قيس وزيد بن جبلة وهم مجتمعون فسلم عليهم ثم بقي مفكرا فقالوا ما لك فقال ما في الأرض ثلاثة أنجب من آبائكم حيث جاؤوا بأمثالكم من أمثال أمهاتكم فضحكوا منه قال وأم الأحنف الزافرية واسمها حبى من باهلة وأم زيد بن جبلة\nعمرة بنت حذلم من بني الشعيراء وأم حارثة الصدوف بنت صدى من بني صريم بن الحارث وقد مضى نسب بني يربوع في نسب جرير وغيره من عشيرته من هذا الكتاب وفي بني غدانة يقول الفرزدق\n(أبني غدانة أنني حررتكم ... فوهبتكم لعطية بن جعال)\n(لولا عطية لاجتدعت أنوفكم ... من بين ألأم أعين وسبال)\nكان عطية استوهب منه أعراضهم لصهر كان بينه وبينهم وكان عطية سيدا من سادات بني تميم فلما سمع هذا الشعر قال والله لقد امتن علي أبو فراس بهذه الهبة وما تممها حتى ارتجعها ووصل الامتنان بتحريرهم بأقبح هجاء لهم قال وكان عطية هذا جوادا وفيه يقول جرير\n(إن الجواد على المواطن كلها ... وابن الجواد عطية بن جعال)\n(يهب النجائب لا يمل عطاءها ... والمقربات كأنهن سعالى)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":0,"spl":"صوت من المائة المختارة — مرتبته بين الشعراء","loc":1576},
{"id":"b86-3","bab":"الجزء 8","sec":"مرتبته بين الشعراء","page":"ج8 ص395","text":"وحارثة بن بدر من فرسان بني تميم ووجوهها وساداتها وجودائها وأحسب أنه قد أدرك النبي في حال صباه وحداثته\nوهو من ولد بني الأحنف بن قيس وليس بمعدود في فحول الشعراء ولكنه كان يعارض نظراءه الشعر وله من ذلك أشياء كثيرة ليست مما يلحقه بالمتقدمين في الشعر والمتصرفين في فنونه أخبرني أحمد بن عبد العزيز الجوهري قال أنبأنا عمر بن شبة قال أنبأنا المدائني قال كان زياد مكرما لحارثة بن بدر قابلا لرأيه محتملا لما يعلمه من تناوله الشراب فلما ولي عبيد الله بن زياد أخر حارثة بعض التأخير فعاتبه على ذلك فقال له عبيد الله إنك تتناول الشراب فقال له قد كان أبوك يعلم هذا مني ويقربني ويكرمني فقال له إن أبي كان لا يخاف من القالة في تقريبك ما أخاف وإن اللسان إلي فيك لأسرع منه إلى أبي فقال حارثة\n(وكم من أمير قد تجبر بعدما ... مريت له الدنيا بسيفي فدرت)\n(إذا ما هي احلولت نفى حق مقسمي ... ويقسم لي منها إذا ما أمرت)\n(إذا زبنته عن فواق يريده ... دعيت ولا أدعى إذا ما أقرت)\nوقال حارثة بن بدر أيضا وقد شاوره عبيد الله في بعض الأمر\n(أهان وأقصى ثم ينتصحونني ... ومن ذا الذي يعطي نصيحته قسرا)\n(رأيت أكف المصلتين عليكم ... ملاء وكفي من عطاياكم صفرا)\n(متى تسألوني ما علي وتمنعوا الذي ... لي لم أسطع على ذلكم صبرا)\nقال له عبيد الله فإني معوضك وموليك فولاه","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":0,"spl":"صوت من المائة المختارة — مرتبته بين الشعراء","loc":1577},
{"id":"b86-4","bab":"الجزء 8","sec":"نماذج من شعره","page":"ج8 ص397","text":"أخبرني يحيى بن علي إجازة قال أنبأنا أحمد بن يحيى بن جابر البلاذري قال قال لي أبو اليقظان حول زياد دعوة حارثة بن بدر وديوانه في قريش لمكانه منه فقال فيه رجل من بني كليب يهجوه بذلك\n(شهدت بأن حارثة بن بدر ... غداني اللهازم والكلام)\n(سجاح في كتاب الله أدنى ... له من نوفل وبني هشام)\nعني سجاح التي ادعت النبوة وهي امرأة من بني تميم قال أحمد بن يحيى وقال المدائني احترقت دار حارثة بن بدر بالبصرة أحرقها بعض أعدائه من بني عمه فقال في ذلك\n(رأيت المنايا بادئات وعودا ... إلى دارنا سهلا إليها طريقها)\n(لها نبعة كانت تقينا فروعها ... فقد تلفت إلا قليلا عروقها)\nقال وكان لحارثة أخ يقال له دارع فأحرق مع ابن الحضرمي بالبصرة وقال أحمد بن يحيى أيضا\nكان عطية بن جعال يهاجي حارثة بن بدر ثم اصطلحا وكان أيضا يهاجيه من قومه العكمص وكانت بنو سليط تروي هجاءه لحارثة بن بدر فقال حارثة يهجوهم\n(أراوية علي بنو سليط ... هجاء الناس يا لبني سليط)\n(فما لحمي لتأكله سليط ... شبيها بالذكي ولا العبيط)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":1,"spl":"نماذج من شعره","loc":1578},
{"id":"b86-5","bab":"الجزء 8","sec":"حوار شعري بينه وبين أنس بن زنيم","page":"ج8 ص398","text":"أخبرنا أحمد بن محمد بن عبد الله بن صالح بن سمح بن عمرة الأسدي أبو الحسن قال أنبأنا حماد بن إسحاق عن أبيه قال قال روح بن السكن كان أنس بن زنيم الليثي صديقا لعبيد الله بن زياد فرأى منه جفوة وأثرة لحارثة بن بدر الغداني فقال\n(أهان وأقصى ثم ترجى نصيحتي ... وأي امرىء يعطي نصيحته قسرا)\n(رأيت أكف المصلتين عليكم ... ملاء وكفي من عطاياكم صفرا)\n(فإن تسألوني ما علي وتمنعوا ال ... ذي لي لم أسطع على ذلكم صبرا)\n(رأيتكم تعطون من ترهبونه ... زربية قد وشحت حلقا صفرا)\n(وإني مع الساعي عليكم بسيفه ... إذا عظمكم يوما رأيت به كسرا)\nفقال عبيد الله بن زياد لحارثة بن بدر أجبه فاستعفاه لمودة كانت بينهما فأكرهه على ذلك وأقسم عليه ليجيبنه فقال\n(تبدلت من أنس إنه ... كذوب المودة خوانها)\n(أراه بصيرا بضر الخليل ... وخير الأخلاء عورانها)\nأجابه أنس فقال\n(إن الخيانة شر الخليل ... والكفر عندك ديوانها)\n(بصرت به في قديم الزمان ... كما بصر العين إنسانها)\nأجابه حارثة بن بدر فقال\n(ألكني إلى أنس إنه ... عظيم الحواشة عندي مهيب)\n(فما أبتغي عثرات الخليل ... ولا أبغين عليه الوثوب)\n(وما إن أرى ماله مغنما ... من الدهر إن أعوزتني الكسوب)\nقال أنس\n(أحار بن بدر وأنت امرؤ ... لعمري المتاع إلي الحبيب)\n(متى كان مالك لي مغنما ... من الدهر إن أعوزتني االكسوب)\n(وشر الأخلاء عند البلاء ... وعند الرزية خل كذوب)\nال فتهادى أنس وحارثة الشعر عند عبيد الله زمانا ووقع بينهما شر حتى قدم سلم بن زياد من عند يزيد بن معاوية عاملا على خراسان وسجستان\nفجعل ينتخب ناسا من أهل البصرة والكوفة وكان الذي بين عبيد الله وبين سلم شيئا فأرسل سلم إلى أنس يعرض عليه صحبته وجعل له أن يستعمله على كورة فقال له أنس أمهلني حتى أنظر في أمري وكتب إلى عبيد الله بن زياد\n(ألم ترني خيرت والأمر واقع ... فما كنت لما قلت بالمتخير)\n(رضاك على شيء سواه ومن يكن ... إذا اختار ذا حرم من الأمر يظفر)\n(فعدت لترضى عن جهاد وصاحب ... شفيق قديم الود كان موقري)\n(على أحد الثغرين ثم تركته ... وقد كنت في تأميره غير ممتري)\n(فأمسكت عن سلم عناني وصحبتي ... ليعرف وجه العذر قبل التعذر)\n(فإن كنت لما تدر ما هي شيمتي ... فسل بي أكفائي وسل ربي معشري)\n(ألست مع الإحسان والجود ذا غنى ... وبأس إذا ما كفروا في التستر)\n(ورأي وقد أعصى الهوى خشية الردى ... وأعرف غب الأمر قبل التدبر)\n(وما كنت لولا ذاك ترتد بغيتي ... علي ارتداد المظلم المتجبر)\nال ودفعها إلى عبيد الله بن زياد في صحيفة فقرأها ثم دفعها إلى حارثة بن بدر وقال له اردد على أنس صحيفته فلا حاجة لنا فيها فقال حارثة\n(ألكني إلى من قال هذا وقل له ... كذبت فما إن أنت بالمتخير)\n(وإنك لو صاحبت سلما وجدته ... كعهدك عهد السوء لم يتغير)\n(أتنصح لي يوما ولست بناصح ... لنفسك فاغشش ما بدا لك أو ذر)\n(كذبت ولكن أنت رهن بخزية ... ويوم كأيام عبوس مذكر)\n(كأشقر أضحى بين رمحين إن مضى ... على الرمح ينحر أو تاخر يعقر)\nال وأعجبت عبيد الله وقال لعمري لقد أجبته على إرادتي وأمسك عبيد الله في يده الصحيفة فلما دخل عليه أنس دفعها إليه فنظر فيها ثم قال لعبيد الله لقد رد علي من لا أستطيع جوابه وظن أن عبيد الله قالها وخرج أنس والصحيفة في يده فلقيه عبد الرحمن بن رألان فدفعها إليه أنس فلما قرأها قال هذا شعر حارثة بن بدر أعرفه فقال له أنس صدقت والله ثم قال لحارثة\n(عجبت لهرج من زمان مضلل ... ورأي لألباب الرجال مغير)\n(ومن حقبة عوجاء غول تلبست ... على الناس جلد الأربد المتنمر)\n(فلا يعرف المعروف فيه لأهله ... وإن قيل فيه منكر لم ينكر)\n(لحارثة المهدي الخنى لي ظالما ... ولم أر مثل مدر صيد مدري)\n(لحار بن بدر قد أتتني مقالة ... فما بال نكر منك من غير منكر)\n(أيروي عليك الناس ما لا تقوله ... فتعذر أم أنت امرؤ غير معذر)\n(فإن يك حقا ما يقال فلا يكن ... دبيبا وجاهرني فما من تستر)\n(أقلدك إن كنت امرأ خان عرضه ... قوافي من باقي الكلام المشهر)\n(وقد كنت قبل اليوم جربت أنني ... أشق على ذي الشعر والمتشعر)\n(وأن لساني بالقصائد ماهر ... تعن له غر القوافي وتنبري)\n(أصادفها حينا يسيرا وأبتغي ... لها مرة شزرا إذا لم تيسر)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":2,"spl":"حوار شعري بينه وبين أنس بن زنيم","loc":1579},
{"id":"b86-6","bab":"الجزء 8","sec":"حوار شعري بينه وبين أنس بن زنيم","page":"ج8 ص398","text":"(تناولني بالشتم في غير كنهه ... فمهلا ابا الخيماء وابن المعذر)\n(هجوت وقد ساماك في الشعر خطة الذليل ... ولم يفعل كأفعال منكر)\nقال وقال أنس بن زنيم لعبيد الله بن زياد وفيه غناء\n(سل أميري ما الذي غيره ... عن وصالي اليوم حتى ودعه)\n(لا تهني بعد إكرامك لي ... فشديد عادة منتزعه)\n(لا يكن وعدك برقا خلبا ... إن خيرالبرق ما الغيث معه)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":3,"spl":"حوار شعري بينه وبين أنس بن زنيم — رده على الأحنف وقد عاتبه على شربه الخمر","loc":1580},
{"id":"b86-7","bab":"الجزء 8","sec":"شعره في طلب الخمر","page":"ج8 ص402","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال زعم عاصم بن الحدثان أن حارثة بن بدر قال لعبيد الله بن ظبيان وكانا في عرس لابن مسمع هل لك في شراب قال نعم فأتيا بنبيذ من زبيب وعسل فأخذ ابن ظبيان العس فكرع فيه حتى كاد يأتي عليه ثم ناوله حارثة فقال له حارثة يابن ظبيان إنك لطب بحسوها فقال أجل والله إني لأشربها حلالا وأجاهر بها إذا أخفى غيري شرب الحرام فقال له حارثة من غيرك هذا قال سائلي عن هذا الأمر فقال حارثة\n(إذا كنت ندماني فخذها وسقني ... ودع عنك من رآك تكرع في الخمر)\n(فإني امرؤ لا أشرب الخمر في الدجا ... ولكنني أحسو النبيذ من التمر)\n(حيا وتقا لله والله عالم ... بكل الذي نأتيه في السر والجهر)\n(ومثلك قد جربته وخبرته ... أبا مطر والحين أسبابه تجري)\n(حساها كمستدمى الغزال عتيقة ... إذا شعشعت بالماء طيبة النشر)\n(أقام عليها دهره كل ليلة ... يشافهها حتى يرى وضح الفجر)\n(فأصبح ميتا ميتة الكلب ضحكة ... لأصحابه حتى يدهده في القبر)\n(فما إن بكاه غير دن ومزهر ... وغانية كالبدر واضحة الثغر)\n(وباطية كانت له خدن زنية ... يعاقرها والليل معتكر الستر)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":3,"spl":"حوار شعري بينه وبين أنس بن زنيم — رده على الأحنف وقد عاتبه على شربه الخمر","loc":1581},
{"id":"b86-8","bab":"الجزء 8","sec":"رده على الأحنف وقد عاتبه على شربه الخمر","page":"ج8 ص403","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن عاصم بن الحدثان قال عاتب الأحنف بن قيس حارثة بن بدر على معاقرة الشراب وقال له قد فضحت نفسك وأسقطت قدرك وأوجعه عتابا فقال له إني سأعتبك فانصرف الأحنف طامعا في صلاحه فلما أمسى راح إليه فقال له اسمع يا ابا بحر ما قلت لك فقال هات فأنشده\n(يذم أبو بحر أمورا يريدها ... ويكرهها للأريحي المسود)\n(فإن كنت عيابا فقل ما تريده ... ودع عنك شربي لست فيه بأوحد)\n(سأشربها صهباء كالمسك ريحها ... وأشربها في كل ناد ومشهد)\n(فنفسك فانصح يابن قيس وخلني ... ورأيي فما رأيي برأي مفند)\n(وقائلة يا حار هل أنت ممسك ... عليك من التبذير قلت لها اقصدي)\n(ولا تأمريني بالسداد فإنني ... رأيت الكثير المال غير مخلد)\n(ولا عيب إلا اصطباحي قهوة ... متى يمتزجها الماء في الكأس تزبد)\n(معتقة صهباء كالمسك ريحها ... إذا هي فاحت أذهبت غلة الصدي)\n(إلا إنما الرشد المبين طريقه ... خلاف الذي قد قلت إذ أنت مرشدي)\n(سأشربها ما حج لله راكب ... مجاهرة وحدي ومع كل مسعد)\n(وأسعد ندماني وأتبع شهوتي ... وأبذل عفوا كل ما ملكت يدي)\n(كذا العيش لا عيش ابن قيس وصحبه ... من الشرب للماء القراح المصرد)\nقال له الأحنف حسبك فإني أراك غير مقلع عن غيك ولن أعاتبك بعدها أبدا قال عاصم ثم كان بعد ذلك بين الأحنف وحارثة كلام وخصومة فافترقا عن مجلسهما متغاضبين فبلغ حارثة أن الأحنف قال أما والله لولا ما يعلم لقلت فيه ما هو أهله فقال حارثة وهل يقدر على أن يذمني بأكثر من الشراب وحبي له وذلك أمر لست أعتذر منه إلى أحد ثم قال في ذلك\n(وكم لائم لي في الشراب زجرته ... فقلت له دعني وما أنا شارب)\n(فلست عن الصهباء ما عشت مقصرا ... وإن لامني فيها اللئام الأشائب)\n(أأترك لذاتي وآتي هواكم ... ألا ليس مثلي يابن قيس يخالب)\n(أنا الليث معدوا عليه وعاديا ... إذا سلت البيض الرقاق القواضب)\n(فأنت حليم تزجر الناس عن هوى ... نفوسهم جهلا وحلمك عازب)\n(فحلمك صنه لا تذله وخلني ... وشأني واركب كل ما أنت راكب)\n(فإني امرؤ عودت نفسي عادة ... وكل امرى لا شك ما اعتاد طالب)\n(أجود بمالي ما حييت سماحة ... وأنت بخيل يجتويك المصاحب)\n(فما أنت أو ما غي من كان غاويا ... إذا أنت لم تسدد عليك المذاهب)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":3,"spl":"حوار شعري بينه وبين أنس بن زنيم — رده على الأحنف وقد عاتبه على شربه الخمر","loc":1582},
{"id":"b86-9","bab":"الجزء 8","sec":"قصته مع الوليد بن عبد الملك","page":"ج8 ص405","text":"أخبرني هاشم بن محمد الخزاعي قال أنبأنا أبو الأسود الخليل بن اسد قال أنبأنا العمري عن العتبي قال أجرى الوليد بن عبد الملك الخيل وعنده حارثة بن بدر الغداني وهو حينئذ في ألف وستمائة من العطاء فسبق الوليد فقال حارثة هذه فرصة فقام فهنأه ودعا له ثم قال\n(إلى الألفين مطلع قريب ... زيادة أربع لي قد بقينا)\n(فإن أهلك فهن لكم وإلا ... فهن من المتاع لكم سنينا)\nقال له الوليد فتشاطرني ذلك لك مائتان ولي مائتان فصير عطاءه ألفا وثمانمائة ثم أجرى الوليد الخيل فسبق أيضا فقال حارثة هذه فرصة أخرى فقام فهنأه ودعا له ثم قال\n(وما احتجب الألفان إلا بهين ... هما الآن أدنى منهما قبل ذالكا)\n(فجد بهما تفديك نفسي فإنني ... معلق آمالي ببعض حبالكا)\nفأمر الوليد له بالمائتين فانصرف وعطاؤه ألفان أخبرني محمد بن يحيى قال أنبأنا محمد بن زكريا قال أنبأنا مهدي بن سابق قال أنبأنا عبد الرحمن بن شبيب بن شيبة عن أبيه قال قال زياد يوما لحارثة بن بدر من أخطب الناس أنا أو أنت فقال الأمير أخطب مني إذا توعد ووعد وأعطى ومنع وبرق ورعد وأنا أخطب منه في الوقادة وفي الثناء والتحبير وأنا أكذب إذا خطبت فأحشوا كلامي بزيادة مليحة شهية والأمير يقصد إلى الحق وميزان العدل ولا يزيد فيه شعيرة ولا ينقص منه فقال له زياد قاتلك الله فلقد اجدت تخليص صفتك وصفتي من حيث أعطيت نفسك الخطابة كلها وأرضيتني وتخلصت ثم التفت إلى أولاده فقال هذا لعمركم البيان الصريح أخبرني محمد بن يحيى قال أنبأنا محمد بن زكريا عن الحرمازي قال شرب حارثة بن بدر مع بني زياد ليلة إلى الصبح فأكثر وصرف ومزجوا فلما أن غدا على زياد كان وجهه شديد الحمرة ففطن له زياد فقال مالك يا حارثة فقال أكلت البارحة رمانا فأكثرت قال قد عرفت مع من أكلته ولكنهم قشروه وأكلته بقشره فأصارك إلى ما ترى","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":4,"spl":"قصته مع الوليد بن عبد الملك — هو وسعد الرابية في مجلس لابن زياد","loc":1583},
{"id":"b86-10","bab":"الجزء 8","sec":"رثاؤه زيادا بن عبيد الله","page":"ج8 ص406","text":"قال الحرمازي قال بعض أهل العلم إن زيادا استعمل حارثة على سرق فمات\nزياد وهو بها ثم إنه بلغه موته فقال حارثة يرثيه\n(إن الرزية في قبر بمنزلة ... تجري عليها بظهر الكوفة المور)\n(أدت إليه قريش نعش سيدها ... ففيه ضافي الندى والحزم مقبور)\n(أبا المغيرة والدنيا مغيرة ... وإن من غر بالدنيا لمغرور)\n(قد كان عندك للمعروف معرفة ... وكان عندك للنكراء تنكير)\n(وكنت تؤتى فتعطي الخير عن سعة ... فاليوم بابك دون الهجر مهجور)\n(ولا تلين إذا عوسرت مقتسرا ... وكل أمرك ما يوسرت ميسور)\nال وكان الذي أتاه بنعيه مسعود بن عمرو الأزدي فقال حارثة\n(لقد جاء مسعود أخو الأزد غدوة ... بداهية غراء باد حجولها)\n(من الشر ظل الناس فيها كأنهم ... وقد جاء بالأخبار من لا يحيلها)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":4,"spl":"قصته مع الوليد بن عبد الملك — هو وسعد الرابية في مجلس لابن زياد","loc":1584},
{"id":"b86-11","bab":"الجزء 8","sec":"هو وسعد الرابية في مجلس لابن زياد","page":"ج8 ص407","text":"أخبرني الحسن بن علي قال أنبأنا العمري عن أحمد بن خالد بن منجوف عن مؤرج السدوسي قال دخل حارثة بن بدر على عبيد الله بن زياد وعنده سعد الرابية أحد بني عمرو بن يربوع بن حنظلة وكان شريرا يضحك ابن زياد ويلهيه وله يقول الفرزدق\n(إني لأبغض سعدا أن أجاوره ... ولا أحب بني عمرو بن يربوع)\n(قوم إذا حاربوا لم يخشهم أحد ... والجار فيهم ذليل غير ممنوع)\nفلما جلس حارثة قال له سعد يا حارثة أينع الكرم قال نعم واستودع ماءه الأصيص فمه قال إني لم أرد بأسا قال أجل ولست من أهل البأس ولكن هل لك علم بالأتان إذا اعتاص رحمها كيف يسطى عليها أكما يسطى على الفرس أم كيف قال واحدة بواحدة والبادي أظلم سألتني عما لا علم لي به وسألتك عما تعلم قال أنت بما سألتك عنه أعلم مني بما سألتني عنه ولكن من شاء جهل نفسه وأنكر ما يعرف وقال حارثة يهجو سعدا\n(لا ترج مني يابن سعد هوادة ... ولا صحبة ما أرزمت أم حائل)\n(أعند الأمير ابن الأمير تعيبني ... وأنت ابن عمرو مضحك في القبائل)\n(ولو غيرنا يا سعد رمت حريمه ... بخسف لقد غودرت لحما لآكل)\n(فشالت بك العنقاء أو صرت لحمة ... لأغبس عواء العشيات عاسل)\nخبرني هاشم بن محمد قال أنبأنا الرياشي عن الأصمعي وأبي عبيدة قالا كان حارثة بن بدر يجالس مالك بن مسمع فإذا جاء وقت يشرب فيه قام فأراد مالك أن يعلم من حضره أنه قام ليشرب فقال له إلى أين تمضي يا أبا العنبس قال أجيء بعباد بن الحصين يفقأ عينك الأخرى وقال\nالأصمعي أمضي فأفقأ عين عباد بن الحصين لآخذ لك بثأرك وكان عباد فقأ عين مالك يوم المربد","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":4,"spl":"قصته مع الوليد بن عبد الملك — هو وسعد الرابية في مجلس لابن زياد","loc":1585},
{"id":"b86-12","bab":"الجزء 8","sec":"شعره في فتنة مسعود","page":"ج8 ص409","text":"قال وذكر المدائني أن حارثة بن بدر كان يومئذ وهو يوم فتنة مسعود على خيل حنظلة بإزاء بكر بن وائل فجعل عبس بن مطلق بن ربيعة الصريمي على الخيل بحيال الأزد ومعه سعد والرباب والأساورة وقال حارثة بن بدر\n(سيكفيك عبس أخو كهمس ... مقارعة الأزد بالمربد)\n(ويكفيك عمرو واشياعه ... لكيز بن أفصى وما عددوا)\n(وأكفيك بكرا إذا أقبلت ... بطعن يشيب له الأمرد)\nلما اصطف الناس أرسل مالك بن مسمع إلى ضرار بن القعقاع يسأله الصلح على أن يعطيه ما أحب فقال له حارثة إنه والله ما أرسل إليك نظرا لك ولا إبقاء عليك ولكنه أراد أن يغري بينك وبين سعد فمضى ضرار إلى راية الأحنف فحملها وحمل على مالك فهزمه وفقئت عينه يومئذ أخبرني محمد بن يحيى قال أنبأنا محمد بن زكريا عن محمد بن سلام عن أبي اليقظان قال مر حارثة بن بدر بالمسجد الذي يقال له مسجد الأحامرة بالبصرة فرأى مشيخة قد خضبوا لحاهم بالحناء فقال ما هذه الأحامرة فالمسجد الآن يلقب مسجد الأحامرة منذ يوم قال حارثة هذا القول\nخبرني محمد بن يحيى قال أنبأنا محمد بن زكريا عن القحذمي قال عرض لحارثة بن بدر رجل من الخلج في أمر كرهه عند زياد فقال فيه حارثة\n(لقد عجبت وكم للدهر من عجب ... مما تزيد في أنسابها الخلج)\n(كانوا خسا أو زكا من دون أربعة ... لم يخلقوا وجدود الناس تعتلج)\nلخسا الفرد والزكا الزوج أخبرني الحسن بن علي قال أنبأنا أحمد بن يحيى قال أنبأنا محمد بن عمر بن زياد الكندي قال أنبأنا يحيى بن آدم عن أبي زائدة عن مجالد عن الشعبي قال كنت عند عبد الله بن جعفر بن أبي طالب فأنشدته لحارثة بن بدر\n(وكان لنا نبع تقينا عروقه ... فقد بلغت إلا قليلا حلوقها)\n(وشيب رأسي واستخف حلومنا ... رعود المنايا فوقنا وبروقها)\n(وإنا لتستحلي المنايا نفوسنا ... وتترك أخرى مرة ما تذوقها)\n(رأيت المنايا بادئات وعودا ... إلى دارنا سهلا إليها طريقها)\n(فقد قسمت نفسي فريقين منهما ... فريق مع الموتى وعندي فريقها)\nال الشعبي فقال لي ابن جعفر نحن كنا أحق بهذا الشعر وجاءه غلامه بدراهم في منديل فقال له هذه غلة أرضك بمكان كذا وكذا فقال ألقها في حجر الشعبي فألقاها في حجري أخبرني الحسن بن علي قال أنبأنا أحمد بن الحارث الخراز عن\nالمدائني عن مسلمة بن محارب أن زيادا استعمل حارثة بن بدر على كوار وهو إذ ذاك عامل علي بن أبي طالب رضي الله عنه على فارس وكان حارثة بن بدر صاحب شراب فكتب زياد إلى حارثة يحثه على جباية الخراج فكتب إليه علقمة بن معبد المازني\n(ألم تر أن حارثة بن بدر ... يصلي وهو أكفر من حمار)\n(وأن المال يعرف من حواه ... ويعرف بالزواني والعقار)\nقال المدائني في خبره هذا حمل زياد بن أبيه حارثة بن بدر على بغلة يقال لها أطلال كان خرزاذ بن الهربد ابتاعها بأربعة آلاف درهم وأهداها له فركبها حارنة وكان فيها نفار فصرعته عن ظهرها فقام فركبها وقال\n(ما هاج أطلال بجنبي حرمه ... تحمل وضاحا رفيع الحكمه)\n(قرما إذا زاحم قرما زحمه ... )","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":5,"spl":"شعره في فتنة مسعود","loc":1586,"partial":1},
{"id":"b86-13","bab":"الجزء 8","sec":"جوابه على سليمان بن عمرو وقد قراه وقرى أصحابه","page":"ج8 ص412","text":"أخبرني محمد بن يحيى قال أنبأنا محمد بن زكرياء قال أنبأنا إبراهيم بن عمر عن أبي عبيدة وعبد الله بن محمد قالا مر سليمان بن عمرو بن مرثد بحارثة بن بدر وهو بفارس يريد خراسان فأنزله وقراه وقرى اصحابه وحملهم وإياه فلما ركبوا للمسير قال سليمان\n(قريت فأحسنت القرى وسقيتنا ... معتقة صهباء كالعنبر الرطب)\n(وواسيتنا فيما ملكت تبرعا ... وكنت ابن بدر نعم ذو منزل الركب)\n(وأنت لعمري في تميم عمادها ... إذا ما تداعت للعلى موضع القطب)\n(وفارسها في كل يوم كريهة ... وملجؤها إن حل خطب من الخطب)\n(وعندكم نال الغنى من أراده ... إذا ما خطرتم كالضراغمة الغلب)\n(يرى الحلق الماذي فوق حماتهم ... إذا الحرب شبت بالمهندة القضب)\n(وعند الرخا والأمن غيث ورحمة ... لمن يعتريهم خائفا صولة الحرب)\n(وجدتهم جودا صباحا وجوههم ... كراما على العلات في فادح الخطب)\n(كأن دنانيرا على قسماتهم ... إذا جئتهم قد خفت نكبا من النكب)\n(فمن مبلغ عني تميما فخيركم ... غدانة حقا قاله غير ذي لعب)\nقال حارثة يجيبه\n(وأسحم ملآن جررت لفتية ... كرام أبوهم خير بكر بن وائل)\n(وأطولهم كفا وأصدقهم حيا ... وأكرمهم عند اختلاف المناصل)\n(من المرثديين الذين إذا انتدوا ... رأيت نديا جده غير خامل)\n(فعالهم زين لهم ووجوههم ... تزين الذي يأتونه في المحافل)\n(فسقيا ورعيا لابن عمرو بن مرثد ... سليمان ذي المجد التليد الحلاحل)\n(فتى لم يزل يسمو إلى كل نجدة ... فيدرك ما أعيت يد المتناول)\n(فحسبك بي علما به وبفضله ... إذا ذكر الأقوام أهل الفضائل)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":6,"spl":"جوابه على سليمان بن عمرو وقد قراه وقرى أصحابه","loc":1587},
{"id":"b86-14","bab":"الجزء 8","sec":"في مجلس ابن زياد","page":"ج8 ص413","text":"أخبرني عمي قال أنبأنا الكراني قال أنبأنا العمري عن عطاء بن مصعب عن عاصم بن الحدثان قال دخل أنس بن زنيم على عبيد الله بن زياد وعنده حارثة بن بدر وكان بينهما تعارض ومقارضة قبل ذلك فلما خرج أنس قال عبيد الله لحارثة أي رجل هو أنس عندك قال هو عندي أصلح الله الأمير كما قلت فيه\n(يبيت بطينا من لحوم صديقه ... خميصا من التقوى ومن طلب الحمد)\n(ينام إذا ما الليل جن ظلامه ... ويسري إلى حاجاته نومة الفهد)\n(يراعي عذارى قومه كلما دجا ... له الليل والسوآت كالأسد الورد)\n(جريئا على أكل الحرام وفعله ... جبانا عن الأقران معترم الكرد)\nفلما كان من الغد دخل أنس على عبيد الله فقال له عبيد الله بحضرة حارثة إني سألت هذا عنك فأخبرني بما كرهته لك ولم أكن إخالك كما نعت لي فقال أصلح الله الأمير إن يكن قال خيرا فأنا أهله وإن قال غير ذلك فلم يعد ما هو أولى به مني أما والله لو كان أصلح الله الأمير حقا لحفظ غيبتي فلقد أوليته حسن الثناء بما ليس أهله والله يعلم أني كنت كاذبا وما إخال ما قاله في إلا عقوبة فإن عقوبة الكذب حاضرة وثمرة الكذب الندامة فقد لعمري أجنيتها بكذبي وقولي فيه ما ليس فيه وهو عندي كما أقول أصلح الله الأمير وأنشد\n(يحلى لي الطرف ابن بدر وإنني ... لأعرف في وجه ابن بدر لي البغضا)\n(رآني شجا في حلقه ما يسيغه ... فما إن يزال الدهر يجرض بي جرضا)\n(وما لي من ذنب إليه علمته ... سوى أن رآني في عشيرته محضا)\n(وإن ابن بدر في تميم مكركس ... إذا سيم خسفا أو مشنعة أغضى)\n(فعش يابن بدر ما بقيت كما أرى ... كثير الخنا لا تسأم الذل والغضا)\n(تعيب الرجال الصالحين وفعلهم ... وتبذل بخلا دون ما نلته العرضا)\n(وترضى بما لا يرتضي الحر مثله ... وذو الحلم بالتخييس والذل لا يرضى)\nقال وقال أنس في حارثة بن بدر ينسبه إلى الخمر والفجور\n(أحار بن بدر باكر الراح إنها ... تنسيك ما قدمت في سالف الدهر)\n(تنسيك أسبابا عظاما ركبتها ... وأنت على عمياء في سنن تجري)\n(أتذكر ما أسديت واخترت فعله ... وجئت من المكروه والشر والنكر)\n(إذا قلت مهلا نلت عرضي فما الذي ... تعيب على مثلي هبلت أبا عمرو)\n(أليس عظيما أن تكايد حرة ... مهفهفة الكشحين طيبة النشر)\n(فإن كنت قد أزمعت بشرك بالذي ... عرفت به إذ أنت تخزي ولا تدري)\n(فدع عنك شرب الخمر وارجع إلى التي ... بها يرتضي أهل النباهة والذكر)\n(عليك نبيذ التمر إن كنت شاربا ... فإن نبيذ التمر خير من الخمر)\n(ألا إن شرب الخمر يزري بذي الحجى ... ويذهب بالمال التلاد وبالوفر)\n(فصبرا عن الصهباء واعلم بأنني ... نصيح وأني قد كبرت عن الزجر)\n(وأنك إن كفكفتني عن نصيحة ... تركتك يا حار بن بدر إلى الحشر)\n(أأبذل نصحي ثم تعصي نصيحتي ... وتهجرني عنها هبلت ابا بدر)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":7,"spl":"في مجلس ابن زياد","loc":1588},
{"id":"b86-15","bab":"الجزء 8","sec":"جوابه على أبي الأسود الدؤلي وقد ولي سرق","page":"ج8 ص415","text":"أخبرني احمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا عبد الله بن محمد بن حكيم عن خالد بن سعيد عن أبيه قال لما ولي حارثة بن بدر سرق خرج معه المشيعون من البصرة وفيهم أبو الأسود الدؤلي فلما انصرف المشيعون دنا منه ابو الأسود فقال له\n(أحار بن بدر قد وليت إمارة ... فكن جرذا فيها تخون وتسرق)\n(ولا تحقرن يا حار شيئا تصيبه ... فحظك من ملك العراقين سرق)\n(فإن جميع الناس إما مكذب ... يقول بما يهوى وإما مصدق)\n(يقولون أقوالا بظن وشبهة ... فإن قيل هاتوا حققوا لم يحققوا)\n(فلا تعجزن فالعجز أبطأ مركب ... وما كل من يدعى إلى الرزق يرزق)\n(وكاثر تميما بالغنى إن للغنى ... لسانا به يسطو العيي وينطق)\nفقال له حارثة\n(جزاك مليك الناس خير جزائه ... فقد قلت معروفا وأوصيت كافيا)\n(أمرت بحزم لو أمرت بغيره ... لألفيتني فيه لرأيك عاصيا)\n(ستلقى أخا يصفيك بالود حاضرا ... ويوليك حفظ الغيب إن كنت نائيا)\nخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن عاصم بن الحدثان قال لما ندب حارثة بن بدر لقتال الأزارقة بدولاب لقيهم فلما حميت الحرب بينهم واشتدت قال حارثة لأصحابه\n(كرنبوا ودولبوا ... وحيث شئتم فاذهبوا)\nم انهزم فقال غوث بن الحباب يهجوه ويعيره بالفرار ويعيره بشرب الخمر ومعاقرتها\n(أحار بن بدر دونك الكأس إنها ... بمثلك أولى من قراع الكتائب)\n(عليك بها صهباء كالمسك ريحها ... يظل أخوها للعدا غير هائب)\n(فدع عنك أقواما وليت قتالهم ... فلست صبورا عند وقع القواضب)\n(وخذها كعين الديك تشفي من الجوى ... وتترك ذا الهمات حصر المذاهب)\n(إذا شعشعت بالماء خلت حبابها ... نظائم در أو عيون الجنادب)\n(كأنك إذ تحسو ثلاثة أكؤس ... من التيه قرم من قروم المرازب)\n(ودع عنك أبناء الحروب وشدهم ... إذا خطروا مثل الجمال المصاعب)\nخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا العلاء بن الفضل بن أبي سوية قال حدثني أبي قال كانت في تميم حمالتان فاجتمعوا في مقبرة بني شيبان فقال لهم الأحنف لا تعجلوا حتى يحضر سيدكم فقالوا من سيدنا غيرك قال حارثة بن بدر قال وقدم حارثة من الأهواز بمال كثير فبلغه ما قال الأحنف فقال اغرمنيها والله ابن الزافرية ثم أتاهم كأنه لم يعلم فيما اجتمعوا فقال فيم اجتمعتم فأخبروه فقال لا تلقوا فيهما أحدا فهما علي ثم أتى منزله فقال\n(خلت الديار فسدت غير مسود ... ومن الشقاء تفردي بالسودد)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":8,"spl":"جوابه على أبي الأسود الدؤلي وقد ولي سرق","loc":1589},
{"id":"b86-16","bab":"الجزء 8","sec":"سفيان بن عيينة يتمثل بشعره","page":"ج8 ص417","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثنا أحمد بن سليمان بن أبي شيخ عن أبيه قال\nخرج أصحاب الحديث إلى سفيان بن عيينة فازدحموا فقال لقد هممت ألا أحدثكم شهرا فقام إليه شاب من أهل العراق فقال له يا أبا محمد ألن جانبك وحسن قولك وتأس بصالحي سلفك وأجمل مجالسة جلسائك فقد أصبحت بقية الناس وأمينا لله ورسوله على العلم والله إن الرجل ليريد الحج فتتعاظمه مشقته حتى يكاد أن يقيم فيكون لقاؤه إياك وطعمه فيك أكثر ما يحركه عليه قال فخضع سفيان وتواضع ورق وبكى ثم تمثل بقول حارثة\n(خلت الديار فسدت غير مسود ... ومن الشقاء تفردي بالسودد)\nثم حدثهم بعد ذلك بكل ما أرادوا إلى أن رحلوا أخبرني هاشم بن محمد الخزاعي ومحمد بن الحسين الكندي قالا حدثنا الخليل بن اسد قال حدثنا العمري عن الهيثم بن عدي عن الحسن بن عمارة عن الحكيم بن عتيبة أن حارثة بن بدر الغداني كان سعى في الأرض فسادا فأهدر علي بن أبي طالب عليه السلام دمه فهرب فاستجار بأشراف الناس فلم يجره أحد فقيل له عليك بسعيد بن قيس الهمداني فلعله أن يجيرك فطلب سعيدا فلم يجده فجلس في طلبه حتى جاء فأخذ بلجام فرسه فقال أجرني أجارك الله قال ويحك ما لك قال أهدر أمير المؤمنين دمي قال وفيم ذاك قال سعيت في الأرض فسادا قال ومن أنت قال حارثة بن بدر الغداني\nقال أقم وانصرف إلى علي عليه السلام فوجده قائما على المنبر يخطب فقال يا أمير المؤمنين ما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا قال أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأرض قال يا أمير المؤمنين إلا من قال إلا من تاب قال فهذا حارثة بن بدر قد جاء تائبا وقد أجرته قال أنت رجل من المسلمين وقد أجرنا من أجرت ثم قال علي عليه السلام وهو على المنبر أيها الناس إني كنت نذرت دم حارثة بن بدر فمن لقيه فلا يعرض له فانصرف إليه سعيد بن قيس فأعلمه وحمله وكساه وأجازه بجائزة سنية فقال فيه حارثة\n(الله يجزي سعيد الخير نافلة ... أعني سعيد بن قيس قرم همدان)\n(أنقذني من شفا غبراء مظلمة ... لولا شفاعته ألبست أكفاني)\n(قالت تميم بن مر لا نخاطبه ... وقد أبت ذلكم قيس بن عيلان)\nقال الهيثم لم يكن الحسن بن عمارة يروي من هذا الشعر غير هذه الثلاثة الأبيات وأخذت الشعر كله من حماد الراوية فقلت له ممن أخذته قال من سماك بن حرب وهو\n(أساغ في الحلق ريقا كان يجرضني ... وأظهر الله سري بعد كتمان)\n(إني تداركني عف شمائله ... آباؤه حين ينمى خير قحطان)\n(ينميه قيس وزيد والفتى كرب ... وذو جبائر من أولاد عثمان)\n(وذو رعين وسيف وابن ذي يزن ... وعلقم قبلهم أعني ابن نبهان)\nال فلما أراد الانصراف إلى البصرة شيعه سعيد بن قيس إلى نهر\nالبصريين في ألف راكب وحمله وجهزه فقال حارثة\n(لقد سررت غداة النهر إذ برزت ... أشياخ همدان فيها المجد والخير)\n(يقودهم ملك جزل مواهبه ... واري الزناد لدى الخيرات مذكور)\n(أعني سعيد بن قيس خير ذي يزن ... سامي العماد لدى السلطان محبور)\n(ما إن يلين إذا ما سيم منقصة ... لكن له غضب فيها وتنكير)\n(أغر أبلج يستسقى الغمام به ... جنابه الدهر يضحي وهو ممطور)\nخبرني محمد بن يحيى قال حدثنا محمد بن زكريا قال حدثنا محمد بن معاوية الزيادي عن القحذمي قال كان حارثة بن بدر فصيحا بليغا عارفا بأخبار الناس وأيامهم حلوا شاعرا ذا فكاهة فكان زياد يأنس به طول حياته فلما مات وولي عبيد الله ابنه كان يجفوه فدخل إليه في جمهور الناس فجلس متواريا منه حتى خف الناس ثم قام فأذكره بحقوقه على زياد وأنسه به فقال له ما أعرفني بما قلت غير أن أبي كان قد عرفه الناس وعرفوا سيرته فلم يكن يلصق به من أهل الريبة مثل ما يلحقني مع الشباب وقرب العهد بالإمارة فأما إن قلت ما قلت فاختر مجالستي إن شئت ليلا وإن شئت نهارا فقال الليل أحب إلي فكان يدعوه ليلا فيسامره فلما عرفه استحلاه فغلب عليه ليله ونهاره حتى كان يغيب فيبعث من يحضره فجاءه ليلة وبوجهه آثار فقال له ما هذا يا حار قال ركبت فرسي الأشقر فلجج بي مضيقا فسحجني قال لكنك لو ركبت أحد\nالأشهبين لم يصبك شيء من هذا يعني اللبن والماء","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":9,"spl":"سفيان بن عيينة يتمثل بشعره","loc":1590},
{"id":"b86-17","bab":"الجزء 8","sec":"طلق زوجته ثم ندم على ذلك","page":"ج8 ص420","text":"أخبرني محمد بن يحيى قال أنبأنا محمد بن زكريا قال أنبأنا محمد بن معاوية الزيادي عن القحذمي عن عمه قال خرج حارثة بن بدر إلى سلم بن زياد بخراسان فأوصى رجلا من غدانة أن يتعاهد امرأته الشماء ويقوم بأمرها فكان الغداني يأتيها فيتحدث عندها ويطيل حتى أحبها وصبا بها فكتب إلى حارثة يخبره أنها فسدت عليه وتغيرت ويشير عليه بفراقها ويقول له إنها قد فضحتك من تلعب الرجال بها فكتب إليها بطلاقها وكتب في آخر كتابه\n(ألا آذنا شماء بالبين إنه ... أبى أود الشماء أن يتقوما)\nال فلما طلقها وقضت عدتها خطبها الغداني فتزوجها وكان حارثة شديد الحب لها وبلغه ذلك وما صنعت فقال 0ل - عمرك ما فارقت شماء عن قلى ... ولكن أطلت النأي عنها فملت مقيما بمروروذ لا أنا قافل ... إليها ولا تدنو إذا هي حلت","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":10,"spl":"طلق زوجته ثم ندم على ذلك","loc":1591},
{"id":"b86-18","bab":"الجزء 8","sec":"رثاء زوجته له","page":"ج8 ص421","text":"أخبرني محمد بن يحيى قال أنبأنا محمد بن زكريا قال أنبأنا\nمهدي بن سابق قال أنبأنا عطاء عن عاصم بن الحدثان قال تزوج حارثة بن بدر ميسة بنت جابر وكانت تذكر بجمال وعقل ولسان فلما هلك حارثة تزوجها بشر بن شعاف بعده فلم تحمده فقالت ترثي حارثة\n(بدلت بشرا شقاء أو معاقبة ... من فارس كان قدما غير خوار)\n(يا ليتني قبل بشر كان عاجلني ... داع من الله أو داع من النار)\nقالت أيضا فيه\n(ما خار لي ذو العرش لما استخرته ... وعذبني أن صرت لابن شعاف)\n(فما كان لي بعلا وما كان مثله ... يكون حليفا أو ينال إلافي)\n(فيا رب قد أوقعتني في بلية ... فكن لي حصنا منه رب وكاف)\n(ونح إلهي ربقتي من يد امرىء ... شتيم محياه لكل مصافي)\n(هو السوأة السوآء لا خير عنده ... لطالب خير أو أحذ قوافي)\n(يرى أكلة إن نلتها قلع ضرسه ... وما تلك زلفى يال عبد مناف)\n(وإن حادث عض الشعافي لم يكن ... صليبا ولا ذا تدرأ وقذاف)\nخبرني محمد بن مزيد قال أنبأنا حماد بن إسحاق عن أبيه عن عاصم بن الحدثان قال لقي أنس بن زنيم الدئلي حارثة بن بدر فقال له يا حارثة قد قلت لك أبياتا فاسمعها فقال هاتها فأنشده\n(فحتى متى أنت ابن بدر مخيم ... وصحبك يحسون الحليب من الكرم)\n(فإن كان شرا فاله عنه وخله ... لغيرك من أهل التخبط والظلم)\n(وإن كان غنما يابن بدر فقد أرى ... سئمت من الإكثار من ذلك الغنم)\n(وإن كنت ذا علم بها واحتسائها ... فما لك تأتي ما يشينك عن علم)\n(تق الله واقبل يابن بدر نصيحتي ... ودعها لمن أمسى بعيدا من الحزم)\n(فلو أنها كانت شرابا محللا ... وقلت لي اتركها لأوضعت في الحكم)\n(وأيقنت أن القول ما قلت فانتفع ... بقولي ولا تجعل كلامي من الجرم)\n(فرب نصيح الجيب رد انتصاحه ... عليه بلا ذنب وعوجل بالشتم)\nقال له حارثة لقد قلت فأحسنت ونصحت فبالغت جزيت الخير أبا زنيم فلما رجع إلى منزله أتاه ندماؤه فذكر لهم ما قال ابن زنيم فقالوا والله ما نرى ذلك إلا حسدا ثم قال حارثة بن بدر لابن زنيم\n(يعيب علي الراح من لو يذوقها ... لجن بها حتى يغيب في القبر)\n(فدعها أو امدحها فإنا نحبها ... صراحا كما أغراك ربك بالهجر)\n(علام تذم الراح والراح كاسمها ... تريح الفتى من همه آخر الدهر)\n(فلمني فإن اللوم فيها يزيدني ... غراما بها إن الملامة قد تغري)\n(وبالله أولي صادقا لو شربتها ... لأقصرت عن عذلي وملت إلى عذري)\n(وإن شئت جربها وذقها عتيقة ... لها أرج كالمسك محمودة الخبر)\n(فإن أنت لم تخلع عذارك فالحني ... وقل لي لحاك الله من عاجز غمر)\n(وقبلك ما قد لامني في اصطباحها ... وفي شربها بدر فأعرضت عن بدر)\n(وحاسيتها قوما كأن وجوههم ... دنانير في اللأواء والزمن النكر)\n(فدعني من التعذل فيها فإنني ... خلقت أبيا لا ألين على القسر)\n(أجود وأعطي المنفسات تبرعا ... وأغلي بها عند اليسارة والعسر)\n(وأشربها حتى أخر مجدلا ... معتقة صهباء طيبة النشر)\n(ولولا النهى لم أصح ما عشت ساعة ... ولكنني نهنهت نفسي عن الهجر)\n(فقصرت عنها بعد طول لجاجة ... وحب لها في سر أمري وفي الجهر)\n(وحق لمثلي أن يكف عن الخنى ... ويقصر عن بعض الغواية والنكر)\nخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبيدة أن عبيد الله بن زياد استعمل حارثة بن بدر على نيسابور فغاب عنه أشهرا ثم قدم فدخل عليه فقال له ما جاء بك ولم أكتب إليك قال استنظفت خراجك وجئت به وليس لي بها عمل فما مقامي قال أوبذلك أمرتك ارجع فاردد عليهم الخراج وخذه منهم نجوما حتى تنقضي السنة وقد فرغت من ذلك فإنه أرفق بالرعية وبك واحذر أن تحملهم على بيع غلاتهم ومواشيهم ولا التعنيف عليهم فرجع فرد الخراج عليهم وأقام يستخرجه منهم نجوما حتى مضت السنة أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي عن الأصمعي قال قال الأحنف بن قيس ما غبت عن أمر قط فحضره حارثة بن بدر إلا","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":11,"spl":"رثاء زوجته له","loc":1592},
{"id":"b86-20","bab":"الجزء 8","sec":"رثاء زوجته له — ماذا قال في يوم دولاب","page":"ج8 ص421 – ج8 ص425","text":"وثقت بإحكامه إياه وجودة عقده له وكان حارثة بن بدر من الدهاة أخبرني علي بن سليمان الأخفش قال حدثنا أحمد بن يحيى عن ابن الأعرابي قال كان حارثة بن بدر يصيب من الشراب وكان حظيا عند زياد فعوتب زياد على رأيه فيه فقال أتلومونني على حارثة فوالله ما تفل في مجلسي قط ولا حك ركابه ركابي ولا سار معي في علاوة الريح فغبر علي ولا دعوته قط فاحتجت إلى تجشم الالتفات إليه حتى يوازيني ولا شاورته في شيء إلا نصحني ولا سألته عن شيء من أمر العرب وأخبارها إلا وجدته به بصيرا\nأخبرني أحمد بن عبد العزيز الجوهري وأحمد بن عبيد الله بن عمار قالا حدثنا عمر بن شبة قال حدثنا الأصمعي قال لما كان يوم دولاب وأفضت الحرب إلى حارثة بن بدر صاح من جاءنا من الموالي فله فريضة العرب ومن جاءنا من الأعراب فله فريضة المهاجر فلما رأى ما يلقى أصحابه من الأزارقة قال\n(أير الحمار فريضة لشبابكم ... والخصيتان فريضة الأعراب)\n(عض الموالي جلد أير أبيهم ... إن الموالي معشر الخياب)\nم قال\n(كرنبوا ودولبوا وشرقوا وغربوا ... )\n(وحيث شئتم فاذهبوا ... )\nيعني بقوله كرنبوا أي خذوا طريق كرنبى ودولبوا خذوا طريق دولاب أخبرني محمد بن زكريا الصحاف قال حدثنا قعنب بن محرز قال حدثنا الهيثم بن عدي عن ابن عياش عن المغيرة بن المنتشر قال إنا عند عبيد الله بن زياد وعنده الأحنف بن قيس وحارثة بن بدر وكان حارثة يتهم بالشراب فقال له عبيد الله يا حارثة أي الشراب أطيب قال برة طبرية بأقطة عنزية بسمنة عربية بسكرة سوسية فتبسم عبيد الله ثم قال للأحنف يا أبا بحر أي الشراب أطيب قال الخمر فقال له عبيد الله وما يدريك ولست من أهلها قال من يستحلها لا يعدوها إلى غيرها ومن يحرمها يتأول فيها حتى يشربها قال فضحك عبيد الله أخبرني أحمد بن محمد أبو الحسن الأسدي وعمرو بن عبد الله العتكي قالا حدثنا الرياشي وقال العتكي في خبره عن أبي عبيدة ولم يقله الأسدي ولا تجاوز الرياشي به إن حارثة كان بكوار من أردشير خره يتنزه فقال\n(ألم تر أن حارثة بن بدر ... أقام بدير أبلق من كوارا)\nم قال لجند كانوا معه من أجاز هذا البيت فله حكمه فقال له رجل\nمنهم أنا أجيزه على أن تجعل لي الأمان من غضبك وتجعلني رسولك إلى البصرة وتطلب لي القفل من الأمير قال ذلك لك قال ثم رد عليه نشيد البيت فقال الرجل\n(مقيما يشرب الصهباء صرفا ... إذا ما قلت تصرعه استدارا)\nقال له حارثة لك شرطك ولو كنت قلت لنا شيئا يسرنا لسررناك","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":12,"spl":"رثاء زوجته له — ماذا قال في يوم دولاب — هجوه الأبيرد الرياحي","loc":1593,"partialRef":{"sid":"b60-8","gi":1,"vi":0,"side":1},"partial":1},
{"id":"b86-21","bab":"الجزء 8","sec":"هجوه الأبيرد الرياحي","page":"ج8 ص427","text":"كتب إلي ابو خليفة الفضل بن الحباب أخبرنا محمد بن سلام قال قدم الأبيرد الرياحي على حارثة بن بدر فقال له اكسني ثوبين أدخل بهما على الأمير فكساه ثوبين لم يرضهما فقال فيه\n(أحارث أمسك فضل برديك إنما ... أجاع وأعرى الله من كنت كاسيا)\n(وكنت إذا استمطرت منك سحابة ... لتمطرني عادت عجاجا وسافيا)\n(أحارث عاود شربك الخمر إنني ... رأيت زيادا عنك أصبح لاهيا)\nبلغت زيادا وبلغت حارثة فقال قبحه الله لقد شهد علي بما لم يعلم ولم أدع جوابه إلا لما يعلم أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن عاصم بن الحدثان قال كان الحكم بن المنذر بن الجارود يشرب الشراب فقيل له في ذلك وعوتب وعرف أن الصلتان العبدي هجاه فقال فيه\n(ترك الأشياء طرا وانحنى ... يضرب الصهباء من ماء العنب)\n(لا يخاف الناس قد أذمنها ... وهي ترزي باللئيم المؤتشب)\n(وهي بالأشراف أزرى وإلى ... غاية التأنيب تدعو ذا الحسب)\n(فدع الخمر أبا حرب وسد ... قومك الأذنين من بين العرب)\nقال لعنه الله والله ما ترك للصلح موضعا ولقد صدق ولولا الشرب لكنت الرجل الكامل وما يخفى علي قبيحه وسوء القالة فيه ولكني سمعت حارثة بن بدر الغداني أنشد ابيات يوما فحملتني على المجاهرة بالشراب وغن كان ذلي إلي بغيضا قيل له وما الأبيات قال سمعته ينشد\n(أذهب عني الغم والذي ... به تطرد الأحداث شرب المروق)\n- فواللله ما أنفك بالراح مهترا ... ولو لام فيها كل خحر موفق فما لائمي فيها وإن كان ناصحا ... بأعلم مني بالرحيق المعتق ولكن قلبي مستهام بحبها ... وحب القيان رأي كل محمق أحب التي لا أملك الدهر بغضها ... وذلك فعل معجب كل أخر\nأشربها صرفا وأسقي صحابتي ... وأطلب غرات الغزال المنطق","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":12,"spl":"رثاء زوجته له — ماذا قال في يوم دولاب — هجوه الأبيرد الرياحي","loc":1594},
{"id":"b86-22","bab":"الجزء 8","sec":"شعره في نديم له","page":"ج8 ص428","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن عاصم بن الحدثان قال كان لحارثة بن بدر نديم من قريش يصيب معه الشراب ولا يفارقه إذا شرب وقال فيه\n(وأبيض من أولاد سعد بن مالك ... سقيت من الصهباء حتى تقطرا)\n(وحتى رأى الشخص القريب بسكره ... شخوصا فنادى يال سعد وكبرا)\n(فقلت أسكران فقال مكابرا ... أبى الله لي أن أستخف وأسكرا)\n(فقلت له اشرب هذه بابلية ... تخال بها مسكا ذكيا وعنبرا)\n(فلما حساها هرها ثم إنه ... تماسك شيئا واجما متفكرا)\n(وقال أعدها قلت صبرا سويعة ... فهوم شيئا ثم قام فبربرا)\n(فقلت له نم ساعة عل ما أرى ... من السكر يبدي منك صرما مذكرا)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":13,"spl":"شعره في نديم له — خبره مع أبي صخر مخارق حين عاتبه على شربه الخمر","loc":1595},
{"id":"b86-23","bab":"الجزء 8","sec":"خبره مع أبي صخر مخارق حين عاتبه على شربه الخمر","page":"ج8 ص429","text":"قال إسحاق قال عاصم بن الحدثان\nكان أبو صخر مخارق بن صخر أحد بني ربيعة بن مالك شاعرا وهو خال أبي حزانة أو خال أبي جميعة وكان صديقا لحارثة بن بدر فدخل عليه يوما وهو مصطبح فعاتبه حارثة بن بدر وقال له قد أسقطت الخمر قدرك\nومروءتك قال له دع عنك هذا الجنون وهلم نتساعد واسمع ما قلت قال هاته فأنشده\n(غدا ناصحا لم يأل جهدا مخارق ... يلوم على شرب السلاف المعتق)\n(فقلت ابا صخر دع الناس يجهلوا ... ودونكها صهباء ذات تألق)\n(تراها إذا ما الماء خالط جسمها ... تخايل في كف الوصيف المنطق)\n(لها أرج كالمسك تذهب ريحها ... عماية حاسيها بحسن ترفق)\n(وكم لائم فيها بصير بفضلها ... رمته بسهم صائب متزلق)\n(فظل لرياها يعض ندامة ... يديه وأرغى بعد طول تمطق)\n(وقال لك العذر ابن بدر على التي ... تسلي هموم المستهام المشوق)\n(فلست ابن صخر تاركا شرب قهوة ... لقول لئيم جاهل متحذلق)\n(يعيب علي الشرب والشرب همه ... ليحسب ذا رأي أصيل مصدق)\n(فما أنا بالغر ابن صخر ولا الذي ... يصمم في شيء من الأمر موبق)\nقال له مخارق بن صخر إنما عاتبتك لأن الناس قد كثروا فيك ورأيت النصيحة لله واجبة علي وكرهت أن تضع لذتك قدرك فإن أطعتني في تركها وإلا فلا تجاهر بها فإنك قادر على أن تبلغ حاجتك في ستر فقال حارثة ما عندي غير ما سمعت فتركه وانصرف أخبرني هاشم بن محمد الخزاعي قال أنبأنا الرياشي عن محمد بن\nسلام عن يونس بن حبيب قال لما بنى فيل مولى زياد داره بالسبابجة صنع طعاما ودعا أصحاب زياد فدخلوا الحمام المعروف بحمام فيل وخرجوا فتغدوا عنده وركب فيل وأصحابه الهماليج والمقاريف والبغال واجتاز بهم معه على حارثة بن بدر وأبي الأسود الدؤلي وهما جالسان فقال أبو الأسود\n(لعمر أبيك ما حمام كسرى ... على الثلثين من حمام فيل)\nقال له حارثة\n(وما إيجافنا خلف الموالي ... بسنتنا على عهد الرسول)\nخبرني محمد بن مزيد قال أنبأنا حماد عن أبيه عن عاصم بن الحدثان قال حدثني عمي عن الحارث الهجيمي قال ذكر حلم الأحنف بن قيس عند عبيد الله بن زياد وعنده حارثة بن بدر فنفس عليه حارثة ذلك فقال لعبيد الله أيها الأمير ما يبلغ حلم من لا قدرة له ولا يملك لعدوه ضرا ولا لصديقه نفعا وإنما يتكلف الدخول فيما لا يعنيه فبلغ ذلك من قوله الأحنف فقال أهون بحارثة وكلامه وما حارثة ومقداره أليس الذي يقول قبح الله رأيه في قوله\n(إذا ما شربت الراح أبدت مكارمي ... وجدت بما حازت يداي من الوفر)\n(وإن سبني جهلا نديمي لم أزد ... على اشرب سقاك الله طيبة النشر)\nرى ذاك حقا واجبا لمنادمي ... إذا قال لي غير الجميل من النكر","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":13,"spl":"شعره في نديم له — خبره مع أبي صخر مخارق حين عاتبه على شربه الخمر","loc":1596},
{"id":"b86-24","bab":"الجزء 8","sec":"شعره في جاريته ميسته","page":"ج8 ص432","text":"أخبرني عمي قال أنبأنا الكراني قال أنبأنا الرياشي عن الأصمعي قال كان لحارثة بن بدر جارية يقال لها ميسة وكان بها مشغوفا فلما مات تزوجت بعده بشر بن شغاف فهؤلاء الشغافيون من ولدها وفيها يقول حارثة\n(خليلي لولا حب ميسة لم أبل ... أفي اليوم لاقيت المنية أم غدا)\n(خليلي إن أفشيت سري إليكما ... فلا تجعلا سري حديثا مبددا)\n(وإن أنتما أفشيتماه فلا رأت عيونكما يوم الحساب محمدا ... )\n(ولا زلتما في شقوة ما بقيتما ... تذوقان عيشا سيىء الحال أنكدا)\nأخبرني حبيب بن نصر المهلبي قال أنبأنا الحسين بن عليل قال أنبأنا مسعود بن بشر عن أبي عبيدة قال اجتاز حارثة بن بدر الغداني بمجلس من مجالس قومه من بني تميم ومعه كعب مولاه فكلما اجتاز بقوم قاموا إليه وقالوا مرحبا بسيدنا فلما ولى قال له كعب ما سمعت كلاما قط أقر لعيني ولا ألذ بسمعي من هذا الكلام الذي سمعته اليوم فقال له حارثة لكني لم أسمع كلاما قط أكره لنفسي وأبغض إلي مما سمعته قال ولم قال ويحك يا كعب إنما سودني قومي حين ذهب خيارهم وأماثلهم فاحفظ عني هذا البيت\n(خلت الديار فسدت غير مسود ... ومن الشقاء تفردي بالسودد)","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":14,"spl":"شعره في جاريته ميسته — وصيته قبل وفاته","loc":1597,"partial":1},
{"id":"b86-25","bab":"الجزء 8","sec":"وصيته قبل وفاته","page":"ج8 ص433","text":"قال واشتكى حارثة بن بدر وأشرف على الموت فجعل قومه يعودونه فقالوا له هل لك من حاجة أو شيء تريده قال نعم اكسروا رجل مولاي كعب لئلا يبرح من عندي فإنه يؤنسني ففعلوا وأنشأ يقول\n(يا كعب مهلا فلا تجزع على أحد ... يا كعب لم يبق منا غير أجساد)\n(يا كعب ما راح من قوم ولا بكروا ... إلا وللموت في آثارهم حادي)\n(يا كعب ما طلعت شمس ولا غربت ... إلا تقرب آجالا لميعاد)\n(يا كعب كم من حمى قوم نزلت به ... على صواعق من زجر وإيعاد)\n(فإن لقيت بواد حية ذكرا ... فاذهب ودعني أمارس حية الوادي)\nاء بعقب هذه الترجمة في الجزء الحادي والعشرين\n(عش فحبيك سريعا قاتلي ... والضنى إن لم تصلني واصلي)\n(ظفر الشوق بقلب دنف ... فيك والسقم بجسم ناحل)\n(فهما بين اكتئاب وضنى ... تركاني كالقضيب الذابل)\nلشعر لخالد الكاتب والغناء للمسدود رمل مطلق في مجرى الوسطى وذكر جحظة أن هذا الرمل أخذ عنه وأنه أول صوت سمعه فكتبه ثم جاءت بعد هذا أخبار خالد الكاتب","topic":"نسب حارثة بن بدر وأخباره","topicNo":86,"sp":14,"spl":"شعره في جاريته ميسته — وصيته قبل وفاته","song":1,"loc":1598}]);